import type { PaperInput } from "@/lib/schema";

const asOf = "2026-09-24";
type P = Omit<PaperInput, "kind" | "asOf">;
const p = (x: P): PaperInput => ({ kind: "paper", asOf, ...x });

/**
 * Wave 1 of docs/CONTENT-ROADMAP.md: the papers behind trials that had none. Written by scripts/fetch-trial-papers.ts,
 * which asks Europe PMC for PubMed records whose title or abstract cites the trial's NCT id and keeps the most cited
 * eligible paper (plus one later report when its title says it is an update). Title, journal, year, DOI, PMID and
 * authors are read from the Europe PMC record; the summary reproduces the record's abstract with markup removed
 * and house-style dashes; the TL;DR, "what it means" and caveats say only how the record was matched. Nothing here
 * has been read by an editor: findings are left empty on purpose. Trials link to these records through
 * src/data/trial-key-papers-wave1.ts. Do not edit by hand; re-run the script.
 */
export const papersTrialsWave1: PaperInput[] = [
  p({ id: "paper-aeneas-j-clin-oncol-2022", name: "AENEAS: A Randomized Phase III Trial of Aumolertinib Versus Gefitinib as First-Line Therapy for Locally Advanced or MetastaticNon-Small-Cell Lung Cancer With EGFR Exon 19 Deletion or L858R Mutations", tldr: "Published report from the AENEAS trial registered as NCT03849768, in Journal of Clinical Oncology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Aumolertinib (formerly almonertinib; HS-10296) is a novel third-generation epidermal growth factor receptor tyrosine kinase inhibitor approved in China. This double-blind phase III trial evaluated the efficacy and safety of aumolertinib compared with gefitinib as a first-line treatment for locally advanced or metastatic EGFR -mutated non-small-cell lung cancer (NSCLC; ClinicalTrials.gov identifier: NCT03849768).\n\nMethods: Patients at 53 sites in China were randomly assigned 1:1 to receive either aumolertinib (110 mg) or gefitinib (250 mg) once daily. The primary end point was progression-free survival (PFS) per investigator assessment.\n\nResults: A total of 429 patients who were naïve to treatment for locally advanced or metastatic NSCLC were enrolled. PFS was significantly longer with aumolertinib compared with gefitinib (hazard ratio, 0.46; 95% CI, 0.36 to 0.60; P <.0001). The median PFS with aumolertinib was 19.3 months (95% CI, 17.8 to 20.8) versus 9.9 months with gefitinib (95% CI, 8.3 to 12.6). Objective response rate and disease control rate were similar in the aumolertinib and gefitinib groups (objective response rate, 73.8% and 72.1%, respectively; disease control rate, 93.0% and 96.7%, respectively). The median duration of response was 18.1 months (95% CI, 15.2 to not applicable) with aumolertinib versus 8.3 months (95% CI, 6.9 to 11.1) with gefitinib. Adverse events of grade ≥ 3 severity (any cause) were observed in 36.4% and 35.8% of patients in the aumolertinib and gefitinib groups, respectively. Rash and diarrhea (any grade) were observed in 23.4% and 16.4% of patients who received aumolertinib compared with 41.4% and 35.8% of those who received gefitinib, respectively.\n\nConclusion: Aumolertinib is a well-tolerated third-generation epidermal growth factor receptor tyrosine kinase inhibitor that could serve as a treatment option for EGFR -mutant NSCLC in the first-line setting.\n\nIndexed on Europe PMC as PubMed record 35580297 (DOI 10.1200/jco.21.02641). Its abstract cites the registry id NCT03849768, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2022, doi: "10.1200/jco.21.02641", pmid: "35580297", authors: "Lu S, Dong X, Jian H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03849768 with the most citations, so it is the natural first reading for anyone following the AENEAS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2022","url":"https://doi.org/10.1200/jco.21.02641"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35580297/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35580297"},{"label":"ClinicalTrials.gov NCT03849768","url":"https://clinicaltrials.gov/study/NCT03849768"}], tags: ["europepmc-ingest"], trials: ["aeneas"], journals: ["jco"] }),
  p({ id: "paper-alex-n-engl-j-med-2017", name: "Alectinib versus Crizotinib in Untreated ALK-Positive Non-Small-Cell Lung Cancer", tldr: "Published report from the ALEX trial registered as NCT02075840, in New England Journal of Medicine (2017), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Alectinib, a highly selective inhibitor of anaplastic lymphoma kinase (ALK), has shown systemic and central nervous system (CNS) efficacy in the treatment of ALK-positive non-small-cell lung cancer (NSCLC). We investigated alectinib as compared with crizotinib in patients with previously untreated, advanced ALK-positive NSCLC, including those with asymptomatic CNS disease.\n\nMethods: In a randomized, open-label, phase 3 trial, we randomly assigned 303 patients with previously untreated, advanced ALK-positive NSCLC to receive either alectinib (600 mg twice daily) or crizotinib (250 mg twice daily). The primary end point was investigator-assessed progression-free survival. Secondary end points were independent review committee-assessed progression-free survival, time to CNS progression, objective response rate, and overall survival.\n\nResults: During a median follow-up of 17.6 months (crizotinib) and 18.6 months (alectinib), an event of disease progression or death occurred in 62 of 152 patients (41%) in the alectinib group and 102 of 151 patients (68%) in the crizotinib group. The rate of investigator-assessed progression-free survival was significantly higher with alectinib than with crizotinib (12-month event-free survival rate, 68.4% [95% confidence interval (CI), 61.0 to 75.9] with alectinib vs. 48.7% [95% CI, 40.4 to 56.9] with crizotinib; hazard ratio for disease progression or death, 0.47 [95% CI, 0.34 to 0.65]; P<0.001); the median progression-free survival with alectinib was not reached. The results for independent review committee-assessed progression-free survival were consistent with those for the primary end point. A total of 18 patients (12%) in the alectinib group had an event of CNS progression, as compared with 68 patients (45%) in the crizotinib group (cause-specific hazard ratio, 0.16; 95% CI, 0.10 to 0.28; P<0.001). A response occurred in 126 patients in the alectinib group (response rate, 82.9%; 95% CI, 76.0 to 88.5) and in 114 patients in the crizotinib group (response rate, 75.5%; 95% CI, 67.8 to 82.1) (P=0.09). Grade 3 to 5 adverse events were less frequent with alectinib (41% vs. 50% with crizotinib).\n\nConclusions: As compared with crizotinib, alectinib showed superior efficacy and lower toxicity in primary treatment of ALK-positive NSCLC. (Funded by F. Hoffmann-La Roche; ALEX ClinicalTrials.gov number, NCT02075840.).\n\nIndexed on Europe PMC as PubMed record 28586279 (DOI 10.1056/nejmoa1704795). Its abstract cites the registry id NCT02075840, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2017, doi: "10.1056/nejmoa1704795", pmid: "28586279", authors: "Peters S, Camidge DR, Shaw AT, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02075840 with the most citations, so it is the natural first reading for anyone following the ALEX trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2017","url":"https://doi.org/10.1056/nejmoa1704795"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28586279/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28586279"},{"label":"ClinicalTrials.gov NCT02075840","url":"https://clinicaltrials.gov/study/NCT02075840"}], tags: ["europepmc-ingest"], trials: ["alex"], journals: ["nejm"] }),
  p({ id: "paper-alex-ann-oncol-2020-update", name: "Updated overall survival and final progression-free survival data for patients with treatment-naive advanced ALK-positive non-small-cell lung cancer in the ALEX study", tldr: "Later report from the ALEX trial registered as NCT02075840, in Annals of Oncology (2020); its title describes an updated or longer-term analysis.", summary: "Background: The ALEX study demonstrated significantly improved progression-free survival (PFS) with alectinib versus crizotinib in treatment-naive ALK-positive non-small-cell lung cancer (NSCLC) at the primary data cut-off (9 February 2017). We report mature PFS (cut-off: 30 November 2018) and overall survival (OS) data up to 5 years (cut-off: 29 November 2019).\n\nPatients and methods: Patients with stage III/IV ALK-positive NSCLC were randomized to receive twice-daily alectinib 600 mg (n = 152) or crizotinib 250 mg (n = 151) until disease progression, toxicity, withdrawal or death. Primary end point: investigator-assessed PFS. Secondary end points included objective response rate, OS and safety.\n\nResults: Mature PFS data showed significantly prolonged investigator-assessed PFS with alectinib [hazard ratio (HR) 0.43, 95% confidence interval (CI) 0.32-0.58; median PFS 34.8 versus 10.9 months crizotinib]. Median duration of OS follow-up: 48.2 months alectinib, 23.3 months crizotinib. OS data remain immature (37% of events). Median OS was not reached with alectinib versus 57.4 months with crizotinib (stratified HR 0.67, 95% CI 0.46-0.98). The 5-year OS rate was 62.5% (95% CI 54.3-70.8) with alectinib and 45.5% (95% CI 33.6-57.4) with crizotinib, with 34.9% and 8.6% of patients still on study treatment, respectively. The OS benefit of alectinib was seen in patients with central nervous system metastases at baseline [HR 0.58 (95% CI 0.34-1.00)] and those without [HR 0.76 (95% CI 0.45-1.26)]. Median treatment duration was longer with alectinib (28.1 versus 10.8 months), and no new safety signals were observed.\n\nConclusions: Mature PFS data from ALEX confirmed significant improvement in PFS for alectinib over crizotinib in ALK-positive NSCLC. OS data remain immature, with a higher 5-year OS rate with alectinib versus crizotinib. This is the first global randomized study to show clinically meaningful improvement in OS for a next-generation tyrosine kinase inhibitor versus crizotinib in treatment-naive ALK-positive NSCLC.\n\nClinical trials number: NCT02075840.\n\nIndexed on Europe PMC as PubMed record 32418886 (DOI 10.1016/j.annonc.2020.04.478). Its abstract cites the registry id NCT02075840, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2020, doi: "10.1016/j.annonc.2020.04.478", pmid: "32418886", authors: "Mok T, Camidge DR, Gadgeel SM, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the ALEX trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2020","url":"https://doi.org/10.1016/j.annonc.2020.04.478"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32418886/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32418886"},{"label":"ClinicalTrials.gov NCT02075840","url":"https://clinicaltrials.gov/study/NCT02075840"}], tags: ["europepmc-ingest"], trials: ["alex"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-alina-n-engl-j-med-2024", name: "Alectinib in Resected ALK -Positive Non-Small-Cell Lung Cancer", tldr: "Published report from the ALINA trial registered as NCT03456076, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Platinum-based chemotherapy is the recommended adjuvant treatment for patients with resectable, ALK -positive non-small-cell lung cancer (NSCLC). Data on the efficacy and safety of adjuvant alectinib as compared with chemotherapy in patients with resected ALK -positive NSCLC are lacking.\n\nMethods: We conducted a global, phase 3, open-label, randomized trial in which patients with completely resected, ALK -positive NSCLC of stage IB (tumors ≥4 cm), II, or IIIA (as classified according to the seventh edition of the Cancer Staging Manual of the American Joint Committee on Cancer and Union for International Cancer Control) were randomly assigned in a 1:1 ratio to receive oral alectinib (600 mg twice daily) for 24 months or intravenous platinum-based chemotherapy in four 21-day cycles. The primary end point was disease-free survival, tested hierarchically among patients with stage II or IIIA disease and then in the intention-to-treat population. Other end points included central nervous system (CNS) disease-free survival, overall survival, and safety.\n\nResults: In total, 257 patients were randomly assigned to receive alectinib (130 patients) or chemotherapy (127 patients). The percentage of patients alive and disease-free at 2 years was 93.8% in the alectinib group and 63.0% in the chemotherapy group among patients with stage II or IIIA disease (hazard ratio for disease recurrence or death, 0.24; 95% confidence interval [CI], 0.13 to 0.45; P<0.001) and 93.6% and 63.7%, respectively, in the intention-to-treat population (hazard ratio, 0.24; 95% CI, 0.13 to 0.43; P<0.001). Alectinib was associated with a clinically meaningful benefit with respect to CNS disease-free survival as compared with chemotherapy (hazard ratio for CNS disease recurrence or death, 0.22; 95% CI, 0.08 to 0.58). Data for overall survival were immature. No unexpected safety findings were observed.\n\nConclusions: Among patients with resected ALK -positive NSCLC of stage IB, II, or IIIA, adjuvant alectinib significantly improved disease-free survival as compared with platinum-based chemotherapy. (Funded by F. Hoffmann-La Roche; ALINA ClinicalTrials.gov number, NCT03456076.).\n\nIndexed on Europe PMC as PubMed record 38598794 (DOI 10.1056/nejmoa2310532). Its abstract cites the registry id NCT03456076, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2310532", pmid: "38598794", authors: "Wu YL, Dziadziuszko R, Ahn JS, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03456076 with the most citations, so it is the natural first reading for anyone following the ALINA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2310532"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38598794/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38598794"},{"label":"ClinicalTrials.gov NCT03456076","url":"https://clinicaltrials.gov/study/NCT03456076"}], tags: ["europepmc-ingest"], trials: ["alina"], journals: ["nejm"] }),
  p({ id: "paper-alta-1l-n-engl-j-med-2018", name: "Brigatinib versus Crizotinib in ALK-Positive Non-Small-Cell Lung Cancer", tldr: "Published report from the ALTA-1L trial registered as NCT02737501, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Brigatinib, a next-generation anaplastic lymphoma kinase (ALK) inhibitor, has robust efficacy in patients with ALK-positive non-small-cell lung cancer (NSCLC) that is refractory to crizotinib. The efficacy of brigatinib, as compared with crizotinib, in patients with advanced ALK-positive NSCLC who have not previously received an ALK inhibitor is unclear.\n\nMethods: In an open-label, phase 3 trial, we randomly assigned, in a 1:1 ratio, patients with advanced ALK-positive NSCLC who had not previously received ALK inhibitors to receive brigatinib at a dose of 180 mg once daily (with a 7-day lead-in period at 90 mg) or crizotinib at a dose of 250 mg twice daily. The primary end point was progression-free survival as assessed by blinded independent central review. Secondary end points included the objective response rate and intracranial response. The first interim analysis was planned when approximately 50% of 198 expected events of disease progression or death had occurred.\n\nResults: A total of 275 patients underwent randomization; 137 were assigned to brigatinib and 138 to crizotinib. At the first interim analysis (99 events), the median follow-up was 11.0 months in the brigatinib group and 9.3 months in the crizotinib group. The rate of progression-free survival was higher with brigatinib than with crizotinib (estimated 12-month progression-free survival, 67% [95% confidence interval {CI}, 56 to 75] vs. 43% [95% CI, 32 to 53]; hazard ratio for disease progression or death, 0.49 [95% CI, 0.33 to 0.74]; P<0.001 by the log-rank test). The confirmed objective response rate was 71% (95% CI, 62 to 78) with brigatinib and 60% (95% CI, 51 to 68) with crizotinib; the confirmed rate of intracranial response among patients with measurable lesions was 78% (95% CI, 52 to 94) and 29% (95% CI, 11 to 52), respectively. No new safety concerns were noted.\n\nConclusions: Among patients with ALK-positive NSCLC who had not previously received an ALK inhibitor, progression-free survival was significantly longer among patients who received brigatinib than among those who received crizotinib. (Funded by Ariad Pharmaceuticals; ALTA-1L ClinicalTrials.gov number, NCT02737501.).\n\nIndexed on Europe PMC as PubMed record 30280657 (DOI 10.1056/nejmoa1810171). Its abstract cites the registry id NCT02737501, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1810171", pmid: "30280657", authors: "Camidge DR, Kim HR, Ahn MJ, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02737501 with the most citations, so it is the natural first reading for anyone following the ALTA-1L trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1810171"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30280657/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30280657"},{"label":"ClinicalTrials.gov NCT02737501","url":"https://clinicaltrials.gov/study/NCT02737501"}], tags: ["europepmc-ingest"], trials: ["alta-1l"], journals: ["nejm"] }),
  p({ id: "paper-alter-0303-jama-oncol-2018", name: "Effect of Anlotinib as a Third-Line or Further Treatment on Overall Survival of Patients With Advanced Non-Small Cell Lung Cancer: The ALTER 0303 Phase 3 Randomized Clinical Trial", tldr: "Published report from the ALTER 0303 trial registered as NCT02388919, in JAMA Oncology (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Anlotinib is a novel multitarget tyrosine kinase inhibitor for tumor angiogenesis and proliferative signaling. A phase 2 trial showed anlotinib to improve progression-free survival with a potential benefit of overall survival, leading to the phase 3 trial to confirm the drug's efficacy in advanced non-small cell lung cancer (NSCLC).\n\nObjective: To investigate the efficacy of anlotinib on overall survival of patients with advanced NSCLC progressing after second-line or further treatment.\n\nDesign, setting, and participants: The ALTER 0303 trial was a multicenter, double-blind, phase 3 randomized clinical trial designed to evaluate the efficacy and safety of anlotinib in patients with advanced NSCLC. Patients from 31 grade-A tertiary hospitals in China were enrolled between March 1, 2015, and August 31, 2016. Those aged 18 to 75 years who had histologically or cytologically confirmed NSCLC were eligible (n = 606), and those who had centrally located squamous cell carcinoma with cavitary features or brain metastases that were uncontrolled or controlled for less than 2 months were excluded. Patients (n = 440) were randomly assigned in a 2-to-1 ratio to receive either 12 mg/d of anlotinib or a matched placebo. All cases were treated with study drugs at least once in accordance with the intention-to-treat principle.\n\nMain outcomes and measures: The primary end point was overall survival. The secondary end points were progression-free survival, objective response rate, disease control rate, quality of life, and safety.\n\nResults: In total, 439 patients were randomized, 296 to the anlotinib group (106 [36.1%] were female and 188 [64.0%] were male, with a mean [SD] age of 57.9 [9.1] years) and 143 to the placebo group (46 [32.2%] were female and 97 [67.8%] were male, with a mean [SD] age of 56.8 [9.1] years). Overall survival was significantly longer in the anlotinib group (median, 9.6 months; 95% CI, 8.2-10.6) than the placebo group (median, 6.3 months; 95% CI, 5.0-8.1), with a hazard ratio (HR) of 0.68 (95% CI, 0.54-0.87; P =.002). A substantial increase in progression-free survival was noted in the anlotinib group compared with the placebo group (median, 5.4 months [95% CI, 4.4-5.6] vs 1.4 months [95% CI, 1.1-1.5]; HR, 0.25 [95% CI, 0.19-0.31]; P <.001). Considerable improvement in objective response rate and disease control rate was observed in the anlotinib group over the placebo group. The most common grade 3 or higher adverse events in the anlotinib arm were hypertension and hyponatremia.\n\nConclusions and relevance: Among the Chinese patients in this trial, anlotinib appears to lead to prolonged overall survival and progression-free survival. This finding suggests that anlotinib is well tolerated and is a potential third-line or further therapy for patients with advanced NSCLC.\n\nTrial registration: ClinicalTrials.gov identifier: NCT02388919.\n\nIndexed on Europe PMC as PubMed record 30098152 (DOI 10.1001/jamaoncol.2018.3039). Its abstract cites the registry id NCT02388919, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2018, doi: "10.1001/jamaoncol.2018.3039", pmid: "30098152", authors: "Han B, Li K, Wang Q, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02388919 with the most citations, so it is the natural first reading for anyone following the ALTER 0303 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2018","url":"https://doi.org/10.1001/jamaoncol.2018.3039"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30098152/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30098152"},{"label":"ClinicalTrials.gov NCT02388919","url":"https://clinicaltrials.gov/study/NCT02388919"}], tags: ["europepmc-ingest"], trials: ["alter-0303"], journals: ["jama-oncology"] }),
  p({ id: "paper-astrum-005-jama-2022", name: "Effect of First-Line Serplulimab vs Placebo Added to Chemotherapy on Survival in Patients With Extensive-Stage Small Cell Lung Cancer: The ASTRUM-005 Randomized Clinical Trial", tldr: "Published report from the ASTRUM-005 trial registered as NCT04063163, in JAMA (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Programmed cell death ligand 1 inhibitors combined with chemotherapy has changed the approach to first-line treatment in patients with extensive-stage small cell lung cancer (SCLC). It remained unknown whether adding a programmed cell death 1 (PD-1) inhibitor to chemotherapy provided similar or better benefits in patients with extensive-stage SCLC, which would add evidence on the efficacy of checkpoint inhibitors in the treatment of extensive-stage SCLC.\n\nObjective: To evaluate the efficacy and adverse event profile of the PD-1 inhibitor serplulimab plus chemotherapy compared with placebo plus chemotherapy as first-line treatment in patients with extensive-stage SCLC.\n\nDesign, setting, and participants: This international, double-blind, phase 3 randomized clinical trial (ASTRUM-005) enrolled patients at 114 hospital sites in 6 countries between September 12, 2019, and April 27, 2021. Of 894 patients who were screened, 585 with extensive-stage SCLC who had not previously received systemic therapy were randomized. Patients were followed up through October 22, 2021.\n\nInterventions: Patients were randomized 2:1 to receive either 4.5 mg/kg of serplulimab (n = 389) or placebo (n = 196) intravenously every 3 weeks. All patients received intravenous carboplatin and etoposide every 3 weeks for up to 12 weeks.\n\nMain outcomes and measures: The primary outcome was overall survival (prespecified significance threshold at the interim analysis, 2-sided P <.012). There were 13 secondary outcomes, including progression-free survival and adverse events.\n\nResults: Among the 585 patients who were randomized (mean age, 61.1 [SD, 8.67] years; 104 [17.8%] women), 246 (42.1%) completed the trial and 465 (79.5%) discontinued study treatment. All patients received study treatment and were included in the primary analyses. at the data cutoff (October 22, 2021) for this interim analysis, the median duration of follow-up was 12.3 months (range, 0.2-24.8 months). The median overall survival was significantly longer in the serplulimab group (15.4 months [95% CI, 13.3 months-not evaluable]) than in the placebo group (10.9 months [95% CI, 10.0-14.3 months]) (hazard ratio, 0.63 [95% CI, 0.49-0.82]; P <.001). The median progression-free survival (assessed by an independent radiology review committee) also was longer in the serplulimab group (5.7 months [95% CI, 5.5-6.9 months]) than in the placebo group (4.3 months [95% CI, 4.2-4.5 months]) (hazard ratio, 0.48 [95% CI, 0.38-0.59]). Treatment-related adverse events that were grade 3 or higher occurred in 129 patients (33.2%) in the serplulimab group and in 54 patients (27.6%) in the placebo group.\n\nConclusions and relevance: Among patients with previously untreated extensive-stage SCLC, serplulimab plus chemotherapy significantly improved overall survival compared with chemotherapy alone, supporting the use of serplulimab plus chemotherapy as the first-line treatment for this patient population.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT04063163.\n\nIndexed on Europe PMC as PubMed record 36166026 (DOI 10.1001/jama.2022.16464). Its abstract cites the registry id NCT04063163, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2022, doi: "10.1001/jama.2022.16464", pmid: "36166026", authors: "Cheng Y, Han L, Wu L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04063163 with the most citations, so it is the natural first reading for anyone following the ASTRUM-005 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2022","url":"https://doi.org/10.1001/jama.2022.16464"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36166026/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36166026"},{"label":"ClinicalTrials.gov NCT04063163","url":"https://clinicaltrials.gov/study/NCT04063163"}], tags: ["europepmc-ingest"], trials: ["astrum-005"], journals: ["jama"] }),
  p({ id: "paper-atlantis-lancet-respir-med-2023", name: "Combination lurbinectedin and doxorubicin versus physician's choice of chemotherapy in patients with relapsed small-cell lung cancer (ATLANTIS): a multicentre, randomised, open-label, phase 3 trial", tldr: "Published report from the ATLANTIS trial registered as NCT02566993, in The Lancet. Respiratory medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Lurbinectedin is a synthetic marine-derived anticancer agent that acts as a selective inhibitor of oncogenic transcription. Lurbinectedin monotherapy (3·2 mg/m 2 every 3 weeks) received accelerated approval from the US Food and Drug Administration on the basis of efficacy in patients with small-cell lung cancer (SCLC) who relapsed after first-line platinum-based chemotherapy. The ATLANTIS trial assessed the efficacy and safety of combination lurbinectedin and the anthracycline doxorubicin as second-line treatment for SCLC.\n\nMethods: In this phase 3, open-label, randomised study, adult patients aged 18 years or older with SCLC who relapsed after platinum-based chemotherapy were recruited from 135 hospitals across North America, South America, Europe, and the Middle East. Patients were randomly assigned (1:1) centrally by dynamic allocation to intravenous lurbinectedin 2·0 mg/m 2 plus doxorubicin 40·0 mg/m 2 administered on day 1 of 21-day cycles or physician's choice of control therapy (intravenous topotecan 1·5 mg/m 2 on days 1-5 of 21-day cycles; or intravenous cyclophosphamide 1000 mg/m 2, doxorubicin 45·0 mg/m 2, and vincristine 2·0 mg on day 1 of 21-day cycles [CAV]) administered until disease progression or unacceptable toxicity. Primary granulocyte-colony stimulating factor prophylaxis was mandatory in both treatment groups. Neither patients nor clinicians were masked to treatment allocation, but the independent review committee, which assessed outcomes, was masked to patients' treatment allocation. The primary endpoint was overall survival in the intention-to-treat population. This trial is registered with ClinicalTrials.gov, NCT02566993, and with EudraCT, 2015-001641-89, and is complete.\n\nFindings: Between Aug 30, 2016, and Aug 20, 2018, 613 patients were randomly assigned to lurbinectedin plus doxorubicin (n=307) or control (topotecan, n=127; CAV, n=179) and comprised the intention-to-treat population; safety endpoints were assessed in patients who had received any partial or complete study treatment infusions (lurbinectedin plus doxorubicin, n=303; control, n=289). After a median follow-up of 24·1 months (95% CI 21·7-26·3), 303 patients in the lurbinectedin plus doxorubicin group and 289 patients in the control group had discontinued study treatment; progressive disease was the most common reason for discontinuation (213 [70%] patients in the lurbinectedin plus doxorubicin group vs 152 [53%] in the control group). Median overall survival was 8·6 months (95% CI 7·1-9·4) in the lurbinectedin plus doxorubicin group versus 7·6 months (6·6-8·2) in the control group (stratified log-rank p=0·90; hazard ratio 0·97 [95% CI 0·82-1·15], p=0·70). 12 patients died because of treatment-related adverse events: two (<1%) of 303 in the lurbinectedin plus doxorubicin group and ten (3%) of 289 in the control group. 296 (98%) of 303 patients in the lurbinectedin plus doxorubicin group had treatment-emergent adverse events compared with 284 (98%) of 289 patients in the control group; treatment-related adverse events occurred in 268 (88%) patients in the lurbinectedin plus doxorubicin group and 266 (92%) patients in the control group. Grade 3 or worse haematological adverse events were less frequent in the lurbinectedin plus doxorubicin group than the control group (anaemia, 57 [19%] of 302 patients in the lurbinectedin plus doxorubicin group vs 110 [38%] of 288 in the control group; neutropenia, 112 [37%] vs 200 [69%]; thrombocytopenia, 42 [14%] vs 90 [31%]). The frequency of treatment-related adverse events leading to treatment discontinuation was lower in the lurbinectedin plus doxorubicin group than in the control group (26 [9%] of 303 patients in the lurbinectedin plus doxorubicin group vs 47 [16%] of 289 in the control group).\n\nInterpretation: Combination therapy with lurbinectedin plus doxorubicin did not improve overall survival versus control in patients with relapsed SCLC. However, lurbinectedin plus doxorubicin showed a favourable haematological safety profile compared with control.\n\nFunding: PharmaMar.\n\nIndexed on Europe PMC as PubMed record 36252599 (DOI 10.1016/s2213-2600(22)00309-5). Its abstract cites the registry id NCT02566993, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2023, doi: "10.1016/s2213-2600(22)00309-5", pmid: "36252599", authors: "Aix SP, Ciuleanu TE, Navarro A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02566993 with the most citations, so it is the natural first reading for anyone following the ATLANTIS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2023","url":"https://doi.org/10.1016/s2213-2600(22)00309-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36252599/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36252599"},{"label":"ClinicalTrials.gov NCT02566993","url":"https://clinicaltrials.gov/study/NCT02566993"}], tags: ["europepmc-ingest"], trials: ["atlantis"] }),
  p({ id: "paper-calgb-140503-n-engl-j-med-2023", name: "Lobar or Sublobar Resection for Peripheral Stage IA Non-Small-Cell Lung Cancer", tldr: "Published report from the CALGB 140503 trial registered as NCT00499330, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The increased detection of small-sized peripheral non-small-cell lung cancer (NSCLC) has renewed interest in sublobar resection in lieu of lobectomy.\n\nMethods: We conducted a multicenter, noninferiority, phase 3 trial in which patients with NSCLC clinically staged as T1aN0 (tumor size, ≤2 cm) were randomly assigned to undergo sublobar resection or lobar resection after intraoperative confirmation of node-negative disease. The primary end point was disease-free survival, defined as the time between randomization and disease recurrence or death from any cause. Secondary end points were overall survival, locoregional and systemic recurrence, and pulmonary functions.\n\nResults: From June 2007 through March 2017, a total of 697 patients were assigned to undergo sublobar resection (340 patients) or lobar resection (357 patients). After a median follow-up of 7 years, sublobar resection was noninferior to lobar resection for disease-free survival (hazard ratio for disease recurrence or death, 1.01; 90% confidence interval [CI], 0.83 to 1.24). In addition, overall survival after sublobar resection was similar to that after lobar resection (hazard ratio for death, 0.95; 95% CI, 0.72 to 1.26). The 5-year disease-free survival was 63.6% (95% CI, 57.9 to 68.8) after sublobar resection and 64.1% (95% CI, 58.5 to 69.0) after lobar resection. The 5-year overall survival was 80.3% (95% CI, 75.5 to 84.3) after sublobar resection and 78.9% (95% CI, 74.1 to 82.9) after lobar resection. No substantial difference was seen between the two groups in the incidence of locoregional or distant recurrence. At 6 months postoperatively, a between-group difference of 2 percentage points was measured in the median percentage of predicted forced expiratory volume in 1 second, favoring the sublobar-resection group.\n\nConclusions: In patients with peripheral NSCLC with a tumor size of 2 cm or less and pathologically confirmed node-negative disease in the hilar and mediastinal lymph nodes, sublobar resection was not inferior to lobectomy with respect to disease-free survival. Overall survival was similar with the two procedures. (Funded by the National Cancer Institute and others; CALGB 140503 ClinicalTrials.gov number, NCT00499330.).\n\nIndexed on Europe PMC as PubMed record 36780674 (DOI 10.1056/nejmoa2212083). Its abstract cites the registry id NCT00499330, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2212083", pmid: "36780674", authors: "Altorki N, Wang X, Kozono D, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00499330 with the most citations, so it is the natural first reading for anyone following the CALGB 140503 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2212083"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36780674/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36780674"},{"label":"ClinicalTrials.gov NCT00499330","url":"https://clinicaltrials.gov/study/NCT00499330"}], tags: ["europepmc-ingest"], trials: ["calgb-140503"], journals: ["nejm"] }),
  p({ id: "paper-camel-lancet-respir-med-2021", name: "Camrelizumab plus carboplatin and pemetrexed versus chemotherapy alone in chemotherapy-naive patients with advanced non-squamous non-small-cell lung cancer (CameL): a randomised, open-label, multicentre, phase 3 trial", tldr: "Published report from the CameL trial registered as NCT03134872, in The Lancet. Respiratory medicine (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Immunotherapy combined with chemotherapy has been shown to be efficacious as treatment for advanced non-squamous non-small-cell lung cancer (NSCLC) without targetable genetic aberrations; however, there is scarce evidence of the effectiveness of the combinations in the Asian population. We evaluated camrelizumab plus chemotherapy against non-squamous NSCLC in China.\n\nMethods: We did a randomised, open-label, multicentre, phase 3 trial (CameL) in 52 hospitals in China for patients with non-squamous NSCLC without EGFR and ALK alteration. Eligible patients were aged 18-70 years and had no previous systemic chemotherapy, Eastern Cooperative Oncology Group performance status of 0 or 1, and at least one measurable lesion per Response Evaluation Criteria in Solid Tumors (version 1.1). Patients were randomly assigned (1:1) to receive 4-6 cycles of carboplatin (area under curve 5 mg/mL per min) plus pemetrexed (500 mg/m 2) with or without camrelizumab (200 mg) every 3 weeks, followed by maintenance therapy with camrelizumab plus pemetrexed or pemetrexed alone. Medication was administered intravenously on day 1 of each 3-week treatment cycle. Randomisation was done using a centralised interactive web-response system with the block size randomly generated as four or six and stratified by sex and smoking history. The two primary endpoints were progression-free survival per blinded independent central review, in all patients and in patients who were PD-L1 positive. Primary analysis was done in the full analysis set that included all randomly assigned patients who received at least one dose of the study treatment. Herein, due to the primary endpoint being met at the interim analysis, we reported the findings of prespecified interim analysis, which only included confirmatory statistical testing for progression-free survival in all patients. Safety was assessed in the as-treated population. This study is registered with ClinicalTrials.gov, NCT03134872 (follow-up is ongoing).\n\nFindings: Between May 12, 2017, and June 6, 2018, of the 419 patients who were randomly assigned, seven did not receive assigned treatment and 412 received either camrelizumab plus chemotherapy (n=205) or chemotherapy alone (n=207). At interim analysis, median follow-up duration was 11·9 months (IQR 9·0-14·9). Progression-free survival in this interim analysis was significantly prolonged with camrelizumab plus chemotherapy than with chemotherapy alone (median 11·3 months [95% CI 9·6-15·4] vs 8·3 months [6·0-9·7]; hazard ratio 0·60 [0·45-0·79]; one-sided p=0·0001). Most common grade 3 or worse treatment-related adverse events were decreased neutrophil count (78 [38%] patients in the camrelizumab plus chemotherapy group vs 63 [30%] patients in the chemotherapy alone group), decreased white blood cell count (40 [20%] vs 30 [14%]), anaemia (38 [19%] vs 23 [11%]), and decreased platelet count (34 [17%] vs 24 [12%]). Serious treatment-related adverse events occurred in 74 (36%) patients in the camrelizumab plus chemotherapy group and 27 (13%) patients in the chemotherapy alone group.\n\nInterpretation: The primary endpoint was met at the interim analysis, showing a statistically significant and clinically meaningful improvement in progression-free survival with camrelizumab plus carboplatin and pemetrexed versus chemotherapy alone in all patients, supporting camrelizumab plus carboplatin and pemetrexed as a first-line treatment option for Chinese patients with advanced non-squamous NSCLC without EGFR and ALK alterations. The trial is being continued to collect long-term outcomes in all patients and carry out confirmatory statistical testing for progression-free survival in the PD-L1-positive population.\n\nFunding: Jiangsu Hengrui Medicine.\n\nIndexed on Europe PMC as PubMed record 33347829 (DOI 10.1016/s2213-2600(20)30365-9). Its abstract cites the registry id NCT03134872, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2021, doi: "10.1016/s2213-2600(20)30365-9", pmid: "33347829", authors: "Zhou C, Chen G, Huang Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03134872 with the most citations, so it is the natural first reading for anyone following the CameL trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2021","url":"https://doi.org/10.1016/s2213-2600(20)30365-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33347829/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33347829"},{"label":"ClinicalTrials.gov NCT03134872","url":"https://clinicaltrials.gov/study/NCT03134872"}], tags: ["europepmc-ingest"], trials: ["camel"] }),
  p({ id: "paper-camel-j-thorac-oncol-2023-update", name: "Camrelizumab Plus Carboplatin and Pemetrexed as First-Line Treatment for Advanced Nonsquamous NSCLC: Extended Follow-Up of CameL Phase 3 Trial", tldr: "Later report from the CameL trial registered as NCT03134872, in Journal of Thoracic Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Introduction: In CameL phase 3 study (ClinicalTrials.gov: NCT03134872), addition of camrelizumab to first-line chemotherapy significantly improved the progression-free survival in patients with stages IIIB to IV nonsquamous NSCLC. Here, we present outcomes after a minimum follow-up of 43.9 months since last patient randomization.\n\nMethods: Eligible patients were randomized 1:1 to 4 to 6 cycles of camrelizumab plus carboplatin and pemetrexed or chemotherapy alone every 3 weeks, followed by maintenance camrelizumab plus pemetrexed or pemetrexed only (n = 205 and 207, respectively). Total camrelizumab exposure was up to 2 years.\n\nResults: at January 31, 2022, camrelizumab plus chemotherapy exhibited substantially improved overall survival over chemotherapy alone (median, 27.1 versus 19.8 mo; hazard ratio = 0.72 [95% confidence interval: 0.57-0.92]). In the chemotherapy-alone group, 95 patients (45.9%) crossed over to camrelizumab monotherapy. After adjustment for crossover, the survival benefit with camrelizumab plus chemotherapy was more pronounced (adjusted hazard ratio = 0.55 [95% confidence interval: 0.42-0.71]). In camrelizumab plus chemotherapy group, 33 patients completed 2 years of camrelizumab. Objective response rate was 97.0%, with ongoing responses in 17 of the 32 responses (53.1%), and 93.9% (31 of 33) of the patients were alive at data cutoff. Safety profiles were consistent with the previous report, and no obvious evidence of cumulative toxicity was found with long exposure to camrelizumab.\n\nConclusions: Camrelizumab plus carboplatin and pemetrexed provides long-term survival benefit over chemotherapy, with manageable toxicity and remarkable and durable response in patients receiving 2 years of camrelizumab, further supporting camrelizumab combination as first-line treatment for advanced nonsquamous NSCLC.\n\nIndexed on Europe PMC as PubMed record 36646210 (DOI 10.1016/j.jtho.2022.12.017). Its abstract cites the registry id NCT03134872, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2023, doi: "10.1016/j.jtho.2022.12.017", pmid: "36646210", authors: "Zhou C, Chen G, Huang Y, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CameL trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Thorac Oncol 2023","url":"https://doi.org/10.1016/j.jtho.2022.12.017"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36646210/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36646210"},{"label":"ClinicalTrials.gov NCT03134872","url":"https://clinicaltrials.gov/study/NCT03134872"}], tags: ["europepmc-ingest"], trials: ["camel"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-capstone-1-lancet-oncol-2022", name: "Adebrelimab or placebo plus carboplatin and etoposide as first-line treatment for extensive-stage small-cell lung cancer (CAPSTONE-1): a multicentre, randomised, double-blind, placebo-controlled, phase 3 trial", tldr: "Published report from the CAPSTONE-1 trial registered as NCT03711305, in The Lancet Oncology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Extensive-stage small-cell lung cancer (ES-SCLC) is associated with poor prognosis and treatment options are scarce. Immunotherapy has shown robust clinical activity in ES-SCLC in previous phase 3 trials. We aimed to assess the efficacy and safety of adebrelimab (SHR-1316), a novel anti-PD-L1 antibody, with standard chemotherapy as a first-line treatment for ES-SCLC.\n\nMethods: The CAPSTONE-1 study was a randomised, double-blind, placebo-controlled, phase 3 trial, done in 47 tertiary hospitals in China. Key inclusion criteria were patients aged 18-75 years, with previously untreated histologically or cytologically confirmed ES-SCLC and an Eastern Cooperative Oncology Group (ECOG) performance status of 0-1. Eligible patients were randomly assigned (1:1) to receive four to six cycles of carboplatin (area under the curve of 5 mg/mL per min, day 1 of each cycle) and etoposide (100 mg/m 2 of body-surface area, on days 1-3 of each cycle) with either adebrelimab (20 mg/kg, day 1 of each cycle) or matching placebo, followed by maintenance therapy with adebrelimab or placebo. All treatments were given intravenously in 21-day cycles. Randomisation was done using a centralised interactive web response system with a block size of four, stratified by liver metastases, brain metastases, and lactate dehydrogenase concentration. The primary endpoint was overall survival in patients who received at least one dose of study medication. Safety was analysed in the as-treated population. This study is complete and registered with ClinicalTrials.gov, NCT03711305.\n\nFindings: Between Dec 26, 2018, and Sept 4, 2020, 462 eligible patients were enrolled and randomly assigned: 230 (50%) patients received adebrelimab plus chemotherapy (adebrelimab group) and 232 (50%) patients received placebo plus chemotherapy (placebo group). At data cutoff (Oct 8, 2021), median follow-up was 13·5 months (IQR 8·9-20·1). Median overall survival was significantly improved in the adebrelimab group (median 15·3 months [95% CI 13·2-17·5]) compared with the placebo group (12·8 months [11·3-13·7]; hazard ratio 0·72 [95% CI 0·58-0·90]; one-sided p=0·0017). The most common treatment-related grade 3 or 4 adverse events were decreased neutrophil count (174 [76%] patients in the adebrelimab group and 175 [75%] patients in the placebo group), decreased white blood cell count (106 [46%] and 88 [38%]), decreased platelet count (88 [38%] and 78 [34%]), and anaemia (64 [28%] and 66 [28%]). Treatment-related serious adverse events occurred in 89 (39%) patients in the adebrelimab group and 66 (28%) patients in the placebo group. Four treatment-related deaths were reported: two each in the adebrelimab group (respiratory failure and interstitial lung disease and pneumonia) and placebo group (multiple organ dysfunction and unknown cause of death).\n\nInterpretation: Adding adebrelimab to chemotherapy significantly improved overall survival with an acceptable safety profile in patients with ES-SCLC, supporting this combination as a new first-line treatment option for this population.\n\nFunding: Jiangsu Hengrui Pharmaceuticals.\n\nIndexed on Europe PMC as PubMed record 35576956 (DOI 10.1016/s1470-2045(22)00224-8). Its abstract cites the registry id NCT03711305, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2022, doi: "10.1016/s1470-2045(22)00224-8", pmid: "35576956", authors: "Wang J, Zhou C, Yao W, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03711305 with the most citations, so it is the natural first reading for anyone following the CAPSTONE-1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2022","url":"https://doi.org/10.1016/s1470-2045(22)00224-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35576956/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35576956"},{"label":"ClinicalTrials.gov NCT03711305","url":"https://clinicaltrials.gov/study/NCT03711305"}], tags: ["europepmc-ingest"], trials: ["capstone-1"], journals: ["lancet-oncology"] }),
  p({ id: "paper-caspian-lancet-2019", name: "Durvalumab plus platinum-etoposide versus platinum-etoposide in first-line treatment of extensive-stage small-cell lung cancer (CASPIAN): a randomised, controlled, open-label, phase 3 trial", tldr: "Published report from the CASPIAN trial registered as NCT03043872, in The Lancet (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Most patients with small-cell lung cancer (SCLC) have extensive-stage disease at presentation, and prognosis remains poor. Recently, immunotherapy has demonstrated clinical activity in extensive-stage SCLC (ES-SCLC). The CASPIAN trial assessed durvalumab, with or without tremelimumab, in combination with etoposide plus either cisplatin or carboplatin (platinum-etoposide) in treatment-naive patients with ES-SCLC.\n\nMethods: This randomised, open-label, phase 3 trial was done at 209 sites across 23 countries. Eligible patients were adults with untreated ES-SCLC, with WHO performance status 0 or 1 and measurable disease as per Response Evaluation Criteria in Solid Tumors, version 1.1. Patients were randomly assigned (in a 1:1:1 ratio) to durvalumab plus platinum-etoposide; durvalumab plus tremelimumab plus platinum-etoposide; or platinum-etoposide alone. All drugs were administered intravenously. Platinum-etoposide consisted of etoposide 80-100 mg/m 2 on days 1-3 of each cycle with investigator's choice of either carboplatin area under the curve 5-6 mg/mL per min or cisplatin 75-80 mg/m 2 (administered on day 1 of each cycle). Patients received up to four cycles of platinum-etoposide plus durvalumab 1500 mg with or without tremelimumab 75 mg every 3 weeks followed by maintenance durvalumab 1500 mg every 4 weeks in the immunotherapy groups and up to six cycles of platinum-etoposide every 3 weeks plus prophylactic cranial irradiation (investigator's discretion) in the platinum-etoposide group. The primary endpoint was overall survival in the intention-to-treat population. We report results for the durvalumab plus platinum-etoposide group versus the platinum-etoposide group from a planned interim analysis. Safety was assessed in all patients who received at least one dose of their assigned study treatment. This study is registered at ClinicalTrials.gov, NCT03043872, and is ongoing.\n\nFindings: Patients were enrolled between March 27, 2017, and May 29, 2018. 268 patients were allocated to the durvalumab plus platinum-etoposide group and 269 to the platinum-etoposide group. Durvalumab plus platinum-etoposide was associated with a significant improvement in overall survival, with a hazard ratio of 0·73 (95% CI 0·59-0·91; p=0·0047]); median overall survival was 13·0 months (95% CI 11·5-14·8) in the durvalumab plus platinum-etoposide group versus 10·3 months (9·3-11·2) in the platinum-etoposide group, with 34% (26·9-41·0) versus 25% (18·4-31·6) of patients alive at 18 months. Any-cause adverse events of grade 3 or 4 occurred in 163 (62%) of 265 treated patients in the durvalumab plus platinum-etoposide group and 166 (62%) of 266 in the platinum-etoposide group; adverse events leading to death occurred in 13 (5%) and 15 (6%) patients.\n\nInterpretation: First-line durvalumab plus platinum-etoposide significantly improved overall survival in patients with ES-SCLC versus a clinically relevant control group. Safety findings were consistent with the known safety profiles of all drugs received.\n\nFunding: AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 31590988 (DOI 10.1016/s0140-6736(19)32222-6). Its abstract cites the registry id NCT03043872, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2019, doi: "10.1016/s0140-6736(19)32222-6", pmid: "31590988", authors: "Paz-Ares L, Dvorkin M, Chen Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03043872 with the most citations, so it is the natural first reading for anyone following the CASPIAN trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2019","url":"https://doi.org/10.1016/s0140-6736(19)32222-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31590988/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31590988"},{"label":"ClinicalTrials.gov NCT03043872","url":"https://clinicaltrials.gov/study/NCT03043872"}], tags: ["europepmc-ingest"], trials: ["caspian"], journals: ["lancet"] }),
  p({ id: "paper-caspian-lancet-oncol-2021-update", name: "Durvalumab, with or without tremelimumab, plus platinum-etoposide versus platinum-etoposide alone in first-line treatment of extensive-stage small-cell lung cancer (CASPIAN): updated results from a randomised, controlled, open-label, phase 3 trial", tldr: "Later report from the CASPIAN trial registered as NCT03043872, in The Lancet Oncology (2021); its title describes an updated or longer-term analysis.", summary: "Background: First-line durvalumab plus etoposide with either cisplatin or carboplatin (platinum-etoposide) showed a significant improvement in overall survival versus platinum-etoposide alone in patients with extensive-stage small-cell lung cancer (ES-SCLC) in the CASPIAN study. Here we report updated results, including the primary analysis for overall survival with durvalumab plus tremelimumab plus platinum-etoposide versus platinum-etoposide alone.\n\nMethods: CASPIAN is an ongoing, open-label, sponsor-blind, randomised, controlled phase 3 trial at 209 cancer treatment centres in 23 countries worldwide. Eligible patients were aged 18 years or older (20 years in Japan) and had treatment-naive, histologically or cytologically documented ES-SCLC, with a WHO performance status of 0 or 1. Patients were randomly assigned (1:1:1) in blocks of six, stratified by planned platinum, using an interactive voice-response or web-response system to receive intravenous durvalumab plus tremelimumab plus platinum-etoposide, durvalumab plus platinum-etoposide, or platinum-etoposide alone. In all groups, patients received etoposide 80-100 mg/m 2 on days 1-3 of each cycle with investigator's choice of either carboplatin area under the curve 5-6 mg/mL/min or cisplatin 75-80 mg/m 2 on day 1 of each cycle. Patients in the platinum-etoposide group received up to six cycles of platinum-etoposide every 3 weeks and optional prophylactic cranial irradiation (investigator's discretion). Patients in the immunotherapy groups received four cycles of platinum-etoposide plus durvalumab 1500 mg with or without tremelimumab 75 mg every 3 weeks followed by maintenance durvalumab 1500 mg every 4 weeks. The two primary endpoints were overall survival for durvalumab plus platinum-etoposide versus platinum-etoposide and for durvalumab plus tremelimumab plus platinum-etoposide versus platinum-etoposide in the intention-to-treat population. Safety was assessed in all patients who received at least one dose of study treatment. This study is registered at ClinicalTrials.gov, NCT03043872.\n\nFindings: Between March 27, 2017, and May 29, 2018, 972 patients were screened and 805 were randomly assigned (268 to durvalumab plus tremelimumab plus platinum-etoposide, 268 to durvalumab plus platinum-etoposide, and 269 to platinum-etoposide). at Jan 27, 2020, the median follow-up was 25·1 months (IQR 22·3-27·9). Durvalumab plus tremelimumab plus platinum-etoposide was not associated with a significant improvement in overall survival versus platinum-etoposide (hazard ratio [HR] 0·82 [95% CI 0·68-1·00]; p=0·045); median overall survival was 10·4 months (95% CI 9·6-12·0) versus 10·5 months (9·3-11·2). Durvalumab plus platinum-etoposide showed sustained improvement in overall survival versus platinum-etoposide (HR 0·75 [95% CI 0·62-0·91]; nominal p=0·0032); median overall survival was 12·9 months (95% CI 11·3-14·7) versus 10·5 months (9·3-11·2). The most common any-cause grade 3 or worse adverse events were neutropenia (85 [32%] of 266 patients in the durvalumab plus tremelimumab plus platinum-etoposide group, 64 [24%] of 265 patients in the durvalumab plus platinum-etoposide group, and 88 [33%] of 266 patients in the platinum-etoposide group) and anaemia (34 [13%], 24 [9%], and 48 [18%]). Any-cause serious adverse events were reported in 121 (45%) patients in the durvalumab plus tremelimumab plus platinum-etoposide group, 85 (32%) in the durvalumab plus platinum-etoposide group, and 97 (36%) in the platinum-etoposide group. Treatment-related deaths occurred in 12 (5%) patients in the durvalumab plus tremelimumab plus platinum-etoposide group (death, febrile neutropenia, and pulmonary embolism [n=2 each]; enterocolitis, general physical health deterioration and multiple organ dysfunction syndrome, pneumonia, pneumonitis and hepatitis, respiratory failure, and sudden death [n=1 each]), six (2%) patients in the durvalumab plus platinum-etoposide group (cardiac arrest, dehydration, hepatotoxicity, interstitial lung disease, pancytopenia, and sepsis [n=1 each]), and two (1%) in the platinum-etoposide group (pancytopenia and thrombocytopenia [n=1 each]).\n\nInterpretation: First-line durvalumab plus platinum-etoposide showed sustained overall survival improvement versus platinum-etoposide but the addition of tremelimumab to durvalumab plus platinum-etoposide did not significantly improve outcomes versus platinum-etoposide. These results support the use of durvalumab plus platinum-etoposide as a new standard of care for the first-line treatment of ES-SCLC.\n\nFunding: AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 33285097 (DOI 10.1016/s1470-2045(20)30539-8). Its abstract cites the registry id NCT03043872, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2021, doi: "10.1016/s1470-2045(20)30539-8", pmid: "33285097", authors: "Goldman JW, Dvorkin M, Chen Y, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CASPIAN trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2021","url":"https://doi.org/10.1016/s1470-2045(20)30539-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33285097/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33285097"},{"label":"ClinicalTrials.gov NCT03043872","url":"https://clinicaltrials.gov/study/NCT03043872"}], tags: ["europepmc-ingest"], trials: ["caspian"], journals: ["lancet-oncology"] }),
  p({ id: "paper-checkmate-227-n-engl-j-med-2018", name: "Nivolumab plus Ipilimumab in Lung Cancer with a High Tumor Mutational Burden", tldr: "Published report from the CheckMate 227 trial registered as NCT02477826, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Nivolumab plus ipilimumab showed promising efficacy for the treatment of non-small-cell lung cancer (NSCLC) in a phase 1 trial, and tumor mutational burden has emerged as a potential biomarker of benefit. In this part of an open-label, multipart, phase 3 trial, we examined progression-free survival with nivolumab plus ipilimumab versus chemotherapy among patients with a high tumor mutational burden (≥10 mutations per megabase).\n\nMethods: We enrolled patients with stage IV or recurrent NSCLC that was not previously treated with chemotherapy. Those with a level of tumor programmed death ligand 1 (PD-L1) expression of at least 1% were randomly assigned, in a 1:1:1 ratio, to receive nivolumab plus ipilimumab, nivolumab monotherapy, or chemotherapy; those with a tumor PD-L1 expression level of less than 1% were randomly assigned, in a 1:1:1 ratio, to receive nivolumab plus ipilimumab, nivolumab plus chemotherapy, or chemotherapy. Tumor mutational burden was determined by the FoundationOne CDx assay.\n\nResults: Progression-free survival among patients with a high tumor mutational burden was significantly longer with nivolumab plus ipilimumab than with chemotherapy. The 1-year progression-free survival rate was 42.6% with nivolumab plus ipilimumab versus 13.2% with chemotherapy, and the median progression-free survival was 7.2 months (95% confidence interval [CI], 5.5 to 13.2) versus 5.5 months (95% CI, 4.4 to 5.8) (hazard ratio for disease progression or death, 0.58; 97.5% CI, 0.41 to 0.81; P<0.001). The objective response rate was 45.3% with nivolumab plus ipilimumab and 26.9% with chemotherapy. The benefit of nivolumab plus ipilimumab over chemotherapy was broadly consistent within subgroups, including patients with a PD-L1 expression level of at least 1% and those with a level of less than 1%. The rate of grade 3 or 4 treatment-related adverse events was 31.2% with nivolumab plus ipilimumab and 36.1% with chemotherapy. ical; CheckMate 227 ClinicalTrials.gov number, NCT02477826.).\n\nConclusions: Progression-free survival was significantly longer with first-line nivolumab plus ipilimumab than with chemotherapy among patients with NSCLC and a high tumor mutational burden, irrespective of PD-L1 expression level. The results validate the benefit of nivolumab plus ipilimumab in NSCLC and the role of tumor mutational burden as a biomarker for patient selection. (Funded by Bristol-Myers Squibb and Ono Pharmaceut\n\nIndexed on Europe PMC as PubMed record 29658845 (DOI 10.1056/nejmoa1801946). Its abstract cites the registry id NCT02477826, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1801946", pmid: "29658845", authors: "Hellmann MD, Ciuleanu TE, Pluzanski A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02477826 with the most citations, so it is the natural first reading for anyone following the CheckMate 227 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1801946"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/29658845/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/29658845"},{"label":"ClinicalTrials.gov NCT02477826","url":"https://clinicaltrials.gov/study/NCT02477826"}], tags: ["europepmc-ingest"], trials: ["checkmate-227"], journals: ["nejm"] }),
  p({ id: "paper-checkmate-227-int-j-clin-oncol-2023-update", name: "First-line nivolumab plus ipilimumab in metastatic non-small cell lung cancer: 5-year outcomes in Japanese patients from CheckMate 227 Part 1", tldr: "Later report from the CheckMate 227 trial registered as NCT02477826, in International journal of clinical oncology (2023); its title describes an updated or longer-term analysis.", summary: "Background: In CheckMate 227 Part 1 (NCT02477826), first-line nivolumab plus ipilimumab demonstrated long-term durable overall survival (OS) benefit versus chemotherapy in patients with metastatic non-small cell lung cancer (NSCLC), regardless of tumor programmed death ligand 1 (PD-L1) expression. We report results in Japanese patients with ≥ 5-year follow-up.\n\nMethods: Adults with stage IV/recurrent NSCLC without EGFR/ALK aberrations were randomized 1:1:1 to nivolumab plus ipilimumab, nivolumab alone, or chemotherapy (patients with tumor PD-L1 ≥ 1%), or nivolumab plus ipilimumab, nivolumab plus chemotherapy, or chemotherapy (patients with tumor PD-L1 < 1%). Five-year efficacy and safety were assessed in Japanese patients.\n\nResults: At 62.1 months' minimum follow-up, 143 Japanese patients with PD-L1 ≥ 1% or < 1% were randomized to nivolumab plus ipilimumab (n = 66) or chemotherapy (n = 77). Five-year OS rates were 46% with nivolumab plus ipilimumab versus 34% with chemotherapy (PD-L1 ≥ 1%) and 36% versus 19% (PD-L1 < 1%). Median duration of response was 59.1 versus 7.1 months (PD-L1 ≥ 1%) and 17.3 versus 3.0 months (PD-L1 < 1%). Among 5-year survivors treated with nivolumab plus ipilimumab (PD-L1 ≥ 1% and < 1%; n = 27), 59% (95% CI, 39%-75%) were off treatment for ≥ 3 years without receiving subsequent therapy. No new safety signals were observed.\n\nConclusions: At 5-year follow-up, nivolumab plus ipilimumab continued to show long-term durable clinical benefit versus chemotherapy, regardless of tumor PD-L1 expression. Consistent with findings for the global population, these data support the use of nivolumab plus ipilimumab as first-line treatment in Japanese patients with metastatic NSCLC.\n\nIndexed on Europe PMC as PubMed record 37548831 (DOI 10.1007/s10147-023-02390-2). Its abstract cites the registry id NCT02477826, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "International journal of clinical oncology", year: 2023, doi: "10.1007/s10147-023-02390-2", pmid: "37548831", authors: "Nishio M, Ohe Y, Ikeda S, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CheckMate 227 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Int J Clin Oncol 2023","url":"https://doi.org/10.1007/s10147-023-02390-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37548831/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37548831"},{"label":"ClinicalTrials.gov NCT02477826","url":"https://clinicaltrials.gov/study/NCT02477826"}], tags: ["europepmc-ingest"], trials: ["checkmate-227"], journals: ["international-journal-of-clinical-oncology"] }),
  p({ id: "paper-checkmate-816-n-engl-j-med-2025-update", name: "Overall Survival with Neoadjuvant Nivolumab plus Chemotherapy in Lung Cancer", tldr: "Later report from the CheckMate 816 trial registered as NCT02998528, in New England Journal of Medicine (2025); its title describes an updated or longer-term analysis.", summary: "Background: Neoadjuvant nivolumab plus chemotherapy significantly improved pathological complete response and event-free survival in patients with resectable non-small-cell lung cancer (NSCLC) in a phase 3 trial. Data are needed on overall survival.\n\nMethods: In this open-label, phase 3 trial, patients with stage IB to IIIA resectable NSCLC were randomly assigned to receive nivolumab plus chemotherapy or chemotherapy alone for three cycles, followed by surgery. The primary end points were event-free survival and pathological complete response. Here, we report the results of the planned analysis of overall survival.\n\nResults: A total of 358 patients were concurrently assigned to receive nivolumab plus chemotherapy (179 patients) or chemotherapy alone (179 patients). The final analysis of overall survival significantly favored neoadjuvant nivolumab plus chemotherapy over chemotherapy (hazard ratio for death, 0.72; 95% confidence interval [CI], 0.523 to 0.998; P = 0.048). At a median follow-up of 68.4 months, the 5-year overall survival was 65.4% with nivolumab plus chemotherapy and 55.0% with chemotherapy alone, with consistency across most subgroups. In exploratory analyses, the 5-year overall survival in the nivolumab-plus-chemotherapy group was 95.3% (95% CI, 82.7 to 98.8) among the patients with a pathological complete response and 55.7% (95% CI, 46.9 to 63.7) among those without such a response; survival was 75.0% among the patients with presurgery clearance of circulating tumor DNA (ctDNA) and 52.6% among those without such clearance. No new safety signals were observed.\n\nConclusions: Three cycles of neoadjuvant nivolumab plus chemotherapy significantly improved overall survival among patients with resectable NSCLC as compared with chemotherapy alone. (Funded by Bristol Myers Squibb; CheckMate 816 ClinicalTrials.gov number, NCT02998528.).\n\nIndexed on Europe PMC as PubMed record 40454642 (DOI 10.1056/nejmoa2502931). Its abstract cites the registry id NCT02998528, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2502931", pmid: "40454642", authors: "Forde PM, Spicer JD, Provencio M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CheckMate 816 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2502931"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40454642/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40454642"},{"label":"ClinicalTrials.gov NCT02998528","url":"https://clinicaltrials.gov/study/NCT02998528"}], tags: ["europepmc-ingest"], trials: ["checkmate-816"], journals: ["nejm"] }),
  p({ id: "paper-chisel-lancet-oncol-2019", name: "Stereotactic ablative radiotherapy versus standard radiotherapy in stage 1 non-small-cell lung cancer (TROG 09.02 CHISEL): a phase 3, open-label, randomised controlled trial", tldr: "Published report from the CHISEL trial registered as NCT01014130, in The Lancet Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Stereotactic ablative body radiotherapy (SABR) is widely used to treat inoperable stage 1 non-small-cell lung cancer (NSCLC), despite the absence of prospective evidence that this type of treatment improves local control or prolongs overall survival compared with standard radiotherapy. We aimed to compare the two treatment techniques.\n\nMethods: We did this multicentre, phase 3, randomised, controlled trial in 11 hospitals in Australia and three hospitals in New Zealand. Patients were eligible if they were aged 18 years or older, had biopsy-confirmed stage 1 (T1-T2aN0M0) NSCLC diagnosed on the basis of 18 F-fluorodeoxyglucose PET, and were medically inoperable or had refused surgery. Patients had to have an Eastern Cooperative Oncology Group performance status of 0 or 1, and the tumour had to be peripherally located. Patients were randomly assigned after stratification for T stage and operability in a 2:1 ratio to SABR (54 Gy in three 18 Gy fractions, or 48 Gy in four 12 Gy fractions if the tumour was <2 cm from the chest wall) or standard radiotherapy (66 Gy in 33 daily 2 Gy fractions or 50 Gy in 20 daily 2·5 Gy fractions, depending on institutional preference) using minimisation, so no sequence was pre-generated. Clinicians, patients, and data managers had no previous knowledge of the treatment group to which patients would be assigned; however, the treatment assignment was subsequently open label (because of the nature of the interventions). The primary endpoint was time to local treatment failure (assessed according to Response Evaluation Criteria in Solid Tumors version 1.0), with the hypothesis that SABR would result in superior local control compared with standard radiotherapy. All efficacy analyses were based on the intention-to-treat analysis. Safety analyses were done on a per-protocol basis, according to treatment that the patients actually received. The trial is registered with ClinicalTrials.gov (NCT01014130) and the Australia and New Zealand Clinical Trials Registry (ACTRN12610000479000). The trial is closed to new participants.\n\nFindings: Between Dec 31, 2009, and June 22, 2015, 101 eligible patients were enrolled and randomly assigned to receive SABR (n=66) or standard radiotherapy (n=35). Five (7·6%) patients in the SABR group and two (6·5%) in the standard radiotherapy group did not receive treatment, and a further four in each group withdrew before study end. at data cutoff (July 31, 2017), median follow-up for local treatment failure was 2·1 years (IQR 1·2-3·6) for patients randomly assigned to standard radiotherapy and 2·6 years (IQR 1·6-3·6) for patients assigned to SABR. 20 (20%) of 101 patients had progressed locally: nine (14%) of 66 patients in the SABR group and 11 (31%) of 35 patients in the standard radiotherapy group, and freedom from local treatment failure was improved in the SABR group compared with the standard radiotherapy group (hazard ratio 0·32, 95% CI 0·13-0·77, p=0·0077). Median time to local treatment failure was not reached in either group. In patients treated with SABR, there was one grade 4 adverse event (dyspnoea) and seven grade 3 adverse events (two cough, one hypoxia, one lung infection, one weight loss, one dyspnoea, and one fatigue) related to treatment compared with two grade 3 events (chest pain) in the standard treatment group.\n\nInterpretation: In patients with inoperable peripherally located stage 1 NSCLC, compared with standard radiotherapy, SABR resulted in superior local control of the primary disease without an increase in major toxicity. The findings of this trial suggest that SABR should be the treatment of choice for this patient group.\n\nFunding: The Radiation and Optometry Section of the Australian Government Department of Health with the assistance of Cancer Australia, and the Cancer Society of New Zealand and the Cancer Research Trust New Zealand (formerly Genesis Oncology Trust).\n\nIndexed on Europe PMC as PubMed record 30770291 (DOI 10.1016/s1470-2045(18)30896-9). Its abstract cites the registry id NCT01014130, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2019, doi: "10.1016/s1470-2045(18)30896-9", pmid: "30770291", authors: "Ball D, Mai GT, Vinod S, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01014130 with the most citations, so it is the natural first reading for anyone following the CHISEL trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2019","url":"https://doi.org/10.1016/s1470-2045(18)30896-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30770291/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30770291"},{"label":"ClinicalTrials.gov NCT01014130","url":"https://clinicaltrials.gov/study/NCT01014130"}], tags: ["europepmc-ingest"], trials: ["chisel"], journals: ["lancet-oncology"] }),
  p({ id: "paper-convert-lancet-oncol-2017", name: "Concurrent once-daily versus twice-daily chemoradiotherapy in patients with limited-stage small-cell lung cancer (CONVERT): an open-label, phase 3, randomised, superiority trial", tldr: "Published report from the CONVERT trial registered as NCT00433563, in The Lancet Oncology (2017), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Concurrent chemoradiotherapy is the standard of care in limited-stage small-cell lung cancer, but the optimal radiotherapy schedule and dose remains controversial. The aim of this study was to establish a standard chemoradiotherapy treatment regimen in limited-stage small-cell lung cancer.\n\nMethods: The CONVERT trial was an open-label, phase 3, randomised superiority trial. We enrolled adult patients (aged ≥18 years) who had cytologically or histologically confirmed limited-stage small-cell lung cancer, Eastern Cooperative Oncology Group performance status of 0-2, and adequate pulmonary function. Patients were recruited from 73 centres in eight countries. Patients were randomly assigned to receive either 45 Gy radiotherapy in 30 twice-daily fractions of 1·5 Gy over 19 days, or 66 Gy in 33 once-daily fractions of 2 Gy over 45 days, starting on day 22 after commencing cisplatin-etoposide chemotherapy (given as four to six cycles every 3 weeks in both groups). The allocation method used was minimisation with a random element, stratified by institution, planned number of chemotherapy cycles, and performance status. Treatment group assignments were not masked. The primary endpoint was overall survival, defined as time from randomisation until death from any cause, analysed by modified intention-to-treat. A 12% higher overall survival at 2 years in the once-daily group versus the twice-daily group was considered to be clinically significant to show superiority of the once-daily regimen. The study is registered with ClinicalTrials.gov (NCT00433563) and is currently in follow-up.\n\nFindings: Between April 7, 2008, and Nov 29, 2013, 547 patients were enrolled and randomly assigned to receive twice-daily concurrent chemoradiotherapy (274 patients) or once-daily concurrent chemoradiotherapy (273 patients). Four patients (one in the twice-daily group and three in the once-daily group) did not return their case report forms and were lost to follow-up; these patients were not included in our analyses. At a median follow-up of 45 months (IQR 35-58), median overall survival was 30 months (95% CI 24-34) in the twice-daily group versus 25 months (21-31) in the once-daily group (hazard ratio for death in the once daily group 1·18 [95% CI 0·95-1·45]; p=0·14). 2-year overall survival was 56% (95% CI 50-62) in the twice-daily group and 51% (45-57) in the once-daily group (absolute difference between the treatment groups 5·3% [95% CI -3·2% to 13·7%]). The most common grade 3-4 adverse event in patients evaluated for chemotherapy toxicity was neutropenia (197 [74%] of 266 patients in the twice-daily group vs 170 [65%] of 263 in the once-daily group). Most toxicities were similar between the groups, except there was significantly more grade 4 neutropenia with twice-daily radiotherapy (129 [49%] vs 101 [38%]; p=0·05). In patients assessed for radiotherapy toxicity, was no difference in grade 3-4 oesophagitis between the groups (47 [19%] of 254 patients in the twice-daily group vs 47 [19%] of 246 in the once-daily group; p=0·85) and grade 3-4 radiation pneumonitis (4 [3%] of 254 vs 4 [2%] of 246; p=0·70). 11 patients died from treatment-related causes (three in the twice-daily group and eight in the once-daily group).\n\nInterpretation: Survival outcomes did not differ between twice-daily and once-daily concurrent chemoradiotherapy in patients with limited-stage small-cell lung cancer, and toxicity was similar and lower than expected with both regimens. Since the trial was designed to show superiority of once-daily radiotherapy and was not powered to show equivalence, the implication is that twice-daily radiotherapy should continue to be considered the standard of care in this setting.\n\nFunding: Cancer Research UK (Clinical Trials Awards and Advisory Committee), French Ministry of Health, Canadian Cancer Society Research Institute, European Organisation for Research and Treatment of Cancer (Cancer Research Fund, Lung Cancer, and Radiation Oncology Groups).\n\nIndexed on Europe PMC as PubMed record 28642008 (DOI 10.1016/s1470-2045(17)30318-2). Its abstract cites the registry id NCT00433563, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2017, doi: "10.1016/s1470-2045(17)30318-2", pmid: "28642008", authors: "Faivre-Finn C, Snee M, Ashcroft L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00433563 with the most citations, so it is the natural first reading for anyone following the CONVERT trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2017","url":"https://doi.org/10.1016/s1470-2045(17)30318-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28642008/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28642008"},{"label":"ClinicalTrials.gov NCT00433563","url":"https://clinicaltrials.gov/study/NCT00433563"}], tags: ["europepmc-ingest"], trials: ["convert"], journals: ["lancet-oncology"] }),
  p({ id: "paper-convert-int-j-radiat-oncol-biol-phys-2024-update", name: "Long-Term Outcomes After Concurrent Once- or Twice-Daily Chemoradiation in Limited-Stage Small Cell Lung Cancer: A Brief Report From the CONVERT Trial", tldr: "Later report from the CONVERT trial registered as NCT00433563, in International Journal of Radiation Oncology, Biology, Physics (2024); its title describes an updated or longer-term analysis.", summary: "Purpose: CONVERT was a phase 3 international randomized clinical trial comparing once-daily (OD) and twice-daily (BD) radiation therapy (RT). This updated analysis describes the 6.5-year outcomes of these regimens delivered with conformal techniques.\n\nMethods and materials: CONVERT (NCT00433563) randomized patients 1:1 between OD RT (66 Gy/33 fractions/6.5 weeks) and BD RT (45 Gy/30 fractions/3 weeks), both delivered with concurrent cisplatin/etoposide. Three-dimensional conformal RT was mandatory, intensity-modulated RT was permitted, and elective nodal irradiation was not allowed. Prophylactic cranial irradiation was delivered at the discretion of treating clinicians. RT treatment planning was subject to central quality assurance.\n\nResults: Five hundred forty-seven patients were recruited at 73 centers. The median follow-up for the surviving cohort (n = 164) was 81.2 months. The median survival for the OD and BD arms were 25.4 months (95% CI, 21.1-30.9) and 30.0 months (95% CI, 25.3-36.5; hazard ratio, 1.13; 95% CI, 0.92-1.38; P =.247). Performance status and tumor volume were associated with survival on multivariate analysis. No treatment-related deaths occurred subsequent to the initial analysis performed in 2017. Regarding late toxicity, 7 patients in the OD arm developed grade 3 esophagitis, 4 of which went on to develop stricture or fistulation, compared with no patients in the BD arm. Grade 3 pulmonary fibrosis occurred in 2 and 3 patients in the OD and BD arms, respectively.\n\nConclusions: As the CONVERT trial did not demonstrate the superiority of OD RT and this regimen had a slightly worse toxicity profile after 80 months of follow-up, 45 Gy BD should remain the standard of care in limited stage small cell lung cancer.\n\nIndexed on Europe PMC as PubMed record 38521132 (DOI 10.1016/j.ijrobp.2024.02.063). Its abstract cites the registry id NCT00433563, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "International Journal of Radiation Oncology, Biology, Physics", year: 2024, doi: "10.1016/j.ijrobp.2024.02.063", pmid: "38521132", authors: "Walls GM, Mistry H, Barlesi F, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CONVERT trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Int J Radiat Oncol Biol Phys 2024","url":"https://doi.org/10.1016/j.ijrobp.2024.02.063"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38521132/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38521132"},{"label":"ClinicalTrials.gov NCT00433563","url":"https://clinicaltrials.gov/study/NCT00433563"}], tags: ["europepmc-ingest"], trials: ["convert"], journals: ["ijrobp"] }),
  p({ id: "paper-crown-lancet-respir-med-2023-update", name: "Efficacy and safety of first-line lorlatinib versus crizotinib in patients with advanced, ALK-positive non-small-cell lung cancer: updated analysis of data from the phase 3, randomised, open-label CROWN study", tldr: "Later report from the CROWN trial registered as NCT03052608, in The Lancet. Respiratory medicine (2023); its title describes an updated or longer-term analysis.", summary: "Background: After a median follow-up of 18·3 months, the third-generation anaplastic lymphoma kinase (ALK) tyrosine-kinase inhibitor, lorlatinib, improved progression-free survival in patients with treatment-naive, ALK-positive non-small-cell lung cancer in the phase 3 CROWN study. Here we report updated efficacy data, including intracranial activity, from an unplanned analysis after 3 years of follow-up.\n\nMethods: CROWN is an ongoing, international, randomised, open-label phase 3 trial done in 104 centres in 23 countries worldwide. Eligible participants were aged 18 years and older or aged 20 years and older (depending on local regulations) with advanced, ALK-positive non-small-cell lung cancer, had received no previous systemic treatment for metastatic disease, had at least one extracranial measurable target lesion (according to the Response Evaluation Criteria in Solid Tumours [RECIST], version 1.1), and had an Eastern Cooperative Oncology Group performance status score of 0-2. Patients were randomly assigned (1:1) to oral lorlatinib 100 mg daily or oral crizotinib 250 mg twice daily in 28-day cycles. Randomisation was stratified by the presence or absence of brain metastasis, and by ethnicity. Since the primary endpoint of the study had been met at the planned interim analysis, no further formal analysis of progression-free survival was planned, per protocol. The current unplanned analysis was done to further characterise tumour-related endpoints with a longer follow-up and is presented descriptively. For the planned study, the primary endpoint was progression-free survival assessed by blinded independent central review. Secondary endpoints included progression-free survival (investigator), objective response rate, intracranial objective response rate, time to intracranial progression, duration of response, intracranial duration of response, and safety. Efficacy endpoints were also assessed by the presence or absence of baseline brain metastases. This study is registered with ClinicalTrials.gov, NCT03052608.\n\nFindings: Between May 11, 2017, and Feb 28, 2019, 425 patients were screened for eligibility, of whom 296 were enrolled and randomly assigned to the lorlatinib (n=149) or crizotinib (n=147) group. At data cutoff for this unplanned analysis (Sept 20, 2021), median duration of follow-up for progression-free survival was 36·7 months (IQR 31·3-41·9) for lorlatinib and 29·3 months (10·8-35·0) for crizotinib. Median progression-free survival by blinded independent central review was not reached (95% CI not reached-not reached) for lorlatinib and was 9·3 months (7·6-11·1) for crizotinib (hazard ratio [HR] 0·27 [95% CI 0·18-0·39]). 3-year progression-free survival was 64% (95% CI 55-71) in the lorlatinib group and 19% (12-27) in the crizotinib group. Progression-free survival (investigator), objective response rate, intracranial objective response rate, time to intracranial progression, and duration of response were improved with lorlatinib versus crizotinib. In patients with baseline brain metastases (n=37 lorlatinib; n=39 crizotinib), the HR for time to intracranial progression for lorlatinib versus crizotinib was 0·10 (95% CI 0·04-0·27); in patients without baseline brain metastases (n=112 lorlatinib; n=108 crizotinib), the HR was 0·02 (95% CI 0·002-0·14). In patients without brain metastases, one (1%) in the lorlatinib group and 25 (23%) in the crizotinib group had intracranial progression. Grade 3-4 adverse events occurred in 113 (76%) of 149 patients (most commonly due to altered lipid levels) with lorlatinib and in 81 (57%) of 142 patients with crizotinib. Adverse events led to treatment discontinuation in 11 (7%) patients in the lorlatinib group and 14 (10%) patients in the crizotinib group. There were no new safety signals.\n\nInterpretation: These updated, long-term data from CROWN show the durable benefit of lorlatinib over crizotinib in patients with treatment-naive, ALK-positive non-small-cell lung cancer and support the use of first-line lorlatinib in patients with and without baseline brain metastases.\n\nFunding: Pfizer.\n\nIndexed on Europe PMC as PubMed record 36535300 (DOI 10.1016/s2213-2600(22)00437-4). Its abstract cites the registry id NCT03052608, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2023, doi: "10.1016/s2213-2600(22)00437-4", pmid: "36535300", authors: "Solomon BJ, Bauer TM, Mok TSK, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CROWN trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Respir Med 2023","url":"https://doi.org/10.1016/s2213-2600(22)00437-4"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36535300/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36535300"},{"label":"ClinicalTrials.gov NCT03052608","url":"https://clinicaltrials.gov/study/NCT03052608"}], tags: ["europepmc-ingest"], trials: ["crown"] }),
  p({ id: "paper-destiny-lung02-j-thorac-oncol-2025", name: "Final Analysis Results and Patient-Reported Outcomes From DESTINY-Lung02-A Dose-Blinded, Randomized, Phase 2 Study of Trastuzumab Deruxtecan in Patients With HER2-Mutant Metastatic NSCLC", tldr: "Published report from the DESTINY-Lung02 trial registered as NCT04644237, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Trastuzumab deruxtecan (T-DXd) demonstrated strong and durable responses in patients with previously treated HER2 (ERBB2) mutant (HER2m) metastatic NSCLC (mNSCLC) in the DESTINY-Lung02 primary analysis (December 23, 2022, data cutoff). This final analysis evaluated T-DXd efficacy and safety after 8 additional months of follow-up, including clinically relevant subgroups and patient-reported outcomes.\n\nMethods: DESTINY-Lung02 was a randomized, dose-blinded, multicenter, phase 2 trial. Patients with previously treated HER2m mNSCLC were randomized 2:1 to receive T-DXd 5.4 or 6.4 mg/kg once every 3 weeks. Primary end point was confirmed objective response rate by blinded independent central review.\n\nResults: at August 25, 2023, 102 and 50 patients had received T-DXd 5.4 or 6.4 mg/kg, respectively. Median follow-up (Q1-Q3) was 15.8 (8.2-20.7) months and 16.5 (9.4-20.8) months, respectively. Confirmed objective response rate (95% confidence interval) was 50.0% (51/102; 39.9%-60.1%) and 56.0% (28/50; 41.3%-70.0%), respectively. Safety profile was acceptable and generally manageable. Accordingly, median treatment duration (Q1-Q3) was 7.7 (3.7-14.4) months and 8.3 (2.8-13.1) months; drug-related grade 3 or higher treatment-emergent adverse events occurred in 39.6% (40/101) and 60.0% (30/50), with nausea most common (67.3% [68/101], 82.0% [41/50]). Adjudicated drug-related interstitial lung disease occurred in 14.9% (15/101) and 32.0% (16/50), mostly grade 1 or 2 with one grade 5 in each arm. Health-related quality of life was preserved for the duration of T-DXd treatment while sample size was sufficient for analysis, with no adverse effects on health-related quality of life observed at either dose.\n\nConclusions: T-DXd demonstrated strong and durable responses at both doses, with no clinically significant changes in toxicity. The approved 5.4-mg/kg dose demonstrated a more favorable benefit-risk profile, including lower adjudicated drug-related interstitial lung disease incidence.\n\nGov identifier: NCT04644237.\n\nIndexed on Europe PMC as PubMed record 40749900 (DOI 10.1016/j.jtho.2025.07.129). Its abstract cites the registry id NCT04644237, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2025.07.129", pmid: "40749900", authors: "Jänne PA, Goto Y, Kubo T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04644237 with the most citations, so it is the natural first reading for anyone following the DESTINY-Lung02 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2025.07.129"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40749900/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40749900"},{"label":"ClinicalTrials.gov NCT04644237","url":"https://clinicaltrials.gov/study/NCT04644237"}], tags: ["europepmc-ingest"], trials: ["destiny-lung02"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-empower-lung-1-lancet-2021", name: "Cemiplimab monotherapy for first-line treatment of advanced non-small-cell lung cancer with PD-L1 of at least 50%: a multicentre, open-label, global, phase 3, randomised, controlled trial", tldr: "Published report from the EMPOWER-Lung 1 trial registered as NCT03088540, in The Lancet (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: We aimed to examine cemiplimab, a programmed cell death 1 inhibitor, in the first-line treatment of advanced non-small-cell lung cancer with programmed cell death ligand 1 (PD-L1) of at least 50%.\n\nMethods: In EMPOWER-Lung 1, a multicentre, open-label, global, phase 3 study, eligible patients recruited in 138 clinics from 24 countries (aged ≥18 years with histologically or cytologically confirmed advanced non-small-cell lung cancer, an Eastern Cooperative Oncology Group performance status of 0-1; never-smokers were ineligible) were randomly assigned (1:1) to cemiplimab 350 mg every 3 weeks or platinum-doublet chemotherapy. Crossover from chemotherapy to cemiplimab was allowed following disease progression. Primary endpoints were overall survival and progression-free survival per masked independent review committee. Primary endpoints were assessed in the intention-to-treat population and in a prespecified PD-L1 of at least 50% population (per US Food and Drug Administration request to the sponsor), which consisted of patients with PD-L1 of at least 50% per 22C3 assay done according to instructions for use. Adverse events were assessed in all patients who received at least one dose of the assigned treatment. This study is registered with ClinicalTrials.gov, NCT03088540 and is ongoing.\n\nFindings: Between June 27, 2017 and Feb 27, 2020, 710 patients were randomly assigned (intention-to-treat population). In the PD-L1 of at least 50% population, which consisted of 563 patients, median overall survival was not reached (95% CI 17·9-not evaluable) with cemiplimab (n=283) versus 14·2 months (11·2-17·5) with chemotherapy (n=280; hazard ratio [HR] 0·57 [0·42-0·77]; p=0·0002). Median progression-free survival was 8·2 months (6·1-8·8) with cemiplimab versus 5·7 months (4·5-6·2) with chemotherapy (HR 0·54 [0·43-0·68]; p<0·0001). Significant improvements in overall survival and progression-free survival were also observed with cemiplimab in the intention-to-treat population despite a high crossover rate (74%). Grade 3-4 treatment-emergent adverse events occurred in 98 (28%) of 355 patients treated with cemiplimab and 135 (39%) of 342 patients treated with chemotherapy.\n\nInterpretation: Cemiplimab monotherapy significantly improved overall survival and progression-free survival compared with chemotherapy in patients with advanced non-small-cell lung cancer with PD-L1 of at least 50%, providing a potential new treatment option for this patient population.\n\nFunding: Regeneron Pharmaceuticals and Sanofi.\n\nIndexed on Europe PMC as PubMed record 33581821 (DOI 10.1016/s0140-6736(21)00228-2). Its abstract cites the registry id NCT03088540, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2021, doi: "10.1016/s0140-6736(21)00228-2", pmid: "33581821", authors: "Sezer A, Kilickap S, Gümüş M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03088540 with the most citations, so it is the natural first reading for anyone following the EMPOWER-Lung 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2021","url":"https://doi.org/10.1016/s0140-6736(21)00228-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33581821/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33581821"},{"label":"ClinicalTrials.gov NCT03088540","url":"https://clinicaltrials.gov/study/NCT03088540"}], tags: ["europepmc-ingest"], trials: ["empower-lung-1"], journals: ["lancet"] }),
  p({ id: "paper-empower-lung-1-lancet-oncol-2023-update", name: "First-line cemiplimab monotherapy and continued cemiplimab beyond progression plus chemotherapy for advanced non-small-cell lung cancer with PD-L1 50% or more (EMPOWER-Lung 1): 35-month follow-up from a mutlicentre, open-label, randomised, phase 3 trial", tldr: "Later report from the EMPOWER-Lung 1 trial registered as NCT03088540, in The Lancet Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Background: Cemiplimab provided significant survival benefit to patients with advanced non-small-cell lung cancer with PD-L1 tumour expression of at least 50% and no actionable biomarkers at 1-year follow-up. In this exploratory analysis, we provide outcomes after 35 months' follow-up and the effect of adding chemotherapy to cemiplimab at the time of disease progression.\n\nMethods: EMPOWER-Lung 1 was a multicentre, open-label, randomised, phase 3 trial. We enrolled patients (aged ≥18 years) with histologically confirmed squamous or non-squamous advanced non-small-cell lung cancer with PD-L1 tumour expression of 50% or more. We randomly assigned (1:1) patients to intravenous cemiplimab 350 mg every 3 weeks for up to 108 weeks, or until disease progression, or investigator's choice of chemotherapy. Central randomisation scheme generated by an interactive web response system governed the randomisation process that was stratified by histology and geographical region. Primary endpoints were overall survival and progression free survival, as assessed by a blinded independent central review (BICR) per Response Evaluation Criteria in Solid Tumours version 1.1. Patients with disease progression on cemiplimab could continue cemiplimab with the addition of up to four cycles of chemotherapy. We assessed response in these patients by BICR against a new baseline, defined as the last scan before chemotherapy initiation. The primary endpoints were assessed in all randomly assigned participants (ie, intention-to-treat population) and in those with a PD-L1 expression of at least 50%. We assessed adverse events in all patients who received at least one dose of their assigned treatment. This trial is registered with ClinicalTrials.gov, NCT03088540.\n\nFindings: Between May 29, 2017, and March 4, 2020, we recruited 712 patients (607 [85%] were male and 105 [15%] were female). We randomly assigned 357 (50%) to cemiplimab and 355 (50%) to chemotherapy. 284 (50%) patients assigned to cemiplimab and 281 (50%) assigned to chemotherapy had verified PD-L1 expression of at least 50%. At 35 months' follow-up, among those with a verified PD-L1 expression of at least 50% median overall survival in the cemiplimab group was 26·1 months (95% CI 22·1-31·8; 149 [52%] of 284 died) versus 13·3 months (10·5-16·2; 188 [67%] of 281 died) in the chemotherapy group (hazard ratio [HR] 0·57, 95% CI 0·46-0·71; p<0·0001), median progression-free survival was 8·1 months (95% CI 6·2-8·8; 214 events occurred) in the cemiplimab group versus 5·3 months (4·3-6·1; 236 events occurred) in the chemotherapy group (HR 0·51, 95% CI 0·42-0·62; p<0·0001). Continued cemiplimab plus chemotherapy as second-line therapy (n=64) resulted in a median progression-free survival of 6·6 months (6·1-9·3) and overall survival of 15·1 months (11·3-18·7). The most common grade 3-4 treatment-emergent adverse events were anaemia (15 [4%] of 356 patients in the cemiplimab group vs 60 [17%] of 343 in the control group), neutropenia (three [1%] vs 35 [10%]), and pneumonia (18 [5%] vs 13 [4%]). Treatment-related deaths occurred in ten (3%) of 356 patients treated with cemiplimab (due to autoimmune myocarditis, cardiac failure, cardio-respiratory arrest, cardiopulmonary failure, septic shock, tumour hyperprogression, nephritis, respiratory failure, [n=1 each] and general disorders or unknown [n=2]) and in seven (2%) of 343 patients treated with chemotherapy (due to pneumonia and pulmonary embolism [n=2 each], and cardiac arrest, lung abscess, and myocardial infarction [n=1 each]). The safety profile of cemiplimab at 35 months, and of continued cemiplimab plus chemotherapy, was generally consistent with that previously observed for these treatments, with no new safety signals INTERPRETATION: At 35 months' follow-up, the survival benefit of cemiplimab for patients with advanced non-small-cell lung cancer was at least as pronounced as at 1 year, affirming its use as first-line monotherapy for this population. Adding chemotherapy to cemiplimab at progression might provide a new second-line treatment for patients with advanced non-small-cell lung cancer.\n\nFunding: Regeneron Pharmaceuticals and Sanofi.\n\nIndexed on Europe PMC as PubMed record 37591293 (DOI 10.1016/s1470-2045(23)00329-7). Its abstract cites the registry id NCT03088540, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2023, doi: "10.1016/s1470-2045(23)00329-7", pmid: "37591293", authors: "Özgüroğlu M, Kilickap S, Sezer A, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the EMPOWER-Lung 1 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2023","url":"https://doi.org/10.1016/s1470-2045(23)00329-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37591293/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37591293"},{"label":"ClinicalTrials.gov NCT03088540","url":"https://clinicaltrials.gov/study/NCT03088540"}], tags: ["europepmc-ingest"], trials: ["empower-lung-1"], journals: ["lancet-oncology"] }),
  p({ id: "paper-furlong-lancet-respir-med-2022", name: "Furmonertinib (AST2818) versus gefitinib as first-line therapy for Chinese patients with locally advanced or metastatic EGFR mutation-positive non-small-cell lung cancer (FURLONG): a multicentre, double-blind, randomised phase 3 study", tldr: "Published report from the FURLONG trial registered as NCT03787992, in The Lancet. Respiratory medicine (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Furmonertinib (AST2818) is an irreversible, selective, third-generation EGFR tyrosine-kinase inhibitor. We aimed to investigate the efficacy and safety of furmonertinib versus the first-generation EGFR tyrosine-kinase inhibitor gefitinib as first-line treatment in patients with EGFR mutation-positive locally advanced or metastatic non-small-cell lung cancer (NSCLC).\n\nMethods: The FURLONG study is a multicentre, double-blind, randomised, phase 3 study done in 55 hospitals across mainland China. We enrolled patients who were aged 18 years or older and had histologically confirmed, locally advanced or metastatic, stage IIIB, IIIC, or IV unresectable NSCLC with EGFR exon 19 deletions or exon 21 Leu858Arg mutation on tissue biopsy confirmed by a central laboratory. Eligible patients were stratified according to EGFR mutation (exon 19 deletions or exon 21 Leu858Arg) and CNS metastases (with or without) and randomly assigned (1:1) to receive either oral furmonertinib (80 mg/day) or oral gefitinib (250 mg/day) in 21-day cycles until disease progression, the occurrence of intolerable toxicities, withdrawal of consent, or other discontinuation reasons judged by the investigators. Investigators, clinicians, participants, independent review centre (IRC) members, the sponsor, and those analysing the data were all masked to treatment allocation. The primary endpoint was IRC-assessed progression-free survival and, along with safety, was analysed in the full analysis set, which comprised all randomly assigned patients who had received at least one dose of study drug. This study is registered with ClinicalTrials.gov, NCT03787992, and is ongoing for survival follow-up.\n\nFindings: Between May 30, 2019, and Dec 5, 2019, 750 patients were screened, of whom 358 were randomly assigned to receive either furmonertinib and gefitinib-matching placebo (n=178) or gefitinib and furmonertinib-matching placebo (n=180). 178 patients randomly assigned to furmonertinib and 179 patients randomly assigned to gefitinib were treated and were included in the full analysis set. Median follow-up was 21·0 months (IQR 18·0-23·5) in the furmonertinib group and 21·0 months (18·0-23·5) in the gefitinib group. Median IRC-assessed progression-free survival was 20·8 months (95% CI 17·8-23·5) in the furmonertinib group and 11·1 months (9·7-12·5) in the gefitinib group (hazard ratio 0·44, 95% CI 0·34-0·58; p<0·0001). Treatment-related adverse events of a grade 3 or more occurred in 20 (11%) of 178 patients in the furmonertinib group and in 32 (18%) of 179 patients in the gefitinib group. Treatment-related serious adverse events were reported in ten (6%) patients in the furmonertinib group and in 11 (6%) patients in the gefitinib group. Ten (6%) patients in the furmonertinib group and three (2%) patients in the gefitinib group died due to adverse events, which were all judged to be possibly unrelated to study treatment by the investigators.\n\nInterpretation: Furmonertinib showed superior efficacy compared with gefitinib as first-line therapy in Chinese patients with EGFR mutation-positive NSCLC, along with an acceptable safety profile without new signals. Furmonertinib is a new potential treatment option for this population.\n\nFunding: Shanghai Allist Pharmaceuticals and the China National Major Project for New Drug Innovation.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 35662408 (DOI 10.1016/s2213-2600(22)00168-0). Its abstract cites the registry id NCT03787992, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2022, doi: "10.1016/s2213-2600(22)00168-0", pmid: "35662408", authors: "Shi Y, Chen G, Wang X, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03787992 with the most citations, so it is the natural first reading for anyone following the FURLONG trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2022","url":"https://doi.org/10.1016/s2213-2600(22)00168-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35662408/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35662408"},{"label":"ClinicalTrials.gov NCT03787992","url":"https://clinicaltrials.gov/study/NCT03787992"}], tags: ["europepmc-ingest"], trials: ["furlong"] }),
  p({ id: "paper-gemstone-302-lancet-oncol-2022", name: "Sugemalimab versus placebo, in combination with platinum-based chemotherapy, as first-line treatment of metastatic non-small-cell lung cancer (GEMSTONE-302): interim and final analyses of a double-blind, randomised, phase 3 clinical trial", tldr: "Published report from the GEMSTONE-302 trial registered as NCT03789604, in The Lancet Oncology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: PD-1 inhibitor plus chemotherapy had been shown to be an effective first-line treatment for patients with metastatic non-small-cell lung cancer (NSCLC). However, there was no robust evidence showing a PD-L1 inhibitor combined with chemotherapy benefited patients with squamous and non-squamous NSCLC. GEMSTONE-302 aimed to evaluate the efficacy and safety of a PD-L1 inhibitor, sugemalimab, plus chemotherapy for patients with metastatic squamous or non-squamous NSCLC.\n\nMethods: This randomised, double-blind, phase 3 trial was done in 35 hospitals and academic research centres in China. Eligible patients were aged 18-75 years, had histologically or cytologically confirmed stage IV squamous or non-squamous NSCLC without known EGFR sensitising mutations, ALK, ROS1, or RET fusions, no previous systemic treatment for metastatic disease, and an Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1. Patients were randomly assigned (2:1) to receive sugemalimab (1200 mg, intravenously, every 3 weeks) plus platinum-based chemotherapy (carboplatin [area under the curve (AUC) 5 mg/mL per min, intravenously] and paclitaxel [175 mg/m 2, intravenously] for squamous NSCLC, or carboplatin [AUC 5 mg/mL per min, intravenously] and pemetrexed [500 mg/m 2, intravenously] for non-squamous NSCLC; sugemalimab group) or placebo plus the same platinum-based chemotherapy regimens for squamous or non-squamous NSCLC as in the sugemalimab group; placebo group) for up to four cycles, followed by maintenance therapy with sugemalimab or placebo for squamous NSCLC, and intravenous sugemalimab 500 mg/m 2 or matching placebo plus pemetrexed for non-squamous NSCLC. Randomisation was done by an interactive voice-web-response system via permuted blocks (block size was a mixture of three and six with a random order within each stratum) and stratified by ECOG performance status, PD-L1 expression, and tumour pathology. The investigators, patients, and the sponsor were masked to treatment assignment. The primary endpoint was investigator-assessed progression-free survival in the intention-to-treat population. Safety was analysed in all patients who received at least one treatment dose. Results reported are from a prespecified interim analysis (ie, when the study met the primary endpoint) and an updated analysis (prespecified final analysis for progression-free survival) with a longer follow-up. This study is registered with ClinicalTrials.gov (NCT03789604), is closed to new participants, and follow-up is ongoing.\n\nFindings: Between Dec 13, 2018, and May 15, 2020, 846 patients were assessed for eligibility; 367 were ineligible, and the remaining 479 patients were randomly assigned to the sugemalimab group (n=320) or placebo group (n=159). At the preplanned interim analysis (data cutoff June 8, 2020; median follow-up 8·6 months [IQR 6·1-11·4]), GEMSTONE-302 met its primary endpoint, with significantly longer progression-free survival in the sugemalimab group compared with the placebo group (median 7·8 months [95% CI 6·9-9·0] vs 4·9 months [4·7-5·0]; stratified hazard ratio [HR] 0·50 [95% CI 0·39-0·64], p<0·0001]). At the final analysis (March 15, 2021) with a median follow-up of 17·8 months (IQR 15·1-20·9), the improvement in progression-free survival was maintained (median 9·0 months [95% CI 7·4-10·8] vs 4·9 months [4·8-5·1]; stratified HR 0·48 [95% CI 0·39-0·60], p<0·0001). The most common grade 3 or 4 any treatment-related adverse events were neutrophil count decreased (104 [33%] of 320 with sugemalimab vs 52 [33%] of 159 with placebo), white blood cell count decreased (45 [14%] vs 27 [17%]), anaemia (43 [13%] vs 18 [11%]), platelet count decreased (33 [10%] vs 15 [9%]), and neutropenia (12 [4%] vs seven [4%]). Any treatment-related serious adverse events occurred in 73 (23%) patients in the sugemalimab group and 31 (20%) patients in the placebo group. Any treatment-related deaths were reported in ten (3%) patients in the sugemalimab group (pneumonia with respiratory failure in one patient; myelosuppression with septic shock in one patient; pneumonia in two patients; respiratory failure, abdominal pain, cardiac failure, and immune-mediated pneumonitis in one patient each; the other two deaths had an unspecified cause) and in two (1%) patients in the placebo group (pneumonia and multiple organ dysfunction syndrome).\n\nInterpretation: Sugemalimab plus chemotherapy showed a statistically significant and clinically meaningful progression-free survival improvement compared with placebo plus chemotherapy, in patients with previously untreated squamous and non-squamous metastatic NSCLC, regardless of PD-L1 expression, and could be a newfirst-line treatment option for both squamous and non-squamous metastatic NSCLC.\n\nFunding: CStone Pharmaceuticals.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 35038432 (DOI 10.1016/s1470-2045(21)00650-1). Its abstract cites the registry id NCT03789604, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2022, doi: "10.1016/s1470-2045(21)00650-1", pmid: "35038432", authors: "Zhou C, Wang Z, Sun Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03789604 with the most citations, so it is the natural first reading for anyone following the GEMSTONE-302 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2022","url":"https://doi.org/10.1016/s1470-2045(21)00650-1"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35038432/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35038432"},{"label":"ClinicalTrials.gov NCT03789604","url":"https://clinicaltrials.gov/study/NCT03789604"}], tags: ["europepmc-ingest"], trials: ["gemstone-302"], journals: ["lancet-oncology"] }),
  p({ id: "paper-gemstone-302-nat-cancer-2023-update", name: "Interim survival analysis of the randomized phase III GEMSTONE-302 trial: sugemalimab or placebo plus chemotherapy as first-line treatment for metastatic NSCLC", tldr: "Later report from the GEMSTONE-302 trial registered as NCT03789604, in Nature Cancer (2023); its title describes an updated or longer-term analysis.", summary: "The randomized, double-blinded, multi-center, phase III GEMSTONE-302 ( NCT03789604) study evaluated the efficacy and safety of sugemalimab versus placebo in combination with chemotherapy as first-line treatment for metastatic non-small-cell lung cancer (NSCLC). In this study, 479 treatment-naive patients with stage IV squamous or non-squamous NSCLC without known EGFR sensitizing mutations, ALK, ROS1 or RET fusions were randomized (2:1) to receive 1,200 mg of sugemalimab (n = 320) or placebo (n = 159) every 3 weeks in combination with platinum-based chemotherapy for up to four cycles, followed by maintenance therapy with sugemalimab or placebo for squamous NSCLC and sugemalimab or placebo plus pemetrexed for non-squamous NSCLC. Placebo-treated patients could cross over to receive sugemalimab monotherapy on disease progression. The primary endpoint was investigator-assessed progression-free survival (PFS) and the secondary endpoints included overall survival (OS) and objective response rate. Sugemalimab plus chemotherapy has demonstrated significant PFS prolongation in the primary analysis as reported previously. at 22 November 2021, the prespecified interim OS analysis showed significant improvement with the addition of sugemalimab to chemotherapy (median OS = 25.4 versus 16.9 months; hazard ratio = 0.65; 95% confidence interval = 0.50-0.84; P = 0.0008). Sugemalimab plus chemotherapy provided superior PFS and OS compared to placebo plus chemotherapy, supporting the use of sugemalimab as a first-line treatment option for metastatic NSCLC.\n\nIndexed on Europe PMC as PubMed record 37322367 (DOI 10.1038/s43018-023-00578-z). Its abstract cites the registry id NCT03789604, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Cancer", year: 2023, doi: "10.1038/s43018-023-00578-z", pmid: "37322367", authors: "Zhou C, Wang Z, Sun M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the GEMSTONE-302 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Nat Cancer 2023","url":"https://doi.org/10.1038/s43018-023-00578-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37322367/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37322367"},{"label":"ClinicalTrials.gov NCT03789604","url":"https://clinicaltrials.gov/study/NCT03789604"}], tags: ["europepmc-ingest"], trials: ["gemstone-302"], journals: ["nature-cancer"] }),
  p({ id: "paper-geometry-mono-1-lancet-oncol-2024-update", name: "Capmatinib in MET exon 14-mutated non-small-cell lung cancer: final results from the open-label, phase 2 GEOMETRY mono-1 trial", tldr: "Later report from the GEOMETRY mono-1 trial registered as NCT02414139, in The Lancet Oncology (2024); its title describes an updated or longer-term analysis.", summary: "Background: Capmatinib has previously shown activity in treatment-naive and previously treated patients with non-small-cell lung cancer (NSCLC) and a MET exon 14-skipping mutation (METex14). Here, we report the final outcomes from the phase 2 GEOMETRY mono-1 study with an aim to provide further evidence for the activity of capmatinib.\n\nMethods: In this non-randomised, multi-cohort, open-label, phase 2 trial conducted in 152 centres and hospitals in 25 countries, with patients treated in 95 centres in 20 countries, eligible patients (aged ≥18 years) with MET-dysregulated, EGFR wild-type, and ALK rearrangement-negative advanced NSCLC (stage IIIB/IV) and an Eastern Cooperative Oncology Group performance status of 0 or 1 were assigned to cohorts (1a, 1b, 2, 3, 4, 5a, 5b, 6 and 7) based on their MET status (METex14 or MET amplification) and previous therapy lines. Patients received capmatinib (400 mg orally twice daily) in 21-day treatment cycles. The primary endpoint was overall response rate by blinded independent central review per Response Evaluation Criteria in Solid Tumours version 1.1 and was performed on the full analysis set (all patients who received at least one dose of capmatinib). Previous reports of this study had published interim or primary data for cohorts 1-7. Here, we report the final clinical outcomes from all METex14 cohorts (4, 5b, 6, and 7) and safety from all study cohorts (1-7). The trial is registered with ClinicalTrials.gov, NCT02414139, and has been completed.\n\nFindings: Of 373 treated patients enrolled from June 11, 2015, to March 12, 2020, 160 (97 [61%] female) patients had METex14 NSCLC and were enrolled in four cohorts: 60 treatment-naive (cohorts 5b and 7) and 100 previously treated (cohorts 4 and 6). The overall median study follow-up was 46·4 months (IQR 41·8-65·4) for the treatment-naïve patients and 66·9 months (56·7-73·9) for previously treated patients, respectively. Overall responses were recorded in 41 (68%; 95% CI 55·0-79·7) of 60 treatment-naive patients and 44 (44%; 95% CI 34·1-54·3) of 100 previously treated patients. In all 373 treated patients, the most common treatment-related adverse events were peripheral oedema (n=174; 47%), nausea (n=130; 35%), increased blood creatinine (n=78; 21%), and vomiting (n=74; 20%). Grade 3-4 serious adverse events occurred in 164 (44%) patients, dyspnoea being the most common (18 patients [5%]). Treatment-related deaths occurred in four (1%) patients (one each of cardiac arrest, hepatitis, organising pneumonia, and pneumonitis). No new safety signals were reported.\n\nInterpretation: These long-term results support METex14 as a targetable oncogenic driver in NSCLC and add to the evidence supporting capmatinib as a targeted treatment option for treatment-naive and previously treated patients with METex14 NSCLC.\n\nFunding: Novartis Pharmaceuticals.\n\nIndexed on Europe PMC as PubMed record 39362249 (DOI 10.1016/s1470-2045(24)00441-8). Its abstract cites the registry id NCT02414139, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2024, doi: "10.1016/s1470-2045(24)00441-8", pmid: "39362249", authors: "Wolf J, Hochmair M, Han JY, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the GEOMETRY mono-1 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2024","url":"https://doi.org/10.1016/s1470-2045(24)00441-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39362249/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39362249"},{"label":"ClinicalTrials.gov NCT02414139","url":"https://clinicaltrials.gov/study/NCT02414139"}], tags: ["europepmc-ingest"], trials: ["geometry-mono-1"], journals: ["lancet-oncology"] }),
  p({ id: "paper-harmoni-a-jama-2024", name: "Ivonescimab Plus Chemotherapy in Non-Small Cell Lung Cancer With EGFR Variant: A Randomized Clinical Trial", tldr: "Published report from the HARMONi-A trial registered as NCT05184712, in JAMA (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: For patients with non-small cell lung cancer whose disease progressed while receiving EGFR tyrosine kinase inhibitor (EGFR-TKI) therapy, particularly third-generation TKIs, optimal treatment options remain limited.\n\nObjective: To compare the efficacy of ivonescimab plus chemotherapy with chemotherapy alone for patients with relapsed advanced or metastatic non-small cell lung cancer with the epidermal growth factor receptor (EGFR) variant.\n\nDesign, setting, and participants: Double-blind, placebo-controlled, randomized, phase 3 trial at 55 sites in China enrolled participants from January 2022 to November 2022; a total of 322 eligible patients were enrolled.\n\nInterventions: Participants received ivonescimab (n = 161) or placebo (n = 161) plus pemetrexed and carboplatin once every 3 weeks for 4 cycles, followed by maintenance therapy of ivonescimab plus pemetrexed or placebo plus pemetrexed.\n\nMain outcomes and measures: The primary end point was progression-free survival in the intention-to-treat population assessed by an independent radiographic review committee (IRRC) per Response Evaluation Criteria in Solid Tumors version 1.1. The results of the first planned interim analysis are reported.\n\nResults: Among 322 enrolled patients in the ivonescimab and placebo groups, the median age was 59.6 vs 59.4 years and 52.2% vs 50.9% of patients were female. at March 10, 2023, median follow-up time was 7.89 months. Median progression-free survival was 7.1 (95% CI, 5.9-8.7) months in the ivonescimab group vs 4.8 (95% CI, 4.2-5.6) months for placebo (difference, 2.3 months; hazard ratio [HR], 0.46 [95% CI, 0.34-0.62]; P <.001). The prespecified subgroup analysis showed progression-free survival benefit favoring patients receiving ivonescimab over placebo across almost all subgroups, including patients whose disease progressed while receiving third-generation EGFR-TKI therapy (HR, 0.48 [95% CI 0.35-0.66]) and those with brain metastases (HR, 0.40 [95% CI, 0.22-0.73]). The objective response rate was 50.6% (95% CI, 42.6%-58.6%) with ivonescimab and 35.4% (95% CI, 28.0%-43.3%) with placebo (difference, 15.6% [95% CI, 5.3%-26.0%]; P =.006). The median overall survival data were not mature; at data cutoff, 69 patients (21.4%) had died. Grade 3 or higher treatment-emergent adverse events occurred in 99 patients (61.5%) in the ivonescimab group vs 79 patients (49.1%) in the placebo group, the most common of which were chemotherapy-related. Grade 3 or higher immune-related adverse events occurred in 10 patients (6.2%) in the ivonescimab group vs 4 (2.5%) in the placebo group. Grade 3 or higher vascular endothelial growth factor-related adverse events occurred in 5 patients (3.1%) in the ivonescimab group vs 4 (2.5%) in the placebo group.\n\nConclusions: Ivonescimab plus chemotherapy significantly improved progression-free survival with tolerable safety profile in TKI-treated non-small cell lung cancer.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT05184712.\n\nIndexed on Europe PMC as PubMed record 38820549 (DOI 10.1001/jama.2024.10613). Its abstract cites the registry id NCT05184712, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2024, doi: "10.1001/jama.2024.10613", pmid: "38820549", authors: "HARMONi-A Study Investigators, Fang W, Zhao Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05184712 with the most citations, so it is the natural first reading for anyone following the HARMONi-A trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2024","url":"https://doi.org/10.1001/jama.2024.10613"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38820549/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38820549"},{"label":"ClinicalTrials.gov NCT05184712","url":"https://clinicaltrials.gov/study/NCT05184712"}], tags: ["europepmc-ingest"], trials: ["harmoni-a"], journals: ["jama"] }),
  p({ id: "paper-imforte-lancet-2025", name: "Efficacy and safety of first-line maintenance therapy with lurbinectedin plus atezolizumab in extensive-stage small-cell lung cancer (IMforte): a randomised, multicentre, open-label, phase 3 trial", tldr: "Published report from the IMforte trial registered as NCT05091567, in The Lancet (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Despite improved efficacy with first-line immune checkpoint inhibitors plus platinum-based chemotherapy for extensive-stage small-cell lung cancer (ES-SCLC), survival remains poor. In this study, we aimed to compare lurbinectedin plus atezolizumab and atezolizumab alone as maintenance therapies in patients with ES-SCLC without progression after induction therapy with atezolizumab, carboplatin, and etoposide.\n\nMethods: IMforte was a randomised, open-label, phase 3 trial done at 96 hospitals and medical centres in 13 countries (Belgium, Germany, Greece, Hungary, Italy, Mexico, Poland, South Korea, Spain, Taiwan, Türkiye, the UK, and the USA). Eligible patients were aged 18 years or older with treatment-naive ES-SCLC. Patients received four 21-day cycles of induction treatment (atezolizumab, carboplatin, and etoposide). After completing induction treatment, eligible patients without disease progression were randomly assigned (1:1) using permuted blocks (Interactive Voice/Web Response System) to receive maintenance treatment intravenously every 3 weeks with lurbinectedin (3·2 mg/m 2; with granulocyte colony-stimulating factor prophylaxis) plus atezolizumab (1200 mg) or atezolizumab (1200 mg). The two primary endpoints were independent review facility-assessed (IRF) progression-free survival and overall survival, measured from randomisation into the maintenance phase. Efficacy endpoints were assessed in the full analysis set, which included all patients who were randomly assigned to maintenance phase treatment, regardless of whether they received their assigned study treatment. Safety was assessed in all patients who received at least one dose of lurbinectedin or atezolizumab, and was analysed according to the treatment received. This study is registered with ClinicalTrials.gov, NCT05091567, and is closed for recruitment.\n\nFindings: Between Nov 17, 2021, and Jan 11, 2024, 895 patients were screened for enrolment, of whom 660 (74%) were enrolled into the induction phase. Between May 24, 2022, and April 30, 2024, 483 (73%) of 660 patients entered the maintenance phase and were randomly assigned to lurbinectedin plus atezolizumab (n=242) or atezolizumab (n=241). At the data cutoff (July 29, 2024), IRF progression-free survival was longer in the lurbinectedin plus atezolizumab group than the atezolizumab group (stratified hazard ratio [HR] 0·54 [95% CI 0·43-0·67]; p<0·0001), as was overall survival (stratified HR 0·73 [0·57-0·95]; p=0·017). 92 (38%) of 242 patients in the lurbinectedin plus atezolizumab group and 53 (22%) of 240 patients in the atezolizumab group had grade 3-4 adverse events. The most common grade 3-4 events in the lurbinectedin plus atezolizumab group were anaemia (20 [8%] of 242 patients), decreased neutrophil count (18 [7%] patients), and decreased platelet count (18 [7%] patients) and the most common events in the atezolizumab group were hyponatremia (five [2%] of 240 patients), dyspnoea (four [2%] patients), and pneumonia (four [2%] patients). Grade 5 adverse events occurred in 12 (5%) of 242 patients in the lurbinectedin plus atezolizumab group and six (3%) of 240 patients in the atezolizumab group. The incidence of myelosuppressive toxicities (eg, neutropenia and leukopenia) was higher in the lurbinectedin plus atezolizumab group than the atezolizumab group.\n\nInterpretation: IRF progression-free survival and overall survival were longer in the lurbinectedin plus atezolizumab group than the atezolizumab group for patients with ES-SCLC, albeit with a higher incidence of adverse events. Lurbinectedin plus atezolizumab represents a novel therapeutic option for first-line maintenance treatment in this setting.\n\nFunding: F Hoffmann-La Roche and Jazz Pharmaceuticals.\n\nIndexed on Europe PMC as PubMed record 40473449 (DOI 10.1016/s0140-6736(25)01011-6). Its abstract cites the registry id NCT05091567, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2025, doi: "10.1016/s0140-6736(25)01011-6", pmid: "40473449", authors: "Paz-Ares L, Borghaei H, Liu SV, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05091567 with the most citations, so it is the natural first reading for anyone following the IMforte trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2025","url":"https://doi.org/10.1016/s0140-6736(25)01011-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40473449/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40473449"},{"label":"ClinicalTrials.gov NCT05091567","url":"https://clinicaltrials.gov/study/NCT05091567"}], tags: ["europepmc-ingest"], trials: ["imforte"], journals: ["lancet"] }),
  p({ id: "paper-impower133-n-engl-j-med-2018", name: "First-Line Atezolizumab plus Chemotherapy in Extensive-Stage Small-Cell Lung Cancer", tldr: "Published report from the IMpower133 trial registered as NCT02763579, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Enhancing tumor-specific T-cell immunity by inhibiting programmed death ligand 1 (PD-L1)-programmed death 1 (PD-1) signaling has shown promise in the treatment of extensive-stage small-cell lung cancer. Combining checkpoint inhibition with cytotoxic chemotherapy may have a synergistic effect and improve efficacy.\n\nMethods: We conducted this double-blind, placebo-controlled, phase 3 trial to evaluate atezolizumab plus carboplatin and etoposide in patients with extensive-stage small-cell lung cancer who had not previously received treatment. Patients were randomly assigned in a 1:1 ratio to receive carboplatin and etoposide with either atezolizumab or placebo for four 21-day cycles (induction phase), followed by a maintenance phase during which they received either atezolizumab or placebo (according to the previous random assignment) until they had unacceptable toxic effects, disease progression according to Response Evaluation Criteria in Solid Tumors, version 1.1, or no additional clinical benefit. The two primary end points were investigator-assessed progression-free survival and overall survival in the intention-to-treat population.\n\nResults: A total of 201 patients were randomly assigned to the atezolizumab group, and 202 patients to the placebo group. At a median follow-up of 13.9 months, the median overall survival was 12.3 months in the atezolizumab group and 10.3 months in the placebo group (hazard ratio for death, 0.70; 95% confidence interval [CI], 0.54 to 0.91; P=0.007). The median progression-free survival was 5.2 months and 4.3 months, respectively (hazard ratio for disease progression or death, 0.77; 95% CI, 0.62 to 0.96; P=0.02). The safety profile of atezolizumab plus carboplatin and etoposide was consistent with the previously reported safety profile of the individual agents, with no new findings observed.\n\nConclusions: The addition of atezolizumab to chemotherapy in the first-line treatment of extensive-stage small-cell lung cancer resulted in significantly longer overall survival and progression-free survival than chemotherapy alone. (Funded by F. Hoffmann-La Roche/Genentech; IMpower133 ClinicalTrials.gov number, NCT02763579.).\n\nIndexed on Europe PMC as PubMed record 30280641 (DOI 10.1056/nejmoa1809064). Its abstract cites the registry id NCT02763579, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1809064", pmid: "30280641", authors: "Horn L, Mansfield AS, Szczęsna A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02763579 with the most citations, so it is the natural first reading for anyone following the IMpower133 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1809064"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30280641/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30280641"},{"label":"ClinicalTrials.gov NCT02763579","url":"https://clinicaltrials.gov/study/NCT02763579"}], tags: ["europepmc-ingest"], trials: ["impower133"], journals: ["nejm"] }),
  p({ id: "paper-keynote-024-189-j-clin-oncol-2021-update", name: "Five-Year Outcomes With Pembrolizumab Versus Chemotherapy for Metastatic Non-Small-Cell Lung Cancer With PD-L1 Tumor Proportion Score ≥ 50", tldr: "Later report from the KEYNOTE-024 trial registered as NCT02142738, in Journal of Clinical Oncology (2021); its title describes an updated or longer-term analysis.", summary: "Purpose: We report the first 5-year follow-up of any first-line phase III immunotherapy trial for non-small-cell lung cancer (NSCLC). KEYNOTE-024 (ClinicalTrials.gov identifier: NCT02142738) is an open-label, randomized controlled trial of pembrolizumab compared with platinum-based chemotherapy in patients with previously untreated NSCLC with a programmed death ligand-1 (PD-L1) tumor proportion score of at least 50% and no sensitizing EGFR or ALK alterations. Previous analyses showed pembrolizumab significantly improved progression-free survival and overall survival (OS).\n\nMethods: Eligible patients were randomly assigned (1:1) to pembrolizumab (200 mg once every 3 weeks for up to 35 cycles) or platinum-based chemotherapy. Patients in the chemotherapy group with progressive disease could cross over to pembrolizumab. The primary end point was progression-free survival; OS was a secondary end point.\n\nResults: Three hundred five patients were randomly assigned: 154 to pembrolizumab and 151 to chemotherapy. Median (range) time from randomization to data cutoff (June 1, 2020) was 59.9 (55.1-68.4) months. Among patients initially assigned to chemotherapy, 99 received subsequent anti-PD-1 or PD-L1 therapy, representing a 66.0% effective crossover rate. Median OS was 26.3 months (95% CI, 18.3 to 40.4) for pembrolizumab and 13.4 months (9.4-18.3) for chemotherapy (hazard ratio, 0.62; 95% CI, 0.48 to 0.81). Kaplan-Meier estimates of the 5-year OS rate were 31.9% for the pembrolizumab group and 16.3% for the chemotherapy group. Thirty-nine patients received 35 cycles (ie, approximately 2 years) of pembrolizumab, 82.1% of whom were still alive at data cutoff (approximately 5 years). Toxicity did not increase with longer treatment exposure.\n\nConclusion: Pembrolizumab provides a durable, clinically meaningful long-term OS benefit versus chemotherapy as first-line therapy for metastatic NSCLC with PD-L1 tumor proportion score of at least 50%.\n\nIndexed on Europe PMC as PubMed record 33872070 (DOI 10.1200/jco.21.00174). Its abstract cites the registry id NCT02142738, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2021, doi: "10.1200/jco.21.00174", pmid: "33872070", authors: "Reck M, Rodríguez-Abreu D, Robinson AG, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-024 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2021","url":"https://doi.org/10.1200/jco.21.00174"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33872070/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33872070"},{"label":"ClinicalTrials.gov NCT02142738","url":"https://clinicaltrials.gov/study/NCT02142738"}], tags: ["europepmc-ingest"], trials: ["keynote-024-189"], journals: ["jco"] }),
  p({ id: "paper-keynote-042-lancet-2019", name: "Pembrolizumab versus chemotherapy for previously untreated, PD-L1-expressing, locally advanced or metastatic non-small-cell lung cancer (KEYNOTE-042): a randomised, open-label, controlled, phase 3 trial", tldr: "Published report from the KEYNOTE-042 trial registered as NCT02220894, in The Lancet (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: First-line pembrolizumab monotherapy improves overall and progression-free survival in patients with untreated metastatic non-small-cell lung cancer with a programmed death ligand 1 (PD-L1) tumour proportion score (TPS) of 50% or greater. We investigated overall survival after treatment with pembrolizumab monotherapy in patients with a PD-L1 TPS of 1% or greater.\n\nMethods: This randomised, open-label, phase 3 study was done in 213 medical centres in 32 countries. Eligible patients were adults (≥18 years) with previously untreated locally advanced or metastatic non-small-cell lung cancer without a sensitising EGFR mutation or ALK translocation and with an Eastern Cooperative Oncology Group (ECOG) performance status score of 0 or 1, life expectancy 3 months or longer, and a PD-L1 TPS of 1% or greater. Randomisation was computer generated, accessed via an interactive voice-response and integrated web-response system, and stratified by region of enrolment (east Asia vs rest of world), ECOG performance status score (0 vs 1), histology (squamous vs non-squamous), and PD-L1 TPS (≥50% vs 1-49%). Enrolled patients were randomly assigned 1:1 in blocks of four per stratum to receive pembrolizumab 200 mg every 3 weeks for up to 35 cycles or the investigator's choice of platinum-based chemotherapy for four to six cycles. Primary endpoints were overall survival in patients with a TPS of 50% or greater, 20% or greater, and 1% or greater (one-sided significance thresholds, p=0·0122, p=0·0120, and p=0·0124, respectively) in the intention-to-treat population, assessed sequentially if the previous findings were significant. This study is registered at ClinicalTrials.gov, number NCT02220894.\n\nFindings: From Dec 19, 2014, to March 6, 2017, 1274 patients (902 men, 372 women, median age 63 years [IQR 57-69]) with a PD-L1 TPS of 1% or greater were allocated to pembrolizumab (n=637) or chemotherapy (n=637) and included in the intention-to-treat population. 599 (47%) had a TPS of 50% or greater and 818 patients (64%) had a TPS of 20% or greater. at Feb 26, 2018, median follow-up was 12·8 months. Overall survival was significantly longer in the pembrolizumab group than in the chemotherapy group in all three TPS populations (≥50% hazard ratio 0·69, 95% CI 0·56-0·85, p=0·0003; ≥20% 0·77, 0·64-0·92, p=0·0020, and ≥1% 0·81, 0·71-0·93, p=0·0018). The median surival values by TPS population were 20·0 months (95% CI 15·4-24·9) for pembrolizumab versus 12·2 months (10·4-14·2) for chemotherapy, 17·7 months (15·3-22·1) versus 13·0 months (11·6-15·3), and 16·7 months (13·9-19·7) versus 12·1 months (11·3-13·3), respectively. Treatment-related adverse events of grade 3 or worse occurred in 113 (18%) of 636 treated patients in the pembrolizumab group and in 252 (41%) of 615 in the chemotherapy group and led to death in 13 (2%) and 14 (2%) patients, respectively.\n\nInterpretation: The benefit-to-risk profile suggests that pembrolizumab monotherapy can be extended as first-line therapy to patients with locally advanced or metastatic non-small-cell lung cancer without sensitising EGFR or ALK alterations and with low PD-L1 TPS.\n\nFunding: Merck Sharp & Dohme.\n\nIndexed on Europe PMC as PubMed record 30955977 (DOI 10.1016/s0140-6736(18)32409-7). Its abstract cites the registry id NCT02220894, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2019, doi: "10.1016/s0140-6736(18)32409-7", pmid: "30955977", authors: "Mok TSK, Wu YL, Kudaba I, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02220894 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-042 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2019","url":"https://doi.org/10.1016/s0140-6736(18)32409-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30955977/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30955977"},{"label":"ClinicalTrials.gov NCT02220894","url":"https://clinicaltrials.gov/study/NCT02220894"}], tags: ["europepmc-ingest"], trials: ["keynote-042"], journals: ["lancet"] }),
  p({ id: "paper-keynote-042-j-clin-oncol-2023-update", name: "Five-Year Outcomes With Pembrolizumab Versus Chemotherapy as First-Line Therapy in Patients With Non-Small-Cell Lung Cancer and Programmed Death Ligand-1 Tumor Proportion Score ≥ 1% in the KEYNOTE-042 Study", tldr: "Later report from the KEYNOTE-042 trial registered as NCT02220894, in Journal of Clinical Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Clinical trials frequently include multiple end points that mature at different times. The initial report, typically based on the primary end point, may be published when key planned co-primary or secondary analyses are not yet available. Clinical Trial Updates provide an opportunity to disseminate additional results from studies, published in JCO or elsewhere, for which the primary end point has already been reported. We report 5-year results from the phase III KEYNOTE-042 study (ClinicalTrials.gov identifier: NCT02220894). Eligible patients with locally advanced/metastatic non-small-cell lung cancer (NSCLC) without EGFR/ALK alterations and with programmed death ligand-1 (PD-L1) tumor proportion score (TPS) ≥ 1% received pembrolizumab 200 mg once every 3 weeks for 35 cycles or chemotherapy (carboplatin + paclitaxel or pemetrexed) for 4-6 cycles with optional maintenance pemetrexed. Primary end points were overall survival (OS) in PD-L1 TPS ≥ 50%, ≥ 20%, and ≥ 1% groups. Patients who completed 35 cycles of pembrolizumab with ≥ stable disease could begin second-course pembrolizumab upon progression. One thousand two hundred seventy-four patients were randomly assigned (pembrolizumab, n = 637; chemotherapy, n = 637). Median follow-up time was 61.1 (range, 50.0-76.3) months. OS outcomes favored pembrolizumab ( v chemotherapy) regardless of PD-L1 TPS (hazard ratio [95% CI] for TPS ≥ 50%, 0.68 [0.57 to 0.81]; TPS ≥ 20%, 0.75 [0.64 to 0.87]; TPS ≥ 1%, 0.79 [0.70 to 0.89]), with estimated 5-year OS rates with pembrolizumab of 21.9%, 19.4%, and 16.6%, respectively. No new toxicities were identified. Objective response rate was 84.3% among 102 patients who completed 35 cycles of pembrolizumab and 15.2% among 33 patients who received second-course pembrolizumab. First-line pembrolizumab monotherapy continued to show durable clinical benefit versus chemotherapy after 5 years of follow-up in PD-L1-positive, locally advanced/metastatic NSCLC without EGFR/ALK alterations and remains a standard of care.\n\nIndexed on Europe PMC as PubMed record 36306479 (DOI 10.1200/jco.21.02885). Its abstract cites the registry id NCT02220894, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.21.02885", pmid: "36306479", authors: "de Castro G, Kudaba I, Wu YL, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-042 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.21.02885"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36306479/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36306479"},{"label":"ClinicalTrials.gov NCT02220894","url":"https://clinicaltrials.gov/study/NCT02220894"}], tags: ["europepmc-ingest"], trials: ["keynote-042"], journals: ["jco"] }),
  p({ id: "paper-keynote-407-n-engl-j-med-2018", name: "Pembrolizumab plus Chemotherapy for Squamous Non-Small-Cell Lung Cancer", tldr: "Published report from the KEYNOTE-407 trial registered as NCT02775435, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Standard first-line therapy for metastatic, squamous non-small-cell lung cancer (NSCLC) is platinum-based chemotherapy or pembrolizumab (for patients with programmed death ligand 1 [PD-L1] expression on ≥50% of tumor cells). More recently, pembrolizumab plus chemotherapy was shown to significantly prolong overall survival among patients with nonsquamous NSCLC.\n\nMethods: In this double-blind, phase 3 trial, we randomly assigned, in a 1:1 ratio, 559 patients with untreated metastatic, squamous NSCLC to receive 200 mg of pembrolizumab or saline placebo for up to 35 cycles; all the patients also received carboplatin and either paclitaxel or nanoparticle albumin-bound [nab]-paclitaxel for the first 4 cycles. Primary end points were overall survival and progression-free survival.\n\nResults: After a median follow-up of 7.8 months, the median overall survival was 15.9 months (95% confidence interval [CI], 13.2 to not reached) in the pembrolizumab-combination group and 11.3 months (95% CI, 9.5 to 14.8) in the placebo-combination group (hazard ratio for death, 0.64; 95% CI, 0.49 to 0.85; P<0.001). The overall survival benefit was consistent regardless of the level of PD-L1 expression. The median progression-free survival was 6.4 months (95% CI, 6.2 to 8.3) in the pembrolizumab-combination group and 4.8 months (95% CI, 4.3 to 5.7) in the placebo-combination group (hazard ratio for disease progression or death, 0.56; 95% CI, 0.45 to 0.70; P<0.001). Adverse events of grade 3 or higher occurred in 69.8% of the patients in the pembrolizumab-combination group and in 68.2% of the patients in the placebo-combination group. Discontinuation of treatment because of adverse events was more frequent in the pembrolizumab-combination group than in the placebo-combination group (13.3% vs. 6.4%).\n\nConclusions: In patients with previously untreated metastatic, squamous NSCLC, the addition of pembrolizumab to chemotherapy with carboplatin plus paclitaxel or nab-paclitaxel resulted in significantly longer overall survival and progression-free survival than chemotherapy alone. (Funded by Merck Sharp & Dohme; KEYNOTE-407 ClinicalTrials.gov number, NCT02775435.).\n\nIndexed on Europe PMC as PubMed record 30280635 (DOI 10.1056/nejmoa1810865). Its abstract cites the registry id NCT02775435, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1810865", pmid: "30280635", authors: "Paz-Ares L, Luft A, Vicente D, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02775435 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-407 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1810865"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30280635/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30280635"},{"label":"ClinicalTrials.gov NCT02775435","url":"https://clinicaltrials.gov/study/NCT02775435"}], tags: ["europepmc-ingest"], trials: ["keynote-407"], journals: ["nejm"] }),
  p({ id: "paper-keynote-407-j-clin-oncol-2023-update", name: "Pembrolizumab Plus Chemotherapy in Squamous Non-Small-Cell Lung Cancer: 5-Year Update of the Phase III KEYNOTE-407 Study", tldr: "Later report from the KEYNOTE-407 trial registered as NCT02775435, in Journal of Clinical Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Clinical trials frequently include multiple end points that mature at different times. The initial report, typically based on the primary end point, may be published when key planned co-primary or secondary analyses are not yet available. Clinical Trial Updates provide an opportunity to disseminate additional results from studies, published in JCO or elsewhere, for which the primary end point has already been reported. We report 5-year efficacy and safety outcomes from the phase III KEYNOTE-407 study (ClinicalTrials.gov identifier: NCT02775435). Eligible patients with previously untreated, metastatic squamous non-small-cell lung cancer (NSCLC) were randomly assigned 1:1 to pembrolizumab 200 mg or placebo plus carboplatin and paclitaxel/nab-paclitaxel once every 3 weeks for four cycles, followed by pembrolizumab or placebo for up to 35 cycles. Primary end points were overall survival (OS) and progression-free survival (PFS) per RECIST version 1.1 by blinded independent central review (BICR). Five hundred fifty-nine patients were randomly assigned in the intention-to-treat population (pembrolizumab plus chemotherapy, n = 278; placebo plus chemotherapy, n = 281). The median time from random assignment to data cutoff was 56.9 (range, 49.9-66.2) months. OS and PFS were improved with pembrolizumab plus chemotherapy versus placebo plus chemotherapy (hazard ratio [95% CI], 0.71 [0.59 to 0.85] and 0.62 [0.52 to 0.74]), with 5-year OS rates of 18.4% versus 9.7%, respectively. Toxicity was manageable. Among 55 patients who completed 35 cycles of pembrolizumab, the objective response rate was 90.9% and the 3-year OS rate after completion of 35 cycles (approximately 5 years after random assignment) was 69.5%. Pembrolizumab plus chemotherapy maintained an OS and PFS benefit versus placebo plus chemotherapy in previously untreated, metastatic squamous NSCLC and is a standard-of-care first-line treatment option for metastatic squamous NSCLC regardless of programmed death ligand 1 expression.\n\nIndexed on Europe PMC as PubMed record 36735893 (DOI 10.1200/jco.22.01990). Its abstract cites the registry id NCT02775435, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.22.01990", pmid: "36735893", authors: "Novello S, Kowalski DM, Luft A, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-407 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.22.01990"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36735893/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36735893"},{"label":"ClinicalTrials.gov NCT02775435","url":"https://clinicaltrials.gov/study/NCT02775435"}], tags: ["europepmc-ingest"], trials: ["keynote-407"], journals: ["jco"] }),
  p({ id: "paper-keynote-671-n-engl-j-med-2023", name: "Perioperative Pembrolizumab for Early-Stage Non-Small-Cell Lung Cancer", tldr: "Published report from the KEYNOTE-671 trial registered as NCT03425643, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Among patients with resectable early-stage non-small-cell lung cancer (NSCLC), a perioperative approach that includes both neoadjuvant and adjuvant immune checkpoint inhibition may provide benefit beyond either approach alone.\n\nMethods: We conducted a randomized, double-blind, phase 3 trial to evaluate perioperative pembrolizumab in patients with early-stage NSCLC. Participants with resectable stage II, IIIA, or IIIB (N2 stage) NSCLC were assigned in a 1:1 ratio to receive neoadjuvant pembrolizumab (200 mg) or placebo once every 3 weeks, each of which was given with cisplatin-based chemotherapy for 4 cycles, followed by surgery and adjuvant pembrolizumab (200 mg) or placebo once every 3 weeks for up to 13 cycles. The dual primary end points were event-free survival (the time from randomization to the first occurrence of local progression that precluded the planned surgery, unresectable tumor, progression or recurrence, or death) and overall survival. Secondary end points included major pathological response, pathological complete response, and safety.\n\nResults: A total of 397 participants were assigned to the pembrolizumab group, and 400 to the placebo group. At the prespecified first interim analysis, the median follow-up was 25.2 months. Event-free survival at 24 months was 62.4% in the pembrolizumab group and 40.6% in the placebo group (hazard ratio for progression, recurrence, or death, 0.58; 95% confidence interval [CI], 0.46 to 0.72; P<0.001). The estimated 24-month overall survival was 80.9% in the pembrolizumab group and 77.6% in the placebo group (P = 0.02, which did not meet the significance criterion). A major pathological response occurred in 30.2% of the participants in the pembrolizumab group and in 11.0% of those in the placebo group (difference, 19.2 percentage points; 95% CI, 13.9 to 24.7; P<0.0001; threshold, P = 0.0001), and a pathological complete response occurred in 18.1% and 4.0%, respectively (difference, 14.2 percentage points; 95% CI, 10.1 to 18.7; P<0.0001; threshold, P = 0.0001). Across all treatment phases, 44.9% of the participants in the pembrolizumab group and 37.3% of those in the placebo group had treatment-related adverse events of grade 3 or higher, including 1.0% and 0.8%, respectively, who had grade 5 events.\n\nConclusions: Among patients with resectable, early-stage NSCLC, neoadjuvant pembrolizumab plus chemotherapy followed by resection and adjuvant pembrolizumab significantly improved event-free survival, major pathological response, and pathological complete response as compared with neoadjuvant chemotherapy alone followed by surgery. Overall survival did not differ significantly between the groups in this analysis. (Funded by Merck Sharp and Dohme; KEYNOTE-671 ClinicalTrials.gov number, NCT03425643.).\n\nIndexed on Europe PMC as PubMed record 37272513 (DOI 10.1056/nejmoa2302983). Its abstract cites the registry id NCT03425643, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2302983", pmid: "37272513", authors: "Wakelee H, Liberman M, Kato T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03425643 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-671 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2302983"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37272513/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37272513"},{"label":"ClinicalTrials.gov NCT03425643","url":"https://clinicaltrials.gov/study/NCT03425643"}], tags: ["europepmc-ingest"], trials: ["keynote-671"], journals: ["nejm"] }),
  p({ id: "paper-keynote-671-ann-oncol-2026-update", name: "Five-Year Outcomes of Perioperative Pembrolizumab for Early-Stage Non-Small-Cell Lung Cancer From the Randomized KEYNOTE-671 Study", tldr: "Later report from the KEYNOTE-671 trial registered as NCT03425643, in Annals of Oncology (2026); its title describes an updated or longer-term analysis.", summary: "Background: Adding perioperative pembrolizumab to neoadjuvant chemotherapy significantly improved survival outcomes compared with neoadjuvant chemotherapy and surgery alone in participants with early-stage non-small-cell lung cancer (NSCLC) in the phase 3, randomized KEYNOTE-671 study. We report results from KEYNOTE-671 after 5 years of follow-up.\n\nPatients and methods: Eligible participants with previously untreated, resectable stage II, IIIA, or IIIB (N2) NSCLC were randomized 1:1 to 4 cycles of pembrolizumab 200 mg or placebo every 3 weeks, plus platinum-doublet chemotherapy, followed by surgery then adjuvant pembrolizumab or placebo every 3 weeks for up to 13 cycles. Dual primary endpoints were event-free survival (EFS) per RECIST v1.1 by investigator assessment and overall survival (OS).\n\nResults: 797 participants were randomized to pembrolizumab (n=397) or placebo (n=400). Median time from randomization to data cutoff (July 3, 2025) was 60.4 (range, 42.6‒85.8) months. Five-year EFS was 49.9% (95% CI, 44.6‒55.0) in the pembrolizumab arm and 26.5% (95% CI, 21.7‒31.5) in the placebo arm (HR, 0.58; 95% CI, 0.48‒0.69); 5-year OS was 64.6% (95% CI, 59.5‒69.2) and 53.6% (95% CI, 48.3‒58.6), respectively (HR, 0.74; 95% CI, 0.59‒0.92). No detriment to health-related quality of life was identified in the pembrolizumab versus placebo arm with longer follow-up. Safety was consistent with the known profiles of each treatment.\n\nConclusions: After 5 years of follow-up, EFS was nearly double with perioperative pembrolizumab plus neoadjuvant chemotherapy, along with continued improvement in OS compared with neoadjuvant chemotherapy and surgery alone. The durable and clinically meaningful benefits observed support use of this treatment as a standard of care for patients with resectable early-stage NSCLC (ClinicalTrials.gov, NCT03425643).\n\nIndexed on Europe PMC as PubMed record 42628840 (DOI 10.1016/j.annonc.2026.08.005). Its abstract cites the registry id NCT03425643, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2026, doi: "10.1016/j.annonc.2026.08.005", pmid: "42628840", authors: "Wakelee H, Spicer JD, Gao S, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-671 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2026","url":"https://doi.org/10.1016/j.annonc.2026.08.005"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42628840/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42628840"},{"label":"ClinicalTrials.gov NCT03425643","url":"https://clinicaltrials.gov/study/NCT03425643"}], tags: ["europepmc-ingest"], trials: ["keynote-671"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-laura-n-engl-j-med-2024", name: "Osimertinib after Chemoradiotherapy in Stage III EGFR -Mutated NSCLC", tldr: "Published report from the LAURA trial registered as NCT03521154, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Osimertinib is a recommended treatment for advanced non-small-cell lung cancer (NSCLC) with an epidermal growth factor receptor ( EGFR) mutation and as adjuvant treatment for resected EGFR -mutated NSCLC. EGFR tyrosine kinase inhibitors have shown preliminary efficacy in unresectable stage III EGFR -mutated NSCLC.\n\nMethods: In this phase 3, double-blind, placebo-controlled trial, we randomly assigned patients with unresectable EGFR -mutated stage III NSCLC without progression during or after chemoradiotherapy to receive osimertinib or placebo until disease progression occurred (as assessed by blinded independent central review) or the regimen was discontinued. The primary end point was progression-free survival as assessed by blinded independent central review.\n\nResults: A total of 216 patients who had undergone chemoradiotherapy were randomly assigned to receive osimertinib (143 patients) or placebo (73 patients). Osimertinib resulted in a significant progression-free survival benefit as compared with placebo: the median progression-free survival was 39.1 months with osimertinib versus 5.6 months with placebo, with a hazard ratio for disease progression or death of 0.16 (95% confidence interval [CI], 0.10 to 0.24; P<0.001). The percentage of patients who were alive and progression free at 12 months was 74% (95% CI, 65 to 80) with osimertinib and 22% (95% CI, 13 to 32) with placebo. Interim overall survival data (maturity, 20%) showed 36-month overall survival among 84% of patients with osimertinib (95% CI, 75 to 89) and 74% with placebo (95% CI, 57 to 85), with a hazard ratio for death of 0.81 (95% CI, 0.42 to 1.56; P = 0.53). The incidence of adverse events of grade 3 or higher was 35% in the osimertinib group and 12% in the placebo group; radiation pneumonitis (majority grade, 1 to 2) was reported in 48% and 38%, respectively. No new safety concerns emerged.\n\nConclusions: Treatment with osimertinib resulted in significantly longer progression-free survival than placebo in patients with unresectable stage III EGFR -mutated NSCLC. (Funded by AstraZeneca; LAURA ClinicalTrials.gov number, NCT03521154.).\n\nIndexed on Europe PMC as PubMed record 38828946 (DOI 10.1056/nejmoa2402614). Its abstract cites the registry id NCT03521154, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2402614", pmid: "38828946", authors: "Lu S, Kato T, Dong X, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03521154 with the most citations, so it is the natural first reading for anyone following the LAURA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2402614"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38828946/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38828946"},{"label":"ClinicalTrials.gov NCT03521154","url":"https://clinicaltrials.gov/study/NCT03521154"}], tags: ["europepmc-ingest"], trials: ["laura"], journals: ["nejm"] }),
  p({ id: "paper-luminosity-j-clin-oncol-2024", name: "Telisotuzumab Vedotin Monotherapy in Patients With Previously Treated c-Met Protein-Overexpressing Advanced Nonsquamous EGFR -Wildtype Non-Small Cell Lung Cancer in the Phase II LUMINOSITY Trial", tldr: "Published report from the LUMINOSITY trial registered as NCT03539536, in Journal of Clinical Oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Telisotuzumab vedotin (Teliso-V) is a c-Met-directed antibody-drug conjugate with a monomethyl auristatin E cytotoxic payload. The phase II LUMINOSITY trial (ClinicalTrials.gov identifier: NCT03539536) aimed to identify the optimal c-Met protein-overexpressing non-small cell lung cancer (NSCLC) population for treatment with Teliso-V (stage I) and expand the selected group for efficacy evaluation (stage II). Stage II enrolled patients with nonsquamous epidermal growth factor receptor ( EGFR)-wildtype NSCLC.\n\nMethods: Eligible patients had locally advanced/metastatic c-Met protein-overexpressing NSCLC and ≤2 previous lines of therapy (including ≤1 line of systemic chemotherapy). c-Met protein overexpression in nonsquamous EGFR -wildtype NSCLC was defined as ≥25% tumor cells with 3+ staining (high [≥50% 3+]; intermediate [≥25%-<50%]). Teliso-V was administered at 1.9 mg/kg once every 2 weeks. The primary end point was overall response rate (ORR) by independent central review.\n\nResults: In total, 172 patients with nonsquamous EGFR -wildtype NSCLC received Teliso-V in stages I and II. ORR was 28.6% (95% CI, 21.7 to 36.2; c-Met high, 34.6% [95% CI, 24.2 to 46.2]; c-Met intermediate, 22.9% [95% CI, 14.4 to 33.4]). The median duration of response was 8.3 months (95% CI, 5.6 to 11.3; c-Met high, 9.0 [95% CI, 4.2 to 13.0]; c-Met intermediate: 7.2 [95% CI, 5.3 to 11.5]). The median overall survival was 14.5 months (95% CI, 9.9 to 16.6; c-Met high, 14.6 [95% CI, 9.2 to 25.6]; c-Met intermediate, 14.2 [95% CI, 9.6 to 16.6]). The median progression-free survival was 5.7 months (95% CI, 4.6 to 6.9; c-Met high, 5.5 [95% CI, 4.1 to 8.3]; c-Met intermediate: 6.0 [95% CI, 4.5 to 8.1]). Most common any-grade treatment-related adverse events (AEs) were peripheral sensory neuropathy (30%), peripheral edema (16%), and fatigue (14%); the most common grade ≥3 AE was peripheral sensory neuropathy (7%).\n\nConclusion: Teliso-V was associated with durable responses in c-Met protein-overexpressing nonsquamous EGFR -wildtype NSCLC, especially in those with high c-Met. AEs were generally manageable.\n\nIndexed on Europe PMC as PubMed record 38843488 (DOI 10.1200/jco.24.00720). Its abstract cites the registry id NCT03539536, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2024, doi: "10.1200/jco.24.00720", pmid: "38843488", authors: "Camidge DR, Bar J, Horinouchi H, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03539536 with the most citations, so it is the natural first reading for anyone following the LUMINOSITY trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2024","url":"https://doi.org/10.1200/jco.24.00720"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38843488/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38843488"},{"label":"ClinicalTrials.gov NCT03539536","url":"https://clinicaltrials.gov/study/NCT03539536"}], tags: ["europepmc-ingest"], trials: ["luminosity"], journals: ["jco"] }),
  p({ id: "paper-luminosity-jto-clin-res-rep-2026-update", name: "Telisotuzumab Vedotin Monotherapy in Patients With Previously Treated c-Met Protein Overexpressing, Nonsquamous, EGFR Wild-type Advanced NSCLC: Updated Analysis of the LUMINOSITY Trial", tldr: "Later report from the LUMINOSITY trial registered as NCT03539536, in JTO clinical and research reports (2026); its title describes an updated or longer-term analysis.", summary: "Introduction: Telisotuzumab vedotin (Teliso-V) is a c-Met-directed antibody-drug conjugate comprising the monoclonal antibody telisotuzumab and the monomethyl auristatin E payload. Primary analysis of the phase 2 LUMINOSITY trial (NCT03539536) revealed Teliso-V monotherapy 1.9 mg/kg elicited durable responses and had generally manageable safety in patients with locally advanced or metastatic c-Met protein overexpressing, EGFR wild-type, nonsquamous NSCLC. We present updated outcomes with approximately 6 months longer follow-up and explore the impact of previous therapies.\n\nMethods: Patients (≥18 y; had previous therapy including ≤1 chemotherapy) received 1.9 mg/kg Teliso-V every 2 weeks. c-Met protein overexpression (clinical trial assay for MET [SP44] [Roche]) was defined as greater than or equal to 25% tumor cells with 3+ staining intensity (c-Met high: ≥50% 3+; c-Met intermediate: 25 to <50% 3+). Primary end point was the overall response rate by independent central review per the Response Evaluation Criteria in Solid Tumors version 1.1.\n\nResults: at February 21, 2024, 172 patients received at least one dose of Teliso-V; 168 patients (c-Met high, n = 84; c-Met intermediate, n = 84) were evaluable for efficacy. The overall response rate was 29.2% (95% confidence interval [CI]: 22.4-36.7; c-Met high, 34.5% [24.5-45.7]; c-Met intermediate, 23.8% [15.2-34.3]). Median duration of response was 7.2 months (95% CI: 5.5-11.0; c-Met high, 7.2 [95% CI: 4.2-12.0]; c-Met intermediate, 7.2 [95% CI: 4.7-11.5]). Previous therapy (platinum, immune checkpoint inhibitors, or both) did not impact efficacy outcomes. The most common treatment-related adverse event was peripheral sensory neuropathy (any-grade: 31%; grade ≥3: 7%).\n\nConclusions: Teliso-V monotherapy 1.9 mg/kg elicited durable responses, irrespective of the type of previous therapy received, and maintained a manageable safety profile in patients with c-Met protein overexpressing EGFR wild-type, nonsquamous NSCLC.\n\nClinicaltrialsgov id number: NCT03539536.\n\nIndexed on Europe PMC as PubMed record 42368479 (DOI 10.1016/j.jtocrr.2026.100988). Its abstract cites the registry id NCT03539536, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JTO clinical and research reports", year: 2026, doi: "10.1016/j.jtocrr.2026.100988", pmid: "42368479", authors: "Girard N, Goldman J, Lu S, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the LUMINOSITY trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"JTO Clin Res Rep 2026","url":"https://doi.org/10.1016/j.jtocrr.2026.100988"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42368479/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42368479"},{"label":"ClinicalTrials.gov NCT03539536","url":"https://clinicaltrials.gov/study/NCT03539536"}], tags: ["europepmc-ingest"], trials: ["luminosity"] }),
  p({ id: "paper-lung-map-s1400i-jama-oncol-2021", name: "Nivolumab Plus Ipilimumab vs Nivolumab for Previously Treated Patients With Stage IV Squamous Cell Lung Cancer: The Lung-MAP S1400I Phase 3 Randomized Clinical Trial", tldr: "Published report from the S1400I trial registered as NCT02785952, in JAMA Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Nivolumab plus ipilimumab is superior to platinum-based chemotherapy in treatment-naive advanced non-small cell lung cancer (NSCLC). Nivolumab is superior to docetaxel in advanced pretreated NSCLC.\n\nObjective: To determine whether the addition of ipilimumab to nivolumab improves survival in patients with advanced, pretreated, immunotherapy-naive squamous (Sq) NSCLC.\n\nDesign, setting, and participants: The Lung Cancer Master Protocol (Lung-MAP) S1400I phase 3, open-label randomized clinical trial was conducted from December 18, 2015, to April 23, 2018, randomizing patients in a 1:1 ratio to nivolumab alone or combined with ipilimumab. The median follow-up in surviving patients was 29.5 months. The trial was conducted through the National Clinical Trials Network and included patients with advanced immunotherapy-naive SqNSCLC and a Zubrod score of 0 (asymptomatic) to 1 (symptomatic but completely ambulatory) with disease progression after standard platinum-based chemotherapy. Randomization was stratified by sex and number of prior therapies (1 vs 2 or more). Data were analyzed from May 3, 2018, to February 1, 2021.\n\nInterventions: Nivolumab, 3 mg/kg intravenously every 2 weeks, with or without ipilimumab, 1 mg/kg intravenously every 6 weeks, until disease progression or intolerable toxic effects.\n\nMain outcomes and measures: The primary end point was overall survival (OS). Secondary end points included investigator-assessed progression-free survival (IA-PFS) and response per Response Evaluation Criteria in Solid Tumors (RECIST) guidelines, version 1.1.\n\nResults: Of 275 enrolled patients, 252 (mean age, 67.5 years [range 41.8-90.3 years]; 169 men [67%]; 206 White patients [82%]) were deemed eligible (125 randomized to nivolumab/ipilimumab and 127 to nivolumab). The study was closed for futility at a planned interim analysis. Overall survival was not significantly different between the groups (hazard ratio [HR], 0.87; 95% CI, 0.66-1.16; P =.34). Median survival was 10 months (95% CI, 8.0-14.4 months) in the nivolumab/ipilimumab group and 11 months (95% CI, 8.6-13.7 months) in the nivolumab group. The IA-PFS HR was 0.80 (95% CI, 0.61-1.03; P =.09); median IA-PFS was 3.8 months (95% CI, 2.7-4.4 months) in the nivolumab/ipilimumab group and 2.9 months (95% CI, 1.8-4.0 months) in the nivolumab alone group. Response rates were 18% (95% CI, 12%-25%) with nivolumab/ipilimumab and 17% (95% CI, 10%-23%) with nivolumab. Median response duration was 28.4 months (95% CI, 4.9 months to not reached) with nivolumab/ipilimumab and 9.7 months with nivolumab (95% CI, 4.2-23.1 months). Grade 3 or higher treatment-related adverse events occurred in 49 of 124 patients (39.5%) who received nivolumab/ipilimumab and in 41 of 123 (33.3%) who received nivolumab alone. Toxic effects led to discontinuation in 31 of 124 patients (25%) on nivolumab/ipilimumab and in 19 of 123 (15%) on nivolumab.\n\nConclusions and relevance: In this phase 3 randomized clinical trial, ipilimumab added to nivolumab did not improve outcomes in patients with advanced, pretreated, immune checkpoint inhibitor-naive SqNSCLC.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02785952.\n\nIndexed on Europe PMC as PubMed record 34264316 (DOI 10.1001/jamaoncol.2021.2209). Its abstract cites the registry id NCT02785952, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2021, doi: "10.1001/jamaoncol.2021.2209", pmid: "34264316", authors: "Gettinger SN, Redman MW, Bazhenova L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02785952 with the most citations, so it is the natural first reading for anyone following the S1400I trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2021","url":"https://doi.org/10.1001/jamaoncol.2021.2209"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34264316/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34264316"},{"label":"ClinicalTrials.gov NCT02785952","url":"https://clinicaltrials.gov/study/NCT02785952"}], tags: ["europepmc-ingest"], trials: ["lung-map-s1400i"], journals: ["jama-oncology"] }),
  p({ id: "paper-navigate-j-clin-invest-2021", name: "NTRK and RET fusion-directed therapy in pediatric thyroid cancer yields a tumor response and radioiodine uptake", tldr: "Published report from the NAVIGATE trial registered as NCT02576431, in Journal of Clinical Investigation (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "BACKGROUNDMolecular characterization in pediatric papillary thyroid cancer (PTC), distinct from adult PTC, is important for developing molecularly targeted therapies for progressive radioiodine-refractory (131I-refractory) PTC.METHODSPTC samples from 106 pediatric patients (age range: 4.3-19.8 years; n = 84 girls, n = 22 boys) who were admitted to SNUH (January 1983-March 2020) were available for genomic profiling. Previous transcriptomic data from 125 adult PTC samples were used for comparison.RESULTSWe identified genetic drivers in 80 tumors: 31 with fusion oncogenes (RET in 21 patients, ALK in 6 patients, and NTRK1/3 in 4 patients); 47 with point mutations (BRAFV600E in 41 patients, TERTC228T in 2 patients [1 of whom had a coexisting BRAFV600E], and DICER1 variants in 5 patients); and 2 with amplifications. Fusion oncogene PTCs, which are predominantly detected in younger patients, were at a more advanced stage and showed more recurrent or persistent disease compared with BRAFV600E PTCs, which are detected mostly in adolescents. Pediatric fusion PTCs (in patients <10 years of age) had lower expression of thyroid differentiation genes, including SLC5A5, than did adult fusion PTCs. Two girls with progressive 131I-refractory lung metastases harboring a TPR-NTRK1 or CCDC6-RET fusion oncogene received fusion-targeted therapy; larotrectinib and selpercatinib decreased the size of the tumor and restored 125I radioiodine uptake. The girl with the CCDC6-RET fusion oncogene received 131I therapy combined with selpercatinib, resulting in a tumor response. In vitro 125I uptake and 131I clonogenic assays showed that larotrectinib inhibited tumor growth and restored radioiodine avidity.CONCLUSIONSIn pediatric patients with fusion oncogene PTC who have 131I-refractory advanced disease, selective fusion-directed therapy may restore radioiodine avidity and lead to a dramatic tumor response, underscoring the importance of molecular testing in pediatric patients with PTC.FUNDINGThe Ministry of Science, ICT and Future Planning (NRF-2016R1A2B4012417 and 2019R1A2C2084332); the Korean Ministry of Health and Welfare (H14C1277); the Ministry of Education (2020R1A6A1A03047972); and the SNUH Research Fund (04-2015-0830).TRIAL REGISTRATIONTwo patients received fusion-targeted therapy with larotrectinib (NCT02576431; NAVIGATE) or selpercatinib (LOXO-RET-18018).\n\nIndexed on Europe PMC as PubMed record 34237031 (DOI 10.1172/jci144847). Its abstract cites the registry id NCT02576431, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Investigation", year: 2021, doi: "10.1172/jci144847", pmid: "34237031", authors: "Lee YA, Lee H, Im SW, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02576431 with the most citations, so it is the natural first reading for anyone following the NAVIGATE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Invest 2021","url":"https://doi.org/10.1172/jci144847"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34237031/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34237031"},{"label":"ClinicalTrials.gov NCT02576431","url":"https://clinicaltrials.gov/study/NCT02576431"}], tags: ["europepmc-ingest"], trials: ["navigate"], journals: ["jci"] }),
  p({ id: "paper-orient-11-j-thorac-oncol-2020", name: "Efficacy and Safety of Sintilimab Plus Pemetrexed and Platinum as First-Line Treatment for Locally Advanced or Metastatic Nonsquamous NSCLC: a Randomized, Double-Blind, Phase 3 Study (Oncology pRogram by InnovENT anti-PD-1-11)", tldr: "Published report from the ORIENT-11 trial registered as NCT03607539, in Journal of Thoracic Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Sintilimab, an anti-programmed death 1 antibody, plus pemetrexed and platinum had revealed promising efficacy for nonsquamous NSCLC in a phase 1b study. We conducted a randomized, double-blind, phase 3 study to compare the efficacy and safety of sintilimab with placebo, both in combination with such chemotherapy (ClinicalTrials.gov: NCT03607539).\n\nMethods: A total of 397 patients with previously untreated, locally advanced or metastatic nonsquamous NSCLC without sensitizing EGFR or anaplastic lymphoma kinase genomic aberration were randomized (2:1 ratio) to receive either sintilimab 200 mg or placebo plus pemetrexed and platinum once every 3 weeks for four cycles, followed by sintilimab or placebo plus pemetrexed therapy. Crossover or treatment beyond disease progression was allowed. The primary end point was progression-free survival (PFS) as judged by an independent radiographic review committee.\n\nResults: at November 15, 2019, the median follow-up was 8.9 months. The median PFS was significantly longer in the sintilimab-combination group than that in the placebo-combination group (8.9 versus 5.0 mo; hazard ratio, 0.482, 95% confidence interval [CI]: 0.362-0.643; p < 0.00001). The confirmed objective response rate was 51.9% (95% CI: 45.7%-58.0%) in the sintilimab-combination group and 29.8% (95% CI: 22.1%-38.4%) in placebo-combination group. The incidence of grade 3 or higher adverse events was 61.7% in sintilimab-combination group and 58.8% in placebo-combination group.\n\nConclusions: In Chinese patients with previously untreated, locally advanced or metastatic nonsquamous NSCLC, the addition of sintilimab to chemotherapy with pemetrexed and platinum resulted in considerably longer PFS than with chemotherapy alone with manageable safety profiles.\n\nIndexed on Europe PMC as PubMed record 32781263 (DOI 10.1016/j.jtho.2020.07.014). Its abstract cites the registry id NCT03607539, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2020, doi: "10.1016/j.jtho.2020.07.014", pmid: "32781263", authors: "Yang Y, Wang Z, Fang J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03607539 with the most citations, so it is the natural first reading for anyone following the ORIENT-11 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2020","url":"https://doi.org/10.1016/j.jtho.2020.07.014"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32781263/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32781263"},{"label":"ClinicalTrials.gov NCT03607539","url":"https://clinicaltrials.gov/study/NCT03607539"}], tags: ["europepmc-ingest"], trials: ["orient-11"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-orient-11-lung-cancer-2022-update", name: "Final overall survival data of sintilimab plus pemetrexed and platinum as First-Line treatment for locally advanced or metastatic nonsquamous NSCLC in the Phase 3 ORIENT-11 study", tldr: "Later report from the ORIENT-11 trial registered as NCT03607539, in Lung cancer (2022); its title describes an updated or longer-term analysis.", summary: "Objectives: In ORIENT-11, first-line sintilimab + pemetrexed-platinum significantly improved PFS compared with placebo + pemetrexed-platinum in patients with advanced metastatic nonsquamous non-small-cell lung cancer (AMnsqNSCLC). The study met the primary endpoint of PFS at 15November2019. Here we report final survival analysis from ORIENT-11 (NCT03607539) using a 15September2021 data cutoff.\n\nMethods: Patients with treatment-naïve locally AMnsqNSCLC without sensitizing EGFR or ALK genomic tumor aberrations were randomly assigned to sintilimab + pemetrexed-platinum (n = 266) or placebo + pemetrexed-platinum (n = 131). Patients were stratified by PD-L1 expression, platinum-chemotherapy, and gender. Treatment continued until PD, unacceptable toxicity, or a maximum of 24 months. Patients in the placebo + pemetrexed-platinum arm could be sequenced to second-line sintilimab monotherapy, contingent upon PD. Response was assessed (RECISTv.1.1) by blinded independent radiographic review committee. Primary endpoint was PFS. OS was a secondary endpoint and defined from date of randomization to date of death due to any cause. Final OS analysis was defined as approximately 2 years after last patient randomized or when approximately 65 % of patients died, whichever first.\n\nResults: At data cutoff of final OS analysis, median study follow-up was 30.8 months. Of 397 patients, 243 OS events were observed (sintilimab + pemetrexed-platinum:151[57 %];placebo + pemetrexed-platinum:92 [70 %]). Of the patients in placebo + pemetrexed-platinum arm, 47 % crossed over to sintilimab monotherapy per protocol. Median OS was 24.2 months in sintilimab + pemetrexed-platinum arm and 16.8 months in placebo + pemetrexed-platinum arm (HR:0.65[95 % CI:0.50,0.85]). Estimated 2-year OS rates were 50 %(sintilimab + pemetrexed-platinum) and 32 %(placebo + pemetrexed-platinum). After adjusting for the crossover effect, OS treatment effect was more pronounced with HR 0.52 (95 % CI:0.38,0.69). OS benefit across all prespecified subgroups was largely consistent with that observed in the ITT population.\n\nConclusions: In the ORIENT-11 final OS analysis, sintilimab + pemetrexed-platinum demonstrated improved OS compared to placebo + pemetrexed-platinum when administered as first-line therapy in AMnsqNSCLC without EGFR or ALK genomic tumor aberrations.\n\nIndexed on Europe PMC as PubMed record 35917647 (DOI 10.1016/j.lungcan.2022.07.013). Its abstract cites the registry id NCT03607539, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Lung cancer", year: 2022, doi: "10.1016/j.lungcan.2022.07.013", pmid: "35917647", authors: "Zhang L, Wang Z, Fang J, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the ORIENT-11 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lung Cancer 2022","url":"https://doi.org/10.1016/j.lungcan.2022.07.013"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35917647/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35917647"},{"label":"ClinicalTrials.gov NCT03607539","url":"https://clinicaltrials.gov/study/NCT03607539"}], tags: ["europepmc-ingest"], trials: ["orient-11"], journals: ["lung-cancer-journal"] }),
  p({ id: "paper-pacific-n-engl-j-med-2018-update", name: "Overall Survival with Durvalumab after Chemoradiotherapy in Stage III NSCLC", tldr: "Later report from the PACIFIC trial registered as NCT02125461, in New England Journal of Medicine (2018); its title describes an updated or longer-term analysis.", summary: "Background: An earlier analysis in this phase 3 trial showed that durvalumab significantly prolonged progression-free survival, as compared with placebo, among patients with stage III, unresectable non-small-cell lung cancer (NSCLC) who did not have disease progression after concurrent chemoradiotherapy. Here we report the results for the second primary end point of overall survival.\n\nMethods: We randomly assigned patients, in a 2:1 ratio, to receive durvalumab intravenously, at a dose of 10 mg per kilogram of body weight, or matching placebo every 2 weeks for up to 12 months. Randomization occurred 1 to 42 days after the patients had received chemoradiotherapy and was stratified according to age, sex, and smoking history. The primary end points were progression-free survival (as assessed by blinded independent central review) and overall survival. Secondary end points included the time to death or distant metastasis, the time to second progression, and safety.\n\nResults: Of the 713 patients who underwent randomization, 709 received the assigned intervention (473 patients received durvalumab and 236 received placebo). at March 22, 2018, the median follow-up was 25.2 months. The 24-month overall survival rate was 66.3% (95% confidence interval [CI], 61.7 to 70.4) in the durvalumab group, as compared with 55.6% (95% CI, 48.9 to 61.8) in the placebo group (two-sided P=0.005). Durvalumab significantly prolonged overall survival, as compared with placebo (stratified hazard ratio for death, 0.68; 99.73% CI, 0.47 to 0.997; P=0.0025). Updated analyses regarding progression-free survival were similar to those previously reported, with a median duration of 17.2 months in the durvalumab group and 5.6 months in the placebo group (stratified hazard ratio for disease progression or death, 0.51; 95% CI, 0.41 to 0.63). The median time to death or distant metastasis was 28.3 months in the durvalumab group and 16.2 months in the placebo group (stratified hazard ratio, 0.53; 95% CI, 0.41 to 0.68). A total of 30.5% of the patients in the durvalumab group and 26.1% of those in the placebo group had grade 3 or 4 adverse events of any cause; 15.4% and 9.8% of the patients, respectively, discontinued the trial regimen because of adverse events.\n\nConclusions: Durvalumab therapy resulted in significantly longer overall survival than placebo. No new safety signals were identified. (Funded by AstraZeneca; PACIFIC ClinicalTrials.gov number, NCT02125461.).\n\nIndexed on Europe PMC as PubMed record 30280658 (DOI 10.1056/nejmoa1809697). Its abstract cites the registry id NCT02125461, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1809697", pmid: "30280658", authors: "Antonia SJ, Villegas A, Daniel D, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the PACIFIC trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1809697"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30280658/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30280658"},{"label":"ClinicalTrials.gov NCT02125461","url":"https://clinicaltrials.gov/study/NCT02125461"}], tags: ["europepmc-ingest"], trials: ["pacific"], journals: ["nejm"] }),
  p({ id: "paper-pharos-j-thorac-oncol-2025", name: "Updated Efficacy and Safety From the Phase 2 PHAROS Study of Encorafenib Plus Binimetinib in Patients With BRAF V600E-Mutant Metastatic NSCLC-A Brief Report", tldr: "Published report from the PHAROS trial registered as NCT03915951, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: The PHAROS primary analysis revealed robust antitumor activity and acceptable safety with encorafenib plus binimetinib in patients with BRAF V600E-mutant metastatic NSCLC (mNSCLC). We report results after 18 months of additional follow-up.\n\nMethods: In this ongoing open-label, single-arm, phase 2 study, patients with BRAF V600E-mutant mNSCLC (59 treatment-naive and 39 previously treated) received encorafenib 450 mg once daily and binimetinib 45 mg twice daily. Primary end point was objective response rate (ORR). Secondary end points included duration of response (DOR), progression-free survival (PFS), overall survival (OS), and safety.\n\nResults: At this data cutoff, median treatment duration with encorafenib plus binimetinib was 16.3 months in treatment-naive and 5.5 months in previously treated patients; minimum follow-up was approximately 32 and 22 months, respectively. In treatment-naive patients, the ORR was 75%, median DOR was 40.0 months, median PFS was 30.2 months, median OS was not estimable (95% confidence interval: 31.3-not estimable), and the 3-year OS probability was 53%. In previously treated patients, the ORR was 46%, median DOR was 16.7 months, median PFS was 9.3 months, median OS was 22.7 months, and the 3-year OS probability was 29%. Overall, the most frequent treatment-related adverse events were nausea (52%), diarrhea (44%), fatigue (33%), and vomiting (30%). Treatment-related adverse events led to dose reductions and permanent treatment discontinuations in 25 (26%) and 16 (16%) patients, respectively.\n\nConclusions: With longer follow-up, encorafenib plus binimetinib showed durable and clinically meaningful antitumor activity, especially in treatment-naive patients, with a manageable safety profile in patients with BRAF V600E-mutant mNSCLC.\n\nClinical trial information: ClinicalTrials.gov Identifier: NCT03915951.\n\nIndexed on Europe PMC as PubMed record 40480428 (DOI 10.1016/j.jtho.2025.05.023). Its abstract cites the registry id NCT03915951, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2025.05.023", pmid: "40480428", authors: "Riely GJ, Ahn MJ, Clarke JM, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03915951 with the most citations, so it is the natural first reading for anyone following the PHAROS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2025.05.023"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40480428/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40480428"},{"label":"ClinicalTrials.gov NCT03915951","url":"https://clinicaltrials.gov/study/NCT03915951"}], tags: ["europepmc-ingest"], trials: ["pharos"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-ponsegromab-phase-2-n-engl-j-med-2024", name: "Ponsegromab for the Treatment of Cancer Cachexia", tldr: "Published report from the trial registered as NCT05546476, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Cachexia is a common complication of cancer and is associated with an increased risk of death. The level of growth differentiation factor 15 (GDF-15), a circulating cytokine, is elevated in cancer cachexia. In a small, open-label, phase 1b study involving patients with cancer cachexia, ponsegromab, a humanized monoclonal antibody inhibiting GDF-15, was associated with improved weight, appetite, and physical activity, along with suppressed serum GDF-15 levels.\n\nMethods: In this phase 2, randomized, double-blind, 12-week trial, we assigned patients with cancer cachexia and an elevated serum GDF-15 level (≥1500 pg per milliliter) in a 1:1:1:1 ratio to receive ponsegromab at a dose of 100 mg, 200 mg, or 400 mg or to receive placebo, administered subcutaneously every 4 weeks for three doses. The primary end point was the change from baseline in body weight at 12 weeks. Key secondary end points were appetite and cachexia symptoms, digital measures of physical activity, and safety.\n\nResults: A total of 187 patients underwent randomization. Of these patients, 40% had non-small-cell lung cancer, 32% had pancreatic cancer, and 29% had colorectal cancer. At 12 weeks, patients in the ponsegromab groups had significantly greater weight gain than those in the placebo group, with a median between-group difference of 1.22 kg (95% credible interval, 0.37 to 2.25) in the 100-mg group, 1.92 (95% credible interval, 0.92 to 2.97) in the 200-mg group, and 2.81 (95% credible interval, 1.55 to 4.08) in the 400-mg group. Improvements were observed across measures of appetite and cachexia symptoms, along with physical activity, in the 400-mg ponsegromab group relative to placebo. Adverse events of any cause were reported in 70% of the patients in the ponsegromab group and in 80% of those in the placebo group.\n\nConclusions: Among patients with cancer cachexia and elevated GDF-15 levels, the inhibition of GDF-15 with ponsegromab resulted in increased weight gain and overall activity level and reduced cachexia symptoms, findings that confirmed the role of GDF-15 as a driver of cachexia. (Funded by Pfizer; ClinicalTrials.gov number, NCT05546476.).\n\nIndexed on Europe PMC as PubMed record 39282907 (DOI 10.1056/nejmoa2409515). Its abstract cites the registry id NCT05546476, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2409515", pmid: "39282907", authors: "Groarke JD, Crawford J, Collins SM, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05546476 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2409515"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39282907/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39282907"},{"label":"ClinicalTrials.gov NCT05546476","url":"https://clinicaltrials.gov/study/NCT05546476"}], tags: ["europepmc-ingest"], trials: ["ponsegromab-phase-2"], journals: ["nejm"] }),
  p({ id: "paper-romana-1-2-lancet-oncol-2016", name: "Anamorelin in patients with non-small-cell lung cancer and cachexia (ROMANA 1 and ROMANA 2): results from two randomised, double-blind, phase 3 trials", tldr: "Published report from the ROMANA 1 trial registered as NCT01387269, in The Lancet Oncology (2016), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Patients with advanced cancer frequently experience anorexia and cachexia, which are associated with reduced food intake, altered body composition, and decreased functionality. We assessed anamorelin, a novel ghrelin-receptor agonist, on cachexia in patients with advanced non-small-cell lung cancer and cachexia.\n\nMethods: ROMANA 1 and ROMANA 2 were randomised, double-blind, placebo-controlled phase 3 trials done at 93 sites in 19 countries. Patients with inoperable stage III or IV non-small-cell lung cancer and cachexia (defined as ≥5% weight loss within 6 months or body-mass index <20 kg/m(2)) were randomly assigned 2:1 to anamorelin 100 mg orally once daily or placebo, with a computer-generated randomisation algorithm stratified by geographical region, cancer treatment status, and weight loss over the previous 6 months. Co-primary efficacy endpoints were the median change in lean body mass and handgrip strength over 12 weeks and were measured in all study participants (intention-to-treat population). Both trials are now completed and are registered with ClinicalTrials.gov, numbers NCT01387269 and NCT01387282.\n\nFindings: From July 8, 2011, to Jan 28, 2014, 484 patients were enrolled in ROMANA 1 (323 to anamorelin, 161 to placebo), and from July 14, 2011, to Oct 31, 2013, 495 patients were enrolled in ROMANA 2 (330 to anamorelin, 165 to placebo). Over 12 weeks, lean body mass increased in patients assigned to anamorelin compared with those assigned to placebo in ROMANA 1 (median increase 0·99 kg [95% CI 0·61 to 1·36] vs -0·47 kg [-1·00 to 0·21], p<0·0001) and ROMANA 2 (0·65 kg [0·38 to 0·91] vs -0·98 kg [-1·49 to -0·41], p<0·0001). We noted no difference in handgrip strength in ROMANA 1 (-1·10 kg [-1·69 to -0·40] vs -1·58 kg [-2·99 to -1·14], p=0·15) or ROMANA 2 (-1·49 kg [-2·06 to -0·58] vs -0·95 kg [-1·56 to 0·04], p=0·65). There were no differences in grade 3-4 treatment-related adverse events between study groups; the most common grade 3-4 adverse event was hyperglycaemia, occurring in one (<1%) of 320 patients given anamorelin in ROMANA 1 and in four (1%) of 330 patients given anamorelin in ROMANA 2.\n\nInterpretation: Anamorelin significantly increased lean body mass, but not handgrip, strength in patients with advanced non-small-cell lung cancer. Considering the unmet medical need for safe and effective treatments for cachexia, anamorelin might be a treatment option for patients with cancer anorexia and cachexia.\n\nFunding: Helsinn Therapeutics.\n\nIndexed on Europe PMC as PubMed record 26906526 (DOI 10.1016/s1470-2045(15)00558-6). Its abstract cites the registry id NCT01387269, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2016, doi: "10.1016/s1470-2045(15)00558-6", pmid: "26906526", authors: "Temel JS, Abernethy AP, Currow DC, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01387269 with the most citations, so it is the natural first reading for anyone following the ROMANA 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","The abstract cites more than one registry id (NCT01387269, NCT01387282); it was kept because the trial's acronym appears in the title."], links: [{"label":"Lancet Oncol 2016","url":"https://doi.org/10.1016/s1470-2045(15)00558-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/26906526/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/26906526"},{"label":"ClinicalTrials.gov NCT01387269","url":"https://clinicaltrials.gov/study/NCT01387269"}], tags: ["europepmc-ingest"], trials: ["romana-1-2"], journals: ["lancet-oncology"] }),
  p({ id: "paper-rtog-0617-lancet-oncol-2015", name: "Standard-dose versus high-dose conformal radiotherapy with concurrent and consolidation carboplatin plus paclitaxel with or without cetuximab for patients with stage IIIA or IIIB non-small-cell lung cancer (RTOG 0617): a randomised, two-by-two factorial phase 3 study", tldr: "Published report from the RTOG 0617 trial registered as NCT00533949, in The Lancet Oncology (2015), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: We aimed to compare overall survival after standard-dose versus high-dose conformal radiotherapy with concurrent chemotherapy and the addition of cetuximab to concurrent chemoradiation for patients with inoperable stage III non-small-cell lung cancer.\n\nMethods: In this open-label randomised, two-by-two factorial phase 3 study in 185 institutions in the USA and Canada, we enrolled patients (aged ≥ 18 years) with unresectable stage III non-small-cell lung cancer, a Zubrod performance status of 0-1, adequate pulmonary function, and no evidence of supraclavicular or contralateral hilar adenopathy. We randomly assigned (1:1:1:1) patients to receive either 60 Gy (standard dose), 74 Gy (high dose), 60 Gy plus cetuximab, or 74 Gy plus cetuximab. All patients also received concurrent chemotherapy with 45 mg/m(2) paclitaxel and carboplatin once a week (AUC 2); 2 weeks after chemoradiation, two cycles of consolidation chemotherapy separated by 3 weeks were given consisting of paclitaxel (200 mg/m(2)) and carboplatin (AUC 6). Randomisation was done with permuted block randomisation methods, stratified by radiotherapy technique, Zubrod performance status, use of PET during staging, and histology; treatment group assignments were not masked. Radiation dose was prescribed to the planning target volume and was given in 2 Gy daily fractions with either intensity-modulated radiation therapy or three-dimensional conformal radiation therapy. The use of four-dimensional CT and image-guided radiation therapy were encouraged but not necessary. For patients assigned to receive cetuximab, 400 mg/m(2) cetuximab was given on day 1 followed by weekly doses of 250 mg/m(2), and was continued through consolidation therapy. The primary endpoint was overall survival. All analyses were done by modified intention-to-treat. The study is registered with ClinicalTrials.gov, number NCT00533949.\n\nFindings: Between Nov 27, 2007, and Nov 22, 2011, 166 patients were randomly assigned to receive standard-dose chemoradiotherapy, 121 to high-dose chemoradiotherapy, 147 to standard-dose chemoradiotherapy and cetuximab, and 110 to high-dose chemoradiotherapy and cetuximab. Median follow-up for the radiotherapy comparison was 22.9 months (IQR 27.5-33.3). Median overall survival was 28.7 months (95% CI 24.1-36.9) for patients who received standard-dose radiotherapy and 20.3 months (17.7-25.0) for those who received high-dose radiotherapy (hazard ratio [HR] 1.38, 95% CI 1.09-1.76; p=0.004). Median follow-up for the cetuximab comparison was 21.3 months (IQR 23.5-29.8). Median overall survival in patients who received cetuximab was 25.0 months (95% CI 20.2-30.5) compared with 24.0 months (19.8-28.6) in those who did not (HR 1.07, 95% CI 0.84-1.35; p=0.29). Both the radiation-dose and cetuximab results crossed protocol-specified futility boundaries. We recorded no statistical differences in grade 3 or worse toxic effects between radiotherapy groups. By contrast, the use of cetuximab was associated with a higher rate of grade 3 or worse toxic effects (205 [86%] of 237 vs 160 [70%] of 228 patients; p<0.0001). There were more treatment-related deaths in the high-dose chemoradiotherapy and cetuximab groups (radiotherapy comparison: eight vs three patients; cetuximab comparison: ten vs five patients). There were no differences in severe pulmonary events between treatment groups. Severe oesophagitis was more common in patients who received high-dose chemoradiotherapy than in those who received standard-dose treatment (43 [21%] of 207 patients vs 16 [7%] of 217 patients; p<0.0001).\n\nInterpretation: 74 Gy radiation given in 2 Gy fractions with concurrent chemotherapy was not better than 60 Gy plus concurrent chemotherapy for patients with stage III non-small-cell lung cancer, and might be potentially harmful. Addition of cetuximab to concurrent chemoradiation and consolidation treatment provided no benefit in overall survival for these patients.\n\nFunding: National Cancer Institute and Bristol-Myers Squibb.\n\nIndexed on Europe PMC as PubMed record 25601342 (DOI 10.1016/s1470-2045(14)71207-0). Its abstract cites the registry id NCT00533949, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2015, doi: "10.1016/s1470-2045(14)71207-0", pmid: "25601342", authors: "Bradley JD, Paulus R, Komaki R, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00533949 with the most citations, so it is the natural first reading for anyone following the RTOG 0617 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2015","url":"https://doi.org/10.1016/s1470-2045(14)71207-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/25601342/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/25601342"},{"label":"ClinicalTrials.gov NCT00533949","url":"https://clinicaltrials.gov/study/NCT00533949"}], tags: ["europepmc-ingest"], trials: ["rtog-0617"], journals: ["lancet-oncology"] }),
  p({ id: "paper-sabr-comet-lancet-2019", name: "Stereotactic ablative radiotherapy versus standard of care palliative treatment in patients with oligometastatic cancers (SABR-COMET): a randomised, phase 2, open-label trial", tldr: "Published report from the trial registered as NCT01446744, in The Lancet (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The oligometastatic paradigm suggests that some patients with a limited number of metastases might be cured if all lesions are eradicated. Evidence from randomised controlled trials to support this paradigm is scarce. We aimed to assess the effect of stereotactic ablative radiotherapy (SABR) on survival, oncological outcomes, toxicity, and quality of life in patients with a controlled primary tumour and one to five oligometastatic lesions.\n\nMethods: This randomised, open-label phase 2 study was done at 10 hospitals in Canada, the Netherlands, Scotland, and Australia. Patients aged 18 or older with a controlled primary tumour and one to five metastatic lesions, Eastern Cooperative Oncology Group score of 0-1, and a life expectancy of at least 6 months were eligible. After stratifying by the number of metastases (1-3 vs 4-5), we randomly assigned patients (1:2) to receive either palliative standard of care treatments alone (control group), or standard of care plus SABR to all metastatic lesions (SABR group), using a computer-generated randomisation list with permuted blocks of nine. Neither patients nor physicians were masked to treatment allocation. The primary endpoint was overall survival. We used a randomised phase 2 screening design with a two-sided α of 0·20 (wherein p<0·20 designates a positive trial). All analyses were intention to treat. This study is registered with ClinicalTrials.gov, number NCT01446744.\n\nFindings: 99 patients were randomised between Feb 10, 2012, and Aug 30, 2016. Of 99 patients, 33 (33%) were assigned to the control group and 66 (67%) to the SABR group. Two (3%) patients in the SABR group did not receive allocated treatment and withdrew from the trial; two (6%) patients in the control group also withdrew from the trial. Median follow-up was 25 months (IQR 19-54) in the control group versus 26 months (23-37) in the SABR group. Median overall survival was 28 months (95% CI 19-33) in the control group versus 41 months (26-not reached) in the SABR group (hazard ratio 0·57, 95% CI 0·30-1·10; p=0·090). Adverse events of grade 2 or worse occurred in three (9%) of 33 controls and 19 (29%) of 66 patients in the SABR group (p=0·026), an absolute increase of 20% (95% CI 5-34). Treatment-related deaths occurred in three (4·5%) of 66 patients after SABR, compared with none in the control group.\n\nInterpretation: SABR was associated with an improvement in overall survival, meeting the primary endpoint of this trial, but three (4·5%) of 66 patients in the SABR group had treatment-related death. Phase 3 trials are needed to conclusively show an overall survival benefit, and to determine the maximum number of metastatic lesions wherein SABR provides a benefit.\n\nFunding: Ontario Institute for Cancer Research and London Regional Cancer Program Catalyst Grant.\n\nIndexed on Europe PMC as PubMed record 30982687 (DOI 10.1016/s0140-6736(18)32487-5). Its abstract cites the registry id NCT01446744, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2019, doi: "10.1016/s0140-6736(18)32487-5", pmid: "30982687", authors: "Palma DA, Olson R, Harrow S, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01446744 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2019","url":"https://doi.org/10.1016/s0140-6736(18)32487-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30982687/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30982687"},{"label":"ClinicalTrials.gov NCT01446744","url":"https://clinicaltrials.gov/study/NCT01446744"}], tags: ["europepmc-ingest"], trials: ["sabr-comet"], journals: ["lancet"] }),
  p({ id: "paper-soho-01-n-engl-j-med-2025", name: "Sevabertinib in Advanced HER2 -Mutant Non-Small-Cell Lung Cancer", tldr: "Published report from the SOHO-01 trial registered as NCT05099172, in New England Journal of Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: HER2 gene mutations occur in 2 to 4% of patients with non-small-cell lung cancer (NSCLC). Sevabertinib is an oral, reversible tyrosine kinase inhibitor that has shown anti-HER2 activity in preclinical models.\n\nMethods: We conducted an open-label, multicenter, multicohort, phase 1-2 study to evaluate sevabertinib at a twice-daily dose of 20 mg in patients with locally advanced or metastatic HER2 -mutant NSCLC. Three cohorts were defined according to previous therapy: cohort D comprised previously treated patients who had not received HER2-targeted therapy; cohort E, patients who had previously received HER2-directed antibody-drug conjugates; and cohort F, patients who had not previously received treatment. The primary end point was an objective response, as assessed by blinded independent central review. Secondary end points were duration of response and progression-free survival.\n\nResults: A total of 209 patients received sevabertinib (at June 27, 2025, the data-cutoff date); the median duration of follow-up was 13.8 months in cohort D, 11.7 months in cohort E, and 9.9 months in cohort F. Among 81 patients in cohort D, an objective response was observed in 64% (95% confidence interval [CI], 53 to 75); the median duration of response was 9.2 months (95% CI, 6.3 to 13.5), and the median progression-free survival was 8.3 months (95% CI, 6.9 to 12.3). Among 55 patients in cohort E, an objective response was observed in 38% (95% CI, 25 to 52); the median duration of response was 8.5 months, and the median progression-free survival was 5.5 months. Among 73 patients in cohort F, an objective response was observed in 71% (95% CI, 59 to 81), and the median duration of response was 11.0 months; data on progression-free survival were immature. Grade 3 or higher drug-related adverse events occurred in 31% of the patients. The most common adverse event was diarrhea (in 84 to 91%), with diarrhea of grade 3 or higher occurring in 5 to 23%. Treatment was discontinued by 3% of the patients owing to drug-related adverse events.\n\nConclusions: Sevabertinib showed antitumor activity in patients with locally advanced or metastatic HER2 -mutant NSCLC. Diarrhea was the most common adverse event. (Funded by Bayer; SOHO-01 ClinicalTrials.gov number, NCT05099172.).\n\nIndexed on Europe PMC as PubMed record 41104928 (DOI 10.1056/nejmoa2511065). Its abstract cites the registry id NCT05099172, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2511065", pmid: "41104928", authors: "Le X, Kim TM, Loong HH, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05099172 with the most citations, so it is the natural first reading for anyone following the SOHO-01 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2511065"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41104928/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41104928"},{"label":"ClinicalTrials.gov NCT05099172","url":"https://clinicaltrials.gov/study/NCT05099172"}], tags: ["europepmc-ingest"], trials: ["soho-01"], journals: ["nejm"] }),
  p({ id: "paper-tropion-lung05-j-clin-oncol-2025", name: "Datopotamab Deruxtecan in Advanced or Metastatic Non-Small Cell Lung Cancer With Actionable Genomic Alterations: Results From the Phase II TROPION-Lung05 Study", tldr: "Published report from the TROPION-Lung05 trial registered as NCT04484142, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Datopotamab deruxtecan (Dato-DXd) is a trophoblast cell-surface antigen-2-directed antibody-drug conjugate with a highly potent topoisomerase I inhibitor payload. The TROPION-Lung05 phase II trial (ClinicalTrials.gov identifier: NCT04484142) evaluated the safety and clinical activity of Dato-DXd in patients with advanced/metastatic non-small cell lung cancer (NSCLC) with actionable genomic alterations progressing on or after targeted therapy and platinum-based chemotherapy.\n\nPatients and methods: Patients received Dato-DXd 6 mg/kg once every 3 weeks. The primary end point was objective response rate (ORR) by blinded independent central review. Secondary end points included duration of response (DOR), safety, tolerability, and survival.\n\nResults: Among 137 patients who received at least 1 dose of Dato-DXd, 71.5% received at least three lines of prior therapies for advanced/metastatic disease. Overall, 56.9% had EGFR mutations and 24.8% had ALK rearrangements. Median treatment duration was 4.4 months (range, 0.7-20.6). The confirmed ORR was 35.8% (95% CI, 27.8 to 44.4) overall, and 43.6% (95% CI, 32.4 to 55.3) and 23.5% (95% CI, 10.7 to 41.2) in those with EGFR mutations and ALK rearrangements, respectively. The median DOR was 7.0 months (95% CI, 4.2 to 9.8), and the overall disease control rate was 78.8% (95% CI, 71.0 to 85.3). Grade ≥3 treatment-related adverse events (TRAEs) occurred in 28.5% of patients. The most common TRAE was stomatitis (preferred term; any grade: 56.2%; grade ≥3: 9.5%). Five (3.6%) patients experienced adjudicated treatment-related interstitial lung disease/pneumonitis, with 1 (0.7%) grade 5 event.\n\nConclusion: Encouraging and durable antitumor activity was observed with Dato-DXd in this heavily pretreated advanced/metastatic NSCLC population with actionable genomic alterations. The rate of treatment-related grade ≥3 toxicities was comparable with previous observations, and no new safety signals were observed.\n\nIndexed on Europe PMC as PubMed record 39761483 (DOI 10.1200/jco-24-01349). Its abstract cites the registry id NCT04484142, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-24-01349", pmid: "39761483", authors: "Sands J, Ahn MJ, Lisberg A, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04484142 with the most citations, so it is the natural first reading for anyone following the TROPION-Lung05 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-24-01349"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39761483/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39761483"},{"label":"ClinicalTrials.gov NCT04484142","url":"https://clinicaltrials.gov/study/NCT04484142"}], tags: ["europepmc-ingest"], trials: ["tropion-lung05"], journals: ["jco"] }),
  p({ id: "paper-alchemist-jama-oncol-2022", name: "Rates of Guideline-Concordant Surgery and Adjuvant Chemotherapy Among Patients With Early-Stage Lung Cancer in the US ALCHEMIST Study (Alliance A151216)", tldr: "Published report from the ALCHEMIST trial registered as NCT02194738, in JAMA Oncology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Standard treatment for resectable non-small cell lung cancer (NSCLC) includes anatomic resection with adequate lymph node dissection and adjuvant chemotherapy for appropriate patients. Historically, many patients with early-stage NSCLC have not received such treatment, which may affect the interpretation of the results of adjuvant therapy trials.\n\nObjective: To ascertain patterns of guideline-concordant treatment among patients enrolled in a US-wide screening protocol for adjuvant treatment trials for resected NSCLC.\n\nDesign, setting, and participants: This retrospective cohort study included 2833 patients with stage IB to IIIA NSCLC (per American Joint Committee on Cancer 7th edition criteria) who enrolled in the Adjuvant Lung Cancer Enrichment Marker Identification and Sequencing Trial (ALCHEMIST) screening study (Alliance for Clinical Trials in Oncology A151216) from August 18, 2014, to April 1, 2019, and who did not enroll in a therapeutic adjuvant clinical trial; patients had tumors of at least 4 cm and/or with positive lymph nodes. Statistical analysis was conducted from June 1, 2020, through October 1, 2021.\n\nExposures: Care patterns were ascertained overall and by sociodemographic and clinical factors, including age, sex, race and ethnicity, educational level, marital status, geography, histologic characteristics, stage, genomic variant status, smoking history, and comorbidities.\n\nMain outcomes and measures: Five outcomes are reported: whether patients (1) had anatomic surgical resection, (2) had adequate lymph node dissection (≥1 N1 nodal station plus ≥3 N2 nodal stations), (3) received any adjuvant chemotherapy, (4) received any cisplatin-based adjuvant chemotherapy, and (5) received at least 4 cycles of adjuvant chemotherapy.\n\nResults: Of the 2833 patients (1505 women [53%]; mean [SD] age, 66.5 [9.2] years) included in this analysis, 2697 (95%) had anatomic surgical resection, 1513 (53%) had adequate lymph node dissection, 1617 (57%) received any adjuvant chemotherapy, 1237 (44%) received at least 4 cycles of adjuvant platinum-based chemotherapy, and 965 (34%) received any cisplatin-based adjuvant chemotherapy. Rates were similar across race and ethnicity.\n\nConclusions and relevance: This cohort study found that among participants in a screening protocol for adjuvant clinical trials for resected early-stage NSCLC, just 53% underwent adequate lymph node dissection, and 57% received adjuvant chemotherapy, despite indications for such treatment. These results may affect the interpretation of adjuvant trials. Efforts are needed to optimize the use of proven therapies for early-stage NSCLC.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02194738.\n\nIndexed on Europe PMC as PubMed record 35297944 (DOI 10.1001/jamaoncol.2022.0039). Its abstract cites the registry id NCT02194738, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2022, doi: "10.1001/jamaoncol.2022.0039", pmid: "35297944", authors: "Kehl KL, Zahrieh D, Yang P, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02194738 with the most citations, so it is the natural first reading for anyone following the ALCHEMIST trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2022","url":"https://doi.org/10.1001/jamaoncol.2022.0039"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35297944/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35297944"},{"label":"ClinicalTrials.gov NCT02194738","url":"https://clinicaltrials.gov/study/NCT02194738"}], tags: ["europepmc-ingest"], trials: ["alchemist"], journals: ["jama-oncology"] }),
  p({ id: "paper-chrysalis-nat-med-2023", name: "Amivantamab plus lazertinib in osimertinib-relapsed EGFR-mutant advanced non-small cell lung cancer: a phase 1 trial", tldr: "Published report from the CHRYSALIS trial registered as NCT02609776, in Nature Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Patients with epidermal growth factor receptor (EGFR)-mutated non-small cell lung cancer (NSCLC) often develop resistance to current standard third-generation EGFR tyrosine kinase inhibitors (TKIs); no targeted treatments are approved in the osimertinib-relapsed setting. In this open-label, dose-escalation and dose-expansion phase 1 trial, the potential for improved anti-tumor activity by combining amivantamab, an EGFR-MET bispecific antibody, with lazertinib, a third-generation EGFR TKI, was evaluated in patients with EGFR-mutant NSCLC whose disease progressed on third-generation TKI monotherapy but were chemotherapy naive (CHRYSALIS cohort E). In the dose-escalation phase, the recommended phase 2 combination dose was established; in the dose-expansion phase, the primary endpoints were safety and overall response rate, and key secondary endpoints included progression-free survival and overall survival. The safety profile of amivantamab and lazertinib was generally consistent with previous experience of each agent alone, with 4% experiencing grade ≥3 events; no new safety signals were identified. In an exploratory cohort of 45 patients who were enrolled without biomarker selection, the primary endpoint of investigator-assessed overall response rate was 36% (95% confidence interval, 22-51). The median duration of response was 9.6 months, and the median progression-free survival was 4.9 months. Next-generation sequencing and immunohistochemistry analyses identified high EGFR and/or MET expression as potential predictive biomarkers of response, which will need to be validated with prospective assessment. ClinicalTrials.gov identifier: NCT02609776.\n\nIndexed on Europe PMC as PubMed record 37710001 (DOI 10.1038/s41591-023-02554-7). Its abstract cites the registry id NCT02609776, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2023, doi: "10.1038/s41591-023-02554-7", pmid: "37710001", authors: "Cho BC, Kim DW, Spira AI, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02609776 with the most citations, so it is the natural first reading for anyone following the CHRYSALIS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2023","url":"https://doi.org/10.1038/s41591-023-02554-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37710001/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37710001"},{"label":"ClinicalTrials.gov NCT02609776","url":"https://clinicaltrials.gov/study/NCT02609776"}], tags: ["europepmc-ingest"], trials: ["chrysalis"], journals: ["nature-medicine"] }),
  p({ id: "paper-lung-map-j-thorac-oncol-2019", name: "SWOG S1400C (NCT02154490)-A Phase II Study of Palbociclib for Previously Treated Cell Cycle Gene Alteration-Positive Patients with Stage IV Squamous Cell Lung Cancer (Lung-MAP Substudy)", tldr: "Published report from the Lung-MAP trial registered as NCT02154490, in Journal of Thoracic Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Objective: Lung-MAP (SWOG S1400) is a master platform trial assessing targeted therapies in squamous NSCLC. The objective of study C (S1400C) was to evaluate the response rate to palbociclib, a cyclin-dependent kinase 4 and cyclin-dependent kinase 6 inhibitor, in patients with cell cycle gene abnormalities.\n\nMethods: Patients with squamous NSCLC, a performance status of 0 to 2, and normal organ function who had progressed after at least one prior platinum-based chemotherapy with cyclin-dependent kinase 4 gene (CDK4) or cyclin D1 gene (CCND1), cyclin D2 gene (CCND2), or cyclin D3 gene (CCND3) amplifications on tumor specimens were eligible. The study was originally designed as a phase II/III trial comparing palbociclib with docetaxel, but it was modified to a single-arm phase II trial with the primary end point of response when immunotherapy was approved. If two or fewer responses were seen in the first 20 patients, then the study would cease enrollment.\n\nResults: A total of 88 patients (9% of patients screened) were assigned to S1400C, and 53 patients enrolled (including 17 to receive docetaxel). One patient who had been registered to receive docetaxel was re-registered to receive palbociclib after progression while taking docetaxel. The frequencies of cell cycle gene alterations in the eligible patients taking palbociclib (n = 32) were as follows: CCND1, 81% (n = 26); CCND2, 9% (n = 3); CCND3, 6% (n = 2); and CDK4, 3% (n = 1). In all, 32 eligible patients received palbociclib. There were two partial responses (response rate 6% [95% confidence interval (CI): 0%-15%]), both with CCND1 amplification. Twelve patients had stable disease (38% [95% CI: 21%-54%]). The median progression-free survival was 1.7 months (95% CI: 1.6-2.9 months) and the median overall survival was 7.1 months (95% CI: 4.2-12.5).\n\nConclusion: Palbociclib as monotherapy failed to demonstrate the prespecified criteria for advancement to phase III testing.\n\nIndexed on Europe PMC as PubMed record 31302234 (DOI 10.1016/j.jtho.2019.06.027). Its title cites the registry id NCT02154490, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2019, doi: "10.1016/j.jtho.2019.06.027", pmid: "31302234", authors: "Edelman MJ, Redman MW, Albain KS, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02154490 with the most citations, so it is the natural first reading for anyone following the Lung-MAP trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2019","url":"https://doi.org/10.1016/j.jtho.2019.06.027"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31302234/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31302234"},{"label":"ClinicalTrials.gov NCT02154490","url":"https://clinicaltrials.gov/study/NCT02154490"}], tags: ["europepmc-ingest"], trials: ["lung-map"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct01933932-jama-2017", name: "Selumetinib Plus Docetaxel Compared With Docetaxel Alone and Progression-Free Survival in Patients With KRAS-Mutant Advanced Non-Small Cell Lung Cancer: The SELECT-1 Randomized Clinical Trial", tldr: "Published report from the SELECT 1 trial registered as NCT01933932, in JAMA (2017), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: There are no specifically approved targeted therapies for the most common genomically defined subset of non-small cell lung cancer (NSCLC), KRAS-mutant lung cancer.\n\nObjective: To compare efficacy of the mitogen-activated protein kinase kinase (MEK) inhibitor selumetinib + docetaxel with docetaxel alone as a second-line therapy for advanced KRAS-mutant NSCLC.\n\nDesign, setting, and participants: Multinational, randomized clinical trial conducted at 202 sites across 25 countries from October 2013 through January 2016. Of 3323 patients with advanced NSCLC and disease progression following first-line anticancer therapy tested for a KRAS mutation, 866 were enrolled and 510 randomized. Primary reason for exclusion was ineligibility. The data cutoff date for analysis was June 7, 2016.\n\nInterventions: Patients were randomized 1:1; 254 to receive selumetinib + docetaxel and 256 to receive placebo + docetaxel.\n\nMain outcomes and measures: Primary end point was investigator assessed progression-free survival. Secondary end points included overall survival, objective response rate, duration of response, effects on disease-related symptoms, safety, and tolerability.\n\nResults: Of 510 randomized patients (mean age, 61.4 years [SD, 8.3]; women, 207 [41%]), 505 patients (99%) received treatment and completed the study (251 received selumetinib + docetaxel; 254 received placebo + docetaxel). At the time of data cutoff, 447 patients (88%) had experienced a progression event and 346 deaths (68%) had occurred. Median progression-free survival was 3.9 months (interquartile range [IQR], 1.5-5.9) with selumetinib + docetaxel and 2.8 months (IQR, 1.4-5.5) with placebo + docetaxel (difference, 1.1 months; hazard ratio [HR], 0.93 [95% CI, 0.77-1.12]; P =.44). Median overall survival was 8.7 months (IQR, 3.6-16.8) with selumetinib + docetaxel and 7.9 months (IQR, 3.8-20.1) with placebo + docetaxel (difference, 0.9 months; HR, 1.05 [95% CI, 0.85-1.30]; P =.64). Objective response rate was 20.1% with selumetinib + docetaxel and 13.7% with placebo + docetaxel (difference, 6.4%; odds ratio, 1.61 [95% CI, 1.00-2.62]; P =.05). Median duration of response was 2.9 months (IQR, 1.7-4.8; 95% CI, 2.7-4.1) with selumetinib + docetaxel and 4.5 months (IQR, 2.3-7.3; 95% CI, 2.8-5.6) with placebo + docetaxel. Adverse events of grade 3 or higher were more frequent with selumetinib + docetaxel (169 adverse events [67%] for selumetinib + docetaxel vs 115 adverse events [45%] for placebo + docetaxel; difference, 22%).\n\nConclusions and relevance: Among patients with previously treated advanced KRAS-mutant non-small cell lung cancer, addition of selumetinib to docetaxel did not improve progression-free survival compared with docetaxel alone.\n\nTrial registration: clinicaltrials.gov: NCT01933932.\n\nIndexed on Europe PMC as PubMed record 28492898 (DOI 10.1001/jama.2017.3438). Its abstract cites the registry id NCT01933932, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2017, doi: "10.1001/jama.2017.3438", pmid: "28492898", authors: "Jänne PA, van den Heuvel MM, Barlesi F, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01933932 with the most citations, so it is the natural first reading for anyone following the SELECT 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2017","url":"https://doi.org/10.1001/jama.2017.3438"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28492898/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28492898"},{"label":"ClinicalTrials.gov NCT01933932","url":"https://clinicaltrials.gov/study/NCT01933932"}], tags: ["europepmc-ingest"], trials: ["nct01933932"], journals: ["jama"] }),
  p({ id: "paper-nct02152631-front-oncol-2020", name: "A Randomized Phase III Study of Abemaciclib Versus Erlotinib in Patients with Stage IV Non-small Cell Lung Cancer With a Detectable KRAS Mutation Who Failed Prior Platinum-Based Therapy: JUNIPER", tldr: "Published report from the JUNIPER trial registered as NCT02152631, in Frontiers in oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: JUNIPER compared the efficacy and safety of abemaciclib, a selective cyclin-dependent kinase 4 and 6 inhibitor, with erlotinib in patients with non-small cell lung cancer (NSCLC) harboring a Kirsten rat sarcoma ( KRAS) mutation.\n\nMethods: JUNIPER was a Phase III, multicenter, randomized, open-label trial of abemaciclib versus erlotinib in patients with stage IV NSCLC and a detectable mutation in codons 12 or 13 of the KRAS oncogene, who progressed after platinum-based chemotherapy and 1 additional therapy (could include immune checkpoint inhibitor therapy). Randomized patients (3:2) received either 200 mg abemaciclib twice daily or 150 mg erlotinib once daily with best supportive care until disease progression or unacceptable toxicity. The primary endpoint was overall survival (OS); secondary endpoints included overall response rate (ORR), progression-free survival (PFS), and safety.\n\nResults: Between December 2014 and April 2017, 453 patients were randomly assigned to receive abemaciclib (N = 270) or erlotinib (N = 183). Median OS was 7.4 months (95% confidence interval [CI]: 6.5, 8.8) with abemaciclib and 7.8 months (95% CI: 6.4, 9.5) with erlotinib (hazard ratio [HR] = 0.968 [95% CI: 0.768, 1.219]; p =.77). Median PFS was 3.6 months (95% CI: 2.8, 3.8) with abemaciclib and 1.9 months (95% CI: 1.9, 2.0) with erlotinib (HR = 0.583 [95% CI: 0.470, 0.723]; p <.000001). ORR was 8.9% and 2.7% (p =.010), and the disease control rate was 54.4% and 31.7% (p <.001) with abemaciclib and erlotinib, respectively. Safety results reflected the known safety profiles of abemaciclib and erlotinib.\n\nConclusions: In this study, the primary endpoint of OS was not met; PFS and ORR were improved with manageable toxicity in the abemaciclib arm. The increases in response rates and PFS support further investigation of abemaciclib in other NSCLC subpopulations or in combination with other agents.\n\nClinical trial registration: www.ClinicalTrials.gov, identifier: NCT02152631.\n\nIndexed on Europe PMC as PubMed record 33194700 (DOI 10.3389/fonc.2020.578756). Its abstract cites the registry id NCT02152631, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Frontiers in oncology", year: 2020, doi: "10.3389/fonc.2020.578756", pmid: "33194700", authors: "Goldman JW, Mazieres J, Barlesi F, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02152631 with the most citations, so it is the natural first reading for anyone following the JUNIPER trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Front Oncol 2020","url":"https://doi.org/10.3389/fonc.2020.578756"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33194700/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33194700"},{"label":"ClinicalTrials.gov NCT02152631","url":"https://clinicaltrials.gov/study/NCT02152631"}], tags: ["europepmc-ingest"], trials: ["nct02152631"] }),
  p({ id: "paper-nct02411448-lancet-oncol-2019", name: "Ramucirumab plus erlotinib in patients with untreated, EGFR-mutated, advanced non-small-cell lung cancer (RELAY): a randomised, double-blind, placebo-controlled, phase 3 trial", tldr: "Published report from the RELAY trial registered as NCT02411448, in The Lancet Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Dual blockade of the EGFR and VEGF pathways in EGFR-mutated metastatic non-small-cell lung cancer (NSCLC) is supported by preclinical and clinical data, yet the approach is not widely implemented. RELAY assessed erlotinib, an EGFR tyrosine kinase inhibitor (TKI) standard of care, plus ramucirumab, a human IgG1 VEGFR2 antagonist, or placebo in patients with untreated EGFR-mutated metastatic NSCLC.\n\nMethods: This is a worldwide, double-blind, phase 3 trial done in 100 hospitals, clinics, and medical centres in 13 countries. Eligible patients were aged 18 years or older (20 years or older in Japan and Taiwan) at the time of study entry, had stage IV NSCLC, with an EGFR exon 19 deletion (ex19del) or exon 21 substitution (Leu858Arg) mutation, an Eastern Cooperative Oncology Group performance status of 0 or 1, and no CNS metastases. We randomly assigned eligible patients in a 1:1 ratio to receive oral erlotinib (150 mg/day) plus either intravenous ramucirumab (10 mg/kg) or matching placebo once every 2 weeks. Randomisation was done by an interactive web response system with a computer-generated sequence and stratified by sex, geographical region, EGFR mutation type, and EGFR testing method. The primary endpoint was investigator-assessed progression-free survival in the intention-to-treat population. Safety was assessed in all patients who received at least one dose of study treatment. This trial is registered at ClinicalTrials.gov, NCT02411448, and is ongoing for long-term survival follow-up.\n\nFindings: Between Jan 28, 2016, and Feb 1, 2018, 449 eligible patients were enrolled and randomly assigned to treatment with ramucirumab plus erlotinib (n=224) or placebo plus erlotinib (n=225). Median duration of follow-up was 20·7 months (IQR 15·8-27·2). At the time of primary analysis, progression-free survival was significantly longer in the ramucirumab plus erlotinib group (19·4 months [95% CI 15·4-21·6]) than in the placebo plus erlotinib group (12·4 months [11·0-13·5]), with a stratified hazard ratio of 0·59 (95% CI 0·46-0·76; p<0·0001). Grade 3-4 treatment-emergent adverse events were reported in 159 (72%) of 221 patients in the ramucirumab plus erlotinib group versus 121 (54%) of 225 in the placebo plus erlotinib group. The most common grade 3-4 treatment-emergent adverse events in the ramucirumab plus erlotinib group were hypertension (52 [24%]; grade 3 only) and dermatitis acneiform (33 [15%]), and in the placebo plus erlotinib group were dermatitis acneiform (20 [9%]) and increased alanine aminotransferase (17 [8%]). Treatment-emergent serious adverse events were reported in 65 (29%) of 221 patients in the ramucirumab plus erlotinib group and 47 (21%) of 225 in the placebo plus erlotinib group. The most common serious adverse events of any grade in the ramucirumab plus erlotinib group were pneumonia (seven [3%]) and cellulitis and pneumothorax (four [2%], each); the most common in the placebo plus erlotinib group were pyrexia (four [2%]) and pneumothorax (three [1%]). One on-study treatment-related death due to an adverse event occurred (haemothorax after a thoracic drainage procedure for a pleural empyema) in the ramucirumab plus erlotinib group.\n\nInterpretation: Ramucirumab plus erlotinib demonstrated superior progression-free survival compared with placebo plus erlotinib in patients with untreated EGFR-mutated metastatic NSCLC. Safety was consistent with the safety profiles of the individual compounds in advanced lung cancer. The RELAY regimen is a viable new treatment option for the initial treatment of EGFR-mutated metastatic NSCLC.\n\nFunding: Eli Lilly.\n\nIndexed on Europe PMC as PubMed record 31591063 (DOI 10.1016/s1470-2045(19)30634-5). Its abstract cites the registry id NCT02411448, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2019, doi: "10.1016/s1470-2045(19)30634-5", pmid: "31591063", authors: "Nakagawa K, Garon EB, Seto T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02411448 with the most citations, so it is the natural first reading for anyone following the RELAY trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2019","url":"https://doi.org/10.1016/s1470-2045(19)30634-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31591063/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31591063"},{"label":"ClinicalTrials.gov NCT02411448","url":"https://clinicaltrials.gov/study/NCT02411448"}], tags: ["europepmc-ingest"], trials: ["nct02411448"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct02411448-j-thorac-oncol-2025-update", name: "RELAY: Final Overall Survival for Erlotinib Plus Ramucirumab or Placebo in Untreated, EGFR-Mutated Metastatic NSCLC", tldr: "Later report from the RELAY trial registered as NCT02411448, in Journal of Thoracic Oncology (2025); its title describes an updated or longer-term analysis.", summary: "Introduction: RELAY, a global double-blind, placebo-controlled phase 3 study (NCT02411448) found statistically significant improvement in progression-free survival (primary end point) for ramucirumab (RAM) plus erlotinib (ERL) (RAM + ERL) in patients with untreated EGFR-mutated metastatic NSCLC (hazard ratio [HR] = 0.59, 95% confidence interval [CI]: 0.46-0.76, p < 0.0001; median progression-free survival: 19.4 versus 12.4 mo). Here, we report the final overall survival (OS; secondary end point) outcomes for the intention-to-treat population.\n\nMethods: Between January 2016 and February 2018, 449 eligible patients with an EGFR exon 19del or L858R mutation and no central nervous system metastases were randomized (1:1) to ERL (150 mg/day) with RAM (10 mg/kg every two weeks, N = 224) or placebo (N = 225).\n\nResults: At data cutoff, 297 deaths were reported (overall event rate = 66%), with a median follow-up of 45.1 months (interquartile range: 26.7-71.2), an OS HR of 0.98 (95% CI: 0.78-1.24, p = 0.864), and median OS of 51.1 months (RAM + ERL) and 46.0 months (placebo + ERL). Outcomes in subsets of patients with poor prognosis (L858R or TP53 co-mutation) suggest a directional improvement in OS (L858R: HR = 0.87, 95% CI: 0.62-1.22; exon 19del: HR = 1.13, 95% CI: 0.83-1.55; TP53 co-mutation: HR = 0.83, 95% CI: 0.58-1.19; TP53-wild-type: HR = 1.22, 95% CI: 0.87-1.72). Treatment-emergent T790M rates were similar between arms. Over 80% of patients received post-study discontinuation therapy (>50% received osimertinib in comparable numbers between arms). The safety profile for RAM + ERL was consistent with previous reports with no increased toxicity over time or new safety signals observed.\n\nConclusion: In RELAY, OS was not significantly improved with similar long OS durations in both treatment arms.\n\nClinical trial information: ClinicalTrials.gov Identifier: NCT02411448.\n\nIndexed on Europe PMC as PubMed record 39622410 (DOI 10.1016/j.jtho.2024.11.032). Its abstract cites the registry id NCT02411448, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2024.11.032", pmid: "39622410", authors: "Nakagawa K, Garon EB, Seto T, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the RELAY trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2024.11.032"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39622410/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39622410"},{"label":"ClinicalTrials.gov NCT02411448","url":"https://clinicaltrials.gov/study/NCT02411448"}], tags: ["europepmc-ingest"], trials: ["nct02411448"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct02453282-jama-oncol-2020", name: "Durvalumab With or Without Tremelimumab vs Standard Chemotherapy in First-line Treatment of Metastatic Non-Small Cell Lung Cancer: The MYSTIC Phase 3 Randomized Clinical Trial", tldr: "Published report from the MYSTIC trial registered as NCT02453282, in JAMA Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Checkpoint inhibitors targeting programmed cell death 1 or its ligand (PD-L1) as monotherapies or in combination with anti-cytotoxic T-lymphocyte-associated antigen 4 have shown clinical activity in patients with metastatic non-small cell lung cancer.\n\nObjective: To compare durvalumab, with or without tremelimumab, with chemotherapy as a first-line treatment for patients with metastatic non-small cell lung cancer.\n\nDesign, setting, and participants: This open-label, phase 3 randomized clinical trial (MYSTIC) was conducted at 203 cancer treatment centers in 17 countries. Patients with treatment-naive, metastatic non-small cell lung cancer who had no sensitizing EGFR or ALK genetic alterations were randomized to receive treatment with durvalumab, durvalumab plus tremelimumab, or chemotherapy. Data were collected from July 21, 2015, to October 30, 2018.\n\nInterventions: Patients were randomized (1:1:1) to receive treatment with durvalumab (20 mg/kg every 4 weeks), durvalumab (20 mg/kg every 4 weeks) plus tremelimumab (1 mg/kg every 4 weeks, up to 4 doses), or platinum-based doublet chemotherapy.\n\nMain outcomes and measures: The primary end points, assessed in patients with ≥25% of tumor cells expressing PD-L1, were overall survival (OS) for durvalumab vs chemotherapy, and OS and progression-free survival (PFS) for durvalumab plus tremelimumab vs chemotherapy. Analysis of blood tumor mutational burden (bTMB) was exploratory.\n\nResults: Between July 21, 2015, and June 8, 2016, 1118 patients were randomized. Baseline demographic and disease characteristics were balanced between treatment groups. Among 488 patients with ≥25% of tumor cells expressing PD-L1, median OS was 16.3 months (95% CI, 12.2-20.8) with durvalumab vs 12.9 months (95% CI, 10.5-15.0) with chemotherapy (hazard ratio [HR], 0.76; 97.54% CI, 0.56-1.02; P =.04 [nonsignificant]). Median OS was 11.9 months (95% CI, 9.0-17.7) with durvalumab plus tremelimumab (HR vs chemotherapy, 0.85; 98.77% CI, 0.61-1.17; P =.20). Median PFS was 3.9 months (95% CI, 2.8-5.0) with durvalumab plus tremelimumab vs 5.4 months (95% CI, 4.6-5.8) with chemotherapy (HR, 1.05; 99.5% CI, 0.72-1.53; P =.71). Among 809 patients with evaluable bTMB, those with a bTMB ≥20 mutations per megabase showed improved OS for durvalumab plus tremelimumab vs chemotherapy (median OS, 21.9 months [95% CI, 11.4-32.8] vs 10.0 months [95% CI, 8.1-11.7]; HR, 0.49; 95% CI, 0.32-0.74). Treatment-related adverse events of grade 3 or higher occurred in 55 (14.9%) of 369 patients who received treatment with durvalumab, 85 (22.9%) of 371 patients who received treatment with durvalumab plus tremelimumab, and 119 (33.8%) of 352 patients who received treatment with chemotherapy. These adverse events led to death in 2 (0.5%), 6 (1.6%), and 3 (0.9%) patients, respectively.\n\nConclusions and relevance: The phase 3 MYSTIC study did not meet its primary end points of improved OS with durvalumab vs chemotherapy or improved OS or PFS with durvalumab plus tremelimumab vs chemotherapy in patients with ≥25% of tumor cells expressing PD-L1. Exploratory analyses identified a bTMB threshold of ≥20 mutations per megabase for optimal OS benefit with durvalumab plus tremelimumab.\n\nTrial registration: ClinicalT rials.gov Identifier: NCT02453282.\n\nIndexed on Europe PMC as PubMed record 32271377 (DOI 10.1001/jamaoncol.2020.0237). Its abstract cites the registry id NCT02453282, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2020, doi: "10.1001/jamaoncol.2020.0237", pmid: "32271377", authors: "Rizvi NA, Cho BC, Reinmuth N, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02453282 with the most citations, so it is the natural first reading for anyone following the MYSTIC trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2020","url":"https://doi.org/10.1001/jamaoncol.2020.0237"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32271377/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32271377"},{"label":"ClinicalTrials.gov NCT02453282","url":"https://clinicaltrials.gov/study/NCT02453282"}], tags: ["europepmc-ingest"], trials: ["nct02453282"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct02486718-lancet-2021", name: "Adjuvant atezolizumab after adjuvant chemotherapy in resected stage IB-IIIA non-small-cell lung cancer (IMpower010): a randomised, multicentre, open-label, phase 3 trial", tldr: "Published report from the trial registered as NCT02486718, in The Lancet (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Novel adjuvant strategies are needed to optimise outcomes after complete surgical resection in patients with early-stage non-small-cell lung cancer (NSCLC). We aimed to evaluate adjuvant atezolizumab versus best supportive care after adjuvant platinum-based chemotherapy in these patients.\n\nMethods: IMpower010 was a randomised, multicentre, open-label, phase 3 study done at 227 sites in 22 countries and regions. Eligible patients were 18 years or older with completely resected stage IB (tumours ≥4 cm) to IIIA NSCLC per the Union Internationale Contre le Cancer and American Joint Committee on Cancer staging system (7th edition). Patients were randomly assigned (1:1) by a permuted-block method (block size of four) to receive adjuvant atezolizumab (1200 mg every 21 days; for 16 cycles or 1 year) or best supportive care (observation and regular scans for disease recurrence) after adjuvant platinum-based chemotherapy (one to four cycles). The primary endpoint, investigator-assessed disease-free survival, was tested hierarchically first in the stage II-IIIA population subgroup whose tumours expressed PD-L1 on 1% or more of tumour cells (SP263), then all patients in the stage II-IIIA population, and finally the intention-to-treat (ITT) population (stage IB-IIIA). Safety was evaluated in all patients who were randomly assigned and received atezolizumab or best supportive care. IMpower010 is registered with ClinicalTrials.gov, NCT02486718 (active, not recruiting).\n\nFindings: Between Oct 7, 2015, and Sept 19, 2018, 1280 patients were enrolled after complete resection. 1269 received adjuvant chemotherapy, of whom 1005 patients were eligible for randomisation to atezolizumab (n=507) or best supportive care (n=498); 495 in each group received treatment. After a median follow-up of 32·2 months (IQR 27·4-38·3) in the stage II-IIIA population, atezolizumab treatment improved disease-free survival compared with best supportive care in patients in the stage II-IIIA population whose tumours expressed PD-L1 on 1% or more of tumour cells (HR 0·66; 95% CI 0·50-0·88; p=0·0039) and in all patients in the stage II-IIIA population (0·79; 0·64-0·96; p=0·020). In the ITT population, HR for disease-free survival was 0·81 (0·67-0·99; p=0·040). Atezolizumab-related grade 3 and 4 adverse events occurred in 53 (11%) of 495 patients and grade 5 events in four patients (1%).\n\nInterpretation: IMpower010 showed a disease-free survival benefit with atezolizumab versus best supportive care after adjuvant chemotherapy in patients with resected stage II-IIIA NSCLC, with pronounced benefit in the subgroup whose tumours expressed PD-L1 on 1% or more of tumour cells, and no new safety signals. Atezolizumab after adjuvant chemotherapy offers a promising treatment option for patients with resected early-stage NSCLC.\n\nFunding: F Hoffmann-La Roche and Genentech.\n\nIndexed on Europe PMC as PubMed record 34555333 (DOI 10.1016/s0140-6736(21)02098-5). Its abstract cites the registry id NCT02486718, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2021, doi: "10.1016/s0140-6736(21)02098-5", pmid: "34555333", authors: "Felip E, Altorki N, Zhou C, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02486718 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2021","url":"https://doi.org/10.1016/s0140-6736(21)02098-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34555333/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34555333"},{"label":"ClinicalTrials.gov NCT02486718","url":"https://clinicaltrials.gov/study/NCT02486718"}], tags: ["europepmc-ingest"], trials: ["nct02486718"], journals: ["lancet"] }),
  p({ id: "paper-nct02486718-ann-oncol-2023-update", name: "Overall survival with adjuvant atezolizumab after chemotherapy in resected stage II-IIIA non-small-cell lung cancer (IMpower010): a randomised, multicentre, open-label, phase III trial", tldr: "Later report from the trial registered as NCT02486718, in Annals of Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Background: IMpower010 (NCT02486718) demonstrated significantly improved disease-free survival (DFS) with adjuvant atezolizumab versus best supportive care (BSC) following platinum-based chemotherapy in the programmed death-ligand 1 (PD-L1)-positive and all stage II-IIIA non-small-cell lung cancer (NSCLC) populations, at the DFS interim analysis. Results of the first interim analysis of overall survival (OS) are reported here.\n\nPatient and methods: The design, participants, and primary-endpoint DFS outcomes have been reported for this phase III, open-label, 1: 1 randomised study of atezolizumab (1200 mg q3w; 16 cycles) versus BSC after adjuvant platinum-based chemotherapy (1-4 cycles) in adults with completely resected stage IB (≥4 cm)-IIIA NSCLC (per the Union Internationale Contre le Cancer and American Joint Committee on Cancer staging system, 7th edition). Key secondary endpoints included OS in the stage IB-IIIA intent-to-treat (ITT) population and safety in randomised treated patients. The first pre-specified interim analysis of OS was conducted after 251 deaths in the ITT population. Exploratory analyses included OS by baseline PD-L1 expression level (SP263 assay).\n\nResults: At a median of 45.3 months' follow-up on 18 April 2022, 127 of 507 patients (25%) in the atezolizumab arm and 124 of 498 (24.9%) in the BSC arm had died. The median OS in the ITT population was not estimable; the stratified hazard ratio (HR) was 0.995 [95% confidence interval (CI) 0.78-1.28]. The stratified OS HRs (95% CI) were 0.95 (0.74-1.24) in the stage II-IIIA (n = 882), 0.71 (0.49-1.03) in the stage II-IIIA PD-L1 tumour cell (TC) ≥1% (n = 476), and 0.43 (95% CI 0.24-0.78) in the stage II-IIIA PD-L1 TC ≥50% (n = 229) populations. Atezolizumab-related adverse event incidences remained unchanged since the previous analysis [grade 3/4 in 53 (10.7%) and grade 5 in 4 (0.8%) of 495 patients, respectively].\n\nConclusions: Although OS remains immature for the ITT population, these data indicate a positive trend favouring atezolizumab in PD-L1 subgroup analyses, primarily driven by the PD-L1 TC ≥50% stage II-IIIA subgroup. No new safety signals were observed after 13 months' additional follow-up. Together, these findings support the positive benefit-risk profile of adjuvant atezolizumab in this setting.\n\nIndexed on Europe PMC as PubMed record 37467930 (DOI 10.1016/j.annonc.2023.07.001). Its abstract cites the registry id NCT02486718, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2023, doi: "10.1016/j.annonc.2023.07.001", pmid: "37467930", authors: "Felip E, Altorki N, Zhou C, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2023","url":"https://doi.org/10.1016/j.annonc.2023.07.001"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37467930/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37467930"},{"label":"ClinicalTrials.gov NCT02486718","url":"https://clinicaltrials.gov/study/NCT02486718"}], tags: ["europepmc-ingest"], trials: ["nct02486718"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct02716116-jama-oncol-2021", name: "Treatment Outcomes and Safety of Mobocertinib in Platinum-Pretreated Patients With EGFR Exon 20 Insertion-Positive Metastatic Non-Small Cell Lung Cancer: A Phase 1/2 Open-label Nonrandomized Clinical Trial", tldr: "Published report from the trial registered as NCT02716116, in JAMA Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Metastatic non-small cell lung cancer (mNSCLC) with EGFR exon 20 insertion (EGFRex20ins) mutations is associated with a poor prognosis. Mobocertinib is an oral tyrosine kinase inhibitor designed to selectively target EGFRex20ins mutations.\n\nObjective: To evaluate treatment outcomes and safety of mobocertinib in patients with previously treated EGFRex20ins-positive mNSCLC.\n\nDesign, setting, and participants: This 3-part, open-label, phase 1/2 nonrandomized clinical trial with dose-escalation/dose-expansion cohorts (28 sites in the US) and a single-arm extension cohort (EXCLAIM; 40 sites in Asia, Europe, and North America) was conducted between June 2016 and November 2020 (data cutoff date). The primary analysis populations were the platinum-pretreated patients (PPP) cohort and the EXCLAIM cohort. The PPP cohort included 114 patients with platinum-pretreated EGFRex20ins-positive mNSCLC who received mobocertinib 160 mg once daily from the dose-escalation (n = 6), dose-expansion (n = 22), and EXCLAIM (n = 86) cohorts. The EXCLAIM cohort included 96 patients with previously treated EGFRex20ins-positive mNSCLC (10 were not platinum pretreated and thus were excluded from the PPP cohort).\n\nInterventions: Mobocertinib 160 mg once daily.\n\nMain outcomes and measures: The primary end point of the PPP and EXCLAIM cohorts was confirmed objective response rate (ORR) assessed by independent review committee (IRC). Secondary end points included confirmed ORR by investigator, duration of response, progression-free survival, overall survival, and safety.\n\nResults: Among the PPP (n = 114) and EXCLAIM (n = 96) cohorts, the median (range) age was 60 (27-84) and 59 (27-80) years, respectively; most patients were women (75 [66%] and 62 [65%], respectively) and of Asian race (68 [60%] and 66 [69%], respectively). At data cutoff, median follow-up was 14.2 months in the PPP cohort (median 2 prior anticancer regimens; 40 [35%] had baseline brain metastases), with confirmed ORR of 28% (95% CI, 20%-37%) by IRC assessment and 35% (95% CI, 26%-45%) by investigator assessment; median duration of response by IRC assessment was 17.5 months (95% CI, 7.4-20.3). Median progression-free survival by IRC assessment was 7.3 months (95% CI, 5.5-9.2). Median overall survival was 24.0 months (95% CI, 14.6-28.8). In the EXCLAIM cohort, median follow-up was 13.0 months, with confirmed ORR by IRC assessment of 25% (95% CI, 17%-35%) and by investigator assessment of 32% (95% CI, 23%-43%). The most common treatment-related adverse events were diarrhea and rash.\n\nConclusions and relevance: In this open-label, phase 1/2 nonrandomized clinical trial, mobocertinib was associated with clinically meaningful benefit in patients with previously treated EGFRex20ins-positive mNSCLC, with a manageable safety profile.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02716116.\n\nIndexed on Europe PMC as PubMed record 34647988 (DOI 10.1001/jamaoncol.2021.4761). Its abstract cites the registry id NCT02716116, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2021, doi: "10.1001/jamaoncol.2021.4761", pmid: "34647988", authors: "Zhou C, Ramalingam SS, Kim TM, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02716116 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2021","url":"https://doi.org/10.1001/jamaoncol.2021.4761"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34647988/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34647988"},{"label":"ClinicalTrials.gov NCT02716116","url":"https://clinicaltrials.gov/study/NCT02716116"}], tags: ["europepmc-ingest"], trials: ["nct02716116"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct02734004-lancet-oncol-2020", name: "Olaparib and durvalumab in patients with germline BRCA-mutated metastatic breast cancer (MEDIOLA): an open-label, multicentre, phase 1/2, basket study", tldr: "Published report from the MEDIOLA trial registered as NCT02734004, in The Lancet Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Poly (ADP-ribose) polymerase inhibitors combined with immunotherapy have shown antitumour activity in preclinical studies. We aimed to assess the safety and activity of olaparib in combination with the PD-L1-inhibitor, durvalumab, in patients with germline BRCA1-mutated or BRCA2-mutated metastatic breast cancer.\n\nMethods: The MEDIOLA trial is a multicentre, open-label, phase 1/2, basket trial of durvalumab and olaparib in solid tumours. Patients were enrolled into four initial cohorts: germline BRCA-mutated, metastatic breast cancer; germline BRCA-mutated, metastatic ovarian cancer; metastatic gastric cancer; and relapsed small-cell lung cancer. Here, we report on the cohort of patients with breast cancer. Patients who were aged 18 years or older (or aged 19 years or older in South Korea) with germline BRCA1-mutated or BRCA2-mutated or both and histologically confirmed, progressive, HER2-negative, metastatic breast cancer were enrolled from 14 health centres in the UK, the USA, Israel, France, Switzerland, and South Korea. Patients should not have received more than two previous lines of chemotherapy for metastatic breast cancer. Patients received 300 mg olaparib in tablet form orally twice daily for 4 weeks and thereafter a combination of olaparib 300 mg twice daily and durvalumab 1·5 g via intravenous infusion every 4 weeks until disease progression. Primary endpoints were safety and tolerability, and 12-week disease control rate. Safety was analysed in patients who received at least one dose of study treatment, and activity analyses were done in the full-analysis set (patients who received at least one dose of study treatment and were not excluded from the study). Recruitment has completed and the study is ongoing. This trial is registered with ClinicalTrials.gov, NCT02734004.\n\nFindings: Between June 14, 2016, and May 2, 2017, 34 patients were enrolled and received both study drugs and were included in the safety analysis. 11 (32%) patients experienced grade 3 or worse adverse events, of which the most common were anaemia (four [12%]), neutropenia (three [9%]), and pancreatitis (two [6%]). Three (9%) patients discontinued due to adverse events and four (12%) patients experienced a total of six serious adverse events. There were no treatment-related deaths. 24 (80%; 90% CI 64·3-90·9) of 30 patients eligible for activity analysis had disease control at 12 weeks.\n\nInterpretation: Combination of olaparib and durvalumab showed promising antitumour activity and safety similar to that previously observed in olaparib and durvalumab monotherapy studies. Further research in a randomised setting is needed to determine predictors of therapeutic benefit and whether addition of durvalumab improves long-term clinical outcomes compared with olaparib monotherapy.\n\nFunding: AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 32771088 (DOI 10.1016/s1470-2045(20)30324-7). Its abstract cites the registry id NCT02734004, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2020, doi: "10.1016/s1470-2045(20)30324-7", pmid: "32771088", authors: "Domchek SM, Postel-Vinay S, Im SA, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02734004 with the most citations, so it is the natural first reading for anyone following the MEDIOLA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2020","url":"https://doi.org/10.1016/s1470-2045(20)30324-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32771088/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32771088"},{"label":"ClinicalTrials.gov NCT02734004","url":"https://clinicaltrials.gov/study/NCT02734004"}], tags: ["europepmc-ingest"], trials: ["nct02734004"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct02767804-jama-oncol-2021", name: "Ensartinib vs Crizotinib for Patients With Anaplastic Lymphoma Kinase-Positive Non-Small Cell Lung Cancer: A Randomized Clinical Trial", tldr: "Published report from the trial registered as NCT02767804, in JAMA Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Ensartinib, an oral tyrosine kinase inhibitor of anaplastic lymphoma kinase (ALK), has shown systemic and central nervous system efficacy for patients with ALK-positive non-small cell lung cancer (NSCLC).\n\nObjective: To compare ensartinib with crizotinib among patients with advanced ALK-positive NSCLC who had not received prior treatment with an ALK inhibitor.\n\nDesign, setting, and participants: This open-label, multicenter, randomized, phase 3 trial conducted in 120 centers in 21 countries enrolled 290 patients between July 25, 2016, and November 12, 2018. Eligible patients were 18 years of age or older and had advanced, recurrent, or metastatic ALK-positive NSCLC.\n\nInterventions: Patients were randomized (1:1) to ensartinib, 225 mg once daily, or crizotinib, 250 mg twice daily.\n\nMain outcomes and measures: The primary end point was blinded independent review committee-assessed progression-free survival (PFS). Secondary end points included systemic and intracranial response, time to central nervous system progression, and overall survival. Efficacy was evaluated in the intent-to-treat (ITT) population as well as a prespecified modified ITT (mITT) population consisting of patients with central laboratory-confirmed ALK-positive NSCLC.\n\nResults: A total of 290 patients (149 men [51.4%]; median age, 54 years [range, 25-90 years]) were randomized. In the ITT population, the median PFS was significantly longer with ensartinib than with crizotinib (25.8 [range, 0.03-44.0 months] vs 12.7 months [range, 0.03-38.6 months]; hazard ratio, 0.51 [95% CI, 0.35-0.72]; log-rank P <.001), with a median follow-up of 23.8 months (range, 0-44 months) for the ensartinib group and 20.2 months (range, 0-38 months) for the crizotinib group. In the mITT population, the median PFS in the ensartinib group was not reached, and the median PFS in the crizotinib group was 12.7 months (95% CI, 8.9-16.6 months; hazard ratio, 0.45; 95% CI, 0.30-0.66; log-rank P <.001). The intracranial response rate confirmed by a blinded independent review committee was 63.6% (7 of 11) with ensartinib vs 21.1% (4 of 19) with crizotinib for patients with target brain metastases at baseline. Progression-free survival for patients without brain metastases was not reached with ensartinib vs 16.6 months with crizotinib as a result of a lower central nervous system progression rate (at 12 months: 4.2% with ensartinib vs 23.9% with crizotinib; cause-specific hazard ratio, 0.32; 95% CI, 0.16-0.63; P =.001). Frequencies of treatment-related serious adverse events (ensartinib: 11 [7.7%] vs crizotinib: 9 [6.1%]), dose reductions (ensartinib: 34 of 143 [23.8%] vs crizotinib: 29 of 146 [19.9%]), or drug discontinuations (ensartinib: 13 of 143 [9.1%] vs crizotinib: 10 of 146 [6.8%]) were similar, without any new safety signals.\n\nConclusions and relevance: In this randomized clinical trial, ensartinib showed superior efficacy to crizotinib in both systemic and intracranial disease. Ensartinib represents a new first-line option for patients with ALK-positive NSCLC.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02767804.\n\nIndexed on Europe PMC as PubMed record 34473194 (DOI 10.1001/jamaoncol.2021.3523). Its abstract cites the registry id NCT02767804, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2021, doi: "10.1001/jamaoncol.2021.3523", pmid: "34473194", authors: "Horn L, Wang Z, Wu G, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02767804 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2021","url":"https://doi.org/10.1001/jamaoncol.2021.3523"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34473194/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34473194"},{"label":"ClinicalTrials.gov NCT02767804","url":"https://clinicaltrials.gov/study/NCT02767804"}], tags: ["europepmc-ingest"], trials: ["nct02767804"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct02864992-jama-oncol-2023-update", name: "Tepotinib Treatment in Patients With MET Exon 14-Skipping Non-Small Cell Lung Cancer: Long-term Follow-up of the VISION Phase 2 Nonrandomized Clinical Trial", tldr: "Later report from the trial registered as NCT02864992, in JAMA Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Importance: MET inhibitors have recently demonstrated clinical activity in patients with MET exon 14 (METex14)-skipping non-small cell lung cancer (NSCLC); however, data with longer follow-up and in larger populations are needed to further optimize therapeutic approaches.\n\nObjective: To assess the long-term efficacy and safety of tepotinib, a potent and highly selective MET inhibitor, in patients with METex14-skipping NSCLC in the VISION study.\n\nDesign, setting, and participants: The VISION phase 2 nonrandomized clinical trial was a multicohort, open-label, multicenter study that enrolled patients with METex14-skipping advanced/metastatic NSCLC (cohorts A and C) from September 2016 to May 2021. Cohort C (>18 months' follow-up) was an independent cohort, designed to confirm findings from cohort A (>35 months' follow-up). Data cutoff was November 20, 2022.\n\nIntervention: Patients received tepotinib, 500 mg (450 mg active moiety), once daily.\n\nMain outcomes and measures: The primary end point was objective response by independent review committee (RECIST v1.1). Secondary end points included duration of response (DOR), progression-free survival (PFS), overall survival (OS), and safety.\n\nResults: Cohorts A and C included 313 patients (50.8% female, 33.9% Asian; median [range] age, 72 [41-94] years). The objective response rate (ORR) was 51.4% (95% CI, 45.8%-57.1%) with a median (m)DOR of 18.0 (95% CI, 12.4-46.4) months. In cohort C (n = 161), an ORR of 55.9% (95% CI, 47.9%-63.7%) with an mDOR of 20.8 (95% CI, 12.6-not estimable [NE]) months was reported across treatment lines, comparable to cohort A (n = 152). In treatment-naive patients (cohorts A and C; n = 164), ORR was 57.3% (95% CI, 49.4%-65.0%) and mDOR was 46.4 (95% CI, 13.8-NE) months. In previously treated patients (n = 149), ORR was 45.0% (95% CI, 36.8%-53.3%) and mDOR was 12.6 (95% CI, 9.5-18.5) months. Peripheral edema, the most common treatment-related adverse event, occurred in 210 patients (67.1%) (35 [11.2%] experienced grade ≥3 events).\n\nConclusions and relevance: The findings from cohort C in this nonrandomized clinical trial supported the results from original cohort A. Overall, the long-term outcomes of VISION demonstrated robust and durable clinical activity following treatment with tepotinib, particularly in the treatment-naive setting, in the largest known clinical trial of patients with METex14-skipping NSCLC, supporting the global approvals of tepotinib and enabling clinicians to implement this therapeutic approach for such patients.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02864992.\n\nIndexed on Europe PMC as PubMed record 37270698 (DOI 10.1001/jamaoncol.2023.1962). Its abstract cites the registry id NCT02864992, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2023, doi: "10.1001/jamaoncol.2023.1962", pmid: "37270698", authors: "Mazieres J, Paik PK, Garassino MC, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"JAMA Oncol 2023","url":"https://doi.org/10.1001/jamaoncol.2023.1962"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37270698/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37270698"},{"label":"ClinicalTrials.gov NCT02864992","url":"https://clinicaltrials.gov/study/NCT02864992"}], tags: ["europepmc-ingest"], trials: ["nct02864992"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct03003962-j-thorac-oncol-2025", name: "Durvalumab Versus Chemotherapy as First-line Treatment for Metastatic NSCLC With Tumor PD-L1 Expression of 25% or Higher: Results From the Randomized Phase 3 PEARL Study", tldr: "Published report from the PEARL trial registered as NCT03003962, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: PEARL (NCT03003962) is an open-label, phase 3 study comparing first-line durvalumab monotherapy with chemotherapy in patients with metastatic NSCLC (mNSCLC [EGFR/ALK wild type]) with programmed cell death ligand 1 (PD-L1) tumor cell (TC) membrane expression status of 25% or higher. We report the final analysis of PEARL.\n\nMethods: Adults (N = 669) with previously untreated stage IV mNSCLC were randomized (1:1) to durvalumab 20 mg/kg every four weeks or chemotherapy every three weeks for four to six cycles. The dual primary endpoints were overall survival (OS) in the population with PD-L1 TC of 25% or higher and OS in the population at low risk of early mortality (LREM) with PD-L1 TC of 25% or higher.\n\nResults: Durvalumab was associated with a numerical reduction in the risk of death versus chemotherapy in the 25% and higher PD-L1 TC population (OS hazard ratio [HR] = 0.84, 95% confidence interval [CI]: 0.71-0.99, p = 0.037; median OS 14.6 months, 95% CI: 12.2-16.9 versus 12.8 months, 95% CI: 10.1-14.7, respectively). In the 25% and higher PD-L1 TC low risk of early mortality population the OS hazard ratio for durvalumab versus chemotherapy was 0.96 (95% CI: 0.79-1.15, p = 0.628); median OS 14.6 months (95% CI: 12.6-17.2) versus 15.0 months (95% CI: 13.1-16.8), respectively. In the safety population, the incidence of grade 3 or 4 treatment-related adverse events was 15.5% (durvalumab) and 45.9% (chemotherapy).\n\nConclusions: Durvalumab did not statistically significantly improve OS versus chemotherapy as first-line treatment in patients with mNSCLC and 25% and higher PD-L1 TC. The numerical improvement in OS was consistent with previous studies of first-line immune checkpoint inhibitor monotherapy in patients with mNSCLC.\n\nIndexed on Europe PMC as PubMed record 39521433 (DOI 10.1016/j.jtho.2024.10.024). Its abstract cites the registry id NCT03003962, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2024.10.024", pmid: "39521433", authors: "Lu S, Wu L, Wang Q, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03003962 with the most citations, so it is the natural first reading for anyone following the PEARL trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2024.10.024"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39521433/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39521433"},{"label":"ClinicalTrials.gov NCT03003962","url":"https://clinicaltrials.gov/study/NCT03003962"}], tags: ["europepmc-ingest"], trials: ["nct03003962"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct03157128-j-clin-oncol-2024-update", name: "Durability of Response With Selpercatinib in Patients With RET -Activated Thyroid Cancer: Long-Term Safety and Efficacy From LIBRETTO-001", tldr: "Later report from the RET Fusion-Positive Solid Tumors trial registered as NCT03157128, in Journal of Clinical Oncology (2024); its title describes an updated or longer-term analysis.", summary: "Clinical trials frequently include multiple end points that mature at different times. The initial report, typically based on the primary end point, may be published when key planned co-primary or secondary analyses are not yet available. Clinical Trial Updates provide an opportunity to disseminate additional results from studies, published in JCO or elsewhere, for which the primary end point has already been reported. LIBRETTO-001 is a registrational phase I/II, single-arm, open-label study of selpercatinib in patients with RET (REarranged during Transfection)-activated cancers (ClinicalTrials.gov identifier: NCT03157128). We present long-term safety and efficacy from LIBRETTO-001 in patients with RET -mutant medullary thyroid cancer (MTC; n = 324) and RET fusion-positive thyroid cancer encompassing different histological subtypes (TC; n = 66). At the data cutoff of January 2023, the objective response rate was 82.5% among patients with cabozantinib/vandetanib-naïve MTC and 95.8% among patients with treatment-naïve TC. At a median follow-up time of 42.4 and 44.0 months in patients with cabozantinib/vandetanib-naïve and pretreated MTC, the median progression-free survival (PFS) was not reached and 41.4 months, respectively. At a median follow-up time of 24.9 and 30.4 months in patients with treatment-naïve and pretreated TC, the median PFS was not reached and 27.4 months, respectively. Three-year PFS rates were 75.2% and 87.3% among patients with cabozantinib/vandetanib-naïve MTC and treatment-naïve TC, respectively. Median PFS was similar to median duration of response for each patient group. The safety profile of selpercatinib was consistent with previous reports. With an additional follow-up of 37 months and 228 more patients from the last disclosure, selpercatinib continued to provide durable and robust responses in treatment-naïve and previously treated patients with RET -mutant MTC and RET fusion-positive TC.\n\nIndexed on Europe PMC as PubMed record 39094065 (DOI 10.1200/jco.23.02503). Its abstract cites the registry id NCT03157128, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2024, doi: "10.1200/jco.23.02503", pmid: "39094065", authors: "Wirth LJ, Brose MS, Subbiah V, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the RET Fusion-Positive Solid Tumors trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2024","url":"https://doi.org/10.1200/jco.23.02503"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39094065/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39094065"},{"label":"ClinicalTrials.gov NCT03157128","url":"https://clinicaltrials.gov/study/NCT03157128"}], tags: ["europepmc-ingest"], trials: ["nct03157128"], journals: ["jco"] }),
  p({ id: "paper-nct03178552-nat-med-2022", name: "Atezolizumab versus chemotherapy in advanced or metastatic NSCLC with high blood-based tumor mutational burden: primary analysis of BFAST cohort C randomized phase 3 trial", tldr: "Published report from the B-FAST trial registered as NCT03178552, in Nature Medicine (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Tumor mutational burden (TMB) is being explored as a predictive biomarker for cancer immunotherapy outcomes in non-small cell lung cancer. BFAST (NCT03178552)-an open-label, global, multicohort trial-evaluated the safety and efficacy of first-line targeted therapies or immunotherapy in patients with unresectable Stage IIIB or IV advanced or metastatic non-small cell lung cancer who were selected for biomarker status using blood-based targeted next-generation sequencing. In the Phase 3 cohort C evaluating blood-based (b)TMB as a biomarker of atezolizumab efficacy, patients with bTMB of ≥10 (N = 471) were randomized 1:1 to receive atezolizumab or platinum-based chemotherapy per local standard of care. Cohort C did not meet its primary endpoint of investigator-assessed progression-free survival in the population with bTMB of ≥16 (hazard ratio, 0.77; 95% confidence interval: 0.59, 1.00; P = 0.053). Adverse events leading to treatment withdrawal occurred in 10% of patients in the atezolizumab arm and 20% in the chemotherapy arm. Adverse events of special interest occurred in 42% of patients in the atezolizumab arm and 26% in the chemotherapy arm. A prespecified exploratory analysis compared the bTMB clinical trial assay with the FoundationOne Liquid Companion Diagnostic assay and showed high concordance between assays. Additional exploration of bTMB to identify optimal cutoffs, confounding factors, assay improvements or cooperative biomarkers is warranted.\n\nIndexed on Europe PMC as PubMed record 35995953 (DOI 10.1038/s41591-022-01933-w). Its abstract cites the registry id NCT03178552, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2022, doi: "10.1038/s41591-022-01933-w", pmid: "35995953", authors: "Peters S, Dziadziuszko R, Morabito A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03178552 with the most citations, so it is the natural first reading for anyone following the B-FAST trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2022","url":"https://doi.org/10.1038/s41591-022-01933-w"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35995953/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35995953"},{"label":"ClinicalTrials.gov NCT03178552","url":"https://clinicaltrials.gov/study/NCT03178552"}], tags: ["europepmc-ingest"], trials: ["nct03178552"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct03334617-nat-med-2024", name: "Biomarker-directed targeted therapy plus durvalumab in advanced non-small-cell lung cancer: a phase 2 umbrella trial", tldr: "Published report from the PD-L1 Containing Therapy trial registered as NCT03334617, in Nature Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "For patients with non-small-cell lung cancer (NSCLC) tumors without currently targetable molecular alterations, standard-of-care treatment is immunotherapy with anti-PD-(L)1 checkpoint inhibitors, alone or with platinum-doublet therapy. However, not all patients derive durable benefit and resistance to immune checkpoint blockade is common. Understanding mechanisms of resistance-which can include defects in DNA damage response and repair pathways, alterations or functional mutations in STK11/LKB1, alterations in antigen-presentation pathways, and immunosuppressive cellular subsets within the tumor microenvironment-and developing effective therapies to overcome them, remains an unmet need. Here the phase 2 umbrella HUDSON study evaluated rational combination regimens for advanced NSCLC following failure of anti-PD-(L)1-containing immunotherapy and platinum-doublet therapy. A total of 268 patients received durvalumab (anti-PD-L1 monoclonal antibody)-ceralasertib (ATR kinase inhibitor), durvalumab-olaparib (PARP inhibitor), durvalumab-danvatirsen (STAT3 antisense oligonucleotide) or durvalumab-oleclumab (anti-CD73 monoclonal antibody). Greatest clinical benefit was observed with durvalumab-ceralasertib; objective response rate (primary outcome) was 13.9% (11/79) versus 2.6% (5/189) with other regimens, pooled, median progression-free survival (secondary outcome) was 5.8 (80% confidence interval 4.6-7.4) versus 2.7 (1.8-2.8) months, and median overall survival (secondary outcome) was 17.4 (14.1-20.3) versus 9.4 (7.5-10.6) months. Benefit with durvalumab-ceralasertib was consistent across known immunotherapy-refractory subgroups. In ATM-altered patients hypothesized to harbor vulnerability to ATR inhibition, objective response rate was 26.1% (6/23) and median progression-free survival/median overall survival were 8.4/22.8 months. Durvalumab-ceralasertib safety/tolerability profile was manageable. Biomarker analyses suggested that anti-PD-L1/ATR inhibition induced immune changes that reinvigorated antitumor immunity. Durvalumab-ceralasertib is under further investigation in immunotherapy-refractory NSCLC.ClinicalTrials.gov identifier: NCT03334617.\n\nIndexed on Europe PMC as PubMed record 38351187 (DOI 10.1038/s41591-024-02808-y). Its abstract cites the registry id NCT03334617, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2024, doi: "10.1038/s41591-024-02808-y", pmid: "38351187", authors: "Besse B, Pons-Tostivint E, Park K, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03334617 with the most citations, so it is the natural first reading for anyone following the PD-L1 Containing Therapy trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2024","url":"https://doi.org/10.1038/s41591-024-02808-y"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38351187/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38351187"},{"label":"ClinicalTrials.gov NCT03334617","url":"https://clinicaltrials.gov/study/NCT03334617"}], tags: ["europepmc-ingest"], trials: ["nct03334617"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct03381274-j-thorac-oncol-2023", name: "CD73 Inhibitor Oleclumab Plus Osimertinib in Previously Treated Patients With Advanced T790M-Negative EGFR-Mutated NSCLC: A Brief Report", tldr: "Published report from the trial registered as NCT03381274, in Journal of Thoracic Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: CD73 is overexpressed in EGFR-mutated NSCLC and may promote immune evasion, suggesting potential for combining CD73 blockers with EGFR tyrosine kinase inhibitors (TKIs). This phase 1b-2 study (NCT03381274) evaluated the anti-CD73 antibody oleclumab plus the third-generation EGFR TKI osimertinib in advanced EGFR-mutated NSCLC.\n\nMethods: Patients had tissue T790M-negative NSCLC with TKI-sensitive EGFR mutations after progression on a first- or second-generation EGFR TKI and were osimertinib naive. They received osimertinib 80 mg orally once daily plus oleclumab 1500 mg (dose level 1 [DL1]) or 3000 mg (DL2) intravenously every 2 weeks. Primary end points included safety and objective response rate by Response Evaluation Criteria in Solid Tumors version 1.1.\n\nResults: By July 9, 2021, five patients received DL1 and 21 received DL2. Of these patients, 60.0% and 85.7% had any-grade treatment-related adverse events (TRAEs) and 20.0% and 14.3% had grade 3 TRAEs, respectively. No dose-limiting toxicities, serious TRAEs, or deaths occurred. Four patients were T790M positive on retrospective circulating tumor DNA (ctDNA) testing; three had objective partial responses. In patients who were T790M negative in tumor and ctDNA, objective response rate was 25.0% at DL1 and 11.8% at DL2 (all partial responses); response durations at DL2 were 14.8 and 16.6 months. In patients receiving DL2, excluding those who were T790M positive by ctDNA, median progression-free survival was 7.4 months, and median overall survival was 24.8 months. DL2 was the recommended phase 2 dose.\n\nConclusions: Oleclumab plus osimertinib was found to have moderate activity with acceptable tolerability in previously treated patients with advanced EGFR-mutated NSCLC.\n\nIndexed on Europe PMC as PubMed record 36641093 (DOI 10.1016/j.jtho.2022.12.021). Its abstract cites the registry id NCT03381274, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2023, doi: "10.1016/j.jtho.2022.12.021", pmid: "36641093", authors: "Kim DW, Kim SW, Camidge DR, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03381274 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2023","url":"https://doi.org/10.1016/j.jtho.2022.12.021"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36641093/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36641093"},{"label":"ClinicalTrials.gov NCT03381274","url":"https://clinicaltrials.gov/study/NCT03381274"}], tags: ["europepmc-ingest"], trials: ["nct03381274"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct03476681-j-exp-clin-cancer-res-2023", name: "First-in-human phase 1 clinical trial of anti-core 1 O-glycans targeting monoclonal antibody NEO-201 in treatment-refractory solid tumors", tldr: "Published report from the trial registered as NCT03476681, in Journal of experimental & clinical cancer research (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: NEO201 is a humanized IgG1 monoclonal antibody (mAb) generated against tumor-associated antigens from patients with colorectal cancer. NEO-201 binds to core 1 or extended core 1 O-glycans expressed by its target cells. Here, we present outcomes from a phase I trial of NEO-201 in patients with advanced solid tumors that have not responded to standard treatments.\n\nMethods: This was a single site, open label 3 + 3 dose escalation clinical trial. NEO-201 was administered intravenously every two weeks in a 28-day cycle at dose level (DL) 1 (1 mg/kg), DL 1.5 (1.5 mg/kg) and DL 2 (2 mg/kg) until dose limiting toxicity (DLT), disease progression, or patient withdrawal. Disease evaluations were conducted after every 2 cycles. The primary objective was to assess the maximum tolerated dose (MTD) and recommended phase 2 dose (RP2D) of NEO-201. The secondary objective was to assess the antitumor activity by RECIST v1.1. The exploratory objectives assessed pharmacokinetics and the effect of NEO-201 administration on immunologic parameters and their impact on clinical response.\n\nResults: Seventeen patients (11 colorectal, 4 pancreatic and 2 breast cancers) were enrolled; 2 patients withdrew after the first dose and were not evaluable for DLT. Twelve of the 15 patients evaluable for safety discontinued due to disease progression and 3 patients discontinued due to DLT (grade 4 febrile neutropenia [1 patient] and prolonged neutropenia [1 patient] at DL 2, and grade 3 prolonged (> 72 h) febrile neutropenia [1 patient] at DL 1.5). A total of 69 doses of NEO-201 were administered (range 1-15, median 4). Common (> 10%) grade 3/4 toxicities occurred as follows: neutropenia (26/69 doses, 17/17 patients), white blood cell decrease (16/69 doses, 12/17 patients), lymphocyte decrease (8/69 doses, 6/17 patients). Thirteen patients were evaluable for disease response; the best response was stable disease (SD) in 4 patients with colorectal cancer. Analysis of soluble factors in serum revealed that a high level of soluble MICA at baseline was correlated with a downregulation of NK cell activation markers and progressive disease. Unexpectedly, flow cytometry showed that NEO-201 also binds to circulating regulatory T cells and reduction of the quantities of these cells was observed especially in patients with SD.\n\nConclusions: NEO-201 was safe and well tolerated at the MTD of 1.5 mg/kg, with neutropenia being the most common adverse event. Furthermore, a reduction in the percentage of regulatory T cells following NEO-201 treatment supports our ongoing phase II clinical trial evaluating the efficiency of the combination of NEO-201 with the immune checkpoint inhibitor pembrolizumab in adults with treatment-resistant solid tumors.\n\nTrial registration: NCT03476681. Registered 03/26/2018.\n\nIndexed on Europe PMC as PubMed record 36991390 (DOI 10.1186/s13046-023-02649-6). Its abstract cites the registry id NCT03476681, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of experimental & clinical cancer research", year: 2023, doi: "10.1186/s13046-023-02649-6", pmid: "36991390", authors: "Cole CB, Morelli MP, Fantini M, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03476681 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Exp Clin Cancer Res 2023","url":"https://doi.org/10.1186/s13046-023-02649-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36991390/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36991390"},{"label":"ClinicalTrials.gov NCT03476681","url":"https://clinicaltrials.gov/study/NCT03476681"}], tags: ["europepmc-ingest"], trials: ["nct03476681"], journals: ["journal-of-experimental-and-clinical-cancer-research"] }),
  p({ id: "paper-nct03706690-j-hematol-oncol-2025", name: "PACIFIC-5: a phase III clinical trial of consolidation durvalumab in patients with unresectable stage III NSCLC and no progression after concurrent or sequential chemoradiotherapy", tldr: "Published report from the PACIFIC-5 trial registered as NCT03706690, in Journal of hematology & oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Consolidation durvalumab following no progression on concurrent chemoradiotherapy (cCRT) is standard of care for unresectable stage III non-small-cell lung cancer (NSCLC). However, in clinical practice many patients receive sequential CRT (sCRT). The PACIFIC-5 trial aimed to evaluate the efficacy and safety of consolidation durvalumab for unresectable stage III NSCLC following no progression on cCRT or sCRT.\n\nMethods: This randomised, double-blind, placebo-controlled, phase III trial enrolled patients aged ≥ 18 years with unresectable stage III NSCLC, regardless of PD-L1 expression or sensitising EGFR or ALK aberrations, without disease progression after cCRT or sCRT. Patients were randomised (2:1) to durvalumab 1500 mg or placebo intravenously every 4 weeks (stratified by tumour PD-L1 expression and prior treatment) until disease progression, unacceptable toxicity, or consent withdrawal. The primary endpoint was progression-free survival (PFS) by blinded independent central review in the modified intention-to-treat population (mITT). Secondary endpoints included overall survival (OS) in the mITT and safety. The safety analysis set include patients who received at least one dose of study treatment.\n\nResults: Of 407 patients randomised to receive durvalumab (n = 272) or placebo (n = 135), 405 received at least one dose of durvalumab (n = 271) or placebo (n = 134). The mITT comprised 381 patients randomised to durvalumab (n = 252) or placebo (n = 129). Durvalumab showed statistically significant improvement in PFS versus placebo in the mITT (median [95% confidence interval {CI}], 14.0 [10.9-18.0] vs. 6.5 [5.4-13.8] months; hazard ratio [95% CI], 0.75 [0.58-0.99]; p = 0.038). There was a trend toward improved OS with durvalumab versus placebo in the mITT (median [95% CI], 38.3 [28.9-42.8] vs. 32.5 [20.6-40.4] months; hazard ratio [95% CI], 0.87 [0.66-1.17]; p = 0.346 [interim analysis]). Among the safety analysis set, maximum grade 3 or 4 adverse events of any cause occurred in 26.9% (73/271) and 23.9% (32/134) and 1.5% (4/271) and 0% (0/134) had treatment-related adverse events leading to death for durvalumab and placebo, respectively.\n\nConclusions: PACIFIC-5 met its primary endpoint of improved PFS after either cCRT or sCRT. Follow-up for overall survival is ongoing.\n\nTrial registration: NCT03706690.\n\nIndexed on Europe PMC as PubMed record 41354932 (DOI 10.1186/s13045-025-01768-1). Its abstract cites the registry id NCT03706690, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of hematology & oncology", year: 2025, doi: "10.1186/s13045-025-01768-1", pmid: "41354932", authors: "Wu YL, Wu L, Bi N, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03706690 with the most citations, so it is the natural first reading for anyone following the PACIFIC-5 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Hematol Oncol 2025","url":"https://doi.org/10.1186/s13045-025-01768-1"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41354932/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41354932"},{"label":"ClinicalTrials.gov NCT03706690","url":"https://clinicaltrials.gov/study/NCT03706690"}], tags: ["europepmc-ingest"], trials: ["nct03706690"], journals: ["journal-of-hematology-and-oncology"] }),
  p({ id: "paper-nct03775486-j-thorac-oncol-2023", name: "Durvalumab in Combination With Olaparib Versus Durvalumab Alone as Maintenance Therapy in Metastatic NSCLC: The Phase 2 ORION Study", tldr: "Published report from the ORION trial registered as NCT03775486, in Journal of Thoracic Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Increased DNA damage triggered through poly (ADP-ribose) polymerase inhibition may modify tumor immunogenicity, sensitizing tumors to immunotherapy. ORION (NCT03775486) evaluated the combination of olaparib with durvalumab as maintenance therapy in patients with metastatic NSCLC.\n\nMethods: ORION is a phase 2, randomized, multicenter, double-blind, international study. Patients with metastatic NSCLC (without activating EGFR or ALK aberrations) and Eastern Cooperative Oncology Group performance status of 0 or 1 were enrolled to receive initial therapy with durvalumab (1500 mg intravenously; every 3 wk) plus platinum-based chemotherapy for four cycles. Patients without disease progression were then randomized (1:1) to maintenance durvalumab (1500 mg; every 4 wk) plus either olaparib (300 mg orally) or placebo (both twice daily); randomization was stratified by objective response during initial therapy and tumor histologic type. The primary end point was investigator-assessed progression-free survival (PFS) (Response Evaluation Criteria in Solid Tumors version 1.1).\n\nResults: Between January 2019 and February 2020, 269 of 401 patients who received initial therapy were randomized. at January 11, 2021 (median follow-up: 9.6 mo), median PFS was 7.2 months (95% confidence interval: 5.3-7.9) with durvalumab plus olaparib versus 5.3 months (3.7-5.8) with durvalumab plus placebo (hazard ratio = 0.76, 95% confidence interval: 0.57-1.02, p = 0.074). Safety findings were consistent with the known profiles of durvalumab and olaparib. Anemia was the most common adverse event (AE) with durvalumab plus olaparib (26.1% versus 8.2% with durvalumab plus placebo). The incidence of grade 3 or 4 AEs (34.3% versus 17.9%) and AEs leading to treatment discontinuation (10.4% versus 4.5%) was numerically higher with durvalumab plus olaparib versus durvalumab plus placebo.\n\nConclusions: Maintenance therapy with durvalumab in combination with olaparib was not associated with a statistically significant improvement in PFS versus durvalumab alone, although numerical improvement was observed.\n\nIndexed on Europe PMC as PubMed record 37390980 (DOI 10.1016/j.jtho.2023.06.013). Its abstract cites the registry id NCT03775486, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2023, doi: "10.1016/j.jtho.2023.06.013", pmid: "37390980", authors: "Ahn MJ, Bondarenko I, Kalinka E, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03775486 with the most citations, so it is the natural first reading for anyone following the ORION trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2023","url":"https://doi.org/10.1016/j.jtho.2023.06.013"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37390980/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37390980"},{"label":"ClinicalTrials.gov NCT03775486","url":"https://clinicaltrials.gov/study/NCT03775486"}], tags: ["europepmc-ingest"], trials: ["nct03775486"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct03778229-ann-oncol-2025", name: "Savolitinib plus osimertinib in epidermal growth factor receptor (EGFR)-mutated advanced non-small cell lung cancer with MET overexpression and/or amplification following disease progression on osimertinib: primary results from the phase II SAVANNAH study", tldr: "Published report from the SAVANNAH trial registered as NCT03778229, in Annals of Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: MET-based resistance following osimertinib treatment for epidermal growth factor receptor (EGFR)-mutated advanced non-small cell lung cancer (NSCLC) is common. We report the primary analysis of the phase II SAVANNAH study (NCT03778229) evaluating savolitinib plus osimertinib in this setting.\n\nPatients and methods: Patients had EGFR-mutated, advanced NSCLC with MET overexpression and/or amplification. MET cut-offs were initially MET immunohistochemistry (IHC)3+/≥50% (3+ intensity in ≥50% of tumor cells) and/or FISH5+ (≥5 MET gene copies or MET/chromosome 7 centromere ratio ≥2), and increased to MET IHC3+/≥90% and/or FISH10+ after a preliminary analysis. Patients received oral savolitinib [300 mg twice daily (b.i.d.) or once daily (o.d.), or 600 mg o.d.] plus osimertinib 80 mg o.d., or savolitinib 300 mg b.i.d. plus placebo. A primary endpoint was investigator-assessed objective response rate (ORR) in patients with progression on first-line osimertinib and MET IHC3+/≥90% and/or FISH10+ status receiving savolitinib 300 mg b.i.d. plus osimertinib (primary efficacy population). Safety was analyzed in all patients receiving savolitinib plus osimertinib.\n\nResults: Of the 365 patients treated, 341 received savolitinib plus osimertinib, with 80 of these included in the primary efficacy population. Investigator-assessed confirmed ORR in the primary efficacy population was 56.3% [95% confidence interval (CI) 44.7% to 67.3%]; the median duration of response (mDoR) was 7.1 months (95% CI 5.6-9.6 months); the median progression-free survival (PFS) was 7.4 months (95% CI 5.5-7.6 months). Blinded independent central review was consistent: confirmed ORR 55.0% (95% CI 43.5% to 66.2%); mDoR 9.9 months (95% CI 6.0-13.7 months); median PFS 7.5 months (95% CI 6.4-11.3 months). The most common any grade adverse events in patients receiving savolitinib plus osimertinib were peripheral edema (46.0%), nausea (40.5%), and diarrhea (23.2%).\n\nConclusions: Savolitinib 300 mg b.i.d. plus osimertinib demonstrated high, clinically meaningful and durable responses in patients with EGFR-mutated, advanced NSCLC with MET IHC3+/≥90% and/or FISH10+ status following progression on first-line osimertinib. The combination was well tolerated and may provide a new oral targeted treatment approach in this setting.\n\nIndexed on Europe PMC as PubMed record 40461383 (DOI 10.1016/j.annonc.2025.04.003). Its abstract cites the registry id NCT03778229, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2025, doi: "10.1016/j.annonc.2025.04.003", pmid: "40461383", authors: "de Marinis F, Kim TM, Bonanno L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03778229 with the most citations, so it is the natural first reading for anyone following the SAVANNAH trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2025","url":"https://doi.org/10.1016/j.annonc.2025.04.003"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40461383/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40461383"},{"label":"ClinicalTrials.gov NCT03778229","url":"https://clinicaltrials.gov/study/NCT03778229"}], tags: ["europepmc-ingest"], trials: ["nct03778229"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct03800134-n-engl-j-med-2023", name: "Perioperative Durvalumab for Resectable Non-Small-Cell Lung Cancer", tldr: "Published report from the AEGEAN trial registered as NCT03800134, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Neoadjuvant or adjuvant immunotherapy can improve outcomes in patients with resectable non-small-cell lung cancer (NSCLC). Perioperative regimens may combine benefits of both to improve long-term outcomes.\n\nMethods: We randomly assigned patients with resectable NSCLC (stage II to IIIB [N2 node stage] according to the eighth edition of the AJCC Cancer Staging Manual) to receive platinum-based chemotherapy plus durvalumab or placebo administered intravenously every 3 weeks for 4 cycles before surgery, followed by adjuvant durvalumab or placebo intravenously every 4 weeks for 12 cycles. Randomization was stratified according to disease stage (II or III) and programmed death ligand 1 (PD-L1) expression (≥1% or <1%). Primary end points were event-free survival (defined as the time to the earliest occurrence of progressive disease that precluded surgery or prevented completion of surgery, disease recurrence [assessed in a blinded fashion by independent central review], or death from any cause) and pathological complete response (evaluated centrally).\n\nResults: A total of 802 patients were randomly assigned to receive durvalumab (400 patients) or placebo (402 patients). The duration of event-free survival was significantly longer with durvalumab than with placebo; the stratified hazard ratio for disease progression, recurrence, or death was 0.68 (95% confidence interval [CI], 0.53 to 0.88; P = 0.004) at the first interim analysis. At the 12-month landmark analysis, event-free survival was observed in 73.4% of the patients who received durvalumab (95% CI, 67.9 to 78.1), as compared with 64.5% of the patients who received placebo (95% CI, 58.8 to 69.6). The incidence of pathological complete response was significantly greater with durvalumab than with placebo (17.2% vs. 4.3% at the final analysis; difference, 13.0 percentage points; 95% CI, 8.7 to 17.6; P<0.001 at interim analysis of data from 402 patients). Event-free survival and pathological complete response benefit were observed regardless of stage and PD-L1 expression. Adverse events of maximum grade 3 or 4 occurred in 42.4% of patients with durvalumab and in 43.2% with placebo. Data from 62 patients with documented EGFR or ALK alterations were excluded from the efficacy analyses in the modified intention-to-treat population.\n\nConclusions: In patients with resectable NSCLC, perioperative durvalumab plus neoadjuvant chemotherapy was associated with significantly greater event-free survival and pathological complete response than neoadjuvant chemotherapy alone, with a safety profile that was consistent with the individual agents. (Funded by AstraZeneca; AEGEAN ClinicalTrials.gov number, NCT03800134.).\n\nIndexed on Europe PMC as PubMed record 37870974 (DOI 10.1056/nejmoa2304875). Its abstract cites the registry id NCT03800134, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2304875", pmid: "37870974", authors: "Heymach JV, Harpole D, Mitsudomi T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03800134 with the most citations, so it is the natural first reading for anyone following the AEGEAN trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2304875"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37870974/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37870974"},{"label":"ClinicalTrials.gov NCT03800134","url":"https://clinicaltrials.gov/study/NCT03800134"}], tags: ["europepmc-ingest"], trials: ["nct03800134"], journals: ["nejm"] }),
  p({ id: "paper-nct03907852-nat-med-2023", name: "Mesothelin-targeting T cell receptor fusion construct cell therapy in refractory solid tumors: phase 1/2 trial interim results", tldr: "Published report from the Phase 1 trial registered as NCT03907852, in Nature Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "The T cell receptor fusion construct (TRuC) gavocabtagene autoleucel (gavo-cel) consists of single-domain anti-mesothelin antibody that integrates into the endogenous T cell receptor (TCR) and engages the signaling capacity of the entire TCR upon mesothelin binding. Here we describe phase 1 results from an ongoing phase1/2 trial of gavo-cel in patients with treatment-refractory mesothelin-expressing solid tumors. The primary objectives were to evaluate safety and determine the recommended phase 2 dose (RP2D). Secondary objectives included efficacy. Thirty-two patients received gavo-cel at increasing doses either as a single agent (n = 3) or after lymphodepletion (LD, n = 29). Dose-limiting toxicities of grade 3 pneumonitis and grade 5 bronchioalveolar hemorrhage were noted. The RP2D was determined as 1 × 10 8 cells per m 2 after LD. Grade 3 or higher pneumonitis was seen in 16% of all patients and in none at the RP2D; grade 3 or higher cytokine release syndrome occurred in 25% of all patients and in 15% at the RP2D. In 30 evaluable patients, the overall response rate and disease control rate were 20% (13% confirmed) and 77%, respectively, and the 6-month overall survival rate was 70%. Gavo-cel warrants further study in patients with mesothelin-expressing cancers given its encouraging anti-tumor activity, but it may have a narrow therapeutic window. ClinicalTrials.gov identifier: NCT03907852.\n\nIndexed on Europe PMC as PubMed record 37501016 (DOI 10.1038/s41591-023-02452-y). Its abstract cites the registry id NCT03907852, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2023, doi: "10.1038/s41591-023-02452-y", pmid: "37501016", authors: "Hassan R, Butler M, O'Cearbhaill RE, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03907852 with the most citations, so it is the natural first reading for anyone following the Phase 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2023","url":"https://doi.org/10.1038/s41591-023-02452-y"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37501016/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37501016"},{"label":"ClinicalTrials.gov NCT03907852","url":"https://clinicaltrials.gov/study/NCT03907852"}], tags: ["europepmc-ingest"], trials: ["nct03907852"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct03916627-lancet-gastroenterol-hepatol-2022", name: "Neoadjuvant cemiplimab for resectable hepatocellular carcinoma: a single-arm, open-label, phase 2 trial", tldr: "Published report from the trial registered as NCT03916627, in The lancet. Gastroenterology & hepatology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Surgical resection of early stage hepatocellular carcinoma is standard clinical practice; however, most tumours recur despite surgery, and no perioperative intervention has shown a survival benefit. Neoadjuvant immunotherapy has induced pathological responses in multiple tumour types and might decrease the risk of postoperative recurrence in hepatocellular carcinoma. We aimed to evaluate the clinical activity of neoadjuvant cemiplimab (an anti-PD-1) in patients with resectable hepatocellular carcinoma.\n\nMethods: For this single-arm, open-label, phase 2 trial, patients with resectable hepatocellular carcinoma (stage Ib, II, and IIIb) were enrolled and received two cycles of neoadjuvant cemiplimab 350 mg intravenously every 3 weeks followed by surgical resection. Eligible patients were aged 18 years or older, had confirmed resectable hepatocellular carcinoma, an Eastern Cooperative Oncology Group performance status of 0 or 1, and adequate liver function. Patients were excluded if they had metastatic disease, if the surgery was not expected to be curative, if they had a known additional malignancy requiring active treatment, or if they required systemic steroid treatment or any other immunosuppressive therapy. After resection, patients received an additional eight cycles of cemiplimab 350 mg intravenously every 3 weeks in the adjuvant setting. The primary endpoint was significant tumour necrosis on pathological examination (defined as >70% necrosis of the resected tumour). Secondary endpoints included delay of surgery, the proportion of patients with an overall response, change in CD8 + T-cell density, and adverse events. Tumour necrosis and response were analysed in all patients who received at least one dose of cemiplimab and completed surgical resection; safety and other endpoints were analysed in the intention-to-treat population. Patients underwent pre-treatment biopsies and blood collection throughout treatment. This trial is registered with ClinicalTrials.gov (NCT03916627, Cohort B) and is ongoing.\n\nFindings: Between Aug 5, 2019, and Nov 25, 2020, 21 patients were enrolled. All patients received neoadjuvant cemiplimab, and 20 patients underwent successful resection. Of the 20 patients with resected tumours, four (20%) had significant tumour necrosis. Three (15%) of 20 patients had a partial response, and all other patients maintained stable disease. 20 (95%) patients had a treatment-emergent adverse event of any grade during the neoadjuvant treatment period. The most common adverse events of any grade were increased aspartate aminotransferase (in four patients), increased blood creatine phosphokinase (in three), constipation (in three), and fatigue (in three). Seven patients had grade 3 adverse events, including increased blood creatine phosphokinase (in two patients) and hypoalbuminaemia (in one). No grade 4 or 5 events were observed. One patient developed pneumonitis, which led to a delay in surgery by 2 weeks.\n\nInterpretation: This report is, to our knowledge, the largest clinical trial of a neoadjuvant anti-PD-1 monotherapy reported to date in hepatocellular carcinoma. The observed pathological responses to cemiplimab in this cohort support the design of larger trials to identify the optimal treatment duration and definitively establish the clinical benefit of preoperative PD-1 blockade in patients with hepatocellular carcinoma.\n\nFunding: Regeneron Pharmaceuticals.\n\nIndexed on Europe PMC as PubMed record 35065058 (DOI 10.1016/s2468-1253(21)00385-x). Its abstract cites the registry id NCT03916627, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The lancet. Gastroenterology & hepatology", year: 2022, doi: "10.1016/s2468-1253(21)00385-x", pmid: "35065058", authors: "Marron TU, Fiel MI, Hamon P, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03916627 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Gastroenterol Hepatol 2022","url":"https://doi.org/10.1016/s2468-1253(21)00385-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35065058/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35065058"},{"label":"ClinicalTrials.gov NCT03916627","url":"https://clinicaltrials.gov/study/NCT03916627"}], tags: ["europepmc-ingest"], trials: ["nct03916627"] }),
  p({ id: "paper-nct03944772-jco-precis-oncol-2025", name: "ORCHARD: Osimertinib Plus Necitumumab in Patients With Epidermal Growth Factor Receptor-Mutated Advanced Non-Small Cell Lung Cancer With a Secondary Epidermal Growth Factor Receptor Alteration Whose Disease Had Progressed on First-Line Osimertinib", tldr: "Published report from the ORCHARD trial registered as NCT03944772, in JCO Precision Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: ORCHARD (ClinicalTrials.gov identifier: NCT03944772) is a phase II, biomarker-directed platform study designed to characterize resistance mechanisms and evaluate novel drug combinations in patients with epidermal growth factor receptor ( EGFR)-mutated advanced non-small cell lung cancer who have progressed on first-line osimertinib. We report final results of the module assessing the efficacy and safety of osimertinib plus necitumumab (a monoclonal antibody that blocks EGFR) in patients with ≥one of the following: EGFR amplification or select secondary EGFR alterations (L718 or G724 mutation, or exon 20 insertion).\n\nMaterials and methods: Patients received osimertinib (80 mg orally once daily) plus necitumumab (800 mg intravenously, days 1 and 8 of a 3-week cycle) until disease progression or unacceptable toxicity. The primary end point was objective response rate (ORR) per RECIST 1.1 by investigator assessment.\n\nResults: Overall, 19 patients received osimertinib plus necitumumab; at data cutoff (April 18, 2023), all patients had discontinued treatment. The ORR was 11% (80% CI, 3 to 26); two patients had a confirmed partial response, with duration of response of 10.4 and 6.0 months; both patients had EGFR amplification. The median progression-free survival was 4.0 months (95% CI, 1.3 to 5.4) and the overall survival was 11.4 months (95% CI, 6.6 to 15.5). Ten patients (53%) had grade ≥3 adverse events, most commonly embolism (not otherwise specified, pulmonary embolism or deep vein thrombosis, reported in four patients; 21%). The safety profile of the combination was consistent with the known profiles of the two individual drugs, and no new signals were identified.\n\nConclusion: Osimertinib plus necitumumab demonstrated modest clinical benefit, and the overall risk-benefit analysis indicates that further evaluation of the regimen is not warranted in these molecularly defined subsets of osimertinib resistance.\n\nIndexed on Europe PMC as PubMed record 40466026 (DOI 10.1200/po-24-00818). Its abstract cites the registry id NCT03944772, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JCO Precision Oncology", year: 2025, doi: "10.1200/po-24-00818", pmid: "40466026", authors: "Riess JW, de Langen AJ, Ponce S, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03944772 with the most citations, so it is the natural first reading for anyone following the ORCHARD trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JCO Precis Oncol 2025","url":"https://doi.org/10.1200/po-24-00818"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40466026/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40466026"},{"label":"ClinicalTrials.gov NCT03944772","url":"https://clinicaltrials.gov/study/NCT03944772"}], tags: ["europepmc-ingest"], trials: ["nct03944772"], journals: ["jco-precision-oncology"] }),
  p({ id: "paper-nct03974022-j-clin-oncol-2025", name: "Phase II Dose-Randomized Study of Sunvozertinib in Platinum-Pretreated Non-Small Cell Lung Cancer With Epidermal Growth Factor Receptor Exon 20 Insertion Mutations (WU-KONG1B)", tldr: "Published report from the WU-KONG1 trial registered as NCT03974022, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: WU-KONG1B (ClinicalTrials.gov identifier: NCT03974022) is a multinational phase II, dose-randomized study to assess the antitumor efficacy of sunvozertinib in pretreated patients with advanced non-small cell lung cancer (NSCLC) with epidermal growth factor receptor ( EGFR) exon 20 insertion mutations (exon20ins).\n\nMethods: Eligible patients with advanced-stage EGFR exon20ins NSCLC were randomly assigned by 1:1 ratio to receive sunvozertinib 200 mg or 300 mg once daily (200 and 300 mg-rand cohorts). After predefined interim analysis, additional patients were enrolled and treated with the 300 mg dose once daily. The primary end point was blinded independent review committee (IRC)-assessed confirmed objective response rate (cORR), and the key secondary end point was duration of response (DoR).\n\nResults: Among 85, 89, and 107 efficacy-evaluable patients in 200 mg-rand, 300 mg-rand, and 300 mg-all (including randomly assigned and nonrandomized patients) cohorts, the cORRs were 45.9% (97.5% CI, 33.6% to 58.5%), 47.2% (97.5% CI, 35.1% to 59.5%), and 45.8% (97.5% CI, 34.8% to 57.0%), respectively, per IRC assessment. The predefined null hypothesis was rejected with statistical significance ( P <.0001). Comparing 300 and 200 mg-rand cohorts, higher cORRs were observed in patients with baseline brain metastasis (52.4% v 28.6%) and previous amivantamab treatment (41.7% v 25%), as well as longer DoR (13.8 v 11.1 months). At 200 and 300 mg once daily, the most common treatment-related adverse events with grade ≥3 included diarrhea (2.2% v 18%), blood creatine phosphokinase increased (6.6% v 12.6%), and anemia (4.4% v 6.3%).\n\nConclusion: Sunvozertinib is efficacious at both 200 and 300 mg once daily in treating platinum-pretreated patients with advanced EGFR exon20ins NSCLC. The treatment-related adverse events of sunvozertinib were consistent with an EGFR tyrosine kinase inhibitor, with a more favorable safety profile at 200 mg than 300 mg once daily.\n\nIndexed on Europe PMC as PubMed record 40923280 (DOI 10.1200/jco-25-00788). Its abstract cites the registry id NCT03974022, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-25-00788", pmid: "40923280", authors: "Yang JC, Wang M, Doucet L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03974022 with the most citations, so it is the natural first reading for anyone following the WU-KONG1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-25-00788"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40923280/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40923280"},{"label":"ClinicalTrials.gov NCT03974022","url":"https://clinicaltrials.gov/study/NCT03974022"}], tags: ["europepmc-ingest"], trials: ["nct03974022"], journals: ["jco"] }),
  p({ id: "paper-nct04025879-n-engl-j-med-2024", name: "Perioperative Nivolumab in Resectable Lung Cancer", tldr: "Published report from the CheckMate 77T trial registered as NCT04025879, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Standard treatment with neoadjuvant nivolumab plus chemotherapy significantly improves outcomes in patients with resectable non-small-cell lung cancer (NSCLC). Perioperative treatment (i.e., neoadjuvant therapy followed by surgery and adjuvant therapy) with nivolumab may further improve clinical outcomes.\n\nMethods: In this phase 3, randomized, double-blind trial, we assigned adults with resectable stage IIA to IIIB NSCLC to receive neoadjuvant nivolumab plus chemotherapy or neoadjuvant chemotherapy plus placebo every 3 weeks for 4 cycles, followed by surgery and adjuvant nivolumab or placebo every 4 weeks for 1 year. The primary outcome was event-free survival according to blinded independent review. Secondary outcomes were pathological complete response and major pathological response according to blinded independent review, overall survival, and safety.\n\nResults: At this prespecified interim analysis (median follow-up, 25.4 months), the percentage of patients with 18-month event-free survival was 70.2% in the nivolumab group and 50.0% in the chemotherapy group (hazard ratio for disease progression or recurrence, abandoned surgery, or death, 0.58; 97.36% confidence interval [CI], 0.42 to 0.81; P<0.001). A pathological complete response occurred in 25.3% of the patients in the nivolumab group and in 4.7% of those in the chemotherapy group (odds ratio, 6.64; 95% CI, 3.40 to 12.97); a major pathological response occurred in 35.4% and 12.1%, respectively (odds ratio, 4.01; 95% CI, 2.48 to 6.49). Grade 3 or 4 treatment-related adverse events occurred in 32.5% of the patients in the nivolumab group and in 25.2% of those in the chemotherapy group.\n\nConclusions: Perioperative treatment with nivolumab resulted in significantly longer event-free survival than chemotherapy in patients with resectable NSCLC. No new safety signals were observed. (Funded by Bristol Myers Squibb; CheckMate 77T ClinicalTrials.gov number, NCT04025879.).\n\nIndexed on Europe PMC as PubMed record 38749033 (DOI 10.1056/nejmoa2311926). Its abstract cites the registry id NCT04025879, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2311926", pmid: "38749033", authors: "Cascone T, Awad MM, Spicer JD, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04025879 with the most citations, so it is the natural first reading for anyone following the CheckMate 77T trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2311926"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38749033/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38749033"},{"label":"ClinicalTrials.gov NCT04025879","url":"https://clinicaltrials.gov/study/NCT04025879"}], tags: ["europepmc-ingest"], trials: ["nct04025879"], journals: ["nejm"] }),
  p({ id: "paper-nct04036682-j-clin-oncol-2025", name: "Zipalertinib in Patients With Epidermal Growth Factor Receptor Exon 20 Insertion-Positive Non-Small Cell Lung Cancer Previously Treated With Platinum-Based Chemotherapy With or Without Amivantamab", tldr: "Published report from the REZILIENT1 trial registered as NCT04036682, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: To evaluate the safety and efficacy of zipalertinib, an irreversible epidermal growth factor receptor (EGFR) inhibitor, in pretreated patients with non-small cell lung cancer (NSCLC) harboring EGFR exon 20 insertion (ex20ins) mutations.\n\nMethods: REZILIENT1 (ClinicalTrials.gov identifier: NCT04036682) is a phase I/II open-label trial enrolling patients with locally advanced or metastatic EGFR ex20ins-mutant NSCLC previously treated with platinum-based chemotherapy with/without ex20ins-targeted therapies. Asymptomatic, treated and untreated stable CNS metastases are permitted. We report data from patients treated with zipalertinib 100 mg twice daily. The primary end points are objective response rate (ORR) and duration of response (DOR) by independent central review.\n\nResults: At data cutoff (December 10, 2024), 244 patients had received treatment with zipalertinib 100 mg twice daily. The primary efficacy population (8 months' follow-up) comprised patients who had received prior platinum-based chemotherapy without ex20ins-targeted therapy (125 patients), with amivantamab only (30 patients), or with amivantamab and other ex20ins-targeted therapy (21 patients). The confirmed ORR was 35.2% (95% CI, 28.2 to 42.8); median DOR was 8.8 months (95% CI, 8.3 to 12.7). Among patients who received prior platinum-based chemotherapy without ex20ins-targeted therapy, amivantamab only, or amivantamab and other ex20ins-targeted therapy, the confirmed ORR was 40%, 30%, and 14.3%, and median DOR was 8.8, 14.7, and 4.2 months, respectively. Among 68 patients with CNS metastases, the ORR was 30.9%. The most common grade ≥3 treatment-related adverse events were anemia (7%), pneumonitis and rash (2.5% each), and diarrhea, ALT increased, and platelet count decreased (2% each).\n\nConclusion: Zipalertinib demonstrated clinically meaningful efficacy with a manageable safety profile in patients with EGFR ex20ins-mutant NSCLC who received prior platinum-based chemotherapy with or without amivantamab.\n\nIndexed on Europe PMC as PubMed record 40450572 (DOI 10.1200/jco-25-00763). Its abstract cites the registry id NCT04036682, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-25-00763", pmid: "40450572", authors: "Piotrowska Z, Passaro A, Nguyen D, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04036682 with the most citations, so it is the natural first reading for anyone following the REZILIENT1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-25-00763"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40450572/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40450572"},{"label":"ClinicalTrials.gov NCT04036682","url":"https://clinicaltrials.gov/study/NCT04036682"}], tags: ["europepmc-ingest"], trials: ["nct04036682"], journals: ["jco"] }),
  p({ id: "paper-nct04129502-j-clin-oncol-2025", name: "First-Line Mobocertinib Versus Platinum-Based Chemotherapy in Patients With EGFR Exon 20 Insertion-Positive Metastatic Non-Small Cell Lung Cancer in the Phase III EXCLAIM-2 Trial", tldr: "Published report from the trial registered as NCT04129502, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Mobocertinib is an oral epidermal growth factor receptor (EGFR) tyrosine kinase inhibitor that targets EGFR exon 20 insertion (ex20ins) mutations in non-small cell lung cancer (NSCLC). This open-label, phase III trial (EXCLAIM-2, ClinicalTrials.gov identifier: NCT04129502) compared mobocertinib versus platinum-based chemotherapy as first-line treatment of EGFR ex20ins+ advanced/metastatic NSCLC.\n\nMethods: Patients with treatment-naive EGFR ex20ins+ locally advanced/metastatic NSCLC were randomly assigned 1:1 to mobocertinib 160 mg once daily or pemetrexed plus cisplatin or carboplatin every 3 weeks for four cycles followed by maintenance pemetrexed. The primary end point was progression-free survival (PFS) by blinded independent central review (BICR), with planned interim analysis (IA) after approximately 70% of 227 expected PFS events.\n\nResults: A total of 354 patients were randomly assigned (mobocertinib: n = 179; chemotherapy: n = 175). Baseline characteristics were balanced between arms. At IA (cutoff: April 4, 2023), the median PFS per BICR was 9.6 months in each treatment arm (hazard ratio [HR], 1.04 [95% CI, 0.77 to 1.39]; P =.803). The primary end point crossed the prespecified futility boundary (HR > 1). The confirmed objective response rate (95% CI) per BICR was 32% (26 to 40) with mobocertinib versus 30% (24 to 38) with chemotherapy; the median duration of response was 12.0 versus 8.4 months. Quality-of-life assessments indicated clinically meaningful delays in time to deterioration of lung cancer symptoms, cognitive function, and constipation with mobocertinib versus chemotherapy. Grade ≥3 adverse events in >5% of patients (mobocertinib, chemotherapy) were diarrhea (20%, 1%), anemia (6%, 10%), increased lipase (6%, 0%), and decreased neutrophil count (1%, 7%).\n\nConclusion: The EXCLAIM-2 trial did not meet its primary end point. The efficacy of mobocertinib was not superior to platinum-based chemotherapy for first-line treatment of patients with EGFR ex20ins+ advanced/metastatic NSCLC.\n\nIndexed on Europe PMC as PubMed record 39879577 (DOI 10.1200/jco-24-01269). Its abstract cites the registry id NCT04129502, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-24-01269", pmid: "39879577", authors: "Jänne PA, Wang BC, Cho BC, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04129502 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-24-01269"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39879577/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39879577"},{"label":"ClinicalTrials.gov NCT04129502","url":"https://clinicaltrials.gov/study/NCT04129502"}], tags: ["europepmc-ingest"], trials: ["nct04129502"], journals: ["jco"] }),
  p({ id: "paper-nct04143607-lancet-respir-med-2025", name: "Efficacy and safety of limertinib versus gefitinib as first-line treatment for locally advanced or metastatic non-small-cell lung cancer with EGFR-sensitising mutation: a randomised, double-blind, double-dummy, phase 3 trial", tldr: "Published report from the trial registered as NCT04143607, in The Lancet. Respiratory medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Limertinib is a new third-generation epidermal growth factor receptor (EGFR) tyrosine kinase inhibitor. This study aimed to prospectively assess the efficacy and safety of limertinib versus gefitinib as a first-line treatment for locally advanced or metastatic non-small-cell lung cancer (NSCLC) with EGFR-sensitising mutation.\n\nMethods: This multicentre, randomised, double-blind, double-dummy, phase 3 trial was done at 56 hospitals in China. Eligible patients were aged ≥18 years with locally advanced or metastatic NSCLC with EGFR-sensitising mutation (exon 19 deletion or exon 21 L858R mutation) detected in tumour tissue samples using the Cobas EGFR Mutation Test at a central laboratory. Patients were randomly assigned (1:1) to receive oral limertinib 80 mg twice a day and gefitinib-matching placebo 250 mg once a day or oral gefitinib 250 mg once a day plus limertinib-matching placebo 80 mg twice a day in 21-day cycles, until disease progression or other discontinuation criteria was met. Random assignment was stratified according to EGFR mutation type (exon 19 deletion or exon 21 L858R mutation) and CNS metastasis (yes or no) using permuted blocks (block size four) through an interactive web-based response system. The primary endpoint was independent central review (ICR)-assessed progression-free survival. All enrolled patients who received at least one dose of study treatment were included in the full analysis set for efficacy analysis. All enrolled patients who received at least one dose of study treatment and one safety assessment were included in the safety set. This study is registered with ClinicalTrials.gov, NCT04143607, and follow-up is ongoing.\n\nFindings: Between June 30, 2021, and Sept 22, 2022, 337 patients were enrolled and 168 were randomly assigned to the limertinib group and 169 to the gefitinib group. Patients' median age was 63 years (34-82). 214 (64%) of 337 patients were female and 123 (36%) were male. The median masked ICR-assessed progression-free survival was 20·7 months (95% CI 15·2-22·1) in the limertinib group and 9·7 months (95% CI 8·3-11·1) in the gefitinib group (hazard ratio [HR] 0·44 [95% CI 0·34-0·58]; p<0·0001). Treatment-related adverse events of grade 3 or worse occurred in 42 (25%) of 168 patients in the limertinib group and 42 (25%) of 169 patients in the gefitinib group. Treatment-related serious adverse events occurred in nine (5%) patients and 17 (10%) patients in each group, respectively. Six (4%) patients in the limertinib group died due to adverse events, all of which were considered possibly unrelated to the study drug by investigators. In the gefitinib group, seven (4%) patients died due to adverse events, with three (2%) of those deaths judged as possibly related to the study drug by investigators. Three treatment-related deaths in the gefitinib group were recorded (one case related to pneumonia and two with cause of death unknown).\n\nInterpretation: Limertinib showed superior efficacy compared with gefitinib and a manageable safety profile for locally advanced or metastatic NSCLC patients with EGFR-sensitising mutation and should be considered as another first-line treatment option for this patient population.\n\nFunding: Jiangsu Aosaikang Pharmaceutical.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 40550238 (DOI 10.1016/s2213-2600(25)00121-3). Its abstract cites the registry id NCT04143607, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2025, doi: "10.1016/s2213-2600(25)00121-3", pmid: "40550238", authors: "Shi Y, Wu L, Ji Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04143607 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2025","url":"https://doi.org/10.1016/s2213-2600(25)00121-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40550238/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40550238"},{"label":"ClinicalTrials.gov NCT04143607","url":"https://clinicaltrials.gov/study/NCT04143607"}], tags: ["europepmc-ingest"], trials: ["nct04143607"] }),
  p({ id: "paper-nct04152499-j-hematol-oncol-2025", name: "Results of a phase 1/2 study of sacituzumab tirumotecan in patients with unresectable locally advanced or metastatic solid tumors refractory to standard therapies", tldr: "Published report from the TROP2 ADC trial registered as NCT04152499, in Journal of hematology & oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sacituzumab tirumotecan (sac-TMT) is an antibody-drug conjugate composed of an anti-TROP2 monoclonal antibody coupled to a cytotoxic belotecan-derived topoisomerase I inhibitor (KL610023) via a novel linker. We report results from the phase 1 dose-escalation cohorts in advanced solid tumors and phase 2 expansion cohorts for metastatic triple-negative breast cancer (TNBC) from the first-in-human MK-2870-001 (KL264-01) study (NCT04152499).\n\nMethods: Patients had unresectable locally advanced/metastatic solid tumors refractory to standard therapies. In the phase 1 dose-escalation cohorts, patients had unresectable locally advanced/metastatic solid tumors refractory to standard therapies. Sac-TMT was administered by intravenous administration every 2 weeks at 2 to 12 mg/kg. In phase 2, patients with TNBC and HR+/HER2- breast cancer received sac-TMT per recommended doses for expansion (RDEs) identified in phase 1. Primary objectives were determining maximum tolerated dose (MTD) of sac-TMT and establishing RDEs (phase 1) and determining ORR per RECIST v1.1 by investigator assessment (phase 2). Adverse events were assessed per NCI-CTCAE version 5.0.\n\nResults: Thirty patients were enrolled in phase 1 and received sac-TMT 2 mg/kg (n = 4), 4 mg/kg (n = 7), 5 mg/kg (n = 7), 5.5 mg/kg (n = 5), and 6 mg/kg (n = 7). Five patients had dose-limiting toxicities: grade 3 stomatitis at 4, 5.5, and 6 mg/kg; grade 3 rash at 5 mg/kg; and grade 3 urticaria at 6 mg/kg. MTD was 5.5 mg/kg and RDEs were 4 and 5 mg/kg. In the phase 2 dose expansion, ORR (95% CI) was 34.8% (16.4%, 57.3%) in the 4-mg/kg group (n = 23) and 38.9% (23.1%, 56.5%) in the 5-mg/kg group (n = 36) for TNBC. ORR (95% CI) was 31.7% (18.1%, 48.1%) for HR+/HER2- breast cancer (n = 41).\n\nConclusions: Sac-TMT demonstrated manageable safety profile in patients with unresectable locally advanced/metastatic solid tumors and promising antitumor activity in metastatic TNBC and HR+/HER2 - breast cancer. Sac-TMT is being investigated in phase 3 studies.\n\nTrial registration: ClinicalTrials.gov, NCT04152499.\n\nIndexed on Europe PMC as PubMed record 40481574 (DOI 10.1186/s13045-025-01705-2). Its abstract cites the registry id NCT04152499, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of hematology & oncology", year: 2025, doi: "10.1186/s13045-025-01705-2", pmid: "40481574", authors: "Ouyang Q, Rodon J, Liang Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04152499 with the most citations, so it is the natural first reading for anyone following the TROP2 ADC trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Hematol Oncol 2025","url":"https://doi.org/10.1186/s13045-025-01705-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40481574/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40481574"},{"label":"ClinicalTrials.gov NCT04152499","url":"https://clinicaltrials.gov/study/NCT04152499"}], tags: ["europepmc-ingest"], trials: ["nct04152499"], journals: ["journal-of-hematology-and-oncology"] }),
  p({ id: "paper-nct04379635-lancet-respir-med-2025", name: "Perioperative tislelizumab plus neoadjuvant chemotherapy for patients with resectable non-small-cell lung cancer (RATIONALE-315): an interim analysis of a randomised clinical trial", tldr: "Published report from the trial registered as NCT04379635, in The Lancet. Respiratory medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Treatment guidelines recommend neoadjuvant or adjuvant chemotherapy, with or without immune checkpoint inhibitors, for resectable non-small-cell lung cancer (NSCLC). We report the interim results for the phase 3 RATIONALE-315 study, which aimed to investigate perioperative tislelizumab for the treatment of resectable NSCLC.\n\nMethods: RATIONALE-315 is a randomised, double-blind, placebo-controlled phase 3 trial conducted at 50 sites (hospitals or academic research centres) in China. Patients (aged ≥18 years) with untreated stage II-IIIA squamous or non-squamous NSCLC were randomly assigned (1:1) to neoadjuvant tislelizumab 200 mg or placebo intravenously every 3 weeks, plus platinum-based doublet chemotherapy followed by surgery and adjuvant tislelizumab 400 mg or placebo every 6 weeks. Dual primary endpoints were major pathological response rate and event-free survival, analysed by intention to treat. Safety was also assessed in all patients who received at least one dose of study treatment. RATIONALE-315 is registered with ClinicalTrials.gov, NCT04379635, and is active but not recruiting.\n\nFindings: Between June 8, 2020, and Aug 31, 2022, 453 patients were assigned to tislelizumab (n=226) or placebo (n=227). The median age of patients was 62·0 years (IQR 56·0-67·0). 410 (91%) of 453 patients were male and 43 (9%) were female. at Aug 21, 2023 (data cutoff for the interim analysis of event-free survival), median duration of follow-up was 22·0 months (IQR 15·5-28·0). Tislelizumab significantly improved event-free survival versus placebo (stratified hazard ratio 0·56 [95% CI 0·40-0·79]; one-sided p=0·0003). The major pathological response rate was significantly higher in the tislelizumab group (56% [95% CI 50-63]) than in the placebo group (15% [11-20]; difference 41% [33-49]; one-sided p<0·0001). Grade 3 or worse adverse events and serious treatment-related adverse events occurred in 163 (72%) of 226 patients and 35 (15%) of 226 patients, respectively, in the tislelizumab group, and in 150 (66%) and 18 (8%) patients, respectively, in the placebo group. The most common grade 3 or worse treatment-related adverse event was decreased neutrophil count (138 [61%] of 226 in the tislelizumab group vs 134 [59%] of 226 in the placebo group). 31 (14%) of 226 patients in the tislelizumab group and 45 (20%) of 227 patients in the placebo group died during the study.\n\nInterpretation: Perioperative tislelizumab plus neoadjuvant chemotherapy showed a clinically meaningful and statistically significant improvement in efficacy and a manageable safety profile compared with neoadjuvant chemotherapy in patients with resectable stage II-IIIA NSCLC.\n\nFunding: BeiGene.\n\nIndexed on Europe PMC as PubMed record 39581197 (DOI 10.1016/s2213-2600(24)00269-8). Its abstract cites the registry id NCT04379635, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2025, doi: "10.1016/s2213-2600(24)00269-8", pmid: "39581197", authors: "Yue D, Wang W, Liu H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04379635 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2025","url":"https://doi.org/10.1016/s2213-2600(24)00269-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39581197/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39581197"},{"label":"ClinicalTrials.gov NCT04379635","url":"https://clinicaltrials.gov/study/NCT04379635"}], tags: ["europepmc-ingest"], trials: ["nct04379635"] }),
  p({ id: "paper-nct04379635-ann-oncol-2026-update", name: "Perioperative tislelizumab plus neoadjuvant chemotherapy for patients with resectable non-small-cell lung cancer: final analysis of the randomized RATIONALE-315 trial", tldr: "Later report from the trial registered as NCT04379635, in Annals of Oncology (2026); its title describes an updated or longer-term analysis.", summary: "Background: Perioperative immunotherapy, particularly anti-programmed cell death protein 1 therapy, combined with neoadjuvant chemotherapy has emerged as one of the standard-of-care options for resectable non-small-cell lung cancer (NSCLC). We report the final analysis of RATIONALE-315, a randomized, double-blind, phase III trial evaluating the efficacy and safety of perioperative tislelizumab plus neoadjuvant chemotherapy versus neoadjuvant chemotherapy alone in patients with resectable, stage II-IIIA NSCLC.\n\nPatients and methods: Adult patients in China were randomized (1: 1) to receive either perioperative tislelizumab or placebo in combination with neoadjuvant chemotherapy. The dual primary endpoints were event-free survival (EFS) and major pathological response, assessed by blinded independent central review. The secondary endpoints included pathological complete response, overall survival (OS), disease-free survival, and safety.\n\nResults: In total, 453 patients were randomized (226 to tislelizumab and 227 to placebo). At the final analysis (median study follow-up of 38.5 months), patients in the tislelizumab group experienced statistically significantly improved OS versus those in the placebo group {hazard ratio (HR) 0.65 [95% confidence interval (CI) 0.45-0.93]; P = 0.009}. The median OS was not reached in either group. The 36-month OS rate was 79.3% in the tislelizumab group versus 69.3% in the placebo group. The median EFS was not reached in the tislelizumab group versus 30.6 months in the placebo group [HR 0.58 (95% CI 0.43-0.79)]. Survival benefits were generally consistent across subgroups. The safety profile of tislelizumab plus chemotherapy was tolerable and consistent with known profiles of the individual therapies.\n\nConclusions: Neoadjuvant tislelizumab plus chemotherapy and adjuvant tislelizumab demonstrated a statistically significant, clinically meaningful OS benefit and sustained, clinically meaningful EFS improvement compared with neoadjuvant chemotherapy, with a tolerable safety profile in patients with resectable stage II-IIIA NSCLC. These results support the use of this regimen in this patient population.\n\nClinical trial number: NCT04379635.\n\nIndexed on Europe PMC as PubMed record 41344593 (DOI 10.1016/j.annonc.2025.11.017). Its abstract cites the registry id NCT04379635, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2026, doi: "10.1016/j.annonc.2025.11.017", pmid: "41344593", authors: "Wang C, Wang W, Liu H, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2026","url":"https://doi.org/10.1016/j.annonc.2025.11.017"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41344593/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41344593"},{"label":"ClinicalTrials.gov NCT04379635","url":"https://clinicaltrials.gov/study/NCT04379635"}], tags: ["europepmc-ingest"], trials: ["nct04379635"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct04395677-j-clin-oncol-2024", name: "Efficacy and Safety of Taletrectinib in Chinese Patients With ROS1+ Non-Small Cell Lung Cancer: The Phase II TRUST-I Study", tldr: "Published report from the trial registered as NCT04395677, in Journal of Clinical Oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Taletrectinib, a highly potent, CNS-active, ROS1 tyrosine kinase inhibitor (TKI), has demonstrated high and durable response rates, high intracranial objective response rate (ORR), prolonged progression-free survival (PFS), and activity against G2032R with a favorable safety profile. We report outcomes from the pivotal TRUST-I study (ClinicalTrials.gov identifier: NCT04395677) of taletrectinib for ROS1+ non-small cell lung cancer in China.\n\nMethods: TRUST-I evaluated TKI-naїve and crizotinib-pretreated patients. The primary end point was confirmed ORR (cORR) by independent review committee; key secondary end points included duration of response (DOR), PFS, and safety.\n\nResults: at November 2023, 173 patients were enrolled (median age, 55 years; 58% female; 73% never smoked; TKI naїve: n = 106; crizotinib pretreated: n = 67). In TKI-naїve patients, cORR and intracranial cORR were 91% and 88%, respectively, and 52% and 73% in crizotinib-pretreated patients. In TKI-naїve patients, median DOR and median PFS were not reached (NR) with 22.1-month and 23.5-month follow-up, respectively. In crizotinib-pretreated patients, the median DOR was 10.6 months (95% CI, 6.3 months to NR; 8.4-month follow-up), and the median PFS was 7.6 months (95% CI, 5.5 to 12.0 months; 9.7-month follow-up). Eight of 12 patients (67%) with G2032R mutations responded. The most frequent treatment-emergent adverse events (TEAEs) were increased AST (76%), diarrhea (70%), and increased ALT (68%), most of which were grade 1-2. Incidences of neurologic TEAEs were low (dizziness: 23%; dysgeusia: 10%) and mostly grade 1. Discontinuations (5%) and dose reductions (19%) due to TEAEs were low.\n\nConclusion: Taletrectinib continues to show high and durable overall responses, prolonged PFS, robust activity against intracranial lesions and acquired resistance mutations including G2032R, and a favorable safety profile with a low incidence of neurologic TEAEs.\n\nIndexed on Europe PMC as PubMed record 38822758 (DOI 10.1200/jco.24.00731). Its abstract cites the registry id NCT04395677, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2024, doi: "10.1200/jco.24.00731", pmid: "38822758", authors: "Li W, Xiong A, Yang N, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04395677 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2024","url":"https://doi.org/10.1200/jco.24.00731"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38822758/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38822758"},{"label":"ClinicalTrials.gov NCT04395677","url":"https://clinicaltrials.gov/study/NCT04395677"}], tags: ["europepmc-ingest"], trials: ["nct04395677"], journals: ["jco"] }),
  p({ id: "paper-nct04395677-j-clin-oncol-2026-update", name: "Long-Term Efficacy and Safety of Taletrectinib in Patients With ROS1 + Non-Small Cell Lung Cancer: Results From the Phase II TRUST-I Study", tldr: "Later report from the trial registered as NCT04395677, in Journal of Clinical Oncology (2026); its title describes an updated or longer-term analysis.", summary: "Taletrectinib is a next-generation, CNS-active, selective ROS1 tyrosine kinase inhibitor (TKI) with activity against the ROS1 G2032R resistance mutation. Initial data from the TRUST-I study (ClinicalTrials.gov identifier: NCT04395677) demonstrated high response rates and intracranial (IC) activity, with promising durability, in Chinese patients with advanced ROS1 + non-small cell lung cancer (NSCLC). With longer follow-up, taletrectinib continued to demonstrate high and durable response rates in both TKI-naïve and crizotinib-pretreated patients, including IC activity and promising overall survival (OS). Among 103 TKI-naïve patients who started taletrectinib at 600 mg once daily (median follow-up, 51.0 months), the objective response rate (ORR) was 90.3% (95% CI, 82.9 to 95.3), the median duration of response (DOR) and median progression-free survival (PFS) exceeded 4 years (49.7 months and 49.6 months, respectively), and median OS was not reached. Among 66 crizotinib-pretreated patients (median follow-up, 45.2 months), the ORR was 51.5%, the median DOR was 13.2 months, the median PFS was 7.6 months, and the median OS was 25.6 months. The safety profile remained consistent with prior reports, and no new safety signals were identified. Overall, taletrectinib demonstrated durable long-term efficacy and a manageable safety profile in patients with advanced ROS1 + NSCLC.\n\nIndexed on Europe PMC as PubMed record 42013573 (DOI 10.1200/jco-26-00434). Its abstract cites the registry id NCT04395677, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2026, doi: "10.1200/jco-26-00434", pmid: "42013573", authors: "Li W, Zhang Y, Fan H, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2026","url":"https://doi.org/10.1200/jco-26-00434"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42013573/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42013573"},{"label":"ClinicalTrials.gov NCT04395677","url":"https://clinicaltrials.gov/study/NCT04395677"}], tags: ["europepmc-ingest"], trials: ["nct04395677"], journals: ["jco"] }),
  p({ id: "paper-nct04538664-n-engl-j-med-2023", name: "Amivantamab plus Chemotherapy in NSCLC with EGFR Exon 20 Insertions", tldr: "Published report from the PAPILLON trial registered as NCT04538664, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Amivantamab has been approved for the treatment of patients with advanced non-small-cell lung cancer (NSCLC) with epidermal growth factor receptor ( EGFR) exon 20 insertions who have had disease progression during or after platinum-based chemotherapy. Phase 1 data showed the safety and antitumor activity of amivantamab plus carboplatin-pemetrexed (chemotherapy). Additional data on this combination therapy are needed.\n\nMethods: In this phase 3, international, randomized trial, we assigned in a 1:1 ratio patients with advanced NSCLC with EGFR exon 20 insertions who had not received previous systemic therapy to receive intravenous amivantamab plus chemotherapy (amivantamab-chemotherapy) or chemotherapy alone. The primary outcome was progression-free survival according to blinded independent central review. Patients in the chemotherapy group who had disease progression were allowed to cross over to receive amivantamab monotherapy.\n\nResults: A total of 308 patients underwent randomization (153 to receive amivantamab-chemotherapy and 155 to receive chemotherapy alone). Progression-free survival was significantly longer in the amivantamab-chemotherapy group than in the chemotherapy group (median, 11.4 months and 6.7 months, respectively; hazard ratio for disease progression or death, 0.40; 95% confidence interval [CI], 0.30 to 0.53; P<0.001). At 18 months, progression-free survival was reported in 31% of the patients in the amivantamab-chemotherapy group and in 3% in the chemotherapy group; a complete or partial response at data cutoff was reported in 73% and 47%, respectively (rate ratio, 1.50; 95% CI, 1.32 to 1.68; P<0.001). In the interim overall survival analysis (33% maturity), the hazard ratio for death for amivantamab-chemotherapy as compared with chemotherapy was 0.67 (95% CI, 0.42 to 1.09; P = 0.11). The predominant adverse events associated with amivantamab-chemotherapy were reversible hematologic and EGFR-related toxic effects; 7% of patients discontinued amivantamab owing to adverse reactions.\n\nConclusions: The use of amivantamab-chemotherapy resulted in superior efficacy as compared with chemotherapy alone as first-line treatment of patients with advanced NSCLC with EGFR exon 20 insertions. (Funded by Janssen Research and Development; PAPILLON ClinicalTrials.gov number, NCT04538664.).\n\nIndexed on Europe PMC as PubMed record 37870976 (DOI 10.1056/nejmoa2306441). Its abstract cites the registry id NCT04538664, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2306441", pmid: "37870976", authors: "Zhou C, Tang KJ, Cho BC, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04538664 with the most citations, so it is the natural first reading for anyone following the PAPILLON trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2306441"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37870976/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37870976"},{"label":"ClinicalTrials.gov NCT04538664","url":"https://clinicaltrials.gov/study/NCT04538664"}], tags: ["europepmc-ingest"], trials: ["nct04538664"], journals: ["nejm"] }),
  p({ id: "paper-nct04561362-j-clin-oncol-2025", name: "First-in-Human, Phase I/II Dose Escalation and Expansion Study of Zelenectide Pevedotin in Patients With Advanced Solid Tumors: Results From Monotherapy Dose Escalation", tldr: "Published report from the trial registered as NCT04561362, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Zelenectide pevedotin (BT8009) is a Bicycle Drug Conjugate comprising a highly selective Nectin-4-targeting Bicycle peptide, linked to monomethyl auristatin E. We report monotherapy dose-escalation results from Duravelo-1 (Phase I/II; ClinicalTrials.gov identifier: NCT04561362).\n\nMethods: Adults with advanced/metastatic solid tumors associated with Nectin-4 expression received zelenectide pevedotin intravenously at 2.5, 5.0, or 7.5 mg/m 2 once weekly on a 28-day cycle; or 7.5 mg/m 2 on days 1 and 8 of a 21-day cycle; or 7.5 or 10.0 mg/m 2 once every 2 weeks on a 28-day cycle. Primary objectives were to evaluate safety and tolerability; antitumor activity and pharmacokinetic characterization were secondary objectives.\n\nResults: Forty-nine patients, most with urothelial carcinoma (UC; 25 of 49), received three previous lines of therapy (median). Common treatment-related adverse events (TRAEs) included nausea (49% [grade 3/4 2%]), likely because of a lack of prophylactic antiemetics during the dose-limiting toxicity period, and fatigue (39% [grade 3/4 6%]). The most common TRAEs of clinical interest were peripheral neuropathy (33% [grade 3/4 2%]), neutropenia (22% [grade 3/4 16%]), and skin reactions (22% [grade 3/4 2%]). The maximum tolerated dose was 7.5 mg/m 2 once every 2 weeks; the recommended phase 2 doses were 5.0 mg/m 2 once weekly and 7.5 mg/m 2 on days 1 and 8 of a 21-day cycle. Across doses (efficacy-evaluable; all tumor types), the objective response rate (ORR) was 24% and the clinical benefit rate (CBR) was 48% (n = 10 of 42; 95% CI, 12.1 to 39.5); the ORR was 38% and the CBR was 57% for patients with UC (n = 8 of 21; 95% CI, 18.1 to 61.6). The median duration of response and the median follow-up for all patients were 11.1 and 7.4 months, respectively.\n\nConclusion: Zelenectide pevedotin monotherapy demonstrated a generally well-tolerated safety profile and preliminary efficacy, particularly in UC, supporting investigation of UC and non-UC populations in the expansion phase.\n\nIndexed on Europe PMC as PubMed record 41197088 (DOI 10.1200/jco-25-00559). Its abstract cites the registry id NCT04561362, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-25-00559", pmid: "41197088", authors: "Baldini C, Verlingue L, Goldschmidt V, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04561362 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-25-00559"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41197088/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41197088"},{"label":"ClinicalTrials.gov NCT04561362","url":"https://clinicaltrials.gov/study/NCT04561362"}], tags: ["europepmc-ingest"], trials: ["nct04561362"], journals: ["jco"] }),
  p({ id: "paper-nct04579380-j-clin-oncol-2023", name: "Tucatinib and Trastuzumab for Previously Treated Human Epidermal Growth Factor Receptor 2-Positive Metastatic Biliary Tract Cancer (SGNTUC-019): A Phase II Basket Study", tldr: "Published report from the trial registered as NCT04579380, in Journal of Clinical Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: To evaluate the efficacy and safety of tucatinib and trastuzumab in patients with previously treated human epidermal growth factor receptor 2-positive (HER2+) metastatic biliary tract cancer (mBTC).\n\nMethods: SGNTUC-019 (ClinicalTrials.gov identifier: NCT04579380) is an open-label phase II basket study evaluating the efficacy and safety of tucatinib and trastuzumab in patients with HER2-altered solid tumors. In the biliary tract cancer cohort, patients had previously treated HER2 overexpressing or amplified (HER2+) tumors (identified with local testing) with no prior HER2-directed therapy. The primary end point was confirmed objective response rate (cORR) per investigator assessment. Patients were treated on a 21-day cycle with tucatinib (300 mg orally twice daily) and trastuzumab (8 mg/kg intravenously followed by 6 mg/kg every 3 weeks).\n\nResults: Thirty patients were enrolled. at data cutoff (January 30, 2023), the median duration of follow-up was 10.8 months. The cORR was 46.7% (90% CI, 30.8 to 63.0), with a disease control rate of 76.7% (90% CI, 60.6 to 88.5). The median duration of response and progression-free survival were 6.0 months (90% CI, 5.5 to 6.9) and 5.5 months (90% CI, 3.9 to 8.1), respectively. At data cutoff, 15 patients (50.0%) had died, and the estimated 12-month overall survival rate was 53.6% (90% CI, 36.8 to 67.8). The two most common treatment-emergent adverse events (TEAEs) were pyrexia (43.3%) and diarrhea (40.0%). Grade ≥3 TEAEs were reported in 18 patients (60.0%), with the most common being cholangitis, decreased appetite, and nausea (all 10.0%), which were generally not treatment related. TEAEs led to treatment regimen discontinuation in one patient, and there were no deaths due to TEAEs.\n\nConclusion: Tucatinib combined with trastuzumab had clinically significant antitumor activity and was well tolerated in patients with previously treated HER2+ mBTC.\n\nIndexed on Europe PMC as PubMed record 37751561 (DOI 10.1200/jco.23.00606). Its abstract cites the registry id NCT04579380, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.23.00606", pmid: "37751561", authors: "Nakamura Y, Mizuno N, Sunakawa Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04579380 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.23.00606"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37751561/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37751561"},{"label":"ClinicalTrials.gov NCT04579380","url":"https://clinicaltrials.gov/study/NCT04579380"}], tags: ["europepmc-ingest"], trials: ["nct04579380"], journals: ["jco"] }),
  p({ id: "paper-nct04585035-signal-transduct-target-ther-2025", name: "Garsorasib, a KRAS G12C inhibitor, with or without cetuximab, an EGFR antibody, in colorectal cancer cohorts of a phase II trial in advanced solid tumors with KRAS G12C mutation", tldr: "Published report from the trial registered as NCT04585035, in Signal transduction and targeted therapy (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Mutations in the KRAS gene have long been implicated in the pathogenesis of colorectal cancer (CRC). KRAS G12C inhibitors overcome the \"undruggable\" challenge, enabling precision therapy. Garsorasib (D-1553), a highly potent and selective KRAS G12C inhibitor, has demonstrated promising anti-tumor activity and favorable safety profile in early clinical trials. We conducted an open-label, nonrandomized phase II trial (ClinicalTrials.gov, NCT04585035) to assess the safety and efficacy of garsorasib with or without cetuximab in KRAS G12C-mutated CRC. In the monotherapy cohort (n = 26), objective response rate (ORR) was 19.2% (95% CI, 6.6-39.4), disease control rate (DCR) was 92.3% (95% CI, 74.9-99.1), median progression-free survival (PFS) was 5.5 months (95% CI, 2.9-11.6) and median overall survival (OS) was 13.1 months (95% CI, 9.5-NE). In the combination cohort (n = 42), ORR was 45.2% (95% CI, 29.8-61.3), DCR was 92.9% (95% CI, 80.5-98.5), median PFS was 7.5 months (95% CI, 5.5-8.1), and median OS was not reached. Grade ≥3 treatment-related adverse events occurred in 5 (19.2%) and 6 (14.3%) patients in monotherapy and combination cohort, respectively. Garsorasib with or without cetuximab showed a promising efficacy and manageable safety profiles in heavily pretreated patients with KRAS G12C-mutated CRC, providing a potential new treatment approach for such population.\n\nIndexed on Europe PMC as PubMed record 40523897 (DOI 10.1038/s41392-025-02274-z). Its abstract cites the registry id NCT04585035, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Signal transduction and targeted therapy", year: 2025, doi: "10.1038/s41392-025-02274-z", pmid: "40523897", authors: "Ruan DY, Wu HX, Xu Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04585035 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Signal Transduct Target Ther 2025","url":"https://doi.org/10.1038/s41392-025-02274-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40523897/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40523897"},{"label":"ClinicalTrials.gov NCT04585035","url":"https://clinicaltrials.gov/study/NCT04585035"}], tags: ["europepmc-ingest"], trials: ["nct04585035"] }),
  p({ id: "paper-nct04619004-j-clin-oncol-2023", name: "HERTHENA-Lung01, a Phase II Trial of Patritumab Deruxtecan (HER3-DXd) in Epidermal Growth Factor Receptor-Mutated Non-Small-Cell Lung Cancer After Epidermal Growth Factor Receptor Tyrosine Kinase Inhibitor Therapy and Platinum-Based Chemotherapy", tldr: "Published report from the HERTHENA-Lung01 trial registered as NCT04619004, in Journal of Clinical Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Patritumab deruxtecan, or HER3-DXd, is an antibody-drug conjugate consisting of a fully human monoclonal antibody to human epidermal growth factor receptor 3 (HER3) attached to a topoisomerase I inhibitor payload via a stable tetrapeptide-based cleavable linker. We assessed the efficacy and safety of HER3-DXd in patients with epidermal growth factor receptor ( EGFR)-mutated non-small-cell lung cancer (NSCLC).\n\nMethods: This phase II study (ClinicalTrials.gov identifier: NCT04619004) was designed to evaluate HER3-DXd in patients with advanced EGFR- mutated NSCLC previously treated with EGFR tyrosine kinase inhibitor (TKI) therapy and platinum-based chemotherapy (PBC). Patients received HER3-DXd 5.6 mg/kg intravenously once every 3 weeks or an uptitration regimen (3.2 → 4.8 → 6.4 mg/kg). The primary end point was confirmed objective response rate (ORR; RECIST 1.1) by blinded independent central review (BICR), with a null hypothesis of 26.4% on the basis of historical data.\n\nResults: Enrollment into the uptitration arm closed early on the basis of a prespecified benefit-risk assessment of data from the phase I U31402-A-U102 trial. In total, 225 patients received HER3-DXd 5.6 mg/kg once every 3 weeks. at May 18, 2023, median study duration was 18.9 (range, 14.9-27.5) months. Confirmed ORR by BICR was 29.8% (95% CI, 23.9 to 36.2); median duration of response, 6.4 months; median progression-free survival, 5.5 months; and median overall survival, 11.9 months. The subgroup of patients with previous osimertinib and PBC had similar outcomes. Efficacy was observed across a broad range of pretreatment tumor HER3 membrane expression levels and across diverse mechanisms of EGFR TKI resistance. In patients with nonirradiated brain metastases at baseline (n = 30), the confirmed CNS ORR by BICR per CNS RECIST was 33.3% (95% CI, 17.3 to 52.8). The safety profile (National Cancer Institute Common Terminology Criteria for Adverse Events v5.0) was manageable and tolerable, consistent with previous observations.\n\nConclusion: After tumor progression with EGFR TKI therapy and PBC in patients with EGFR -mutated NSCLC, HER3-DXd once every 3 weeks demonstrated clinically meaningful efficacy with durable responses, including in CNS metastases. A phase III trial in EGFR- mutated NSCLC after progression on an EGFR TKI is ongoing (HERTHENA-Lung02; ClinicalTrials.gov identifier: NCT05338970).\n\nIndexed on Europe PMC as PubMed record 37689979 (DOI 10.1200/jco.23.01476). Its abstract cites the registry id NCT04619004, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.23.01476", pmid: "37689979", authors: "Yu HA, Goto Y, Hayashi H, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04619004 with the most citations, so it is the natural first reading for anyone following the HERTHENA-Lung01 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","The abstract cites more than one registry id (NCT04619004, NCT05338970); it was kept because the trial's acronym appears in the title."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.23.01476"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37689979/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37689979"},{"label":"ClinicalTrials.gov NCT04619004","url":"https://clinicaltrials.gov/study/NCT04619004"}], tags: ["europepmc-ingest"], trials: ["nct04619004"], journals: ["jco"] }),
  p({ id: "paper-nct04665856-j-thorac-oncol-2026", name: "SKYSCRAPER-02C: A Phase 3, Randomized, Double-Blind, Placebo-Controlled Study of Atezolizumab Plus Carboplatin and Etoposide With or Without Tiragolumab in Patients With Untreated Extensive-Stage SCLC in China", tldr: "Published report from the SKYSCRAPER-02C trial registered as NCT04665856, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Tiragolumab may synergize with other immunotherapies to enhance antitumor immune responses. We report efficacy, safety, and biomarker findings from SKYSCRAPER-02C (NCT04665856), comparing tiragolumab plus atezolizumab plus carboplatin and etoposide (CE; experimental arm) with atezolizumab plus CE (control arm) in patients with untreated extensive-stage SCLC (ES-SCLC) in China.\n\nMethods: Patients were randomized (1:1) to tiragolumab 600 mg or placebo, plus atezolizumab 1200 mg and CE (four cycles), then maintenance tiragolumab or placebo plus atezolizumab. Primary end points were investigator-assessed progression-free survival (PFS) and overall survival (OS) in patients without history or presence of brain metastases at baseline (primary analysis set).\n\nResults: The primary analysis set comprised 54 patients in the experimental arm and 56 in the control arm. Median PFS was 5.6 months (experimental) and 5.4 months (control; unstratified hazard ratio = 0.65, 95% confidence interval: 0.43‒0.97; median follow-up 26.7 months); median OS was 18.7 and 13.5 months, respectively (unstratified hazard ratio 0.89, 95% confidence interval: 0.56‒1.40). The biomarker-evaluable population comprised 69 patients with immunohistochemistry data and 66 with RNA sequencing data. RNA sequencing survival analysis found that patients with non-negative matrix factorization 3 (SCLC-inflamed-neuroendocrine) or non-negative matrix factorization 4 (SCLC-inflamed-non-neuroendocrine) molecular subtypes, and those with high T-effector and tumor-associated macrophage immune signatures, benefited from tiragolumab plus atezolizumab plus CE treatment. Tiragolumab was well tolerated, with no new safety signals.\n\nConclusions: Although results from the global SKYSCRAPER-02 study were not statistically significant, numerical improvements in PFS and OS were observed with tiragolumab plus atezolizumab plus CE versus atezolizumab plus CE in Chinese patients with ES-SCLC. Biomarker analysis identified immune-inflamed signatures that may guide future tyrosine-based inhibitory motif domain-based strategies.\n\nIndexed on Europe PMC as PubMed record 41950998 (DOI 10.1016/j.jtho.2026.103713). Its abstract cites the registry id NCT04665856, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2026.103713", pmid: "41950998", authors: "Lu S, Fang J, Yu Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04665856 with the most citations, so it is the natural first reading for anyone following the SKYSCRAPER-02C trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2026.103713"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41950998/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41950998"},{"label":"ClinicalTrials.gov NCT04665856","url":"https://clinicaltrials.gov/study/NCT04665856"}], tags: ["europepmc-ingest"], trials: ["nct04665856"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct04687241-lancet-oncol-2026", name: "Aumolertinib as adjuvant therapy in resected EGFR-mutated non-small-cell lung cancer (ARTS): a double-blind, multicentre, randomised, controlled, phase 3 trial", tldr: "Published report from the trial registered as NCT04687241, in The Lancet Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Patients with resectable non-small-cell lung cancer (NSCLC), particularly those with EGFR mutations, face a high risk of recurrence and mortality post-surgery. Aumolertinib, a third-generation EGFR tyrosine-kinase inhibitor, is approved in China for adjuvant treatment in patients with NSCLC harbouring EGFR with an exon 19 deletion (ex19del) or exon 21 substitution (Leu858Arg) mutation. The ARTS study aimed to evaluate the efficacy and safety of adjuvant therapy with aumolertinib in patients with stage II-IIIB EGFR-mutated NSCLC.\n\nMethods: This double-blind, multicentre, randomised, controlled, phase 3 trial enrolled patients from 48 hospitals in mainland China. Eligible patients were 18 years or older with stage II-IIIB NSCLC, had undergone a complete resection followed by standard adjuvant therapy, and had an EGFR ex19del or Leu858Arg mutation and an Eastern Cooperative Oncology Group performance status score of 0 or 1. Patients were stratified by EGFR mutation status and tumour stage and were randomly assigned (1:1) to receive aumolertinib 110 mg or placebo orally, once daily for 3 years or until disease recurrence or other discontinuation criteria were met. Patients were randomly allocated to groups using an interactive web response system; the double‑dummy technique masked patients, investigators, and assessors. The primary endpoint was disease-free survival in the modified intention-to treat (mITT) population (ie, all patients with stage II-IIIB NSCLC harbouring EGFR mutations who had undergone complete tumour resection and standard adjuvant therapy), assessed by blinded independent central review (BICR). Safety was assessed in all patients who received at least one dose of study treatment. Although the study is ongoing, with some patients remaining in follow-up, this analysis represents the protocol-specified primary analysis. This study is registered with ClinicalTrials.gov (NCT04687241).\n\nFindings: Between April 30, 2021, and May 17, 2022, 399 individuals were screened for study eligibility; of these, 214 patients were randomly assigned to receive aumolertinib or placebo (107 in each group). 120 (56%) patients were female, 94 (44%) were male, median age was 59 years (IQR 54-66), and all patients were Chinese. 204 (95%) of 214 patients had received prior adjuvant chemotherapy. One patient in the aumolertinib group and three patients in the placebo group had stage I disease; therefore, 106 patients in the aumolertinib group and 104 in the placebo group were included in the mITT (primary analysis) population. at the data cutoff date (April 15, 2024), the median duration of follow-up was 27·56 months (IQR 22·18-27·70) in the aumolertinib group and 27·63 months (22·18-27·79) in the placebo group. The BICR-assessed disease-free survival was significantly improved in the aumolertinib group compared with the placebo group, with an HR of 0·17 (95% CI 0·09-0·29, p<0·0001). The median disease-free survival per BICR in the aumolertinib group was not reached (95% CI 29·14 to not applicable), whereas it was 19·42 months (11·24-26·22) in the placebo group. The most common grade 3-4 adverse events in the aumolertinib group versus the placebo group were increased blood creatine phosphokinase (seven [7%] vs none), prolonged electrocardiogram QT interval (three [3%] vs three [3%]), hypertension (one [1%] vs five [5%]), and pneumonia (two [2%] vs three [3%]). Treatment-related serious adverse events occurred in one (1%) patient receiving aumolertinib and three (3%) patients receiving placebo. No treatment-related deaths occurred and no new safety signals were identified for aumolertinib.\n\nInterpretation: Aumolertinib showed substantial clinical benefits as adjuvant therapy in Chinese patients with stage II-IIIB EGFR-mutated NSCLC. The manageable safety profile of aumolertinib supports its suitability in the adjuvant setting.\n\nFunding: Hansoh Pharmaceutical Group.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 41539318 (DOI 10.1016/s1470-2045(25)00643-6). Its abstract cites the registry id NCT04687241, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2026, doi: "10.1016/s1470-2045(25)00643-6", pmid: "41539318", authors: "Zhang L, Zhang X, Wu L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04687241 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2026","url":"https://doi.org/10.1016/s1470-2045(25)00643-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41539318/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41539318"},{"label":"ClinicalTrials.gov NCT04687241","url":"https://clinicaltrials.gov/study/NCT04687241"}], tags: ["europepmc-ingest"], trials: ["nct04687241"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct04765059-esmo-open-2025", name: "COMPEL: osimertinib plus platinum-based chemotherapy in patients with EGFR-mutated advanced NSCLC and progression on first-line osimertinib", tldr: "Published report from the COMPEL trial registered as NCT04765059, in ESMO Open (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: COMPEL (NCT04765059) was a global, randomized, double-blind study that evaluated osimertinib plus chemotherapy versus placebo plus chemotherapy in patients with epidermal growth factor receptor (EGFR)-mutated advanced non-small-cell lung cancer (NSCLC) following non-central nervous system (CNS) progression on first-line osimertinib.\n\nPatients and methods: Patients were randomly assigned to receive osimertinib 80 mg, or placebo, once daily (o.d.) in combination with chemotherapy [cisplatin 75 mg/m 2 or carboplatin area under the curve 5 plus pemetrexed 500 mg/m 2 every 3 weeks (q3w) for four cycles], followed by osimertinib 80 mg, or placebo, o.d. in combination with maintenance pemetrexed (500 mg/m 2 q3w) until progression. The primary endpoint was investigator-assessed progression-free survival (PFS). Secondary endpoints included CNS PFS according to CNS metastases status at baseline and overall survival (OS).\n\nResults: Ninety-eight patients were randomly assigned (49 per arm). Median PFS in all patients was 8.4 months [95% confidence interval (CI) 5.7-11.8 months] with osimertinib plus chemotherapy versus 4.4 months (95% CI 3.5-5.6 months) with placebo plus chemotherapy [hazard ratio (HR) 0.43, 95% CI 0.27-0.70]. CNS PFS was longer with osimertinib plus chemotherapy versus placebo plus chemotherapy (HR 0.56, 95% CI 0.27-1.13) in patients without baseline CNS metastases (n = 75). Median OS in all patients was 15.9 months (95% CI 12.4-20.8 months) with osimertinib plus chemotherapy versus 9.8 months (95% CI 8.4-17.2 months) with placebo plus chemotherapy (HR 0.71, 95% CI 0.42-1.23). Grade ≥3 adverse events occurred more frequently with osimertinib plus chemotherapy (63%) than placebo plus chemotherapy (46%).\n\nConclusions: In patients with non-CNS progression on first-line osimertinib, osimertinib plus chemotherapy was associated with improved PFS and longer OS compared with placebo plus chemotherapy. These findings support osimertinib as a backbone treatment for EGFR-mutated advanced NSCLC through lines of therapy.\n\nIndexed on Europe PMC as PubMed record 41139117 (DOI 10.1016/j.esmoop.2025.105807). Its abstract cites the registry id NCT04765059, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "ESMO Open", year: 2025, doi: "10.1016/j.esmoop.2025.105807", pmid: "41139117", authors: "Peled N, Tufman A, Sequist LV, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04765059 with the most citations, so it is the natural first reading for anyone following the COMPEL trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"ESMO Open 2025","url":"https://doi.org/10.1016/j.esmoop.2025.105807"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41139117/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41139117"},{"label":"ClinicalTrials.gov NCT04765059","url":"https://clinicaltrials.gov/study/NCT04765059"}], tags: ["europepmc-ingest"], trials: ["nct04765059"], journals: ["esmo-open"] }),
  p({ id: "paper-nct04819100-n-engl-j-med-2026", name: "Selpercatinib in Early-Stage RET Fusion-Positive Non-Small-Cell Lung Cancer", tldr: "Published report from the LIBRETTO-432 trial registered as NCT04819100, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Selpercatinib, a highly selective, potent, and central nervous system-penetrant RET inhibitor, is approved for RET fusion-positive advanced or metastatic non-small-cell lung cancer (NSCLC). The efficacy and safety of selpercatinib in early-stage NSCLC are unknown.\n\nMethods: We conducted a phase 3, double-blind trial involving patients with RET fusion-positive NSCLC who had received definitive therapy with curative intent (surgery or radiotherapy with adjuvant systemic anticancer therapy, if applicable). Patients were randomly assigned to receive adjuvant selpercatinib or placebo for up to 3 years. The primary end point was investigator-assessed event-free survival in patients with stage II or IIIA disease. Secondary end points were investigator-assessed event-free survival in patients with stage IB, II, or IIIA disease; event-free survival as assessed by blinded independent central review; overall survival; and safety.\n\nResults: A total of 151 patients were assigned to receive selpercatinib (75 patients) or placebo (76 patients). Median follow-up was 24 months and 27 months in the respective groups. Among 109 patients with stage II or IIIA disease, 2-year investigator-assessed event-free survival was 92% with selpercatinib and 61% with placebo (hazard ratio for disease recurrence, progression, or death, 0.17; 95% confidence interval [CI], 0.06 to 0.51; P<0.001). Event-free survival as assessed by blinded independent central review was consistent with investigator-assessed event-free survival. Among the 151 patients with stage IB, II, or IIIA NSCLC, investigator-assessed event-free survival at 2 years was 94% with selpercatinib and 70% with placebo (hazard ratio for disease recurrence, progression, or death, 0.16; 95% CI, 0.06 to 0.48; P<0.001). The most common adverse events during the treatment period were increased levels of alanine aminotransferase and aspartate aminotransferase (grade ≥3 in 17% and 19% of patients, respectively, in the selpercatinib group). Three deaths occurred, all in the placebo group, owing to disease progression.\n\nConclusions: Among patients with stage II or IIIA RET fusion-positive NSCLC, event-free survival was significantly longer with adjuvant selpercatinib than with placebo. (Funded by Lilly; LIBRETTO-432 ClinicalTrials.gov number, NCT04819100.).\n\nIndexed on Europe PMC as PubMed record 42223087 (DOI 10.1056/nejmoa2602628). Its abstract cites the registry id NCT04819100, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2602628", pmid: "42223087", authors: "Wu YL, Hochmair M, Yang Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04819100 with the most citations, so it is the natural first reading for anyone following the LIBRETTO-432 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2602628"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42223087/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42223087"},{"label":"ClinicalTrials.gov NCT04819100","url":"https://clinicaltrials.gov/study/NCT04819100"}], tags: ["europepmc-ingest"], trials: ["nct04819100"], journals: ["nejm"] }),
  p({ id: "paper-nct04923906-lancet-oncol-2026", name: "Aumolertinib with or without chemotherapy in EGFR-mutated advanced non-small-cell lung cancer (AENEAS2): an open-label, multicentre, randomised, controlled, phase 3 trial", tldr: "Published report from the trial registered as NCT04923906, in The Lancet Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Although third-generation epidermal growth-factor receptor (EGFR)-tyrosine-kinase inhibitors (TKIs) are standard first-line therapies for patients with advanced EGFR-mutated non-small-cell lung cancer (NSCLC), their effectiveness is often limited by the emergence of drug resistance and subsequent disease progression. Given the previously established clinical efficacy and adverse event profile of aumolertinib, we aimed to evaluate the efficacy and adverse event profile of aumolertinib in combination with platinum-based chemotherapy versus aumolertinib monotherapy as first-line treatment for patients with locally advanced or metastatic NSCLC patients with EGFR-sensitive mutations.\n\nMethods: The open-label, multicentre, randomised, controlled, phase 3 AENEAS2 trial was done across 60 hospitals in China. Patients aged at least 18 years with Eastern Cooperative Oncology Group performance status (ECOG PS) 0-1; treatment-naive; histologically or cytologically confirmed locally advanced or metastatic NSCLC harbouring EGFR-sensitive mutations (ex19del/L858R with or without other EGFR mutations) were eligible. Brain metastases were allowed if neurologically stable. Previous EGFR-TKI therapy was an exclusion criterion. Patients were randomly assigned (1:1) with block randomisation (block size of 6), stratified by EGFR mutation type and baseline brain metastasis, to receive aumolertinib monotherapy (110 mg orally once a day) or combination therapy (aumolertinib 110 mg orally once a day plus pemetrexed 500 mg/m 2 intravenously with cisplatin [75 mg/m 2 ] or carboplatin [area under the plasma concentration-time curve 5] intravenously on day 1 of 21-day cycles for 4-6 cycles), followed by maintenance therapy (aumolertinib 110 mg orally once a day and pemetrexed 500 mg/m 2 intravenously once every 3 weeks). The primary endpoint was progression-free survival assessed by blinded independent central review (BICR; RECIST version 1.1). Efficacy was analysed in the full-analysis set, which included all randomly assigned patients, and safety was analysed in patients who received at least one dose of the actual trial treatment. The trial is registered at ClinicalTrials.gov, NCT04923906, and is ongoing, but closed to enrolment.\n\nFindings: Between Aug 4, 2021, to June 18, 2024, of 1011 patients assessed for eligibility, 624 randomly assigned patients (median age 59·0 years [IQR 52·0-66·0]; 337 [54%] were female, 287 [46%] were male) were randomly assigned. 310 (50%) patients received combination therapy and 314 (50%) received monotherapy. at the data cutoff date (June 18, 2024), the median follow-up was 23·4 months (IQR 20·5-26·5), In the full-analysis set, median BICR-assessed progression-free survival was 28·9 months (95% CI 26.3, NA) in the combination therapy versus 18·9 months (17·8-21·1) in the monotherapy (hazard ratio [HR] 0·47, 95% CI 0·37-0·60; log-rank p<0·0001). The most common grade 3-4 adverse events (occurring in at least 20% in any group) were neutrophil count decreased (168 [55%] of 304 in the combination group versus four [1%] of 316 in monotherapy group), white blood cell count decreased (103 [34%] vs one [<1%]), and platelet count decreased (62 [20%] vs two [1%]). Serious adverse events occurred in 109 (36%) patients in the combination group and 53 (17%) in the monotherapy group, the most common of which were platelet count decreased (22 [7%] vs 0), neutrophil count decreased (17 [6%] vs 0), white blood cell count decreased (13 [4%] vs 0), and anaemia (ten [3%] vs two [1%]). Treatment-related deaths occurred in one (<1%) patient in the combination group (encephalopathy) and two (1%) in the monotherapy group (pulmonary embolism and respiratory failure with circulatory collapse).\n\nInterpretation: Aumolertinib in combination with chemotherapy significantly improved progression-free survival. Although this regimen was associated with increased toxicity, the side-effects were managed with dose adjustment and supportive treatment aligned with clinical practice. Long-term follow-up is required to assess overall survival. The AENEAS2 study provides evidence to guide clinical practice regarding EGFR-TKIs and their combination use in treating patients with advanced EGFR-mutated NSCLC.\n\nFunding: Jiangsu Hansoh Pharmaceutical Group, and the Collaborative Innovation Center for Clinical and Translational Science by Ministry of Education & Shanghai.\n\nTranslations: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 42296979 (DOI 10.1016/s1470-2045(26)00090-2). Its abstract cites the registry id NCT04923906, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2026, doi: "10.1016/s1470-2045(26)00090-2", pmid: "42296979", authors: "Li Z, Hu J, Chen J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04923906 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2026","url":"https://doi.org/10.1016/s1470-2045(26)00090-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42296979/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42296979"},{"label":"ClinicalTrials.gov NCT04923906","url":"https://clinicaltrials.gov/study/NCT04923906"}], tags: ["europepmc-ingest"], trials: ["nct04923906"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct04956640-nat-commun-2026", name: "Pan-tumor activity of olomorasib, a next-generation KRAS G12C inhibitor in KRAS G12C-mutant advanced solid tumors: a first-in-human study", tldr: "Published report from the trial registered as NCT04956640, in Nature Communications (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "This multicenter, first-in-human Phase 1 study (NCT04956640) evaluated olomorasib (LY3537982), a next-generation KRAS G12C inhibitor designed to enhance target occupancy at low absolute exposures. In total, data from 195 patients are reported: Phase 1a dose escalation (n = 112) assessed olomorasib monotherapy at 50, 100, 150 or 200 mg BID across KRAS G12C-mutant advanced solid tumors; the primary objective was to determine the recommended Phase 2 dose (RP2D) based on dose-limiting toxicities (DLTs). No DLTs occurred, and 150 mg BID was selected as the RP2D. The primary objective for the Phase 1b dose expansion (n = 83) was to evaluate the safety and tolerability of olomorasib in specific KRAS G12C-mutant tumor types. Olomorasib was well tolerated, with predominantly grade 1-2 treatment-related adverse events (TRAEs) and infrequent grade 3 TRAEs; no grade 4/5 TRAEs occurred. Secondary objectives evaluated the antitumor activity of olomorasib. Among 168 efficacy-evaluable patients, the ORR and median PFS were both higher in non-CRC solid tumors compared to CRC, including in patients with NSCLC who previously received a KRAS G12C inhibitor. Intracranial responses were observed in patients with untreated, active brain metastases. This may support the potential of next-generation KRAS G12C inhibitors to overcome limitations of earlier agents and justify further investigation of combination therapy.\n\nIndexed on Europe PMC as PubMed record 41820335 (DOI 10.1038/s41467-026-69943-7). Its abstract cites the registry id NCT04956640, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Communications", year: 2026, doi: "10.1038/s41467-026-69943-7", pmid: "41820335", authors: "Murciano-Goroff YR, Hollebecque A, Heist RS, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04956640 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Commun 2026","url":"https://doi.org/10.1038/s41467-026-69943-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41820335/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41820335"},{"label":"ClinicalTrials.gov NCT04956640","url":"https://clinicaltrials.gov/study/NCT04956640"}], tags: ["europepmc-ingest"], trials: ["nct04956640"], journals: ["nature-communications"] }),
  p({ id: "paper-nct05009329-nat-med-2025", name: "Glecirasib in KRAS G12C -mutated nonsmall-cell lung cancer: a phase 2b trial", tldr: "Published report from the trial registered as NCT05009329, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Glecirasib (JAB-21822) is a new covalent oral KRAS-G12C inhibitor. This multicenter, single-arm phase 2b study assessed the efficacy and safety of glecirasib administered orally at 800 mg daily in patients with locally advanced or metastatic KRAS G12C -mutated nonsmall-cell lung cancer. The primary endpoint was the objective response rate (ORR) assessed by an independent review committee (IRC). Between 15 September 2022 and 28 September 2023, 119 patients with a median age of 62 years were enrolled. at the data cut-off date on 28 March 2024, the ORR assessed by IRC was 47.9% (56/117; 95% confidence interval: 38.5-57.3%). The incidence of treatment-related adverse events (TRAEs) of any grade was 97.5% (116/119). The incidence of grades 3 and 4 TRAEs was 38.7% (46/119). A total of 5.0% (6/119) of patients discontinued the treatment due to TRAEs. No treatment-related deaths occurred. Glecirasib exhibited promising clinical efficacy and manageable safety profiles in these patient populations. ClinicalTrials.gov identifier: NCT05009329.\n\nIndexed on Europe PMC as PubMed record 39762419 (DOI 10.1038/s41591-024-03401-z). Its abstract cites the registry id NCT05009329, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-024-03401-z", pmid: "39762419", authors: "Shi Y, Fang J, Xing L, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05009329 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-024-03401-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39762419/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39762419"},{"label":"ClinicalTrials.gov NCT05009329","url":"https://clinicaltrials.gov/study/NCT05009329"}], tags: ["europepmc-ingest"], trials: ["nct05009329"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05081609-j-immunother-cancer-2022", name: "TransCon IL-2 β/γ: a novel long-acting prodrug with sustained release of an IL-2Rβ/γ-selective IL-2 variant with improved pharmacokinetics and potent activation of cytotoxic immune cells for the treatment of cancer", tldr: "Published report from the trial registered as NCT05081609, in Journal for ImmunoTherapy of Cancer (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Recombinant interleukin-2 (IL-2, aldesleukin) is an approved cancer immunotherapy but causes severe toxicities including cytokine storm and vascular leak syndrome (VLS). IL-2 promotes antitumor function of IL-2Rβ/γ + natural killer (NK) cells and CD8 +, CD4 + and gamma delta (γδ) T cells. However, IL-2 also potently activates immunosuppressive IL-2Rα + regulatory T cells (Tregs) and IL-2Rα + eosinophils and endothelial cells, which may promote VLS. Aldesleukin is rapidly cleared requiring frequent dosing, resulting in high C max likely potentiating toxicity. Thus, IL-2 cancer immunotherapy has two critical drawbacks: potent activation of undesired IL-2Rα + cells and suboptimal pharmacokinetics with high C max and short half-life.\n\nMethods: TransCon IL-2 β/γ was designed to optimally address these drawbacks. To abolish IL-2Rα binding yet retain strong IL-2Rβ/γ activity, IL-2 β/γ was created by permanently attaching a small methoxy polyethylene glycol (mPEG) moiety in the IL-2Rα binding site. To improve pharmacokinetics, IL-2 β/γ was transiently attached to a 40 kDa mPEG carrier via a TransCon (transient conjugation) linker creating a prodrug, TransCon IL-2 β/γ, with sustained release of IL-2 β/γ. IL-2 β/γ was characterized in binding and primary cell assays while TransCon IL-2 β/γ was studied in tumor-bearing mice and cynomolgus monkeys.\n\nResults: IL-2 β/γ demonstrated selective and potent human IL-2Rβ/γ binding and activation without IL-2Rα interactions. TransCon IL-2 β/γ showed slow-release pharmacokinetics with a low C max and a long (>30 hours) effective half-life for IL-2 β/γ in monkeys. In mouse tumor models, TransCon IL-2 β/γ promoted CD8 + T cell and NK cell activation and antitumor activity. In monkeys, TransCon IL-2 β/γ induced robust activation and expansion of CD8 + T cells, NK cells and γδ T cells, relative to CD4 + T cells, Tregs and eosinophils, with no evidence of cytokine storm or VLS. Similarly, IL-2 β/γ enhanced proliferation and cytotoxicity of primary human CD8 + T cells, NK cells and γδ T cells.\n\nSummary: TransCon IL-2 β/γ is a novel long-acting prodrug with sustained release of an IL-2Rβ/γ-selective IL-2. It has remarkable and durable pharmacodynamic effects in monkeys and potential for improved clinical efficacy and tolerability compared with aldesleukin. TransCon IL-2 β/γ is currently being evaluated in a Phase 1/2 clinical trial (NCT05081609).\n\nIndexed on Europe PMC as PubMed record 35817480 (DOI 10.1136/jitc-2022-004991). Its abstract cites the registry id NCT05081609, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal for ImmunoTherapy of Cancer", year: 2022, doi: "10.1136/jitc-2022-004991", pmid: "35817480", authors: "Rosen DB, Kvarnhammar AM, Laufer B, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05081609 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Immunother Cancer 2022","url":"https://doi.org/10.1136/jitc-2022-004991"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35817480/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35817480"},{"label":"ClinicalTrials.gov NCT05081609","url":"https://clinicaltrials.gov/study/NCT05081609"}], tags: ["europepmc-ingest"], trials: ["nct05081609"], journals: ["jitc"] }),
  p({ id: "paper-nct05128487-cell-rep-med-2026", name: "HPK1 inhibitor NDI-101150 as monotherapy and in combination with pembrolizumab in patients with advanced solid tumors: Phase 1/2 trial results", tldr: "Published report from the trial registered as NCT05128487, in Cell reports. Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Hematopoietic progenitor kinase 1 (HPK1) induces potent anti-tumor immunity in preclinical models by activating and recruiting T cells, B cells, and dendritic cells into the tumor microenvironment (TME). Here, we evaluate NDI-101150, a potent, selective HPK1 inhibitor, in a phase 1/2 trial as a monotherapy or in combination with pembrolizumab in patients with advanced solid tumors. The monotherapy maximum tolerated dose (MTD) is 150 mg once daily, and doses tested up to 100 mg once daily are combinable with pembrolizumab without reaching an MTD. In clear cell renal cell carcinoma, the investigator-assessed overall response rate with monotherapy treatment is 13.6%, including one complete response and two partial responses, with a clinical benefit rate of 27.3% and a disease control rate of 54.5%. Pharmacodynamic analyses show pharmacodynamic biomarker phospho-SLP76 inhibition and increased activated CD8 + T cells and dendritic cells in the TME, supporting continued development (clinical registration number NCT05128487).\n\nIndexed on Europe PMC as PubMed record 42097144 (DOI 10.1016/j.xcrm.2026.102789). Its abstract cites the registry id NCT05128487, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Cell reports. Medicine", year: 2026, doi: "10.1016/j.xcrm.2026.102789", pmid: "42097144", authors: "Braun DA, Noel MS, Moy RH, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05128487 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Cell Rep Med 2026","url":"https://doi.org/10.1016/j.xcrm.2026.102789"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42097144/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42097144"},{"label":"ClinicalTrials.gov NCT05128487","url":"https://clinicaltrials.gov/study/NCT05128487"}], tags: ["europepmc-ingest"], trials: ["nct05128487"] }),
  p({ id: "paper-nct05186974-j-thorac-oncol-2026", name: "First-Line Sacituzumab Govitecan Plus Pembrolizumab in Metastatic NSCLC: PD-L1 TPS Less Than 50% and More Than or Equal to 50% Cohorts of the EVOKE-02 Study", tldr: "Published report from the EVOKE-02 trial registered as NCT05186974, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Sacituzumab govitecan (SG) is a Trop-2-directed antibody-drug conjugate previously studied in patients with pretreated metastatic NSCLC (mNSCLC). Here, we report the results of EVOKE-02 (NCT05186974), a global, open-label, multicohort phase 2 study of SG plus pembrolizumab as first-line treatment in patients with mNSCLC.\n\nMethods: Adult patients without prior systemic mNSCLC treatment, and no actionable genomic alterations, received SG 10 mg/kg intravenously on days 1 and 8 plus pembrolizumab 200 mg intravenously on day 1 of 21-day cycles. The primary end point was objective response rate (ORR) per independent review committee, and secondary end points included progression-free survival (PFS) and safety.\n\nResults: at data cutoff (June 3, 2024), there were 30 patients with programmed death-ligand 1 (PD-L1) tumor proportion score (TPS) more than or equal to 50% (cohort A) and 62 patients with PD-L1 TPS less than 50% (cohort B). ORR (95% confidence interval) was 66.7% (47.2-82.7) for cohort A and 29.0% (18.2-41.9) for cohort B. Median (95% confidence interval) PFS was 13.1 (6.7-not reached) months for cohort A and 7.0 (4.2-12.9) months for cohort B. Trop-2 expression did not correlate with greater clinical efficacy (PFS, ORR) from treatment with SG plus pembrolizumab. Grade 3 or greater treatment-emergent adverse events (TEAEs) occurred in 70 patients (76.1%); the most common TEAE was neutropenia (17.4%). TEAEs leading to discontinuation of any study drug occurred in 25 patients (27.2%).\n\nConclusions: SG plus pembrolizumab demonstrated activity as treatment for mNSCLC, especially in patients with PD-L1 TPS more than or equal to 50%. AEs were manageable and consistent with the known safety profile of each individual agent.\n\nIndexed on Europe PMC as PubMed record 41173143 (DOI 10.1016/j.jtho.2025.10.016). Its abstract cites the registry id NCT05186974, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2025.10.016", pmid: "41173143", authors: "Reck M, Patel JD, Gray JE, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05186974 with the most citations, so it is the natural first reading for anyone following the EVOKE-02 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2025.10.016"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41173143/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41173143"},{"label":"ClinicalTrials.gov NCT05186974","url":"https://clinicaltrials.gov/study/NCT05186974"}], tags: ["europepmc-ingest"], trials: ["nct05186974"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct05195632-lung-cancer-2026", name: "A phase 2 study of encorafenib in combination with binimetinib for Chinese participants with BRAF V600E mutated metastatic non-small cell lung cancer: Results from the OCEAN II study", tldr: "Published report from the OCEANII trial registered as NCT05195632, in Lung cancer (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: The ongoing OCEAN II study (ClinicalTrials.gov identifier: NCT05195632) evaluates encorafenib in combination with binimetinib (E+B) in Chinese participants with BRAF V600E -mutated metastatic non-small cell lung cancer (NSCLC).\n\nMethods: Participants with metastatic unresectable stage IV BRAF V600E -mutated NSCLC (treatment-naïve or with prior systemic therapy excluding BRAF/MEK-inhibitors), were enrolled in a phase 2 study with two parts: safety lead-in (SLI) and pivotal part (PP). Participants received daily oral encorafenib (450mg) and twice daily oral binimetinib (90mg total). Primary endpoints were dose-limiting toxicities (DLT) during SLI and confirmed objective response rate by independent central review (cORR-ICR) during PP. Secondary endpoints were other measures of efficacy, safety, and pharmacokinetics.\n\nResults: In total, 63 participants were enrolled. One DLT (non-serious Grade 3 lipase increased) during SLI considered possibly related to E+B resolved without intervention, supporting initiation of PP. Pre-defined statistical efficacy criteria on the first 50 participants were met. In the main analysis, cORR-ICRwas59% (95%CI 45-72). At a later ad hoc analysis, cORR-ICR was 61% (95%CI 47-74), disease control rate 87% (95%CI 75-95). Medians (95%CI) were, time-to-response 1.8 months, duration of response 17.5 months, progression-free survival 13.8 months (7.5-not estimable), overall survival 27.9 months (14.7-30.0). 98.4% of participants experienced ≥1 treatment-related TEAE, and 55.6% had any Grade ≥3 TEAE. Nine (14.3%) participants discontinued any drug due to adverse events.\n\nConclusion: These data confirm the clinical benefit of E+B in Chinese participants with BRAF V600E -mNSCLC, a population with distinct genomic and disease characteristics. No new safety concerns were identified in Chinese participants.\n\nIndexed on Europe PMC as PubMed record 42612509 (DOI 10.1016/j.lungcan.2026.109580). Its abstract cites the registry id NCT05195632, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Lung cancer", year: 2026, doi: "10.1016/j.lungcan.2026.109580", pmid: "42612509", authors: "Zhou H, Zhou Q, Guo Q, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05195632 with the most citations, so it is the natural first reading for anyone following the OCEANII trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lung Cancer 2026","url":"https://doi.org/10.1016/j.lungcan.2026.109580"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42612509/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42612509"},{"label":"ClinicalTrials.gov NCT05195632","url":"https://clinicaltrials.gov/study/NCT05195632"}], tags: ["europepmc-ingest"], trials: ["nct05195632"], journals: ["lung-cancer-journal"] }),
  p({ id: "paper-nct05199272-cancer-res-commun-2025", name: "First-in-Human Study of 23ME-00610, an Antagonistic Antibody for Genetically Validated CD200R1 Immune Checkpoint, in Participants with Advanced Solid Malignancies", tldr: "Published report from the trial registered as NCT05199272, in Cancer research communications (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: In this phase 1 portion of a first-in-human phase 1/2a study (NCT05199272), 23ME-00610 was evaluated in participants with advanced solid malignancies to determine its safety, tolerability, pharmacokinetics (PK), and pharmacodynamics (PD). Exploratory biomarkers were evaluated to examine potential correlates of efficacy and safety.\n\nPatients and methods: Eligible participants (≥18 years) were administered 23ME-00610 intravenously every 3 weeks (Q3W) using an accelerated titration design followed by a traditional 3 + 3 design, with an initial dose level of 2 mg.\n\nResults: Twenty-eight participants were enrolled across seven cohorts and received a median of four cycles of 23ME-00610. No treatment-related serious adverse events (AE) were observed, and the maximum tolerated dose was not reached. Overall, the PK of 23ME-00610 was linear and dose proportional for doses ≥60 mg, with a median terminal half-life of 13 days at 1,400 mg. Peripheral saturation of CD200R1 was observed for doses ≥60 mg. Immune-related AEs, including rash, pruritus, and hypothyroidism, were predicted by phenome-wide association studies and observed for doses ≥60 mg. A confirmed partial response was observed in a participant with well-differentiated pancreatic neuroendocrine cancer whose tumor was among those with the highest tumor CD200 expression.\n\nConclusions: 23ME-00610 has mild-to-moderate on-target AEs and PK/PD consistent with tumor target saturation and dosing every 3 weeks. The trend for clinical benefit in participants with tumor CD200 expression suggests that 23ME-00610 inhibits CD200R1 signaling and may reverse CD200-mediated immune evasion. Based on PK/PD, safety, and preliminary antitumor activity, 1,400 mg Q3W was selected as the dose for further study.\n\nSignificance: Genome-wide association studies (GWAS) of the 23andMe genetic database identified CD200R1 as a promising therapeutic target for cancer. This phase 1 study of 23ME-00610, a CD200R1 antagonist IgG1, showed acceptable safety and tolerability, PK supporting Q3W dosing, and PD and preliminary clinical activity supporting an initial recommended phase 2 dose of 1,400 mg.\n\nIndexed on Europe PMC as PubMed record 39651931 (DOI 10.1158/2767-9764.crc-24-0568). Its abstract cites the registry id NCT05199272, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Cancer research communications", year: 2025, doi: "10.1158/2767-9764.crc-24-0568", pmid: "39651931", authors: "Kummar S, Razak AA, Laurie S, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05199272 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Cancer Res Commun 2025","url":"https://doi.org/10.1158/2767-9764.crc-24-0568"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39651931/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39651931"},{"label":"ClinicalTrials.gov NCT05199272","url":"https://clinicaltrials.gov/study/NCT05199272"}], tags: ["europepmc-ingest"], trials: ["nct05199272"], journals: ["cancer-research-communications"] }),
  p({ id: "paper-nct05246514-clin-lung-cancer-2026", name: "Trastuzumab Deruxtecan in Patients From China With Pretreated HER2-Mutant Non-Small Cell Lung Cancer: Final Analysis of the Phase 2, Single-Arm DESTINY-Lung05 Trial", tldr: "Published report from the DESTINY-Lung05 trial registered as NCT05246514, in Clinical lung cancer (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Trastuzumab deruxtecan (T-DXd) was approved in China in October 2024 for previously treated human epidermal growth factor receptor 2 (HER2)-mutant (HER2m) unresectable/metastatic non-small cell lung cancer (NSCLC), based on DESTINY-Lung02 and DESTINY-Lung05 primary results. Here, we report the DESTINY-Lung05 final analysis.\n\nMethods: DESTINY-Lung05 (NCT05246514), an open-label, single-arm, multicenter, phase 2 study, investigated T-DXd (5.4 mg/kg once every 3 weeks) in patients from China with HER2m (locally or centrally confirmed activating HER2 exon 19/20 mutation) metastatic NSCLC with disease progression on/after ≥ 1 prior anticancer therapy. The primary endpoint was confirmed objective response rate (ORR) per Response Evaluation Criteria in Solid Tumors 1.1 by independent central review (ICR). Secondary endpoints included progression-free survival (PFS) by ICR, overall survival (OS), and safety.\n\nResults: at November 4, 2024, 72 patients with HER2m NSCLC had received T-DXd 5.4 mg/kg; the median duration of follow-up was 20.2 months (range, 2-27). Confirmed ORR (ICR) was 56.9% (95% confidence interval [CI] 44.7-68.6). Median PFS (ICR) and OS were 9.9 months (95% CI 7.1-16.5) and 21.0 months (95% CI 17.5-not calculable), respectively. Grade ≥ 3 drug-related adverse events occurred in 40 (55.6%) patients. Adjudicated drug-related interstitial lung disease/pneumonitis events were observed in 9 (12.5%) patients (n = 8 grade 1/2; n = 1 grade 3).\n\nConclusions: With extended follow-up, T-DXd continued to demonstrate clinically meaningful and durable antitumor activity in patients from China with pretreated HER2m metastatic NSCLC, with no new safety signals. Results affirm the use of T-DXd as a treatment option in China for this patient population.\n\nIndexed on Europe PMC as PubMed record 42480250 (DOI 10.1016/j.cllc.2026.06.003). Its abstract cites the registry id NCT05246514, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Clinical lung cancer", year: 2026, doi: "10.1016/j.cllc.2026.06.003", pmid: "42480250", authors: "Liu Y, Li D, Wu L, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05246514 with the most citations, so it is the natural first reading for anyone following the DESTINY-Lung05 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Clin Lung Cancer 2026","url":"https://doi.org/10.1016/j.cllc.2026.06.003"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42480250/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42480250"},{"label":"ClinicalTrials.gov NCT05246514","url":"https://clinicaltrials.gov/study/NCT05246514"}], tags: ["europepmc-ingest"], trials: ["nct05246514"], journals: ["clinical-lung-cancer"] }),
  p({ id: "paper-nct05663866-j-thorac-oncol-2025", name: "Preventing Infusion-Related Reactions With Intravenous Amivantamab-Results From SKIPPirr, a Phase 2 Study: A Brief Report", tldr: "Published report from the trial registered as NCT05663866, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Amivantamab, an EGFR-MET bispecific antibody, is approved for multiple indications in EGFR-mutated advanced NSCLC as monotherapy or combined with other agents. Intravenous amivantamab is associated with a 67% infusion-related reaction (IRR) rate.\n\nMethods: The phase 2 SKIPPirr study (NCT05663866) enrolled participants with EGFR-mutated (exon 19 deletion or exon 21 L858R) advanced NSCLC after progression on osimertinib and platinum-based chemotherapy who received intravenous amivantamab plus oral lazertinib (amivantamab-lazertinib), a third-generation tyrosine kinase inhibitor. Aiming to mitigate IRRs, four independent prophylactic approaches were evaluated using Simon's two-stage design with an expansion stage if a cohort passed both stages: oral dexamethasone 4 mg twice daily given on cycle (C) 1 day (D) -1 (two doses); oral dexamethasone 8 mg twice daily given on C1D-2, C1D-1, and the morning of C1D1 (five doses); oral montelukast 10 mg once daily given on C1D-4, C1D-3, C1D-2, C1D-1, and C1D1 (five doses); subcutaneous methotrexate 25 mg (one dose) given anytime between C1D-7 and C1D-3. The primary end point was C1D1 IRR incidence.\n\nResults: at June 24, 2024, 68 participants were treated across all cohorts. The dexamethasone 8 mg cohort passed stages 1 and 2 proceeding to the expansion stage, with 24 additional participants treated. At C1D1, nine of 40 participants (22.5%) experienced IRRs, resulting in an approximately threefold decrease versus historical data (67.4%). By the end of C3, 10 of 41 participants (24.4%) in the dexamethasone 8 mg cohort experienced IRRs (grades 1-2, except one grade 3 on C2D1). Amivantamab-lazertinib's safety and efficacy were consistent with previous reports.\n\nConclusions: Prophylaxis with 8 mg oral dexamethasone meaningfully reduced IRRs and can be readily implemented in clinical practice.\n\nIndexed on Europe PMC as PubMed record 39864547 (DOI 10.1016/j.jtho.2025.01.018). Its abstract cites the registry id NCT05663866, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2025.01.018", pmid: "39864547", authors: "Spira AI, Paz-Ares L, Han JY, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05663866 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2025.01.018"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39864547/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39864547"},{"label":"ClinicalTrials.gov NCT05663866","url":"https://clinicaltrials.gov/study/NCT05663866"}], tags: ["europepmc-ingest"], trials: ["nct05663866"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct05668988-n-engl-j-med-2026", name: "First-Line Sunvozertinib in NSCLC with EGFR Exon 20 Insertion Mutations", tldr: "Published report from the WU-KONG28 trial registered as NCT05668988, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sunvozertinib received accelerated approval for use in later lines of therapy for patients with advanced non-small-cell lung cancer (NSCLC) with epidermal growth factor receptor ( EGFR) exon 20 insertion mutations. Data are needed on the efficacy and safety of sunvozertinib as a first-line treatment for NSCLC.\n\nMethods: In this phase 3, international trial, we randomly assigned, in a 1:1 ratio, patients with advanced nonsquamous NSCLC with EGFR exon 20 insertions to receive sunvozertinib or chemotherapy (carboplatin-pemetrexed). The primary end point was progression-free survival as assessed by blinded independent central review. Crossover to the sunvozertinib group was allowed after disease progression was confirmed. Secondary end points included overall survival, investigator-assessed progression-free survival, objective response (complete or partial response), change in tumor size, and duration of response.\n\nResults: A total of 324 patients were randomly assigned to receive sunvozertinib (163 patients) or chemotherapy (161 patients). Treatment with sunvozertinib led to significantly longer median progression-free survival than chemotherapy (10.3 vs. 7.5 months; hazard ratio for disease progression or death, 0.65; 95% confidence interval, 0.50 to 0.85; P<0.001). At 12 months, progression-free survival was reported in 46.1% of the patients in the sunvozertinib group and in 26.7% of those in the chemotherapy group; the data for overall survival were immature (38.9% maturity). The percentage of patients with an objective response was 58.9% in the sunvozertinib group and 31.1% in the chemotherapy group; the median best percentage change in tumor size was -42.1% and -24.7% respectively, and the median duration of response was 11.2 and 7.1 months. Grade 3 or higher adverse events were reported in 75.5% of the patients in the sunvozertinib group and in 56.7% of those in the chemotherapy group. In the sunvozertinib group, the most common adverse events of grade 3 or higher included increased serum creatine kinase levels, diarrhea, and anemia. No deaths were attributed to adverse events considered by the investigators to be related to sunvozertinib.\n\nConclusions: The efficacy of sunvozertinib was superior to that of chemotherapy as first-line treatment for advanced NSCLC with EGFR exon 20 insertions. (Funded by Dizal Pharmaceuticals; WU-KONG28 ClinicalTrials.gov number, NCT05668988.).\n\nIndexed on Europe PMC as PubMed record 42212913 (DOI 10.1056/nejmoa2604461). Its abstract cites the registry id NCT05668988, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2604461", pmid: "42212913", authors: "Zhou C, Greillier L, Liu G, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05668988 with the most citations, so it is the natural first reading for anyone following the WU-KONG28 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2604461"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42212913/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42212913"},{"label":"ClinicalTrials.gov NCT05668988","url":"https://clinicaltrials.gov/study/NCT05668988"}], tags: ["europepmc-ingest"], trials: ["nct05668988"], journals: ["nejm"] }),
  p({ id: "paper-nct05671510-nat-med-2026", name: "Gotistobart or docetaxel in metastatic squamous non-small cell lung cancer: stage 1 of the randomized phase 3 PRESERVE-003 trial", tldr: "Published report from the PD-L1 Inhibitors trial registered as NCT05671510, in Nature Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "PRESERVE-003 is a two-stage phase 3 trial evaluating gotistobart (BNT316/ONC-392), a novel pH-sensitive anti-cytotoxic T lymphocyte-associated protein 4 (CTLA-4) antibody that selectively depletes regulatory T cells within the tumor microenvironment, in patients with metastatic squamous non-small cell lung cancer (sqNSCLC) without actionable genomic alterations who progressed on programmed cell death protein/programmed death ligand 1 inhibitor/platinum-based chemotherapy-a population with a poor prognosis. Here we report on stage 1, which aimed to confirm the dose and assess the preliminary efficacy (primary outcome: overall survival; secondary outcomes: progression‑free survival, objective response rate and duration of response) and safety of gotistobart compared to docetaxel. Patients with sqNSCLC were randomized (1:1) to gotistobart (6 mg kg -1 with two 10 mg kg -1 loading doses every 3 weeks (N = 45)) or docetaxel (75 mg m - 2 every 3 weeks (N = 42)). After a median follow-up of 14.5 months, median overall survival was not reached with gotistobart (95% confidence interval (CI) 9.3 to not evaluable) versus 10.0 months (95% CI 6.2 to 11.9 months) with docetaxel (hazard ratio 0.46, 95% CI 0.25 to 0.84, nominal two-sided P = 0.0102). Safety was manageable, with grade ≥3 treatment-related adverse events in 42% and 49% of patients receiving gotistobart and docetaxel, respectively. Stage 1 results suggest that gotistobart monotherapy can provide clinically meaningful benefit for patients with programmed cell death protein/programmed death ligand 1-resistant and chemotherapy-resistant metastatic sqNSCLC. ClinicalTrials.gov identifier: NCT05671510.\n\nIndexed on Europe PMC as PubMed record 41896648 (DOI 10.1038/s41591-026-04323-8). Its abstract cites the registry id NCT05671510, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2026, doi: "10.1038/s41591-026-04323-8", pmid: "41896648", authors: "Cho BC, Balaraman R, Chen HJ, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05671510 with the most citations, so it is the natural first reading for anyone following the PD-L1 Inhibitors trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2026","url":"https://doi.org/10.1038/s41591-026-04323-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41896648/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41896648"},{"label":"ClinicalTrials.gov NCT05671510","url":"https://clinicaltrials.gov/study/NCT05671510"}], tags: ["europepmc-ingest"], trials: ["nct05671510"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05712902-lancet-respir-med-2024", name: "Sunvozertinib for patients in China with platinum-pretreated locally advanced or metastatic non-small-cell lung cancer and EGFR exon 20 insertion mutation (WU-KONG6): single-arm, open-label, multicentre, phase 2 trial", tldr: "Published report from the WU-KONG6 trial registered as NCT05712902, in The Lancet. Respiratory medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sunvozertinib is an oral, irreversible, and selective tyrosine kinase inhibitor that has a favourable safety profile and encouraging antitumour activity, as shown in phase 1 studies of patients with heavily pretreated non-small cell lung cancer (NSCLC) with EGFR exon 20 insertion mutation (exon20ins). We aimed to assess the antitumour efficacy of sunvozertinib in patients with platinum-pretreated locally advanced or metastatic NSCLC with EGFR exon20ins.\n\nMethods: WU-KONG6 is a single-group, open-label, multicentre phase 2 trial of sunvozertinib monotherapy, conducted across 37 medical centres in China. We enrolled adult patients with pathologically or cytologically confirmed locally advanced or metastatic NSCLC whose tumour tissue carried an EGFR exon20ins mutation. All patients had received at least one line of previous systemic therapy, with at least one line containing platinum-based chemotherapy. The primary endpoint was objective response rate (ORR), as assessed by the independent review committee. The ORR was defined as the percentage of patients who achieved complete or partial response, confirmed by two separate assessments with at least 4-week time interval, until disease progression or initiation of any new anti-cancer therapy. Enrolled patients received sunvozertinib 300 mg once daily until meeting discontinuation criteria per the protocol. Patients who received at least one dose of treatment and were evaluable for efficacy analysis were included in the primary analysis, and all patients who received at least one dose of treatment were included in the safety analysis. This study is registered with ChinaDrugTrials.org, CTR20211009, and ClinicalTrials.gov, NCT05712902, and efficacy and safety follow-up are ongoing.\n\nFindings: Between July 19, 2021, and May 6, 2022, 104 patients were enrolled. At data cutoff (Oct 17, 2022), the last enrolled patient had been followed up for about 6 months. Among 97 patients evaluable for efficacy analysis, 59 (61%) patients achieved tumour response, with a confirmed ORR of 61% (95% CI 50-71). All tumour responses were partial responses. Tumour responses were observed irrespective of age, sex, smoking history, EGFR exon20ins subtypes, brain metastasis at baseline, previous lines of therapy, and history of onco-immunotherapy. In total, 19 death events occurred over a median follow-up period of 7·6 months (IQR 6·1-9·4). Sunvozertinib was well tolerated at 300 mg once daily. The most common grade 3 or worse treatment-related adverse events were blood creatine phosphokinase increased (18 [17%] of 104), diarrhoea (eight [8%]), and anaemia (six [6%]). The most common serious treatment-related adverse events were interstitial lung disease (five [5%] of 104), anaemia (three [3%]), vomiting (two [2%]), nausea (two [2%]) and pneumonia (two [2%]).\n\nInterpretation: In this phase 2 study, sunvozertinib demonstrated antitumour efficacy in patients with platinum-based chemotherapy pretreated NSCLC with EGFR exon20ins, with a manageable safety profile. A multinational randomised, phase 3 study of sunvozertinib versus platinum-doublet chemotherapy in EGFR exon20ins NSCLC is ongoing (NCT05668988).\n\nFunding: Dizal Pharmaceutical.\n\nIndexed on Europe PMC as PubMed record 38101437 (DOI 10.1016/s2213-2600(23)00379-x). Its abstract cites the registry id NCT05712902, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2024, doi: "10.1016/s2213-2600(23)00379-x", pmid: "38101437", authors: "Wang M, Fan Y, Sun M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05712902 with the most citations, so it is the natural first reading for anyone following the WU-KONG6 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","The abstract cites more than one registry id (NCT05712902, NCT05668988); it was kept because the trial's acronym appears in the title."], links: [{"label":"Lancet Respir Med 2024","url":"https://doi.org/10.1016/s2213-2600(23)00379-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38101437/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38101437"},{"label":"ClinicalTrials.gov NCT05712902","url":"https://clinicaltrials.gov/study/NCT05712902"}], tags: ["europepmc-ingest"], trials: ["nct05712902"] }),
  p({ id: "paper-nct05722015-ann-oncol-2025", name: "Subcutaneous versus intravenous pembrolizumab, in combination with chemotherapy, for treatment of metastatic non-small-cell lung cancer: the phase III 3475A-D77 trial", tldr: "Published report from the trial registered as NCT05722015, in Annals of Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Pembrolizumab with berahyaluronidase alfa is for subcutaneous (s.c.) administration. The phase III open-label 3475A-D77 study (NCT05722015) assessed s.c. pembrolizumab versus intravenous (i.v.) pembrolizumab, plus chemotherapy, for treatment of metastatic non-small-cell lung cancer (mNSCLC).\n\nPatients and methods: Participants with newly diagnosed stage IV squamous or nonsquamous NSCLC without sensitizing EGFR, ALK, or ROS1 alterations were randomized 2: 1 to pembrolizumab s.c. 790 mg every 6 weeks (q6w) or pembrolizumab i.v. 400 mg q6w (18 cycles), each given with platinum-doublet chemotherapy. Dual primary endpoints were pharmacokinetic exposure measures of cycle 1 area under the curve (AUC 0-6 weeks) and steady-state trough concentration (C trough) of pembrolizumab. The noninferiority margin for AUC 0-6 weeks and C trough geometric mean ratios (GMRs) of pembrolizumab s.c. versus i.v. was specified as 0.8. Secondary endpoints included additional pharmacokinetic exposure measures, pembrolizumab immunogenicity, efficacy, and safety.\n\nResults: In total 377 participants were randomized to the pembrolizumab s.c. (n = 251) or i.v. (n = 126) arms. The median time from randomization to data cut-off (12 July 2024) was 9.6 months (range 6.2-16.4 months). The median injection time for pembrolizumab s.c. was 2.0 min (range 1-12 min). The GMR [96% confidence interval (CI)] for cycle 1 AUC 0-6 weeks was 1.14 (1.06-1.22); P < 0.0001. The GMR (94% CI) for steady-state C trough was 1.67 (1.52-1.84); P < 0.0001. Secondary pharmacokinetic endpoints were within established bounds for pembrolizumab. Anti-pembrolizumab antibodies were detected in 1.4% (pembrolizumab s.c. arm) and 0.9% (pembrolizumab i.v. arm) of participants. For the pembrolizumab s.c. versus i.v. arms, objective response rates (ORRs) were 45.4% versus 42.1% (ORR ratio 1.08, 95% CI 0.85-1.37). Other efficacy measures were similar and safety profiles were consistent between treatment arms.\n\nConclusions: Overall exposure and trough concentrations of pembrolizumab s.c. 790 mg q6w were noninferior to those of pembrolizumab i.v. 400 mg q6w given with chemotherapy in participants with treatment-naive mNSCLC. Results support pembrolizumab s.c. as a treatment option in all indications where pembrolizumab i.v. can be used.\n\nIndexed on Europe PMC as PubMed record 40157574 (DOI 10.1016/j.annonc.2025.03.012). Its abstract cites the registry id NCT05722015, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2025, doi: "10.1016/j.annonc.2025.03.012", pmid: "40157574", authors: "Felip E, Rojas CI, Schenker M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05722015 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2025","url":"https://doi.org/10.1016/j.annonc.2025.03.012"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40157574/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40157574"},{"label":"ClinicalTrials.gov NCT05722015","url":"https://clinicaltrials.gov/study/NCT05722015"}], tags: ["europepmc-ingest"], trials: ["nct05722015"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct05840016-lancet-2025", name: "Ivonescimab plus chemotherapy versus tislelizumab plus chemotherapy as first-line treatment for advanced squamous non-small-cell lung cancer (HARMONi-6): a randomised, double-blind, phase 3 trial", tldr: "Published report from the trial registered as NCT05840016, in The Lancet (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Squamous non-small-cell lung cancer (NSCLC) is associated with worse clinical outcomes than non-squamous NSCLC, but treatment options are scarce. We aimed to evaluate the efficacy and safety of ivonescimab plus chemotherapy versus tislelizumab plus chemotherapy as a first-line therapy for patients with advanced squamous NSCLC.\n\nMethods: We conducted a randomised, double-blind, phase 3 trial at 50 sites across China (HARMONi-6). Patients aged 18-75 years with previously untreated, pathologically confirmed, unresectable stage IIIB, IIIC, or stage IV squamous NSCLC and an Eastern Cooperative Oncology Group performance status score of 0 or 1 were eligible for inclusion. Patients were randomly assigned (1:1) to receive intravenous ivonescimab (20 mg/kg) or tislelizumab (200 mg), plus intravenous paclitaxel (175 mg/m 2) and carboplatin (area under the curve 5 mg/mL per min) once every 3 weeks for four cycles, followed by ivonescimab (20 mg/kg) or tislelizumab (200 mg) monotherapy as maintenance treatment for up to 24 months. Randomisation was stratified by disease stage (IIIB or IIIC vs IV) and PD-L1 tumour proportion score (≥1% vs <1%). The primary endpoint was progression-free survival assessed by the independent radiographic review committee as per Response Evaluation Criteria in Solid Tumours guidelines (version 1.1) in all randomly assigned patients. Safety, defined as adverse events and serious adverse events related to treatment, as well as adverse events related to immunity or VEGF blockade, were analysed in all randomly assigned patients who received at least one dose of the assigned study treatment. This study is registered at ClinicalTrial.gov (NCT05840016), has completed enrolment, and is ongoing for treatment and follow-up.\n\nFindings: From Aug 17, 2023, to Jan 21, 2025, 761 patients were screened for eligibility, among whom 532 (70%) patients were enrolled and randomly assigned to receive ivonescimab plus chemotherapy (266 [50%] patients) or tislelizumab plus chemotherapy (266 [50%] patients). at Feb 28, 2025, median follow-up time was 10·3 months (95% CI 9·5-11·0). Median progression-free survival was 11·1 months (95% CI 9·9-not evaluable) in the ivonescimab group and 6·9 months (5·8-8·6) in the tislelizumab group (hazard ratio 0·60 [95% CI 0·46-0·78]; one-sided p<0·0001). The progression-free survival benefit with ivonescimab plus chemotherapy was consistent regardless of PD-L1 status. 170 (64%) patients in the ivonescimab group and 144 (54%) patients in the tislelizumab group had grade 3 or higher treatment-related adverse events, with grade 3 or higher immune-related adverse events occurring in 24 (9%) patients in the ivonescimab group and in 27 (10%) patients in the tislelizumab group. Grade 3 or higher treatment-related haemorrhage occurred in five (2%) patients in the ivonescimab group and in two (1%) patients in the tislelizumab group.\n\nInterpretation: In patients with untreated advanced squamous NSCLC, ivonescimab plus chemotherapy showed significantly improved progression-free survival compared with tislelizumab plus chemotherapy, regardless of PD-L1 status, as well as a manageable safety profile. This regimen could be used as a novel first-line treatment in this patient group.\n\nFunding: Akeso Biopharma.\n\nIndexed on Europe PMC as PubMed record 41125109 (DOI 10.1016/s0140-6736(25)01848-3). Its abstract cites the registry id NCT05840016, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2025, doi: "10.1016/s0140-6736(25)01848-3", pmid: "41125109", authors: "Chen Z, Yang F, Jiang Z, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05840016 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2025","url":"https://doi.org/10.1016/s0140-6736(25)01848-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41125109/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41125109"},{"label":"ClinicalTrials.gov NCT05840016","url":"https://clinicaltrials.gov/study/NCT05840016"}], tags: ["europepmc-ingest"], trials: ["nct05840016"], journals: ["lancet"] }),
  p({ id: "paper-nct05840016-lancet-2026-update", name: "Ivonescimab plus chemotherapy versus tislelizumab plus chemotherapy in advanced squamous non-small-cell lung cancer (HARMONi-6): interim overall survival analysis of a randomised, double-blind, phase 3 trial in China", tldr: "Later report from the trial registered as NCT05840016, in The Lancet (2026); its title describes an updated or longer-term analysis.", summary: "Background: Bispecific antibodies targeting programmed death 1 (PD-1) and vascular endothelial growth factor (PD1-VEGF) have shown promising efficacy in non-small-cell lung cancer (NSCLC). In our previous report of the HARMONi-6 study, we aimed to evaluate the efficacy and safety of ivonescimab plus chemotherapy versus tislelizumab plus chemotherapy as a first-line therapy for patients with advanced squamous NSCLC. Ivonescimab combined with chemotherapy significantly prolonged progression-free survival compared with tislelizumab plus chemotherapy. Here we report the prespecified interim overall survival analysis.\n\nMethods: HARMONi-6 is a double-blind, randomised, phase 3 trial, which was conducted at 50 hospitals across China. Patients aged 18-75 years with previously untreated, pathologically confirmed, unresectable stage IIIB, IIIC, or stage IV squamous NSCLC and an Eastern Cooperative Oncology Group performance status score of 0 or 1 were eligible for inclusion. Eligible patients were randomly assigned in a 1:1 ratio to receive ivonescimab or tislelizumab, in combination with paclitaxel and carboplatin for four cycles, followed by maintenance ivonescimab or tislelizumab monotherapy. The primary endpoint was progression-free survival assessed by the independent radiographic review committee as per Response Evaluation Criteria in Solid Tumours guidelines (version 1.1) in all randomly assigned patients. Overall survival was a key secondary endpoint; an interim analysis was planned when approximately 225 overall survival events were observed, but it was triggered after 204 overall survival events to meet regulatory deadlines. Safety, defined as adverse events and serious adverse events related to treatment, as well as adverse events related to immunity or VEGF blockade, were analysed in all randomly assigned patients who received at least one dose of the assigned study treatment. This study is registered at ClinicalTrials.gov (NCT05840016), has completed enrolment, and is ongoing for treatment and follow-up.\n\nFindings: From Aug 17, 2023, to Jan 21, 2025, 761 patients were assessed for eligibility, and after 229 exclusions a total of 532 patients were randomly allocated (266 per group). 494 (93%) of patients were male and 38 (7%) of patients were female. The median age was 64 years (IQR 59-69). At data cutoff (Feb 27, 2026), 204 deaths had occurred: 84 (32%) patients in the ivonescimab plus chemotherapy group and 120 (45%) in the tislelizumab plus chemotherapy group. With a median follow-up of 21·4 months (95% CI 20·27-21·91), the median overall survival was 27·9 months (95% CI 27·89-not evaluable [NE]) with ivonescimab versus 23·7 months (20·11-NE) with tislelizumab (hazard ratio for death 0·66 [95% CI 0·50-0·87]; p one-sided =0·0017), meeting the prespecified boundary (p<0·0049). The overall survival benefit with ivonescimab plus chemotherapy was consistent across key subgroups. Treatment-related adverse events of grade 3 or higher occurred in 184 (69%) of 266 patients in the ivonescimab group and 156 (59%) of 265 patients in the tislelizumab group. The incidence of grade 3 or higher haemorrhage was seven (3%) of 266 and two (1%) of 265, respectively.\n\nInterpretation: Ivonescimab plus chemotherapy demonstrated a statistically significant and clinically meaningful improvement in overall survival compared with tislelizumab plus chemotherapy in previously untreated patients with advanced squamous NSCLC. This regimen could provide a novel treatment option as first-line treatment in this patient group.\n\nFunding: Akeso Biopharma.\n\nIndexed on Europe PMC as PubMed record 42218899 (DOI 10.1016/s0140-6736(26)00966-9). Its abstract cites the registry id NCT05840016, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2026, doi: "10.1016/s0140-6736(26)00966-9", pmid: "42218899", authors: "Lu S, Liu B, Luo Y, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet 2026","url":"https://doi.org/10.1016/s0140-6736(26)00966-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42218899/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42218899"},{"label":"ClinicalTrials.gov NCT05840016","url":"https://clinicaltrials.gov/study/NCT05840016"}], tags: ["europepmc-ingest"], trials: ["nct05840016"], journals: ["lancet"] }),
  p({ id: "paper-nct05870319-n-engl-j-med-2026", name: "Sacituzumab Tirumotecan in EGFR-TKI-Resistant, EGFR -Mutated Advanced NSCLC", tldr: "Published report from the trial registered as NCT05870319, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sacituzumab tirumotecan (sac-TMT) is an antibody-drug conjugate targeting trophoblast cell-surface antigen 2 that has shown significant survival benefits in patients with EGFR -mutated non-small-cell lung cancer (NSCLC) that has progressed after epidermal growth factor receptor (EGFR) tyrosine kinase inhibitor (TKI) therapy and platinum-based chemotherapy.\n\nMethods: In this phase 3 trial, we enrolled patients with EGFR -mutated locally advanced or metastatic nonsquamous NSCLC that had progressed after EGFR-TKI therapy. The patients were randomly assigned, in a 1:1 ratio, to receive sac-TMT monotherapy or pemetrexed plus platinum-based chemotherapy. The primary end point was progression-free survival as assessed by blinded independent review. Overall survival was a hierarchically tested key secondary end point. In the interim analysis of progression-free survival as assessed by blinded independent review, sac-TMT monotherapy met the prespecified criterion for significance (two-sided P<0.0001); we report here the prespecified final analysis of progression-free survival and the preplanned interim analysis of overall survival.\n\nResults: Overall, 376 patients underwent randomization, with 188 assigned to each group. After a median follow-up of 18.9 months, the median progression-free survival was 8.3 months in the sac-TMT group and 4.3 months in the chemotherapy group (hazard ratio for disease progression or death, 0.49; 95% confidence interval [CI], 0.39 to 0.62). Overall survival was significantly longer with sac-TMT than with chemotherapy (hazard ratio for death, 0.60; 95% CI, 0.44 to 0.82; two-sided P = 0.001); 18-month overall survival was 65.8% and 48.0%, respectively. Treatment-related adverse events of grade 3 or higher occurred in 58.0% of patients receiving sac-TMT and in 53.8% of those receiving chemotherapy, with the most common being a decreased neutrophil count (39.9% vs. 33.0%); treatment-related serious adverse events occurred in 9.0% and 17.6%, respectively.\n\nConclusions: In patients with EGFR -mutated advanced or metastatic NSCLC that had progressed after previous EGFR-TKI therapy, progression-free survival and overall survival outcomes were significantly better with sac-TMT than with platinum-based chemotherapy. (Funded by Sichuan Kelun-Biotech Biopharmaceutical; OptiTROP-Lung04 ClinicalTrials.gov number, NCT05870319.).\n\nIndexed on Europe PMC as PubMed record 41124220 (DOI 10.1056/nejmoa2512071). Its abstract cites the registry id NCT05870319, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2512071", pmid: "41124220", authors: "Fang W, Wu L, Meng X, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05870319 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2512071"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41124220/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41124220"},{"label":"ClinicalTrials.gov NCT05870319","url":"https://clinicaltrials.gov/study/NCT05870319"}], tags: ["europepmc-ingest"], trials: ["nct05870319"], journals: ["nejm"] }),
  p({ id: "paper-nct05933265-invest-new-drugs-2026", name: "A first-in-human phase 1a study of LP-184, a tumor-site activated novel alkylating agent, in patients with advanced solid tumors", tldr: "Published report from the trial registered as NCT05933265, in Investigational new drugs (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "LP-184 is a novel acylfulvene pro-drug that alkylates DNA after bioactivation by the intracellular oxidoreductase prostaglandin reductase 1 (PTGR1). In preclinical studies, potent growth inhibition has been observed against a wide variety of solid tumor models, particularly those carrying DNA damage repair deficiency. Here, we report results of the first-in-human dose escalation trial of LP-184 in advanced solid tumors. A dose escalation Bayesian optimal interval design was used with a starting dose of 0.01 mg/kg. Eligible patients with advanced refractory solid tumors were enrolled to receive LP-184 intravenously on days 1 and 8 of each 21-day cycle. Sixty-three patients were enrolled, with a median age of 62 years. Twelve dose levels (DLs) were evaluated with one dose-limiting toxicity (DLT) at DL11 (0.49 mg/kg; grade 4 platelet count decreased) and two DLTs at DL12 (0.61 mg/kg; grade 3 alanine aminotransferase increased and acute liver injury). The most common (≥ 20%) treatment-related adverse events of any grade included nausea, vomiting, fatigue, and platelet count decreased. No treatment-related deaths occurred during the study. Best response to monotherapy LP-184 was stable disease (SD), which was observed in 22 (40%) of the evaluable patients. Three patients experienced SD that lasted more than 12 months. LP-184 was safe and tolerable in the Phase 1a trial in patients with advanced refractory solid tumors. The maximum tolerated dose (MTD) of LP-184 is 0.49 mg/kg. Registry: ClinicalTrials.gov, TRN: NCT05933265, Registration date: June 23, 2023.\n\nIndexed on Europe PMC as PubMed record 42410111 (DOI 10.1007/s10637-026-01626-y). Its abstract cites the registry id NCT05933265, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Investigational new drugs", year: 2026, doi: "10.1007/s10637-026-01626-y", pmid: "42410111", authors: "Mahadevan D, Parekh J, Beck JT, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05933265 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Invest New Drugs 2026","url":"https://doi.org/10.1007/s10637-026-01626-y"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42410111/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42410111"},{"label":"ClinicalTrials.gov NCT05933265","url":"https://clinicaltrials.gov/study/NCT05933265"}], tags: ["europepmc-ingest"], trials: ["nct05933265"] }),
  p({ id: "paper-nct05955391-j-thorac-oncol-2026", name: "Deulorlatinib (TGRX-326) in ALK Gene Fusion Positive NSCLC After Failure of Second-Generation Inhibitors: A Single-Arm, Multicenter, Phase 2 Trial", tldr: "Published report from the trial registered as NCT05955391, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Deulorlatinib (TGRX-326), a potent third-generation anaplastic lymphoma kinase (ALK) inhibitor, has reported promising activity and a favorable safety profile in ALK-positive NSCLC in a phase 1 trial. Here, we report the primary results of the pivotal phase 2 trial (NCT05955391) evaluating deulorlatinib in patients with ALK-positive NSCLC in whom second-generation ALK inhibitors had failed.\n\nMethods: This single-arm, phase 2 trial was conducted at 36 centers in China. Eligible patients received deulorlatinib 60 mg once daily. The primary end point was objective response rate (ORR) assessed by an independent review committee (IRC). Key secondary end points included disease control rate, progression-free survival (PFS), duration of response, overall survival, intracranial efficacy, and safety. Exploratory biomarker analyses were performed using cell-free DNA.\n\nResults: The efficacy and safety analysis sets comprised 158 and 163 patients, respectively. The primary end point was met with an IRC-assessed ORR of 43.7% (95% confidence interval [CI], 35.8-51.8). The IRC-assessed median PFS was 11.1 months (95% CI, 8.3-13.7). Among patients with measurable central nervous system (CNS) metastases (n = 43), the intracranial ORR was 55.8% (95% CI, 39.9-70.9). In patients harboring the G1202R mutation (n = 8), robust activity was observed (ORR: 62.5%; disease control rate: 100%; median PFS: 11.0 months). The investigator-assessed results were consistent with the IRC-assessed findings. Treatment-related adverse events occurred in 96.3% of patients (47.2% grade ≥3). Nevertheless, dose modifications were infrequent (interruption, 13.5%; reduction, 11.0%; permanent discontinuation, 0.6%). The incidence of CNS-related treatment-related adverse events was 12.9%, with no patients interrupting or discontinuing treatment owing to CNS toxicity.\n\nConclusions: Deulorlatinib indicated encouraging antitumor activity in patients with advanced ALK-positive NSCLC after failure of second-generation ALK inhibitors, including those with the G1202R mutation. Given its favorable safety profile, deulorlatinib represents a promising new option for this population.\n\nIndexed on Europe PMC as PubMed record 42031067 (DOI 10.1016/j.jtho.2026.103737). Its abstract cites the registry id NCT05955391, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2026.103737", pmid: "42031067", authors: "Huang J, Chen G, Wang Z, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05955391 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2026.103737"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42031067/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42031067"},{"label":"ClinicalTrials.gov NCT05955391","url":"https://clinicaltrials.gov/study/NCT05955391"}], tags: ["europepmc-ingest"], trials: ["nct05955391"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct06015503-j-thorac-oncol-2026", name: "Andamertinib in Advanced NSCLC With EGFR Exon 20 Insertions After Platinum-Based Chemotherapy or Immunotherapy: Results From the Phase 2 KANNON Study", tldr: "Published report from the KANNON trial registered as NCT06015503, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Objectives: This study aimed to evaluate andamertinib, a selective and irreversible tyrosine kinase inhibitor, in pretreated advanced EGFR exon 20 insertion (ex20ins)-mutant NSCLC.\n\nMethods: In the phase 2, multicenter, single-arm KANNON study (NCT06015503), patients with locally advanced or metastatic NSCLC harboring EGFR ex20ins mutations who had progressed after platinum-based chemotherapy or immunotherapy received oral andamertinib 240 mg once daily in 28-day cycles. The primary end point was the confirmed objective response rate (ORR) assessed by independent review.\n\nResults: A total of 92 patients were enrolled and received daily 240 mg andamertinib, with nearly 30 different exon20ins subtypes included. The confirmed ORR was 42.7% (95% confidence interval [CI], 32.4-53.0), with a disease control rate of 86.5% and a median duration of response of 8.7 months (95% CI, 5.65-11.96). at September 6, 2025, with a median follow-up of 15.4 (range, 0.4-20.5) months, the median progression-free survival was 6.2 months (95% CI, 4.63-7.85) and median overall survival was not reached (95% CI, 13.93 mo to not estimable), with a 12-month survival rate of 70.5%. Among 38 patients with brain metastasis, the systemic confirmed ORR was 47.4% (95% CI, 31.5-63.2). Grade more than or equal to 3 treatment-related adverse events occurred in 40.2% of patients, and the most frequent events were diarrhea (12.0%) and rash (7.6%). No interstitial lung disease or grade more than or equal to 3 QT prolongation was reported.\n\nConclusions: Andamertinib at 240 mg once daily demonstrated efficacy with a manageable safety profile in previously treated patients with EGFR ex20ins-mutant NSCLC.\n\nIndexed on Europe PMC as PubMed record 41248848 (DOI 10.1016/j.jtho.2025.11.008). Its abstract cites the registry id NCT06015503, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2025.11.008", pmid: "41248848", authors: "Yang JJ, Mu Y, Wang ZH, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06015503 with the most citations, so it is the natural first reading for anyone following the KANNON trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2025.11.008"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41248848/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41248848"},{"label":"ClinicalTrials.gov NCT06015503","url":"https://clinicaltrials.gov/study/NCT06015503"}], tags: ["europepmc-ingest"], trials: ["nct06015503"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct06099782-jco-oncol-pract-2026", name: "Participant-Reported Preference for Pembrolizumab Administered Subcutaneously or Intravenously: A Randomized, Open-Label, Phase II Study", tldr: "Published report from the trial registered as NCT06099782, in JCO Oncology Practice (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Pembrolizumab with berahyaluronidase alfa, a human hyaluronidase variant, is for subcutaneous (SC) injection. The phase II, open-label, crossover study 3475A-F11 (ClinicalTrials.gov identifier: NCT06099782) assessed participant preference for SC or intravenous (IV) pembrolizumab.\n\nMethods: Participants with resected melanoma, resected renal cell carcinoma, or metastatic non-small cell lung cancer (PD-L1 tumor proportion score ≥50%) were randomly assigned 1:1 to pembrolizumab SC 395 mg (arm A) or pembrolizumab IV 200 mg (arm B) once every 3 weeks for three cycles before crossover to the other administration route for three cycles. The primary objective was participant preference for SC pembrolizumab as assessed by the Patient Preference Questionnaire. Secondary objectives included reasons for participant preference, participant satisfaction with administration route, participant choice of treatment (SC or IV) to continue after cycle 6, and safety and tolerability.\n\nResults: Overall, 147 participants were randomly assigned (arm A = 71, arm B = 76). The participant preference rate for pembrolizumab SC was 65% (95% CI, 56 to 74). The most common reason for this preference was less time in clinic (64%). Altogether, 64%/25% of participants were very satisfied/satisfied with pembrolizumab SC; 54%/31% were very satisfied/satisfied with pembrolizumab IV. More participants chose to continue treatment after cycle 6 with pembrolizumab SC than pembrolizumab IV (68% v 32%). Grade 3-4 treatment-related adverse events (AEs) in cycles 1-3 occurred in one (1%; arm A) and five (7%; arm B) participants. Injection-site AEs during SC administration cycles of the crossover period occurred in nine (13%; arm A) and 11 (16%; arm B) participants (mostly grade 1).\n\nConclusion: More participants preferred pembrolizumab SC over pembrolizumab IV and chose to continue with pembrolizumab SC. The results of this study suggest that pembrolizumab SC improves convenience compared with pembrolizumab IV in cancer treatment.\n\nIndexed on Europe PMC as PubMed record 42234938 (DOI 10.1200/op-25-01248). Its abstract cites the registry id NCT06099782, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JCO Oncology Practice", year: 2026, doi: "10.1200/op-25-01248", pmid: "42234938", authors: "Casarini IA, Kowalski DM, Caglevic C, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06099782 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JCO Oncol Pract 2026","url":"https://doi.org/10.1200/op-25-01248"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42234938/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42234938"},{"label":"ClinicalTrials.gov NCT06099782","url":"https://clinicaltrials.gov/study/NCT06099782"}], tags: ["europepmc-ingest"], trials: ["nct06099782"], journals: ["jco-oncology-practice"] }),
  p({ id: "paper-nct06120140-j-thorac-oncol-2025", name: "Enhanced Versus Standard Dermatologic Management With Amivantamab-Lazertinib in EGFR-Mutated Advanced NSCLC: The COCOON Global Randomized Controlled Trial", tldr: "Published report from the COCOON trial registered as NCT06120140, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Amivantamab plus lazertinib significantly improved progression-free and overall survival versus osimertinib in patients with previously untreated, EGFR-mutant advanced NSCLC. EGFR-targeted therapies are associated with dermatologic adverse events (AEs), which can affect quality of life (QoL). COCOON was conducted to assess prophylactic management and improve treatment experience.\n\nMethods: In the phase 2 COCOON study (NCT06120140), participants with previously untreated, EGFR-mutant, locally advanced or metastatic NSCLC received intravenous amivantamab plus oral lazertinib and were randomized 1:1 to enhanced dermatologic management (COCOON DM) or standard of care (SoC DM) per local guidelines. COCOON DM included oral doxycycline or minocycline (100 mg twice daily; weeks 1-12), clindamycin 1% (on scalp daily; weeks 13-52), chlorhexidine 4% (on fingernails and toenails daily), and ceramide-based moisturizer (on body and face at least daily). Primary end point was incidence of grade 2 or higher dermatologic AEs of interest (DAEIs) by week 12.\n\nResults: In total, 201 participants were randomized (99 to COCOON DM and 102 to SoC DM). At a median follow-up of 7.1 months, COCOON DM demonstrated significant reduction in the primary end point versus SoC DM (42% versus 75%; OR, 0.24; 95% confidence interval, 0.13-0.45; p < 0.0001). By week 12, the largest benefit with COCOON DM was observed in DAEIs involving the face and body (excludes paronychia; 26% versus 60%; p < 0.0001) and DAEIs involving the scalp (10% versus 26%; p = 0.0049). This benefit was maintained at 6 months, with significant reductions of DAEIs involving face, body, and scalp (excluding paronychia). Patient-reported outcomes favored COCOON DM, indicating reduced impact of dermatologic symptoms on QoL.\n\nConclusion: An uncomplicated, widely available, prophylactic regimen (COCOON DM) reduced the incidence of DAEIs with amivantamab-lazertinib and the impact of symptoms on QoL.\n\nIndexed on Europe PMC as PubMed record 40923969 (DOI 10.1016/j.jtho.2025.07.117). Its abstract cites the registry id NCT06120140, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2025.07.117", pmid: "40923969", authors: "Cho BC, Li W, Spira AI, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06120140 with the most citations, so it is the natural first reading for anyone following the COCOON trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2025.07.117"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40923969/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40923969"},{"label":"ClinicalTrials.gov NCT06120140","url":"https://clinicaltrials.gov/study/NCT06120140"}], tags: ["europepmc-ingest"], trials: ["nct06120140"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct06396065-lancet-oncol-2026", name: "Ivonescimab plus chemotherapy versus placebo plus chemotherapy in patients with advanced EGFR-mutated non-small-cell lung cancer after disease progression on EGFR tyrosine kinase inhibitor therapy (HARMONi): a multicentre, randomised, double-blind, phase 3 trial", tldr: "Published report from the trial registered as NCT06396065, in The Lancet Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Ivonescimab has shown clinical efficacy in non-small-cell lung cancer (NSCLC). We aimed to assess the efficacy and safety of ivonescimab plus chemotherapy versus placebo plus chemotherapy in patients with advanced EGFR-mutated NSCLC whose disease progressed after third-generation EGFR tyrosine kinase inhibitor (TKI) therapy.\n\nMethods: HARMONi is a randomised, placebo-controlled, double-blind, phase 3 trial done at 114 cancer centres and hospitals across Asia, Europe, and North America. Eligible patients were aged at least 18 years (upper limit: 75 years in Asia) with stage IIIB/IIIC or IV non-squamous EGFR-mutated NSCLC, disease progression after treatment with a third-generation EGFR-TKI, and an Eastern Cooperative Oncology Group performance status score of 0 or 1. Patients were randomly assigned (1:1) via a centralised interactive voice response system or interactive web response system to receive ivonescimab (20 mg/kg) or placebo plus pemetrexed (500 mg/m 2) and carboplatin (target area under the curve 5 mg/mL per min) intravenously every 3 weeks. Randomisation was stratified by brain metastases status at enrolment and geographical region. The primary endpoints were progression-free survival by blinded independent radiology review committee and overall survival in the intention-to-treat population. Safety was assessed in patients who received at least one dose of trial treatment. This study is registered with ClinicalTrials.gov (NCT06396065), has completed enrolment, and is ongoing for treatment and follow-up.\n\nFindings: From Jan 25, 2022, to Oct 1, 2024, 660 individuals were screened for eligibility; of these, 438 were enrolled and randomly assigned to receive ivonescimab plus chemotherapy or placebo plus chemotherapy (219 per group). Of enrolled patients, 257 (59%) were female and 181 (41%) were male; 306 (70%) reported race as Asian, and 105 (24%) as White. At a median follow-up of 22·3 months (95% CI 21·5-23·0), 275 progression or death events had occurred in 345 patients (129 events among 172 patients in the ivonescimab plus chemotherapy group and 146 events among 173 patients in the placebo plus chemotherapy group). Median progression-free survival was 6·8 months (95% CI 5·7-7·1) in the ivonescimab plus chemotherapy group versus 4·4 months (4·1-5·5) in the placebo plus chemotherapy group (hazard ratio [HR] 0·52; 95% CI 0·41-0·66; p<0·0001). At a median follow-up of 29·7 months (95% CI 27·7-31·0), 262 deaths occurred in 438 patients (122 in the ivonescimab plus chemotherapy group and 140 in the placebo plus chemotherapy group). Median overall survival was 16·8 months (14·3-19·0) in the ivonescimab plus chemotherapy group versus 14·0 months (12·8-15·7) in the placebo plus chemotherapy group (HR 0·79; 0·62-1·01). The most common grade 3-4 treatment-related adverse events in the ivonescimab plus chemotherapy versus the placebo plus chemotherapy group were decreased neutrophil count (42 [19%] of 218 vs 36 [17%] of 218), decreased white blood cell count (28 [13%] vs 24 [11%]), decreased platelet count (27 [12%] vs 14 [6%]), and anaemia (22 [10%] vs 27 [12%]). Serious treatment-related adverse events occurred in 61 (28%) patients in the ivonescimab plus chemotherapy group and 33 (15%) patients in the placebo plus chemotherapy group. Treatment-related adverse events led to death in four patients (disease progression, multiple organ dysfunction syndrome, and hepatic failure, each in one patient; gastrointestinal haemorrhage and pulmonary embolism in one patient) in the ivonescimab plus chemotherapy group and five patients (pneumonitis, myocardial infarction, cerebrovascular accident, cognitive disorder, and embolic stroke, each in one patient) in the placebo plus chemotherapy group.\n\nInterpretation: Ivonescimab plus chemotherapy showed a clinically meaningful and statistically significant progression-free survival benefit in patients with EGFR-mutated NSCLC after progression on EGFR-TKI therapy. The clinical benefit and lack of new safety signals of ivonescimab with chemotherapy support the potential for the combination as a new treatment option in this patient population.\n\nFunding: Summit Therapeutics.\n\nIndexed on Europe PMC as PubMed record 42636833 (DOI 10.1016/s1470-2045(26)00282-2). Its abstract cites the registry id NCT06396065, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2026, doi: "10.1016/s1470-2045(26)00282-2", pmid: "42636833", authors: "Le X, Passaro A, Zhao Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06396065 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2026","url":"https://doi.org/10.1016/s1470-2045(26)00282-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42636833/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42636833"},{"label":"ClinicalTrials.gov NCT06396065","url":"https://clinicaltrials.gov/study/NCT06396065"}], tags: ["europepmc-ingest"], trials: ["nct06396065"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct06448312-lancet-2026", name: "Sacituzumab tirumotecan plus pembrolizumab versus pembrolizumab in PD-L1-positive advanced non-small-cell lung cancer (OptiTROP-Lung05): interim analysis of a randomised, open-label, phase 3 trial", tldr: "Published report from the trial registered as NCT06448312, in The Lancet (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sacituzumab tirumotecan (sac-TMT), a trophoblast cell-surface antigen 2-targeting antibody-drug conjugate, combined with programmed death 1 (PD-1) or programmed death ligand 1 (PD-L1) inhibitors, has shown promising antitumour activity as first-line therapy for non-small-cell lung cancer (NSCLC) in early-phase studies. Our aim was to evaluate the efficacy and safety of sac-TMT plus pembrolizumab as first-line treatment for patients with PD-L1-positive advanced NSCLC without targetable genomic alterations.\n\nMethods: In this randomised, open-label, phase 3 trial (OptiTROP-Lung05) conducted across 68 hospitals in China, eligible patients had locally advanced or metastatic NSCLC without targetable genomic alterations and a PD-L1 tumour proportion score (TPS) of 1% or greater. Patients were randomly assigned (1:1) to receive sac-TMT (4 mg/kg on days 1, 15, and 29) plus pembrolizumab (400 mg fixed dose on day 1), or pembrolizumab alone, administered intravenously every 6 weeks. The primary endpoint was progression-free survival, as assessed by blinded independent central review in the intention-to-treat population. This trial was registered with ClinicalTrials.gov (NCT06448312). Recruitment is complete, with the trial ongoing and the final analysis to be reported later.\n\nFindings: Between June 7, 2024, and March 27, 2025, 741 patients were screened and 413 eligible patients were randomly assigned to receive sac-TMT plus pembrolizumab (n=208) or pembrolizumab alone (n=205). At the prespecified interim analysis, conducted after a median follow-up of 10·5 months (IQR 8·7-12·5), median progression-free survival was significantly longer with sac-TMT plus pembrolizumab than with pembrolizumab alone (not reached vs 5·7 months; stratified hazard ratio [HR] 0·35 [95% CI 0·26-0·47]; p<0·0001). The progression-free survival benefit was broadly consistent across subgroups, including patients with PD-L1 TPS of 1-49% (HR 0·28 [95% CI 0·19-0·41]) and those with PD-L1 TPS of 50% or greater (HR 0·47 [0·29-0·77]). Grade 3 or higher treatment-emergent adverse events occurred in 115 (55%) of 208 patients in the sac-TMT plus pembrolizumab group and 64 (31%) of 204 patients in the pembrolizumab group.\n\nInterpretation: Among patients with PD-L1-positive advanced NSCLC without targetable genomic alterations, first-line treatment with sac-TMT plus pembrolizumab significantly prolonged progression-free survival compared with pembrolizumab alone. Therefore, sac-TMT plus pembrolizumab has the potential to redefine first-line treatment for patients with PD-L1-positive advanced NSCLC without targetable genomic alterations.\n\nFunding: Sichuan Kelun-Biotech Biopharmaceutical.\n\nIndexed on Europe PMC as PubMed record 42214392 (DOI 10.1016/s0140-6736(26)00968-2). Its abstract cites the registry id NCT06448312, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2026, doi: "10.1016/s0140-6736(26)00968-2", pmid: "42214392", authors: "Xiong A, Yao W, Zheng W, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06448312 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2026","url":"https://doi.org/10.1016/s0140-6736(26)00968-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42214392/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42214392"},{"label":"ClinicalTrials.gov NCT06448312","url":"https://clinicaltrials.gov/study/NCT06448312"}], tags: ["europepmc-ingest"], trials: ["nct06448312"], journals: ["lancet"] }),
  p({ id: "paper-nct06612151-n-engl-j-med-2026", name: "Tambotatug Pelitecan in Small-Cell Lung Cancer after Platinum-Based Therapy", tldr: "Published report from the TAISHAN-302 trial registered as NCT06612151, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Tambotatug pelitecan (known as Tam-Peli, a new antibody-drug conjugate that targets the immune-checkpoint molecule B7-H3) showed promising clinical efficacy in patients with relapsed extensive-stage small-cell lung cancer in early-phase trials.\n\nMethods: In this phase 3, multicenter, open-label, randomized trial, we assigned eligible patients with small-cell lung cancer that had progressed after first-line platinum-based therapy in a 1:1 ratio to receive tambotatug pelitecan or topotecan. The primary end point was overall survival. The key secondary end points were progression-free survival and objective response as assessed by investigators. Here, we report the results from the prespecified interim analysis.\n\nResults: A total of 451 patients underwent randomization: 225 were assigned to receive tambotatug pelitecan and 226 to receive topotecan. Overall survival was significantly longer with tambotatug pelitecan than with topotecan - a median of 13.3 months (95% confidence interval [CI], 12.1 to could not be estimated), as compared with 9.4 months (95% CI, 7.7 to 10.5); the stratified hazard ratio for death was 0.46 (95% CI, 0.35 to 0.62; P<0.001). Treatment with tambotatug pelitecan also resulted in significantly longer progression-free survival than treatment with topotecan (median, 7.4 months [95% CI, 6.1 to 7.6] vs. 2.8 months [95% CI, 1.8 to 3.0]; stratified hazard ratio, 0.29 [95% CI, 0.23 to 0.37]; P<0.001). A confirmed objective response occurred in 59.1% of the patients in the tambotatug pelitecan group, as compared with 9.7% of those in the topotecan group (P<0.001). The overall incidence of adverse events of grade 3 or higher was lower with tambotatug pelitecan than with topotecan (55.4% vs. 77.9%).\n\nConclusions: Among patients with relapsed small-cell lung cancer after platinum-based therapy, treatment with tambotatug pelitecan resulted in longer overall survival, longer progression-free survival, and a higher percentage of patients with an objective response than treatment with topotecan, with a lower incidence of adverse events of grade 3 or higher. (Funded by the Innovative Drug Research and Development National Science and Technology Major Project and MediLink Therapeutics; TAISHAN-302 ClinicalTrials.gov number, NCT06612151.).\n\nIndexed on Europe PMC as PubMed record 42734213 (DOI 10.1056/nejmoa2610229). Its abstract cites the registry id NCT06612151, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2610229", pmid: "42734213", authors: "Zhao Y, Liu H, Meng X, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06612151 with the most citations, so it is the natural first reading for anyone following the TAISHAN-302 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2610229"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42734213/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42734213"},{"label":"ClinicalTrials.gov NCT06612151","url":"https://clinicaltrials.gov/study/NCT06612151"}], tags: ["europepmc-ingest"], trials: ["nct06612151"], journals: ["nejm"] }),
  p({ id: "paper-nct04270591-eclinicalmedicine-2023", name: "Gumarontinib in patients with non-small-cell lung cancer harbouring MET exon 14 skipping mutations: a multicentre, single-arm, open-label, phase 1b/2 trial", tldr: "Published report from the trial registered as NCT04270591, in EClinicalMedicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Approximately 3-4% of patients with non-small-cell lung cancer (NSCLC) have MET exon 14 ( MET ex14) skipping mutations. We report primary results from the phase 2 stage of a phase 1b/2 study of gumarontinib, a selective, potent, oral MET inhibitor, in patients with MET ex14 skipping mutation-positive ( MET ex14-positive) NSCLC.\n\nMethods: The single-arm, multicentre, open-label, phase 2 stage of the GLORY study was conducted at 42 centres across China and Japan. Adults with locally advanced or metastatic MET ex14-positive NSCLC received oral gumarontinib 300 mg once daily in continuous 21-day cycles until disease progression, intolerable toxicity, or withdrawal of consent. Eligible patients had failed one or two prior lines of therapy (not including a MET inhibitor), were ineligible for/refused chemotherapy, and had no genetic alterations targetable with standard therapies. The primary endpoint was objective response rate in patients with a valid baseline tumour assessment, by blinded independent review. The study was registered at ClinicalTrials.gov (NCT04270591).\n\nFindings: Between Aug 2, 2019 and Apr 28, 2021, 84 patients were enrolled and received gumarontinib (median follow-up 13.5 months [IQR 8.7-17.1]), at data cut-off (Apr 28, 2022) five patients whose MET ex14 status could not be confirmed by a central laboratory were excluded from the efficacy analysis. The objective response rate was 66% (95% CI 54-76) overall (n = 79), 71% (95% CI 55-83) in treatment-naïve patients (n = 44), and 60% (95% CI 42-76) in previously-treated patients (n = 35). The most common treatment-related adverse events (any grade) were oedema (67/84 patients, 80%) and hypoalbuminuria (32/84, 38%). Grade ≥3 treatment-emergent adverse events occurred in 45 (54%) patients. Treatment-related adverse events leading to permanent discontinuation occurred in 8% (7/84) of patients.\n\nInterpretation: Gumarontinib monotherapy had durable antitumour activity with manageable toxicity in patients with locally advanced or metastatic MET ex14-positive NSCLC when used in first line or later.\n\nFunding: Haihe Biopharma Co., Ltd. Supported in part by grants from the National Science and Technology Major Project of China for \"Clinical Research of Gumarontinib, a highly selective MET inhibitor\" (2018ZX09711002-011-003); the National Natural Science Foundation of China (82030045 to S.L. and 82172633 to YF.Y); Shanghai Municipal Science & Technology Commission Research Project (19411950500 to S.L.); Shanghai Shenkang Action Plan (16CR3005A to S.L.) and Shanghai Chest Hospital Project of Collaborative Innovation (YJXT20190105 to S.L.).\n\nIndexed on Europe PMC as PubMed record 37096188 (DOI 10.1016/j.eclinm.2023.101952). Its abstract cites the registry id NCT04270591, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "EClinicalMedicine", year: 2023, doi: "10.1016/j.eclinm.2023.101952", pmid: "37096188", authors: "Yu Y, Zhou J, Li X, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04270591 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"EClinicalMedicine 2023","url":"https://doi.org/10.1016/j.eclinm.2023.101952"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37096188/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37096188"},{"label":"ClinicalTrials.gov NCT04270591","url":"https://clinicaltrials.gov/study/NCT04270591"}], tags: ["europepmc-ingest"], trials: ["nct04270591"] }),
  p({ id: "paper-nct04270591-transl-lung-cancer-res-2025-update", name: "Long-term follow-up results from the GLORY study: phase II study of gumarontinib in East Asian patients with MET exon 14 skipping mutated non-small cell lung cancer", tldr: "Later report from the trial registered as NCT04270591, in Translational lung cancer research (2025); its title describes an updated or longer-term analysis.", summary: "Background: Gumarontinib has previously shown activity in patients with non-small cell lung cancer (NSCLC) harboring MET exon 14 skipping mutation ( MET ex14). We hereby report the updated results from the phase II stage of GLORY study after additional 18-month follow-up.\n\nMethods: The single-arm, multicenter, open-label, phase II of the GLORY study was conducted at 42 centers across China and Japan. Patients with locally advanced or metastatic MET ex14-positive NSCLC received gumarontinib 300 mg orally once daily until disease progression or intolerable toxicity. Eligible patients had failed one or two prior lines of therapy (not including a MET inhibitor) and had no genetic alterations targetable with standard therapies. The primary endpoint was the objective response rate (ORR) by the blinded independent review committee (BIRC) per Response Evaluation Criteria in Solid Tumors version 1.1. The study was registered at ClinicalTrials.gov (NCT04270591).\n\nResults: The phase II stage of GLORY study included 84 patients. at the data cutoff date on October 28, 2023, the ORR assessed by BIRC was 65.8% [95% confidence interval (CI): 54.3% to 76.1%], with 70.5% (95% CI: 54.8% to 83.2%) in treatment-naïve and 60.0% (95% CI: 42.1% to 76.1%) in pre-treated populations. The median duration of response (DOR) assessed by BIRC was 8.3 (95% CI: 6.2 to 18.3) months, the median progression-free survival (PFS) was 7.7 (95% CI: 7.6 to 9.7) months, and the median overall survival (OS) was 19.4 (95% CI: 12.1 to 30.1) months, with a median OS of 25.4 [95% CI: 11.7 to not evaluable (NE)] months in treatment-naïve population and 16.3 (95% CI: 8.7 to NE) months in the pre-treated population. The most common treatment-related adverse events (any grade) were oedema (67/84, 79.8%) and hypoalbuminemia (32/84, 38.1%). Grade ≥3 treatment-related adverse events occurred in 53.6% (45/84) patients. Treatment-related adverse events leading to permanent discontinuation occurred in 8.3% (7/84) of patients.\n\nConclusions: Gumarontinib showed promising efficacy and acceptable toxicities in East Asian population, with a rapid onset of action, substantial and durable response, which can be converted into a long-term survival benefit.\n\nIndexed on Europe PMC as PubMed record 41132955 (DOI 10.21037/tlcr-2025-638). Its abstract cites the registry id NCT04270591, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Translational lung cancer research", year: 2025, doi: "10.21037/tlcr-2025-638", pmid: "41132955", authors: "Lu S, Yu Y, Zhou J, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Transl Lung Cancer Res 2025","url":"https://doi.org/10.21037/tlcr-2025-638"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41132955/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41132955"},{"label":"ClinicalTrials.gov NCT04270591","url":"https://clinicaltrials.gov/study/NCT04270591"}], tags: ["europepmc-ingest"], trials: ["nct04270591"] }),
  p({ id: "paper-nct04606446-nat-med-2024", name: "Inhibition of lysine acetyltransferase KAT6 in ER + HER2 - metastatic breast cancer: a phase 1 trial", tldr: "Published report from the trial registered as NCT04606446, in Nature Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Inhibition of histone lysine acetyltransferases (KATs) KAT6A and KAT6B has shown antitumor activity in estrogen receptor-positive (ER +) breast cancer preclinical models. PF-07248144 is a selective catalytic inhibitor of KAT6A and KAT6B. In the present study, we report the safety, pharmacokinetics (PK), pharmacodynamics, efficacy and biomarker results from the first-in-human, phase 1 dose escalation and dose expansion study (n = 107) of PF-07248144 monotherapy and fulvestrant combination in heavily pretreated ER + human epidermal growth factor receptor-negative (HER2 -) metastatic breast cancer (mBC). The primary objectives of assessing the safety and tolerability and determining the recommended dose for expansion of PF-07248144, as monotherapy and in combination with fulvestrant, were met. Secondary endpoints included characterization of PK and evaluation of antitumor activity, including objective response rate (ORR) and progression-free survival (PFS). Common treatment-related adverse events (any grade; grades 3-4) included dysgeusia (83.2%, 0%), neutropenia (59.8%, 35.5%) and anemia (48.6%, 13.1%). Exposure was approximately dose proportional. Antitumor activity was observed as monotherapy. For the PF-07248144-fulvestrant combination (n = 43), the ORR (95% confidence interval (CI)) was 30.2% (95% CI = 17.2-46.1%) and the median PFS was 10.7 (5.3-not evaluable) months. PF-07248144 demonstrated a tolerable safety profile and durable antitumor activity in heavily pretreated ER + HER2 - mBC. These findings establish KAT6A and KAT6B as druggable cancer targets, provide clinical proof of concept and reveal a potential avenue to treat mBC. clinicaltrial.gov registration: NCT04606446.\n\nIndexed on Europe PMC as PubMed record 38824244 (DOI 10.1038/s41591-024-03060-0). Its abstract cites the registry id NCT04606446, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2024, doi: "10.1038/s41591-024-03060-0", pmid: "38824244", authors: "Mukohara T, Park YH, Sommerhalder D, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04606446 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2024","url":"https://doi.org/10.1038/s41591-024-03060-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38824244/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38824244"},{"label":"ClinicalTrials.gov NCT04606446","url":"https://clinicaltrials.gov/study/NCT04606446"}], tags: ["europepmc-ingest"], trials: ["nct04606446"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05061550-nat-med-2025", name: "Perioperative durvalumab plus chemotherapy plus new agents for resectable non-small-cell lung cancer: the platform phase 2 NeoCOAST-2 trial", tldr: "Published report from the NeoCOAST-2 trial registered as NCT05061550, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "In the phase II NeoCOAST-2 platform study, 202 patients with untreated, resectable stage IIA-IIIB non-small-cell lung cancer (NSCLC) were randomized to receive neoadjuvant durvalumab plus platinum-doublet chemotherapy with oleclumab, a CD73 inhibitor (Arm 1), or with monalizumab, a NKG2A inhibitor (Arm 2), or neoadjuvant durvalumab plus single-agent platinum chemotherapy with the TROP-2 antibody-drug conjugate (ADC) datopotamab deruxtecan (Arm 4), followed by surgical resection and adjuvant durvalumab with oleclumab or monalizumab (Arms 1 and 2) or durvalumab alone (Arm 4). Primary endpoints were pathological complete response (pCR) rate and safety; secondary endpoints included feasibility of surgery and major pathological response (mPR) rate. In the modified intention-to-treat population (n = 198; Arm 1, n = 74; Arm 2, n = 70; Arm 4, n = 54), pCR rates were 20.3% (15/74; 95% CI, 11.8-31.2), 25.7% (18/70; 95% CI, 16.0-37.6) and 35.2% (19/54; 95% CI, 22.7-49.4), and mPR rates were 41.9% (31/74; 95% CI, 30.5-53.9), 50.0% (35/70; 95% CI, 37.8-62.2) and 63.0% (34/54; 95% CI, 48.7-75.7) in arms 1, 2, and 4, respectively. In the safety population, 69/74 (93.2%), 66/71 (93.0%), and 51/54 (94.4%) patients underwent surgery, respectively. Overall, grade ≥3 treatment-related adverse events occurred in 27/74 (36.5%), 29/71 (40.8%) and 11/54 (20.4%) patients, respectively. In NeoCOAST-2, the first neoadjuvant trial examining an ADC plus chemo-immunotherapy in resectable NSCLC, pCR rates were highest in the datopotamab-deruxtecan-containing arm, warranting further investigation in larger trials of ADCs and checkpoint inhibition in the neoadjuvant setting. ClinicalTrials.gov identifier: NCT05061550.\n\nIndexed on Europe PMC as PubMed record 40450142 (DOI 10.1038/s41591-025-03746-z). Its abstract cites the registry id NCT05061550, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-03746-z", pmid: "40450142", authors: "Cascone T, Bonanno L, Guisier F, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05061550 with the most citations, so it is the natural first reading for anyone following the NeoCOAST-2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-03746-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40450142/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40450142"},{"label":"ClinicalTrials.gov NCT05061550","url":"https://clinicaltrials.gov/study/NCT05061550"}], tags: ["europepmc-ingest"], trials: ["nct05061550"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05168566-j-thorac-oncol-2026", name: "Sutetinib for Patients with Non-Small Cell Lung Cancer Harboring Uncommon EGFR Mutations: A Multicenter, Open-Label, Phase IIb Trial", tldr: "Published report from the trial registered as NCT05168566, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Uncommon epidermal growth factor receptor (EGFR) mutations account for ∼10% of EGFR-altered non-small cell lung cancer (NSCLC) and show heterogeneous sensitivity to EGFR-tyrosine kinase inhibitors (TKIs), with limited prospective evidence to inform first-line therapy. Sutetinib is an irreversible EGFR-TKI. We assessed the safety and antitumor efficacy of sutetinib in patients with locally advanced or metastatic NSCLC with uncommon EGFR mutations.\n\nMethods: In this multicenter, open-label, single-arm phase IIb trial, adults with locally advanced or metastatic NSCLC harboring EGFR G719X, S768I, L861Q, or predefined compound mutations and no prior EGFR-TKI therapy were enrolled. Patients received sutetinib 80 mg orally once daily in 28-day cycles until radiographic progression or unacceptable toxicity. Patients who received at least one dose of treatment and evaluable for efficacy analysis were included in the primary analysis, and all patients who received at least one dose of treatment were included in the safety analysis. The primary endpoint was objective response rate (ORR), as assessed by the independent review committee (IRC). Secondary endpoints included duration of response (DoR), disease control rate (DCR), time to response (TTR), progression-free survival (PFS), overall survival (OS), and safety.\n\nResults: From December 9, 2021, to May 5, 2024, 99 patients were enrolled (efficacy-evaluable, n=96; safety, n=99). at data cut-off in October, 2024, the median follow-up was 16.6 months. The IRC-confirmed ORR was 70.8% (95% confidence interval [CI], 60.7-79.7) and the DCR was 90.6% (95% CI, 82.9-95.6). Median DoR was 12.0 months (95% CI, 9.3-15.7) and median PFS was 13.7 months (95% CI, 10.9-16.4). Median OS was not reached (95% CI, 22.2-not reached). ORR was numerically higher in patients with compound versus solitary uncommon EGFR mutations (84.4% vs 64.1%), with median PFS of 13.8 versus 11.0 months, respectively. Treatment-related adverse events (TRAEs) of any grade occurred in 97.0% (96/99) of patients, and grade ≥3 TRAEs occurred in 42.4% (42/99). The most common grade ≥3 TRAEs were diarrhea (28.3% [28/99]), hypokalemia (8.1% [8/99]), and increased gamma-glutamyl transferase (5.1% [5/99]). TRAEs led to dose reduction in 34.3% (34/99) and treatment discontinuation in 4.0% (4/99). No treatment-related deaths occurred.\n\nConclusions: Sutetinib met the prespecified primary endpoint and demonstrated clinically meaningful antitumor activity with a manageable safety profile in advanced NSCLC harboring uncommon EGFR mutations (G719X, S768I, and L861Q). These findings support sutetinib as a potential treatment option for this molecularly heterogeneous population.\n\nTrial registration: NCT05168566.\n\nIndexed on Europe PMC as PubMed record 42637134 (DOI 10.1016/j.jtho.2026.104165). Its abstract cites the registry id NCT05168566, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2026.104165", pmid: "42637134", authors: "Wu F, Zhang W, Zhao Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05168566 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2026.104165"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42637134/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42637134"},{"label":"ClinicalTrials.gov NCT05168566","url":"https://clinicaltrials.gov/study/NCT05168566"}], tags: ["europepmc-ingest"], trials: ["nct05168566"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct05288205-lancet-respir-med-2026", name: "Glecirasib plus sitneprotafib in patients with KRAS G12C -mutated non-small-cell lung cancer in China: an open-label, multicentre, single-arm, phase 1/2a trial", tldr: "Published report from the Phase 1 trial registered as NCT05288205, in The Lancet. Respiratory medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Monotherapy with KRAS G12C (ie, KRAS Gly12Cys) inhibitors has emerged as a mainstream treatment for patients with KRAS G12C -mutated non-small-cell lung cancer (NSCLC). Synergistic effects have been observed with the combination of a KRAS G12C inhibitor and a SHP2 inhibitor in multiple xenograft models. We aimed to evaluate the safety and efficacy of the KRAS G12C inhibitor glecirasib combined with the SHP2 inhibitor sitneprotafib (JAB-3312; Jacobio Pharmaceuticals, Beijing, China) in patients with KRAS G12C -mutated solid tumours.\n\nMethods: We conducted an open-label, multicentre, single-arm, phase 1/2a trial at 26 hospitals across China. Patients (aged ≥18 years) with locally advanced or metastatic solid tumours harbouring a KRAS G12C mutation, an Eastern Cooperative Oncology Group performance status score of 0-1, and measurable disease according to Response Evaluation Criteria in Solid Tumours (RECIST; version 1.1) were eligible for inclusion in both phases. Patients received oral glecirasib (400 mg or 800 mg once daily) in combination with oral sitneprotafib (2 mg or 3 mg once daily) in seven cohorts evaluating various dose levels and schedules of the two drugs. In phase 1, the primary endpoint was safety assessed by investigators according to the National Cancer Institute Common Terminology Criteria for Adverse Events (version 5.0) from first treatment dose to 30 days after the last dose of both agents. In phase 2a, the primary endpoint was objective response rate (ORR) between baseline and disease progression or initiation of anticancer therapy, whichever occurred first, based on the comprehensive assessment of all tumour evaluations by investigators following RECIST (version 1.1). All patients who received at least one dose of combination therapy were included in the safety and efficacy analyses. This trial is registered with ClinicalTrials.gov (NCT05288205) and is currently recruiting.\n\nFindings: Between May 7, 2022, and Aug 20, 2024, a total of 194 patients with advanced solid tumours were enrolled, of whom 171 (88%) had NSCLC (50 [29%] in phase 1 and 121 [71%] in phase 2a). Median participant age was 65 years (IQR 59-70); 140 (82%) were men and 31 (18%) were women. At data cutoff on Aug 20, 2024, the median follow-up duration was 14·5 months (IQR 11·9-17·1), and 106 (62%) patients had discontinued treatment. Phase 1 concluded with one dose-limiting toxicity (DLT; grade 3 pneumonitis) at the highest dose level (glecirasib 800 mg plus sitneprotafib 3 mg once daily, 1 week on and 1 week off); no DLTs were observed at other dose levels. Across phase 1 and 2a, 167 patients (98%) had at least one treatment-related adverse event, which were grade 3-4 in 78 (46%) patients. The most common treatment-related adverse events (occurring in ≥20% of all 171 patients) were anaemia (105 [61%]), hypertriglyceridaemia (103 [60%]), increased aspartate aminotransferase (95 [56%]), increased alanine aminotransferase (83 [49%]), increased blood bilirubin (78 [46%]), oedema (62 [36%]), increased blood creatine phosphokinase (60 [35%]), neutropenia (54 [32%]), decreased white blood cell count (50 [29%]), and increased bodyweight (44 [26%]). Three (2%) patients discontinued glecirasib and sitneprotafib due to treatment-related adverse events. No grade 5 treatment-related adverse event was reported. The ORR was 71% (72 patients [95% CI 61-79]) in the subgroup of 102 patients with previously untreated NSCLC; 49% (19 patients [32-65]) in the 39 patients previously treated with systemic therapy but naive to KRAS G12C inhibitors; and 10% (three patients [2-27]) in the 30 patients previously treated with KRAS G12C inhibitor therapy.\n\nInterpretation: Glecirasib combined with sitneprotafib showed promising efficacy and manageable safety in patients with advanced KRAS G12C -mutated NSCLC, particularly among those who had not received previous treatment. These findings support the evaluation of this combination in a phase 3 trial comparing this chemotherapy-free regimen to current standard of care in this patient group.\n\nFunding: Jacobio Pharmaceuticals.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 41325755 (DOI 10.1016/s2213-2600(25)00258-9). Its abstract cites the registry id NCT05288205, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2026, doi: "10.1016/s2213-2600(25)00258-9", pmid: "41325755", authors: "Zhong J, Zhao J, Duan J, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05288205 with the most citations, so it is the natural first reading for anyone following the Phase 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2026","url":"https://doi.org/10.1016/s2213-2600(25)00258-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41325755/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41325755"},{"label":"ClinicalTrials.gov NCT05288205","url":"https://clinicaltrials.gov/study/NCT05288205"}], tags: ["europepmc-ingest"], trials: ["nct05288205"] }),
  p({ id: "paper-nct05351788-nat-med-2025", name: "First-line sacituzumab tirumotecan with tagitanlimab in advanced non-small-cell lung cancer: a phase 2 trial", tldr: "Published report from the trial registered as NCT05351788, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Sacituzumab tirumotecan (sac-TMT, also known as MK-2870 or SKB264) is an antibody-drug conjugate targeting trophoblast cell surface antigen 2. We report the initial findings from the ongoing phase 2 OptiTROP-Lung01 study, evaluating the combination of sac-TMT and tagitanlimab (KL-A167), an anti-PD-L1 antibody, as first-line therapy in patients with advanced or metastatic non-small-cell lung cancer who lack actionable genomic alterations (cohorts 1A and 1B). Cohort 1A received sac-TMT (5 mg kg -1, every 3 weeks) plus tagitanlimab (1,200 mg, every 3 weeks) in each 3-week cycle, whereas cohort 1B was treated with sac-TMT (5 mg kg -1, every 2 weeks) plus tagitanlimab (900 mg, every 2 weeks) in each 4-week cycle, in a nonrandomized manner until disease progression or unacceptable toxicity. The primary endpoints included safety and objective response rate. This study was not powered for formal hypothesis testing. A total of 40 and 63 patients were enrolled in cohorts 1A and 1B, respectively. The median age was 63 years in both cohorts. An Eastern Cooperative Oncology Group performance status of 1 was observed in 97.5% and 85.7% of patients in cohorts 1A and 1B, respectively. In cohorts 1A and 1B, the most common grade ≥3 treatment-related adverse events were decreased neutrophil count (30.0% and 34.9%), decreased white blood cell count (5.0% and 19.0%) and anemia (5.0% and 19.0%). No treatment-related deaths were observed. After median follow-ups of 19.3 months for cohort 1A and 13.0 months for cohort 1B, the confirmed objective response rate in the full analysis set was 40.0% (16 of 40) and 66.7% (42 of 63), the disease control rate was 85.0% and 92.1% and median progression-free survival was 15.4 months (95% confidence interval 6.7-17.9) and not reached for cohorts 1A and 1B, respectively. sac-TMT plus tagitanlimab showed promising efficacy as a first-line treatment for advanced or metastatic non-small-cell lung cancer, with a manageable safety profile. ClinicalTrials.gov registration: NCT05351788.\n\nIndexed on Europe PMC as PubMed record 40830660 (DOI 10.1038/s41591-025-03883-5). Its abstract cites the registry id NCT05351788, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-03883-5", pmid: "40830660", authors: "Hong S, Wang Q, Cheng Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05351788 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-03883-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40830660/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40830660"},{"label":"ClinicalTrials.gov NCT05351788","url":"https://clinicaltrials.gov/study/NCT05351788"}], tags: ["europepmc-ingest"], trials: ["nct05351788"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05379985-n-engl-j-med-2026", name: "Daraxonrasib in Previously Treated Advanced RAS -Mutated Pancreatic Cancer", tldr: "Published report from the trial registered as NCT05379985, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Current therapies for patients with pancreatic ductal adenocarcinoma (PDAC) provide modest benefit. Activating RAS mutations occur in more than 90% of PDAC tumors. Daraxonrasib (RMC-6236) is an oral RAS(ON) multiselective inhibitor that targets guanosine triphosphate-bound mutant and wild-type RAS.\n\nMethods: In this phase 1-2 study, we evaluated daraxonrasib in patients with advanced solid tumors with activating RAS mutations. Patients received 10 to 400 mg of daraxonrasib orally once daily; 300 mg was selected as the phase 3 dose. The primary end point was safety. Pharmacokinetics and antitumor activity were secondary end points. This report focuses on the 168 study patients with previously treated RAS -mutated PDAC.\n\nResults: Among the 168 patients with PDAC who received daraxonrasib at a dose of 300 mg or less, treatment-related adverse events of any grade were reported in 96%; such events of grade 3 or higher were reported in 30%. Treatment-related adverse events that occurred in at least 10% of the patients included rash, diarrhea, nausea, stomatitis or mucositis, vomiting, and fatigue. In a subgroup of 26 patients with RAS G12 mutations who were treated with second-line daraxonrasib at a dose of 300 mg, an objective response to therapy was reported in 35% (95% confidence interval [CI], 17 to 56). The median duration of response was 8.2 months (95% CI, 3.8 to not evaluable), with median values of 8.5 months for progression-free survival and 13.1 months for overall survival. Among the 38 patients with RAS G12, G13, or Q61 mutations, 29% (95% CI, 15 to 46) had an objective response. The median duration of response was 8.2 months (95% CI, 3.8 to 8.8), with median values of 8.1 months for progression-free survival and 15.6 months for overall survival.\n\nConclusions: Daraxonrasib was associated with treatment-related adverse events of grade 3 or higher in one third of patients with previously treated RAS -mutated PDAC; antitumor activity was also reported. (Funded by Revolution Medicines; RMC-6236-001 ClinicalTrials.gov number, NCT05379985.).\n\nIndexed on Europe PMC as PubMed record 42090791 (DOI 10.1056/nejmoa2505783). Its abstract cites the registry id NCT05379985, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2505783", pmid: "42090791", authors: "Wolpin BM, Park W, Garrido-Laguna I, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05379985 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2505783"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42090791/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42090791"},{"label":"ClinicalTrials.gov NCT05379985","url":"https://clinicaltrials.gov/study/NCT05379985"}], tags: ["europepmc-ingest"], trials: ["nct05379985"], journals: ["nejm"] }),
  p({ id: "paper-nct05435248-j-transl-med-2025", name: "HS-10375, a selective EGFR C797S tyrosine kinase inhibitor, in advanced non-small cell lung cancer", tldr: "Published report from the Phase 1 trial registered as NCT05435248, in Journal of translational medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The C797S mutation is one of the most common mechanisms of acquired resistance to third generation EGFR TKIs, yet no approved therapies have been available to target it. Here we developed a novel selective EGFR C797S inhibitor, HS-10375, and report the results of pre-clinical research and the first-in-human phase 1 trial.\n\nMethods: Ba/F3 cell lines and patient-derived cells expressing mutant EGFR were used to test the selectively inhibitory potency of HS-10375 in vitro, and cell line-derived xenograft animal models were used to evaluate the anticancer efficacy of HS-10375 in vivo. In the phase 1 trial, HS-10375 was administered orally at six dose levels (10-240 mg) daily (QD) in 21-day cycles, following a rule-based, rolling six design. The primary objectives were the safety, tolerability and maximum tolerated dose (MTD). The secondary objectives included PK parameters and anti-tumor activity.\n\nResults: HS-10375 showed more potent activity in inhibiting EGFR phosphorylation compared to 1st to 3rd generation EGFR TKIs in C797S triple-mutant cell lines. HS-10375 also exhibited comparable inhibitory activity to 1st- and 2nd- generation EGFR TKIs and superior activity to 3rd-generation EGFR TKIs in C797S double-mutant cell lines. Furthermore, cells harboring EGFR double or triple C797S mutation underwent remarkable apoptosis upon HS-10375 treatment. HS-10375 effectively inhibited tumor growth in C797S triple-mutant mouse models. In the first-in-human trial, 28 patients with advanced or metastatic non-small cell lung cancers who harbored EGFR mutation and who had experienced treatment failure with EGFR TKI treatment received at least one dose of HS-10375. Dose-limiting toxicities were observed in 2 patients at 240 mg QD, and MTD was reached at HS-10375 150 mg QD. The most common treatment-related adverse events were vomit (37.0%), loss of appetite (33.3%), and elevated AST (33.3%). One patient with EGFR mutations showed tumor shrinkage after progression on five-line treatment including gefitinib, almonertinib, chemotherapy, immunotherapy, and EGFRxHER3 antibody-drug conjugate.\n\nConclusions: HS-10375 demonstrated potent and mutant-selective activity against the EGFR C797S mutation in preclinical results, and showed an acceptable safety profile and objective response in a first-in-human phase 1 trial. Trial registration This trial is registered on China Drug Trials (CTR20220045), and ClinicalTrials.gov (NCT05435248).\n\nIndexed on Europe PMC as PubMed record 40468352 (DOI 10.1186/s12967-025-06613-0). Its abstract cites the registry id NCT05435248, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of translational medicine", year: 2025, doi: "10.1186/s12967-025-06613-0", pmid: "40468352", authors: "Zhan J, Xue J, Wu L, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05435248 with the most citations, so it is the natural first reading for anyone following the Phase 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Transl Med 2025","url":"https://doi.org/10.1186/s12967-025-06613-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40468352/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40468352"},{"label":"ClinicalTrials.gov NCT05435248","url":"https://clinicaltrials.gov/study/NCT05435248"}], tags: ["europepmc-ingest"], trials: ["nct05435248"] }),
  p({ id: "paper-nct05751798-eur-j-cancer-2026", name: "A Phase 1 dose-escalation study to evaluate safety, pharmacokinetics, and pharmacodynamics of OSE-279, an anti-PD-1 monoclonal antibody in patients with advanced solid tumours", tldr: "Published report from the trial registered as NCT05751798, in European Journal of Cancer (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: OSE-279 is a high affinity humanized monoclonal bivalent antibody against PD-1 with potent antitumor activity in vivo in syngeneic non-clinical models.\n\nMethods: This phase I study assessed the safety, pharmacokinetics, pharmacodynamics and antitumor activity of OSE-279 in advanced solid tumours.\n\nResults: Twenty patients received OSE-279 intravenously at 100 mg q3w (n = 2), 300 mg q3w (n = 7) and 600 mg q6w (n = 11). Median age was 61.5 (range 3-81) years, 50% were female, median number of prior metastatic lines was 2 (range 1-6). Most frequent tumour types were soft tissue sarcoma (n = 4) and anal squamous cell carcinoma (n = 3). OSE-279 monotherapy was safe. Two recommended phase 2 doses were established: 300 mg q3w and 600 mg q6w. The most common (≥10%) related TEAEs were diarrhoea, dry mouth, pruritus, chills, fatigue, headache, dysgeusia and hyperthyroidism. OSE-279 PK exhibited linear dose proportionality and mean receptor occupancy was maintained above 80% in all tested doses. There were 1 CR at 300 mg q3w, 4 PRs at 600 mg q6w and 7 SD with response duration ranging from 6.8 to 18.4 months.\n\nConclusion: OSE-279 monotherapy was well tolerated with durable responses in patients with advanced solid tumours. The trial is continuing with OSE-279 combined with OSE2101, a therapeutic cancer vaccine in 1st line HLA-A2 positive PD-L1 ≥ 50% NSCLC. CLINICAL TRIAL REGISTRATION (NCT NUMBER: NCT05751798).\n\nIndexed on Europe PMC as PubMed record 42034003 (DOI 10.1016/j.ejca.2026.116729). Its abstract cites the registry id NCT05751798, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "European Journal of Cancer", year: 2026, doi: "10.1016/j.ejca.2026.116729", pmid: "42034003", authors: "Robert M, Kotecki N, Gomez-Roca C, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05751798 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Eur J Cancer 2026","url":"https://doi.org/10.1016/j.ejca.2026.116729"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42034003/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42034003"},{"label":"ClinicalTrials.gov NCT05751798","url":"https://clinicaltrials.gov/study/NCT05751798"}], tags: ["europepmc-ingest"], trials: ["nct05751798"], journals: ["european-journal-of-cancer"] }),
  p({ id: "paper-aphinity-j-clin-oncol-2024-update", name: "Adjuvant Pertuzumab and Trastuzumab in Early Human Epidermal Growth Factor Receptor 2-Positive Breast Cancer in the APHINITY Trial: Third Interim Overall Survival Analysis With Efficacy Update", tldr: "Later report from the APHINITY trial registered as NCT01358877, in Journal of Clinical Oncology (2024); its title describes an updated or longer-term analysis.", summary: "Clinical trials frequently include multiple end points that mature at different times. The initial report, typically based on the primary end point, may be published when key planned co-primary or secondary analyses are not yet available. Clinical Trial Updates provide an opportunity to disseminate additional results from studies, published in JCO or elsewhere, for which the primary end point has already been reported. The APHINITY trial (ClinicalTrials.gov identifier: NCT01358877) previously demonstrated that pertuzumab added to adjuvant trastuzumab and chemotherapy improved invasive disease-free survival (iDFS) for patients with early human epidermal growth factor receptor 2-positive (HER2+) breast cancer (BC). Here, we report the preplanned third interim analysis of overall survival (OS) and a descriptive updated iDFS analysis with 8.4 years of median follow-up of 4,804 patients in the intent-to-treat population. The 8-year OS was 92.7% in the pertuzumab versus 92.0% in the placebo group (hazard ratio [HR], 0.83 [95% CI, 0.68 to 1.02]; P =.078, above the 0.006 significance threshold). The HR was 0.80 [95% CI 0.63 to 1.00] in the node-positive cohort and 0.99 [95% CI, 0.64 to 1.55] in the node-negative cohort. Updated results of 8-year iDFS in the node-positive cohort showed an absolute improvement of 4.9% favoring pertuzumab (86.1% v 81.2%; HR, 0.72 [95% CI, 0.60 to 0.87]). The node-negative cohort did well without adding pertuzumab (8-year iDFS and OS in the placebo group were 93.3% and 96.4%, respectively). The iDFS benefit was seen in the hormone receptor-negative (HR, 0.82 [95% CI, 0.64 to 1.06]) and HR+ cohorts (HR of 0.75 [95% CI, 0.61 to 0.92]). Despite improvement in overall iDFS, the addition of pertuzumab did not improve OS at this third interim analysis.\n\nIndexed on Europe PMC as PubMed record 39259927 (DOI 10.1200/jco.23.02505). Its abstract cites the registry id NCT01358877, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2024, doi: "10.1200/jco.23.02505", pmid: "39259927", authors: "Loibl S, Jassem J, Sonnenblick A, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the APHINITY trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2024","url":"https://doi.org/10.1200/jco.23.02505"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39259927/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39259927"},{"label":"ClinicalTrials.gov NCT01358877","url":"https://clinicaltrials.gov/study/NCT01358877"}], tags: ["europepmc-ingest"], trials: ["aphinity"], journals: ["jco"] }),
  p({ id: "paper-apt-trial-lancet-oncol-2023-update", name: "Adjuvant paclitaxel and trastuzumab for node-negative, HER2-positive breast cancer: final 10-year analysis of the open-label, single-arm, phase 2 APT trial", tldr: "Later report from the trial registered as NCT00542451, in The Lancet Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Background: We aimed to report on long-term outcomes of patients with small, node-negative, HER2-positive breast cancer treated with adjuvant paclitaxel and trastuzumab and to establish potential biomarkers to predict prognosis.\n\nMethods: In this open-label, single-arm, phase 2 study, patients aged 18 years or older, with small (≤3 cm), node-negative, HER2-positive breast cancer, and an Eastern Cooperative Oncology Group performance status of 0-1, were recruited from 16 institutions in 13 cities in the USA. Eligible patients were given intravenous paclitaxel (80 mg/m 2) with intravenous trastuzumab (loading dose of 4 mg/kg, subsequent doses 2 mg/kg) weekly for 12 weeks, followed by trastuzumab (weekly at 2 mg/kg or once every 3 weeks at 6 mg/kg) for 40 weeks to complete a full year of trastuzumab. The primary endpoint was 3-year invasive disease-free survival. Here, we report 10-year survival outcomes, assessed in all participants who received protocol-defined treatment, with exploratory analyses using the HER2DX genomic tool. This study is registered on ClinicalTrials.gov, NCT00542451, and is closed to accrual.\n\nFindings: Between Oct 29, 2007, and Sept 3, 2010, 410 patients were enrolled and 406 were given adjuvant paclitaxel and trastuzumab and included in the analysis. Mean age at enrolment was 55 years (SD 10·5), 405 (99·8%) of 406 patients were female and one (0·2%) was male, 350 (86·2%) were White, 28 (6·9%) were Black or African American, and 272 (67·0%) had hormone receptor-positive disease. After a median follow-up of 10·8 years (IQR 7·1-11·4), among 406 patients included in the analysis population, we observed 31 invasive disease-free survival events, of which six (19·4%) were locoregional ipsilateral recurrences, nine (29·0%) were new contralateral breast cancers, six (19·4%) were distant recurrences, and ten (32·3%) were all-cause deaths. 10-year invasive disease-free survival was 91·3% (95% CI 88·3-94·4), 10-year recurrence-free interval was 96·3% (95% CI 94·3-98·3), 10-year overall survival was 94·3% (95% CI 91·8-96·8), and 10-year breast cancer-specific survival was 98·8% (95% CI 97·6-100). HER2DX risk score as a continuous variable was significantly associated with invasive disease-free survival (hazard ratio [HR] per 10-unit increment 1·24 [95% CI 1·00-1·52]; p=0·047) and recurrence-free interval (1·45 [1·09-1·93]; p=0·011).\n\nInterpretation: Adjuvant paclitaxel and trastuzumab is a reasonable treatment standard for patients with small, node-negative, HER2-positive breast cancer. The HER2DX genomic tool might help to refine the prognosis for this population.\n\nFunding: Genentech.\n\nIndexed on Europe PMC as PubMed record 36858723 (DOI 10.1016/s1470-2045(23)00051-7). Its abstract cites the registry id NCT00542451, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2023, doi: "10.1016/s1470-2045(23)00051-7", pmid: "36858723", authors: "Tolaney SM, Tarantino P, Graham N, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2023","url":"https://doi.org/10.1016/s1470-2045(23)00051-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36858723/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36858723"},{"label":"ClinicalTrials.gov NCT00542451","url":"https://clinicaltrials.gov/study/NCT00542451"}], tags: ["europepmc-ingest"], trials: ["apt-trial"], journals: ["lancet-oncology"] }),
  p({ id: "paper-ascent-03-n-engl-j-med-2025", name: "Sacituzumab Govitecan in Untreated, Advanced Triple-Negative Breast Cancer", tldr: "Published report from the ASCENT-03 trial registered as NCT05382299, in New England Journal of Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Patients with previously untreated, locally advanced, unresectable or metastatic triple-negative breast cancer who are not candidates for inhibitors of programmed cell death protein 1 (PD-1) or programmed death ligand 1 (PD-L1) have limited treatment options.\n\nMethods: In this international, phase 3, open-label, randomized trial, we enrolled patients with previously untreated, advanced triple-negative breast cancer who were not candidates for PD-1 or PD-L1 inhibitors owing to previous use or coexisting conditions. Patients had either PD-L1-negative tumors with a combined positive score (CPS; the number of PD-L1-staining tumor cells, lymphocytes, and macrophages divided by the total number of viable tumor cells, multiplied by 100) of less than 10 or PD-L1-positive tumors with a CPS of 10 or higher and were assigned in a 1:1 ratio to receive sacituzumab govitecan or chemotherapy (paclitaxel, nanoparticle albumin-bound paclitaxel, or gemcitabine plus carboplatin). The primary end point was progression-free survival, assessed by blinded independent central review. Secondary end points included overall survival, objective response, the duration of response, and safety.\n\nResults: Among 558 patients, median progression-free survival was 9.7 months (95% confidence interval [CI], 8.1 to 11.1) with sacituzumab govitecan and 6.9 months (95% CI, 5.6 to 8.2) with chemotherapy (stratified hazard ratio for disease progression or death, 0.62; 95% CI, 0.50 to 0.77; P<0.001). An objective response was confirmed in 48% of patients (95% CI, 42 to 54) who received sacituzumab govitecan and 46% (95% CI, 40 to 52) who received chemotherapy; the median response duration was 12.2 months (95% CI, 9.7 to 13.8) and 7.2 months (95% CI, 5.7 to 8.4), respectively. Adverse events of grade 3 or higher occurred in 66% of patients who received sacituzumab govitecan (most frequently neutropenia [in 43%], diarrhea [in 9%], and leukopenia [in 7%]) and in 62% of patients who received chemotherapy (most frequently neutropenia [in 41%], anemia [in 16%], and leukopenia [in 13%]). The incidence of adverse events that led to discontinuation of sacituzumab govitecan or at least one chemotherapy drug was 4% and 12%, respectively.\n\nConclusions: Sacituzumab govitecan led to significantly longer progression-free survival than chemotherapy among patients with advanced triple-negative breast cancer who were not candidates for treatment with PD-1 or PD-L1 inhibitors. The incidence of adverse events of grade 3 or higher with sacituzumab govitecan was similar to that with chemotherapy, but adverse events were common. (Funded by Gilead Sciences; ASCENT-03 ClinicalTrials.gov number, NCT05382299.).\n\nIndexed on Europe PMC as PubMed record 41124233 (DOI 10.1056/nejmoa2511734). Its abstract cites the registry id NCT05382299, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2511734", pmid: "41124233", authors: "Cortés J, Punie K, Barrios C, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05382299 with the most citations, so it is the natural first reading for anyone following the ASCENT-03 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2511734"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41124233/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41124233"},{"label":"ClinicalTrials.gov NCT05382299","url":"https://clinicaltrials.gov/study/NCT05382299"}], tags: ["europepmc-ingest"], trials: ["ascent-03"], journals: ["nejm"] }),
  p({ id: "paper-ascent-04-n-engl-j-med-2026", name: "Sacituzumab Govitecan plus Pembrolizumab for Advanced Triple-Negative Breast Cancer", tldr: "Published report from the ASCENT-04 trial registered as NCT05382286, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Triple-negative breast cancer is an aggressive breast cancer subtype, and there remains an unmet need to improve outcomes in patients with previously untreated, programmed death ligand 1 (PD-L1)-positive, locally advanced unresectable or metastatic triple-negative breast cancer.\n\nMethods: In this phase 3, open-label, international trial, we randomly assigned patients in a 1:1 ratio to receive sacituzumab govitecan plus pembrolizumab or chemotherapy plus pembrolizumab. The primary end point was progression-free survival as assessed by blinded independent central review. Secondary end points included overall survival, objective response (complete or partial response) and duration of response as assessed by blinded independent central review, and safety.\n\nResults: A total of 443 patients were randomly assigned to receive sacituzumab govitecan plus pembrolizumab (221 patients) or chemotherapy plus pembrolizumab (222 patients). The median progression-free survival was 11.2 months (95% confidence interval [CI], 9.3 to 16.7) with sacituzumab govitecan plus pembrolizumab and 7.8 months (95% CI, 7.3 to 9.3) with chemotherapy plus pembrolizumab (hazard ratio for disease progression or death, 0.65; 95% CI, 0.51 to 0.84; two-sided P<0.001). Data for overall survival were immature. The percentage of patients with an objective response was 60% (95% CI, 53 to 66) with sacituzumab govitecan plus pembrolizumab and 53% (95% CI, 46 to 60) with chemotherapy plus pembrolizumab; among patients with a response, the median duration of response was 16.5 months (95% CI, 12.7 to 19.5) and 9.2 months (95% CI, 7.6 to 11.3), respectively. Adverse events of grade 3 or higher occurred in 71% of the patients receiving sacituzumab govitecan plus pembrolizumab and in 70% of those receiving chemotherapy plus pembrolizumab; the incidence of treatment discontinuation due to adverse events was 12% and 31%, respectively. Adverse events leading to death occurred in 3% of the patients in each group.\n\nConclusions: Sacituzumab govitecan plus pembrolizumab led to significantly longer progression-free survival than chemotherapy plus pembrolizumab among patients with previously untreated, PD-L1-positive, advanced triple-negative breast cancer. (Funded by Gilead Sciences; ASCENT-04/KEYNOTE-D19 ClinicalTrials.gov number, NCT05382286.).\n\nIndexed on Europe PMC as PubMed record 41564397 (DOI 10.1056/nejmoa2508959). Its abstract cites the registry id NCT05382286, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2508959", pmid: "41564397", authors: "Tolaney SM, de Azambuja E, Kalinsky K, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05382286 with the most citations, so it is the natural first reading for anyone following the ASCENT-04 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2508959"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41564397/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41564397"},{"label":"ClinicalTrials.gov NCT05382286","url":"https://clinicaltrials.gov/study/NCT05382286"}], tags: ["europepmc-ingest"], trials: ["ascent-04"], journals: ["nejm"] }),
  p({ id: "paper-bolero-2-n-engl-j-med-2012", name: "Everolimus in postmenopausal hormone-receptor-positive advanced breast cancer", tldr: "Published report from the BOLERO-2 trial registered as NCT00863655, in New England Journal of Medicine (2012), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Resistance to endocrine therapy in breast cancer is associated with activation of the mammalian target of rapamycin (mTOR) intracellular signaling pathway. In early studies, the mTOR inhibitor everolimus added to endocrine therapy showed antitumor activity.\n\nMethods: In this phase 3, randomized trial, we compared everolimus and exemestane versus exemestane and placebo (randomly assigned in a 2:1 ratio) in 724 patients with hormone-receptor-positive advanced breast cancer who had recurrence or progression while receiving previous therapy with a nonsteroidal aromatase inhibitor in the adjuvant setting or to treat advanced disease (or both). The primary end point was progression-free survival. Secondary end points included survival, response rate, and safety. A preplanned interim analysis was performed by an independent data and safety monitoring committee after 359 progression-free survival events were observed.\n\nResults: Baseline characteristics were well balanced between the two study groups. The median age was 62 years, 56% had visceral involvement, and 84% had hormone-sensitive disease. Previous therapy included letrozole or anastrozole (100%), tamoxifen (48%), fulvestrant (16%), and chemotherapy (68%). The most common grade 3 or 4 adverse events were stomatitis (8% in the everolimus-plus-exemestane group vs. 1% in the placebo-plus-exemestane group), anemia (6% vs. <1%), dyspnea (4% vs. 1%), hyperglycemia (4% vs. <1%), fatigue (4% vs. 1%), and pneumonitis (3% vs. 0%). At the interim analysis, median progression-free survival was 6.9 months with everolimus plus exemestane and 2.8 months with placebo plus exemestane, according to assessments by local investigators (hazard ratio for progression or death, 0.43; 95% confidence interval [CI], 0.35 to 0.54; P<0.001). Median progression-free survival was 10.6 months and 4.1 months, respectively, according to central assessment (hazard ratio, 0.36; 95% CI, 0.27 to 0.47; P<0.001).\n\nConclusions: Everolimus combined with an aromatase inhibitor improved progression-free survival in patients with hormone-receptor-positive advanced breast cancer previously treated with nonsteroidal aromatase inhibitors. (Funded by Novartis; BOLERO-2 ClinicalTrials.gov number, NCT00863655.).\n\nIndexed on Europe PMC as PubMed record 22149876 (DOI 10.1056/nejmoa1109653). Its abstract cites the registry id NCT00863655, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2012, doi: "10.1056/nejmoa1109653", pmid: "22149876", authors: "Baselga J, Campone M, Piccart M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00863655 with the most citations, so it is the natural first reading for anyone following the BOLERO-2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2012","url":"https://doi.org/10.1056/nejmoa1109653"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/22149876/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/22149876"},{"label":"ClinicalTrials.gov NCT00863655","url":"https://clinicaltrials.gov/study/NCT00863655"}], tags: ["europepmc-ingest"], trials: ["bolero-2"], journals: ["nejm"] }),
  p({ id: "paper-bolero-2-ann-oncol-2014-update", name: "Everolimus plus exemestane for hormone-receptor-positive, human epidermal growth factor receptor-2-negative advanced breast cancer: overall survival results from BOLERO-2†", tldr: "Later report from the BOLERO-2 trial registered as NCT00863655, in Annals of Oncology (2014); its title describes an updated or longer-term analysis.", summary: "Background: The BOLERO-2 study previously demonstrated that adding everolimus (EVE) to exemestane (EXE) significantly improved progression-free survival (PFS) by more than twofold in patients with hormone-receptor-positive (HR(+)), HER2-negative advanced breast cancer that recurred or progressed during/after treatment with nonsteroidal aromatase inhibitors (NSAIs). The overall survival (OS) analysis is presented here.\n\nPatients and methods: BOLERO-2 is a phase III, double-blind, randomized international trial comparing EVE 10 mg/day plus EXE 25 mg/day versus placebo (PBO) + EXE 25 mg/day in postmenopausal women with HR(+) advanced breast cancer with prior exposure to NSAIs. The primary end point was PFS by local investigator assessment; OS was a key secondary end point.\n\nResults: At the time of data cutoff (3 October 2013), 410 deaths had occurred and 13 patients remained on treatment. Median OS in patients receiving EVE + EXE was 31.0 months [95% confidence interval (CI) 28.0-34.6 months] compared with 26.6 months (95% CI 22.6-33.1 months) in patients receiving PBO + EXE (hazard ratio = 0.89; 95% CI 0.73-1.10; log-rank P = 0.14). Poststudy treatments were received by 84% of patients in the EVE + EXE arm versus 90% of patients in the PBO + EXE arm. Types of poststudy therapies were balanced across arms, except for chemotherapy (53% EVE + EXE versus 63% PBO + EXE). No new safety concerns were identified.\n\nConclusions: In BOLERO-2, adding EVE to EXE did not confer a statistically significant improvement in the secondary end point OS despite producing a clinically meaningful and statistically significant improvement in the primary end point, PFS (4.6-months prolongation in median PFS; P < 0.0001). Ongoing translational research should further refine the benefit of mTOR inhibition and related pathways in this treatment setting.\n\nTrial registration number: NCT00863655.\n\nIndexed on Europe PMC as PubMed record 25231953 (DOI 10.1093/annonc/mdu456). Its abstract cites the registry id NCT00863655, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2014, doi: "10.1093/annonc/mdu456", pmid: "25231953", authors: "Piccart M, Hortobagyi GN, Campone M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the BOLERO-2 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2014","url":"https://doi.org/10.1093/annonc/mdu456"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/25231953/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/25231953"},{"label":"ClinicalTrials.gov NCT00863655","url":"https://clinicaltrials.gov/study/NCT00863655"}], tags: ["europepmc-ingest"], trials: ["bolero-2"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-cleopatra-n-engl-j-med-2012", name: "Pertuzumab plus trastuzumab plus docetaxel for metastatic breast cancer", tldr: "Published report from the CLEOPATRA trial registered as NCT00567190, in New England Journal of Medicine (2012), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The anti-human epidermal growth factor receptor 2 (HER2) humanized monoclonal antibody trastuzumab improves the outcome in patients with HER2-positive metastatic breast cancer. However, most cases of advanced disease eventually progress. Pertuzumab, an anti-HER2 humanized monoclonal antibody that inhibits receptor dimerization, has a mechanism of action that is complementary to that of trastuzumab, and combination therapy with the two antibodies has shown promising activity and an acceptable safety profile in phase 2 studies involving patients with HER2-positive breast cancer.\n\nMethods: We randomly assigned 808 patients with HER2-positive metastatic breast cancer to receive placebo plus trastuzumab plus docetaxel (control group) or pertuzumab plus trastuzumab plus docetaxel (pertuzumab group) as first-line treatment until the time of disease progression or the development of toxic effects that could not be effectively managed. The primary end point was independently assessed progression-free survival. Secondary end points included overall survival, progression-free survival as assessed by the investigator, the objective response rate, and safety.\n\nResults: The median progression-free survival was 12.4 months in the control group, as compared with 18.5 months in the pertuzumab group (hazard ratio for progression or death, 0.62; 95% confidence interval, 0.51 to 0.75; P<0.001). The interim analysis of overall survival showed a strong trend in favor of pertuzumab plus trastuzumab plus docetaxel. The safety profile was generally similar in the two groups, with no increase in left ventricular systolic dysfunction; the rates of febrile neutropenia and diarrhea of grade 3 or above were higher in the pertuzumab group than in the control group.\n\nConclusions: The combination of pertuzumab plus trastuzumab plus docetaxel, as compared with placebo plus trastuzumab plus docetaxel, when used as first-line treatment for HER2-positive metastatic breast cancer, significantly prolonged progression-free survival, with no increase in cardiac toxic effects. (Funded by F. Hoffmann-La Roche/Genentech; ClinicalTrials.gov number, NCT00567190.).\n\nIndexed on Europe PMC as PubMed record 22149875 (DOI 10.1056/nejmoa1113216). Its abstract cites the registry id NCT00567190, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2012, doi: "10.1056/nejmoa1113216", pmid: "22149875", authors: "Baselga J, Cortés J, Kim SB, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00567190 with the most citations, so it is the natural first reading for anyone following the CLEOPATRA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2012","url":"https://doi.org/10.1056/nejmoa1113216"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/22149875/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/22149875"},{"label":"ClinicalTrials.gov NCT00567190","url":"https://clinicaltrials.gov/study/NCT00567190"}], tags: ["europepmc-ingest"], trials: ["cleopatra"], journals: ["nejm"] }),
  p({ id: "paper-cleopatra-lancet-oncol-2013-update", name: "Pertuzumab, trastuzumab, and docetaxel for HER2-positive metastatic breast cancer (CLEOPATRA study): overall survival results from a randomised, double-blind, placebo-controlled, phase 3 study", tldr: "Later report from the CLEOPATRA trial registered as NCT00567190, in The Lancet Oncology (2013); its title describes an updated or longer-term analysis.", summary: "Background: CLEOPATRA is a phase 3 study to compare the efficacy and safety of pertuzumab, trastuzumab, and docetaxel with placebo, trastuzumab, and docetaxel in patients with HER2-positive first-line metastatic breast cancer. The results of the primary analysis showed significantly longer median progression-free survival in the pertuzumab group than in the placebo group. Interim analysis of overall survival favoured the pertuzumab group but was not significant. Here, we report results for overall survival after an additional year of follow-up.\n\nMethods: The study was a double-blind randomised trial undertaken at 204 centres in 25 countries. Patients with HER2-positive metastatic breast cancer who had not received previous chemotherapy or biological treatment for their metastatic disease were randomly assigned to receive either pertuzumab, trastuzumab, and docetaxel (n=402) or the same regimen with a matching placebo replacing pertuzumab (n=406). Randomisation was in a 1:1 ratio, stratified by geographical region and previous treatment status. The primary endpoint was progression-free survival (assessed independently), which has been reported previously; no follow-up data were gathered for the primary endpoint. Secondary endpoints included overall survival, progression-free survival (assessed by investigator), objective response rate, and safety. Median follow-up was 30 months in both groups. Efficacy endpoints were analysed in the intention-to-treat population and safety was analysed by treatment received. The study is completed but safety and survival data continue to be followed up. This trial is registered with ClinicalTrials.gov, number NCT00567190.\n\nFindings: In the intention-to-treat population, 267 patients died by data cutoff (May 14, 2012), 154 (38%) of 406 in the placebo group and 113 (28%) of 402 in the pertuzumab group. Median overall survival was 37.6 months (95% CI 34.3-NE [not estimable]) in the placebo group but had not been reached (95% CI 42.4-NE) in the pertuzumab group (hazard ratio 0.66, 95% CI 0.52-0.84; p=0.0008). Investigator-assessed median progression-free survival was 12.4 months (95% CI 10.4-13.5) in the placebo group and 18.7 months (16.6-21.6) in the pertuzumab group (hazard ratio 0.69, 95% CI 0.58-0.81). Serious adverse events were reported in 115 (29%) of 396 patients who received placebo, trastuzumab, and docetaxel and 148 (36%) of 408 who received pertuzumab, trastuzumab, and docetaxel, and included febrile neutropenia, neutropenia, diarrhoea, pneumonia, and cellulitis. Overall, adverse events were similar to those reported at the primary analysis with respect to frequency, severity, and specificity.\n\nInterpretation: Our analysis shows a significant improvement in overall survival with pertuzumab, trastuzumab, and docetaxel in patients with HER2-positive metastatic breast cancer, compared with placebo, trastuzumab, and docetaxel. Since this effect was not achieved at the expense of adverse events, this regimen represents a substantial improvement on the standard of care for this population of patients.\n\nFunding: F Hoffmann-La Roche, Genentech.\n\nIndexed on Europe PMC as PubMed record 23602601 (DOI 10.1016/s1470-2045(13)70130-x). Its abstract cites the registry id NCT00567190, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2013, doi: "10.1016/s1470-2045(13)70130-x", pmid: "23602601", authors: "Swain SM, Kim SB, Cortés J, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CLEOPATRA trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2013","url":"https://doi.org/10.1016/s1470-2045(13)70130-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/23602601/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/23602601"},{"label":"ClinicalTrials.gov NCT00567190","url":"https://clinicaltrials.gov/study/NCT00567190"}], tags: ["europepmc-ingest"], trials: ["cleopatra"], journals: ["lancet-oncology"] }),
  p({ id: "paper-comet-dcis-jama-2025", name: "Active Monitoring With or Without Endocrine Therapy for Low-Risk Ductal Carcinoma In Situ: The COMET Randomized Clinical Trial", tldr: "Published report from the COMET trial registered as NCT02926911, in JAMA (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Active monitoring for low-risk ductal carcinoma in situ (DCIS) of the breast has been proposed as an alternative to guideline-concordant care, but the safety of this approach is unknown.\n\nObjective: To compare rates of invasive cancer in patients with low-risk DCIS receiving active monitoring vs guideline-concordant care.\n\nDesign, setting, and participants: Prospective, randomized noninferiority trial enrolling 995 women aged 40 years or older with a new diagnosis of hormone receptor-positive grade 1 or grade 2 DCIS without invasive cancer at 100 US Alliance Cancer Cooperative Group clinical trial sites from 2017 to 2023.\n\nInterventions: Participants were randomized to receive active monitoring (follow-up every 6 months with breast imaging and physical examination; n = 484) or guideline-concordant care (surgery with or without radiation therapy; n = 473).\n\nMain outcomes and measures: The primary outcome was 2-year cumulative risk of ipsilateral invasive cancer diagnosis, according to planned intention-to-treat and per-protocol analyses, with a noninferiority bound of 5%.\n\nResults: The median age of the 957 participants analyzed was 63.6 (95% CI, 55.5-70.5) years in the guideline-concordant care group and 63.7 (95% CI, 60.0-71.6) years in the active monitoring group. Overall, 15.7% of participants were Black and 75.0% were White. In this prespecified primary analysis, median follow-up was 36.9 months; 346 patients had surgery for DCIS, 264 in the guideline-concordant care group and 82 in the active monitoring group. Forty-six women were diagnosed with invasive cancer, 19 in the active monitoring group and 27 in the guideline-concordant care group. The 2-year Kaplan-Meier cumulative rate of ipsilateral invasive cancer was 4.2% in the active monitoring group vs 5.9% in the guideline-concordant care group, a difference of -1.7% (upper limit of the 95% CI, 0.95%), indicating that active monitoring is not inferior to guideline-concordant care. Invasive tumor characteristics did not differ significantly between groups.\n\nConclusions and relevance: Women with low-risk DCIS randomized to active monitoring did not have a higher rate of invasive cancer in the same breast at 2 years compared with those randomized to guideline-concordant care.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02926911.\n\nIndexed on Europe PMC as PubMed record 39665585 (DOI 10.1001/jama.2024.26698). Its abstract cites the registry id NCT02926911, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2025, doi: "10.1001/jama.2024.26698", pmid: "39665585", authors: "Hwang ES, Hyslop T, Lynch T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02926911 with the most citations, so it is the natural first reading for anyone following the COMET trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2025","url":"https://doi.org/10.1001/jama.2024.26698"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39665585/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39665585"},{"label":"ClinicalTrials.gov NCT02926911","url":"https://clinicaltrials.gov/study/NCT02926911"}], tags: ["europepmc-ingest"], trials: ["comet-dcis"], journals: ["jama"] }),
  p({ id: "paper-dawna-1-nat-med-2021", name: "Dalpiciclib or placebo plus fulvestrant in hormone receptor-positive and HER2-negative advanced breast cancer: a randomized, phase 3 trial", tldr: "Published report from the DAWNA-1 trial registered as NCT03927456, in Nature Medicine (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Blockade of the cyclin-dependent kinase 4 and 6 pathway has been shown to be effective in the treatment of hormone receptor-positive advanced breast cancer (ABC). We report the interim results of DAWNA-1 ( NCT03927456), a double-blind, randomized, phase 3 trial of dalpiciclib (a new cyclin-dependent kinase 4 and 6 inhibitor) plus fulvestrant in hormone receptor-positive, HER2-negative ABC with disease progression after endocrine therapy. A total of 361 patients were randomized 2:1 to receive dalpiciclib plus fulvestrant or placebo plus fulvestrant. The study met the primary end point, showing significantly prolonged investigator-assessed progression-free survival with dalpiciclib plus fulvestrant versus placebo plus fulvestrant (median = 15.7, 95% confidence interval (CI) = 11.1-not reached versus 7.2, 95% CI = 5.6-9.2 months; hazard ratio = 0.42, 95% CI = 0.31-0.58; one-sided P < 0.0001 (boundary was P ≤ 0.008)). The most common grade 3 or 4 adverse events with dalpiciclib plus fulvestrant were neutropenia (84.2%) and leukopenia (62.1%). The incidence of serious adverse events was 5.8% with dalpiciclib plus fulvestrant versus 6.7% with placebo plus fulvestrant. Our findings support dalpiciclib plus fulvestrant as a new treatment option for pretreated hormone receptor-positive, HER2-negative ABC.\n\nIndexed on Europe PMC as PubMed record 34737452 (DOI 10.1038/s41591-021-01562-9). Its abstract cites the registry id NCT03927456, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2021, doi: "10.1038/s41591-021-01562-9", pmid: "34737452", authors: "Xu B, Zhang Q, Zhang P, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03927456 with the most citations, so it is the natural first reading for anyone following the DAWNA-1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2021","url":"https://doi.org/10.1038/s41591-021-01562-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34737452/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34737452"},{"label":"ClinicalTrials.gov NCT03927456","url":"https://clinicaltrials.gov/study/NCT03927456"}], tags: ["europepmc-ingest"], trials: ["dawna-1"], journals: ["nature-medicine"] }),
  p({ id: "paper-destiny-breast03-lancet-2023-update", name: "Trastuzumab deruxtecan versus trastuzumab emtansine in patients with HER2-positive metastatic breast cancer: updated results from DESTINY-Breast03, a randomised, open-label, phase 3 trial", tldr: "Later report from the DESTINY-Breast03 trial registered as NCT03529110, in The Lancet (2023); its title describes an updated or longer-term analysis.", summary: "Background: An improvement in progression-free survival was shown with trastuzumab deruxtecan versus trastuzumab emtansine in patients with HER2-positive metastatic breast cancer in the progression-free survival interim analysis of the DESTINY-Breast03 trial. The aim of DESTINY-Breast03 was to compare the efficacy and safety of trastuzumab deruxtecan versus trastuzumab emtansine.\n\nMethods: This open-label, randomised, multicentre, phase 3 trial was done in 169 study centres in North America, Asia, Europe, Australia, and South America. Eligible patients were aged 18 or older, had HER2-positive unresectable or metastatic breast cancer previously treated with trastuzumab and a taxane, had an Eastern Cooperative Oncology Group performance status 0-1, and at least one measurable lesion per Response Evaluation Criteria in Solid Tumours version 1.1. Patients were randomly assigned (1:1) to receive trastuzumab deruxtecan 5·4 mg/kg or trastuzumab emtansine 3·6 mg/kg, both administered by intravenous infusion every 3 weeks. Randomisation was stratified by hormone receptor status, previous treatment with pertuzumab, and history of visceral disease, and was managed through an interactive web-based system. Within each stratum, balanced block randomisation was used with a block size of four. Patients and investigators were not masked to the treatment received. The primary endpoint was progression-free survival by blinded independent central review. The key secondary endpoint was overall survival and this prespecified second overall survival interim analysis reports updated overall survival, efficacy, and safety results. Efficacy analyses were performed using the full analysis set. Safety analyses included all randomly assigned patients who received at least one dose of study treatment. This study is registered with ClinicalTrials.gov, NCT03529110.\n\nFindings: Between July 20, 2018, and June 23, 2020, 699 patients were screened for eligibility, 524 of whom were enrolled and randomly assigned to receive trastuzumab deruxtecan (n=261) or trastuzumab emtansine (n=263). Median duration of study follow-up was 28·4 months (IQR 22·1-32·9) with trastuzumab deruxtecan and 26·5 months (14·5-31·3) with trastuzumab emtansine. Median progression-free survival by blinded independent central review was 28·8 months (95% CI 22·4-37·9) with trastuzumab deruxtecan and 6·8 months (5·6-8·2) with trastuzumab emtansine (hazard ratio [HR] 0·33 [95% CI 0·26-0·43]; nominal p<0·0001). Median overall survival was not reached (95% CI 40·5 months-not estimable), with 72 (28%) overall survival events, in the trastuzumab deruxtecan group and was not reached (34·0 months-not estimable), with 97 (37%) overall survival events, in the trastuzumab emtansine group (HR 0·64; 95% CI 0·47-0·87]; p=0·0037). The number of grade 3 or worse treatment-emergent adverse events was similar in patients who received trastuzumab deruxtecan versus trastuzumab emtansine (145 [56%] patients versus 135 [52%] patients). Adjudicated drug-related interstitial lung disease or pneumonitis occurred in 39 (15%) patients treated with trastuzumab deruxtecan and eight (3%) patients treated with trastuzumab emtansine, with no grade 4 or 5 events in either group.\n\nInterpretation: Trastuzumab deruxtecan showed a significant improvement in overall survival versus trastuzumab emtansine in patients with HER2-positive metastatic breast cancer, as well as the longest reported median progression-free survival, reaffirming trastuzumab deruxtecan as the standard of care in the second-line setting. A manageable safety profile of trastuzumab deruxtecan was confirmed with longer treatment duration.\n\nFunding: Daiichi Sankyo and AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 36495879 (DOI 10.1016/s0140-6736(22)02420-5). Its abstract cites the registry id NCT03529110, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2023, doi: "10.1016/s0140-6736(22)02420-5", pmid: "36495879", authors: "Hurvitz SA, Hegg R, Chung WP, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the DESTINY-Breast03 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet 2023","url":"https://doi.org/10.1016/s0140-6736(22)02420-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36495879/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36495879"},{"label":"ClinicalTrials.gov NCT03529110","url":"https://clinicaltrials.gov/study/NCT03529110"}], tags: ["europepmc-ingest"], trials: ["destiny-breast03"], journals: ["lancet"] }),
  p({ id: "paper-destiny-breast04-nat-med-2025-update", name: "Trastuzumab deruxtecan in HER2-low metastatic breast cancer: long-term survival analysis of the randomized, phase 3 DESTINY-Breast04 trial", tldr: "Later report from the DESTINY-Breast04 trial registered as NCT03734029, in Nature Medicine (2025); its title describes an updated or longer-term analysis.", summary: "In DESTINY-Breast04 ( NCT03734029), trastuzumab deruxtecan (T-DXd) significantly improved overall survival (OS) and progression-free survival compared with treatment of physician's choice of chemotherapy (TPC) for patients with human epidermal growth factor receptor 2-low (HER2-low) (immunohistochemistry (IHC) 1+ or IHC 2+/in situ hybridization-negative) metastatic breast cancer. After an extended median follow-up of 32.0 months, median OS in the overall cohort was 22.9 months for T-DXd and 16.8 months for TPC (hazard ratio 0.69; 95% confidence interval 0.55-0.86). For the hormone receptor-positive cohort, median OS was 23.9 and 17.6 months for T-DXd and TPC, respectively (hazard ratio 0.69; 95% confidence interval 0.55-0.87). Median OS also favored T-DXd in exploratory analyses of hormone receptor-negative, estrogen receptor IHC 1%-10% and estrogen receptor IHC >10% cohorts. The overall safety profile of T-DXd was acceptable and generally manageable. Results confirm T-DXd as standard of care after prior chemotherapy in patients with HER2-low metastatic breast cancer. ClinicalTrials.gov identifier: NCT03734029.\n\nIndexed on Europe PMC as PubMed record 41062831 (DOI 10.1038/s41591-025-03981-4). Its abstract cites the registry id NCT03734029, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-03981-4", pmid: "41062831", authors: "Modi S, Jacot W, Iwata H, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the DESTINY-Breast04 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-03981-4"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41062831/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41062831"},{"label":"ClinicalTrials.gov NCT03734029","url":"https://clinicaltrials.gov/study/NCT03734029"}], tags: ["europepmc-ingest"], trials: ["destiny-breast04"], journals: ["nature-medicine"] }),
  p({ id: "paper-destiny-breast05-n-engl-j-med-2026", name: "Trastuzumab Deruxtecan in Residual HER2-Positive Early Breast Cancer", tldr: "Published report from the DESTINY-Breast05 trial registered as NCT04622319, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Patients with human epidermal growth factor receptor 2 (HER2)-positive early breast cancer and residual disease after neoadjuvant therapy are at high risk for recurrence.\n\nMethods: In a phase 3, open-label, international, randomized trial, we investigated postneoadjuvant trastuzumab deruxtecan (T-DXd; 5.4 mg per kilogram of body weight) as compared with trastuzumab emtansine (T-DM1; 3.6 mg per kilogram), the current standard treatment, in patients with HER2-positive breast cancer with residual invasive disease and node-positive disease at surgery or inoperable disease at diagnosis. The primary end point was invasive disease-free survival, and the key secondary end point was disease-free survival (including survival free from noninvasive breast cancers and second primary nonbreast cancers). Other end points included overall survival, distant recurrence-free interval, brain metastasis-free interval, and safety.\n\nResults: A total of 1635 patients were randomly assigned (in a 1:1 ratio) to receive T-DXd (818 patients) or T-DM1 (817 patients). At the data-cutoff date, the median duration of follow-up was approximately 30 months in each group. Invasive-disease events or deaths were reported in 51 patients (6.2%) in the T-DXd group and 102 patients (12.5%) in the T-DM1 group (hazard ratio, 0.47; 95% confidence interval [CI], 0.34 to 0.66; P<0.001); 3-year invasive disease-free survival was 92.4% and 83.7%, respectively. Invasive-disease events, noninvasive-disease events, or deaths were reported in 52 patients (6.4%) in the T-DXd group and 103 patients (12.6%) in the T-DM1 group (hazard ratio, 0.47; 95% CI, 0.34 to 0.66; P<0.001); 3-year disease-free survival was 92.3% and 83.5%, respectively. The most common adverse events were nausea (71.3% of patients), constipation (32.0%), decreased neutrophil count (31.6%), and vomiting (31.0%) with T-DXd and increased liver-enzyme levels (aspartate aminotransferase [50.2%] and alanine aminotransferase [45.3%]) and decreased platelet count (49.8%) with T-DM1. The incidence of adjudicated drug-related interstitial lung disease was higher with T-DXd than with T-DM1 (9.6% vs. 1.6%). Two patients with interstitial lung disease in the T-DXd group died.\n\nConclusions: In patients with high-risk, residual invasive HER2-positive breast cancer, postneoadjuvant T-DXd resulted in a significantly higher likelihood of invasive disease-free survival than T-DM1; toxic effects were mainly gastrointestinal and hematologic. An important identified risk of T-DXd is interstitial lung disease, which requires appropriate monitoring and management. (Funded by Daiichi Sankyo and AstraZeneca; DESTINY-Breast05 ClinicalTrials.gov number, NCT04622319.).\n\nIndexed on Europe PMC as PubMed record 41370739 (DOI 10.1056/nejmoa2514661). Its abstract cites the registry id NCT04622319, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2514661", pmid: "41370739", authors: "Loibl S, Park YH, Shao Z, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04622319 with the most citations, so it is the natural first reading for anyone following the DESTINY-Breast05 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2514661"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41370739/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41370739"},{"label":"ClinicalTrials.gov NCT04622319","url":"https://clinicaltrials.gov/study/NCT04622319"}], tags: ["europepmc-ingest"], trials: ["destiny-breast05"], journals: ["nejm"] }),
  p({ id: "paper-destiny-breast09-n-engl-j-med-2026", name: "Trastuzumab Deruxtecan plus Pertuzumab for HER2-Positive Metastatic Breast Cancer", tldr: "Published report from the DESTINY-Breast09 trial registered as NCT04784715, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Trastuzumab deruxtecan has shown efficacy in patients with previously treated human epidermal growth factor receptor 2 (HER2)-positive advanced or metastatic breast cancer. The efficacy and safety of trastuzumab deruxtecan in patients with no previous therapy for HER2-positive advanced or metastatic breast cancer are unclear.\n\nMethods: We conducted a phase 3 trial involving patients with HER2-positive advanced or metastatic breast cancer and no previous chemotherapy or HER2-directed therapy for metastatic disease. Patients were randomly assigned in a 1:1:1 ratio to receive trastuzumab deruxtecan plus pertuzumab; trastuzumab deruxtecan plus placebo; or a taxane, trastuzumab, and pertuzumab (THP). The primary end point was progression-free survival as assessed by blinded independent central review. Secondary end points included objective response, duration of response, and safety.\n\nResults: For this prespecified interim analysis, data for trastuzumab deruxtecan plus pertuzumab and for THP are reported; data for trastuzumab deruxtecan plus placebo remain blinded until the final analysis of progression-free survival. At the data-cutoff date (February 26, 2025), the median progression-free survival was 40.7 months with trastuzumab deruxtecan plus pertuzumab (383 patients) and 26.9 months with THP (387 patients) (hazard ratio for progression or death, 0.56; 95% confidence interval [CI], 0.44 to 0.71; P<0.00001 [P-value boundary for superiority, 0.00043]). The incidence of a confirmed response was 85.1% with trastuzumab deruxtecan plus pertuzumab and 78.6% with THP (complete responses in 15.1% and 8.5%, respectively), with a median duration of response of 39.2 months and 26.4 months. Safety was consistent with the known profiles of the individual treatments. The incidence of grade 3 or higher adverse events was 63.5% with trastuzumab deruxtecan plus pertuzumab and 62.3% with THP; the most common were neutropenia, hypokalemia, and anemia with trastuzumab deruxtecan plus pertuzumab and neutropenia, leukopenia, and diarrhea with THP. Adjudicated drug-related interstitial lung disease or pneumonitis occurred in 12.1% of patients receiving trastuzumab deruxtecan plus pertuzumab (grade 1 or 2 in 44 patients and grade 5 [death] in 2 patients) and in 1.0% of those receiving THP (all grade 1 or 2).\n\nConclusions: Trastuzumab deruxtecan plus pertuzumab led to a significantly lower risk of progression or death than THP when used as first-line treatment for HER2-positive advanced or metastatic breast cancer, with no new safety signals. (Funded by AstraZeneca and Daiichi Sankyo; DESTINY-Breast09 ClinicalTrials.gov number, NCT04784715.).\n\nIndexed on Europe PMC as PubMed record 41160818 (DOI 10.1056/nejmoa2508668). Its abstract cites the registry id NCT04784715, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2508668", pmid: "41160818", authors: "Tolaney SM, Jiang Z, Zhang Q, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04784715 with the most citations, so it is the natural first reading for anyone following the DESTINY-Breast09 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2508668"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41160818/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41160818"},{"label":"ClinicalTrials.gov NCT04784715","url":"https://clinicaltrials.gov/study/NCT04784715"}], tags: ["europepmc-ingest"], trials: ["destiny-breast09"], journals: ["nejm"] }),
  p({ id: "paper-destiny-breast12-nat-med-2024", name: "Trastuzumab deruxtecan in HER2-positive advanced breast cancer with or without brain metastases: a phase 3b/4 trial", tldr: "Published report from the DESTINY-Breast12 trial registered as NCT04739761, in Nature Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Trastuzumab deruxtecan (T-DXd) intracranial activity has been observed in small or retrospective patient cohorts with human epidermal growth factor receptor 2-positive (HER2 +) advanced/metastatic breast cancer (mBC) and stable or active (untreated/previously treated and progressing) brain metastases (BMs). The phase 3b/4 DESTINY-Breast12 study investigated T-DXd in patients with HER2 + mBC and is, to our knowledge, the largest prospective study of T-DXd in patients with BMs in this setting. Patients (stable/active BMs (n = 263) and no BMs (n = 241)) treated with one or more prior anti-HER2-based regimens received T-DXd (5.4 mg per kg). Primary endpoints were progression-free survival (PFS; BMs cohort) and objective response rate (ORR) per Response Evaluation Criteria in Solid Tumors version 1.1 (non-BMs cohort). Additional endpoints included central nervous system (CNS) PFS, ORR, time to second progression, CNS ORR (BMs cohort), incidence of new symptomatic CNS metastases (non-BMs cohort), time to progression, duration of response, overall survival and safety (both cohorts). No formal hypothesis testing was conducted for this single-arm, open-label study. In the BMs cohort, 12-month PFS was 61.6% (95% confidence interval (CI): 54.9-67.6), and 12-month CNS PFS was 58.9% (95% CI: 51.9-65.3). In the non-BMs cohort, ORR was 62.7% (95% CI: 56.5-68.8). Grade 3 or higher adverse events occurred in 51% (BMs cohort) and 49% (non-BMs cohort) of patients. Investigator-reported interstitial lung disease/pneumonitis occurred in 16% (grade ≥3: 3%) of patients with BMs and 13% (grade ≥3: 1%) of patients without BMs. These data show substantial and durable overall and intracranial activity for T-DXd, supporting its use in previously treated patients with HER2 + mBC irrespective of stable/active baseline BMs. ClinicalTrials.gov identifier: NCT04739761.\n\nIndexed on Europe PMC as PubMed record 39271844 (DOI 10.1038/s41591-024-03261-7). Its abstract cites the registry id NCT04739761, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2024, doi: "10.1038/s41591-024-03261-7", pmid: "39271844", authors: "Harbeck N, Ciruelos E, Jerusalem G, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04739761 with the most citations, so it is the natural first reading for anyone following the DESTINY-Breast12 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2024","url":"https://doi.org/10.1038/s41591-024-03261-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39271844/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39271844"},{"label":"ClinicalTrials.gov NCT04739761","url":"https://clinicaltrials.gov/study/NCT04739761"}], tags: ["europepmc-ingest"], trials: ["destiny-breast12"], journals: ["nature-medicine"] }),
  p({ id: "paper-ember-3-n-engl-j-med-2025", name: "Imlunestrant with or without Abemaciclib in Advanced Breast Cancer", tldr: "Published report from the EMBER-3 trial registered as NCT04975308, in New England Journal of Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Imlunestrant is a next-generation, brain-penetrant, oral selective estrogen-receptor (ER) degrader that delivers continuous ER inhibition, even in cancers with mutations in the gene encoding ERα ( ESR1).\n\nMethods: In a phase 3, open-label trial, we enrolled patients with ER-positive, human epidermal growth factor receptor 2 (HER2)-negative advanced breast cancer that recurred or progressed during or after aromatase inhibitor therapy, administered alone or with a cyclin-dependent kinase 4 and 6 (CDK4/6) inhibitor. Patients were assigned in a 1:1:1 ratio to receive imlunestrant, standard endocrine monotherapy, or imlunestrant-abemaciclib. Primary end points were investigator-assessed progression-free survival with imlunestrant as compared with standard therapy among patients with ESR1 mutations and among all patients and with imlunestrant-abemaciclib as compared with imlunestrant among all patients who had undergone randomization concurrently.\n\nResults: Overall, 874 patients underwent randomization, with 331 assigned to imlunestrant, 330 to standard therapy, and 213 to imlunestrant-abemaciclib. Among 256 patients with ESR1 mutations, the median progression-free survival was 5.5 months with imlunestrant and 3.8 months with standard therapy. The estimated restricted mean survival time at 19.4 months was 7.9 months (95% confidence interval [CI], 6.8 to 9.1) with imlunestrant and 5.4 months (95% CI, 4.6 to 6.2) with standard therapy (difference, 2.6 months; 95% CI, 1.2 to 3.9; P<0.001). In the overall population, the median progression-free survival was 5.6 months with imlunestrant and 5.5 months with standard therapy (hazard ratio for progression or death, 0.87; 95% CI, 0.72 to 1.04; P = 0.12). Among 426 patients in the comparison of imlunestrant-abemaciclib with imlunestrant, the median progression-free survival was 9.4 months and 5.5 months, respectively (hazard ratio, 0.57; 95% CI, 0.44 to 0.73; P<0.001). The incidence of grade 3 or higher adverse events was 17.1% with imlunestrant, 20.7% with standard therapy, and 48.6% with imlunestrant-abemaciclib.\n\nConclusions: Among patients with ER-positive, HER2-negative advanced breast cancer, treatment with imlunestrant led to significantly longer progression-free survival than standard therapy among those with ESR1 mutations but not in the overall population. Imlunestrant-abemaciclib significantly improved progression-free survival as compared with imlunestrant, regardless of ESR1 -mutation status. (Funded by Eli Lilly; EMBER-3 ClinicalTrials.gov number, NCT04975308.).\n\nIndexed on Europe PMC as PubMed record 39660834 (DOI 10.1056/nejmoa2410858). Its abstract cites the registry id NCT04975308, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2410858", pmid: "39660834", authors: "Jhaveri KL, Neven P, Casalnuovo ML, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04975308 with the most citations, so it is the natural first reading for anyone following the EMBER-3 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2410858"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39660834/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39660834"},{"label":"ClinicalTrials.gov NCT04975308","url":"https://clinicaltrials.gov/study/NCT04975308"}], tags: ["europepmc-ingest"], trials: ["ember-3"], journals: ["nejm"] }),
  p({ id: "paper-embraca-n-engl-j-med-2018", name: "Talazoparib in Patients with Advanced Breast Cancer and a Germline BRCA Mutation", tldr: "Published report from the EMBRACA trial registered as NCT01945775, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The poly(adenosine diphosphate-ribose) inhibitor talazoparib has shown antitumor activity in patients with advanced breast cancer and germline mutations in BRCA1 and BRCA2 ( BRCA1/2).\n\nMethods: We conducted a randomized, open-label, phase 3 trial in which patients with advanced breast cancer and a germline BRCA1/2 mutation were assigned, in a 2:1 ratio, to receive talazoparib (1 mg once daily) or standard single-agent therapy of the physician's choice (capecitabine, eribulin, gemcitabine, or vinorelbine in continuous 21-day cycles). The primary end point was progression-free survival, which was assessed by blinded independent central review.\n\nResults: Of the 431 patients who underwent randomization, 287 were assigned to receive talazoparib and 144 were assigned to receive standard therapy. Median progression-free survival was significantly longer in the talazoparib group than in the standard-therapy group (8.6 months vs. 5.6 months; hazard ratio for disease progression or death, 0.54; 95% confidence interval [CI], 0.41 to 0.71; P<0.001). The interim median hazard ratio for death was 0.76 (95% CI, 0.55 to 1.06; P=0.11 [57% of projected events]). The objective response rate was higher in the talazoparib group than in the standard-therapy group (62.6% vs. 27.2%; odds ratio, 5.0; 95% CI, 2.9 to 8.8; P<0.001). Hematologic grade 3-4 adverse events (primarily anemia) occurred in 55% of the patients who received talazoparib and in 38% of the patients who received standard therapy; nonhematologic grade 3 adverse events occurred in 32% and 38% of the patients, respectively. Patient-reported outcomes favored talazoparib; significant overall improvements and significant delays in the time to clinically meaningful deterioration according to both the global health status-quality-of-life and breast symptoms scales were observed.\n\nConclusions: Among patients with advanced breast cancer and a germline BRCA1/2 mutation, single-agent talazoparib provided a significant benefit over standard chemotherapy with respect to progression-free survival. Patient-reported outcomes were superior with talazoparib. (Funded by Medivation [Pfizer]; EMBRACA ClinicalTrials.gov number, NCT01945775.).\n\nIndexed on Europe PMC as PubMed record 30110579 (DOI 10.1056/nejmoa1802905). Its abstract cites the registry id NCT01945775, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1802905", pmid: "30110579", authors: "Litton JK, Rugo HS, Ettl J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01945775 with the most citations, so it is the natural first reading for anyone following the EMBRACA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1802905"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30110579/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30110579"},{"label":"ClinicalTrials.gov NCT01945775","url":"https://clinicaltrials.gov/study/NCT01945775"}], tags: ["europepmc-ingest"], trials: ["embraca"], journals: ["nejm"] }),
  p({ id: "paper-eortc-22922-n-engl-j-med-2015", name: "Internal Mammary and Medial Supraclavicular Irradiation in Breast Cancer", tldr: "Published report from the EORTC 22922 trial registered as NCT00002851, in New England Journal of Medicine (2015), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The effect of internal mammary and medial supraclavicular lymph-node irradiation (regional nodal irradiation) added to whole-breast or thoracic-wall irradiation after surgery on survival among women with early-stage breast cancer is unknown.\n\nMethods: We randomly assigned women who had a centrally or medially located primary tumor, irrespective of axillary involvement, or an externally located tumor with axillary involvement to undergo either whole-breast or thoracic-wall irradiation in addition to regional nodal irradiation (nodal-irradiation group) or whole-breast or thoracic-wall irradiation alone (control group). The primary end point was overall survival. Secondary end points were the rates of disease-free survival, survival free from distant disease, and death from breast cancer.\n\nResults: Between 1996 and 2004, a total of 4004 patients underwent randomization. The majority of patients (76.1%) underwent breast-conserving surgery. After mastectomy, 73.4% of the patients in both groups underwent chest-wall irradiation. Nearly all patients with node-positive disease (99.0%) and 66.3% of patients with node-negative disease received adjuvant systemic treatment. At a median follow-up of 10.9 years, 811 patients had died. At 10 years, overall survival was 82.3% in the nodal-irradiation group and 80.7% in the control group (hazard ratio for death with nodal irradiation, 0.87; 95% confidence interval [CI], 0.76 to 1.00; P=0.06). The rate of disease-free survival was 72.1% in the nodal-irradiation group and 69.1% in the control group (hazard ratio for disease progression or death, 0.89; 95% CI, 0.80 to 1.00; P=0.04), the rate of distant disease-free survival was 78.0% versus 75.0% (hazard ratio, 0.86; 95% CI, 0.76 to 0.98; P=0.02), and breast-cancer mortality was 12.5% versus 14.4% (hazard ratio, 0.82; 95% CI, 0.70 to 0.97; P=0.02). Acute side effects of regional nodal irradiation were modest.\n\nConclusions: In patients with early-stage breast cancer, irradiation of the regional nodes had a marginal effect on overall survival. Disease-free survival and distant disease-free survival were improved, and breast-cancer mortality was reduced. (Funded by Fonds Cancer; ClinicalTrials.gov number, NCT00002851.).\n\nIndexed on Europe PMC as PubMed record 26200978 (DOI 10.1056/nejmoa1415369). Its abstract cites the registry id NCT00002851, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2015, doi: "10.1056/nejmoa1415369", pmid: "26200978", authors: "Poortmans PM, Collette S, Kirkove C, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00002851 with the most citations, so it is the natural first reading for anyone following the EORTC 22922 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2015","url":"https://doi.org/10.1056/nejmoa1415369"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/26200978/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/26200978"},{"label":"ClinicalTrials.gov NCT00002851","url":"https://clinicaltrials.gov/study/NCT00002851"}], tags: ["europepmc-ingest"], trials: ["eortc-22922"], journals: ["nejm"] }),
  p({ id: "paper-eortc-22922-lancet-oncol-2020-update", name: "Internal mammary and medial supraclavicular lymph node chain irradiation in stage I-III breast cancer (EORTC 22922/10925): 15-year results of a randomised, phase 3 trial", tldr: "Later report from the EORTC 22922 trial registered as NCT00002851, in The Lancet Oncology (2020); its title describes an updated or longer-term analysis.", summary: "Background: 10-year results from several studies showed improved disease-free survival and distant metastasis-free survival, reduced breast cancer-related mortality, and variable effects on overall survival with the addition of partial or comprehensive regional lymph node irradiation after surgery in patients with breast cancer. We present the scheduled 15-year analysis of the European Organisation for Research and Treatment of Cancer (EORTC) 22922/10925 trial, which aims to investigate the impact on overall survival of elective internal mammary and medial supraclavicular (IM-MS) irradiation.\n\nMethods: EORTC 22922/10925, a randomised, phase 3 trial done across 46 radiation oncology departments from 13 countries, included women up to 75 years of age with unilateral, histologically confirmed, stage I-III breast adenocarcinoma with involved axillary nodes or a central or medially located primary tumour. Surgery consisted of mastectomy or breast-conserving surgery and axillary staging. Patients were randomly assigned (1:1) centrally using minimisation to receive IM-MS irradiation at 50 Gy in 25 fractions (IM-MS irradiation group) or no IM-MS irradiation (control group). Stratification was done for institution, menopausal status, site of the primary tumour within the breast, type of breast and axillary surgery, and pathological T and N stage. Patients and investigators were not masked to treatment allocation. The primary endpoint was overall survival analysed according to the intention-to-treat principle. Secondary endpoints were disease-free survival, distant metastasis-free survival, breast cancer mortality, any breast cancer recurrence, and cause of death. Follow-up is ongoing for 20 years after randomisation. This study is registered with ClinicalTrials.gov, NCT00002851.\n\nFindings: Between Aug 5, 1996, and Jan 13, 2004, we enrolled 4004 patients, of whom 2002 were randomly assigned to the IM-MS irradiation group and 2002 to the no IM-MS irradiation group. At a median follow-up of 15·7 years (IQR 14·0-17·6), 554 (27·7%) patients in the IM-MS irradiation group and 569 (28·4%) patients in the control group had died. Overall survival was 73·1% (95% CI 71·0-75·2) in the IM-MS irradiation group and 70·9% (68·6-72·9) in the control group (HR 0·95 [95% CI 0·84-1·06], p=0·36). Any breast cancer recurrence (24·5% [95% CI 22·5-26·6] vs 27·1% [25·1-29·2]; HR 0·87 [95% CI 0·77-0·98], p=0·024) and breast cancer mortality (16·0% [14·3-17·7] vs 19·8% [18·0-21·7]; 0·81 [0·70-0·94], p=0·0055) were lower in the IM-MS irradiation group than in the control group. No significant differences in the IM-MS irradiation group versus the control group were seen for disease-free survival (60·8% [95% CI 58·4-63·2] vs 59·9% [57·5-62·2]; HR 0·93 [95% CI 0·84-1·03], p=0·18), or distant metastasis-free survival (70·0% [67·7-72·2] vs 68·2% [65·9-70·3]; 0·93 [0·83-1·04], p=0·18). Causes of death between groups were similar.\n\nInterpretation: The 15-year results show a significant reduction of breast cancer mortality and any breast cancer recurrence by IM-MS irradiation in stage I-III breast cancer. However, this is not converted to improved overall survival.\n\nFunding: US National Cancer Institute, Ligue Nationale contre le Cancer, and KWF Kankerbestrijding.\n\nIndexed on Europe PMC as PubMed record 33152277 (DOI 10.1016/s1470-2045(20)30472-1). Its abstract cites the registry id NCT00002851, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2020, doi: "10.1016/s1470-2045(20)30472-1", pmid: "33152277", authors: "Poortmans PM, Weltens C, Fortpied C, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the EORTC 22922 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2020","url":"https://doi.org/10.1016/s1470-2045(20)30472-1"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33152277/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33152277"},{"label":"ClinicalTrials.gov NCT00002851","url":"https://clinicaltrials.gov/study/NCT00002851"}], tags: ["europepmc-ingest"], trials: ["eortc-22922"], journals: ["lancet-oncology"] }),
  p({ id: "paper-geparsixto-lancet-oncol-2014", name: "Neoadjuvant carboplatin in patients with triple-negative and HER2-positive early breast cancer (GeparSixto; GBG 66): a randomised phase 2 trial", tldr: "Published report from the GeparSixto trial registered as NCT01426880, in The Lancet Oncology (2014), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Preclinical data suggest that triple-negative breast cancers are sensitive to interstrand crosslinking agents, and that synergy may exist for the combination of a taxane, trastuzumab, and a platinum salt for HER2-positive breast cancer. We therefore aimed to assess the efficacy of the addition of carboplatin to neoadjuvant therapy for triple-negative and HER2-positive breast cancer.\n\nMethods: Patients with previously untreated, non-metastatic, stage II-III, triple-negative breast cancer and HER2-positive breast cancer were enrolled. Patients were treated for 18 weeks with paclitaxel (80 mg/m(2) once a week) and non-pegylated liposomal doxorubicin (20 mg/m(2) once a week). Patients with triple-negative breast cancer received simultaneous bevacizumab (15 mg/kg intravenously every 3 weeks). Patients with HER2-positive disease received simultaneous trastuzumab (8 mg/kg initial dose with subsequent doses of 6 mg/kg intravenously every 3 weeks) and lapatinib (750 mg daily). Patients were randomly assigned in a 1:1 ratio with dynamic allocation and minimisation, stratified by biological subtype and Ki-67 level to receive, at the same time as the backbone regimens, either carboplatin (AUC 1·5 [2·0 for the first 329 patients] once a week) or no carboplatin. The primary endpoint the proportion of patients who achieved a pathological complete response (defined as ypT0 ypN0), analysed for all patients who started treatment; a p value of less than 0·2 was deemed significant for the primary endpoint. This trial is registered with ClinicalTrials.gov, number NCT01426880.\n\nFindings: 296 patients were randomly assigned to receive carboplatin and 299 to no additional carboplatin, of whom 295 and 293 started treatment, respectively. In this final analysis, 129 patients (43·7%, 95% CI 38·1-49·4) in the carboplatin group achieved a pathological complete response, compared with 108 patients (36·9%, 31·3-42·4) without carboplatin (odds ratio 1·33, 95% CI 0·96-1·85; p=0·107). Of the patients with triple-negative breast cancer, 84 (53·2%, 54·4-60·9) of 158 patients achieved a pathological complete response with carboplatin, compared with 58 (36·9%, 29·4-44·5) of 157 without (p=0·005). Of the patients with HER2-positive tumours, 45 (32·8%, 25·0-40·7) of 137 patients achieved a pathological complete response with carboplatin compared with 50 (36·8%, 28·7-44·9) of 136 without (p=0·581; test for interaction p=0·015). Haematological and non-haematological toxic effects that were significantly more common in the carboplatin group than in the no-carboplatin group included grade 3 or 4 neutropenia (192 [65%] vs 79 [27%]), grade 3 or 4 anaemia (45 [15%] vs one [<1%]), grade 3 or 4 thrombocytopenia (42 [14%] vs one [<1%]), and grade 3 or 4 diarrhoea (51 [17%] vs 32 [11%]); carboplatin was more often associated with dose discontinuations (141 [48%] with carboplatin and 114 [39%] without carboplatin; p=0·031). The frequency of grade 3 or 4 haematological events decreased from 82% (n=135) to 70% (n=92) and grade 3 or 4 non-haematological events from 78% (n=128) to 59% (n=77) in the carboplatin arm when the dose of carboplatin was reduced from AUC 2·0 to 1·5.\n\nInterpretation: The addition of neoadjuvant carboplatin to a regimen of a taxane, an anthracycline, and targeted therapy significantly increases the proportion of patients achieving a pathological complete response. This regimen seems to increase responses in patients with triple-negative breast cancer, but not in those with HER2-positive breast cancer.\n\nFunding: GlaxoSmithKline, Roche, and Teva.\n\nIndexed on Europe PMC as PubMed record 24794243 (DOI 10.1016/s1470-2045(14)70160-3). Its abstract cites the registry id NCT01426880, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2014, doi: "10.1016/s1470-2045(14)70160-3", pmid: "24794243", authors: "von Minckwitz G, Schneeweiss A, Loibl S, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01426880 with the most citations, so it is the natural first reading for anyone following the GeparSixto trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2014","url":"https://doi.org/10.1016/s1470-2045(14)70160-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/24794243/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/24794243"},{"label":"ClinicalTrials.gov NCT01426880","url":"https://clinicaltrials.gov/study/NCT01426880"}], tags: ["europepmc-ingest"], trials: ["geparsixto"], journals: ["lancet-oncology"] }),
  p({ id: "paper-her2climb-02-ann-oncol-2026", name: "Tucatinib and trastuzumab emtansine for patients with previously treated HER2-positive locally advanced and metastatic breast cancer: primary analysis of the randomized phase III trial HER2CLIMB-02", tldr: "Published report from the HER2CLIMB-02 trial registered as NCT03975647, in Annals of Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Trastuzumab emtansine (T-DM1) is a standard treatment option in patients with previously treated human epidermal growth factor receptor 2 (HER2)-positive locally advanced or metastatic breast cancer (LA/MBC). Here, we report the efficacy and safety of tucatinib in combination with T-DM1 compared with T-DM1 alone from the phase III HER2CLIMB-02 study (NCT03975647).\n\nPatients and methods: Eligible patients had HER2-positive LA/MBC that had been previously treated with trastuzumab and a taxane in any setting; these included patients with brain metastases (BMs). Patients were randomly assigned 1: 1 to receive T-DM1 (3.6 mg/kg intravenously every 21 days) combined with either tucatinib (300 mg orally twice daily) in the tucatinib arm or placebo (orally twice daily) in the control arm.\n\nResults: In total, 463 patients were randomly assigned. After a median follow-up duration of 24.4 months, the median progression-free survival (PFS) was 9.5 months in the tucatinib arm and 7.4 months in the control arm [hazard ratio (HR) 0.76, 95% confidence interval (CI) 0.61-0.95, P = 0.0163]. A PFS benefit was observed across all prespecified subgroups, including in patients with BMs. Interim overall survival analysis results were immature. The median OS was not reached in the tucatinib arm and was 38.0 months in the control arm (HR 1.23, 95% CI 0.87-1.74). The incidences of treatment-emergent adverse events (TEAEs) associated with any treatment discontinuation and of grade ≥3 TEAEs were higher in the tucatinib arm than in the control arm (22.1% versus 11.6% and 68.8% versus 41.2%, respectively). The most common grade ≥3 TEAEs in the tucatinib arm were elevated alanine aminotransferase (16.5%) and aspartate aminotransferase levels (16.5%) (versus 2.6% for both in the control arm).\n\nConclusion: The addition of tucatinib to T-DM1 improved PFS in patients with previously treated HER2-positive LA/MBC, including patients with BMs, and exhibited a manageable safety profile.\n\nIndexed on Europe PMC as PubMed record 41260264 (DOI 10.1016/j.annonc.2025.11.005). Its abstract cites the registry id NCT03975647, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2026, doi: "10.1016/j.annonc.2025.11.005", pmid: "41260264", authors: "Hurvitz SA, Loi S, O'Shaughnessy J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03975647 with the most citations, so it is the natural first reading for anyone following the HER2CLIMB-02 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2026","url":"https://doi.org/10.1016/j.annonc.2025.11.005"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41260264/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41260264"},{"label":"ClinicalTrials.gov NCT03975647","url":"https://clinicaltrials.gov/study/NCT03975647"}], tags: ["europepmc-ingest"], trials: ["her2climb-02"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-her2climb-05-j-clin-oncol-2026", name: "HER2CLIMB-05: A Phase III Study of Tucatinib Versus Placebo in Combination With Trastuzumab and Pertuzumab as First-Line Maintenance Therapy for HER2+ Metastatic Breast Cancer", tldr: "Published report from the HER2CLIMB-05 trial registered as NCT05132582, in Journal of Clinical Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: The HER2CLIMB-05 study (ClinicalTrials.gov identifier: NCT05132582) is investigating the efficacy and safety of adding tucatinib to trastuzumab and pertuzumab as first-line (1L) maintenance therapy in patients with human epidermal growth factor receptor 2-positive (HER2+) metastatic breast cancer (MBC).\n\nMethods: Patients with centrally confirmed HER2+ MBC without evidence of progression post induction therapy and no or asymptomatic brain metastases (BM) were enrolled. Patients were randomly assigned 1:1 to tucatinib (300 mg) or placebo twice a day combined with trastuzumab/pertuzumab. The primary end point is investigator-assessed progression-free survival (PFS); secondary end points include overall survival (OS), PFS per blinded independent central review, CNS-PFS, and safety.\n\nResults: Between March 2022 and July 2024, 654 patients were randomly assigned to tucatinib (n = 326) and placebo (n = 328) arms. All patients were female (median age, 54 years), 69.3% had de novo MBC, 52.6% were hormone receptor-positive, and 12.4% had presence/history of baseline BM. In this primary analysis, PFS was statistically significantly improved with addition of tucatinib versus placebo (hazard ratio, 0.641 [95% CI, 0.514 to 0.799]; P <.0001; median PFS: 24.9 v 16.3 months); a PFS benefit was seen regardless of the presence/absence of BM or hormone receptor status. OS data remain immature. The most common treatment-emergent adverse events (TEAEs) in the tucatinib arm were diarrhea (72.7%), nausea (33.1%), and elevated liver enzymes (ALT: 28.2%; AST: 25.8%), of which 6.1%, 0.9%, 13.5%, and 7.1%, respectively, were grade ≥3. In the tucatinib arm, 13.5% discontinued tucatinib because of TEAEs.\n\nConclusion: Tucatinib addition to trastuzumab and pertuzumab demonstrated improvement in PFS with no new safety signals identified and may be an option for 1L maintenance therapy in patients with HER2+ MBC.\n\nIndexed on Europe PMC as PubMed record 41369677 (DOI 10.1200/jco-25-02600). Its abstract cites the registry id NCT05132582, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2026, doi: "10.1200/jco-25-02600", pmid: "41369677", authors: "Dieras V, Curigliano G, Martin M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05132582 with the most citations, so it is the natural first reading for anyone following the HER2CLIMB-05 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2026","url":"https://doi.org/10.1200/jco-25-02600"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41369677/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41369677"},{"label":"ClinicalTrials.gov NCT05132582","url":"https://clinicaltrials.gov/study/NCT05132582"}], tags: ["europepmc-ingest"], trials: ["her2climb-05"], journals: ["jco"] }),
  p({ id: "paper-hera-b31-n9831-n-engl-j-med-2005", name: "Trastuzumab after adjuvant chemotherapy in HER2-positive breast cancer", tldr: "Published report from the HERA trial registered as NCT00045032, in New England Journal of Medicine (2005), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Trastuzumab, a recombinant monoclonal antibody against HER2, has clinical activity in advanced breast cancer that overexpresses HER2. We investigated its efficacy and safety after excision of early-stage breast cancer and completion of chemotherapy.\n\nMethods: This international, multicenter, randomized trial compared one or two years of trastuzumab given every three weeks with observation in patients with HER2-positive and either node-negative or node-positive breast cancer who had completed locoregional therapy and at least four cycles of neoadjuvant or adjuvant chemotherapy.\n\nResults: Data were available for 1694 women randomly assigned to two years of treatment with trastuzumab, 1694 women assigned to one year of trastuzumab, and 1693 women assigned to observation. We report here the results only of treatment with trastuzumab for one year or observation. At the first planned interim analysis (median follow-up of one year), 347 events (recurrence of breast cancer, contralateral breast cancer, second nonbreast malignant disease, or death) were observed: 127 events in the trastuzumab group and 220 in the observation group. The unadjusted hazard ratio for an event in the trastuzumab group, as compared with the observation group, was 0.54 (95 percent confidence interval, 0.43 to 0.67; P<0.0001 by the log-rank test, crossing the interim analysis boundary), representing an absolute benefit in terms of disease-free survival at two years of 8.4 percentage points. Overall survival in the two groups was not significantly different (29 deaths with trastuzumab vs. 37 with observation). Severe cardiotoxicity developed in 0.5 percent of the women who were treated with trastuzumab.\n\nConclusions: One year of treatment with trastuzumab after adjuvant chemotherapy significantly improves disease-free survival among women with HER2-positive breast cancer. (ClinicalTrials.gov number, NCT00045032.)\n\nIndexed on Europe PMC as PubMed record 16236737 (DOI 10.1056/nejmoa052306). Its abstract cites the registry id NCT00045032, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2005, doi: "10.1056/nejmoa052306", pmid: "16236737", authors: "Piccart-Gebhart MJ, Procter M, Leyland-Jones B, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00045032 with the most citations, so it is the natural first reading for anyone following the HERA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2005","url":"https://doi.org/10.1056/nejmoa052306"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/16236737/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/16236737"},{"label":"ClinicalTrials.gov NCT00045032","url":"https://clinicaltrials.gov/study/NCT00045032"}], tags: ["europepmc-ingest"], trials: ["hera-b31-n9831"], journals: ["nejm"] }),
  p({ id: "paper-hera-b31-n9831-lancet-2017-update", name: "11 years' follow-up of trastuzumab after adjuvant chemotherapy in HER2-positive early breast cancer: final analysis of the HERceptin Adjuvant (HERA) trial", tldr: "Later report from the HERA trial registered as NCT00045032, in The Lancet (2017); its title describes an updated or longer-term analysis.", summary: "Background: Clinical trials have shown that trastuzumab, a recombinant monoclonal antibody against HER2 receptor, significantly improves overall survival and disease-free survival in women with HER2-positive early breast cancer, but long-term follow-up data are needed. We report the results of comparing observation with two durations of trastuzumab treatment at a median follow-up of 11 years, for patients enrolled in the HERA (HERceptin Adjuvant) trial.\n\nMethods: HERA (BIG 1-01) is an international, multicentre, open-label, phase 3 randomised trial of 5102 women with HER2-positive early breast cancer, who were enrolled from hospitals in 39 countries between Dec 7, 2001, and June 20, 2005. After completion of all primary therapy (including, surgery, chemotherapy, and radiotherapy as indicated), patients were randomly assigned (1:1:1) to receive trastuzumab for 1 year (once at 8 mg/kg of bodyweight intravenously, then 6 mg/kg once every 3 weeks) or for 2 years (with the same dose schedule), or to the observation group. Primary endpoint is disease-free survival, and analyses are in the intention-to-treat population. Hazard ratios (HRs) were estimated from Cox models, and survival curves were estimated by the Kaplan-Meier method. Comparison of 2 years versus 1 year of trastuzumab is based on 366-day landmark analyses. This study is registered with ClinicalTrials.gov (NCT00045032).\n\nFindings: Of the 5102 women randomly assigned in the HERA trial, three patients had no evidence of having provided written informed consent to participate. We followed up the intention-to-treat population of 5099 patients (1697 in observation, 1702 in 1-year trastuzumab, and 1700 in 2-years trastuzumab groups). After a median follow-up of 11 years (IQR 10·09-11·53), random assignment to 1 year of trastuzumab significantly reduced the risk of a disease-free survival event (HR 0·76, 95% CI 0·68-0·86) and death (0·74, 0·64-0·86) compared with observation. 2 years of adjuvant trastuzumab did not improve disease free-survival outcomes compared with 1 year of this drug (HR 1·02, 95% CI 0·89-1·17). Estimates of 10-year disease-free survival were 63% for observation, 69% for 1 year of trastuzumab, and 69% for 2 years of trastuzumab. 884 (52%) patients assigned to the observation group selectively crossed over to receive trastuzumab. Cardiac toxicity remained low in all groups and occurred mostly during the treatment phase. The incidence of secondary cardiac endpoints was 122 (7·3%) in the 2-years trastuzumab group, 74 (4·4%) in the 1-year trastuzumab group, and 15 (0·9%) in the observation group.\n\nInterpretation: 1 year of adjuvant trastuzumab after chemotherapy for patients with HER2-positive early breast cancer significantly improves long-term disease-free survival, compared with observation. 2 years of trastuzumab had no additional benefit.\n\nFunding: F Hoffmann-La Roche (Roche).\n\nIndexed on Europe PMC as PubMed record 28215665 (DOI 10.1016/s0140-6736(16)32616-2). Its abstract cites the registry id NCT00045032, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2017, doi: "10.1016/s0140-6736(16)32616-2", pmid: "28215665", authors: "Cameron D, Piccart-Gebhart MJ, Gelber RD, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the HERA trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet 2017","url":"https://doi.org/10.1016/s0140-6736(16)32616-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28215665/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28215665"},{"label":"ClinicalTrials.gov NCT00045032","url":"https://clinicaltrials.gov/study/NCT00045032"}], tags: ["europepmc-ingest"], trials: ["hera-b31-n9831"], journals: ["lancet"] }),
  p({ id: "paper-horizon-breast01-lancet-oncol-2026", name: "Trastuzumab rezetecan versus pyrotinib plus capecitabine for patients with HER2-positive metastatic breast cancer (HORIZON-Breast01): interim analysis of a multicentre, open-label, randomised, controlled, phase 3 trial", tldr: "Published report from the HORIZON-Breast01 trial registered as NCT05424835, in The Lancet Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Trastuzumab rezetecan has shown antitumour activity in a phase 1 trial. Pyrotinib plus capecitabine is the current standard treatment for patients with HER2-positive advanced or metastatic breast cancer after trastuzumab and chemotherapy (taxane or anthracycline). We aimed to evaluate the efficacy and safety of trastuzumab rezetecan versus pyrotinib plus capecitabine in this patient population.\n\nMethods: This interim analysis of a multicentre, open-label, randomised, controlled, phase 3 trial was conducted at 50 hospitals in China. Eligible patients were aged 18-75 years with histologically confirmed HER2-positive unresectable or metastatic breast cancer; previously received a taxane and trastuzumab at the advanced stage or had disease progression within 12 months after (neo)adjuvant treatment with an anti-HER2 monoclonal antibody and taxane-based regimen; had measurable lesions; and an Eastern Cooperative Oncology Group performance status of 0 or 1. Patients were randomly assigned (1:1; stratified by hormone receptor status and previous lines of chemotherapy for metastatic disease), using permuted blocks to intravenous trastuzumab rezetecan (4·8 mg/kg) on day 1 of each 21-day cycle or oral pyrotinib 400 mg once per day continuously plus oral capecitabine 1000 mg/m 2 twice per day on days 1-14 of each 21-day cycle. Protocol amendments led to a temporary modification (between Nov 29, 2022, and July 12, 2023) of trastuzumab rezetecan dose to 6·4 mg/kg; primary evaluation focuses on the 4·8 mg/kg group. The primary endpoint was progression-free survival per blinded independent central review in the modified intention-to-treat population 1 (defined as all patients randomly assigned to the trastuzumab rezetecan 4·8 mg/kg or control groups). Results presented here are from a prespecified interim analysis. This study was registered with ClinicalTrials.gov, NCT05424835 (active, not recruiting).\n\nFindings: From Aug 4, 2022, to Aug 9, 2024, 414 patients with HER2-positive metastatic breast cancer were assessed for eligibility, 127 were ineligible and 287 were randomly assigned to trastuzumab rezetecan (n=142) or pyrotinib plus capecitabine (control group; n=145) in the modified intention-to-treat population 1. All 287 patients were female and the median age was 55·0 years (IQR 49·0-60·0). 268 (93%) patients self-reported as Han Chinese and 19 (7%) as other Chinese ethnicity. At data cutoff of the interim analysis on June 30, 2025, after a median follow-up of 15·0 months (IQR 12·9-18·5) for the trastuzumab rezetecan group versus 13·9 months (11·4-17·8) for the control group, 124 progression-free survival events had occurred (37 [26%] vs 87 [60%]). The median progression-free survival was 30·6 months (95% CI 16·8-not reached [NR]) with trastuzumab rezetecan and 8·3 months (6·9-11·0) with pyrotinib plus capecitabine (HR 0·22 [0·15-0·34]; p<0·0001). The 12-month progression-free survival rate was 84·7% (77·0-90·0) in the trastuzumab rezetecan group versus 35·5% (26·8-44·2) in the control group. The most common (grade ≥3) treatment-related adverse events were decreased neutrophil count (77 [54%] with trastuzumab rezetecan vs 13 [9%] with the control), decreased white blood cell count (29 [20%] vs four [3%]), and decreased platelet count (15 [11%] vs two [1%]); whereas treatment-related serious adverse events occurred in 19 (13%) versus 17 (12%). Two adverse events led to death (one [1%] septic shock unrelated to trastuzumab rezetecan treatment and one [1%] unknown reason related to pyrotinib plus capecitabine treatment). Interstitial lung disease occurred in four (3%) patients in the trastuzumab rezetecan group.\n\nInterpretation: Trastuzumab rezetecan improved progression-free survival versus pyrotinib plus capecitabine and showed a distinct safety profile in patients with HER2-positive breast cancer, presenting as a potential new treatment option.\n\nFunding: Jiangsu Hengrui Pharmaceuticals.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 42385760 (DOI 10.1016/s1470-2045(26)00193-2). Its abstract cites the registry id NCT05424835, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2026, doi: "10.1016/s1470-2045(26)00193-2", pmid: "42385760", authors: "Yao H, Zhang Q, Li H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05424835 with the most citations, so it is the natural first reading for anyone following the HORIZON-Breast01 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2026","url":"https://doi.org/10.1016/s1470-2045(26)00193-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42385760/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42385760"},{"label":"ClinicalTrials.gov NCT05424835","url":"https://clinicaltrials.gov/study/NCT05424835"}], tags: ["europepmc-ingest"], trials: ["horizon-breast01"], journals: ["lancet-oncology"] }),
  p({ id: "paper-impassion031-lancet-2020", name: "Neoadjuvant atezolizumab in combination with sequential nab-paclitaxel and anthracycline-based chemotherapy versus placebo and chemotherapy in patients with early-stage triple-negative breast cancer (IMpassion031): a randomised, double-blind, phase 3 trial", tldr: "Published report from the IMpassion031 trial registered as NCT03197935, in The Lancet (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Preferred neoadjuvant regimens for early-stage triple-negative breast cancer (TNBC) include anthracycline-cyclophosphamide and taxane-based chemotherapy. IMpassion031 compared efficacy and safety of atezolizumab versus placebo combined with nab-paclitaxel followed by doxorubicin plus cyclophosphamide as neoadjuvant treatment for early-stage TNBC.\n\nMethods: This double-blind, randomised, phase 3 study enrolled patients in 75 academic and community sites in 13 countries. Patients aged 18 years or older with previously untreated stage II-III histologically documented TNBC were randomly assigned (1:1) to receive chemotherapy plus intravenous atezolizumab at 840 mg or placebo every 2 weeks. Chemotherapy comprised of nab-paclitaxel at 125 mg/m 2 every week for 12 weeks followed by doxorubicin at 60 mg/m 2 and cyclophosphamide at 600 mg/m 2 every 2 weeks for 8 weeks, which was then followed by surgery. Stratification was by clinical breast cancer stage and programmed cell death ligand 1 (PD-L1) status. Co-primary endpoints were pathological complete response in all-randomised (ie, all randomly assigned patients in the intention-to-treat population) and PD-L1-positive (ie, patients with PD-L1-expressing tumour infiltrating immune cells covering ≥1% of tumour area) populations. This study is registered with ClinicalTrials.gov (NCT03197935), Eudra (CT2016-004734-22), and the Japan Pharmaceutical Information Center (JapicCTI-173630), and is ongoing.\n\nFindings: Between July 7, 2017, and Sept 24, 2019, 455 patients were recruited and assessed for eligibility. Of the 333 eligible patients, 165 were randomly assigned to receive atezolizumab plus chemotherapy and 168 to placebo plus chemotherapy. At data cutoff (April 3, 2020), median follow-up was 20·6 months (IQR 8·7-24·9) in the atezolizumab plus chemotherapy group and 19·8 months (8·1-24·5) in the placebo plus chemotherapy group. Pathological complete response was documented in 95 (58%, 95% CI 50-65) patients in the atezolizumab plus chemotherapy group and 69 (41%, 34-49) patients in the placebo plus chemotherapy group (rate difference 17%, 95% CI 6-27; one-sided p=0·0044 [significance boundary 0·0184]). In the PD-L1-positive population, pathological complete response was documented in 53 (69%, 95% CI 57-79) of 77 patients in the atezolizumab plus chemotherapy group versus 37 (49%, 38-61) of 75 patients in the placebo plus chemotherapy group (rate difference 20%, 95% CI 4-35; one-sided p=0·021 [significance boundary 0·0184]). In the neoadjuvant phase, grade 3-4 adverse events were balanced and treatment-related serious adverse events occurred in 37 (23%) and 26 (16%) patients, with one patient per group experiencing an unrelated grade 5 adverse event (traffic accident in the atezolizumab plus chemotherapy group and pneumonia in the placebo plus chemotherapy group).\n\nInterpretation: In patients with early-stage TNBC, neoadjuvant treatment with atezolizumab in combination with nab-paclitaxel and anthracycline-based chemotherapy significantly improved pathological complete response rates with an acceptable safety profile.\n\nFunding: F Hoffmann-La Roche/Genentech.\n\nIndexed on Europe PMC as PubMed record 32966830 (DOI 10.1016/s0140-6736(20)31953-x). Its abstract cites the registry id NCT03197935, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2020, doi: "10.1016/s0140-6736(20)31953-x", pmid: "32966830", authors: "Mittendorf EA, Zhang H, Barrios CH, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03197935 with the most citations, so it is the natural first reading for anyone following the IMpassion031 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2020","url":"https://doi.org/10.1016/s0140-6736(20)31953-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32966830/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32966830"},{"label":"ClinicalTrials.gov NCT03197935","url":"https://clinicaltrials.gov/study/NCT03197935"}], tags: ["europepmc-ingest"], trials: ["impassion031"], journals: ["lancet"] }),
  p({ id: "paper-impassion031-nat-med-2025-update", name: "Peri-operative atezolizumab in early-stage triple-negative breast cancer: final results and ctDNA analyses from the randomized phase 3 IMpassion031 trial", tldr: "Later report from the IMpassion031 trial registered as NCT03197935, in Nature Medicine (2025); its title describes an updated or longer-term analysis.", summary: "Previously published results demonstrated that the randomized phase 3 IMpassion031 trial met its primary objective: adding atezolizumab to neoadjuvant chemotherapy significantly improved pathologic complete response (pCR) rate in patients with stage II/III triple-negative breast cancer (TNBC). Here we report the prespecified final analysis of the secondary endpoints with 3 years' follow-up, together with exploratory analyses of circulating tumor (ct)DNA. Patients with previously untreated stage II/III TNBC enrolled in 75 academic and community sites in 13 countries were randomized 1:1 to receive neoadjuvant chemotherapy with either peri-operative atezolizumab (n = 165) or preoperative placebo (n = 168). Descriptive secondary endpoints included event-free, disease-free and overall survival. Long-term outcomes favored the atezolizumab group (event-free survival hazard ratio (HR), 0.76; 95% confidence interval (CI), 0.47-1.21; disease-free survival HR, 0.76; 95% CI, 0.44-1.30; overall survival HR, 0.56; 95% CI, 0.30-1.04). Among patients without pCR, 14 of 70 (20%) atezolizumab-treated and 33 of 99 (33%) placebo-treated patients received additional adjuvant therapy, frequently capecitabine. In exploratory biomarker analyses, patients with baseline ctDNA-negative status (6%) had excellent long-term outcomes. Most patients (87%) had cleared ctDNA at surgery. ctDNA-positive status at surgery identified a subset of non-pCR patients with poorest prognosis. Long-term safety was consistent with primary results. These data show that adding atezolizumab to chemotherapy for stage II/III TNBC is associated with favorable long-term outcomes, and ctDNA dynamics provide prognostic value beyond pCR. ClinicalTrials.gov identifier: NCT03197935.\n\nIndexed on Europe PMC as PubMed record 40467898 (DOI 10.1038/s41591-025-03725-4). Its abstract cites the registry id NCT03197935, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-03725-4", pmid: "40467898", authors: "Mittendorf EA, Assaf ZJ, Harbeck N, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the IMpassion031 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-03725-4"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40467898/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40467898"},{"label":"ClinicalTrials.gov NCT03197935","url":"https://clinicaltrials.gov/study/NCT03197935"}], tags: ["europepmc-ingest"], trials: ["impassion031"], journals: ["nature-medicine"] }),
  p({ id: "paper-impassion130-n-engl-j-med-2018", name: "Atezolizumab and Nab-Paclitaxel in Advanced Triple-Negative Breast Cancer", tldr: "Published report from the IMpassion130 trial registered as NCT02425891, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Unresectable locally advanced or metastatic triple-negative (hormone-receptor-negative and human epidermal growth factor receptor 2 [HER2]-negative) breast cancer is an aggressive disease with poor outcomes. Nanoparticle albumin-bound (nab)-paclitaxel may enhance the anticancer activity of atezolizumab.\n\nMethods: In this phase 3 trial, we randomly assigned (in a 1:1 ratio) patients with untreated metastatic triple-negative breast cancer to receive atezolizumab plus nab-paclitaxel or placebo plus nab-paclitaxel; patients continued the intervention until disease progression or an unacceptable level of toxic effects occurred. Stratification factors were the receipt or nonreceipt of neoadjuvant or adjuvant taxane therapy, the presence or absence of liver metastases at baseline, and programmed death ligand 1 (PD-L1) expression at baseline (positive vs. negative). The two primary end points were progression-free survival (in the intention-to-treat population and PD-L1-positive subgroup) and overall survival (tested in the intention-to-treat population; if the finding was significant, then it would be tested in the PD-L1-positive subgroup).\n\nResults: Each group included 451 patients (median follow-up, 12.9 months). In the intention-to-treat analysis, the median progression-free survival was 7.2 months with atezolizumab plus nab-paclitaxel, as compared with 5.5 months with placebo plus nab-paclitaxel (hazard ratio for progression or death, 0.80; 95% confidence interval [CI], 0.69 to 0.92; P=0.002); among patients with PD-L1-positive tumors, the median progression-free survival was 7.5 months and 5.0 months, respectively (hazard ratio, 0.62; 95% CI, 0.49 to 0.78; P<0.001). In the intention-to-treat analysis, the median overall survival was 21.3 months with atezolizumab plus nab-paclitaxel and 17.6 months with placebo plus nab-paclitaxel (hazard ratio for death, 0.84; 95% CI, 0.69 to 1.02; P=0.08); among patients with PD-L1-positive tumors, the median overall survival was 25.0 months and 15.5 months, respectively (hazard ratio, 0.62; 95% CI, 0.45 to 0.86). No new adverse effects were identified. Adverse events that led to the discontinuation of any agent occurred in 15.9% of the patients who received atezolizumab plus nab-paclitaxel and in 8.2% of those who received placebo plus nab-paclitaxel.\n\nConclusions: Atezolizumab plus nab-paclitaxel prolonged progression-free survival among patients with metastatic triple-negative breast cancer in both the intention-to-treat population and the PD-L1-positive subgroup. Adverse events were consistent with the known safety profiles of each agent. (Funded by F. Hoffmann-La Roche/Genentech; IMpassion130 ClinicalTrials.gov number, NCT02425891.).\n\nIndexed on Europe PMC as PubMed record 30345906 (DOI 10.1056/nejmoa1809615). Its abstract cites the registry id NCT02425891, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1809615", pmid: "30345906", authors: "Schmid P, Adams S, Rugo HS, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02425891 with the most citations, so it is the natural first reading for anyone following the IMpassion130 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1809615"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30345906/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30345906"},{"label":"ClinicalTrials.gov NCT02425891","url":"https://clinicaltrials.gov/study/NCT02425891"}], tags: ["europepmc-ingest"], trials: ["impassion130"], journals: ["nejm"] }),
  p({ id: "paper-impassion130-lancet-oncol-2020-update", name: "Atezolizumab plus nab-paclitaxel as first-line treatment for unresectable, locally advanced or metastatic triple-negative breast cancer (IMpassion130): updated efficacy results from a randomised, double-blind, placebo-controlled, phase 3 trial", tldr: "Later report from the IMpassion130 trial registered as NCT02425891, in The Lancet Oncology (2020); its title describes an updated or longer-term analysis.", summary: "Background: Immunotherapy in combination with chemotherapy has shown promising efficacy across many different tumour types. We report the prespecified second interim overall survival analysis of the phase 3 IMpassion130 study assessing the efficacy and safety of atezolizumab plus nab-paclitaxel in patients with unresectable, locally advanced or metastatic triple-negative breast cancer.\n\nMethods: In this randomised, placebo-controlled, double-blind, phase 3 trial, done in 246 academic centres and community oncology practices in 41 countries, patients aged 18 years or older, with previously untreated, histologically documented, locally advanced or metastatic triple-negative breast cancer, and Eastern Cooperative Oncology Group performance status of 0 or 1 were eligible. Patients were randomly assigned (1:1) using a permuted block method (block size of four) and an interactive voice-web response system. Randomisation was stratified by previous taxane use, liver metastases, and PD-L1 expression on tumour-infiltrating immune cells. Patients received atezolizumab 840 mg or matching placebo intravenously on day 1 and day 15 of every 28-day cycle and nab-paclitaxel 100 mg/m 2 of body surface area intravenously on days 1, 8, and 15 until progression or unacceptable toxicity. Investigators, patients, and the funder were masked to treatment assignment. Coprimary endpoints were investigator-assessed progression-free survival per Response Evaluation Criteria in Solid Tumors version 1.1 and overall survival, assessed in the intention-to-treat population and in patients with PD-L1 immune cell-positive tumours (tumours with ≥1% PD-L1 expression). The final progression-free survival results were previously reported at the first interim overall survival analysis. The prespecified statistical testing hierarchy meant that overall survival in the subgroup of PD-L1 immune cell-positive patients could only be formally tested if overall survival was significantly different between the treatment groups in the intention-to-treat population. This study is registered with ClinicalTrials.gov, NCT02425891.\n\nFindings: Between June 23, 2015, and May 24, 2017, 902 patients were enrolled, of whom 451 were randomly assigned to receive atezolizumab plus nab-paclitaxel and 451 were assigned to receive placebo plus nab-paclitaxel (the intention-to-treat population). Six patients from each group did not receive treatment. At the second interim analysis (data cutoff Jan 2, 2019), median follow-up was 18·5 months (IQR 9·6-22·8) in the atezolizumab group and 17·5 months (8·4-22·4) in the placebo group. Median overall survival in the intention-to-treat patients was 21·0 months (95% CI 19·0-22·6) with atezolizumab and 18·7 months (16·9-20·3) with placebo (stratified hazard ratio [HR] 0·86, 95% CI 0·72-1·02, p=0·078). In the exploratory overall survival analysis in patients with PD-L1 immune cell-positive tumours, median overall survival was 25·0 months (95% CI 19·6-30·7) with atezolizumab versus 18·0 months (13·6-20·1) with placebo (stratified HR 0·71, 0·54-0·94]). at Sept 3, 2018 (the date up to which updated safety data were available), the most common grade 3-4 adverse events were neutropenia (38 [8%] of 453 patients in the atezolizumab group vs 36 [8%] of 437 patients in the placebo group), peripheral neuropathy (25 [6%] vs 12 [3%]), decreased neutrophil count (22 [5%] vs 16 [4%]), and fatigue (17 [4%] vs 15 [3%]). Treatment-related deaths occurred in two (<1%) patients in the atezolizumab group (autoimmune hepatitis related to atezolizumab [n=1] and septic shock related to nab-paclitaxel [n=1]) and one (<1%) patient in the placebo group (hepatic failure). No new treatment-related deaths have been reported since the primary clinical data cutoff date (April 17, 2018).\n\nInterpretation: Consistent with the first interim analysis, this second interim overall survival analysis of IMpassion130 indicates no significant difference in overall survival between the treatment groups in the intention-to-treat population but suggests a clinically meaningful overall survival benefit with atezolizumab plus nab-paclitaxel in patients with PD-L1 immune cell-positive disease. However, this positive result could not be formally tested due to the prespecified statistical testing hierarchy. For patients with PD-L1 immune cell-positive metastatic triple-negative breast cancer, atezolizumab plus nab-paclitaxel is an important therapeutic option in a disease with high unmet need.\n\nFunding: F Hoffmann-La Roche and Genentech.\n\nIndexed on Europe PMC as PubMed record 31786121 (DOI 10.1016/s1470-2045(19)30689-8). Its abstract cites the registry id NCT02425891, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2020, doi: "10.1016/s1470-2045(19)30689-8", pmid: "31786121", authors: "Schmid P, Rugo HS, Adams S, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the IMpassion130 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2020","url":"https://doi.org/10.1016/s1470-2045(19)30689-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31786121/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31786121"},{"label":"ClinicalTrials.gov NCT02425891","url":"https://clinicaltrials.gov/study/NCT02425891"}], tags: ["europepmc-ingest"], trials: ["impassion130"], journals: ["lancet-oncology"] }),
  p({ id: "paper-impassion131-ann-oncol-2021", name: "Primary results from IMpassion131, a double-blind, placebo-controlled, randomised phase III trial of first-line paclitaxel with or without atezolizumab for unresectable locally advanced/metastatic triple-negative breast cancer", tldr: "Published report from the IMpassion131 trial registered as NCT03125902, in Annals of Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: In the phase III IMpassion130 trial, combining atezolizumab with first-line nanoparticle albumin-bound-paclitaxel for advanced triple-negative breast cancer (aTNBC) showed a statistically significant progression-free survival (PFS) benefit in the intention-to-treat (ITT) and programmed death-ligand 1 (PD-L1)-positive populations, and a clinically meaningful overall survival (OS) effect in PD-L1-positive aTNBC. The phase III KEYNOTE-355 trial adding pembrolizumab to chemotherapy for aTNBC showed similar PFS effects. IMpassion131 evaluated first-line atezolizumab-paclitaxel in aTNBC.\n\nPatients and methods: Eligible patients [no prior systemic therapy or ≥12 months since (neo)adjuvant chemotherapy] were randomised 2:1 to atezolizumab 840 mg or placebo (days 1, 15), both with paclitaxel 90 mg/m 2 (days 1, 8, 15), every 28 days until disease progression or unacceptable toxicity. Stratification factors were tumour PD-L1 status, prior taxane, liver metastases and geographical region. The primary endpoint was investigator-assessed PFS, tested hierarchically first in the PD-L1-positive [immune cell expression ≥1%, VENTANA PD-L1 (SP142) assay] population, and then in the ITT population. OS was a secondary endpoint.\n\nResults: Of 651 randomised patients, 45% had PD-L1-positive aTNBC. At the primary PFS analysis, adding atezolizumab to paclitaxel did not improve investigator-assessed PFS in the PD-L1-positive population [hazard ratio (HR) 0.82, 95% confidence interval (CI) 0.60-1.12; P = 0.20; median PFS 6.0 months with atezolizumab-paclitaxel versus 5.7 months with placebo-paclitaxel]. In the PD-L1-positive population, atezolizumab-paclitaxel was associated with more favourable unconfirmed best overall response rate (63% versus 55% with placebo-paclitaxel) and median duration of response (7.2 versus 5.5 months, respectively). Final OS results showed no difference between arms (HR 1.11, 95% CI 0.76-1.64; median 22.1 months with atezolizumab-paclitaxel versus 28.3 months with placebo-paclitaxel in the PD-L1-positive population). Results in the ITT population were consistent with the PD-L1-positive population. The safety profile was consistent with known effects of each study drug.\n\nConclusion: Combining atezolizumab with paclitaxel did not improve PFS or OS versus paclitaxel alone. CLINICALTRIALS.GOV: NCT03125902.\n\nIndexed on Europe PMC as PubMed record 34219000 (DOI 10.1016/j.annonc.2021.05.801). Its abstract cites the registry id NCT03125902, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2021, doi: "10.1016/j.annonc.2021.05.801", pmid: "34219000", authors: "Miles D, Gligorov J, André F, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03125902 with the most citations, so it is the natural first reading for anyone following the IMpassion131 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2021","url":"https://doi.org/10.1016/j.annonc.2021.05.801"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34219000/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34219000"},{"label":"ClinicalTrials.gov NCT03125902","url":"https://clinicaltrials.gov/study/NCT03125902"}], tags: ["europepmc-ingest"], trials: ["impassion131"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-inavo120-n-engl-j-med-2024", name: "Inavolisib-Based Therapy in PIK3CA -Mutated Advanced Breast Cancer", tldr: "Published report from the INAVO120 trial registered as NCT04191499, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Inavolisib is a highly potent and selective inhibitor of the alpha isoform of the p110 catalytic subunit of the phosphatidylinositol 3-kinase complex (encoded by PIK3CA) that also promotes the degradation of mutated p110α. Inavolisib plus palbociclib-fulvestrant has shown synergistic activity in preclinical models and promising antitumor activity in early-phase trials.\n\nMethods: In a phase 3, double-blind, randomized trial, we compared first-line inavolisib (at an oral dose of 9 mg once daily) plus palbociclib-fulvestrant (inavolisib group) with placebo plus palbociclib-fulvestrant (placebo group) in patients with PIK3CA -mutated, hormone receptor-positive, human epidermal growth factor receptor 2 (HER2)-negative locally advanced or metastatic breast cancer who had had relapse during or within 12 months after the completion of adjuvant endocrine therapy. The primary end point was progression-free survival as assessed by the investigator.\n\nResults: A total of 161 patients were assigned to the inavolisib group and 164 to the placebo group; the median follow-up was 21.3 months and 21.5 months, respectively. The median progression-free survival was 15.0 months (95% confidence interval [CI], 11.3 to 20.5) in the inavolisib group and 7.3 months (95% CI, 5.6 to 9.3) in the placebo group (hazard ratio for disease progression or death, 0.43; 95% CI, 0.32 to 0.59; P<0.001). An objective response occurred in 58.4% of the patients in the inavolisib group and in 25.0% of those in the placebo group. The incidence of grade 3 or 4 neutropenia was 80.2% in the inavolisib group and 78.4% in the placebo group; grade 3 or 4 hyperglycemia, 5.6% and 0%, respectively; grade 3 or 4 stomatitis or mucosal inflammation, 5.6% and 0%; and grade 3 or 4 diarrhea, 3.7% and 0%. No grade 3 or 4 rash was observed. Discontinuation of any trial agent because of adverse events occurred in 6.8% of the patients in the inavolisib group and in 0.6% of those in the placebo group.\n\nConclusions: In patients with PIK3CA -mutated, hormone receptor-positive, HER2-negative locally advanced or metastatic breast cancer, inavolisib plus palbociclib-fulvestrant led to significantly longer progression-free survival than placebo plus palbociclib-fulvestrant, with a greater incidence of toxic effects. The percentage of patients who discontinued any trial agent because of adverse events was low. (Funded by F. Hoffmann-La Roche; INAVO120 ClinicalTrials.gov number, NCT04191499.).\n\nIndexed on Europe PMC as PubMed record 39476340 (DOI 10.1056/nejmoa2404625). Its abstract cites the registry id NCT04191499, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2404625", pmid: "39476340", authors: "Turner NC, Im SA, Saura C, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04191499 with the most citations, so it is the natural first reading for anyone following the INAVO120 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2404625"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39476340/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39476340"},{"label":"ClinicalTrials.gov NCT04191499","url":"https://clinicaltrials.gov/study/NCT04191499"}], tags: ["europepmc-ingest"], trials: ["inavo120"], journals: ["nejm"] }),
  p({ id: "paper-inavo120-n-engl-j-med-2025-update", name: "Overall Survival with Inavolisib in PIK3CA -Mutated Advanced Breast Cancer", tldr: "Later report from the INAVO120 trial registered as NCT04191499, in New England Journal of Medicine (2025); its title describes an updated or longer-term analysis.", summary: "Background: In the phase 3, double-blind, randomized INAVO120 trial, treatment with inavolisib plus palbociclib-fulvestrant led to a significant progression-free survival benefit, as compared with placebo plus palbociclib-fulvestrant, among patients with PIK3CA -mutated, hormone receptor-positive, human epidermal growth factor receptor 2 (HER2)-negative locally advanced or metastatic breast cancer who had had relapse during or within 12 months after completion of adjuvant endocrine therapy.\n\nMethods: We randomly assigned patients with PIK3CA -mutated, hormone receptor-positive, HER2-negative locally advanced or metastatic breast cancer who had had disease recurrence or progression during or within 12 months after completion of adjuvant endocrine therapy to receive inavolisib plus palbociclib-fulvestrant (inavolisib group) or placebo plus palbociclib-fulvestrant (placebo group). In the current report, we provide the results of the final analysis of overall survival, including updated data on efficacy and safety.\n\nResults: A total of 161 patients were assigned to the inavolisib group, and 164 to the placebo group. After a median follow-up of 34.2 months in the inavolisib group and 32.3 months in the placebo group, the median overall survival was 34.0 months (95% confidence interval [CI], 28.4 to 44.8) with inavolisib and 27.0 months (95% CI, 22.8 to 38.7) with placebo (hazard ratio for death, 0.67; 95% CI, 0.48 to 0.94; P = 0.02 [prespecified boundary for statistical significance, P<0.0469]). An objective response occurred in 62.7% (95% CI, 54.8 to 70.2) of patients in the inavolisib group and 28.0% (95% CI, 21.3 to 35.6) of those in the placebo group (P<0.001). The updated hazard ratio for disease progression or death was 0.42 (95% CI, 0.32 to 0.55). Adverse events led to discontinuation of inavolisib in 6.8% of patients and discontinuation of placebo in 0.6%. The incidence of hyperglycemia, stomatitis or mucosal inflammation, gastrointestinal toxic effects (e.g., diarrhea), and ocular toxic effects (e.g., dry eye and blurred vision) was higher with inavolisib than with placebo.\n\nConclusions: Treatment with inavolisib plus palbociclib-fulvestrant led to a significant overall survival benefit, as compared with placebo plus palbociclib-fulvestrant. Hyperglycemia, stomatitis or mucosal inflammation, gastrointestinal toxic effects, and ocular toxic effects were reported more frequently with inavolisib than with placebo. (Funded by F. Hoffmann-La Roche; INAVO120 ClinicalTrials.gov number, NCT04191499.).\n\nIndexed on Europe PMC as PubMed record 40454641 (DOI 10.1056/nejmoa2501796). Its abstract cites the registry id NCT04191499, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2501796", pmid: "40454641", authors: "Jhaveri KL, Im SA, Saura C, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the INAVO120 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2501796"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40454641/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40454641"},{"label":"ClinicalTrials.gov NCT04191499","url":"https://clinicaltrials.gov/study/NCT04191499"}], tags: ["europepmc-ingest"], trials: ["inavo120"], journals: ["nejm"] }),
  p({ id: "paper-keynote-355-lancet-2020", name: "Pembrolizumab plus chemotherapy versus placebo plus chemotherapy for previously untreated locally recurrent inoperable or metastatic triple-negative breast cancer (KEYNOTE-355): a randomised, placebo-controlled, double-blind, phase 3 clinical trial", tldr: "Published report from the KEYNOTE-355 trial registered as NCT02819518, in The Lancet (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Pembrolizumab monotherapy showed durable antitumour activity and manageable safety in patients with metastatic triple-negative breast cancer. We aimed to examine whether the addition of pembrolizumab would enhance the antitumour activity of chemotherapy in patients with metastatic triple-negative breast cancer.\n\nMethods: In this randomised, placebo-controlled, double-blind, phase 3 trial, done in 209 sites in 29 countries, we randomly assigned patients 2:1 with untreated locally recurrent inoperable or metastatic triple-negative breast cancer using a block method (block size of six) and an interactive voice-response system with integrated web-response to pembrolizumab (200 mg) every 3 weeks plus chemotherapy (nab-paclitaxel; paclitaxel; or gemcitabine plus carboplatin) or placebo plus chemotherapy. Randomisation was stratified by type of on-study chemotherapy (taxane or gemcitabine-carboplatin), PD-L1 expression at baseline (combined positive score [CPS] ≥1 or <1), and previous treatment with the same class of chemotherapy in the neoadjuvant or adjuvant setting (yes or no). Eligibility criteria included age at least 18 years, centrally confirmed triple-negative breast cancer; at least one measurable lesion; provision of a newly obtained tumour sample for determination of triple-negative breast cancer status and PD-L1 status by immunohistochemistry at a central laboratory; an Eastern Cooperative Oncology Group performance status score 0 or 1; and adequate organ function. The sponsor, investigators, other study site staff (except for the unmasked pharmacist), and patients were masked to pembrolizumab versus saline placebo administration. In addition, the sponsor, the investigators, other study site staff, and patients were masked to patient-level tumour PD-L1 biomarker results. Dual primary efficacy endpoints were progression-free survival and overall survival assessed in the PD-L1 CPS of 10 or more, CPS of 1 or more, and intention-to-treat populations. The definitive assessment of progression-free survival was done at this interim analysis; follow-up to assess overall survival is continuing. For progression-free survival, a hierarchical testing strategy was used, such that testing was done first in patients with CPS of 10 or more (prespecified statistical criterion was α=0·00411 at this interim analysis), then in patients with CPS of 1 or more (α=0·00111 at this interim analysis, with partial alpha from progression-free survival in patients with CPS of 10 or more passed over), and finally in the intention-to-treat population (α=0·00111 at this interim analysis). This study is registered with ClinicalTrials.gov, NCT02819518, and is ongoing.\n\nFindings: Between Jan 9, 2017, and June 12, 2018, of 1372 patients screened, 847 were randomly assigned to treatment, with 566 patients in the pembrolizumab-chemotherapy group and 281 patients in the placebo-chemotherapy group. At the second interim analysis (data cutoff, Dec 11, 2019), median follow-up was 25·9 months (IQR 22·8-29·9) in the pembrolizumab-chemotherapy group and 26·3 months (22·7-29·7) in the placebo-chemotherapy group. Among patients with CPS of 10 or more, median progression-free survival was 9·7 months with pembrolizumab-chemotherapy and 5·6 months with placebo-chemotherapy (hazard ratio [HR] for progression or death, 0·65, 95% CI 0·49-0·86; one-sided p=0·0012 [primary objective met]). Median progression-free survival was 7·6 and 5·6 months (HR, 0·74, 0·61-0·90; one-sided p=0·0014 [not significant]) among patients with CPS of 1 or more and 7·5 and 5·6 months (HR, 0·82, 0·69-0·97 [not tested]) among the intention-to-treat population. The pembrolizumab treatment effect increased with PD-L1 enrichment. Grade 3-5 treatment-related adverse event rates were 68% in the pembrolizumab-chemotherapy group and 67% in the placebo-chemotherapy group, including death in <1% in the pembrolizumab-chemotherapy group and 0% in the placebo-chemotherapy group.\n\nInterpretation: Pembrolizumab-chemotherapy showed a significant and clinically meaningful improvement in progression-free survival versus placebo-chemotherapy among patients with metastatic triple-negative breast cancer with CPS of 10 or more. These findings suggest a role for the addition of pembrolizumab to standard chemotherapy for the first-line treatment of metastatic triple-negative breast cancer.\n\nFunding: Merck Sharp & Dohme Corp, a subsidiary of Merck & Co, Inc.\n\nIndexed on Europe PMC as PubMed record 33278935 (DOI 10.1016/s0140-6736(20)32531-9). Its abstract cites the registry id NCT02819518, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2020, doi: "10.1016/s0140-6736(20)32531-9", pmid: "33278935", authors: "Cortes J, Cescon DW, Rugo HS, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02819518 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-355 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2020","url":"https://doi.org/10.1016/s0140-6736(20)32531-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33278935/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33278935"},{"label":"ClinicalTrials.gov NCT02819518","url":"https://clinicaltrials.gov/study/NCT02819518"}], tags: ["europepmc-ingest"], trials: ["keynote-355"], journals: ["lancet"] }),
  p({ id: "paper-keynote-522-n-engl-j-med-2020", name: "Pembrolizumab for Early Triple-Negative Breast Cancer", tldr: "Published report from the KEYNOTE-522 trial registered as NCT03036488, in New England Journal of Medicine (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Previous trials showed promising antitumor activity and an acceptable safety profile associated with pembrolizumab in patients with early triple-negative breast cancer. Whether the addition of pembrolizumab to neoadjuvant chemotherapy would significantly increase the percentage of patients with early triple-negative breast cancer who have a pathological complete response (defined as no invasive cancer in the breast and negative nodes) at definitive surgery is unclear.\n\nMethods: In this phase 3 trial, we randomly assigned (in a 2:1 ratio) patients with previously untreated stage II or stage III triple-negative breast cancer to receive neoadjuvant therapy with four cycles of pembrolizumab (at a dose of 200 mg) every 3 weeks plus paclitaxel and carboplatin (784 patients; the pembrolizumab-chemotherapy group) or placebo every 3 weeks plus paclitaxel and carboplatin (390 patients; the placebo-chemotherapy group); the two groups then received an additional four cycles of pembrolizumab or placebo, and both groups received doxorubicin-cyclophosphamide or epirubicin-cyclophosphamide. After definitive surgery, the patients received adjuvant pembrolizumab or placebo every 3 weeks for up to nine cycles. The primary end points were a pathological complete response at the time of definitive surgery and event-free survival in the intention-to-treat population.\n\nResults: At the first interim analysis, among the first 602 patients who underwent randomization, the percentage of patients with a pathological complete response was 64.8% (95% confidence interval [CI], 59.9 to 69.5) in the pembrolizumab-chemotherapy group and 51.2% (95% CI, 44.1 to 58.3) in the placebo-chemotherapy group (estimated treatment difference, 13.6 percentage points; 95% CI, 5.4 to 21.8; P<0.001). After a median follow-up of 15.5 months (range, 2.7 to 25.0), 58 of 784 patients (7.4%) in the pembrolizumab-chemotherapy group and 46 of 390 patients (11.8%) in the placebo-chemotherapy group had disease progression that precluded definitive surgery, had local or distant recurrence or a second primary tumor, or died from any cause (hazard ratio, 0.63; 95% CI, 0.43 to 0.93). Across all treatment phases, the incidence of treatment-related adverse events of grade 3 or higher was 78.0% in the pembrolizumab-chemotherapy group and 73.0% in the placebo-chemotherapy group, including death in 0.4% (3 patients) and 0.3% (1 patient), respectively.\n\nConclusions: Among patients with early triple-negative breast cancer, the percentage with a pathological complete response was significantly higher among those who received pembrolizumab plus neoadjuvant chemotherapy than among those who received placebo plus neoadjuvant chemotherapy. (Funded by Merck Sharp & Dohme [a subsidiary of Merck]; KEYNOTE-522 ClinicalTrials.gov number, NCT03036488.).\n\nIndexed on Europe PMC as PubMed record 32101663 (DOI 10.1056/nejmoa1910549). Its abstract cites the registry id NCT03036488, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2020, doi: "10.1056/nejmoa1910549", pmid: "32101663", authors: "Schmid P, Cortes J, Pusztai L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03036488 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-522 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2020","url":"https://doi.org/10.1056/nejmoa1910549"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32101663/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32101663"},{"label":"ClinicalTrials.gov NCT03036488","url":"https://clinicaltrials.gov/study/NCT03036488"}], tags: ["europepmc-ingest"], trials: ["keynote-522"], journals: ["nejm"] }),
  p({ id: "paper-keynote-522-n-engl-j-med-2024-update", name: "Overall Survival with Pembrolizumab in Early-Stage Triple-Negative Breast Cancer", tldr: "Later report from the KEYNOTE-522 trial registered as NCT03036488, in New England Journal of Medicine (2024); its title describes an updated or longer-term analysis.", summary: "Background: In patients with early-stage triple-negative breast cancer, the phase 3 KEYNOTE-522 trial showed significant improvements in pathological complete response and event-free survival with the addition of pembrolizumab to platinum-containing chemotherapy. Here we report the final results for overall survival.\n\nMethods: We randomly assigned, in a 2:1 ratio, patients with previously untreated stage II or III triple-negative breast cancer to receive neoadjuvant therapy with four cycles of pembrolizumab (at a dose of 200 mg) or placebo every 3 weeks plus paclitaxel and carboplatin, followed by four cycles of pembrolizumab or placebo plus doxorubicin-cyclophosphamide or epirubicin-cyclophosphamide. After definitive surgery, patients received adjuvant pembrolizumab (pembrolizumab-chemotherapy group) or placebo (placebo-chemotherapy group) every 3 weeks for up to nine cycles. The primary end points were pathological complete response and event-free survival. Overall survival was a secondary end point.\n\nResults: Of the 1174 patients who underwent randomization, 784 were assigned to the pembrolizumab-chemotherapy group and 390 to the placebo-chemotherapy group. At the data-cutoff date (March 22, 2024), the median follow-up was 75.1 months (range, 65.9 to 84.0). The estimated overall survival at 60 months was 86.6% (95% confidence interval [CI], 84.0 to 88.8) in the pembrolizumab-chemotherapy group, as compared with 81.7% (95% CI, 77.5 to 85.2) in the placebo-chemotherapy group (P = 0.002). Adverse events were consistent with the established safety profiles of pembrolizumab and chemotherapy.\n\nConclusions: Neoadjuvant pembrolizumab plus chemotherapy followed by adjuvant pembrolizumab resulted in a significant improvement, as compared with neoadjuvant chemotherapy alone, in overall survival among patients with early-stage triple-negative breast cancer. (Funded by Merck Sharp and Dohme, a subsidiary of Merck [Rahway, NJ]; KEYNOTE-522 ClinicalTrials.gov number, NCT03036488.).\n\nIndexed on Europe PMC as PubMed record 39282906 (DOI 10.1056/nejmoa2409932). Its abstract cites the registry id NCT03036488, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2409932", pmid: "39282906", authors: "Schmid P, Cortes J, Dent R, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-522 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2409932"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39282906/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39282906"},{"label":"ClinicalTrials.gov NCT03036488","url":"https://clinicaltrials.gov/study/NCT03036488"}], tags: ["europepmc-ingest"], trials: ["keynote-522"], journals: ["nejm"] }),
  p({ id: "paper-kristine-lancet-oncol-2018", name: "Neoadjuvant trastuzumab, pertuzumab, and chemotherapy versus trastuzumab emtansine plus pertuzumab in patients with HER2-positive breast cancer (KRISTINE): a randomised, open-label, multicentre, phase 3 trial", tldr: "Published report from the KRISTINE trial registered as NCT02131064, in The Lancet Oncology (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: HER2-targeted treatments have improved outcomes in patients with HER2-positive breast cancer in the neoadjuvant, adjuvant, and metastatic settings; however, some patients remain at risk of relapse or death for many years after treatment of early-stage disease. Therefore, new strategies are needed. We did a phase 3 trial to assess a neoadjuvant regimen for HER2-positive breast cancer that replaces traditional systemic chemotherapy with targeted treatment.\n\nMethods: We did a randomised, open-label phase 3 KRISTINE trial in 68 Translational Research In Oncology centres (hospitals and specialty cancer centres in Asia, Europe, USA, and Canada). Eligible participants were aged 18 years or older with centrally confirmed HER2-positive stage II-III operable breast cancer (>2 cm tumour size), an Eastern Cooperative Oncology Group performance status of 0-1, and a baseline left ventricular ejection fraction of at least 55% (by echocardiogram or multiple-gated acquisition scan). We randomly assigned participants (1:1) to receive either trastuzumab emtansine plus pertuzumab or docetaxel, carboplatin, and trastuzumab plus pertuzumab. We did the randomisation via an interactive response system under a permuted block randomisation scheme (block size of four), stratified by hormone receptor status, stage at diagnosis, and geographical location. Patients received six cycles (every 3 weeks) of neoadjuvant trastuzumab emtansine plus pertuzumab (trastuzumab emtansine 3·6 mg/kg; pertuzumab 840 mg loading dose, 420 mg maintenance doses) or docetaxel, carboplatin, and trastuzumab plus pertuzumab (docetaxel 75 mg/m 2; carboplatin area under the concentration-time curve 6 mg/mL × min; trastuzumab 8 mg/kg loading dose, 6 mg/kg maintenance doses) plus pertuzumab [same dosing as in the other group]). All treatments were administered intravenously. The primary objective was to compare the number of patients who achieved a pathological complete response (ypT0/is, ypN0), between groups in the intention-to-treat population (two-sided assessment), based on local evaluation of tumour samples taken at breast cancer surgery done between 14 days and 6 weeks after completion of neoadjuvant therapy. Safety was analysed in patients who received at least one dose of study medication. This trial is registered with ClinicalTrials.gov, number NCT02131064, and follow-up of the adjuvant phase is ongoing.\n\nFindings: Between June 25, 2014, and June 15, 2015, we randomly assigned 444 patients to neoadjuvant treatment with trastuzumab emtansine plus pertuzumab (n=223) or docetaxel, carboplatin, and trastuzumab plus pertuzumab (n=221). A pathological complete response was achieved by 99 (44·4%) of 223 patients in the trastuzumab emtansine plus pertuzumab group and 123 (55·7%) of 221 patients in the docetaxel, carboplatin, and trastuzumab plus pertuzumab group (absolute difference -11·3 percentage points, 95% CI -20·5 to -2·0; p=0·016). During neoadjuvant treatment, compared with patients receiving docetaxel, carboplatin, and trastuzumab plus pertuzumab, fewer patients receiving trastuzumab emtansine plus pertuzumab had a grade 3-4 adverse event (29 [13%] of 223 vs 141 [64%] of 219) or a serious adverse event (11 [5%] of 223 vs 63 [29%] of 219). The most common grade 3-4 adverse events in the trastuzumab emtansine plus pertuzumab group were decreased platelet count (three [1%] of 223 patients vs 11 [5%] of 219 with docetaxel, carboplatin, and trastuzumab plus pertuzumab), fatigue (three [1%] vs seven [3%]), alanine aminotransferase increase (three [1%] vs four [2%]), and hypokalaemia (three [1%] vs five [2%]). The most common grade 3-4 adverse events in the docetaxel, carboplatin, and trastuzumab plus pertuzumab group were neutropenia (55 [25%] of 219 vs one [<1%] of 223 with trastuzumab emtansine plus pertuzumab), diarrhoea (33 [15%] vs 2 [<1%]), and febrile neutropenia (33 [15%] vs 0). No deaths were reported during neoadjuvant treatment.\n\nInterpretation: Traditional neoadjuvant systemic chemotherapy plus dual HER2-targeted blockade (docetaxel, carboplatin, and trastuzumab plus pertuzumab) resulted in significantly more patients achieving a pathological complete response than HER2-targeted chemotherapy plus HER2-targeted blockade (trastuzumab emtansine plus pertuzumab); however, numerically more grade 3-4 and serious adverse events occurred in the chemotherapy plus trastuzumab and pertuzumab group. Further efforts to improve the efficacy of chemotherapy without imparting more toxicity are warranted.\n\nFunding: F Hoffmann-La Roche and Genentech.\n\nIndexed on Europe PMC as PubMed record 29175149 (DOI 10.1016/s1470-2045(17)30716-7). Its abstract cites the registry id NCT02131064, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2018, doi: "10.1016/s1470-2045(17)30716-7", pmid: "29175149", authors: "Hurvitz SA, Martin M, Symmans WF, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02131064 with the most citations, so it is the natural first reading for anyone following the KRISTINE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2018","url":"https://doi.org/10.1016/s1470-2045(17)30716-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/29175149/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/29175149"},{"label":"ClinicalTrials.gov NCT02131064","url":"https://clinicaltrials.gov/study/NCT02131064"}], tags: ["europepmc-ingest"], trials: ["kristine"], journals: ["lancet-oncology"] }),
  p({ id: "paper-lumina-n-engl-j-med-2023", name: "Omitting Radiotherapy after Breast-Conserving Surgery in Luminal A Breast Cancer", tldr: "Published report from the LUMINA trial registered as NCT01791829, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Adjuvant radiotherapy is prescribed after breast-conserving surgery to reduce the risk of local recurrence. However, radiotherapy is inconvenient, costly, and associated with both short-term and long-term side effects. Clinicopathologic factors alone are of limited use in the identification of women at low risk for local recurrence in whom radiotherapy can be omitted. Molecularly defined intrinsic subtypes of breast cancer can provide additional prognostic information.\n\nMethods: We performed a prospective cohort study involving women who were at least 55 years of age, had undergone breast-conserving surgery for T1N0 (tumor size <2 cm and node negative), grade 1 or 2, luminal A-subtype breast cancer (defined as estrogen receptor positivity of ≥1%, progesterone receptor positivity of >20%, negative human epidermal growth factor receptor 2, and Ki67 index of ≤13.25%), and had received adjuvant endocrine therapy. Patients who met the clinical eligibility criteria were registered, and Ki67 immunohistochemical analysis was performed centrally. Patients with a Ki67 index of 13.25% or less were enrolled and did not receive radiotherapy. The primary outcome was local recurrence in the ipsilateral breast. In consultation with radiation oncologists and patients with breast cancer, we determined that if the upper boundary of the two-sided 90% confidence interval for the cumulative incidence at 5 years was less than 5%, this would represent an acceptable risk of local recurrence at 5 years.\n\nResults: Of 740 registered patients, 500 eligible patients were enrolled. At 5 years after enrollment, recurrence was reported in 2.3% of the patients (90% confidence interval [CI], 1.3 to 3.8; 95% CI, 1.2 to 4.1), a result that met the prespecified boundary. Breast cancer occurred in the contralateral breast in 1.9% of the patients (90% CI, 1.1 to 3.2), and recurrence of any type was observed in 2.7% (90% CI, 1.6 to 4.1).\n\nConclusions: Among women who were at least 55 years of age and had T1N0, grade 1 or 2, luminal A breast cancer that were treated with breast-conserving surgery and endocrine therapy alone, the incidence of local recurrence at 5 years was low with the omission of radiotherapy. (Funded by the Canadian Cancer Society and the Canadian Breast Cancer Foundation; LUMINA ClinicalTrials.gov number, NCT01791829.).\n\nIndexed on Europe PMC as PubMed record 37585627 (DOI 10.1056/nejmoa2302344). Its abstract cites the registry id NCT01791829, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2302344", pmid: "37585627", authors: "Whelan TJ, Smith S, Parpia S, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01791829 with the most citations, so it is the natural first reading for anyone following the LUMINA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2302344"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37585627/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37585627"},{"label":"ClinicalTrials.gov NCT01791829","url":"https://clinicaltrials.gov/study/NCT01791829"}], tags: ["europepmc-ingest"], trials: ["lumina"], journals: ["nejm"] }),
  p({ id: "paper-ma-20-n-engl-j-med-2015", name: "Regional Nodal Irradiation in Early-Stage Breast Cancer", tldr: "Published report from the trial registered as NCT00005957, in New England Journal of Medicine (2015), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Most women with breast cancer who undergo breast-conserving surgery receive whole-breast irradiation. We examined whether the addition of regional nodal irradiation to whole-breast irradiation improved outcomes.\n\nMethods: We randomly assigned women with node-positive or high-risk node-negative breast cancer who were treated with breast-conserving surgery and adjuvant systemic therapy to undergo either whole-breast irradiation plus regional nodal irradiation (including internal mammary, supraclavicular, and axillary lymph nodes) (nodal-irradiation group) or whole-breast irradiation alone (control group). The primary outcome was overall survival. Secondary outcomes were disease-free survival, isolated locoregional disease-free survival, and distant disease-free survival.\n\nResults: Between March 2000 and February 2007, a total of 1832 women were assigned to the nodal-irradiation group or the control group (916 women in each group). The median follow-up was 9.5 years. At the 10-year follow-up, there was no significant between-group difference in survival, with a rate of 82.8% in the nodal-irradiation group and 81.8% in the control group (hazard ratio, 0.91; 95% confidence interval [CI], 0.72 to 1.13; P=0.38). The rates of disease-free survival were 82.0% in the nodal-irradiation group and 77.0% in the control group (hazard ratio, 0.76; 95% CI, 0.61 to 0.94; P=0.01). Patients in the nodal-irradiation group had higher rates of grade 2 or greater acute pneumonitis (1.2% vs. 0.2%, P=0.01) and lymphedema (8.4% vs. 4.5%, P=0.001).\n\nConclusions: Among women with node-positive or high-risk node-negative breast cancer, the addition of regional nodal irradiation to whole-breast irradiation did not improve overall survival but reduced the rate of breast-cancer recurrence. (Funded by the Canadian Cancer Society Research Institute and others; MA.20 ClinicalTrials.gov number, NCT00005957.).\n\nIndexed on Europe PMC as PubMed record 26200977 (DOI 10.1056/nejmoa1415340). Its abstract cites the registry id NCT00005957, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2015, doi: "10.1056/nejmoa1415340", pmid: "26200977", authors: "Whelan TJ, Olivotto IA, Parulekar WR, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00005957 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2015","url":"https://doi.org/10.1056/nejmoa1415340"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/26200977/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/26200977"},{"label":"ClinicalTrials.gov NCT00005957","url":"https://clinicaltrials.gov/study/NCT00005957"}], tags: ["europepmc-ingest"], trials: ["ma-20"], journals: ["nejm"] }),
  p({ id: "paper-masai-lancet-digit-health-2025", name: "Screening performance and characteristics of breast cancer detected in the Mammography Screening with Artificial Intelligence trial (MASAI): a randomised, controlled, parallel-group, non-inferiority, single-blinded, screening accuracy study", tldr: "Published report from the MASAI trial registered as NCT04838756, in The Lancet Digital Health (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Emerging evidence suggests that artificial intelligence (AI) can increase cancer detection in mammography screening while reducing screen-reading workload, but further understanding of the clinical impact is needed.\n\nMethods: In this randomised, controlled, parallel-group, non-inferiority, single-blinded, screening-accuracy study, done within the Swedish national screening programme, women recruited at four screening sites in southwest Sweden (Malmö, Lund, Landskrona, and Trelleborg) who were eligible for mammography screening were randomly allocated (1:1) to AI-supported screening or standard double reading. The AI system (Transpara version 1.7.0 ScreenPoint Medical, Nijmegen, Netherlands) was used to triage screening examinations to single or double reading and as detection support highlighting suspicious findings. This is a protocol-defined analysis of the secondary outcome measures of recall, cancer detection, false-positive rates, positive predictive value of recall, type and stage of cancer detected, and screen-reading workload. This trial is registered at ClinicalTrials.gov, NCT04838756 and is closed to accrual.\n\nFindings: Between April 12, 2021, and Dec 7, 2022, 105 934 women were randomly assigned to the intervention or control group. 19 women were excluded from the analysis. The median age was 53·7 years (IQR 46·5-63·2). AI-supported screening among 53 043 participants resulted in 338 detected cancers and 1110 recalls. Standard screening among 52 872 participants resulted in 262 detected cancers and 1027 recalls. Cancer-detection rates were 6·4 per 1000 (95% CI 5·7-7·1) screened participants in the intervention group and 5·0 per 1000 (4·4-5·6) in the control group, a ratio of 1·29 (95% CI 1·09-1·51; p=0·0021). AI-supported screening resulted in an increased detection of invasive cancers (270 vs 217, a proportion ratio of 1·24 [95% CI 1·04-1·48]), wich were mainly small lymph-node negative cancers (58 more T1, 46 more lymph-node negative, and 21 more non-luminal A). AI-supported screening also resulted in an increased detection of in situ cancers (68 vs 45, a proportion ratio of 1·51 [1·03-2·19]), with about half of the increased detection being high-grade in situ cancer (12 more nuclear grade III, and no increase in nuclear grade I). The recall and false-positive rate were not significantly higher in the intervention group (a ratio of 1·08 [95% CI 0·99-1·17; p=0·084] and 1·01 [0·91-1·11; p=0·92], respectively). The positive predictive value of recall was significantly higher in the intervention group compared with the control group, with a ratio of 1·19 (95% CI 1·04-1·37; p=0·012). There were 61 248 screen readings in the intervention group and 109 692 in the control group, resulting in a 44·2% reduction in the screen-reading workload.\n\nInterpretation: The findings suggest that AI contributes to the early detection of clinically relevant breast cancer and reduces screen-reading workload without increasing false positives.\n\nFunding: Swedish Cancer Society, Confederation of Regional Cancer Centres, and Swedish governmental funding for clinical research.\n\nIndexed on Europe PMC as PubMed record 39904652 (DOI 10.1016/s2589-7500(24)00267-x). Its abstract cites the registry id NCT04838756, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Digital Health", year: 2025, doi: "10.1016/s2589-7500(24)00267-x", pmid: "39904652", authors: "Hernström V, Josefsson V, Sartor H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04838756 with the most citations, so it is the natural first reading for anyone following the MASAI trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Digit Health 2025","url":"https://doi.org/10.1016/s2589-7500(24)00267-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39904652/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39904652"},{"label":"ClinicalTrials.gov NCT04838756","url":"https://clinicaltrials.gov/study/NCT04838756"}], tags: ["europepmc-ingest"], trials: ["masai"], journals: ["lancet-digital-health"] }),
  p({ id: "paper-mindact-ann-oncol-2014", name: "High concordance of protein (by IHC), gene (by FISH; HER2 only), and microarray readout (by TargetPrint) of ER, PgR, and HER2: results from the EORTC 10041/BIG 03-04 MINDACT trial", tldr: "Published report from the MINDACT trial registered as NCT00433589, in Annals of Oncology (2014), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: To investigate the correlation of TargetPrint with local and central immunohistochemistry/fluorescence in situ hybridization assessment of estrogen (ER), progesterone (PgR), and human epidermal growth factor receptor 2 (HER2) in the first 800 patients enrolled in the MINDACT trial.\n\nPatients and methods: Data from local (N = 800) and central (N = 626) assessments of receptor status were collected and compared with TargetPrint results.\n\nResults: For ER, the positive agreement (the percentage of central pathology positive assessments that were also TargetPrint/local laboratory positive) for TargetPrint in comparison to centralized assessment was 98% with a negative agreement (the percentage of central pathology negative assessments that were also TargetPrint/local laboratory negative) of 96%. For PgR, the positive agreement was 83% with a negative agreement of 92%. For HER2, the positive agreement was 75% with a negative agreement of 99%. Even though the local assessment showed higher positive agreement for PgR (89%) and higher positive agreement for HER2 (85%), the range of discordant local versus central assessments were as high as 6.7% for ER, 12.9% for PgR, and 4.3% for HER2.\n\nConclusion: TargetPrint and local assessment of ER, PgR, and HER2 show high concordance with central assessment in the first 800 MINDACT patients. However, there are concerns about the higher discordance rates for some local sites. TargetPrint can improve the reliability of hormone receptor and HER2 testing for those centers with a lower rate of concordance with the reference laboratory, with the limitation of a positive agreement of 75% for HER2. TargetPrint consequently has important implications for treatment decisions in clinical practice and is a reliable alternative to local assessment for ER.\n\nClinical trials number: NCT00433589.\n\nIndexed on Europe PMC as PubMed record 24667714 (DOI 10.1093/annonc/mdu026). Its abstract cites the registry id NCT00433589, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2014, doi: "10.1093/annonc/mdu026", pmid: "24667714", authors: "Viale G, Slaets L, Bogaerts J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00433589 with the most citations, so it is the natural first reading for anyone following the MINDACT trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2014","url":"https://doi.org/10.1093/annonc/mdu026"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/24667714/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/24667714"},{"label":"ClinicalTrials.gov NCT00433589","url":"https://clinicaltrials.gov/study/NCT00433589"}], tags: ["europepmc-ingest"], trials: ["mindact"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-monaleesa-2-n-engl-j-med-2016", name: "Ribociclib as First-Line Therapy for HR-Positive, Advanced Breast Cancer", tldr: "Published report from the MONALEESA-2 trial registered as NCT01958021, in New England Journal of Medicine (2016), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The inhibition of cyclin-dependent kinases 4 and 6 (CDK4/6) could potentially overcome or delay resistance to endocrine therapy in advanced breast cancer that is positive for hormone receptor (HR) and negative for human epidermal growth factor receptor 2 (HER2).\n\nMethods: In this randomized, placebo-controlled, phase 3 trial, we evaluated the efficacy and safety of the selective CDK4/6 inhibitor ribociclib combined with letrozole for first-line treatment in 668 postmenopausal women with HR-positive, HER2-negative recurrent or metastatic breast cancer who had not received previous systemic therapy for advanced disease. We randomly assigned the patients to receive either ribociclib (600 mg per day on a 3-weeks-on, 1-week-off schedule) plus letrozole (2.5 mg per day) or placebo plus letrozole. The primary end point was investigator-assessed progression-free survival. Secondary end points included overall survival, overall response rate, and safety. A preplanned interim analysis was performed on January 29, 2016, after 243 patients had disease progression or died. Prespecified criteria for superiority required a hazard ratio of 0.56 or less with P<1.29×10 -5.\n\nResults: The duration of progression-free survival was significantly longer in the ribociclib group than in the placebo group (hazard ratio, 0.56; 95% CI, 0.43 to 0.72; P=3.29×10 -6 for superiority). The median duration of follow-up was 15.3 months. After 18 months, the progression-free survival rate was 63.0% (95% confidence interval [CI], 54.6 to 70.3) in the ribociclib group and 42.2% (95% CI, 34.8 to 49.5) in the placebo group. In patients with measurable disease at baseline, the overall response rate was 52.7% and 37.1%, respectively (P<0.001). Common grade 3 or 4 adverse events that were reported in more than 10% of the patients in either group were neutropenia (59.3% in the ribociclib group vs. 0.9% in the placebo group) and leukopenia (21.0% vs. 0.6%); the rates of discontinuation because of adverse events were 7.5% and 2.1%, respectively.\n\nConclusions: Among patients receiving initial systemic treatment for HR-positive, HER2-negative advanced breast cancer, the duration of progression-free survival was significantly longer among those receiving ribociclib plus letrozole than among those receiving placebo plus letrozole, with a higher rate of myelosuppression in the ribociclib group. (Funded by Novartis Pharmaceuticals; ClinicalTrials.gov number, NCT01958021.).\n\nIndexed on Europe PMC as PubMed record 27717303 (DOI 10.1056/nejmoa1609709). Its abstract cites the registry id NCT01958021, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2016, doi: "10.1056/nejmoa1609709", pmid: "27717303", authors: "Hortobagyi GN, Stemmer SM, Burris HA, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01958021 with the most citations, so it is the natural first reading for anyone following the MONALEESA-2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2016","url":"https://doi.org/10.1056/nejmoa1609709"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/27717303/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/27717303"},{"label":"ClinicalTrials.gov NCT01958021","url":"https://clinicaltrials.gov/study/NCT01958021"}], tags: ["europepmc-ingest"], trials: ["monaleesa-2"], journals: ["nejm"] }),
  p({ id: "paper-monaleesa-2-n-engl-j-med-2022-update", name: "Overall Survival with Ribociclib plus Letrozole in Advanced Breast Cancer", tldr: "Later report from the MONALEESA-2 trial registered as NCT01958021, in New England Journal of Medicine (2022); its title describes an updated or longer-term analysis.", summary: "Background: In a previous analysis of this phase 3 trial, first-line ribociclib plus letrozole resulted in significantly longer progression-free survival than letrozole alone among postmenopausal patients with hormone receptor (HR)-positive, human epidermal growth factor receptor 2 (HER2)-negative advanced breast cancer. Whether overall survival would also be longer with ribociclib was not known.\n\nMethods: Here we report the results of the protocol-specified final analysis of overall survival, a key secondary end point. Patients were randomly assigned in a 1:1 ratio to receive either ribociclib or placebo in combination with letrozole. Overall survival was assessed with the use of a stratified log-rank test and summarized with the use of Kaplan-Meier methods after 400 deaths had occurred. A hierarchical testing strategy was used for the analysis of progression-free survival and overall survival to ensure the validity of the findings.\n\nResults: After a median follow-up of 6.6 years, 181 deaths had occurred among 334 patients (54.2%) in the ribociclib group and 219 among 334 (65.6%) in the placebo group. Ribociclib plus letrozole showed a significant overall survival benefit as compared with placebo plus letrozole. Median overall survival was 63.9 months (95% confidence interval [CI], 52.4 to 71.0) with ribociclib plus letrozole and 51.4 months (95% CI, 47.2 to 59.7) with placebo plus letrozole (hazard ratio for death, 0.76; 95% CI, 0.63 to 0.93; two-sided P = 0.008). No new safety signals were observed.\n\nConclusions: First-line therapy with ribociclib plus letrozole showed a significant overall survival benefit as compared with placebo plus letrozole in patients with HR-positive, HER2-negative advanced breast cancer. Median overall survival was more than 12 months longer with ribociclib than with placebo. (Funded by Novartis; MONALEESA-2 ClinicalTrials.gov number, NCT01958021.).\n\nIndexed on Europe PMC as PubMed record 35263519 (DOI 10.1056/nejmoa2114663). Its abstract cites the registry id NCT01958021, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2022, doi: "10.1056/nejmoa2114663", pmid: "35263519", authors: "Hortobagyi GN, Stemmer SM, Burris HA, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the MONALEESA-2 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"N Engl J Med 2022","url":"https://doi.org/10.1056/nejmoa2114663"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35263519/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35263519"},{"label":"ClinicalTrials.gov NCT01958021","url":"https://clinicaltrials.gov/study/NCT01958021"}], tags: ["europepmc-ingest"], trials: ["monaleesa-2"], journals: ["nejm"] }),
  p({ id: "paper-monarche-lancet-oncol-2023", name: "Abemaciclib plus endocrine therapy for hormone receptor-positive, HER2-negative, node-positive, high-risk early breast cancer (monarchE): results from a preplanned interim analysis of a randomised, open-label, phase 3 trial", tldr: "Published report from the monarchE trial registered as NCT03155997, in The Lancet Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Adjuvant abemaciclib plus endocrine therapy previously showed a significant improvement in invasive disease-free survival and distant relapse-free survival in hormone receptor-positive, human epidermal growth factor receptor 2 (HER2; also known as ERBB2)-negative, node-positive, high-risk, early breast cancer. Here, we report updated results from an interim analysis to assess overall survival as well as invasive disease-free survival and distant relapse-free survival with additional follow-up.\n\nMethods: In monarchE, an open-label, randomised, phase 3 trial, adult patients (aged ≥18 years) who had hormone receptor-positive, HER2-negative, node-positive, early breast cancer at a high risk of recurrence with an Eastern Cooperative Oncology Group performance status of 0 or 1 were recruited from 603 sites including hospitals and academic and community centres in 38 countries. Patients were randomly assigned (1:1) by means of an interactive web-based response system (block size of 4), stratified by previous chemotherapy, menopausal status, and region, to receive standard-of-care endocrine therapy of physician's choice for up to 10 years with or without abemaciclib 150 mg orally twice a day for 2 years (treatment period). All therapies were administered in an open-label manner without masking. High-risk disease was defined as either four or more positive axillary lymph nodes, or between one and three positive axillary lymph nodes and either grade 3 disease or tumour size of 5 cm or larger (cohort 1). A smaller group of patients were enrolled with between one and three positive axillary lymph nodes and Ki-67 of at least 20% as an additional risk feature (cohort 2). This was a prespecified overall survival interim analysis planned to occur 2 years after the primary outcome analysis for invasive disease-free survival. Efficacy was assessed in the intention-to-treat population. Safety was assessed in all treated patients. The study is registered with ClinicalTrials.gov, NCT03155997, and is ongoing.\n\nFindings: Between July 17, 2017, and Aug 12, 2019, 5637 patients were randomly assigned (5601 [99·4%] were women and 36 [0·6%] were men). 2808 were assigned to receive abemaciclib plus endocrine therapy and 2829 were assigned to receive endocrine therapy alone. At a median follow-up of 42 months (IQR 37-47), median invasive disease-free survival was not reached in either group and the invasive disease-free survival benefit previously reported was sustained: HR 0·664 (95% CI 0·578-0·762, nominal p<0·0001). At 4 years, the absolute difference in invasive disease-free survival between the groups was 6·4% (85·8% [95% CI 84·2-87·3] in the abemaciclib plus endocrine therapy group vs 79·4% [77·5-81·1] in the endocrine therapy alone group). 157 (5·6%) of 2808 patients in the abemaciclib plus endocrine therapy group died compared with 173 (6·1%) of 2829 patients in the endocrine therapy alone group (HR 0·929, 95% CI 0·748-1·153; p=0·50). The most common grade 3-4 adverse events were neutropenia (in 548 [19·6%] of 2791 patients receiving abemaciclib plus endocrine therapy vs 24 [0·9%] of 2800 patients in the endocrine therapy alone group), leukopenia (318 [11·4%] vs 11 [0·4%]), and diarrhoea (218 [7·8%] vs six [0·2%]). Serious adverse events occurred in 433 (15·5%) of 2791 patients receiving abemaciclib plus endocrine therapy versus 256 (9·1%) of 2800 receiving endocrine therapy. There were two treatment-related deaths in the abemaciclib plus endocrine therapy group (diarrhoea and pneumonitis) and none in the endocrine therapy alone group.\n\nInterpretation: Adjuvant abemaciclib reduces the risk of recurrence. The benefit is sustained beyond the completion of treatment with an absolute increase at 4 years, further supporting the use of abemaciclib in patients with high-risk hormone receptor-positive, HER2-negative early breast cancer. Further follow-up is needed to establish whether overall survival can be improved with abemaciclib plus endocrine therapy in these patients.\n\nFunding: Eli Lilly.\n\nIndexed on Europe PMC as PubMed record 36493792 (DOI 10.1016/s1470-2045(22)00694-5). Its abstract cites the registry id NCT03155997, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2023, doi: "10.1016/s1470-2045(22)00694-5", pmid: "36493792", authors: "Johnston SRD, Toi M, O'Shaughnessy J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03155997 with the most citations, so it is the natural first reading for anyone following the monarchE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2023","url":"https://doi.org/10.1016/s1470-2045(22)00694-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36493792/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36493792"},{"label":"ClinicalTrials.gov NCT03155997","url":"https://clinicaltrials.gov/study/NCT03155997"}], tags: ["europepmc-ingest"], trials: ["monarche"], journals: ["lancet-oncology"] }),
  p({ id: "paper-monarche-ann-oncol-2026-update", name: "Overall survival with abemaciclib in early breast cancer", tldr: "Later report from the monarchE trial registered as NCT03155997, in Annals of Oncology (2026); its title describes an updated or longer-term analysis.", summary: "Background: Adjuvant abemaciclib combined with endocrine therapy (ET) significantly improved invasive disease-free survival (IDFS) in patients with hormone receptor (HR)-positive, human epidermal growth factor 2 (HER2)-negative, node-positive, high-risk early breast cancer (EBC). The impact on overall survival (OS) remained unknown.\n\nPatients and methods: In the phase III monarchE trial (NCT03155997), patients received ET for at least 5 years with or without abemaciclib for 2 years. In this article, we report the primary OS results, a key secondary endpoint, and updated estimates of IDFS and distant relapse-free survival (DRFS).\n\nResults: Overall, 5637 patients underwent randomization, with 2808 assigned to abemaciclib-ET, and 2829 to ET. In the intent-to-treat population, with a median follow-up of 76.2 months, abemaciclib-ET resulted in a 15.8% lower risk of death than ET [661 deaths; hazard ratio 0.842, 95% confidence interval (CI) 0.722-0.981, P = 0.027], meeting the prespecified boundary for significance. The 7-year OS was 86.8% with abemaciclib-ET and 85.0% with ET (absolute difference, 1.8%). OS benefit was consistent across prespecified subgroups. In addition to patients who had already died of metastatic disease, fewer patients in the abemaciclib-ET arm were living with metastatic disease compared with the ET arm (6.4% versus 9.4%). Sustained improvement was demonstrated in IDFS and DRFS (hazard ratio 0.734, 95% CI 0.657-0.820 and hazard ratio 0.746, 95% CI 0.662-0.840, respectively). Seven-year IDFS was 77.4% with abemaciclib-ET and 70.9% with ET (absolute difference, 6.5%) and 7-year DRFS were 80.0% and 74.9% (absolute difference, 5.1%). The long-term safety data compiled did not support any concerns of delayed toxicities.\n\nConclusions: Adjuvant abemaciclib-ET resulted in a statistically significant and clinically meaningful improvement in OS compared with ET in patients with HR-positive, HER2-negative, node-positive, high-risk EBC. At 7 years, abemaciclib-ET continued to demonstrate a sustained IDFS and DRFS benefit.\n\nIndexed on Europe PMC as PubMed record 41110697 (DOI 10.1016/j.annonc.2025.10.005). Its abstract cites the registry id NCT03155997, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2026, doi: "10.1016/j.annonc.2025.10.005", pmid: "41110697", authors: "Johnston S, Martin M, O'Shaughnessy J, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the monarchE trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2026","url":"https://doi.org/10.1016/j.annonc.2025.10.005"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41110697/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41110697"},{"label":"ClinicalTrials.gov NCT03155997","url":"https://clinicaltrials.gov/study/NCT03155997"}], tags: ["europepmc-ingest"], trials: ["monarche"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nala-j-clin-oncol-2020", name: "Neratinib Plus Capecitabine Versus Lapatinib Plus Capecitabine in HER2-Positive Metastatic Breast Cancer Previously Treated With ≥ 2 HER2-Directed Regimens: Phase III NALA Trial", tldr: "Published report from the NALA trial registered as NCT01808573, in Journal of Clinical Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: NALA (ClinicalTrials.gov identifier: NCT01808573) is a randomized, active-controlled, phase III trial comparing neratinib, an irreversible pan-HER tyrosine kinase inhibitor (TKI), plus capecitabine (N+C) against lapatinib, a reversible dual TKI, plus capecitabine (L+C) in patients with centrally confirmed HER2-positive, metastatic breast cancer (MBC) with ≥ 2 previous HER2-directed MBC regimens.\n\nMethods: Patients, including those with stable, asymptomatic CNS disease, were randomly assigned 1:1 to neratinib (240 mg once every day) plus capecitabine (750 mg/m 2 twice a day 14 d/21 d) with loperamide prophylaxis, or to lapatinib (1,250 mg once every day) plus capecitabine (1,000 mg/m 2 twice a day 14 d/21 d). Coprimary end points were centrally confirmed progression-free survival (PFS) and overall survival (OS). NALA was considered positive if either primary end point was met (α split between end points). Secondary end points were time to CNS disease intervention, investigator-assessed PFS, objective response rate (ORR), duration of response (DoR), clinical benefit rate, safety, and health-related quality of life (HRQoL).\n\nResults: A total of 621 patients from 28 countries were randomly assigned (N+C, n = 307; L+C, n = 314). Centrally reviewed PFS was improved with N+C (hazard ratio [HR], 0.76; 95% CI, 0.63 to 0.93; stratified log-rank P =. 0059). The OS HR was 0.88 (95% CI, 0.72 to 1.07; P =. 2098). Fewer interventions for CNS disease occurred with N+C versus L+C (cumulative incidence, 22.8% v 29.2%; P =. 043). ORRs were N+C 32.8% (95% CI, 27.1 to 38.9) and L+C 26.7% (95% CI, 21.5 to 32.4; P =. 1201); median DoR was 8.5 versus 5.6 months, respectively (HR, 0.50; 95% CI, 0.33 to 0.74; P =.0004). The most common all-grade adverse events were diarrhea (N+C 83% v L+C 66%) and nausea (53% v 42%). Discontinuation rates and HRQoL were similar between groups.\n\nConclusion: N+C significantly improved PFS and time to intervention for CNS disease versus L+C. No new N+C safety signals were observed.\n\nIndexed on Europe PMC as PubMed record 32678716 (DOI 10.1200/jco.20.00147). Its abstract cites the registry id NCT01808573, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2020, doi: "10.1200/jco.20.00147", pmid: "32678716", authors: "Saura C, Oliveira M, Feng YH, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01808573 with the most citations, so it is the natural first reading for anyone following the NALA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2020","url":"https://doi.org/10.1200/jco.20.00147"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32678716/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32678716"},{"label":"ClinicalTrials.gov NCT01808573","url":"https://clinicaltrials.gov/study/NCT01808573"}], tags: ["europepmc-ingest"], trials: ["nala"], journals: ["jco"] }),
  p({ id: "paper-natalee-jama-oncol-2025-update", name: "Ribociclib Plus Endocrine Therapy in Hormone Receptor-Positive/ERBB2-Negative Early Breast Cancer: 4-Year Outcomes From the NATALEE Randomized Clinical Trial", tldr: "Later report from the NATALEE trial registered as NCT03701334, in JAMA Oncology (2025); its title describes an updated or longer-term analysis.", summary: "Importance: Ribociclib plus a nonsteroidal aromatase inhibitor (NSAI) has demonstrated a statistically significant invasive disease-free survival (iDFS) benefit over NSAI alone in patients with hormone receptor-positive/ERBB2 (formerly HER2)-negative early breast cancer. Evaluating the efficacy and safety of adjuvant ribociclib beyond the planned 3-year treatment period is critical for understanding the long-term impact on recurrences.\n\nObjective: To evaluate efficacy and safety of adjuvant ribociclib in an exploratory 4-year analysis of the NATALEE (New Adjuvant Trial With Ribociclib [LEE011]) randomized clinical trial, with all patients no longer receiving ribociclib treatment.\n\nDesign, setting, and participants: This exploratory analysis of an international, open-label, randomized phase 3 trial analyzed adjuvant treatment for premenopausal and postmenopausal women and men with hormone receptor-positive/ERBB2-negative early breast cancer. Eligible patients had anatomic stage IIA (either N0 with additional risk factors or N1 [1-3 axillary lymph nodes]), IIB, or III disease per the American Joint Committee on Cancer Staging Manual, eighth edition. The data cutoff date was April 29, 2024.\n\nInterventions: Patients were randomized 1:1 to receive ribociclib (400 mg once daily, days 1-21 of a 28-day cycle, over 36 months) plus NSAI (letrozole, 2.5 mg, or anastrozole, 1 mg, once daily continuously for 60 months) or NSAI alone. Men and premenopausal women also received goserelin (3.6 mg once every 28 days administered subcutaneously).\n\nMain outcomes and measures: The primary end point was iDFS, and secondary efficacy end points included distant disease-free survival, recurrence-free survival, and overall survival. Survival was evaluated by the Kaplan-Meier method.\n\nResults: Among 5101 patients included in the analysis (median [range] age, 52 [24-90] years; 5081 [99.6%] female), the median follow-up for iDFS was 44.2 months (range, 0-63 months). Ribociclib plus NSAI continued to show iDFS benefit over NSAI alone (hazard ratio, 0.72; 95% CI, 0.61-0.84), with 3-year iDFS rates of 90.8% vs 88.1% (difference, 2.7 percentage points) and 4-year rates of 88.5% vs 83.6% (difference, 4.9 percentage points). The efficacy benefit was consistent across subgroups and secondary end points. Overall survival data remain immature, although a trend in favor of ribociclib plus NSAI over NSAI alone was observed (hazard ratio, 0.83; 95% CI, 0.64-1.07). The incidence of adverse events has remained stable.\n\nConclusions and relevance: This exploratory analysis of the NATALEE randomized clinical trial, with a median follow-up beyond the 3-year treatment duration, demonstrated consistent iDFS benefit with ribociclib plus NSAI over NSAI alone.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT03701334.\n\nIndexed on Europe PMC as PubMed record 40996773 (DOI 10.1001/jamaoncol.2025.3700). Its abstract cites the registry id NCT03701334, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2025, doi: "10.1001/jamaoncol.2025.3700", pmid: "40996773", authors: "Fasching PA, Stroyakovskiy D, Yardley DA, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the NATALEE trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"JAMA Oncol 2025","url":"https://doi.org/10.1001/jamaoncol.2025.3700"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40996773/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40996773"},{"label":"ClinicalTrials.gov NCT03701334","url":"https://clinicaltrials.gov/study/NCT03701334"}], tags: ["europepmc-ingest"], trials: ["natalee"], journals: ["jama-oncology"] }),
  p({ id: "paper-neosphere-lancet-oncol-2012", name: "Efficacy and safety of neoadjuvant pertuzumab and trastuzumab in women with locally advanced, inflammatory, or early HER2-positive breast cancer (NeoSphere): a randomised multicentre, open-label, phase 2 trial", tldr: "Published report from the NeoSphere trial registered as NCT00545688, in The Lancet Oncology (2012), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Studies with pertuzumab, a novel anti-HER2 antibody, show improved efficacy when combined with the established HER2-directed antibody trastuzumab in breast cancer therapy. We investigated the combination of pertuzumab or trastuzumab, or both, with docetaxel and the combination of pertuzumab and trastuzumab without chemotherapy in the neoadjuvant setting.\n\nMethods: In this multicentre, open-label, phase 2 study, treatment-naive women with HER2-positive breast cancer were randomly assigned (1:1:1:1) centrally and stratified by operable, locally advanced, and inflammatory breast cancer, and by hormone receptor expression to receive four neoadjuvant cycles of: trastuzumab (8 mg/kg loading dose, followed by 6 mg/kg every 3 weeks) plus docetaxel (75 mg/m(2), escalating, if tolerated, to 100 mg/m(2) every 3 weeks; group A) or pertuzumab (loading dose 840 mg, followed by 420 mg every 3 weeks) and trastuzumab plus docetaxel (group B) or pertuzumab and trastuzumab (group C) or pertuzumab plus docetaxel (group D). The primary endpoint, examined in the intention-to-treat population, was pathological complete response in the breast. Neither patients nor investigators were masked to treatment. This study is registered with ClinicalTrials.gov, number NCT00545688.\n\nFindings: Of 417 eligible patients, 107 were randomly assigned to group A, 107 to group B, 107 to group C, and 96 to group D. Patients given pertuzumab and trastuzumab plus docetaxel (group B) had a significantly improved pathological complete response rate (49 of 107 patients; 45·8% [95% CI 36·1-55·7]) compared with those given trastuzumab plus docetaxel (group A; 31 of 107; 29·0% [20·6-38·5]; p=0·0141). 23 of 96 (24·0% [15·8-33·7]) women given pertuzumab plus docetaxel (group D) had a pathological complete response, as did 18 of 107 (16·8% [10·3-25·3]) given pertuzumab and trastuzumab (group C). The most common adverse events of grade 3 or higher were neutropenia (61 of 107 women in group A, 48 of 107 in group B, one of 108 in group C, and 52 of 94 in group D), febrile neutropenia (eight, nine, none, and seven, respectively), and leucopenia (13, five, none, and seven, respectively). The number of serious adverse events was similar in groups A, B, and D (15-20 serious adverse events per group in 10-17% of patients) but lower in group C (four serious adverse events in 4% of patients).\n\nInterpretation: Patients given pertuzumab and trastuzumab plus docetaxel (group B) had a significantly improved pathological complete response rate compared with those given trastuzumab plus docetaxel, without substantial differences in tolerability. Pertuzumab and trastuzumab without chemotherapy eradicated tumours in a proportion of women and showed a favourable safety profile. These findings justify further exploration in adjuvant trials and support the neoadjuvant approach for accelerating drug assessment in early breast cancer.\n\nFunding: F Hoffmann-La Roche.\n\nIndexed on Europe PMC as PubMed record 22153890 (DOI 10.1016/s1470-2045(11)70336-9). Its abstract cites the registry id NCT00545688, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2012, doi: "10.1016/s1470-2045(11)70336-9", pmid: "22153890", authors: "Gianni L, Pienkowski T, Im YH, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00545688 with the most citations, so it is the natural first reading for anyone following the NeoSphere trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2012","url":"https://doi.org/10.1016/s1470-2045(11)70336-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/22153890/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/22153890"},{"label":"ClinicalTrials.gov NCT00545688","url":"https://clinicaltrials.gov/study/NCT00545688"}], tags: ["europepmc-ingest"], trials: ["neosphere"], journals: ["lancet-oncology"] }),
  p({ id: "paper-neosphere-lancet-oncol-2016-update", name: "5-year analysis of neoadjuvant pertuzumab and trastuzumab in patients with locally advanced, inflammatory, or early-stage HER2-positive breast cancer (NeoSphere): a multicentre, open-label, phase 2 randomised trial", tldr: "Later report from the NeoSphere trial registered as NCT00545688, in The Lancet Oncology (2016); its title describes an updated or longer-term analysis.", summary: "Background: In the primary analysis of the NeoSphere trial, patients given neoadjuvant pertuzumab, trastuzumab, and docetaxel showed a significantly improved pathological complete response compared with those given trastuzumab and docetaxel after surgery. Here, we report 5-year progression-free survival, disease-free survival, and safety.\n\nMethods: In this multicentre, open-label, phase 2 randomised trial in hospitals and medical clinics, treatment-naive adults with locally advanced, inflammatory, or early-stage HER2-positive breast cancer were randomly assigned (1:1:1:1) to receive four neoadjuvant cycles of trastuzumab (8 mg/kg loading dose, followed by 6 mg/kg every 3 weeks) plus docetaxel (75 mg/m(2) every 3 weeks, increasing to 100 mg/m(2) from cycle 2 if tolerated; group A), pertuzumab (840 mg loading dose, followed by 420 mg every 3 weeks) and trastuzumab plus docetaxel (group B), pertuzumab and trastuzumab (group C), or pertuzumab and docetaxel (group D). After surgery, patients received three cycles of FEC (fluorouracil 600 mg/m(2), epirubicin 90 mg/m(2), and cyclophosphamide 600 mg/m(2)) every 3 weeks (patients in group C received four cycles of docetaxel prior to FEC), and trastuzumab 6 mg/kg every 3 weeks to complete 1 year's treatment (17 cycles in total). Randomisation was done by a central centre using dynamic allocation, stratified by operable, locally advanced, and inflammatory breast cancer, and by oestrogen and/or progesterone receptor positivity. Safety analyses were done according to treatment received. The primary endpoint (pathological complete response) was previously reported; secondary endpoints reported here are 5-year progression-free survival (analysed in the intention-to-treat population) and disease-free survival (analysed in patients who had surgery). Secondary and exploratory analyses were not powered for formal statistical hypothesis testing, and therefore results are for descriptive purposes only. The study ended on Sept 22, 2014 (last patient, last visit). This study is registered with ClinicalTrials.gov, number NCT00545688.\n\nFindings: Between Dec 17, 2007, and Dec 22, 2009, 417 eligible patients were randomly assigned to group A (107 patients), group B (107 patients), group C (107 patients), or group D (96 patients). One patient in group A withdrew before treatment. One patient assigned to group D received group A treatment, one patient assigned to group D received group B treatment, and one patient assigned to group B received group C treatment. At clinical cutoff, 87 patients had progressed or died. 5-year progression-free survival rates were 81% (95% CI 71-87) for group A, 86% (77-91) for group B, 73% (64-81) for group C, and 73% (63-81) for group D (hazard ratios 0·69 [95% CI 0·34-1·40] group B vs group A, 1·25 [0·68-2·30] group C vs group A, and 2·05 [1·07-3·93] group D vs group B). Disease-free survival results were consistent with progression-free survival results and were 81% (95% CI 72-88) for group A, 84% (72-91) for group B, 80% (70-86) for group C, and 75% (64-83) for group D. Patients who achieved total pathological complete response (all groups combined) had longer progression-free survival compared with patients who did not (85% [76-91] in patients who achieved total pathological response vs 76% [71-81] in patients who did not achieve total pathological response; hazard ratio 0·54 [95% CI 0·29-1·00]). There were no new or long-term safety concerns and tolerability was similar across groups (neoadjuvant and adjuvant treatment periods combined). The most common grade 3 or worse adverse events were neutropenia (group A: 71 [66%] of 107 patients; group B: 59 [55%] of 107; group C: 40 [37%] of 108; group D: 60 [64%] of 94), febrile neutropenia (group A: 10 [9%]; group B: 12 [11%]; group C: 5 [5%]; group D: 15 [16%]), and leucopenia (group A: 13 [12%]; group B: 6 [6%]; group C: 4 [4%]; group D: 8 [9%]). The number of patients with one or more serious adverse event was similar across groups (19-22 serious adverse events per group in 18-22% of patients).\n\nInterpretation: Progression-free survival and disease-free survival at 5-year follow-up show large and overlapping CIs, but support the primary endpoint (pathological complete response) and suggest that neoadjuvant pertuzumab is beneficial when combined with trastuzumab and docetaxel. Additionally, they suggest that total pathological complete response could be an early indicator of long-term outcome in early-stage HER2-positive breast cancer.\n\nFunding: F Hoffmann-La Roche.\n\nIndexed on Europe PMC as PubMed record 27179402 (DOI 10.1016/s1470-2045(16)00163-7). Its abstract cites the registry id NCT00545688, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2016, doi: "10.1016/s1470-2045(16)00163-7", pmid: "27179402", authors: "Gianni L, Pienkowski T, Im YH, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the NeoSphere trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2016","url":"https://doi.org/10.1016/s1470-2045(16)00163-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/27179402/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/27179402"},{"label":"ClinicalTrials.gov NCT00545688","url":"https://clinicaltrials.gov/study/NCT00545688"}], tags: ["europepmc-ingest"], trials: ["neosphere"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nsabp-b39-lancet-2019", name: "Long-term primary results of accelerated partial breast irradiation after breast-conserving surgery for early-stage breast cancer: a randomised, phase 3, equivalence trial", tldr: "Published report from the NSABP B-39 trial registered as NCT00103181, in The Lancet (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Whole-breast irradiation after breast-conserving surgery for patients with early-stage breast cancer decreases ipsilateral breast-tumour recurrence (IBTR), yielding comparable results to mastectomy. It is unknown whether accelerated partial breast irradiation (APBI) to only the tumour-bearing quadrant, which shortens treatment duration, is equally effective. In our trial, we investigated whether APBI provides equivalent local tumour control after lumpectomy compared with whole-breast irradiation.\n\nMethods: We did this randomised, phase 3, equivalence trial (NSABP B-39/RTOG 0413) in 154 clinical centres in the USA, Canada, Ireland, and Israel. Adult women (>18 years) with early-stage (0, I, or II; no evidence of distant metastases, but up to three axillary nodes could be positive) breast cancer (tumour size ≤3 cm; including all histologies and multifocal breast cancers), who had had lumpectomy with negative (ie, no detectable cancer cells) surgical margins, were randomly assigned (1:1) using a biased-coin-based minimisation algorithm to receive either whole-breast irradiation (whole-breast irradiation group) or APBI (APBI group). Whole-breast irradiation was delivered in 25 daily fractions of 50 Gy over 5 weeks, with or without a supplemental boost to the tumour bed, and APBI was delivered as 34 Gy of brachytherapy or 38·5 Gy of external bream radiation therapy in 10 fractions, over 5 treatment days within an 8-day period. Randomisation was stratified by disease stage, menopausal status, hormone-receptor status, and intention to receive chemotherapy. Patients, investigators, and statisticians could not be masked to treatment allocation. The primary outcome of invasive and non-invasive IBTR as a first recurrence was analysed in the intention-to-treat population, excluding those patients who were lost to follow-up, with an equivalency test on the basis of a 50% margin increase in the hazard ratio (90% CI for the observed HR between 0·667 and 1·5 for equivalence) and a Cox proportional hazard model. Survival was assessed by intention to treat, and sensitivity analyses were done in the per-protocol population. This trial is registered with ClinicalTrials.gov, NCT00103181.\n\nFindings: Between March 21, 2005, and April 16, 2013, 4216 women were enrolled. 2109 were assigned to the whole-breast irradiation group and 2107 were assigned to the APBI group. 70 patients from the whole-breast irradiation group and 14 from the APBI group withdrew consent or were lost to follow-up at this stage, so 2039 and 2093 patients respectively were available for survival analysis. Further, three and four patients respectively were lost to clinical follow-up (ie, survival status was assessed by phone but no physical examination was done), leaving 2036 patients in the whole-breast irradiation group and 2089 in the APBI group evaluable for the primary outcome. At a median follow-up of 10·2 years (IQR 7·5-11·5), 90 (4%) of 2089 women eligible for the primary outcome in the APBI group and 71 (3%) of 2036 women in the whole-breast irradiation group had an IBTR (HR 1·22, 90% CI 0·94-1·58). The 10-year cumulative incidence of IBTR was 4·6% (95% CI 3·7-5·7) in the APBI group versus 3·9% (3·1-5·0) in the whole-breast irradiation group. 44 (2%) of 2039 patients in the whole-breast irradiation group and 49 (2%) of 2093 patients in the APBI group died from recurring breast cancer. There were no treatment-related deaths. Second cancers and treatment-related toxicities were similar between the two groups. 2020 patients in the whole-breast irradiation group and 2089 in APBI group had available data on adverse events. The highest toxicity grade reported was: grade 1 in 845 (40%), grade 2 in 921 (44%), and grade 3 in 201 (10%) patients in the APBI group, compared with grade 1 in 626 (31%), grade 2 in 1193 (59%), and grade 3 in 143 (7%) in the whole-breast irradiation group.\n\nInterpretation: APBI did not meet the criteria for equivalence to whole-breast irradiation in controlling IBTR for breast-conserving therapy. Our trial had broad eligibility criteria, leading to a large, heterogeneous pool of patients and sufficient power to detect treatment equivalence, but was not designed to test equivalence in patient subgroups or outcomes from different APBI techniques. For patients with early-stage breast cancer, our findings support whole-breast irradiation following lumpectomy; however, with an absolute difference of less than 1% in the 10-year cumulative incidence of IBTR, APBI might be an acceptable alternative for some women.\n\nFunding: National Cancer Institute, US Department of Health and Human Services.\n\nIndexed on Europe PMC as PubMed record 31813636 (DOI 10.1016/s0140-6736(19)32514-0). Its abstract cites the registry id NCT00103181, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2019, doi: "10.1016/s0140-6736(19)32514-0", pmid: "31813636", authors: "Vicini FA, Cecchini RS, White JR, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00103181 with the most citations, so it is the natural first reading for anyone following the NSABP B-39 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2019","url":"https://doi.org/10.1016/s0140-6736(19)32514-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31813636/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31813636"},{"label":"ClinicalTrials.gov NCT00103181","url":"https://clinicaltrials.gov/study/NCT00103181"}], tags: ["europepmc-ingest"], trials: ["nsabp-b39"], journals: ["lancet"] }),
  p({ id: "paper-olympiad-ann-oncol-2019-update", name: "OlympiAD final overall survival and tolerability results: Olaparib versus chemotherapy treatment of physician's choice in patients with a germline BRCA mutation and HER2-negative metastatic breast cancer", tldr: "Later report from the OlympiAD trial registered as NCT02000622, in Annals of Oncology (2019); its title describes an updated or longer-term analysis.", summary: "Background: In the OlympiAD study, olaparib was shown to improve progression-free survival compared with chemotherapy treatment of physician's choice (TPC) in patients with a germline BRCA1 and/or BRCA2 mutation (BRCAm) and human epidermal growth factor receptor 2 (HER2)-negative metastatic breast cancer (mBC). We now report the planned final overall survival (OS) results, and describe the most common adverse events (AEs) to better understand olaparib tolerability in this population.\n\nPatients and methods: OlympiAD, a Phase III, randomized, controlled, open-label study (NCT02000622), enrolled patients with a germline BRCAm and HER2-negative mBC who had received ≤2 lines of chemotherapy for mBC. Patients were randomized to olaparib tablets (300 mg bid) or predeclared TPC (capecitabine, vinorelbine, or eribulin). OS and safety were secondary end points.\n\nResults: A total of 205 patients were randomized to olaparib and 97 to TPC. At 64% data maturity, median OS was 19.3 months with olaparib versus 17.1 months with TPC (HR 0.90, 95% CI 0.66-1.23; P = 0.513); median follow-up was 25.3 and 26.3 months, respectively. HR for OS with olaparib versus TPC in prespecified subgroups were: prior chemotherapy for mBC [no (first-line setting): 0.51, 95% CI 0.29-0.90; yes (second/third-line): 1.13, 0.79-1.64]; receptor status (triple negative: 0.93, 0.62-1.43; hormone receptor positive: 0.86, 0.55-1.36); prior platinum (yes: 0.83, 0.49-1.45; no: 0.91, 0.64-1.33). Adverse events during olaparib treatment were generally low grade and manageable by supportive treatment or dose modification. There was a low rate of treatment discontinuation (4.9%), and the risk of developing anemia did not increase with extended olaparib exposure.\n\nConclusions: While there was no statistically significant improvement in OS with olaparib compared to TPC, there was the possibility of meaningful OS benefit among patients who had not received chemotherapy for metastatic disease. Olaparib was generally well-tolerated, with no evidence of cumulative toxicity during extended exposure. Please see the article online for additional video content.\n\nIndexed on Europe PMC as PubMed record 30689707 (DOI 10.1093/annonc/mdz012). Its abstract cites the registry id NCT02000622, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2019, doi: "10.1093/annonc/mdz012", pmid: "30689707", authors: "Robson ME, Tung N, Conte P, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the OlympiAD trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2019","url":"https://doi.org/10.1093/annonc/mdz012"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30689707/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30689707"},{"label":"ClinicalTrials.gov NCT02000622","url":"https://clinicaltrials.gov/study/NCT02000622"}], tags: ["europepmc-ingest"], trials: ["olympiad"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-pallas-penelope-b-lancet-oncol-2021", name: "Palbociclib with adjuvant endocrine therapy in early breast cancer (PALLAS): interim analysis of a multicentre, open-label, randomised, phase 3 study", tldr: "Published report from the PALLAS trial registered as NCT02513394, in The Lancet Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Palbociclib added to endocrine therapy improves progression-free survival in hormone-receptor-positive, HER2-negative, metastatic breast cancer. The PALLAS trial aimed to investigate whether the addition of 2 years of palbociclib to adjuvant endocrine therapy improves invasive disease-free survival over endocrine therapy alone in patients with hormone-receptor-positive, HER2-negative, early-stage breast cancer.\n\nMethods: PALLAS is an ongoing multicentre, open-label, randomised, phase 3 study that enrolled patients at 406 cancer centres in 21 countries worldwide with stage II-III histologically confirmed hormone-receptor-positive, HER2-negative breast cancer, within 12 months of initial diagnosis. Eligible patients were aged 18 years or older with an Eastern Cooperative Oncology Group performance score of 0 or 1. Patients were randomly assigned (1:1) in permuted blocks of random size (4 or 6), stratified by anatomic stage, previous chemotherapy, age, and geographical region, by use of central telephone-based and web-based interactive response technology, to receive either 2 years of palbociclib (125 mg orally once daily on days 1-21 of a 28-day cycle) with ongoing standard provider or patient-choice adjuvant endocrine therapy (tamoxifen or aromatase inhibitor, with or without concurrent luteinising hormone-releasing hormone agonist), or endocrine therapy alone, without masking. The primary endpoint of the study was invasive disease-free survival in the intention-to-treat population. Safety was assessed in all randomly assigned patients who started palbociclib or endocrine therapy. This report presents results from the second pre-planned interim analysis triggered on Jan 9, 2020, when 67% of the total number of expected invasive disease-free survival events had been observed. The trial is registered with ClinicalTrials.gov (NCT02513394) and EudraCT (2014-005181-30).\n\nFindings: Between Sept 1, 2015, and Nov 30, 2018, 5760 patients were randomly assigned to receive palbociclib plus endocrine therapy (n=2883) or endocrine therapy alone (n=2877). At the time of the planned second interim analysis, at a median follow-up of 23·7 months (IQR 16·9-29·2), 170 of 2883 patients assigned to palbociclib plus endocrine therapy and 181 of 2877 assigned to endocrine therapy alone had invasive disease-free survival events. 3-year invasive disease-free survival was 88·2% (95% CI 85·2-90·6) for palbociclib plus endocrine therapy and 88·5% (85·8-90·7) for endocrine therapy alone (hazard ratio 0·93 [95% CI 0·76-1·15]; log-rank p=0·51). As the test statistic comparing invasive disease-free survival between groups crossed the prespecified futility boundary, the independent data monitoring committee recommended discontinuation of palbociclib in patients still receiving palbociclib and endocrine therapy. The most common grade 3-4 adverse events were neutropenia (1742 [61·3%] of 2840 patients on palbociclib and endocrine therapy vs 11 [0·3%] of 2903 on endocrine therapy alone), leucopenia (857 [30·2%] vs three [0·1%]), and fatigue (60 [2·1%] vs ten [0·3%]). Serious adverse events occurred in 351 (12·4%) of 2840 patients on palbociclib plus endocrine therapy versus 220 (7·6%) of 2903 patients on endocrine therapy alone. There were no treatment-related deaths.\n\nInterpretation: At the planned second interim analysis, addition of 2 years of adjuvant palbociclib to adjuvant endocrine therapy did not improve invasive disease-free survival compared with adjuvant endocrine therapy alone. On the basis of these findings, this regimen cannot be recommended in the adjuvant setting. Long-term follow-up of the PALLAS population and correlative studies are ongoing.\n\nFunding: Pfizer.\n\nIndexed on Europe PMC as PubMed record 33460574 (DOI 10.1016/s1470-2045(20)30642-2). Its abstract cites the registry id NCT02513394, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2021, doi: "10.1016/s1470-2045(20)30642-2", pmid: "33460574", authors: "Mayer EL, Dueck AC, Martin M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02513394 with the most citations, so it is the natural first reading for anyone following the PALLAS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2021","url":"https://doi.org/10.1016/s1470-2045(20)30642-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33460574/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33460574"},{"label":"ClinicalTrials.gov NCT02513394","url":"https://clinicaltrials.gov/study/NCT02513394"}], tags: ["europepmc-ingest"], trials: ["pallas-penelope-b"], journals: ["lancet-oncology"] }),
  p({ id: "paper-paloma-2-n-engl-j-med-2016", name: "Palbociclib and Letrozole in Advanced Breast Cancer", tldr: "Published report from the PALOMA-2 trial registered as NCT01740427, in New England Journal of Medicine (2016), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: A phase 2 study showed that progression-free survival was longer with palbociclib plus letrozole than with letrozole alone in the initial treatment of postmenopausal women with estrogen-receptor (ER)-positive, human epidermal growth factor receptor 2 (HER2)-negative advanced breast cancer. We performed a phase 3 study that was designed to confirm and expand the efficacy and safety data for palbociclib plus letrozole for this indication.\n\nMethods: In this double-blind study, we randomly assigned, in a 2:1 ratio, 666 postmenopausal women with ER-positive, HER2-negative breast cancer, who had not had prior treatment for advanced disease, to receive palbociclib plus letrozole or placebo plus letrozole. The primary end point was progression-free survival, as assessed by the investigators; secondary end points were overall survival, objective response, clinical benefit response, patient-reported outcomes, pharmacokinetic effects, and safety.\n\nResults: The median progression-free survival was 24.8 months (95% confidence interval [CI], 22.1 to not estimable) in the palbociclib-letrozole group, as compared with 14.5 months (95% CI, 12.9 to 17.1) in the placebo-letrozole group (hazard ratio for disease progression or death, 0.58; 95% CI, 0.46 to 0.72; P<0.001). The most common grade 3 or 4 adverse events were neutropenia (occurring in 66.4% of the patients in the palbociclib-letrozole group vs. 1.4% in the placebo-letrozole group), leukopenia (24.8% vs. 0%), anemia (5.4% vs. 1.8%), and fatigue (1.8% vs. 0.5%). Febrile neutropenia was reported in 1.8% of patients in the palbociclib-letrozole group and in none of the patients in the placebo-letrozole group. Permanent discontinuation of any study treatment as a result of adverse events occurred in 43 patients (9.7%) in the palbociclib-letrozole group and in 13 patients (5.9%) in the placebo-letrozole group.\n\nConclusions: Among patients with previously untreated ER-positive, HER2-negative advanced breast cancer, palbociclib combined with letrozole resulted in significantly longer progression-free survival than that with letrozole alone, although the rates of myelotoxic effects were higher with palbociclib-letrozole. (Funded by Pfizer; PALOMA-2 ClinicalTrials.gov number, NCT01740427.).\n\nIndexed on Europe PMC as PubMed record 27959613 (DOI 10.1056/nejmoa1607303). Its abstract cites the registry id NCT01740427, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2016, doi: "10.1056/nejmoa1607303", pmid: "27959613", authors: "Finn RS, Martin M, Rugo HS, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01740427 with the most citations, so it is the natural first reading for anyone following the PALOMA-2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2016","url":"https://doi.org/10.1056/nejmoa1607303"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/27959613/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/27959613"},{"label":"ClinicalTrials.gov NCT01740427","url":"https://clinicaltrials.gov/study/NCT01740427"}], tags: ["europepmc-ingest"], trials: ["paloma-2"], journals: ["nejm"] }),
  p({ id: "paper-paloma-2-breast-cancer-res-treat-2019-update", name: "Palbociclib plus letrozole as first-line therapy in estrogen receptor-positive/human epidermal growth factor receptor 2-negative advanced breast cancer with extended follow-up", tldr: "Later report from the PALOMA-2 trial registered as NCT01740427, in Breast cancer research and treatment (2019); its title describes an updated or longer-term analysis.", summary: "Purpose: In the initial PALOMA-2 (NCT01740427) analysis with median follow-up of 23 months, palbociclib plus letrozole significantly prolonged progression-free survival (PFS) in women with estrogen receptor-positive (ER+)/human epidermal growth factor receptor 2-negative (HER2-) advanced breast cancer (ABC) [hazard ratio (HR) 0.58; P < 0.001]. Herein, we report results overall and by subgroups with extended follow-up.\n\nMethods: In this double-blind, phase 3 study, post-menopausal women with ER+/HER2- ABC who had not received prior systemic therapy for their advanced disease were randomized 2:1 to palbociclib-letrozole or placebo-letrozole. Endpoints include investigator-assessed PFS (primary), safety, and patient-reported outcomes (PROs).\n\nResults: After a median follow-up of approximately 38 months, median PFS was 27.6 months for palbociclib-letrozole (n = 444) and 14.5 months for placebo-letrozole (n = 222) (HR 0.563; 1-sided P < 0.0001). All subgroups benefited from palbociclib treatment. The improvement of PFS with palbociclib-letrozole was maintained in the next 2 subsequent lines of therapy and delayed the use of chemotherapy (40.4 vs. 29.9 months for palbociclib-letrozole vs. placebo-letrozole). Safety data were consistent with the known profile. Patients' quality of life was maintained.\n\nConclusions: With approximately 15 months of additional follow-up, palbociclib plus letrozole continued to demonstrate improved PFS compared with placebo plus letrozole in the overall population and across all patient subgroups, while the safety profile remained favorable and quality of life was maintained. These data confirm that palbociclib-letrozole should be considered the standard of care for first-line therapy in patients with ER+/HER2- ABC, including those with low disease burden or long disease-free interval. Sponsored by Pfizer; ClinicalTrials.gov: NCT01740427.\n\nIndexed on Europe PMC as PubMed record 30632023 (DOI 10.1007/s10549-018-05125-4). Its abstract cites the registry id NCT01740427, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Breast cancer research and treatment", year: 2019, doi: "10.1007/s10549-018-05125-4", pmid: "30632023", authors: "Rugo HS, Finn RS, Diéras V, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the PALOMA-2 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Breast Cancer Res Treat 2019","url":"https://doi.org/10.1007/s10549-018-05125-4"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30632023/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30632023"},{"label":"ClinicalTrials.gov NCT01740427","url":"https://clinicaltrials.gov/study/NCT01740427"}], tags: ["europepmc-ingest"], trials: ["paloma-2"], journals: ["breast-cancer-research-and-treatment"] }),
  p({ id: "paper-patina-n-engl-j-med-2026", name: "Palbociclib for Hormone-Receptor-Positive, HER2-Positive Advanced Breast Cancer", tldr: "Published report from the PATINA trial registered as NCT02947685, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Dual anti-human epidermal growth factor receptor 2 (HER2) therapy plus chemotherapy followed by maintenance treatment with HER2-targeted and endocrine therapies is standard first-line treatment for hormone-receptor-positive, HER2-positive metastatic breast cancer. On the basis of preclinical and clinical data, the addition of palbociclib (a selective inhibitor of cyclin-dependent kinases 4 and 6) may overcome resistance to both endocrine and HER2-directed therapies.\n\nMethods: In this phase 3, open-label, randomized trial, we enrolled patients with hormone-receptor-positive, HER2-positive metastatic breast cancer who did not have disease progression after four to eight cycles of chemotherapy plus HER2-targeted therapy. Patients were randomly assigned in a 1:1 ratio to receive maintenance HER2-targeted and endocrine therapies with or without palbociclib. The primary end point was investigator-assessed progression-free survival. Secondary end points included the objective response, clinical benefit, safety, and overall survival.\n\nResults: A total of 518 patients underwent randomization: 261 were assigned to receive palbociclib and 257 to receive standard therapy. At a median follow-up of 53.5 months, patients in the palbociclib group had significantly longer progression-free survival than those in the standard-therapy group (median duration, 44.3 months vs. 29.1 months; hazard ratio for disease progression or death, 0.75; 95% confidence interval, 0.59 to 0.96; two-sided P = 0.02). Grade 3 and 4 adverse events, predominantly from neutropenia, occurred in 79.7% and 10.0% of the patients, respectively, in the palbociclib group, as compared with 30.6% and 3.6% of the patients, respectively, in the standard-therapy group.\n\nConclusions: The addition of palbociclib to maintenance anti-HER2 and endocrine therapies led to a significant improvement in progression-free survival over standard therapy, with increased toxic effects, mainly neutropenia. (Funded by Pfizer and others; PATINA ClinicalTrials.gov number, NCT02947685.).\n\nIndexed on Europe PMC as PubMed record 41604639 (DOI 10.1056/nejmoa2511218). Its abstract cites the registry id NCT02947685, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2511218", pmid: "41604639", authors: "Metzger O, Mandrekar S, Goel S, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02947685 with the most citations, so it is the natural first reading for anyone following the PATINA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2511218"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41604639/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41604639"},{"label":"ClinicalTrials.gov NCT02947685","url":"https://clinicaltrials.gov/study/NCT02947685"}], tags: ["europepmc-ingest"], trials: ["patina"], journals: ["nejm"] }),
  p({ id: "paper-penelope-b-j-clin-oncol-2021", name: "Palbociclib for Residual High-Risk Invasive HR-Positive and HER2-Negative Early Breast Cancer-The Penelope-B Trial", tldr: "Published report from the PENELOPE-B trial registered as NCT01864746, in Journal of Clinical Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: About one third of patients with hormone receptor-positive, human epidermal growth factor receptor 2-negative breast cancer who have residual invasive disease after neoadjuvant chemotherapy (NACT) will relapse. Thus, additional therapy is needed. Palbociclib is a cyclin-dependent kinase 4 and 6 inhibitor demonstrating efficacy in the metastatic setting.\n\nPatients and methods: PENELOPE-B (NCT01864746) is a double-blind, placebo-controlled, phase III study in women with hormone receptor-positive, human epidermal growth factor receptor 2-negative primary breast cancer without a pathological complete response after taxane-containing NACT and at high risk of relapse (clinical pathological staging-estrogen receptor grading score ≥ 3 or 2 and ypN+). Patients were randomly assigned (1:1) to receive 13 cycles of palbociclib 125 mg once daily or placebo on days 1-21 in a 28-day cycle in addition to endocrine therapy (ET). Primary end point is invasive disease-free survival (iDFS). Final analysis was planned after 290 iDFS events with a two-sided efficacy boundary P <.0463 because of two interim analyses.\n\nResults: One thousand two hundred fifty patients were randomly assigned. The median age was 49.0 years (range, 19-79), and the majority were ypN+ with Ki-67 ≤ 15%; 59.4% of patients had a clinical pathological staging-estrogen receptor grading score ≥ 3. 50.1% received aromatase inhibitor, and 33% of premenopausal women received a luteinizing hormone releasing hormone analog in addition to either tamoxifen or an aromatase inhibitor. After a median follow-up of 42.8 months (92% complete), 308 events were confirmed. Palbociclib did not improve iDFS versus placebo added to ET-stratified hazard ratio, 0.93 (95% repeated CI, 0.74 to 1.17) and two-sided weighted log-rank test (Cui, Hung, and Wang) P =.525. There was no difference among the subgroups. Most common related serious adverse events were infections and vascular disorders in 113 (9.1%) patients with no difference between the treatment arms. Eight fatal serious adverse events (two palbociclib and six placebo) were reported.\n\nConclusion: Palbociclib for 1 year in addition to ET did not improve iDFS in women with residual invasive disease after NACT.\n\nIndexed on Europe PMC as PubMed record 33793299 (DOI 10.1200/jco.20.03639). Its abstract cites the registry id NCT01864746, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2021, doi: "10.1200/jco.20.03639", pmid: "33793299", authors: "Loibl S, Marmé F, Martin M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01864746 with the most citations, so it is the natural first reading for anyone following the PENELOPE-B trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2021","url":"https://doi.org/10.1200/jco.20.03639"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33793299/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33793299"},{"label":"ClinicalTrials.gov NCT01864746","url":"https://clinicaltrials.gov/study/NCT01864746"}], tags: ["europepmc-ingest"], trials: ["penelope-b"], journals: ["jco"] }),
  p({ id: "paper-persephone-lancet-2019", name: "6 versus 12 months of adjuvant trastuzumab for HER2-positive early breast cancer (PERSEPHONE): 4-year disease-free survival results of a randomised phase 3 non-inferiority trial", tldr: "Published report from the PERSEPHONE trial registered as NCT00712140, in The Lancet (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Adjuvant trastuzumab significantly improves outcomes for patients with HER2-positive early breast cancer. The standard treatment duration is 12 months but shorter treatment could provide similar efficacy while reducing toxicities and cost. We aimed to investigate whether 6-month adjuvant trastuzumab treatment is non-inferior to the standard 12-month treatment regarding disease-free survival.\n\nMethods: This study is an open-label, randomised phase 3 non-inferiority trial. Patients were recruited from 152 centres in the UK. We randomly assigned patients with HER2-positive early breast cancer, aged 18 years or older, and with a clear indication for chemotherapy, by a computerised minimisation process (1:1), to receive either 6-month or 12-month trastuzumab delivered every 3 weeks intravenously (loading dose of 8 mg/kg followed by maintenance doses of 6 mg/kg) or subcutaneously (600 mg), given in combination with chemotherapy (concurrently or sequentially). The primary endpoint was disease-free survival, analysed by intention to treat, with a non-inferiority margin of 3% for 4-year disease-free survival. Safety was analysed in all patients who received trastuzumab. This trial is registered with EudraCT (number 2006-007018-39), ISRCTN (number 52968807), and ClinicalTrials.gov (number NCT00712140).\n\nFindings: Between Oct 4, 2007, and July 31, 2015, 2045 patients were assigned to 12-month trastuzumab treatment and 2044 to 6-month treatment (one patient was excluded because they were double randomised). Median follow-up was 5·4 years (IQR 3·6-6·7) for both treatment groups, during which a disease-free survival event occurred in 265 (13%) of 2043 patients in the 6-month group and 247 (12%) of 2045 patients in the 12-month group. 4-year disease-free survival was 89·4% (95% CI 87·9-90·7) in the 6-month group and 89·8% (88·3-91·1) in the 12-month group (hazard ratio 1·07 [90% CI 0·93-1·24], non-inferiority p=0·011), showing non-inferiority of the 6-month treatment. 6-month trastuzumab treatment resulted in fewer patients reporting severe adverse events (373 [19%] of 1939 patients vs 459 [24%] of 1894 patients, p=0·0002) or stopping early because of cardiotoxicity (61 [3%] of 1939 patients vs 146 [8%] of 1894 patients, p<0·0001).\n\nInterpretation: We have shown that 6-month trastuzumab treatment is non-inferior to 12-month treatment in patients with HER2-positive early breast cancer, with less cardiotoxicity and fewer severe adverse events. These results support consideration of reduced duration trastuzumab for women at similar risk of recurrence as to those included in the trial.\n\nFunding: UK National Institute for Health Research, Health Technology Assessment Programme.\n\nIndexed on Europe PMC as PubMed record 31178152 (DOI 10.1016/s0140-6736(19)30650-6). Its abstract cites the registry id NCT00712140, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2019, doi: "10.1016/s0140-6736(19)30650-6", pmid: "31178152", authors: "Earl HM, Hiller L, Vallier AL, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00712140 with the most citations, so it is the natural first reading for anyone following the PERSEPHONE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2019","url":"https://doi.org/10.1016/s0140-6736(19)30650-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31178152/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31178152"},{"label":"ClinicalTrials.gov NCT00712140","url":"https://clinicaltrials.gov/study/NCT00712140"}], tags: ["europepmc-ingest"], trials: ["persephone"], journals: ["lancet"] }),
  p({ id: "paper-phergain-lancet-oncol-2021", name: "Chemotherapy de-escalation using an 18 F-FDG-PET-based pathological response-adapted strategy in patients with HER2-positive early breast cancer (PHERGain): a multicentre, randomised, open-label, non-comparative, phase 2 trial", tldr: "Published report from the PHERGain trial registered as NCT03161353, in The Lancet Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Several de-escalation approaches are under investigation in patients with HER2-positive, early-stage breast cancer. We assessed early metabolic responses to neoadjuvant trastuzumab and pertuzumab using 18 F-fluorodeoxyglucose ( 18 F-FDG)-PET ( 18 F-FDG-PET) and the possibility of chemotherapy de-escalation using a pathological response-adapted strategy.\n\nMethods: We did a multicentre, randomised, open-label, non-comparative, phase 2 trial in 45 hospitals in Spain, France, Belgium, Germany, the UK, Italy, and Portugal. Eligible participants were women aged 18 years or older with centrally confirmed, HER2-positive, stage I-IIIA, invasive, operable breast cancer (≥1·5 cm tumour size) with at least one breast lesion evaluable by 18 F-FDG-PET, an Eastern Cooperative Oncology Group performance status of 0 or 1, and a baseline left ventricular ejection fraction of at least 55%. We randomly assigned participants (1:4), via an interactive response system using central block randomisation with block sizes of five, stratified by hormone receptor status, to either docetaxel (75 mg/m 2 intravenous), carboplatin (area under the concentration-time curve 6 mg/mL per min intravenous), trastuzumab (subcutaneous 600 mg fixed dose), and pertuzumab (intravenous 840 mg loading dose, 420 mg maintenance doses; group A); or trastuzumab and pertuzumab (group B). Hormone receptor-positive patients allocated to group B were additionally given letrozole if postmenopausal (2·5 mg/day orally) or tamoxifen if premenopausal (20 mg/day orally). Centrally reviewed 18 F-FDG-PET scans were done before randomisation and after two treatment cycles. Patients assigned to group A completed six cycles of treatment (every 3 weeks) regardless of 18 F-FDG-PET results. All patients assigned to group B initially received two cycles of trastuzumab and pertuzumab. 18 F-FDG-PET responders in group B continued this treatment for six further cycles; 18 F-FDG-PET non-responders in this group were switched to six cycles of docetaxel, carboplatin, trastuzumab, and pertuzumab. Surgery was done 2-6 weeks after the last dose of study treatment. Adjuvant treatment was selected according to the neoadjuvant treatment administered, pathological response, hormone receptor status, and clinical stage at diagnosis. The coprimary endpoints were the proportion of 18 F-FDG-PET responders in group B with a pathological complete response in the breast and axilla (ypT0/is ypN0) as determined by a local pathologist after surgery after eight cycles of treatment, and 3-year invasive disease-free survival of patients in group B, both assessed by intention to treat. The definitive assessment of pathological complete response was done at this primary analysis; follow-up to assess invasive disease-free survival is continuing, hence these data are not included in this Article. Safety was assessed in all participants who received at least one dose of study drug. Health-related quality-of-life was assessed with EORTC QLQ-C30 and QLQ-BR23 questionnaires at baseline, after two cycles of treatment, and before surgery. This trial is registered with EudraCT (2016-002676-27) and ClinicalTrials.gov (NCT03161353), and is ongoing.\n\nFindings: Between June 26, 2017, and April 24, 2019, we randomly assigned 71 patients to group A and 285 to group B. Median follow-up was 5·7 months (IQR 5·3-6·0). 227 (80%) of 285 patients in group B were 18 F-FDG-PET responders, of whom 86 (37·9%, 95% CI 31·6-44·5; p<0·0001 compared with the historical rate) of 227 had a pathological complete response. The most common haematological grade 3-4 adverse events were anaemia (six [9%] of 68 patients in group A vs four [1%] of 283 patients in group B), neutropenia (16 [24%] vs ten [4%]), and febrile neutropenia (14 [21%] vs 11 [4%]). Serious adverse events occurred in 20 (29%) of 68 patients in group A versus 13 (5%) of 283 patients in group B. No deaths were reported during neoadjuvant treatment. Global health status declined by at least 10% in 65·0% (95% CI 46·5-72·4) and 35·5% (29·7-41·7) of patients in groups A and B, respectively INTERPRETATION: 18 F-FDG-PET identified patients with HER2-positive, early-stage breast cancer who were likely to benefit from chemotherapy-free dual HER2 blockade with trastuzumab and pertuzumab, and a reduced impact on global health status. Depending on the forthcoming results for the 3-year invasive disease-free survival endpoint, this strategy might be a valid approach to select patients not requiring chemotherapy.\n\nFunding: F Hoffmann-La Roche.\n\nIndexed on Europe PMC as PubMed record 34019819 (DOI 10.1016/s1470-2045(21)00122-4). Its abstract cites the registry id NCT03161353, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2021, doi: "10.1016/s1470-2045(21)00122-4", pmid: "34019819", authors: "Pérez-García JM, Gebhart G, Ruiz Borrego M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03161353 with the most citations, so it is the natural first reading for anyone following the PHERGain trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2021","url":"https://doi.org/10.1016/s1470-2045(21)00122-4"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34019819/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34019819"},{"label":"ClinicalTrials.gov NCT03161353","url":"https://clinicaltrials.gov/study/NCT03161353"}], tags: ["europepmc-ingest"], trials: ["phergain"], journals: ["lancet-oncology"] }),
  p({ id: "paper-phergain-lancet-2024-update", name: "3-year invasive disease-free survival with chemotherapy de-escalation using an 18 F-FDG-PET-based, pathological complete response-adapted strategy in HER2-positive early breast cancer (PHERGain): a randomised, open-label, phase 2 trial", tldr: "Later report from the PHERGain trial registered as NCT03161353, in The Lancet (2024); its title describes an updated or longer-term analysis.", summary: "Background: PHERGain was designed to assess the feasibility, safety, and efficacy of a chemotherapy-free treatment based on a dual human epidermal growth factor receptor 2 (HER2) blockade with trastuzumab and pertuzumab in patients with HER2-positive early breast cancer (EBC). It used an 18 fluorine-fluorodeoxyglucose-PET-based, pathological complete response (pCR)-adapted strategy.\n\nMethods: PHERGain was a randomised, open-label, phase 2 trial that took place in 45 hospitals in seven European countries. It randomly allocated patients in a 1:4 ratio with centrally confirmed, HER2-positive, stage I-IIIA invasive, operable breast cancer with at least one PET-evaluable lesion to either group A, where patients received docetaxel (75 mg/m 2, intravenous), carboplatin (area under the curve 6 mg/mL per min, intravenous), trastuzumab (600 mg fixed dose, subcutaneous), and pertuzumab (840 mg loading dose followed by 420 mg maintenance doses, intravenous; TCHP), or group B, where patients received trastuzumab and pertuzumab with or without endocrine therapy, every 3 weeks. Random allocation was stratified by hormone receptor status. Centrally reviewed PET was conducted at baseline and after two treatment cycles. Patients in group B were treated according to on-treatment PET results. Patients in group B who were PET-responders continued with trastuzumab and pertuzumab with or without endocrine therapy for six cycles, while PET-non-responders were switched to receive six cycles of TCHP. After surgery, patients in group B who were PET-responders who did not achieve a pCR received six cycles of TCHP, and all patients completed up to 18 cycles of trastuzumab and pertuzumab. The primary endpoints were pCR in patients who were group B PET-responders after two treatment cycles (the results for which have been reported previously) and 3-year invasive disease-free survival (iDFS) in patients in group B. The study is registered with ClinicalTrials.gov (NCT03161353) and is ongoing.\n\nFindings: Between June 26, 2017, and April 24, 2019, a total of 356 patients were randomly allocated (71 patients in group A and 285 patients in group B), and 63 (89%) and 267 (94%) patients proceeded to surgery in groups A and B, respectively. At this second analysis (data cutoff: Nov 4, 2022), the median duration of follow-up was 43·3 months (range 0·0-63·0). In group B, the 3-year iDFS rate was 94·8% (95% CI 91·4-97·1; p=0·001), meeting the primary endpoint. No new safety signals were identified. Treatment-related adverse events and serious adverse events (SAEs) were numerically higher in patients allocated to group A than to group B (grade ≥3 62% vs 33%; SAEs 28% vs 14%). Group B PET-responders with pCR presented the lowest incidence of treatment-related grade 3 or higher adverse events (1%) without any SAEs.\n\nInterpretation: Among HER2-positive EBC patients, a PET-based, pCR-adapted strategy was associated with an excellent 3-year iDFS. This strategy identified about a third of patients who had HER2-positive EBC who could safely omit chemotherapy.\n\nFunding: F Hoffmann-La Roche.\n\nIndexed on Europe PMC as PubMed record 38582092 (DOI 10.1016/s0140-6736(24)00054-0). Its abstract cites the registry id NCT03161353, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2024, doi: "10.1016/s0140-6736(24)00054-0", pmid: "38582092", authors: "Pérez-García JM, Cortés J, Ruiz-Borrego M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the PHERGain trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet 2024","url":"https://doi.org/10.1016/s0140-6736(24)00054-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38582092/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38582092"},{"label":"ClinicalTrials.gov NCT03161353","url":"https://clinicaltrials.gov/study/NCT03161353"}], tags: ["europepmc-ingest"], trials: ["phergain"], journals: ["lancet"] }),
  p({ id: "paper-rxponder-n-engl-j-med-2021", name: "21-Gene Assay to Inform Chemotherapy Benefit in Node-Positive Breast Cancer", tldr: "Published report from the RxPONDER trial registered as NCT01272037, in New England Journal of Medicine (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The recurrence score based on the 21-gene breast-cancer assay has been clinically useful in predicting a chemotherapy benefit in hormone-receptor-positive, human epidermal growth factor receptor 2 (HER2)-negative, axillary lymph-node-negative breast cancer. In women with positive lymph-node disease, the role of the recurrence score with respect to predicting a benefit of adjuvant chemotherapy is unclear.\n\nMethods: In a prospective trial, we randomly assigned women with hormone-receptor-positive, HER2-negative breast cancer, one to three positive axillary lymph nodes, and a recurrence score of 25 or lower (scores range from 0 to 100, with higher scores indicating a worse prognosis) to endocrine therapy only or to chemotherapy plus endocrine (chemoendocrine) therapy. The primary objective was to determine the effect of chemotherapy on invasive disease-free survival and whether the effect was influenced by the recurrence score. Secondary end points included distant relapse-free survival.\n\nResults: A total of 5083 women (33.2% premenopausal and 66.8% postmenopausal) underwent randomization, and 5018 participated in the trial. At the prespecified third interim analysis, the chemotherapy benefit with respect to increasing invasive disease-free survival differed according to menopausal status (P = 0.008 for the comparison of chemotherapy benefit in premenopausal and postmenopausal participants), and separate prespecified analyses were conducted. Among postmenopausal women, invasive disease-free survival at 5 years was 91.9% in the endocrine-only group and 91.3% in the chemoendocrine group, with no chemotherapy benefit (hazard ratio for invasive disease recurrence, new primary cancer [breast cancer or another type], or death, 1.02; 95% confidence interval [CI], 0.82 to 1.26; P = 0.89). Among premenopausal women, invasive disease-free survival at 5 years was 89.0% with endocrine-only therapy and 93.9% with chemoendocrine therapy (hazard ratio, 0.60; 95% CI, 0.43 to 0.83; P = 0.002), with a similar increase in distant relapse-free survival (hazard ratio, 0.58; 95% CI, 0.39 to 0.87; P = 0.009). The relative chemotherapy benefit did not increase as the recurrence score increased.\n\nConclusions: Among premenopausal women with one to three positive lymph nodes and a recurrence score of 25 or lower, those who received chemoendocrine therapy had longer invasive disease-free survival and distant relapse-free survival than those who received endocrine-only therapy, whereas postmenopausal women with similar characteristics did not benefit from adjuvant chemotherapy. (Funded by the National Cancer Institute and others; RxPONDER ClinicalTrials.gov number, NCT01272037.).\n\nIndexed on Europe PMC as PubMed record 34914339 (DOI 10.1056/nejmoa2108873). Its abstract cites the registry id NCT01272037, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2021, doi: "10.1056/nejmoa2108873", pmid: "34914339", authors: "Kalinsky K, Barlow WE, Gralow JR, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01272037 with the most citations, so it is the natural first reading for anyone following the RxPONDER trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2021","url":"https://doi.org/10.1056/nejmoa2108873"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34914339/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34914339"},{"label":"ClinicalTrials.gov NCT01272037","url":"https://clinicaltrials.gov/study/NCT01272037"}], tags: ["europepmc-ingest"], trials: ["rxponder"], journals: ["nejm"] }),
  p({ id: "paper-serena-6-n-engl-j-med-2025", name: "First-Line Camizestrant for Emerging ESR1 -Mutated Advanced Breast Cancer", tldr: "Published report from the SERENA-6 trial registered as NCT04964934, in New England Journal of Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Mutations in ESR1 are the most common mechanism of acquired resistance to treatment with an aromatase inhibitor plus a cyclin-dependent kinase 4 and 6 (CDK4/6) inhibitor for advanced breast cancer. Camizestrant, a next-generation selective estrogen-receptor (ER) degrader and complete ER antagonist, has shown antitumor activity in ER-positive advanced breast cancer.\n\nMethods: We tested patients with advanced breast cancer with ER-positive, human epidermal growth factor receptor 2 (HER2)-negative tumors for ESR1 mutations in circulating tumor DNA (ctDNA) once every 2 to 3 months. All the patients had received at least 6 months of first-line therapy with an aromatase inhibitor plus a CDK4/6 inhibitor (palbociclib, ribociclib, or abemaciclib). Patients who were found to have an ESR1 mutation and did not have radiologic progression were assigned in a 1:1 ratio to switch to camizestrant (75 mg once daily) with a continued CDK4/6 inhibitor plus placebo in place of an aromatase inhibitor or to continue to receive an aromatase inhibitor plus a CDK4/6 inhibitor plus placebo in place of camizestrant. The primary outcome was investigator-assessed progression-free survival.\n\nResults: A total of 3256 patients were tested for an ESR1 mutation. The 315 eligible patients were assigned to switch to camizestrant (157 patients) or to continue to receive an aromatase inhibitor (158 patients). At an interim analysis at a median follow-up of 12.6 months, the median progression-free survival was 16.0 months (95% confidence interval [CI], 12.7 to 18.2) in the camizestrant group and 9.2 months (95% CI, 7.2 to 9.5) in the aromatase-inhibitor group (hazard ratio for progression or death, 0.44; 95% CI, 0.31 to 0.60; P<0.0001). The median time until a deterioration in the patient-reported global health status and quality of life occurred was 21.0 months with camizestrant and 6.4 months with an aromatase inhibitor (hazard ratio, 0.54; 95% CI, 0.34 to 0.84). The frequency of discontinuation because of adverse events was 1.3% with camizestrant and 1.9% with an aromatase inhibitor.\n\nConclusions: In patients with ER-positive, HER2-negative advanced breast cancer with an ESR1 mutation that emerged during treatment, those who were switched to camizestrant with continuation of a CDK4/6 inhibitor during first-line therapy had significantly longer progression-free survival than those who maintained the aromatase-inhibitor combination. (Funded by AstraZeneca; SERENA-6 ClinicalTrials.gov number, NCT04964934.).\n\nIndexed on Europe PMC as PubMed record 40454637 (DOI 10.1056/nejmoa2502929). Its abstract cites the registry id NCT04964934, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2502929", pmid: "40454637", authors: "Bidard FC, Mayer EL, Park YH, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04964934 with the most citations, so it is the natural first reading for anyone following the SERENA-6 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2502929"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40454637/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40454637"},{"label":"ClinicalTrials.gov NCT04964934","url":"https://clinicaltrials.gov/study/NCT04964934"}], tags: ["europepmc-ingest"], trials: ["serena-6"], journals: ["nejm"] }),
  p({ id: "paper-soft-text-n-engl-j-med-2015", name: "Adjuvant ovarian suppression in premenopausal breast cancer", tldr: "Published report from the SOFT trial registered as NCT00066690, in New England Journal of Medicine (2015), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Suppression of ovarian estrogen production reduces the recurrence of hormone-receptor-positive early breast cancer in premenopausal women, but its value when added to tamoxifen is uncertain.\n\nMethods: We randomly assigned 3066 premenopausal women, stratified according to prior receipt or nonreceipt of chemotherapy, to receive 5 years of tamoxifen, tamoxifen plus ovarian suppression, or exemestane plus ovarian suppression. The primary analysis tested the hypothesis that tamoxifen plus ovarian suppression would improve disease-free survival, as compared with tamoxifen alone. In the primary analysis, 46.7% of the patients had not received chemotherapy previously, and 53.3% had received chemotherapy and remained premenopausal.\n\nResults: After a median follow-up of 67 months, the estimated disease-free survival rate at 5 years was 86.6% in the tamoxifen-ovarian suppression group and 84.7% in the tamoxifen group (hazard ratio for disease recurrence, second invasive cancer, or death, 0.83; 95% confidence interval [CI], 0.66 to 1.04; P=0.10). Multivariable allowance for prognostic factors suggested a greater treatment effect with tamoxifen plus ovarian suppression than with tamoxifen alone (hazard ratio, 0.78; 95% CI, 0.62 to 0.98). Most recurrences occurred in patients who had received prior chemotherapy, among whom the rate of freedom from breast cancer at 5 years was 82.5% in the tamoxifen-ovarian suppression group and 78.0% in the tamoxifen group (hazard ratio for recurrence, 0.78; 95% CI, 0.60 to 1.02). At 5 years, the rate of freedom from breast cancer was 85.7% in the exemestane-ovarian suppression group (hazard ratio for recurrence vs. tamoxifen, 0.65; 95% CI, 0.49 to 0.87).\n\nConclusions: Adding ovarian suppression to tamoxifen did not provide a significant benefit in the overall study population. However, for women who were at sufficient risk for recurrence to warrant adjuvant chemotherapy and who remained premenopausal, the addition of ovarian suppression improved disease outcomes. Further improvement was seen with the use of exemestane plus ovarian suppression. (Funded by Pfizer and others; SOFT ClinicalTrials.gov number, NCT00066690.).\n\nIndexed on Europe PMC as PubMed record 25495490 (DOI 10.1056/nejmoa1412379). Its abstract cites the registry id NCT00066690, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2015, doi: "10.1056/nejmoa1412379", pmid: "25495490", authors: "Francis PA, Regan MM, Fleming GF, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00066690 with the most citations, so it is the natural first reading for anyone following the SOFT trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2015","url":"https://doi.org/10.1056/nejmoa1412379"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/25495490/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/25495490"},{"label":"ClinicalTrials.gov NCT00066690","url":"https://clinicaltrials.gov/study/NCT00066690"}], tags: ["europepmc-ingest"], trials: ["soft-text"], journals: ["nejm"] }),
  p({ id: "paper-soft-text-j-clin-oncol-2023-update", name: "Adjuvant Endocrine Therapy in Premenopausal Breast Cancer: 12-Year Results From SOFT", tldr: "Later report from the SOFT trial registered as NCT00066690, in Journal of Clinical Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Clinical trials frequently include multiple end points that mature at different times. The initial report, typically based on the primary end point, may be published when key planned co-primary or secondary analyses are not yet available. Clinical Trial Updates provide an opportunity to disseminate additional results from studies, published in JCO or elsewhere, for which the primary end point has already been reported. The Suppression of Ovarian Function Trial (SOFT; ClinicalTrials.gov identifier: NCT00066690) randomly assigned premenopausal women with hormone receptor-positive breast cancer to 5 years of adjuvant tamoxifen, tamoxifen plus ovarian function suppression (OFS), or exemestane plus OFS. The primary analysis compared disease-free survival (DFS) between tamoxifen plus OFS versus tamoxifen alone; exemestane plus OFS versus tamoxifen was a secondary objective. After 8 years, SOFT reported a significant reduction in recurrence and improved overall survival (OS) with adjuvant tamoxifen plus OFS versus tamoxifen alone. Here, we report outcomes after median follow-up of 12 years. DFS remained significantly improved with tamoxifen plus OFS versus tamoxifen (hazard ratio, 0.82; 95% CI, 0.69 to 0.98) with a 12-year DFS of 71.9% with tamoxifen, 76.1% with tamoxifen plus OFS, and 79.0% with exemestane plus OFS. OS was improved with tamoxifen plus OFS versus tamoxifen (hazard ratio, 0.78; 95% CI, 0.60 to 1.01) and was 86.8% with tamoxifen, 89.0% with tamoxifen plus OFS, and 89.4% with exemestane plus OFS at 12 years. Among those who received prior chemotherapy for human epidermal growth factor receptor-2-negative tumors, OS was 78.8% with tamoxifen, 81.1% with tamoxifen plus OFS, and 84.4% with exemestane plus OFS. In conclusion, after 12 years, there remains a benefit from including OFS in adjuvant endocrine therapy, with an absolute improvement in OS more apparent with higher baseline risk of recurrence.[Media: see text].\n\nIndexed on Europe PMC as PubMed record 36493334 (DOI 10.1200/jco.22.01065). Its abstract cites the registry id NCT00066690, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.22.01065", pmid: "36493334", authors: "Francis PA, Fleming GF, Láng I, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the SOFT trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.22.01065"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36493334/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36493334"},{"label":"ClinicalTrials.gov NCT00066690","url":"https://clinicaltrials.gov/study/NCT00066690"}], tags: ["europepmc-ingest"], trials: ["soft-text"], journals: ["jco"] }),
  p({ id: "paper-solar-1-ann-oncol-2021-update", name: "Alpelisib plus fulvestrant for PIK3CA-mutated, hormone receptor-positive, human epidermal growth factor receptor-2-negative advanced breast cancer: final overall survival results from SOLAR-1", tldr: "Later report from the SOLAR-1 trial registered as NCT02437318, in Annals of Oncology (2021); its title describes an updated or longer-term analysis.", summary: "Background: Activation of the phosphatidylinositol-3-kinase (PI3K) pathway via PIK3CA mutations occurs in 28%-46% of hormone receptor-positive (HR+), human epidermal growth factor receptor-2-negative (HER2-) advanced breast cancers (ABCs) and is associated with poor prognosis. The SOLAR-1 trial showed that the addition of alpelisib to fulvestrant treatment provided statistically significant and clinically meaningful progression-free survival (PFS) benefit in PIK3CA-mutated, HR+, HER2- ABC.\n\nPatients and methods: Men and postmenopausal women with HR+, HER2- ABC whose disease progressed on or after aromatase inhibitor (AI) were randomized 1: 1 to receive alpelisib (300 mg/day) plus fulvestrant (500 mg every 28 days and once on day 15) or placebo plus fulvestrant. Overall survival (OS) in the PIK3CA-mutant cohort was evaluated by Kaplan-Meier methodology and a one-sided stratified log-rank test was carried out with an O'Brien-Fleming efficacy boundary of P ≤ 0.0161.\n\nResults: In the PIK3CA-mutated cohort (n = 341), median OS [95% confidence interval (CI)] was 39.3 months (34.1-44.9) for alpelisib-fulvestrant and 31.4 months (26.8-41.3) for placebo-fulvestrant [hazard ratio (HR) = 0.86 (95% CI, 0.64-1.15; P = 0.15)]. OS results did not cross the prespecified efficacy boundary. Median OS (95% CI) in patients with lung and/or liver metastases was 37.2 months (28.7-43.6) and 22.8 months (19.0-26.8) in the alpelisib-fulvestrant and placebo-fulvestrant arms, respectively [HR = 0.68 (0.46-1.00)]. Median times to chemotherapy (95% CI) for the alpelisib-fulvestrant and placebo-fulvestrant arms were 23.3 months (15.2-28.4) and 14.8 months (10.5-22.6), respectively [HR = 0.72 (0.54-0.95)]. No new safety signals were observed with longer follow-up.\n\nConclusions: Although the analysis did not cross the prespecified boundary for statistical significance, there was a 7.9-month numeric improvement in median OS when alpelisib was added to fulvestrant treatment of patients with PIK3CA-mutated, HR+, HER2- ABC. Overall, these results further support the statistically significant prolongation of PFS observed with alpelisib plus fulvestrant in this population, which has a poor prognosis due to a PIK3CA mutation. CLINICALTRIALS.\n\nGov id: NCT02437318.\n\nIndexed on Europe PMC as PubMed record 33246021 (DOI 10.1016/j.annonc.2020.11.011). Its abstract cites the registry id NCT02437318, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2021, doi: "10.1016/j.annonc.2020.11.011", pmid: "33246021", authors: "André F, Ciruelos EM, Juric D, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the SOLAR-1 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2021","url":"https://doi.org/10.1016/j.annonc.2020.11.011"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33246021/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33246021"},{"label":"ClinicalTrials.gov NCT02437318","url":"https://clinicaltrials.gov/study/NCT02437318"}], tags: ["europepmc-ingest"], trials: ["solar-1"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-tropics-02-lancet-2023", name: "Overall survival with sacituzumab govitecan in hormone receptor-positive and human epidermal growth factor receptor 2-negative metastatic breast cancer (TROPiCS-02): a randomised, open-label, multicentre, phase 3 trial", tldr: "Published report from the TROPiCS-02 trial registered as NCT03901339, in The Lancet (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sacituzumab govitecan demonstrated significant progression-free survival benefit over chemotherapy in the phase 3 TROPiCS-02 trial in patients with pretreated, endocrine-resistant hormone receptor-positive, human epidermal growth factor receptor 2-negative (HR+ and HER2-) metastatic breast cancer with limited treatment options. Here, we report the protocol-specified final analysis of overall survival and endpoints by trophoblast cell-surface antigen 2 (Trop-2) expression and other variables.\n\nMethods: In this randomised, open-label, multicentre, phase 3 trial, which took place in 91 centres across North America (the USA and Canada) and Europe (Belgium, France, Germany, Italy, the Netherlands, Spain, and the UK), patients were randomly assigned (1:1) to receive sacituzumab govitecan or chemotherapy (eribulin, vinorelbine, capecitabine, or gemcitabine). Patients had confirmed HR+ and HER2- locally recurrent inoperable or metastatic breast cancer and had received at least one previous endocrine therapy, a taxane, and a CDK4/6 inhibitor in any setting and two to four previous chemotherapy regimens for metastatic disease. The primary endpoint was progression-free survival (previously reported and not included in this analysis), and secondary endpoints included overall survival, objective response rate (ORR), and patient-reported outcomes. Overall survival was assessed using stratified log-rank tests and Cox regression. Trop-2 expression was assessed in tumour tissue by immunohistochemistry. In the statistical testing hierarchy, ORR and patient-reported outcomes were tested sequentially if overall survival was significant. This study is registered with ClinicalTrials.gov, NCT03901339.\n\nFindings: At the data cutoff date of July 1, 2022, 543 of 776 screened patients were randomly assigned between May 30, 2019, and April 5, 2021, with 272 patients in the sacituzumab govitecan group and 271 patients in the chemotherapy group. With a 12·5-month (IQR 6·4-18·8) median follow-up, 390 deaths occurred among 543 patients. Overall survival was significantly improved with sacituzumab govitecan versus chemotherapy (median 14·4 months [95% CI 13·0-15·7] vs 11·2 months [10·1-12·7]; hazard ratio [HR] 0·79, 95% CI 0·65-0·96; p=0·020); survival benefit was consistent across Trop-2 expression-level subgroups. ORR was significantly improved with sacituzumab govitecan compared with chemotherapy (57 [21%] patients vs 38 [14%]; odds ratio 1·63 [95% CI 1·03-2·56]; p=0·035), as was time to deterioration of global health status and quality of life (median 4·3 months vs 3·0 months; HR 0·75 [0·61-0·92]; p=0·0059) and fatigue (median 2·2 months vs 1·4 months; HR 0·73 [0·60-0·89]; p=0·0021). The safety profile of sacituzumab govitecan was consistent with previous studies (including the TROPiCS-02 primary analysis and the ASCENT trial). One fatal adverse event (septic shock caused by neutropenic colitis) was determined to be related to sacituzumab govitecan treatment.\n\nInterpretation: Sacituzumab govitecan demonstrated statistically significant and clinically meaningful benefit over chemotherapy, with a 3·2-month median overall survival improvement and a manageable safety profile. These data support sacituzumab govitecan as a new treatment option for patients with pretreated, endocrine-resistant HR+ and HER2- metastatic breast cancer.\n\nFunding: Gilead Sciences.\n\nIndexed on Europe PMC as PubMed record 37633306 (DOI 10.1016/s0140-6736(23)01245-x). Its abstract cites the registry id NCT03901339, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2023, doi: "10.1016/s0140-6736(23)01245-x", pmid: "37633306", authors: "Rugo HS, Bardia A, Marmé F, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03901339 with the most citations, so it is the natural first reading for anyone following the TROPiCS-02 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2023","url":"https://doi.org/10.1016/s0140-6736(23)01245-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37633306/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37633306"},{"label":"ClinicalTrials.gov NCT03901339","url":"https://clinicaltrials.gov/study/NCT03901339"}], tags: ["europepmc-ingest"], trials: ["tropics-02"], journals: ["lancet"] }),
  p({ id: "paper-whel-jama-2007", name: "Influence of a diet very high in vegetables, fruit, and fiber and low in fat on prognosis following treatment for breast cancer: the Women's Healthy Eating and Living (WHEL) randomized trial", tldr: "Published report from the WHEL trial registered as NCT00003787, in JAMA (2007), chosen as the most cited paper whose own text cites the registry id.", summary: "Context: Evidence is lacking that a dietary pattern high in vegetables, fruit, and fiber and low in total fat can influence breast cancer recurrence or survival.\n\nObjective: To assess whether a major increase in vegetable, fruit, and fiber intake and a decrease in dietary fat intake reduces the risk of recurrent and new primary breast cancer and all-cause mortality among women with previously treated early stage breast cancer.\n\nDesign, setting, and participants: Multi-institutional randomized controlled trial of dietary change in 3088 women previously treated for early stage breast cancer who were 18 to 70 years old at diagnosis. Women were enrolled between 1995 and 2000 and followed up through June 1, 2006.\n\nIntervention: The intervention group (n = 1537) was randomly assigned to receive a telephone counseling program supplemented with cooking classes and newsletters that promoted daily targets of 5 vegetable servings plus 16 oz of vegetable juice; 3 fruit servings; 30 g of fiber; and 15% to 20% of energy intake from fat. The comparison group (n = 1551) was provided with print materials describing the \"5-A-Day\" dietary guidelines.\n\nMain outcome measures: Invasive breast cancer event (recurrence or new primary) or death from any cause.\n\nResults: From comparable dietary patterns at baseline, a conservative imputation analysis showed that the intervention group achieved and maintained the following statistically significant differences vs the comparison group through 4 years: servings of vegetables, +65%; fruit, +25%; fiber, +30%, and energy intake from fat, -13%. Plasma carotenoid concentrations validated changes in fruit and vegetable intake. Throughout the study, women in both groups received similar clinical care. Over the mean 7.3-year follow-up, 256 women in the intervention group (16.7%) vs 262 in the comparison group (16.9%) experienced an invasive breast cancer event (adjusted hazard ratio, 0.96; 95% confidence interval, 0.80-1.14; P =.63), and 155 intervention group women (10.1%) vs 160 comparison group women (10.3%) died (adjusted hazard ratio, 0.91; 95% confidence interval, 0.72-1.15; P =.43). No significant interactions were observed between diet group and baseline demographics, characteristics of the original tumor, baseline dietary pattern, or breast cancer treatment.\n\nConclusion: Among survivors of early stage breast cancer, adoption of a diet that was very high in vegetables, fruit, and fiber and low in fat did not reduce additional breast cancer events or mortality during a 7.3-year follow-up period.\n\nTrial registration: clinicaltrials.gov Identifier: NCT00003787.\n\nIndexed on Europe PMC as PubMed record 17635889 (DOI 10.1001/jama.298.3.289). Its abstract cites the registry id NCT00003787, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2007, doi: "10.1001/jama.298.3.289", pmid: "17635889", authors: "Pierce JP, Natarajan L, Caan BJ, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00003787 with the most citations, so it is the natural first reading for anyone following the WHEL trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2007","url":"https://doi.org/10.1001/jama.298.3.289"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/17635889/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/17635889"},{"label":"ClinicalTrials.gov NCT00003787","url":"https://clinicaltrials.gov/study/NCT00003787"}], tags: ["europepmc-ingest"], trials: ["whel"], journals: ["jama"] }),
  p({ id: "paper-brightness-lancet-oncol-2018", name: "Addition of the PARP inhibitor veliparib plus carboplatin or carboplatin alone to standard neoadjuvant chemotherapy in triple-negative breast cancer (BrighTNess): a randomised, phase 3 trial", tldr: "Published report from the BrighTNess trial registered as NCT02032277, in The Lancet Oncology (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Although several randomised trials in patients with triple-negative breast cancer have shown that the addition of carboplatin, with or without poly(ADP-ribose) polymerase (PARP) inhibitors, to neoadjuvant chemotherapy increases the likelihood of achieving a pathological complete response, the use of these therapies in this setting has remained controversial. The BrighTNess trial was designed to assess the addition of the PARP inhibitor veliparib plus carboplatin or carboplatin alone to standard neoadjuvant chemotherapy in triple-negative breast cancer.\n\nMethods: We did a phase 3, randomised, double-blind, placebo-controlled trial (BrighTNess) across 145 sites in 15 countries. Patients aged 18 years and older with previously untreated histologically or cytologically confirmed clinical stage II-III triple-negative breast cancer, who were candidates for potentially curative surgery and had an Eastern Cooperative Oncology Group performance status of 0 or 1, were randomly assigned (2:1:1) by an interactive response technology system via permuted blocks (block size of four) within strata to receive one of three segment 1 regimens: paclitaxel (80 mg/m 2 intravenously weekly for 12 doses) plus carboplatin (area under the curve 6 mg/mL per min, intravenously every 3 weeks, for four cycles) plus veliparib (50 mg orally, twice a day); paclitaxel plus carboplatin plus veliparib placebo (twice a day); or paclitaxel plus carboplatin placebo (every 3 weeks for four cycles) plus veliparib placebo. Following segment 1, all patients were assigned to segment 2 in which they received doxorubicin and cyclophosphamide every 2-3 weeks for four cycles. Randomisation for segment 1 was stratified by germline BRCA mutation status, nodal stage, and planned schedule of doxorubicin and cyclophosphamide administration. The primary endpoint was pathological complete response in breast and lymph nodes as determined by site pathologists following completion of neoadjuvant therapy. Efficacy analyses were done by intention to treat and safety analyses included all patients who received at least one dose of study treatment. These are the first results of an ongoing clinical trial; the data cutoff for the analyses presented was Dec 8, 2016. This study is registered with ClinicalTrials.gov, number NCT02032277.\n\nFindings: Between April 4, 2014, and March 18, 2016, 634 patients were randomly assigned: 316 to paclitaxel plus carboplatin plus veliparib, 160 to paclitaxel plus carboplatin, and 158 to paclitaxel alone. The proportion of patients who achieved a pathological complete response was higher in the paclitaxel, carboplatin, and veliparib group than in patients receiving paclitaxel alone (168 [53%] of 316 patients vs 49 [31%] of 158, p<0·0001), but not compared with patients receiving paclitaxel plus carboplatin (92 [58%] of 160 patients, p=0·36). Grade 3 or 4 toxicities, and serious adverse events were more common in patients receiving carboplatin, whereas veliparib did not substantially increase toxicity. The most common grade 3 or 4 events overall were neutropenia (352 [56%] of 628 patients), anaemia (180 [29%]), and thrombocytopenia (75 [12%]) through complete treatment, and febrile neutropenia (88 [15%] of 601 patients) during segment 2. The most common serious adverse events were febrile neutropenia (80 [13%] of 628 patients) and anaemia (20 [3%]).\n\nInterpretation: Although the addition of veliparib and carboplatin to paclitaxel followed by doxorubicin and cyclophosphamide improved the proportion of patients with triple-negative breast cancer who achieved a pathological complete response, the addition of veliparib to carboplatin and paclitaxel did not. Increased toxicities with the addition of carboplatin (with or without veliparib) to paclitaxel were manageable and did not substantially affect treatment delivery of paclitaxel followed by doxorubicin and cyclophosphamide. Given the consistent results with previous studies, the addition of carboplatin appears to have a favourable risk to benefit profile and might be considered as a potential component of neoadjuvant chemotherapy for patients with high-risk, triple-negative breast cancer.\n\nFunding: AbbVie.\n\nIndexed on Europe PMC as PubMed record 29501363 (DOI 10.1016/s1470-2045(18)30111-6). Its abstract cites the registry id NCT02032277, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2018, doi: "10.1016/s1470-2045(18)30111-6", pmid: "29501363", authors: "Loibl S, O'Shaughnessy J, Untch M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02032277 with the most citations, so it is the natural first reading for anyone following the BrighTNess trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2018","url":"https://doi.org/10.1016/s1470-2045(18)30111-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/29501363/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/29501363"},{"label":"ClinicalTrials.gov NCT02032277","url":"https://clinicaltrials.gov/study/NCT02032277"}], tags: ["europepmc-ingest"], trials: ["brightness"], journals: ["lancet-oncology"] }),
  p({ id: "paper-plasmamatch-lancet-oncol-2020", name: "Circulating tumour DNA analysis to direct therapy in advanced breast cancer (plasmaMATCH): a multicentre, multicohort, phase 2a, platform trial", tldr: "Published report from the plasmaMATCH trial registered as NCT03182634, in The Lancet Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Circulating tumour DNA (ctDNA) testing might provide a current assessment of the genomic profile of advanced cancer, without the need to repeat tumour biopsy. We aimed to assess the accuracy of ctDNA testing in advanced breast cancer and the ability of ctDNA testing to select patients for mutation-directed therapy.\n\nMethods: We did an open-label, multicohort, phase 2a, platform trial of ctDNA testing in 18 UK hospitals. Participants were women (aged ≥18 years) with histologically confirmed advanced breast cancer and an Eastern Cooperative Oncology Group performance status 0-2. Patients had completed at least one previous line of treatment for advanced breast cancer or relapsed within 12 months of neoadjuvant or adjuvant chemotherapy. Patients were recruited into four parallel treatment cohorts matched to mutations identified in ctDNA: cohort A comprised patients with ESR1 mutations (treated with intramuscular extended-dose fulvestrant 500 mg); cohort B comprised patients with HER2 mutations (treated with oral neratinib 240 mg, and if oestrogen receptor-positive with intramuscular standard-dose fulvestrant); cohort C comprised patients with AKT1 mutations and oestrogen receptor-positive cancer (treated with oral capivasertib 400 mg plus intramuscular standard-dose fulvestrant); and cohort D comprised patients with AKT1 mutations and oestrogen receptor-negative cancer or PTEN mutation (treated with oral capivasertib 480 mg). Each cohort had a primary endpoint of confirmed objective response rate. For cohort A, 13 or more responses among 78 evaluable patients were required to infer activity and three or more among 16 were required for cohorts B, C, and D. Recruitment to all cohorts is complete and long-term follow-up is ongoing. This trial is registered with ClinicalTrials.gov, NCT03182634; the European Clinical Trials database, EudraCT2015-003735-36; and the ISRCTN registry, ISRCTN16945804.\n\nFindings: Between Dec 21, 2016, and April 26, 2019, 1051 patients registered for the study, with ctDNA results available for 1034 patients. Agreement between ctDNA digital PCR and targeted sequencing was 96-99% (n=800, kappa 0·89-0·93). Sensitivity of digital PCR ctDNA testing for mutations identified in tissue sequencing was 93% (95% CI 83-98) overall and 98% (87-100) with contemporaneous biopsies. In all cohorts, combined median follow-up was 14·4 months (IQR 7·0-23·7). Cohorts B and C met or exceeded the target number of responses, with five (25% [95% CI 9-49]) of 20 patients in cohort B and four (22% [6-48]) of 18 patients in cohort C having a response. Cohorts A and D did not reach the target number of responses, with six (8% [95% CI 3-17]) of 74 in cohort A and two (11% [1-33]) of 19 patients in cohort D having a response. The most common grade 3-4 adverse events were raised gamma-glutamyltransferase (13 [16%] of 80 patients; cohort A); diarrhoea (four [25%] of 20; cohort B); fatigue (four [22%] of 18; cohort C); and rash (five [26%] of 19; cohort D). 17 serious adverse reactions occurred in 11 patients, and there was one treatment-related death caused by grade 4 dyspnoea (in cohort C).\n\nInterpretation: ctDNA testing offers accurate, rapid genotyping that enables the selection of mutation-directed therapies for patients with breast cancer, with sufficient clinical validity for adoption into routine clinical practice. Our results demonstrate clinically relevant activity of targeted therapies against rare HER2 and AKT1 mutations, confirming these mutations could be targetable for breast cancer treatment.\n\nFunding: Cancer Research UK, AstraZeneca, and Puma Biotechnology.\n\nIndexed on Europe PMC as PubMed record 32919527 (DOI 10.1016/s1470-2045(20)30444-7). Its abstract cites the registry id NCT03182634, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2020, doi: "10.1016/s1470-2045(20)30444-7", pmid: "32919527", authors: "Turner NC, Kingston B, Kilburn LS, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03182634 with the most citations, so it is the natural first reading for anyone following the plasmaMATCH trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2020","url":"https://doi.org/10.1016/s1470-2045(20)30444-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32919527/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32919527"},{"label":"ClinicalTrials.gov NCT03182634","url":"https://clinicaltrials.gov/study/NCT03182634"}], tags: ["europepmc-ingest"], trials: ["plasmamatch"], journals: ["lancet-oncology"] }),
  p({ id: "paper-i-spy-2-jama-oncol-2020", name: "Effect of Pembrolizumab Plus Neoadjuvant Chemotherapy on Pathologic Complete Response in Women With Early-Stage Breast Cancer: An Analysis of the Ongoing Phase 2 Adaptively Randomized I-SPY2 Trial", tldr: "Published report from the I-SPY 2 trial registered as NCT01042379, in JAMA Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Approximately 25% of patients with early-stage breast cancer who receive (neo)adjuvant chemotherapy experience a recurrence within 5 years. Improvements in therapy are greatly needed.\n\nObjective: To determine if pembrolizumab plus neoadjuvant chemotherapy (NACT) in early-stage breast cancer is likely to be successful in a 300-patient, confirmatory randomized phase 3 neoadjuvant clinical trial.\n\nDesign, setting, and participants: The I-SPY2 study is an ongoing open-label, multicenter, adaptively randomized phase 2 platform trial for high-risk, stage II/III breast cancer, evaluating multiple investigational arms in parallel. Standard NACT serves as the common control arm; investigational agent(s) are added to this backbone. Patients with ERBB2 (formerly HER2)-negative breast cancer were eligible for randomization to pembrolizumab between November 2015 and November 2016.\n\nInterventions: Participants were randomized to receive taxane- and anthracycline-based NACT with or without pembrolizumab, followed by definitive surgery.\n\nMain outcomes and measures: The primary end point was pathologic complete response (pCR). Secondary end points were residual cancer burden (RCB) and 3-year event-free and distant recurrence-free survival. Investigational arms graduated when demonstrating an 85% predictive probability of success in a hypothetical confirmatory phase 3 trial.\n\nResults: Of the 250 women included in the final analysis, 181 were randomized to the standard NACT control group (median [range] age, 47 [24.77] years). Sixty-nine women (median [range] age, 50 [27-71] years) were randomized to 4 cycles of pembrolizumab in combination with weekly paclitaxel followed by AC; 40 hormone receptor (HR)-positive and 29 triple-negative. Pembrolizumab graduated in all 3 biomarker signatures studied. Final estimated pCR rates, evaluated in March 2017, were 44% vs 17%, 30% vs 13%, and 60% vs 22% for pembrolizumab vs control in the ERBB2-negative, HR-positive/ERBB2-negative, and triple-negative cohorts, respectively. Pembrolizumab shifted the RCB distribution to a lower disease burden for each cohort evaluated. Adverse events included immune-related endocrinopathies, notably thyroid abnormalities (13.0%) and adrenal insufficiency (8.7%). Achieving a pCR appeared predictive of long-term outcome, where patients with pCR following pembrolizumab plus chemotherapy had high event-free survival rates (93% at 3 years with 2.8 years' median follow-up).\n\nConclusions and relevance: When added to standard neoadjuvant chemotherapy, pembrolizumab more than doubled the estimated pCR rates for both HR-positive/ERBB2-negative and triple-negative breast cancer, indicating that checkpoint blockade in women with early-stage, high-risk, ERBB2-negative breast cancer is highly likely to succeed in a phase 3 trial. Pembrolizumab was the first of 10 agents to graduate in the HR-positive/ERBB2-negative signature.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT01042379.\n\nIndexed on Europe PMC as PubMed record 32053137 (DOI 10.1001/jamaoncol.2019.6650). Its abstract cites the registry id NCT01042379, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2020, doi: "10.1001/jamaoncol.2019.6650", pmid: "32053137", authors: "Nanda R, Liu MC, Yau C, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01042379 with the most citations, so it is the natural first reading for anyone following the I-SPY 2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2020","url":"https://doi.org/10.1001/jamaoncol.2019.6650"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32053137/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32053137"},{"label":"ClinicalTrials.gov NCT01042379","url":"https://clinicaltrials.gov/study/NCT01042379"}], tags: ["europepmc-ingest"], trials: ["i-spy-2"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct02107703-j-clin-oncol-2017", name: "MONARCH 2: Abemaciclib in Combination With Fulvestrant in Women With HR+/HER2- Advanced Breast Cancer Who Had Progressed While Receiving Endocrine Therapy", tldr: "Published report from the MONARCH 2 trial registered as NCT02107703, in Journal of Clinical Oncology (2017), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose MONARCH 2 ( ClinicalTrials.gov identifier: NCT02107703) compared the efficacy and safety of abemaciclib, a selective cyclin-dependent kinase 4 and 6 inhibitor, plus fulvestrant with fulvestrant alone in patients with advanced breast cancer (ABC). Patients and Methods MONARCH 2 was a global, double-blind, phase III study of women with hormone receptor-positive and human epidermal growth factor receptor 2-negative ABC who had progressed while receiving neoadjuvant or adjuvant endocrine therapy (ET), ≤ 12 months from the end of adjuvant ET, or while receiving first-line ET for metastatic disease. Patients were randomly assigned 2:1 to receive abemaciclib or placebo (150 mg twice daily) on a continuous schedule and fulvestrant (500 mg, per label). The primary end point was investigator-assessed progression-free survival (PFS), and key secondary end points included overall survival, objective response rate (ORR), duration of response, clinical benefit rate, quality of life, and safety. Results Between August 2014 and December 2015, 669 patients were randomly assigned to receive abemaciclib plus fulvestrant (n = 446) or placebo plus fulvestrant (n = 223). Abemaciclib plus fulvestrant significantly extended PFS versus fulvestrant alone (median, 16.4 v 9.3 months; hazard ratio, 0.553; 95% CI, 0.449 to 0.681; P <.001). In patients with measurable disease, abemaciclib plus fulvestrant achieved an ORR of 48.1% (95% CI, 42.6% to 53.6%) compared with 21.3% (95% CI, 15.1% to 27.6%) in the control arm. The most common adverse events in the abemaciclib versus placebo arms were diarrhea (86.4% v 24.7%), neutropenia (46.0% v 4.0%), nausea (45.1% v 22.9%), and fatigue (39.9% v 26.9%). Conclusions Abemaciclib at 150 mg twice daily plus fulvestrant was effective, significantly improving PFS and ORR and demonstrating a tolerable safety profile in women with hormone receptor-positive and human epidermal growth factor receptor 2-negative ABC who progressed while receiving ET.\n\nIndexed on Europe PMC as PubMed record 28580882 (DOI 10.1200/jco.2017.73.7585). Its abstract cites the registry id NCT02107703, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2017, doi: "10.1200/jco.2017.73.7585", pmid: "28580882", authors: "Sledge GW, Toi M, Neven P, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02107703 with the most citations, so it is the natural first reading for anyone following the MONARCH 2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2017","url":"https://doi.org/10.1200/jco.2017.73.7585"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28580882/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28580882"},{"label":"ClinicalTrials.gov NCT02107703","url":"https://clinicaltrials.gov/study/NCT02107703"}], tags: ["europepmc-ingest"], trials: ["nct02107703"], journals: ["jco"] }),
  p({ id: "paper-nct02107703-jama-oncol-2020-update", name: "The Effect of Abemaciclib Plus Fulvestrant on Overall Survival in Hormone Receptor-Positive, ERBB2-Negative Breast Cancer That Progressed on Endocrine Therapy-MONARCH 2: A Randomized Clinical Trial", tldr: "Later report from the MONARCH 2 trial registered as NCT02107703, in JAMA Oncology (2020); its title describes an updated or longer-term analysis.", summary: "Importance: Statistically significant overall survival (OS) benefits of CDK4 and CDK6 inhibitors in combination with fulvestrant for hormone receptor (HR)-positive, ERBB2 (formerly HER2)-negative advanced breast cancer (ABC) in patients regardless of menopausal status after prior endocrine therapy (ET) has not yet been demonstrated.\n\nObjective: To compare the effect of abemaciclib plus fulvestrant vs placebo plus fulvestrant on OS at the prespecified interim of MONARCH 2 (338 events) in patients with HR-positive, ERBB2-negative advanced breast cancer that progressed during prior ET.\n\nDesign, setting, and participants: MONARCH 2 was a global, randomized, placebo-controlled, double-blind phase 3 trial of abemaciclib plus fulvestrant vs placebo plus fulvestrant for treatment of premenopausal or perimenopausal women (with ovarian suppression) and postmenopausal women with HR-positive, ERBB2-negative ABC that progressed during ET. Patients were enrolled between August 7, 2014, and December 29, 2015. Analyses for this report were conducted at the time of database lock on June 20, 2019.\n\nInterventions: Patients were randomized 2:1 to receive abemaciclib or placebo, 150 mg, every 12 hours on a continuous schedule plus fulvestrant, 500 mg, per label. Randomization was stratified based on site of metastasis (visceral, bone only, or other) and resistance to prior ET (primary vs secondary).\n\nMain outcomes and measures: The primary end point was investigator-assessed progression-free survival. Overall survival was a gated key secondary end point. The boundary P value for the interim analysis was.02.\n\nResults: Of 669 women enrolled, 446 (median [range] age, 59 [32-91] years) were randomized to the abemaciclib plus fulvestrant arm and 223 (median [range] age, 62 [32-87] years) were randomized to the placebo plus fulvestrant arm. At the prespecified interim, 338 deaths (77% of the planned 441 at the final analysis) were observed in the intent-to-treat population, with a median OS of 46.7 months for abemaciclib plus fulvestrant and 37.3 months for placebo plus fulvestrant (hazard ratio [HR], 0.757; 95% CI, 0.606-0.945; P =.01). Improvement in OS was consistent across all stratification factors. Among stratification factors, more pronounced effects were observed in patients with visceral disease (HR, 0.675; 95% CI, 0.511-0.891) and primary resistance to prior ET (HR, 0.686; 95% CI, 0.451-1.043). Time to second disease progression (median, 23.1 months vs 20.6 months), time to chemotherapy (median, 50.2 months vs 22.1 months), and chemotherapy-free survival (median, 25.5 months vs 18.2 months) were also statistically significantly improved in the abemaciclib arm vs placebo arm. No new safety signals were observed for abemaciclib.\n\nConclusions and relevance: Treatment with abemaciclib plus fulvestrant resulted in a statistically significant and clinically meaningful median OS improvement of 9.4 months for patients with HR-positive, ERBB2-negative ABC who progressed after prior ET regardless of menopausal status. Abemaciclib substantially delayed the receipt of subsequent chemotherapy.\n\nTrial registration: ClinicalTrials.gov identifier: NCT02107703.\n\nIndexed on Europe PMC as PubMed record 31563959 (DOI 10.1001/jamaoncol.2019.4782). Its abstract cites the registry id NCT02107703, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2020, doi: "10.1001/jamaoncol.2019.4782", pmid: "31563959", authors: "Sledge GW, Toi M, Neven P, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the MONARCH 2 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"JAMA Oncol 2020","url":"https://doi.org/10.1001/jamaoncol.2019.4782"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31563959/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31563959"},{"label":"ClinicalTrials.gov NCT02107703","url":"https://clinicaltrials.gov/study/NCT02107703"}], tags: ["europepmc-ingest"], trials: ["nct02107703"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct03330847-clin-cancer-res-2026", name: "Safety and Efficacy of Ceralasertib plus Olaparib for Advanced/Metastatic Triple-Negative Breast Cancer in Three Molecular Strata: The Phase II VIOLETTE Study", tldr: "Published report from the VIOLETTE trial registered as NCT03330847, in Clinical Cancer Research (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: VIOLETTE (NCT03330847) assessed olaparib alone or with ceralasertib (ATR inhibitor) or adavosertib (WEE1 inhibitor) as second-/third-line treatment in three molecular strata of patients with previously treated, PARP inhibitor-naïve, advanced triple-negative breast cancer (TNBC).\n\nPatients and methods: Patients were randomized 1:1:1 to olaparib 300 mg twice daily (BD), ceralasertib 160 mg once daily (Days 1-7; 28-day cycles) + olaparib 300 mg BD, or adavosertib 150 mg BD (Days 1-3, 8-10; 21-day cycles) + olaparib 200 mg BD. Patients were stratified by presence of tumoral homologous recombination repair (HRR) pathway mutations (m): BRCA1/2m, non-BRCA1/2m HRRm, or non-HRRm. Primary endpoint was progression-free survival (PFS) by blinded independent central review.\n\nResults: 273 patients were randomized: 114, 112, and 47 to the olaparib, ceralasertib + olaparib, and adavosertib + olaparib arms, respectively. The adavosertib + olaparib arm was terminated early due to unacceptable toxicity. Median PFS of ceralasertib + olaparib was 7.4, 3.9, and 3.6 months in the BRCA1/2m, non-BRCA1/2m HRRm, and non-HRRm strata, respectively, and did not differ significantly from olaparib (HR 1.02 [90% CI, 0.63-1.66], 0.54 [90% CI, 0.28-1.03], and 0.76 [90% CI, 0.50-1.14], respectively). In the non-HRRm group objective response rates (ORR) were significantly improved for ceralasertib + olaparib (15.4%) vs. olaparib (3.9%; OR, 4.45; 90% CI, 1.30‒21.20; P = 0.0425). No unexpected safety signals were reported for ceralasertib or olaparib.\n\nConclusions: In patients with advanced PARP inhibitor-naïve non-HRRm TNBC, ceralasertib + olaparib significantly improved ORR versus olaparib. However, clinical significance is limited without improvement in PFS.\n\nIndexed on Europe PMC as PubMed record 42765908 (DOI 10.1158/1078-0432.ccr-26-1066). Its abstract cites the registry id NCT03330847, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Clinical Cancer Research", year: 2026, doi: "10.1158/1078-0432.ccr-26-1066", pmid: "42765908", authors: "Tutt A, Nowecki Z, Szoszkiewicz R, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03330847 with the most citations, so it is the natural first reading for anyone following the VIOLETTE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Clin Cancer Res 2026","url":"https://doi.org/10.1158/1078-0432.ccr-26-1066"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42765908/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42765908"},{"label":"ClinicalTrials.gov NCT03330847","url":"https://clinicaltrials.gov/study/NCT03330847"}], tags: ["europepmc-ingest"], trials: ["nct03330847"], journals: ["clinical-cancer-research"] }),
  p({ id: "paper-nct03725059-nat-med-2025", name: "Pembrolizumab and chemotherapy in high-risk, early-stage, ER + /HER2 - breast cancer: a randomized phase 3 trial", tldr: "Published report from the KEYNOTE-756 trial registered as NCT03725059, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Addition of pembrolizumab to neoadjuvant chemotherapy followed by adjuvant pembrolizumab improved outcomes in patients with high-risk, early-stage, triple-negative breast cancer. However, whether the addition of neoadjuvant pembrolizumab to chemotherapy would improve outcomes in high-risk, early-stage, estrogen receptor-positive/human epidermal growth factor receptor 2-negative (ER + /HER2 -) breast cancer remains unclear. We conducted a double-blind, placebo-controlled phase 3 study (KEYNOTE-756) in which patients with previously untreated ER + /HER2 - grade 3 high-risk invasive breast cancer (T1c-2 (≥2 cm), cN1-2 or T3-4, cN0-2) were randomly assigned (1:1) to neoadjuvant pembrolizumab 200 mg or placebo Q3W given with paclitaxel QW for 12 weeks, followed by four cycles of doxorubicin or epirubicin plus cyclophosphamide Q2W or Q3W. After surgery (with/without adjuvant radiation therapy), patients received adjuvant pembrolizumab or placebo for nine cycles plus adjuvant endocrine therapy. Dual primary endpoints were pathological complete response and event-free survival in the intention-to-treat population. In total, 635 patients were assigned to the pembrolizumab-chemotherapy arm and 643 to the placebo-chemotherapy arm. At the study's prespecified first interim analysis, the pathological complete response rate was 24.3% (95% confidence interval (CI), 21.0-27.8%) in the pembrolizumab-chemotherapy arm and 15.6% (95% CI, 12.8-18.6%) in the placebo-chemotherapy arm (estimated treatment difference, 8.5 percentage points; 95% CI, 4.2-12.8; P = 0.00005). Event-free survival was not mature in this analysis. During the neoadjuvant phase, treatment-related adverse events of grade ≥3 were reported in 52.5% and 46.4% of patients in the pembrolizumab-chemotherapy and placebo-chemotherapy arms, respectively. In summary, the addition of pembrolizumab to neoadjuvant chemotherapy significantly improved the pathological complete response rate in patients with high-risk, early-stage ER + /HER2 - breast cancer. Safety was consistent with the known profiles of each study treatment. Follow-up continues for event-free survival. ClinicalTrials.gov identifier: NCT03725059.\n\nIndexed on Europe PMC as PubMed record 39838117 (DOI 10.1038/s41591-024-03415-7). Its abstract cites the registry id NCT03725059, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-024-03415-7", pmid: "39838117", authors: "Cardoso F, O'Shaughnessy J, Liu Z, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03725059 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-756 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-024-03415-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39838117/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39838117"},{"label":"ClinicalTrials.gov NCT03725059","url":"https://clinicaltrials.gov/study/NCT03725059"}], tags: ["europepmc-ingest"], trials: ["nct03725059"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct03742102-ann-oncol-2026", name: "Datopotamab deruxtecan (Dato-DXd) in combination with durvalumab as first-line treatment for unresectable locally advanced or metastatic triple-negative breast cancer: results from arms 7 and 8 of the phase Ib/II BEGONIA study", tldr: "Published report from the BEGONIA trial registered as NCT03742102, in Annals of Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: BEGONIA (NCT03742102) is a phase Ib/II, Simon's 2-stage, open-label, platform study evaluating the safety and efficacy of durvalumab, an anti-programmed death ligand-1 (PD-L1) antibody, combined with novel therapies, as first-line treatment for patients with unresectable locally advanced or metastatic triple-negative breast cancer (TNBC). Arms 7 and 8 of BEGONIA assessed the combination of datopotamab deruxtecan (Dato-DXd), a TROP2-directed antibody-drug conjugate, with durvalumab.\n\nPatients and methods: Arm 7 included patients regardless of tumor PD-L1 expression level. Arm 8 then enrolled patients with PD-L1-high tumors, as determined by local immunohistochemistry-based testing. In Arms 7 and 8, patients received Dato-DXd 6 mg/kg intravenously plus durvalumab 1120 mg intravenously every 3 weeks. Primary endpoints were safety and tolerability, and investigator-assessed confirmed objective response rate (cORR). Secondary endpoints included cORR (Part 1), duration of response (DoR), progression-free survival (PFS) per RECIST 1.1 and overall survival (OS).\n\nResults: Overall, 62 and 33 patients had received Dato-DXd and durvalumab in Arms 7 and 8, respectively. At data cutoff (29 November 2024), median study follow-up was 35.0 and 10.7 months in Arms 7 and 8, respectively. In Arm 7, cORR was 79.0% [95% confidence interval (CI) 66.8-88.3], median DoR was 17.6 months (95% CI 10.5-27.3), median PFS was 14.0 months (11.0-21.1) and median OS was not reached. In Arm 8, cORR was 81.8% (95% CI 64.5-93.0). The median DoR and median PFS for Arm 8 were immature given the short median follow-up (8.3 months in censored patients). The safety profile of the combination was manageable, with no new safety signals versus prior studies.\n\nConclusions: First-line Dato-DXd plus durvalumab demonstrated substantial and durable antitumor activity in locally advanced unresectable or metastatic TNBC, regardless of PD-L1 status.\n\nIndexed on Europe PMC as PubMed record 42167437 (DOI 10.1016/j.annonc.2026.05.693). Its abstract cites the registry id NCT03742102, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2026, doi: "10.1016/j.annonc.2026.05.693", pmid: "42167437", authors: "Schmid P, Wang HC, Lynce F, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03742102 with the most citations, so it is the natural first reading for anyone following the BEGONIA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2026","url":"https://doi.org/10.1016/j.annonc.2026.05.693"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42167437/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42167437"},{"label":"ClinicalTrials.gov NCT03742102","url":"https://clinicaltrials.gov/study/NCT03742102"}], tags: ["europepmc-ingest"], trials: ["nct03742102"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct04214288-lancet-oncol-2024", name: "Camizestrant, a next-generation oral SERD, versus fulvestrant in post-menopausal women with oestrogen receptor-positive, HER2-negative advanced breast cancer (SERENA-2): a multi-dose, open-label, randomised, phase 2 trial", tldr: "Published report from the SERENA-2 trial registered as NCT04214288, in The Lancet Oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Resistance to endocrine therapies in hormone receptor-positive breast cancer is challenging. We aimed to assess the next-generation oral selective oestrogen receptor degrader (SERD) and complete oestrogen receptor antagonist, camizestrant, versus the first-approved SERD, fulvestrant, in post-menopausal women with oestrogen receptor-positive, HER2-negative, advanced breast cancer.\n\nMethods: SERENA-2 is an open-label, randomised, phase 2 trial that is being conducted at 74 study centres across Asia, Europe, the Middle East, and North America. Female patients aged 18 years or older who were post-menopausal with histologically or cytologically confirmed metastastic or locoregional oestrogen receptor-positive, HER2-negative breast cancer, an Eastern Cooperative Oncology Group or WHO performance status of 0 or 1, and disease recurrence or progression on at least one line of endocrine therapy, and no more than one previous endocrine therapy in the advanced setting. Patients were initially randomly assigned (1:1:1:1) to receive oral camizestrant once daily at 75 mg, 150 mg, or 300 mg (until the 300 mg group was closed), or fulvestrant intramuscularly at 500 mg (per label). Randomisation was managed through an interactive web-based system and stratified by previous treatment with CDK4/6 inhibitors and presence of liver and/or lung metastases. The primary objective was to determine clinical efficacy of camizestrant versus fulvestrant at each dose level using the primary endpoint of investigator-assessed progression-free survival, per Response Evaluation Criteria in Solid Tumours (version 1.1), assessed by intention to treat in all randomly assigned patients (full analysis set). No formal statistical comparison for the efficacy analysis of the camizestrant 300 mg dose versus fulvestrant was to be performed. Safety analyses included all randomly assigned patients who received at least one dose of study treatment. This study is registered with ClinicalTrials.gov, NCT04214288, and is ongoing.\n\nFindings: Between May 11, 2020, and Aug 10, 2021, 240 patients were randomly assigned to receive camizestrant 75 mg (n=74), 150 mg (n=73), 300 mg (n=20), or fulvestrant (n=73), and were included in the full analysis set. All patients received at least one dose of study drug. Median follow-up was 16·6 months (IQR 12·9-19·4) for the camizestrant 75 mg group, 16·3 months (12·9-18·3) for the camizestrant 150 mg group, and 14·7 months (12·7-20·1) for the fulvestrant 500 mg group. Median progression-free survival was 7·2 months (90% CI 3·7-10·9) with camizestrant 75 mg, 7·7 months (5·5-12·9) with camizestrant 150 mg, and 3·7 months (2·0-6·0) with fulvestrant. The hazard ratio for camizestrant 75 mg versus fulvestrant was 0·59 (90% CI 0·42-0·82; p=0·017), and the hazard ratio for camizestrant 150 mg versus fulvestrant was 0·64 (0·46-0·89; p=0·0090). Treatment-related adverse events occurred in 39 (53%) of 74 patients in the camizestrant 75 mg group, 49 (67%) of 73 patients in the camizestrant 150 mg group, 14 (70%) of 20 patients in the camizestrant 300 mg group, and 13 (18%) of 73 patients in the fulvestrant group. No single grade 3 or worse treatment-emergent adverse event occurred in more than two (3%) patients in any group. Serious treatment-emergent adverse events occurred in six (8%) patients in the camizestrant 75 mg group, seven (10%) patients in the camizestrant 150 mg group, two (10%) patients in the camizestrant 300 mg group, and four (5%) patients in the fulvestrant group. No treatment-related deaths occurred.\n\nInterpretation: Camizestrant at 75 and 150 mg showed a significant benefit in progression-free survival versus fulvestrant. These results support further development of camizestrant for the treatment of oestrogen receptor-positive, HER2-negative breast cancer.\n\nFunding: AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 39481395 (DOI 10.1016/s1470-2045(24)00387-5). Its abstract cites the registry id NCT04214288, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2024, doi: "10.1016/s1470-2045(24)00387-5", pmid: "39481395", authors: "Oliveira M, Pominchuk D, Nowecki Z, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04214288 with the most citations, so it is the natural first reading for anyone following the SERENA-2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2024","url":"https://doi.org/10.1016/s1470-2045(24)00387-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39481395/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39481395"},{"label":"ClinicalTrials.gov NCT04214288","url":"https://clinicaltrials.gov/study/NCT04214288"}], tags: ["europepmc-ingest"], trials: ["nct04214288"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct04454437-int-j-cancer-2023", name: "A Phase IIb, single arm, multicenter trial of sacituzumab govitecan in Chinese patients with metastatic triple-negative breast cancer who received at least two prior treatments", tldr: "Published report from the trial registered as NCT04454437, in International journal of cancer (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Refractory or relapsing metastatic triple-negative breast cancer (mTNBC) has a poor prognosis. Sacituzumab govitecan (SG) is a novel antibody-drug conjugate, targeting human trophoblast cell-surface antigen 2 (Trop-2). This is the first report of SG's efficacy and safety in Chinese patients with mTNBC. EVER-132-001 (NCT04454437) was a multicenter, single-arm, Phase IIb study in Chinese patients with mTNBC who failed ≥2 prior chemotherapy regimens. Eligible patients received 10 mg/kg SG on Days 1 and 8 of each 21-day treatment cycle, until disease progression/unacceptable toxicity. The primary endpoint was objective response rate (ORR) assessed by the Independent Review Committee. Secondary endpoints included: duration of response (DOR), clinical benefit rate (CBR), progression-free survival (PFS), overall survival (OS) and safety. Eighty female Chinese patients (median age 47.6 years; range 24-69.9 years) received ≥1 SG dose with a median of 8 treatment cycles by the cutoff date (August 6, 2021). Median number of prior systemic cancer treatments was 4.0 (range 2.0-8.0). ORR and CBR were reported 38.8% (95% confidence interval [CI]: 28.06-50.30) and 43.8% (95% CI, 32.68-55.30) of patients, respectively. The median PFS was 5.55 months (95% CI, 4.14-N/A). SG-related Grade ≥3 treatment-emergent adverse events (TEAEs) were reported in 71.3%, the most common were neutrophil count decreased (62.5%), white blood cell count decreased (48.8%) and anemia (21.3%); 6.3% discontinued SG because of TEAEs. SG demonstrated substantial clinical activity in heavily pretreated Chinese patients with mTNBC. The observed safety profile was generally manageable.\n\nIndexed on Europe PMC as PubMed record 36621000 (DOI 10.1002/ijc.34424). Its abstract cites the registry id NCT04454437, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "International journal of cancer", year: 2023, doi: "10.1002/ijc.34424", pmid: "36621000", authors: "Xu B, Ma F, Wang T, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04454437 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Int J Cancer 2023","url":"https://doi.org/10.1002/ijc.34424"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36621000/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36621000"},{"label":"ClinicalTrials.gov NCT04454437","url":"https://clinicaltrials.gov/study/NCT04454437"}], tags: ["europepmc-ingest"], trials: ["nct04454437"], journals: ["international-journal-of-cancer"] }),
  p({ id: "paper-nct04576455-j-clin-oncol-2024", name: "Giredestrant for Estrogen Receptor-Positive, HER2-Negative, Previously Treated Advanced Breast Cancer: Results From the Randomized, Phase II acelERA Breast Cancer Study", tldr: "Published report from the trial registered as NCT04576455, in Journal of Clinical Oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: To compare giredestrant and physician's choice of endocrine monotherapy (PCET) for estrogen receptor-positive, HER2-negative, advanced breast cancer (BC) in the phase II acelERA BC study (ClinicalTrials.gov identifier: NCT04576455).\n\nMethods: Post-/pre-/perimenopausal women, or men, age 18 years or older with measurable disease/evaluable bone lesions, whose disease progressed after 1-2 lines of systemic therapy (≤1 targeted, ≤1 chemotherapy regimen, prior fulvestrant allowed) were randomly assigned 1:1 to giredestrant (30 mg oral once daily) or fulvestrant/aromatase inhibitor per local guidelines (+luteinizing hormone-releasing hormone agonist in pre-/perimenopausal women, and men) until disease progression/unacceptable toxicity. Stratification was by visceral versus nonvisceral disease, prior cyclin-dependent kinase 4/6 inhibitor, and prior fulvestrant. The primary end point was investigator-assessed progression-free survival (INV-PFS).\n\nResults: At clinical cutoff (February 18, 2022; median follow-up: 7.9 months; N = 303), the INV-PFS hazard ratio (HR) was 0.81 (95% CI, 0.60 to 1.10; P =.1757). In the prespecified secondary end point analysis of INV-PFS by ESR1 mutation (m) status in circulating tumor DNA-evaluable patients (n = 232), the HR in patients with a detectable ESR1 m (n = 90) was 0.60 (95% CI, 0.35 to 1.03) versus 0.88 (95% CI, 0.54 to 1.42) in patients with no ESR1 m detected (n = 142). Related grade 3-4 adverse events (AEs), serious AEs, and discontinuations due to AEs were balanced across arms.\n\nConclusion: Although the acelERA BC study did not reach statistical significance for its primary INV-PFS end point, there was a consistent treatment effect with giredestrant across most key subgroups and a trend toward favorable benefit among patients with ESR1 -mutated tumors. Giredestrant was well tolerated, with a safety profile comparable to PCET and consistent with known endocrine therapy risks. Overall, these data support the continued investigation of giredestrant in other studies.\n\nIndexed on Europe PMC as PubMed record 38537155 (DOI 10.1200/jco.23.01500). Its abstract cites the registry id NCT04576455, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2024, doi: "10.1200/jco.23.01500", pmid: "38537155", authors: "Martín M, Lim E, Chavez-MacGregor M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04576455 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2024","url":"https://doi.org/10.1200/jco.23.01500"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38537155/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38537155"},{"label":"ClinicalTrials.gov NCT04576455","url":"https://clinicaltrials.gov/study/NCT04576455"}], tags: ["europepmc-ingest"], trials: ["nct04576455"], journals: ["jco"] }),
  p({ id: "paper-nct05077449-nat-commun-2025", name: "Bireociclib plus fulvestrant for HR+/HER2- advanced female breast cancer progressed on or after endocrine therapy: phase 3 BRIGHT-2 study interim analysis", tldr: "Published report from the trial registered as NCT05077449, in Nature Communications (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "The BRIGHT-2 study (NCT05077449) is a randomized, double-blind, placebo-controlled, phase 3 trial evaluating the efficacy and safety of bireociclib plus fulvestrant (BF) vs. placebo plus fulvestrant (F) in Chinese female patients with hormone receptor-positive (HR+)/HER2-negative (HER2-) advanced breast cancer (ABC) who had progressed on or after prior endocrine therapy (ET). Interim results were analyzed after 70% of progression-free survival (PFS) events across 64 centers in China between December 8, 2021, and March 28, 2023. Patients were randomized (2:1) to receive BF or F, with stratification based on visceral involvement (yes/no) and resistance to prior primary or secondary ET. As the primary outcome, PFS was significantly prolonged in the BF group (n = 204) (12.94 months; 95% CI: 11.07-not reached) compared to 7.29 months (95% CI: 5.45-11.04) in the F group (n = 101) (hazard ratio, 0.56; 95% CI: 0.39-0.80; p = 0.001). The objective response rate in the BF group was 39.7% in the intention-to-treat population. Grade ≥3 adverse events were more frequent in the BF group (64.7%) than in the F group (18.8%), with neutropenia, leukopenia, and anemia being the most common. These findings suggest that BF is a promising therapeutic option for patients with HR+/HER2- ABC following ET failure.\n\nIndexed on Europe PMC as PubMed record 40204778 (DOI 10.1038/s41467-025-58647-z). Its abstract cites the registry id NCT05077449, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Communications", year: 2025, doi: "10.1038/s41467-025-58647-z", pmid: "40204778", authors: "Wang J, Zhang Q, Li H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05077449 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Commun 2025","url":"https://doi.org/10.1038/s41467-025-58647-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40204778/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40204778"},{"label":"ClinicalTrials.gov NCT05077449","url":"https://clinicaltrials.gov/study/NCT05077449"}], tags: ["europepmc-ingest"], trials: ["nct05077449"], journals: ["nature-communications"] }),
  p({ id: "paper-nct05101096-int-j-clin-oncol-2024", name: "Preliminary results from ASCENT-J02: a phase 1/2 study of sacituzumab govitecan in Japanese patients with advanced solid tumors", tldr: "Published report from the ASCENT-J02 trial registered as NCT05101096, in International journal of clinical oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sacituzumab govitecan (SG) is a Trop-2-directed antibody-drug conjugate approved outside Japan for second-line and later metastatic triple-negative breast cancer (mTNBC), based on the ASCENT study (NCT02574455). We report SG safety and efficacy in an open-label, phase 1/2 bridging study in Japanese patients with advanced solid tumors (ASCENT-J02; NCT05101096; jRCT2031210346).\n\nMethods: Phase 1 was a standard 3 + 3 design. Patients received intravenous SG 6 mg/kg, escalating to 10 mg/kg, on Days 1 and 8 per 21-day cycle; primary endpoints were safety, incidence of dose-limiting toxicity/toxicities (DLTs), and determination of the recommended phase 2 dose (RP2D). In the multicohort phase 2 study, patients in the mTNBC cohort with previously treated disease received SG at the RP2D; primary endpoint was independent review committee (IRC)-assessed objective response rate (ORR; RECIST v1.1). Safety was a secondary endpoint.\n\nResults: In phase 1 (N = 15), one DLT (grade 3 elevated transaminases) occurred with SG 10 mg/kg; RP2D was SG 10 mg/kg regardless of UGT1A1 status. In phase 2, 36 patients with mTNBC received SG 10 mg/kg. At median follow-up of 6.1 months, IRC-assessed ORR was 25.0% (95% CI 12.1-42.2; P = 0.0077). Median progression-free survival was 5.6 months (95% CI 3.9-not reached [NR]); median overall survival was NR. No treatment-emergent adverse events led to discontinuation or death.\n\nConclusions: SG RP2D was established as 10 mg/kg in Japanese patients. SG showed efficacy in Japanese patients with previously treated mTNBC, a manageable safety profile, and no new safety signals, consistent with the previous ASCENT study.\n\nIndexed on Europe PMC as PubMed record 39302614 (DOI 10.1007/s10147-024-02589-x). Its abstract cites the registry id NCT05101096, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "International journal of clinical oncology", year: 2024, doi: "10.1007/s10147-024-02589-x", pmid: "39302614", authors: "Naito Y, Nakamura S, Kawaguchi-Sakita N, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05101096 with the most citations, so it is the natural first reading for anyone following the ASCENT-J02 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","The abstract cites more than one registry id (NCT02574455, NCT05101096); it was kept because the trial's acronym appears in the title."], links: [{"label":"Int J Clin Oncol 2024","url":"https://doi.org/10.1007/s10147-024-02589-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39302614/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39302614"},{"label":"ClinicalTrials.gov NCT05101096","url":"https://clinicaltrials.gov/study/NCT05101096"}], tags: ["europepmc-ingest"], trials: ["nct05101096"], journals: ["international-journal-of-clinical-oncology"] }),
  p({ id: "paper-nct05227664-nat-med-2026", name: "First-line PD-1/VEGF bispecific antibody plus chemotherapy in triple-negative breast cancer: a phase 2 trial", tldr: "Published report from the trial registered as NCT05227664, in Nature Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Triple-negative breast cancer is an aggressive subtype comprising 10-20% of all breast cancer cases and has a worse prognosis than other subtypes. This open-label, multicenter, single-arm, phase 2 clinical trial evaluates the safety and efficacy of ivonescimab combined with chemotherapy as first-line treatment in female patients with locally advanced unresectable or metastatic triple-negative breast cancer who have not received previous systemic therapy. Eligible patients received ivonescimab 20 mg kg -1 intravenously every 2 weeks and paclitaxel 90 mg m - 2 or nab-paclitaxel 100 mg m - 2 intravenously on days 1, 8 and 15 of each 4-week treatment cycle. The primary endpoints were safety and the investigator-assessed objective response rate per RECIST v.1.1. A total of 36 patients were enrolled. at July 15, 2025, the median follow-up duration was 22.1 months. The primary endpoints were met. Treatment-related adverse events occurred in 36 (100.0%) patients. Grade ≥3 treatment-related adverse events were reported in 21 (58.3%) patients. No treatment-related deaths occurred. Immune-related adverse events occurred in 15 (41.7%) patients, with grade ≥3 events in 4 (11.1%) patients. Of the 35 patients evaluable for treatment efficacy, the objective response rate was 80.0% (95% confidence interval: 63.1-91.6), including 2 (5.7%) complete responses and 26 (74.3%) partial responses. Ivonescimab plus chemotherapy demonstrated encouraging antitumor activity as first-line therapy for patients with previously untreated advanced triple-negative breast cancer and merits further investigation. ClinicalTrials.gov identifier: NCT05227664.\n\nIndexed on Europe PMC as PubMed record 42587052 (DOI 10.1038/s41591-026-04564-7). Its abstract cites the registry id NCT05227664, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2026, doi: "10.1038/s41591-026-04564-7", pmid: "42587052", authors: "Shao X, Tian C, Chen Z, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05227664 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2026","url":"https://doi.org/10.1038/s41591-026-04564-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42587052/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42587052"},{"label":"ClinicalTrials.gov NCT05227664","url":"https://clinicaltrials.gov/study/NCT05227664"}], tags: ["europepmc-ingest"], trials: ["nct05227664"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05347134-nat-med-2025", name: "Sacituzumab tirumotecan in previously treated metastatic triple-negative breast cancer: a randomized phase 3 trial", tldr: "Published report from the trial registered as NCT05347134, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Chemotherapy remains a standard treatment option for metastatic triple-negative breast cancer (TNBC) but is associated with limited survival. Although some targeted antibody-drug conjugates have demonstrated clinical benefits and are considered standard therapy, persistent unmet medical needs remain due to varying accessibility. The OptiTROP-Breast01 phase 3 trial assessed sacituzumab tirumotecan (sac-TMT) versus chemotherapy in patients with locally recurrent or metastatic TNBC who had received two or more prior therapies, including at least one for metastatic disease. Patients were randomized to sac-TMT (n = 130) or chemotherapy (n = 133). The primary endpoint of progression-free survival (PFS) by blinded independent central review (BICR) was met based on the protocol-specified interim analysis. At final analysis, the median PFS by BICR was 6.7 (95% confidence interval (CI), 5.5-8.0) months with sac-TMT and 2.5 (95% CI, 1.7-2.7) months with chemotherapy (hazard ratio (HR), 0.32; 95% CI, 0.24-0.44; P < 0.00001). Concurrently, at the protocol-specified interim analysis for overall survival (OS), the median OS was not reached (95% CI, 11.2 months to not estimable (NE)) with sac-TMT and 9.4 (95% CI, 8.5-11.7) months with chemotherapy (HR, 0.53; 95% CI, 0.36-0.78; P = 0.0005). The percentage of patients with an objective response was 45.4% with sac-TMT and 12.0% with chemotherapy. The median duration of response was 7.1 (95% CI, 5.6-NE) months with sac-TMT and 3.0 (95% CI, 2.5-NE) months with chemotherapy. The most common treatment-related adverse event with sac-TMT was hematologic toxicity. Sac-TMT demonstrated statistically significant and clinically meaningful improvements in PFS compared to chemotherapy, with a manageable safety profile. The study findings support sac-TMT as an additional effective treatment option for pretreated metastatic TNBC. ClinicalTrials.gov identifier: NCT05347134.\n\nIndexed on Europe PMC as PubMed record 40217078 (DOI 10.1038/s41591-025-03630-w). Its abstract cites the registry id NCT05347134, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-03630-w", pmid: "40217078", authors: "Yin Y, Fan Y, Ouyang Q, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05347134 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-03630-w"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40217078/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40217078"},{"label":"ClinicalTrials.gov NCT05347134","url":"https://clinicaltrials.gov/study/NCT05347134"}], tags: ["europepmc-ingest"], trials: ["nct05347134"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05587296-n-engl-j-med-2025", name: "Elinzanetant for Vasomotor Symptoms from Endocrine Therapy for Breast Cancer", tldr: "Published report from the OASIS-4 trial registered as NCT05587296, in New England Journal of Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Women receiving endocrine therapy for hormone receptor (HR)-positive breast cancer or its prevention among those at high risk for breast cancer commonly have vasomotor symptoms. Data are lacking on the effects of elinzanetant, a neurokinin-targeted therapy shown to be effective in treating vasomotor symptoms, in this population.\n\nMethods: We performed a phase 3 trial involving women 18 to 70 years of age with moderate-to-severe vasomotor symptoms associated with endocrine therapy for HR-positive breast cancer or its prevention. Women were randomly assigned in a 2:1 ratio to receive once-daily elinzanetant at a dose of 120 mg for 52 weeks or once-daily placebo for 12 weeks followed by once-daily elinzanetant at a dose of 120 mg for 40 weeks. The primary end points were the change in the mean daily frequency of moderate-to-severe vasomotor symptoms from baseline to week 4 and to week 12.\n\nResults: A total of 316 participants were assigned to the elinzanetant group and 158 to the placebo-elinzanetant group. At baseline, the mean daily frequency of moderate-to-severe vasomotor symptoms was 11.4 episodes (95% confidence interval [CI], 10.7 to 12.2) in the elinzanetant group and 11.5 episodes (95% CI, 10.5 to 12.5) in the placebo-elinzanetant group. At week 4, the mean change from baseline in the mean daily frequency of moderate-to-severe vasomotor symptoms was -6.5 episodes (95% CI, -7.2 to -5.8) among those who were receiving elinzanetant and -3.0 episodes (95% CI, -3.9 to -2.2) among those who were receiving placebo (least-squares mean difference, -3.5 episodes; 95% CI, -4.4 to -2.6; P<0.001). At week 12, the mean change was -7.8 episodes (95% CI, -8.5 to -7.1) among those receiving elinzanetant and -4.2 episodes (95% CI, -5.2 to -3.2) among those receiving placebo (least-squares mean difference, -3.4 episodes; 95% CI, -4.2 to -2.5; P<0.001). During weeks 1 through 12, a total of 220 participants (69.8%) receiving elinzanetant and 98 (62.0%) receiving placebo reported at least one adverse event that occurred while receiving elinzanetant or placebo, with the most common being headache, fatigue, and somnolence. Serious adverse events occurred during weeks 1 through 12 in 8 participants (2.5%) receiving elinzanetant and 1 participant (0.6%) receiving placebo.\n\nConclusions: Elinzanetant led to a significantly lower frequency of vasomotor symptoms associated with endocrine therapy than placebo. (Funded by Bayer; OASIS-4 ClinicalTrials.gov number, NCT05587296.).\n\nIndexed on Europe PMC as PubMed record 40454634 (DOI 10.1056/nejmoa2415566). Its abstract cites the registry id NCT05587296, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2415566", pmid: "40454634", authors: "Cardoso F, Parke S, Brennan DJ, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05587296 with the most citations, so it is the natural first reading for anyone following the OASIS-4 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2415566"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40454634/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40454634"},{"label":"ClinicalTrials.gov NCT05587296","url":"https://clinicaltrials.gov/study/NCT05587296"}], tags: ["europepmc-ingest"], trials: ["nct05587296"], journals: ["nejm"] }),
  p({ id: "paper-nct06198751-j-clin-oncol-2026", name: "Efficacy and Safety of Neoadjuvant TQB2102 in Locally Advanced or Early Human Epidermal Growth Factor Receptor 2-Positive Breast Cancer: A Randomized, Open-Label, Multicenter, Phase II Trial", tldr: "Published report from the trial registered as NCT06198751, in Journal of Clinical Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: To evaluate the efficacy and safety of the bispecific human epidermal growth factor receptor 2 (HER2)-directed antibody-drug conjugate (ADC) TQB2102 in the neoadjuvant treatment of HER2-positive breast cancer.\n\nPatients and methods: This randomized, open-label, multicenter, phase II study (ClinicalTrials.gov identifier: NCT06198751) enrolled HER2-positive patients with stage II and III disease. Patients were stratified by hormone receptor status and randomly assigned (1:1) to receive 6.0 mg/kg once every 3 weeks of TQB2102 for six (cohort 1) or eight cycles (cohort 2) or 7.5 mg/kg once every 3 weeks for six (cohort 3) or eight cycles (cohort 4). The primary end point was total pathologic complete response (tpCR) rate across all four cohorts (n = 26 per cohort). When the lower limit of the 90% CI (Clopper-Pearson exact binomial test) for tpCR rate exceeded 40%, efficacy was considered better than that of the historical control.\n\nResults: Between February 5, 2024, and September 24, 2024, 104 patients were enrolled, with 26 patients in each cohort. The tpCR rates were 57.7% (15 of 26 [90% CI, 43.2 to 71.3]; P =.04) for cohort 1, 76.9% (20 of 26 [90% CI, 62.3 to 87.6]; P <.01) for cohort 2, 61.5% (16 of 26 [90% CI, 46.5 to 74.8]; P =.02) for cohort 3, and 69.2% (18 of 26 [90% CI, 54.6 to 81.3]; P <.01) for cohort 4. The incidence rates of grade ≥3 treatment-related adverse events were 23.1% (6 of 26) for cohort 1, 30.8% (8 of 26) for cohort 2, 30.8% (8 of 26) for cohort 3, and 26.9% (7 of 26) for cohort 4. No treatment-related deaths occurred in any groups.\n\nConclusion: To our knowledge, this was the first study to report the efficacy and safety of the bispecific HER2-directed ADC TQB2102 in the neoadjuvant setting for HER2-positive breast cancer. TQB2102 showed robust activity and was well-tolerated.\n\nIndexed on Europe PMC as PubMed record 41289548 (DOI 10.1200/jco-25-01153). Its abstract cites the registry id NCT06198751, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2026, doi: "10.1200/jco-25-01153", pmid: "41289548", authors: "Li JJ, Zhang WJ, Zeng XH, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06198751 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2026","url":"https://doi.org/10.1200/jco-25-01153"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41289548/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41289548"},{"label":"ClinicalTrials.gov NCT06198751","url":"https://clinicaltrials.gov/study/NCT06198751"}], tags: ["europepmc-ingest"], trials: ["nct06198751"], journals: ["jco"] }),
  p({ id: "paper-nct06747338-jama-oncol-2026", name: "Neoadjuvant Anbenitamab and HB1801 in ERBB2-Positive Breast Cancer: A Phase 3 Randomized Clinical Trial", tldr: "Published report from the trial registered as NCT06747338, in JAMA Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: The combination of neoadjuvant taxanes with trastuzumab and pertuzumab remains the cornerstone treatment strategy in ERBB2-positive breast cancer. Anbenitamab (a ERBB2-biparatopic antibody that induces profound receptor clustering) and HB1801 (a solvent-free albumin-bound docetaxel), have shown promising antitumor activity and an acceptable safety profile in patients with breast cancer.\n\nObjective: To evaluate whether neoadjuvant anbenitamab combined with HB1801 could improve efficacy without increasing toxic effects for patients with early ERBB2-positive breast cancer.\n\nDesign, setting, and participants: This multicenter, phase 3 registrational randomized clinical trial enrolled patients with stage II or III ERBB2-positive breast cancer from 61 hospitals in China between December 19, 2024, and August 29, 2025 (data cutoff: January 28, 2026). Data were analyzed from February 1 to March 20, 2026.\n\nInterventions: Patients were randomly assigned (1:1) to receive 6 cycles of neoadjuvant anbenitamab plus HB1801, with or without carboplatin (investigational group), or trastuzumab, pertuzumab, and docetaxel, with or without carboplatin (control group).\n\nMain outcomes and measures: The primary end point was total pathological complete response (tpCR) assessed by a blinded independent review committee.\n\nResults: Among 521 included patients (median [IQR] age, 52.0 [23-79] years), 263 were randomized to the investigational group and 258 to the control group. The tpCR rate was significantly higher in the investigational group than the control group (164 patients [62.4%] vs 132 patients [51.2%]; absolute difference, 11.4 [95% CI, 3.2 to 19.6] percentage points; P =.004). Benefit was consistent across subgroups, including subgroups with hormone receptor-positive disease (77 patients [51.7%] vs 63 patients [44.4%]), hormone receptor-negative disease (87 patients [76.3%] vs 69 patients [59.5%]), early-stage disease (111 patients [63.8%] vs 87 patients [51.8%]), locally advanced disease (53 patients [59.6%] vs 45 patients [50.0%]), with carboplatin treatment (74 patients [66.7%] vs 61 patients [54.5%]), and without carboplatin treatment (90 patients [59.2%] vs 71 patients [48.6%]). Grade 3 or 4 treatment-related adverse events occurred in 77 patients (29.3%) in the investigational group and 73 patients (28.3%) of the control group. No treatment-related deaths occurred.\n\nConclusions and relevance: This randomized clinical trial found that neoadjuvant anbenitamab and HB1801 in patients with breast cancer significantly improved the tpCR rate compared with standard therapy with a highly manageable safety profile. This new combination may offer an improved treatment option, although long-term survival follow-up analyses are warranted.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT06747338.\n\nIndexed on Europe PMC as PubMed record 42690668 (DOI 10.1001/jamaoncol.2026.3329). Its abstract cites the registry id NCT06747338, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2026, doi: "10.1001/jamaoncol.2026.3329", pmid: "42690668", authors: "Li J, Liu T, Yu KD, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06747338 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2026","url":"https://doi.org/10.1001/jamaoncol.2026.3329"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42690668/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42690668"},{"label":"ClinicalTrials.gov NCT06747338","url":"https://clinicaltrials.gov/study/NCT06747338"}], tags: ["europepmc-ingest"], trials: ["nct06747338"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct06968585-j-clin-oncol-2026", name: "Trastuzumab Botidotin Versus Trastuzumab Emtansine in Human Epidermal Growth Factor Receptor 2-Positive Advanced Breast Cancer: A Phase III, Open-Label, Randomized Controlled Trial", tldr: "Published report from the trial registered as NCT06968585, in Journal of Clinical Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: To evaluate the safety and efficacy of the novel human epidermal growth factor receptor 2 (HER2)-directed antibody-drug conjugate, trastuzumab botidotin, for the treatment of HER2-positive unresectable/metastatic breast cancer (BC).\n\nMethods: In this phase III, open-label, multicenter trial (ClinicalTrials.gov identifier: NCT06968585), conducted at 57 centers in China, adult patients with HER2-positive, unresectable/metastatic BC who had received prior trastuzumab and a taxane were randomly assigned (1:1) to receive trastuzumab botidotin or trastuzumab emtansine. The primary end point was progression-free survival (PFS), assessed by blinded independent central review (BICR), using an intention-to-treat analysis. In a prespecified interim analysis of PFS per BICR, trastuzumab botidotin met the prespecified superiority boundary ( P <.0001). We report here the prespecified final analysis of PFS.\n\nResults: Between July 18, 2023, and April 26, 2024, 365 patients were randomly assigned to trastuzumab botidotin (n = 182) or trastuzumab emtansine (n = 183). At data cutoff (median follow-up, 14.9 months), trastuzumab botidotin resulted in longer PFS than trastuzumab emtansine (median, 11.1 v 4.4 months; hazard ratio [HR], 0.39 [95% CI, 0.30 to 0.51]; nominal P <.0001). Benefit was consistent across subgroups, including those defined by prior lines of anti-HER2 therapy, prior pertuzumab or anti-HER2 tyrosine kinase inhibitors, and visceral metastases. The objective response rate was 76.9% (95% CI, 70.1 to 82.8) with trastuzumab botidotin and 53.0% (95% CI, 45.5 to 60.4) with trastuzumab emtansine. Overall survival data were immature (medians not reached in either group; HR, 0.62 [95% CI, 0.38 to 1.03]). Grade ≥3 treatment-emergent adverse events occurred in 127 (69.8%) and 116 (63.7%) patients in each group, respectively. Ocular treatment-related adverse events had a high incidence with trastuzumab botidotin; however, with a protocol-defined algorithm, most events generally recovered or resolved. Trastuzumab botidotin treatment had low incidences of pulmonary, hematologic, hepatic, and GI toxicities.\n\nConclusion: Among patients with HER2-positive advanced BC previously treated with trastuzumab and a taxane, trastuzumab botidotin resulted in significantly longer PFS than trastuzumab emtansine, with a distinct safety profile.\n\nIndexed on Europe PMC as PubMed record 42727044 (DOI 10.1200/jco-26-00602). Its abstract cites the registry id NCT06968585, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2026, doi: "10.1200/jco-26-00602", pmid: "42727044", authors: "Zhang J, Ouyang Q, Zhang Q, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06968585 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2026","url":"https://doi.org/10.1200/jco-26-00602"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42727044/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42727044"},{"label":"ClinicalTrials.gov NCT06968585","url":"https://clinicaltrials.gov/study/NCT06968585"}], tags: ["europepmc-ingest"], trials: ["nct06968585"], journals: ["jco"] }),
  p({ id: "paper-wisdom-trial-jama-2026", name: "Risk-Based vs Annual Breast Cancer Screening: The WISDOM Randomized Clinical Trial", tldr: "Published report from the WISDOM trial registered as NCT02620852, in JAMA (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Individual breast cancer risk can guide screening initiation, frequency, use of supplemental imaging, and preventive measures to improve breast cancer screening by shifting resources from low-risk women to high-risk women.\n\nObjective: To determine whether risk-based breast cancer screening is a feasible alternative to annual mammography.\n\nDesign, setting, and participants: Parallel-group, pragmatic, multicenter randomized clinical trial comparing risk-based (n = 14 212) with annual (n = 14 160) breast cancer screening. Women aged 40 to 74 years without prior diagnoses of breast cancer or ductal carcinoma in situ, or prophylactic bilateral mastectomy, were recruited from all 50 US states from September 2016 to February 2023, with follow-up through September 5, 2025 (median follow-up, 5.1 years). Statistical analysis was conducted between July and November 2025. All study procedures were conducted via an online platform. Women who declined randomization were enrolled in an observational cohort.\n\nInterventions: Risk assessment included sequencing of 9 susceptibility genes, polygenic risk score, and the Breast Cancer Surveillance Consortium version 2 model. The risk-based group received 1 of 4 recommendations: (1) highest risk (≥6% 5-year risk, high-penetrance pathogenic variant): alternating mammography and magnetic resonance imaging (MRI) every 6 months and counseling; (2) elevated risk (top 2.5 risk percentile by age): annual mammography and risk-reduction counseling; (3) average risk: biennial mammography; and (4) low risk (aged 40-49 years and <1.3% 5-year risk): no screening until risk is 1.3% or greater or age 50 years.\n\nMain outcomes and measures: The coprimary outcomes included noninferiority for stage ≥IIB cancers and superiority in reducing biopsy rates. Secondary outcomes included identification of stage ≥IIA cancers, mammogram rates, uptake of prevention strategies in higher risk cohorts, preference for screening group in the observational cohort, ductal carcinoma in situ, MRI, and stage-specific cancer rates.\n\nResults: A total of 28 372 women were randomized. The mean (SD) age was 54 (9.6) years and the majority were non-Hispanic White (77%). The rate of stage ≥IIB cancers was noninferior in the risk-based compared with the annual group (risk-based: 30.0 [95% CI, 16.3-43.8] vs annual: 48.0 [95% CI, 30.1-65.5] per 100 000 person-years; rate difference, -18.0 per 100 000 person-years [95% CI, -40.2 to 4.1]). The rate of breast biopsies was not lower in the risk-based group (rate difference, 98.7 per 100 000 person-years [95% CI, -17.9 to 215.3]) despite fewer mammograms (rate difference, -3835.9 [95% CI, -4516.8 to -3154.9]). The cumulative incidence of cancer, biopsy, mammogram, and MRI increased as risk category increased. In the observational cohort, 89% of participants (15 980/18 031) chose risk based.\n\nConclusions: Risk-based breast cancer screening that includes population-based genetic testing safely stratified risk and screening intensity, but did not reduce biopsy rates.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02620852.\n\nIndexed on Europe PMC as PubMed record 41385349 (DOI 10.1001/jama.2025.24784). Its abstract cites the registry id NCT02620852, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2026, doi: "10.1001/jama.2025.24784", pmid: "41385349", authors: "Esserman LJ, Fiscalini AS, Naeim A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02620852 with the most citations, so it is the natural first reading for anyone following the WISDOM trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2026","url":"https://doi.org/10.1001/jama.2025.24784"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41385349/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41385349"},{"label":"ClinicalTrials.gov NCT02620852","url":"https://clinicaltrials.gov/study/NCT02620852"}], tags: ["europepmc-ingest"], trials: ["wisdom-trial"], journals: ["jama"] }),
  p({ id: "paper-alascca-n-engl-j-med-2025", name: "Low-Dose Aspirin for PI3K-Altered Localized Colorectal Cancer", tldr: "Published report from the ALASCCA trial registered as NCT02647099, in New England Journal of Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Aspirin reduces the incidence of colorectal adenoma and colorectal cancer among high-risk persons. Observational studies suggest that aspirin may also improve disease-free survival after diagnosis, particularly among patients with tumors harboring somatic PIK3CA mutations. However, data from randomized trials are lacking.\n\nMethods: We conducted a double-blind, randomized, placebo-controlled trial involving patients with stage I, II, or III rectal cancer or stage II or III colon cancer with somatic alterations in PI3K pathway genes. The patients were assigned in a 1:1 ratio to receive 160 mg of aspirin or matched placebo once daily for 3 years. Patients with prespecified PIK3CA hotspot mutations in exon 9 or 20 (group A alterations) and those with other moderate- or high-impact somatic variants in PIK3CA, PIK3R1, or PTEN (group B alterations) were eligible for randomization. The primary end point was colorectal cancer recurrence, assessed in a time-to-event analysis, in patients with group A alterations. Secondary end points included colorectal cancer recurrence in patients with group B alterations, disease-free survival, and safety.\n\nResults: Alterations in PI3K pathway genes were detected in 1103 of 2980 patients (37.0%) with complete genomic data. Of 515 patients with group A alterations and 588 patients with group B alterations, 314 and 312, respectively, were assigned to receive aspirin or placebo. The estimated 3-year cumulative incidence of recurrence was 7.7% with aspirin and 14.1% with placebo (hazard ratio, 0.49; 95% confidence interval [CI], 0.24 to 0.98; P = 0.04) among patients with group A alterations and 7.7% and 16.8%, respectively (hazard ratio, 0.42; 95% CI, 0.21 to 0.83), among those with group B alterations. The estimated 3-year disease-free survival was 88.5% with aspirin and 81.4% with placebo (hazard ratio, 0.61; 95% CI, 0.34 to 1.08) among patients with group A alterations and 89.1% and 78.7%, respectively (hazard ratio, 0.51; 95% CI, 0.29 to 0.88), among those with group B alterations. Severe adverse events occurred in 16.8% of aspirin recipients and 11.6% of placebo recipients.\n\nConclusions: Aspirin led to a significantly lower incidence of colorectal cancer recurrence than placebo among patients with PIK3CA hotspot mutations in exon 9 or 20 and appeared to have a similar benefit among those with other somatic alterations in PI3K pathway genes. (Funded by the Swedish Research Council and others; ALASCCA ClinicalTrials.gov number, NCT02647099; EudraCT number, 2015-004240-19.).\n\nIndexed on Europe PMC as PubMed record 40961426 (DOI 10.1056/nejmoa2504650). Its abstract cites the registry id NCT02647099, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2504650", pmid: "40961426", authors: "Martling A, Hed Myrberg I, Nilbert M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02647099 with the most citations, so it is the natural first reading for anyone following the ALASCCA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2504650"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40961426/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40961426"},{"label":"ClinicalTrials.gov NCT02647099","url":"https://clinicaltrials.gov/study/NCT02647099"}], tags: ["europepmc-ingest"], trials: ["alascca"], journals: ["nejm"] }),
  p({ id: "paper-atomic-n-engl-j-med-2026", name: "Atezolizumab plus FOLFOX for Stage III Mismatch Repair-Deficient Colon Cancer", tldr: "Published report from the ATOMIC trial registered as NCT02912559, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Standard adjuvant chemotherapy for stage III colon cancer consists of a fluoropyrimidine-plus-oxaliplatin regimen. Whether the addition of atezolizumab (an anti-programmed death ligand 1 agent) to a modified FOLFOX6 regimen (fluorouracil, oxaliplatin, and leucovorin; called mFOLFOX6) would improve outcomes in patients with stage III colon cancer with mismatch repair-deficient (dMMR) status is unclear.\n\nMethods: In a phase 3 trial, we randomly assigned, in a 1:1 ratio, patients with resected stage III dMMR tumors to receive either adjuvant atezolizumab plus mFOLFOX6 for 6 months, with atezolizumab continued as monotherapy (for a total of 12 months of therapy), or mFOLFOX6 alone for 6 months. The primary end point was disease-free survival. Secondary end points were overall survival and the adverse-event profile.\n\nResults: A total of 355 patients were assigned to receive atezolizumab plus mFOLFOX6 and 357 to receive mFOLFOX6 alone. The median age of the patients was 64 years, 55.1% were women, and 53.9% had tumors that were T4, N2, or both (indicating high risk). At a median follow-up of 40.9 months, the 3-year disease-free survival was 86.3% (95% confidence interval [CI], 81.8 to 89.8) in the atezolizumab-mFOLFOX6 group, as compared with 76.2% (95% CI, 70.9 to 80.6) in the mFOLFOX6 group (hazard ratio for disease recurrence or death, 0.50; 95% CI, 0.35 to 0.73; P<0.001). Adverse events of grade 3 or 4 occurred in 84.1% of the patients who received atezolizumab plus mFOLFOX6 and in 71.9% of those who received mFOLFOX6 alone.\n\nConclusions: The addition of atezolizumab to mFOLFOX6 significantly improved disease-free survival among patients with stage III dMMR colon cancer. (Funded by the National Cancer Institute of the National Institutes of Health and Genentech; ATOMIC ClinicalTrials.gov number, NCT02912559.).\n\nIndexed on Europe PMC as PubMed record 41880612 (DOI 10.1056/nejmoa2507874). Its abstract cites the registry id NCT02912559, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2507874", pmid: "41880612", authors: "Sinicrope FA, Ou FS, Arnold D, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02912559 with the most citations, so it is the natural first reading for anyone following the ATOMIC trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2507874"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41880612/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41880612"},{"label":"ClinicalTrials.gov NCT02912559","url":"https://clinicaltrials.gov/study/NCT02912559"}], tags: ["europepmc-ingest"], trials: ["atomic"], journals: ["nejm"] }),
  p({ id: "paper-blue-c-n-engl-j-med-2024", name: "Next-Generation Multitarget Stool DNA Test for Colorectal Cancer Screening", tldr: "Published report from the BLUE-C trial registered as NCT04144738, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: A next-generation multitarget stool DNA test, including assessments of DNA molecular markers and hemoglobin level, was developed to improve the performance of colorectal cancer screening, primarily with regard to specificity.\n\nMethods: In a prospective study, we evaluated a next-generation multitarget stool DNA test in asymptomatic adults 40 years of age or older who were undergoing screening colonoscopy. The primary outcomes were sensitivity of the test for colorectal cancer and specificity for advanced neoplasia (colorectal cancer or advanced precancerous lesions). Advanced precancerous lesions included one or more adenomas or sessile serrated lesions measuring at least 1 cm in the longest dimension, lesions with villous histologic features, and high-grade dysplasia. Secondary objectives included the quantification of sensitivity for advanced precancerous lesions and specificity for nonneoplastic findings or negative colonoscopy and comparison of sensitivities for colorectal cancer and advanced precancerous lesions between the multitarget stool DNA test and a commercially available fecal immunochemical test (FIT).\n\nResults: Of 20,176 participants, 98 had colorectal cancer, 2144 had advanced precancerous lesions, 6973 had nonadvanced adenomas, and 10,961 had nonneoplastic findings or negative colonoscopy. With the next-generation test, sensitivity for colorectal cancer was 93.9% (95% confidence interval [CI], 87.1 to 97.7), and specificity for advanced neoplasia was 90.6% (95% CI, 90.1 to 91.0). Sensitivity for advanced precancerous lesions was 43.4% (95% CI, 41.3 to 45.6), and specificity for nonneoplastic findings or negative colonoscopy was 92.7% (95% CI, 92.2 to 93.1). With the FIT, sensitivity was 67.3% (95% CI, 57.1 to 76.5) for colorectal cancer and 23.3% (95% CI, 21.5 to 25.2) for advanced precancerous lesions; specificity was 94.8% (95% CI, 94.4 to 95.1) for advanced neoplasia and 95.7% (95% CI, 95.3 to 96.1) for nonneoplastic findings or negative colonoscopy. As compared with FIT, the next-generation test had superior sensitivity for colorectal cancer (P<0.001) and for advanced precancerous lesions (P<0.001) but had lower specificity for advanced neoplasia (P<0.001). No adverse events occurred.\n\nConclusions: The next-generation multitarget stool DNA test showed higher sensitivity for colorectal cancer and advanced precancerous lesions than FIT but also showed lower specificity. (Funded by Exact Sciences; BLUE-C ClinicalTrials.gov number, NCT04144738.).\n\nIndexed on Europe PMC as PubMed record 38477986 (DOI 10.1056/nejmoa2310336). Its abstract cites the registry id NCT04144738, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2310336", pmid: "38477986", authors: "Imperiale TF, Porter K, Zella J, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04144738 with the most citations, so it is the natural first reading for anyone following the BLUE-C trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2310336"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38477986/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38477986"},{"label":"ClinicalTrials.gov NCT04144738","url":"https://clinicaltrials.gov/study/NCT04144738"}], tags: ["europepmc-ingest"], trials: ["blue-c"], journals: ["nejm"] }),
  p({ id: "paper-breakwater-nat-med-2025", name: "Encorafenib, cetuximab and chemotherapy in BRAF-mutant colorectal cancer: a randomized phase 3 trial", tldr: "Published report from the BREAKWATER trial registered as NCT04607421, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Encorafenib + cetuximab (EC) is approved for previously treated BRAF V600E-mutant metastatic colorectal cancer (mCRC) based on the BEACON phase 3 study. Historically, first-line treatment of BRAF V600E-mutant mCRC with chemotherapy regimens has had limited efficacy. The phase 3 BREAKWATER study investigated EC+mFOLFOX6 versus standard of care (SOC) in patients with previously untreated BRAF V600E mCRC. The dual primary endpoint of progression-free survival is event driven; data were not mature at data cutoff. BREAKWATER met the other dual primary endpoint of objective response rate, demonstrating significant and clinically relevant improvement in objective response rate (EC+mFOLFOX6: 60.9%; SOC: 40.0%; odds ratio, 2.443; 95% confidence interval (CI): 1.403-4.253; 99.8% CI: 1.019-5.855; one-sided P = 0.0008). Median duration of response was 13.9 versus 11.1 months. At this first interim analysis of overall survival, the hazard ratio was 0.47 (95% CI: 0.318-0.691; repeated CI: 0.166-1.322). Serious adverse event rates were 37.7% versus 34.6%. The safety profiles were consistent with those known for each agent. BREAKWATER demonstrated a significantly improved response rate that was durable for first-line EC+mFOLFOX6 versus SOC in patients with BRAF V600E mCRC. ClinicalTrials.gov identifier: NCT04607421.\n\nIndexed on Europe PMC as PubMed record 39863775 (DOI 10.1038/s41591-024-03443-3). Its abstract cites the registry id NCT04607421, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-024-03443-3", pmid: "39863775", authors: "Kopetz S, Yoshino T, Van Cutsem E, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04607421 with the most citations, so it is the natural first reading for anyone following the BREAKWATER trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-024-03443-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39863775/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39863775"},{"label":"ClinicalTrials.gov NCT04607421","url":"https://clinicaltrials.gov/study/NCT04607421"}], tags: ["europepmc-ingest"], trials: ["breakwater"], journals: ["nature-medicine"] }),
  p({ id: "paper-checkmate-8hw-n-engl-j-med-2024", name: "Nivolumab plus Ipilimumab in Microsatellite-Instability-High Metastatic Colorectal Cancer", tldr: "Published report from the CheckMate 8HW trial registered as NCT04008030, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Patients with microsatellite-instability-high (MSI-H) or mismatch-repair-deficient (dMMR) metastatic colorectal cancer have poor outcomes with standard chemotherapy with or without targeted therapies. Nivolumab plus ipilimumab has shown clinical benefit in nonrandomized studies of MSI-H or dMMR metastatic colorectal cancer.\n\nMethods: In this phase 3 open-label trial, we randomly assigned patients with unresectable or metastatic colorectal cancer and MSI-H or dMMR status according to local testing to receive, in a 2:2:1 ratio, nivolumab plus ipilimumab, nivolumab alone, or chemotherapy with or without targeted therapies. The dual primary end points, assessed in patients with centrally confirmed MSI-H or dMMR status, were progression-free survival with nivolumab plus ipilimumab as compared with chemotherapy as first-line therapy and progression-free survival with nivolumab plus ipilimumab as compared with nivolumab alone in patients regardless of previous systemic treatment for metastatic disease. At this prespecified interim analysis, the first primary end point (involving nivolumab plus ipilimumab vs. chemotherapy) was assessed.\n\nResults: A total of 303 patients who had not previously received systemic treatment for metastatic disease were randomly assigned to receive nivolumab plus ipilimumab or chemotherapy; 255 patients had centrally confirmed MSI-H or dMMR tumors. At a median follow-up of 31.5 months (range, 6.1 to 48.4), progression-free survival outcomes (the primary analysis) were significantly better with nivolumab plus ipilimumab than with chemotherapy (P<0.001 for the between-group difference in progression-free survival, calculated with the use of a two-sided stratified log-rank test); 24-month progression-free survival was 72% (95% confidence interval [CI], 64 to 79) with nivolumab plus ipilimumab as compared with 14% (95% CI, 6 to 25) with chemotherapy. At 24 months, the restricted mean survival time was 10.6 months (95% CI, 8.4 to 12.9) longer with nivolumab plus ipilimumab than with chemotherapy, a finding consistent with the primary analysis of progression-free survival. Grade 3 or 4 treatment-related adverse events occurred in 23% of the patients in the nivolumab-plus-ipilimumab group and in 48% of the patients in the chemotherapy group.\n\nConclusions: Progression-free survival was longer with nivolumab plus ipilimumab than with chemotherapy among patients who had not previously received systemic treatment for MSI-H or dMMR metastatic colorectal cancer. (Funded by Bristol Myers Squibb and Ono Pharmaceutical; CheckMate 8HW ClinicalTrials.gov number, NCT04008030.).\n\nIndexed on Europe PMC as PubMed record 39602630 (DOI 10.1056/nejmoa2402141). Its abstract cites the registry id NCT04008030, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2402141", pmid: "39602630", authors: "Andre T, Elez E, Van Cutsem E, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04008030 with the most citations, so it is the natural first reading for anyone following the CheckMate 8HW trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2402141"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39602630/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39602630"},{"label":"ClinicalTrials.gov NCT04008030","url":"https://clinicaltrials.gov/study/NCT04008030"}], tags: ["europepmc-ingest"], trials: ["checkmate-8hw"], journals: ["nejm"] }),
  p({ id: "paper-deep-c-n-engl-j-med-2014", name: "Multitarget stool DNA testing for colorectal-cancer screening", tldr: "Published report from the DeeP-C trial registered as NCT01397747, in New England Journal of Medicine (2014), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: An accurate, noninvasive test could improve the effectiveness of colorectal-cancer screening.\n\nMethods: We compared a noninvasive, multitarget stool DNA test with a fecal immunochemical test (FIT) in persons at average risk for colorectal cancer. The DNA test includes quantitative molecular assays for KRAS mutations, aberrant NDRG4 and BMP3 methylation, and β-actin, plus a hemoglobin immunoassay. Results were generated with the use of a logistic-regression algorithm, with values of 183 or more considered to be positive. FIT values of more than 100 ng of hemoglobin per milliliter of buffer were considered to be positive. Tests were processed independently of colonoscopic findings.\n\nResults: Of the 9989 participants who could be evaluated, 65 (0.7%) had colorectal cancer and 757 (7.6%) had advanced precancerous lesions (advanced adenomas or sessile serrated polyps measuring ≥1 cm in the greatest dimension) on colonoscopy. The sensitivity for detecting colorectal cancer was 92.3% with DNA testing and 73.8% with FIT (P=0.002). The sensitivity for detecting advanced precancerous lesions was 42.4% with DNA testing and 23.8% with FIT (P<0.001). The rate of detection of polyps with high-grade dysplasia was 69.2% with DNA testing and 46.2% with FIT (P=0.004); the rates of detection of serrated sessile polyps measuring 1 cm or more were 42.4% and 5.1%, respectively (P<0.001). Specificities with DNA testing and FIT were 86.6% and 94.9%, respectively, among participants with nonadvanced or negative findings (P<0.001) and 89.8% and 96.4%, respectively, among those with negative results on colonoscopy (P<0.001). The numbers of persons who would need to be screened to detect one cancer were 154 with colonoscopy, 166 with DNA testing, and 208 with FIT.\n\nConclusions: In asymptomatic persons at average risk for colorectal cancer, multitarget stool DNA testing detected significantly more cancers than did FIT but had more false positive results. (Funded by Exact Sciences; ClinicalTrials.gov number, NCT01397747.).\n\nIndexed on Europe PMC as PubMed record 24645800 (DOI 10.1056/nejmoa1311194). Its abstract cites the registry id NCT01397747, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2014, doi: "10.1056/nejmoa1311194", pmid: "24645800", authors: "Imperiale TF, Ransohoff DF, Itzkowitz SH, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01397747 with the most citations, so it is the natural first reading for anyone following the DeeP-C trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2014","url":"https://doi.org/10.1056/nejmoa1311194"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/24645800/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/24645800"},{"label":"ClinicalTrials.gov NCT01397747","url":"https://clinicaltrials.gov/study/NCT01397747"}], tags: ["europepmc-ingest"], trials: ["deep-c"], journals: ["nejm"] }),
  p({ id: "paper-destiny-crc02-lancet-oncol-2024", name: "Trastuzumab deruxtecan in patients with HER2-positive advanced colorectal cancer (DESTINY-CRC02): primary results from a multicentre, randomised, phase 2 trial", tldr: "Published report from the DESTINY-CRC02 trial registered as NCT04744831, in The Lancet Oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Trastuzumab deruxtecan has shown encouraging activity in patients with treatment-refractory HER2-positive, RAS wild-type and BRAF wild-type metastatic colorectal cancer. Dose optimisation and further antitumour assessments in patients with RAS mutations and those with previous anti-HER2 therapy are warranted. We aimed to evaluate two doses of trastuzumab deruxtecan (5·4 mg/kg and 6·4 mg/kg) to establish the recommended dose in patients with pretreated HER2-positive, RAS wild-type or mutant metastatic colorectal cancer.\n\nMethods: DESTINY-CRC02 was a multicentre, randomised, two-stage, two-arm, phase 2 study done in 53 research hospitals and medical centres in Australia, Belgium, France, Italy, Japan, South Korea, Spain, Taiwan, the UK, and the USA. Eligible patients were aged 18 years and older or 20 years and older (depending on region) with pretreated pathologically documented, unresectable, recurrent, or metastatic HER2-positive, and RAS wild-type or mutant colorectal cancer. Patients were required to have an Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1 and have received previous chemotherapy, and anti-EGFR, anti-VEGF, or anti-PD-L1 therapy, if clinically indicated. In stage 1, patients were randomly assigned (1:1), via a secure interactive response technology system, to receive 5·4 mg/kg or 6·4 mg/kg trastuzumab deruxtecan administered intravenously every 21 days. Stratification factors were ECOG performance status, HER2 status, and RAS status. In stage 2, patients were assigned into the 5·4 mg/kg treatment group only. The primary endpoint was confirmed objective response rate by blinded independent central review, assessed in all patients for whom treatment was assigned (full analysis set). Safety was assessed in all patients who received at least one dose of study drug. This trial is registered with ClinicalTrials.gov, NCT04744831, and is ongoing (not recruiting).\n\nFindings: Between March 5, 2021, and March 29, 2022, 135 patients were centrally screened, 122 of whom were enrolled. In stage 1, 40 patients each were randomly assigned to receive trastuzumab deruxtecan 5·4 mg/kg and 6·4 mg/kg. In stage 2, an additional 42 patients were enrolled in the 5·4 mg/kg group. 64 (52%) participants were male and 58 (48%) were female. The median duration of follow-up was 8·9 months (IQR 6·7-10·5) in the 5·4 mg/kg group and 10·3 months (5·9-12·7) in the 6·4 mg/kg group. The confirmed objective response rate by blinded independent central review was 37·8% (31/82 [95% CI 27·3-49·2]) in the 5·4 mg/kg group and 27·5% (11/40 [14·6-43·9]) in the 6·4 mg/kg group. 34 (41%) of 83 patients in the 5·4 mg/kg group and 19 (49%) of 39 in the 6·4 mg/kg group had grade 3 or worse drug-related treatment-emergent adverse events. The most common grade 3 or worse drug-related treatment-emergent adverse events were neutrophil count decreased (13 [16%] of 83 patients), anaemia (six [7%]), nausea (six [7%]), and white blood cell count decreased (five [6%]) in the 5·4 mg/kg group; and were neutrophil count decreased (10 [26%] of 39 patients), anaemia (eight [21%]), platelet count decreased (four [10%]), and white blood cell count decreased (four [10%]) in the 6·4 mg/kg group. Drug-related serious adverse events occurred in 11 (13%) of 83 patients in the 5·4 mg/kg group and six (15%) of 39 patients in the 6·4 mg/kg group; the most common in the 5·4 mg/kg group was nausea (three [4%] patients) and the most common in the 6·4 mg/kg group were fatigue (two [5%] patients), neutropenia (two [5%]), and thrombocytopenia (two [5%]). A drug-related treatment-emergent adverse event related to death occurred in one (1%) patient in the 5·4 mg/kg group (due to hepatic failure). Adjudicated drug-related interstitial lung disease or pneumonitis events were observed in seven (8%) patients in the 5·4 mg/kg group (all grade 1 or 2) and in five (13%) patients in the 6·4 mg/kg group (four grade 1 or 2; one grade 5).\n\nInterpretation: The promising antitumour activity and favourable safety profile support trastuzumab deruxtecan 5·4 mg/kg as the optimal single-agent dose for patients with pretreated HER2-positive metastatic colorectal cancer, including those with RAS mutations, previous anti-HER2 therapy, or both.\n\nFunding: Daiichi Sankyo and AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 39116902 (DOI 10.1016/s1470-2045(24)00380-2). Its abstract cites the registry id NCT04744831, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2024, doi: "10.1016/s1470-2045(24)00380-2", pmid: "39116902", authors: "Raghav K, Siena S, Takashima A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04744831 with the most citations, so it is the natural first reading for anyone following the DESTINY-CRC02 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2024","url":"https://doi.org/10.1016/s1470-2045(24)00380-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39116902/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39116902"},{"label":"ClinicalTrials.gov NCT04744831","url":"https://clinicaltrials.gov/study/NCT04744831"}], tags: ["europepmc-ingest"], trials: ["destiny-crc02"], journals: ["lancet-oncology"] }),
  p({ id: "paper-dynamic-nat-med-2025-update", name: "Circulating tumor DNA analysis guiding adjuvant therapy in stage II colon cancer: 5-year outcomes of the randomized DYNAMIC trial", tldr: "Later report from the DYNAMIC trial registered as ACTRN12615000381583, in Nature Medicine (2025); its title describes an updated or longer-term analysis.", summary: "Early data from the DYNAMIC study of circulating tumor DNA (ctDNA)-guided adjuvant chemotherapy (ACT) versus standard approach met its primary outcome demonstrating reduced ACT use without compromising 2-year recurrence-free survival (RFS) for stage II colon cancer. We report here other prespecified analyses of overall survival, ctDNA clearance and ctDNA level. At a median follow-up of 59.7 months, 5-year RFS was 88% and 87% with ctDNA-guided and standard management, respectively (difference 1.1%, 95% confidence interval -5.8% to 8.0%), and 5-year overall survival is similar (93.8% versus 93.3%, hazard ratio (HR) 1.05; P = 0.887). For treated ctDNA-positive patients, ctDNA clearance was observed at the end of ACT (EOT) in 35 out of 40 patients (87.5%). A higher than median postoperative tumor-derived mutant molecules per milliliter plasma was associated with worse 5-year RFS (HR 10.62; P = 0.005). For treated ctDNA-positive patients, post hoc analysis of ctDNA clearance at EOT assessed by a new assay that evaluated an average of 29 tumor-derived mutations per patient predicted for a favorable 5-year recurrence-free probability of 97% versus 0% for ctDNA persistence (P < 0.001). Mature DYNAMIC outcome data support a ctDNA-guided approach to ACT for stage II colon cancer, with potential to further risk stratify ctDNA-positive patients based on ctDNA burden and EOT results. Australian New Zealand Clinical Trials Registry Identifier: ACTRN12615000381583.\n\nIndexed on Europe PMC as PubMed record 40055522 (DOI 10.1038/s41591-025-03579-w). Its abstract cites the registry id ACTRN12615000381583, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-03579-w", pmid: "40055522", authors: "Tie J, Wang Y, Lo SN, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the DYNAMIC trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-03579-w"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40055522/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40055522"},{"label":"ClinicalTrials.gov ACTRN12615000381583","url":"https://clinicaltrials.gov/study/ACTRN12615000381583"}], tags: ["europepmc-ingest"], trials: ["dynamic"], journals: ["nature-medicine"] }),
  p({ id: "paper-eclipse-shield-n-engl-j-med-2024", name: "A Cell-free DNA Blood-Based Test for Colorectal Cancer Screening", tldr: "Published report from the ECLIPSE trial registered as NCT04136002, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Colorectal cancer is the third most diagnosed cancer in adults in the United States. Early detection could prevent more than 90% of colorectal cancer-related deaths, yet more than one third of the screening-eligible population is not up to date with screening despite multiple available tests. A blood-based test has the potential to improve screening adherence, detect colorectal cancer earlier, and reduce colorectal cancer-related mortality.\n\nMethods: We assessed the performance characteristics of a cell-free DNA (cfDNA) blood-based test in a population eligible for colorectal cancer screening. The coprimary outcomes were sensitivity for colorectal cancer and specificity for advanced neoplasia (colorectal cancer or advanced precancerous lesions) relative to screening colonoscopy. The secondary outcome was sensitivity to detect advanced precancerous lesions.\n\nResults: The clinical validation cohort included 10,258 persons, 7861 of whom met eligibility criteria and were evaluable. A total of 83.1% of the participants with colorectal cancer detected by colonoscopy had a positive cfDNA test and 16.9% had a negative test, which indicates a sensitivity of the cfDNA test for detection of colorectal cancer of 83.1% (95% confidence interval [CI], 72.2 to 90.3). Sensitivity for stage I, II, or III colorectal cancer was 87.5% (95% CI, 75.3 to 94.1), and sensitivity for advanced precancerous lesions was 13.2% (95% CI, 11.3 to 15.3). A total of 89.6% of the participants without any advanced colorectal neoplasia (colorectal cancer or advanced precancerous lesions) identified on colonoscopy had a negative cfDNA blood-based test, whereas 10.4% had a positive cfDNA blood-based test, which indicates a specificity for any advanced neoplasia of 89.6% (95% CI, 88.8 to 90.3). Specificity for negative colonoscopy (no colorectal cancer, advanced precancerous lesions, or nonadvanced precancerous lesions) was 89.9% (95% CI, 89.0 to 90.7).\n\nConclusions: In an average-risk screening population, this cfDNA blood-based test had 83% sensitivity for colorectal cancer, 90% specificity for advanced neoplasia, and 13% sensitivity for advanced precancerous lesions. (Funded by Guardant Health; ECLIPSE ClinicalTrials.gov number, NCT04136002.).\n\nIndexed on Europe PMC as PubMed record 38477985 (DOI 10.1056/nejmoa2304714). Its abstract cites the registry id NCT04136002, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2304714", pmid: "38477985", authors: "Chung DC, Gray DM, Singh H, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04136002 with the most citations, so it is the natural first reading for anyone following the ECLIPSE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2304714"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38477985/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38477985"},{"label":"ClinicalTrials.gov NCT04136002","url":"https://clinicaltrials.gov/study/NCT04136002"}], tags: ["europepmc-ingest"], trials: ["eclipse-shield"], journals: ["nejm"] }),
  p({ id: "paper-fresco-2-lancet-2023", name: "Fruquintinib versus placebo in patients with refractory metastatic colorectal cancer (FRESCO-2): an international, multicentre, randomised, double-blind, phase 3 study", tldr: "Published report from the FRESCO-2 trial registered as NCT04322539, in The Lancet (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: There is a paucity of effective systemic therapy options for patients with advanced, chemotherapy-refractory colorectal cancer. We aimed to evaluate the efficacy and safety of fruquintinib, a highly selective and potent oral inhibitor of vascular endothelial growth factor receptors (VEGFRs) 1, 2, and 3, in patients with heavily pretreated metastatic colorectal cancer.\n\nMethods: We conducted an international, randomised, double-blind, placebo-controlled, phase 3 study (FRESCO-2) at 124 hospitals and cancer centres across 14 countries. We included patients aged 18 years or older (≥20 years in Japan) with histologically or cytologically documented metastatic colorectal adenocarcinoma who had received all current standard approved cytotoxic and targeted therapies and progressed on or were intolerant to trifluridine-tipiracil or regorafenib, or both. Eligible patients were randomly assigned (2:1) to receive fruquintinib (5 mg capsule) or matched placebo orally once daily on days 1-21 in 28-day cycles, plus best supportive care. Stratification factors were previous trifluridine-tipiracil or regorafenib, or both, RAS mutation status, and duration of metastatic disease. Patients, investigators, study site personnel, and sponsors, except for selected sponsor pharmacovigilance personnel, were masked to study group assignments. The primary endpoint was overall survival, defined as the time from randomisation to death from any cause. A non-binding futility analysis was done when approximately one-third of the expected overall survival events had occurred. Final analysis occurred after 480 overall survival events. This study is registered with ClinicalTrials.gov, NCT04322539, and EudraCT, 2020-000158-88, and is ongoing but not recruiting.\n\nFindings: Between Aug 12, 2020, and Dec 2, 2021, 934 patients were assessed for eligibility and 691 were enrolled and randomly assigned to receive fruquintinib (n=461) or placebo (n=230). Patients had received a median of 4 lines (IQR 3-6) of previous systemic therapy for metastatic disease, and 502 (73%) of 691 patients had received more than 3 lines. Median overall survival was 7·4 months (95% CI 6·7-8·2) in the fruquintinib group versus 4·8 months (4·0-5·8) in the placebo group (hazard ratio 0·66, 95% CI 0·55-0·80; p<0·0001). Grade 3 or worse adverse events occurred in 286 (63%) of 456 patients who received fruquintinib and 116 (50%) of 230 who received placebo; the most common grade 3 or worse adverse events in the fruquintinib group included hypertension (n=62 [14%]), asthenia (n=35 [8%]), and hand-foot syndrome (n=29 [6%]). There was one treatment-related death in each group (intestinal perforation in the fruquintinib group and cardiac arrest in the placebo group).\n\nInterpretation: Fruquintinib treatment resulted in a significant and clinically meaningful benefit in overall survival compared with placebo in patients with refractory metastatic colorectal cancer. These data support the use of fruquintinib as a global treatment option for patients with refractory metastatic colorectal cancer. Ongoing analysis of the quality of life data will further establish the clinical benefit of fruquintinib in this patient population.\n\nFunding: HUTCHMED.\n\nIndexed on Europe PMC as PubMed record 37331369 (DOI 10.1016/s0140-6736(23)00772-9). Its abstract cites the registry id NCT04322539, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2023, doi: "10.1016/s0140-6736(23)00772-9", pmid: "37331369", authors: "Dasari A, Lonardi S, Garcia-Carbonero R, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04322539 with the most citations, so it is the natural first reading for anyone following the FRESCO-2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2023","url":"https://doi.org/10.1016/s0140-6736(23)00772-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37331369/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37331369"},{"label":"ClinicalTrials.gov NCT04322539","url":"https://clinicaltrials.gov/study/NCT04322539"}], tags: ["europepmc-ingest"], trials: ["fresco-2"], journals: ["lancet"] }),
  p({ id: "paper-keynote-177-lancet-oncol-2022-update", name: "Pembrolizumab versus chemotherapy for microsatellite instability-high or mismatch repair-deficient metastatic colorectal cancer (KEYNOTE-177): final analysis of a randomised, open-label, phase 3 study", tldr: "Later report from the KEYNOTE-177 trial registered as NCT02563002, in The Lancet Oncology (2022); its title describes an updated or longer-term analysis.", summary: "Background: Pembrolizumab has shown improved progression-free survival versus chemotherapy in patients with newly diagnosed microsatellite instability-high or mismatch repair-deficient metastatic colorectal cancer. However, the treatment's effect on overall survival in this cohort of patients was unknown. Here, we present the final overall survival analysis of the KEYNOTE-177 study.\n\nMethods: This randomised, open-label, phase 3 study was done in 193 academic medical centres and hospitals in 23 countries. We recruited patients aged at least 18 years, with an Eastern Cooperative Oncology Group performance status of 0 or 1, and who had previously untreated microsatellite instability-high or mismatch repair-deficient metastatic colorectal cancer. Patients were randomly assigned (1:1) in blocks of four using an interactive voice response system or integrated web response system to intravenous pembrolizumab 200 mg every 3 weeks or to the investigator's choice of intravenous mFOLFOX6 (oxaliplatin 85 mg/m 2 on day 1, leucovorin 400 mg/m 2 on day 1, and fluorouracil 400 mg/m 2 bolus on day 1 followed by a continuous infusion of 1200 mg/m 2 per day for 2 days on days 1-2) or intravenous FOLFIRI (irinotecan 180 mg/m 2 on day 1, leucovorin 400 mg/m 2 on day 1, and fluorouracil 400 mg/m 2 bolus on day 1 followed by a continuous infusion of 1200 mg/m 2 per day for 2 days on days 1-2), every 2 weeks with or without intravenous bevacizumab 5 mg/kg every 2 weeks or intravenous weekly cetuximab (first dose 400 mg/m 2, then 250 mg/m 2 for every subsequent dose). Patients receiving chemotherapy could cross over to pembrolizumab for up to 35 treatment cycles after progression. The co-primary endpoints were overall survival and progression-free survival in the intention-to-treat population. KEYNOTE-177 is registered at ClinicalTrials.gov, NCT02563002, and is no longer enrolling patients.\n\nFindings: Between Feb 11, 2016, and Feb 19, 2018, 852 patients were screened, of whom 307 (36%) were randomly assigned to pembrolizumab (n=153) or chemotherapy (n=154). 93 (60%) patients crossed over from chemotherapy to anti-PD-1 or anti-PD-L1 therapy (56 patients to on-study pembrolizumab and 37 patients to off-study therapy). At final analysis (median follow-up of 44·5 months [IQR 39·7-49·8]), median overall survival was not reached (NR; 95% CI 49·2-NR) with pembrolizumab vs 36·7 months (27·6-NR) with chemotherapy (hazard ratio [HR] 0·74; 95% CI 0·53-1·03; p=0·036). Superiority of pembrolizumab versus chemotherapy for overall survival was not demonstrated because the prespecified α of 0·025 needed for statistical significance was not achieved. At this updated analysis, median progression-free survival was 16·5 months (95% CI 5·4-38·1) with pembrolizumab versus 8·2 months (6·1-10·2) with chemotherapy (HR 0·59, 95% CI 0·45-0·79). Treatment-related adverse events of grade 3 or worse occurred in 33 (22%) of 153 patients in the pembrolizumab group versus 95 (66%) of 143 patients in the chemotherapy group. Common adverse events of grade 3 or worse that were attributed to pembrolizumab were increased alanine aminotransferase, colitis, diarrhoea, and fatigue in three (2%) patients each, and those attributed to chemotherapy were decreased neutrophil count (in 24 [17%] patients), neutropenia (22 [15%]), diarrhoea (14 [10%]), and fatigue (13 [9%]). Serious adverse events attributed to study treatment occurred in 25 (16%) patients in the pembrolizumab group and in 41 (29%) patients in the chemotherapy group. No deaths attributed to pembrolizumab occurred; one death due to intestinal perforation was attributed to chemotherapy.\n\nInterpretation: In this updated analysis, although pembrolizumab continued to show durable antitumour activity and fewer treatment-related adverse events compared with chemotherapy, there was no significant difference in overall survival between the two treatment groups. These findings support pembrolizumab as an efficacious first-line therapy in patients with microsatellite instability-high or mismatch repair-deficient metastatic colorectal cancer.\n\nFunding: MSD.\n\nIndexed on Europe PMC as PubMed record 35427471 (DOI 10.1016/s1470-2045(22)00197-8). Its abstract cites the registry id NCT02563002, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2022, doi: "10.1016/s1470-2045(22)00197-8", pmid: "35427471", authors: "Diaz LA, Shiu KK, Kim TW, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-177 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2022","url":"https://doi.org/10.1016/s1470-2045(22)00197-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35427471/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35427471"},{"label":"ClinicalTrials.gov NCT02563002","url":"https://clinicaltrials.gov/study/NCT02563002"}], tags: ["europepmc-ingest"], trials: ["keynote-177"], journals: ["lancet-oncology"] }),
  p({ id: "paper-niche-2-nat-med-2020", name: "Neoadjuvant immunotherapy leads to pathological responses in MMR-proficient and MMR-deficient early-stage colon cancers", tldr: "Published report from the NICHE-2 trial registered as NCT03026140, in Nature Medicine (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "PD-1 plus CTLA-4 blockade is highly effective in advanced-stage, mismatch repair (MMR)-deficient (dMMR) colorectal cancers, yet not in MMR-proficient (pMMR) tumors. We postulated a higher efficacy of neoadjuvant immunotherapy in early-stage colon cancers. In the exploratory NICHE study (ClinicalTrials.gov: NCT03026140), patients with dMMR or pMMR tumors received a single dose of ipilimumab and two doses of nivolumab before surgery, the pMMR group with or without celecoxib. The primary objective was safety and feasibility; 40 patients with 21 dMMR and 20 pMMR tumors were treated, and 3 patients received nivolumab monotherapy in the safety run-in. Treatment was well tolerated and all patients underwent radical resections without delays, meeting the primary endpoint. Of the patients who received ipilimumab + nivolumab (20 dMMR and 15 pMMR tumors), 35 were evaluable for efficacy and translational endpoints. Pathological response was observed in 20/20 (100%; 95% exact confidence interval (CI): 86-100%) dMMR tumors, with 19 major pathological responses (MPRs, ≤10% residual viable tumor) and 12 pathological complete responses. In pMMR tumors, 4/15 (27%; 95% exact CI: 8-55%) showed pathological responses, with 3 MPRs and 1 partial response. CD8 + PD-1 + T cell infiltration was predictive of response in pMMR tumors. These data indicate that neoadjuvant immunotherapy may have the potential to become the standard of care for a defined group of colon cancer patients when validated in larger studies with at least 3 years of disease-free survival data.\n\nIndexed on Europe PMC as PubMed record 32251400 (DOI 10.1038/s41591-020-0805-8). Its abstract cites the registry id NCT03026140, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2020, doi: "10.1038/s41591-020-0805-8", pmid: "32251400", authors: "Chalabi M, Fanchi LF, Dijkstra KK, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03026140 with the most citations, so it is the natural first reading for anyone following the NICHE-2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2020","url":"https://doi.org/10.1038/s41591-020-0805-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32251400/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32251400"},{"label":"ClinicalTrials.gov NCT03026140","url":"https://clinicaltrials.gov/study/NCT03026140"}], tags: ["europepmc-ingest"], trials: ["niche-2"], journals: ["nature-medicine"] }),
  p({ id: "paper-nordicc-lancet-2026-update", name: "Long-term effects of colonoscopy screening on colorectal cancer incidence and mortality: a multicountry, population-based randomised controlled trial", tldr: "Later report from the NordICC trial registered as NCT00883792, in The Lancet (2026); its title describes an updated or longer-term analysis.", summary: "Background: We previously reported the 10-year effects of colonoscopy screening on colorectal cancer incidence and mortality. Here, we report the effects after 13 years of follow-up.\n\nMethods: In this multicountry, population-based randomised controlled trial, 84 583 men and women aged 55-64 years at enrolment from Norway, Poland, and Sweden were randomly allocated (1:2) to colonoscopy screening or no screening and analysed. The primary outcomes were colorectal cancer incidence and mortality after 10-15 years of follow-up in intention-to-screen analyses, with first analysis after 10 years, and repeated every other year or at longer intervals. This trial is registered with ClinicalTrials.gov, NCT00883792, and is ongoing.\n\nFindings: At 13 years of follow-up, colorectal cancer incidence was 375 colorectal cancers (1·46%) of 28 217 individuals in the screening group and 912 colorectal cancers (1·80%) of 56 366 individuals in the no-screening group. The risk ratio (RR) was 0·81 (95% CI 0·71-0·90) in intention-to-screen analyses and 0·55 (0·33-0·81) in per-protocol analyses. The risk for proximal colorectal cancer was 129 (0·51%) in the screening group versus 283 (0·56%) in the no-screening group (RR 0·91 [0·71-1·09]), and the risk for distal colorectal cancer was 224 (0·87%) in the screening group versus 563 (1·11%) in the no-screening group (RR 0·79 [0·65-0·89]; interaction p<0·0001). In men, the colorectal cancer risk was 214 (1·69%) of 14 154 in the screening group and 541 (2·19%) of 28 247 in the no-screening group (RR 0·77 [0·64 to -0·88]); in women, the risk was 161 (1·24%) of 14 063 in the screening group versus 371 (1·43%) of 28 119 in the no-screening group (RR 0·87 [0·70 to 1·02]; interaction p<0·0001). Colorectal cancer mortality was 106 (0·41%) of 28 217 in the screening group and 236 (0·47%) of 56 366 in the no-screening group (intention-to-screen RR 0·88 [0·68-1·08], per-protocol RR 0·70 [0·26-1·25]). The observed colorectal cancer mortality in the non-screening group (0·47%) was substantially lower than expected at the time of designing the trial (0·82%).\n\nInterpretation: One colonoscopy significantly reduced colorectal cancer incidence but not mortality over 13 years. Colorectal cancer mortality was lower in both study groups than when the trial was designed.\n\nFunding: The Norwegian Research Council, the Nordic Cancer Union, the Norwegian Cancer Society, and the Health Fund of South-East Norway.\n\nIndexed on Europe PMC as PubMed record 42102826 (DOI 10.1016/s0140-6736(26)00508-8). Its abstract cites the registry id NCT00883792, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2026, doi: "10.1016/s0140-6736(26)00508-8", pmid: "42102826", authors: "Kaminski MF, Kalager M, Løberg M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the NordICC trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet 2026","url":"https://doi.org/10.1016/s0140-6736(26)00508-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42102826/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42102826"},{"label":"ClinicalTrials.gov NCT00883792","url":"https://clinicaltrials.gov/study/NCT00883792"}], tags: ["europepmc-ingest"], trials: ["nordicc"], journals: ["lancet"] }),
  p({ id: "paper-opra-j-clin-oncol-2024", name: "Long-Term Results of Organ Preservation in Patients With Rectal Adenocarcinoma Treated With Total Neoadjuvant Therapy: The Randomized Phase II OPRA Trial", tldr: "Published report from the OPRA trial registered as NCT02008656, in Journal of Clinical Oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Clinical trials frequently include multiple end points that mature at different times. The initial report, typically based on the primary end point, may be published when key planned co-primary or secondary analyses are not yet available. Clinical Trial Updates provide an opportunity to disseminate additional results from studies, published in JCO or elsewhere, for which the primary end point has already been reported. To assess long-term risk of local tumor regrowth, we report updated organ preservation rate and oncologic outcomes of the OPRA trial (ClinicalTrials.gov identifier: NCT02008656). Patients with stage II/III rectal cancer were randomly assigned to receive induction chemotherapy followed by chemoradiation (INCT-CRT) or chemoradiation followed by consolidation chemotherapy (CRT-CNCT). Patients who achieved a complete or near-complete response after finishing treatment were offered watch-and-wait (WW). Total mesorectal excision (TME) was recommended for those who achieved an incomplete response. The primary end point was disease-free survival (DFS). The secondary end point was TME-free survival. In total, 324 patients were randomly assigned (INCT-CRT, n = 158; CRT-CNCT, n = 166). Median follow-up was 5.1 years. The 5-year DFS rates were 71% (95% CI, 64 to 79) and 69% (95% CI, 62 to 77) for INCT-CRT and CRT-CNCT, respectively ( P =.68). TME-free survival was 39% (95% CI, 32 to 48) in the INCT-CRT group and 54% (95% CI, 46 to 62) in the CRT-CNCT group ( P =.012). Of 81 patients with regrowth, 94% occurred within 2 years and 99% occurred within 3 years. DFS was similar for patients who underwent TME after restaging (64% [95% CI, 53 to 78]) and patients in WW who underwent TME after regrowth (64% [95% CI, 53 to 78]; P =.94). Updated analysis continues to show long-term organ preservation in half of the patients with rectal cancer treated with total neoadjuvant therapy. In patients who enter WW, most cases of tumor regrowth occur in the first 2 years.\n\nIndexed on Europe PMC as PubMed record 37883738 (DOI 10.1200/jco.23.01208). Its abstract cites the registry id NCT02008656, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2024, doi: "10.1200/jco.23.01208", pmid: "37883738", authors: "Verheij FS, Omer DM, Williams H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02008656 with the most citations, so it is the natural first reading for anyone following the OPRA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2024","url":"https://doi.org/10.1200/jco.23.01208"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37883738/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37883738"},{"label":"ClinicalTrials.gov NCT02008656","url":"https://clinicaltrials.gov/study/NCT02008656"}], tags: ["europepmc-ingest"], trials: ["opra"], journals: ["jco"] }),
  p({ id: "paper-paradigm-jama-2023", name: "Panitumumab vs Bevacizumab Added to Standard First-line Chemotherapy and Overall Survival Among Patients With RAS Wild-type, Left-Sided Metastatic Colorectal Cancer: A Randomized Clinical Trial", tldr: "Published report from the PARADIGM trial registered as NCT02394795, in JAMA (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: For patients with RAS wild-type metastatic colorectal cancer, adding anti-epidermal growth factor receptor (anti-EGFR) or anti-vascular endothelial growth factor (anti-VEGF) monoclonal antibodies to first-line doublet chemotherapy is routine, but the optimal targeted therapy has not been defined.\n\nObjective: To evaluate the effect of adding panitumumab (an anti-EGFR monoclonal antibody) vs bevacizumab (an anti-VEGF monoclonal antibody) to standard first-line chemotherapy for treatment of RAS wild-type, left-sided, metastatic colorectal cancer.\n\nDesign, setting, and participants: Randomized, open-label, phase 3 clinical trial at 197 sites in Japan in May 2015-January 2022 among 823 patients with chemotherapy-naive RAS wild-type, unresectable metastatic colorectal cancer (final follow-up, January 14, 2022).\n\nInterventions: Panitumumab (n = 411) or bevacizumab (n = 412) plus modified fluorouracil, l-leucovorin, and oxaliplatin (mFOLFOX6) every 14 days.\n\nMain outcomes and measures: The primary end point, overall survival, was tested first in participants with left-sided tumors, then in the overall population. Secondary end points were progression-free survival, response rate, duration of response, and curative (defined as R0 status) resection rate.\n\nResults: In the as-treated population (n = 802; median age, 66 years; 282 [35.2%] women), 604 (75.3%) had left-sided tumors. Median follow-up was 61 months. Median overall survival was 37.9 months with panitumumab vs 34.3 months with bevacizumab in participants with left-sided tumors (hazard ratio [HR] for death, 0.82; 95.798% CI, 0.68-0.99; P =.03) and 36.2 vs 31.3 months, respectively, in the overall population (HR, 0.84; 95% CI, 0.72-0.98; P =.03). Median progression-free survival for panitumumab vs bevacizumab was 13.1 vs 11.9 months, respectively, for those with left-sided tumors (HR, 1.00; 95% CI, 0.83-1.20) and 12.2 vs 11.4 months overall (HR, 1.05; 95% CI, 0.90-1.24). Response rates with panitumumab vs bevacizumab were 80.2% vs 68.6%, respectively, for left-sided tumors (difference, 11.2%; 95% CI, 4.4%-17.9%) and 74.9% vs 67.3% overall (difference, 7.7%; 95% CI, 1.5%-13.8%). Median duration of response with panitumumab vs bevacizumab was 13.1 vs 11.2 months for left-sided tumors (HR, 0.86; 95% CI, 0.70-1.10) and 11.9 vs 10.7 months overall (HR, 0.89; 95% CI, 0.74-1.06). Curative resection rates with panitumumab vs bevacizumab were 18.3% vs 11.6% for left-sided tumors; (difference, 6.6%; 95% CI, 1.0%-12.3%) and 16.5% vs 10.9% overall (difference, 5.6%; 95% CI, 1.0%-10.3%). Common treatment-emergent adverse events were acneiform rash (panitumumab: 74.8%; bevacizumab: 3.2%), peripheral sensory neuropathy (panitumumab: 70.8%; bevacizumab: 73.7%), and stomatitis (panitumumab: 61.6%; bevacizumab: 40.5%).\n\nConclusions and relevance: Among patients with RAS wild-type metastatic colorectal cancer, adding panitumumab, compared with bevacizumab, to standard first-line chemotherapy significantly improved overall survival in those with left-sided tumors and in the overall population.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02394795.\n\nIndexed on Europe PMC as PubMed record 37071094 (DOI 10.1001/jama.2023.4428). Its abstract cites the registry id NCT02394795, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2023, doi: "10.1001/jama.2023.4428", pmid: "37071094", authors: "Watanabe J, Muro K, Shitara K, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02394795 with the most citations, so it is the natural first reading for anyone following the PARADIGM trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2023","url":"https://doi.org/10.1001/jama.2023.4428"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37071094/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37071094"},{"label":"ClinicalTrials.gov NCT02394795","url":"https://clinicaltrials.gov/study/NCT02394795"}], tags: ["europepmc-ingest"], trials: ["paradigm"], journals: ["jama"] }),
  p({ id: "paper-mountaineer-nat-commun-2026-update", name: "Tucatinib plus trastuzumab for chemotherapy-refractory, HER2 +, RAS wild-type metastatic colorectal cancer (MOUNTAINEER): final analysis", tldr: "Later report from the MOUNTAINEER trial registered as NCT03043313, in Nature Communications (2026); its title describes an updated or longer-term analysis.", summary: "MOUNTAINEER was a multicenter, open-label, phase 2 trial (NCT03043313) that evaluated the efficacy and safety of tucatinib plus trastuzumab, a dual HER2-targeted chemotherapy-free regimen. Patients were included if they had chemotherapy-refractory, HER2+, RAS wild-type unresectable or metastatic colorectal cancer. This final analysis reports updated efficacy and safety after a median follow-up of 32.4 months. Of the 84 patients who received tucatinib plus trastuzumab, the confirmed objective response rate was 39.3%; median duration of response was 15.2 months. Median progression-free survival was 8.1 months and overall survival was 23.9 months. Efficacy was relatively similar across central HER2+ testing methods. No clear association of treatment response with co-occurring biomarker alterations was seen. Few patients discontinued treatment due to adverse events; no treatment-emergent deaths occurred. Tucatinib plus trastuzumab showed clinically meaningful efficacy and favorable safety. Efficacy was observed irrespective of central HER2+ testing methods and in patients with heterogeneous tumor biomarker profiles.\n\nIndexed on Europe PMC as PubMed record 41526345 (DOI 10.1038/s41467-025-67824-z). Its abstract cites the registry id NCT03043313, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Communications", year: 2026, doi: "10.1038/s41467-025-67824-z", pmid: "41526345", authors: "Strickler JH, Cercek A, Siena S, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the MOUNTAINEER trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Nat Commun 2026","url":"https://doi.org/10.1038/s41467-025-67824-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41526345/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41526345"},{"label":"ClinicalTrials.gov NCT03043313","url":"https://clinicaltrials.gov/study/NCT03043313"}], tags: ["europepmc-ingest"], trials: ["mountaineer"], journals: ["nature-communications"] }),
  p({ id: "paper-mypathway-lancet-oncol-2019", name: "Pertuzumab plus trastuzumab for HER2-amplified metastatic colorectal cancer (MyPathway): an updated report from a multicentre, open-label, phase 2a, multiple basket study", tldr: "Published report from the MyPathway trial registered as NCT02091141, in The Lancet Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Therapies targeting HER2 have improved clinical outcomes in HER2-positive breast and gastric cancers, and are emerging as potential treatments for HER2-positive metastatic colorectal cancer. MyPathway evaluates the activity of targeted therapies in non-indicated tumour types with potentially predictive molecular alterations. We aimed to assess the activity of pertuzumab and trastuzumab in patients with HER2-amplified metastatic colorectal cancer.\n\nMethods: MyPathway is an ongoing, phase 2a, multiple basket study. Patients in this subset analysis were aged 18 years or older and had treatment-refractory, histologically confirmed HER2-amplified metastatic colorectal cancer with measurable or evaluable disease and an Eastern Cooperative Oncology Group performance status score of 2 or less, enrolled from 25 hospitals or clinics in 16 states of the USA. Patients received pertuzumab (840 mg loading dose, then 420 mg every 3 weeks, intravenously) and trastuzumab (8 mg/kg loading dose, then 6 mg/kg every 3 weeks, intravenously). The primary endpoint was the proportion of patients who achieved an objective response based on investigator-reported tumour responses. Analyses were done per protocol. This ongoing trial is registered with ClinicalTrials.gov, number NCT02091141.\n\nFindings: Between Oct 20, 2014, and June 22, 2017, 57 patients with HER2-amplified metastatic colorectal cancer were enrolled in the MyPathway study and deemed eligible for inclusionin this cohort analysis. Among these 57 evaluable patients, at Aug 1, 2017, one (2%) patient had a complete response and 17 (30%) had partial responses; thus overall 18 of 57 patients achieved an objective response (32%, 95% CI 20-45). The most common treatment-emergent adverse events were diarrhoea (19 [33%] of 57 patients), fatigue (18 [32%] patients), and nausea (17 [30%] patients). Grade 3-4 treatment-emergent adverse events were recorded in 21 (37%) of 57 patients, most commonly hypokalaemia and abdominal pain (each three [5%] patients). Serious treatment-emergent adverse events were reported in ten (18%) patients and two (4%) of these adverse events (ie, chills and infusion-related reaction) were considered treatment related. There were no treatment-related deaths.\n\nInterpretation: Dual HER2-targeted therapy with pertuzumab plus trastuzumab is well tolerated and could represent a therapeutic opportunity for patients with heavily pretreated, HER2-amplified metastatic colorectal cancer.\n\nFunding: F Hoffmann-La Roche/Genentech.\n\nIndexed on Europe PMC as PubMed record 30857956 (DOI 10.1016/s1470-2045(18)30904-5). Its abstract cites the registry id NCT02091141, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2019, doi: "10.1016/s1470-2045(18)30904-5", pmid: "30857956", authors: "Meric-Bernstam F, Hurwitz H, Raghav KPS, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02091141 with the most citations, so it is the natural first reading for anyone following the MyPathway trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2019","url":"https://doi.org/10.1016/s1470-2045(18)30904-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30857956/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30857956"},{"label":"ClinicalTrials.gov NCT02091141","url":"https://clinicaltrials.gov/study/NCT02091141"}], tags: ["europepmc-ingest"], trials: ["mypathway"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct03785249-n-engl-j-med-2022", name: "Adagrasib in Non-Small-Cell Lung Cancer Harboring a KRAS G12C Mutation", tldr: "Published report from the Phase 1 trial registered as NCT03785249, in New England Journal of Medicine (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Adagrasib, a KRAS G12C inhibitor, irreversibly and selectively binds KRAS G12C, locking it in its inactive state. Adagrasib showed clinical activity and had an acceptable adverse-event profile in the phase 1-1b part of the KRYSTAL-1 phase 1-2 study.\n\nMethods: In a registrational phase 2 cohort, we evaluated adagrasib (600 mg orally twice daily) in patients with KRAS G12C -mutated non-small-cell lung cancer (NSCLC) previously treated with platinum-based chemotherapy and anti-programmed death 1 or programmed death ligand 1 therapy. The primary end point was objective response assessed by blinded independent central review. Secondary end points included the duration of response, progression-free survival, overall survival, and safety.\n\nResults: at October 15, 2021, a total of 116 patients with KRAS G12C -mutated NSCLC had been treated (median follow-up, 12.9 months); 98.3% had previously received both chemotherapy and immunotherapy. Of 112 patients with measurable disease at baseline, 48 (42.9%) had a confirmed objective response. The median duration of response was 8.5 months (95% confidence interval [CI], 6.2 to 13.8), and the median progression-free survival was 6.5 months (95% CI, 4.7 to 8.4). at January 15, 2022 (median follow-up, 15.6 months), the median overall survival was 12.6 months (95% CI, 9.2 to 19.2). Among 33 patients with previously treated, stable central nervous system metastases, the intracranial confirmed objective response rate was 33.3% (95% CI, 18.0 to 51.8). Treatment-related adverse events occurred in 97.4% of the patients - grade 1 or 2 in 52.6% and grade 3 or higher in 44.8% (including two grade 5 events) - and resulted in drug discontinuation in 6.9% of patients.\n\nConclusions: In patients with previously treated KRAS G12C -mutated NSCLC, adagrasib showed clinical efficacy without new safety signals. (Funded by Mirati Therapeutics; ClinicalTrials.gov number, NCT03785249.).\n\nIndexed on Europe PMC as PubMed record 35658005 (DOI 10.1056/nejmoa2204619). Its abstract cites the registry id NCT03785249, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2022, doi: "10.1056/nejmoa2204619", pmid: "35658005", authors: "Jänne PA, Riely GJ, Gadgeel SM, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03785249 with the most citations, so it is the natural first reading for anyone following the Phase 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2022","url":"https://doi.org/10.1056/nejmoa2204619"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35658005/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35658005"},{"label":"ClinicalTrials.gov NCT03785249","url":"https://clinicaltrials.gov/study/NCT03785249"}], tags: ["europepmc-ingest"], trials: ["nct03785249"], journals: ["nejm"] }),
  p({ id: "paper-nct04068610-br-j-cancer-2024", name: "COLUMBIA-1: a randomised study of durvalumab plus oleclumab in combination with chemotherapy and bevacizumab in metastatic microsatellite-stable colorectal cancer", tldr: "Published report from the COLUMBIA-1 trial registered as NCT04068610, in British Journal of Cancer (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: To determine whether the addition of durvalumab (anti-PD-L1) and oleclumab (anti-CD73) to standard-of-care treatment (FOLFOX and bevacizumab) enhances the anti-tumour effect in patients with metastatic colorectal cancer (mCRC).\n\nMethods: COLUMBIA-1 (NCT04068610) was a Phase Ib (feasibility; Part 1)/Phase II (randomised; Part 2) trial in patients with treatment-naïve microsatellite stable mCRC. Patients in Part 2 were randomised to receive standard-of-care (control arm) or standard-of-care plus durvalumab and oleclumab (experimental arm). Primary objectives included safety and efficacy.\n\nResults: Seven patients were enrolled in Part 1 and 52 in Part 2 (n = 26 in each arm). Grade ≥3 treatment-emergent adverse events (TEAE) occurred in 80.8% and 65.4% of patients in the control and experimental arms of Part 2, respectively, with 26.9% and 46.3% experiencing serious TEAEs. The confirmed objective response rate (ORR) was numerically higher in the experimental arm compared with the control arm (61.5% [95% confidence interval (CI), 40.6-79.8] vs 46.2% [95% CI, 26.6-66.6]) but did not meet the statistically significant threshold in either arm.\n\nConclusion: The safety profile of FOLFOX and bevacizumab in combination with durvalumab and oleclumab was manageable; however, the efficacy results do not warrant further development of this combination in patients with microsatellite stable mCRC.\n\nRegistration: NCT04068610.\n\nIndexed on Europe PMC as PubMed record 39048638 (DOI 10.1038/s41416-024-02796-3). Its abstract cites the registry id NCT04068610, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "British Journal of Cancer", year: 2024, doi: "10.1038/s41416-024-02796-3", pmid: "39048638", authors: "Segal NH, Tie J, Kopetz S, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04068610 with the most citations, so it is the natural first reading for anyone following the COLUMBIA-1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Br J Cancer 2024","url":"https://doi.org/10.1038/s41416-024-02796-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39048638/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39048638"},{"label":"ClinicalTrials.gov NCT04068610","url":"https://clinicaltrials.gov/study/NCT04068610"}], tags: ["europepmc-ingest"], trials: ["nct04068610"], journals: ["british-journal-of-cancer"] }),
  p({ id: "paper-nct04854668-signal-transduct-target-ther-2026", name: "First-line anlotinib versus bevacizumab plus CapeOX in RAS/BRAF wild-type unresectable metastatic colorectal cancer (ANCHOR): a multicenter, prospective, randomized, phase 3 trial", tldr: "Published report from the BRAF Wild Metastatic Colorectal Can trial registered as NCT04854668, in Signal transduction and targeted therapy (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Bevacizumab plus chemotherapy is the standard first-line therapy for metastatic colorectal cancer (mCRC). To date, no phase 3 trial has compared first-line oral multitargeted TKI versus bevacizumab plus chemotherapy in RAS/BRAF wild-type mCRC. The open-label, noninferiority, randomized, phase 3 trial (ANCHOR; NCT04854668; CTR20210940) evaluated first-line anlotinib versus bevacizumab plus oxaliplatin and capecitabine (CapeOX) in this setting. Patients were centrally randomized (1:1) to receive 4-8 cycles of CapeOX in combination with either anlotinib (12 mg once daily on days 1-14) or bevacizumab (7.5 mg/kg on day 1) every 3 weeks, followed by maintenance therapy with anlotinib or bevacizumab plus capecitabine until unacceptable toxicity or disease progression. The primary endpoint was progression-free survival (PFS) assessed by an independent review committee in the intention-to-treat population. The hazard ratio (HR) for the noninferiority margin was 1.09. Between May 25, 2021, and August 30, 2023, 373 patients were assigned to the anlotinib group and 375 to the bevacizumab group. at February 2, 2025, the median follow-up was 25.1 months (95% confidence interval [CI] 23.8-26.3). The median PFS was 11.0 months (95% CI 9.8-11.2) in the anlotinib group versus 11.0 months (9.7-11.2) in the bevacizumab group (stratified HR, 1.00; 95% CI 0.84-1.18; p = 0.87). The incidences of grade ≥3 treatment-related adverse events were 64.9% and 44.8%, respectively. Compared with bevacizumab plus CapeOX, anlotinib plus CapeOX showed similar antitumor activity but failed to reach the prespecified noninferiority margin for PFS and was associated with increased manageable toxicity.\n\nIndexed on Europe PMC as PubMed record 42675036 (DOI 10.1038/s41392-026-02938-4). Its abstract cites the registry id NCT04854668, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Signal transduction and targeted therapy", year: 2026, doi: "10.1038/s41392-026-02938-4", pmid: "42675036", authors: "Liu Y, Zhang Y, Lin R, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04854668 with the most citations, so it is the natural first reading for anyone following the BRAF Wild Metastatic Colorectal Can trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Signal Transduct Target Ther 2026","url":"https://doi.org/10.1038/s41392-026-02938-4"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42675036/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42675036"},{"label":"ClinicalTrials.gov NCT04854668","url":"https://clinicaltrials.gov/study/NCT04854668"}], tags: ["europepmc-ingest"], trials: ["nct04854668"] }),
  p({ id: "paper-nct05425940-lancet-2025", name: "Zanzalintinib plus atezolizumab versus regorafenib in refractory colorectal cancer (STELLAR-303): a randomised, open-label, phase 3 trial", tldr: "Published report from the STELLAR-303 trial registered as NCT05425940, in The Lancet (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Zanzalintinib is a multitargeted tyrosine-kinase inhibitor that, when combined with atezolizumab, showed promising antitumour activity and manageable toxicity in a phase 1 study. We aimed to compare the efficacy and safety of zanzalintinib-atezolizumab versus regorafenib in patients with previously treated metastatic colorectal cancer.\n\nMethods: STELLAR-303 is a global, randomised, open-label, phase 3 trial done at 121 centres (including hospitals, academic medical centres, and specialised cancer research facilities) in 16 countries. Patients aged 18 years and older with confirmed metastatic adenocarcinoma of the colon or rectum, who had previously received standard-of-care therapy, and did not have microsatellite instability-high (MSI-H) or mismatch repair deficient (dMMR) tumours were randomly assigned (1:1) in blocks of four to oral zanzalintinib (100 mg daily) plus intravenous atezolizumab (1200 mg every 3 weeks) or oral regorafenib (160 mg daily on days 1-21 of each 28-day cycle) using an interactive response technology system, stratified by geographical region, RAS status, and presence of liver metastases. Dual primary endpoints were overall survival in the intention-to-treat (ITT) population and in the subset of patients without liver metastases. Safety was assessed in all patients who received at least one dose of study drug. This report is based on a planned overall survival analysis (data cutoff April 30, 2025); the trial is active but not recruiting, and continues to the final overall survival analysis in the subset of patients without liver metastases. This trial is registered with ClinicalTrials.gov (NCT05425940).\n\nFindings: 1325 patients were screened for eligibility; between Sept 7, 2022, and July 15, 2024, 901 patients were randomly assigned to zanzalintinib-atezolizumab (n=451) or regorafenib (n=450). 528 (59%) patients were male and 373 (41%) were female; 485 (54%) were White, 338 (38%) were Asian, 18 (2%) were Black, 24 (3%) were other races, and 36 (4%) had race not reported. At a median follow-up of 18·0 months (IQR 14·6-21·5), zanzalintinib-atezolizumab showed a significant overall survival benefit versus regorafenib in the ITT population (stratified hazard ratio [HR] 0·80 [95% CI 0·69-0·93]; p=0·0045) with a median overall survival of 10·9 months (95% CI 9·9-12·1) versus 9·4 months (8·5-10·2). At the interim analysis of overall survival in the subset of patients without liver metastases, the stratified HR for zanzalintinib-atezolizumab versus regorafenib was 0·79 (95% CI 0·61-1·03); p=0·087 (median overall survival 15·9 months [95% CI 13·5-17·6] vs 12·7 months [10·9-15·5]). Grade 3 or worse treatment-related adverse events occurred in 268 (60%) of 446 patients receiving zanzalintinib-atezolizumab and 161 (37%) of 434 patients receiving regorafenib. There were five (1%) treatment-related deaths in the zanzalintinib-atezolizumab group and one (<1%) in the regorafenib group.\n\nInterpretation: STELLAR-303 is the first phase 3 trial to show a significant improvement in overall survival with an immunotherapy-based regimen, zanzalintinib-atezolizumab, in patients with relapsed or refractory metastatic colorectal cancer that is not MSI-H or dMMR. This combination represents a chemotherapy-free treatment option with a novel mechanism of action for heavily pretreated patients in need of improved therapies.\n\nFunding: Exelixis.\n\nIndexed on Europe PMC as PubMed record 41130252 (DOI 10.1016/s0140-6736(25)02025-2). Its abstract cites the registry id NCT05425940, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2025, doi: "10.1016/s0140-6736(25)02025-2", pmid: "41130252", authors: "Hecht JR, Park YS, Tabernero J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05425940 with the most citations, so it is the natural first reading for anyone following the STELLAR-303 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2025","url":"https://doi.org/10.1016/s0140-6736(25)02025-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41130252/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41130252"},{"label":"ClinicalTrials.gov NCT05425940","url":"https://clinicaltrials.gov/study/NCT05425940"}], tags: ["europepmc-ingest"], trials: ["nct05425940"], journals: ["lancet"] }),
  p({ id: "paper-nct05890742-cancer-cell-2025", name: "Neoadjuvant treatment of IBI310 plus sintilimab in locally advanced MSI-H/dMMR colon cancer: A randomized phase 1b study", tldr: "Published report from the dMMR Resectable Colon Cancer trial registered as NCT05890742, in Cancer Cell (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Although neoadjuvant immunotherapy showed promising efficacy in locally advanced microsatellite instability-high or mismatch repair-deficient (MSI-H/dMMR) colon cancer, whether dual immune checkpoint inhibition provides additional benefit over anti-PD-1 monotherapy remains unclear. This randomized phase 1b trial (NCT05890742) evaluated a neoadjuvant regimen of IBI310 (anti-cytotoxic T lymphocyte-associated antigen 4 [CTLA-4]) plus sintilimab (n = 52) versus sintilimab monotherapy (n = 49). Surgery was performed in 51 and 45 patients, respectively. The primary endpoint, pathological complete response (pCR) rate, was significantly higher in the combination compared to the monotherapy arm within the modified intent-to-treat (mITT) population (78.4% versus 46.7%, p = 0.0015), with consistent results in the intent-to-treat (ITT) population (76.9% versus 42.9%). Safety in both arms was comparable and manageable without new safety signals. After a median follow-up of 21.4 months, no disease recurrences occurred. One death occurred in each arm due to postoperative complication and adverse events. These findings demonstrate the added benefit of neoadjuvant IBI310 plus sintilimab over sintilimab monotherapy for locally advanced MSI-H/dMMR colon cancer.\n\nIndexed on Europe PMC as PubMed record 41043438 (DOI 10.1016/j.ccell.2025.09.004). Its abstract cites the registry id NCT05890742, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Cancer Cell", year: 2025, doi: "10.1016/j.ccell.2025.09.004", pmid: "41043438", authors: "Wang F, Chen G, Qiu M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05890742 with the most citations, so it is the natural first reading for anyone following the dMMR Resectable Colon Cancer trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Cancer Cell 2025","url":"https://doi.org/10.1016/j.ccell.2025.09.004"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41043438/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41043438"},{"label":"ClinicalTrials.gov NCT05890742","url":"https://clinicaltrials.gov/study/NCT05890742"}], tags: ["europepmc-ingest"], trials: ["nct05890742"], journals: ["cancer-cell"] }),
  p({ id: "paper-nct06106308-j-clin-oncol-2025", name: "Onvansertib in Combination With Chemotherapy and Bevacizumab in Second-Line Treatment of KRAS -Mutant Metastatic Colorectal Cancer: A Single-Arm, Phase II Trial", tldr: "Published report from the trial registered as NCT06106308, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: This phase II study evaluated the efficacy and tolerability of onvansertib, a polo-like kinase 1 (PLK1) inhibitor, in combination with fluorouracil, leucovorin, and irinotecan (FOLFIRI) + bevacizumab for the second-line treatment of KRAS -mutant metastatic colorectal cancer (mCRC).\n\nPatients and methods: This multicenter, open-label, single-arm study enrolled patients with KRAS -mutated mCRC previously treated with oxaliplatin and fluorouracil with or without bevacizumab. Patients received onvansertib (15 mg/m 2 once daily on days 1-5 and 15-19 of a 28-day cycle) and FOLFIRI + bevacizumab (days 1 and 15). The primary end point was the objective response rate (ORR), and secondary endpoints included progression-free survival (PFS), duration of response (DOR), and tolerability. Translational and preclinical studies were conducted in KRAS -mutant CRC.\n\nResults: Among the 53 patients treated, the confirmed ORR was 26.4% (95% CI, 15.3 to 40.3). The median DOR was 11.7 months (95% CI, 9.4 to not reached). Grade 3/4 adverse events were reported in 62% of patients. A post hoc analysis revealed that patients with no prior bevacizumab treatment had a significantly higher ORR and longer PFS compared with patients with prior bevacizumab treatment: ORR of 76.9% versus 10.0% (odds ratio of 30.0, P <.001) and median PFS of 14.9 months versus 6.6 months (hazard ratio of 0.16, P <.001). Our translational findings support that prior bevacizumab exposure contributes to onvansertib resistance. Preclinically, we showed that onvansertib inhibited the hypoxia pathway and exhibited robust antitumor activity in combination with bevacizumab through the inhibition of angiogenesis.\n\nConclusion: Onvansertib in combination with FOLFIRI + bevacizumab showed significant activity in the second-line treatment of patients with KRAS -mutant mCRC, particularly in patients with no prior bevacizumab treatment. These findings led to the evaluation of the combination in the first-line setting (ClinicalTrails.gov identifier: NCT06106308).\n\nIndexed on Europe PMC as PubMed record 39475591 (DOI 10.1200/jco-24-01266). Its abstract cites the registry id NCT06106308, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-24-01266", pmid: "39475591", authors: "Ahn DH, Ridinger M, Cannon TL, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06106308 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-24-01266"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39475591/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39475591"},{"label":"ClinicalTrials.gov NCT06106308","url":"https://clinicaltrials.gov/study/NCT06106308"}], tags: ["europepmc-ingest"], trials: ["nct06106308"], journals: ["jco"] }),
  p({ id: "paper-nct04547166-med-2024", name: "First-line serplulimab in metastatic colorectal cancer: Phase 2 results of a randomized, double-blind, phase 2/3 trial", tldr: "Published report from the trial registered as NCT04547166, in Med (New York, N.Y.) (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Whether or not the addition of immunotherapy to current standard-of-care treatments can improve efficacy in proficient mismatch repair (pMMR)/microsatellite-stable (MSS) metastatic colorectal cancer (mCRC), the predominant type of mCRC, is unclear.\n\nMethods: This randomized, double-blind, phase 2 part of a phase 2/3 trial was conducted at 23 hospitals across China (ClinicalTrials.gov: NCT04547166). Patients with unresectable metastatic/recurrent colorectal adenocarcinoma and no prior systemic therapy were randomly assigned 1:1 to receive every-3-weeks intravenous serplulimab (300 mg) plus HLX04 (7.5 mg/kg) and XELOX (serplulimab group) or placebo (300 mg) plus bevacizumab (7.5 mg/kg) and XELOX (placebo group). The primary endpoint was independent radiology review committee (IRRC)-assessed progression-free survival (PFS). Secondary endpoints included other efficacy endpoints and safety.\n\nFindings: Between July 16, 2021, and January 20, 2022, 114 patients were enrolled and randomly assigned to the serplulimab (n = 57) or placebo (n = 57) group. All patients had stage IV CRC, and 95.7% of the patients with available microsatellite instability (MSI) status were MSS. With a median follow-up duration of 17.7 months, median PFS was prolonged in the serplulimab group (17.2 vs. 10.7 months; hazard ratio [HR], 0.60; 95% confidence interval [CI], 0.31-1.14). Although the median overall survival (OS) was not reached for either group, a trend of an OS benefit was observed for the serplulimab group (HR, 0.77; 95% CI, 0.41-1.45). 36 (65.5%) and 32 (56.1%) patients in the serplulimab and placebo groups had grade ≥3 treatment-related adverse events, respectively.\n\nConclusions: Serplulimab plus HLX04 and XELOX exhibits promising efficacy and is safe and tolerable in patients with treatment-naive mCRC.\n\nFunding: This work was funded by Shanghai Henlius Biotech, Inc.\n\nIndexed on Europe PMC as PubMed record 38870931 (DOI 10.1016/j.medj.2024.05.009). Its abstract cites the registry id NCT04547166, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Med (New York, N.Y.)", year: 2024, doi: "10.1016/j.medj.2024.05.009", pmid: "38870931", authors: "Wang ZX, Peng J, Liang X, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04547166 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Med 2024","url":"https://doi.org/10.1016/j.medj.2024.05.009"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38870931/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38870931"},{"label":"ClinicalTrials.gov NCT04547166","url":"https://clinicaltrials.gov/study/NCT04547166"}], tags: ["europepmc-ingest"], trials: ["nct04547166"] }),
  p({ id: "paper-nct04585750-n-engl-j-med-2026", name: "Phase 1 Study of Rezatapopt, a p53 Reactivator, in TP53 Y220C-Mutated Tumors", tldr: "Published report from the PYNNACLE trial registered as NCT04585750, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Rezatapopt is an investigational, first-in-class, oral, selective p53 reactivator that specifically binds to Y220C-mutated p53, which stabilizes p53 in its wild-type conformation and restores its functionality.\n\nMethods: In this phase 1, single-group, dose-escalation and dose-optimization study, we assigned heavily pretreated patients with locally advanced or metastatic solid tumors harboring a TP53 Y220C mutation to receive rezatapopt during continuous 21-day treatment cycles. The primary objectives were to determine the maximum tolerated dose and recommended phase 2 dose. Primary end points included dose-limiting toxic effects and adverse events. Secondary end points included preliminary efficacy and pharmacokinetic features.\n\nResults: A total of 77 patients received rezatapopt at one of eight escalating doses: 150 mg, 300 mg, 600 mg, 1150 mg, 1500 mg, 2000 mg, or 2500 mg once daily or 1500 mg twice daily. The maximum tolerated dose was 1500 mg twice daily. On the basis of safety, efficacy, and pharmacokinetic data, 2000 mg once daily with food was selected as the recommended phase 2 dose. During the treatment period, 76 patients (99%) had at least one adverse event and 29 (38%) had an adverse event of grade 1 or 2. The most common adverse events were nausea (in 58% of patients), vomiting (in 44%), an increased blood creatinine level (in 39%), fatigue (in 39%), and anemia (in 36%). Treatment-related adverse events occurred in 67 patients (87%) and those of grade 1 or 2 in 48 (62%); 2 patients (3%) discontinued rezatapopt because of a treatment-related adverse event. Most gastrointestinal adverse events resolved with the treatment of symptoms and were less frequent when rezatapopt was given with food. Anemia was the most common adverse event of grade 3 or higher during the treatment period, occurring in 16% of patients. The overall response (complete or partial response) was 20% among all patients and 30% among those who had a KRAS wild-type tumor and received a dose of at least 1150 mg once daily. Confirmed responses were seen across multiple tumor types, including ovarian and breast cancers. All patients with a response had a solid tumor that harbored TP53 Y220C and wild-type KRAS.\n\nConclusions: In this phase 1 study involving heavily pretreated patients, the most common adverse events associated with rezatapopt were nausea and vomiting. Antitumor activity occurred across multiple tumor types, providing proof of concept for p53 reactivation. (Funded by PMV Pharmaceuticals; PYNNACLE ClinicalTrials.gov number, NCT04585750.).\n\nIndexed on Europe PMC as PubMed record 41740031 (DOI 10.1056/nejmoa2508820). Its abstract cites the registry id NCT04585750, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2508820", pmid: "41740031", authors: "Dumbrava EE, Shapiro GI, Parikh AR, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04585750 with the most citations, so it is the natural first reading for anyone following the PYNNACLE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2508820"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41740031/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41740031"},{"label":"ClinicalTrials.gov NCT04585750","url":"https://clinicaltrials.gov/study/NCT04585750"}], tags: ["europepmc-ingest"], trials: ["nct04585750"], journals: ["nejm"] }),
  p({ id: "paper-nct05300269-cancer-lett-2026", name: "Efficacy and safety of SHR-1701 combined with chemoradiotherapy as neoadjuvant treatment for locally advanced rectal cancer", tldr: "Published report from the trial registered as NCT05300269, in Cancer letters (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Locally advanced rectal cancer (LARC) remains challenging to treat due to high recurrence rates and limited therapeutic options, particularly for patients with high-risk features. This prospective, multicenter, single-arm, open-label phase 2 trial (ClinicalTrials.gov identifier: NCT05300269) evaluated the efficacy and safety of SHR-1701, a novel bifunctional fusion protein targeting both PD-L1 and TGF-β, in combination with neoadjuvant chemoradiotherapy (CRT) followed by total mesorectal excision (TME) for high-risk LARC. Eligible patients had at least one high-risk factor, including cT3c-d or cT4 tumors, positive mesorectal fascia, extramural vascular invasion, or involvement of ≥4 lymph nodes. Patients received concurrent SHR-1701 and CRT, followed by two cycles of SHR-1701 plus XELOX and subsequent TME surgery. Postoperatively, patients underwent six additional cycles of SHR-1701 plus XELOX. The primary endpoints were pathological complete response (pCR) rate and safety. Among the 37 enrolled patients, 36 (97.3 %) completed the planned full-dose radiotherapy (50.4 Gy in 28 fractions) and subsequently underwent surgery. The pCR rate was 36.1 % (13/36). The median intervals from neoadjuvant therapy initiation to surgery and from surgery to adjuvant therapy were 112 days (range, 95-139) and 29 days (range, 22-59), respectively. The median follow-up was 9.9 months (range, 2-18) from the first dose of capecitabine. Grade ≥3 treatment-related adverse events during neoadjuvant therapy occurred in 40.5 % (15/37) of patients, most commonly lymphopenia (37.8 %, 14/37) and anemia (5.4 %, 2/37). One patient experienced fatal immune-mediated myocarditis prior to surgery. Overall, the addition of SHR-1701 to CRT demonstrated encouraging efficacy and manageable safety in high-risk LARC, supporting further investigation in larger randomized trials.\n\nIndexed on Europe PMC as PubMed record 40876501 (DOI 10.1016/j.canlet.2025.218006). Its abstract cites the registry id NCT05300269, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Cancer letters", year: 2026, doi: "10.1016/j.canlet.2025.218006", pmid: "40876501", authors: "Tang W, Lv Y, Xie H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05300269 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Cancer Lett 2026","url":"https://doi.org/10.1016/j.canlet.2025.218006"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40876501/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40876501"},{"label":"ClinicalTrials.gov NCT05300269","url":"https://clinicaltrials.gov/study/NCT05300269"}], tags: ["europepmc-ingest"], trials: ["nct05300269"], journals: ["cancer-letters"] }),
  p({ id: "paper-nct05379595-j-clin-oncol-2026", name: "Amivantamab Monotherapy in Chemorefractory RAS / BRAF Wild-Type Metastatic Colorectal Cancer: Results From OrigAMI-1, an Open-Label, Phase Ib/II Study", tldr: "Published report from the OrigAMI-1 trial registered as NCT05379595, in Journal of Clinical Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Amivantamab, an EGFR-MET bispecific antibody with immune cell-directing activity, is approved in non-small cell lung cancer (NSCLC). Effective treatments are limited for chemorefractory metastatic colorectal cancer (mCRC).\n\nMethods: OrigAMI-1 (ClinicalTrials.gov identifier: NCT05379595) is a phase Ib/II study evaluating amivantamab monotherapy in chemorefractory (2-3 prior lines) mCRC. Participants had centrally confirmed RAS / BRAF / EGFR ectodomain wild-type status, without ERBB2 / HER2 amplification. Participants with left-sided mCRC without (cohort A) or with (cohort B) prior anti-EGFR antibody treatment, or right-sided mCRC (cohort C) regardless of prior anti-EGFR treatment, received intravenous amivantamab 1,050 mg (1,400 mg for ≥80 kg) once every 2 weeks. The primary end point was objective response rate (ORR) per RECIST v1.1.\n\nResults: By October 31, 2024, 94 participants received amivantamab monotherapy (median follow-up, 11.9 months). The median age was 60 years, and 65% of participants were male, with a median of 2 prior lines (94%, prior bevacizumab). In left-sided cohorts, the ORR was 29% (5 of 17) in cohort A and 19% (10 of 54) in cohort B; the median duration of response (DoR) was 9.0 months and 6.1 months, and the median progression-free survival (PFS) was 5.7 months and 4.6 months, respectively. In the right-sided cohort, the ORR was 22% (10 of 23; 43% had prior anti-EGFR), the median DoR was 9.8 months, and the median PFS was 3.7 months. Most frequent treatment-related grade ≥3 adverse events (AEs) were rash (7%), dermatitis acneiform (4%), and hypoalbuminemia (4%). One participant discontinued amivantamab because of a treatment-related AE.\n\nConclusion: Amivantamab monotherapy demonstrated promising, durable antitumor activity in chemorefractory mCRC, regardless of prior anti-EGFR therapy and the primary tumor location. The amivantamab safety profile in mCRC is consistent with experience in NSCLC. Amivantamab plus chemotherapy is currently being explored in two phase III studies in first-line and second-line mCRCs.\n\nIndexed on Europe PMC as PubMed record 42013403 (DOI 10.1200/jco-25-02187). Its abstract cites the registry id NCT05379595, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2026, doi: "10.1200/jco-25-02187", pmid: "42013403", authors: "Oberstein PE, Hecht JR, Raghav K, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05379595 with the most citations, so it is the natural first reading for anyone following the OrigAMI-1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2026","url":"https://doi.org/10.1200/jco-25-02187"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42013403/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42013403"},{"label":"ClinicalTrials.gov NCT05379595","url":"https://clinicaltrials.gov/study/NCT05379595"}], tags: ["europepmc-ingest"], trials: ["nct05379595"], journals: ["jco"] }),
  p({ id: "paper-tracc-clin-cancer-res-2024", name: "Tissue-Free Liquid Biopsies Combining Genomic and Methylation Signals for Minimal Residual Disease Detection in Patients with Early Colorectal Cancer from the UK TRACC Part B Study", tldr: "Published report from the TRACC trial registered as NCT04050345, in Clinical Cancer Research (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: The absence of postoperative circulating tumor DNA (ctDNA) identifies patients with resected colorectal cancer (CRC) with low recurrence risk for adjuvant chemotherapy (ACT) de-escalation. Our study presents the largest resected CRC cohort to date with tissue-free minimal residual disease (MRD) detection.\n\nExperimental design: TRACC (tracking mutations in cell-free tumor DNA to predict relapse in early colorectal cancer) included patients with stage I to III resectable CRC. Prospective longitudinal plasma collection for ctDNA occurred pre- and postsurgery, post-ACT, every 3 months for year 1 and every 6 months in years 2 and 3 with imaging annually. The Guardant Reveal assay evaluated genomic and methylation signals. The primary endpoint was 2-year recurrence-free survival (RFS) by postoperative ctDNA detection (NCT04050345).\n\nResults: Between December 2016 and August 2022, 1,203 were patients enrolled. Plasma samples (n = 997) from 214 patients were analyzed. One hundred forty-three patients were evaluable for the primary endpoint; 92 (64.3%) colon, 51 (35.7%) rectal; two (1.4%) stage I, 64 (44.8%) stage II, and 77 (53.8%) stage III. Median follow-up was 30.3 months (95% CI, 29.5-31.3). Two-year RFS was 91.1% in patients with ctDNA not detected postoperatively and 50.4% in those with ctDNA detected [HR, 6.5 (2.96-14.5); P < 0.0001]. Landmark negative predictive value (NPV) was 91.2% (95% CI, 83.9-95.9). Longitudinal sensitivity and specificity were 62.1% (95% CI, 42.2-79.3) and 85.9% (95% CI, 78.9-91.3), respectively. The median lead time from ctDNA detection to radiological recurrence was 7.3 months (IQR, 3.3-12.5; n = 9).\n\nConclusions: Tissue-free MRD detection with longitudinal sampling predicts recurrence in patients with stage I to III CRC without the need for tissue sequencing. The UK TRACC Part C study is currently investigating the potential for ACT de-escalation in patients with undetectable postoperative ctDNA, given the high NPV indicating a low likelihood of residual disease.\n\nIndexed on Europe PMC as PubMed record 38864835 (DOI 10.1158/1078-0432.ccr-24-0226). Its abstract cites the registry id NCT04050345, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Clinical Cancer Research", year: 2024, doi: "10.1158/1078-0432.ccr-24-0226", pmid: "38864835", authors: "Slater S, Bryant A, Aresu M, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04050345 with the most citations, so it is the natural first reading for anyone following the TRACC trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Clin Cancer Res 2024","url":"https://doi.org/10.1158/1078-0432.ccr-24-0226"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38864835/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38864835"},{"label":"ClinicalTrials.gov NCT04050345","url":"https://clinicaltrials.gov/study/NCT04050345"}], tags: ["europepmc-ingest"], trials: ["tracc"], journals: ["clinical-cancer-research"] }),
  p({ id: "paper-bolt-j-eur-acad-dermatol-venereol-2018-update", name: "Long-term efficacy and safety of sonidegib in patients with locally advanced and metastatic basal cell carcinoma: 30-month analysis of the randomized phase 2 BOLT study", tldr: "Later report from the BOLT trial registered as NCT01327053, in Journal of the European Academy of Dermatology and Venereology (2018); its title describes an updated or longer-term analysis.", summary: "Background: Patients with locally advanced basal cell carcinoma (laBCC) or metastatic BCC (mBCC), two difficult-to-treat populations, have had limited treatment options. Sonidegib, a hedgehog pathway inhibitor (HPI), was approved in laBCC based on results from the BOLT trial.\n\nObjective: To evaluate long-term efficacy and safety of sonidegib in laBCC and mBCC in the BOLT 18- and 30-month analyses.\n\nMethods: BOLT (NCT01327053, ClinicalTrials.gov), a double-blind phase 2 study, enrolled patients from July 2011 until January 2013. Eligible HPI-treatment-naïve patients with laBCC not amenable to curative surgery/radiotherapy or mBCC were randomized 1: 2 to sonidegib 200 mg (laBCC, n = 66; mBCC, n = 13) or 800 mg (laBCC, n = 128; mBCC, n = 23). Tumour response was assessed per central and investigator review.\n\nResults: With 30 months of follow-up, among patients treated with sonidegib 200 mg (approved dose), objective response rates were 56.1% (central) and 71.2% (investigator) in laBCC and 7.7% (central) and 23.1% (investigator) in mBCC. Tumour responses were durable as follows: median duration of response was 26.1 months (central) and 15.7 months (investigator) in laBCC and 24.0 months (central) and 18.1 months (investigator) in mBCC. Five patients with laBCC and three with mBCC in the 200-mg arm died. Median overall survival was not reached in either population; 2-year overall survival rates were 93.2% (laBCC) and 69.3% (mBCC). In laBCC, efficacy was similar regardless of aggressive or non-aggressive histology. Sonidegib 200 mg continued to have a better safety profile than 800 mg, with lower rates of grade 3/4 adverse events (43.0% vs. 64.0%) and adverse events leading to discontinuation (30.4% vs. 40.0%).\n\nConclusion: Sonidegib continued to demonstrate long-term efficacy and safety in these populations. These data support the use of sonidegib 200 mg per local treatment guidelines.\n\nIndexed on Europe PMC as PubMed record 28846163 (DOI 10.1111/jdv.14542). Its abstract cites the registry id NCT01327053, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of the European Academy of Dermatology and Venereology", year: 2018, doi: "10.1111/jdv.14542", pmid: "28846163", authors: "Lear JT, Migden MR, Lewis KD, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the BOLT trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Eur Acad Dermatol Venereol 2018","url":"https://doi.org/10.1111/jdv.14542"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28846163/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28846163"},{"label":"ClinicalTrials.gov NCT01327053","url":"https://clinicaltrials.gov/study/NCT01327053"}], tags: ["europepmc-ingest"], trials: ["bolt"] }),
  p({ id: "paper-checkmate-204-n-engl-j-med-2018", name: "Combined Nivolumab and Ipilimumab in Melanoma Metastatic to the Brain", tldr: "Published report from the CheckMate 204 trial registered as NCT02320058, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Brain metastases are a common cause of disabling neurologic complications and death in patients with metastatic melanoma. Previous studies of nivolumab combined with ipilimumab in metastatic melanoma have excluded patients with untreated brain metastases. We evaluated the efficacy and safety of nivolumab plus ipilimumab in patients with melanoma who had untreated brain metastases.\n\nMethods: In this open-label, multicenter, phase 2 study, patients with metastatic melanoma and at least one measurable, nonirradiated brain metastasis (tumor diameter, 0.5 to 3 cm) and no neurologic symptoms received nivolumab (1 mg per kilogram of body weight) plus ipilimumab (3 mg per kilogram) every 3 weeks for up to four doses, followed by nivolumab (3 mg per kilogram) every 2 weeks until progression or unacceptable toxic effects. The primary end point was the rate of intracranial clinical benefit, defined as the percentage of patients who had stable disease for at least 6 months, complete response, or partial response.\n\nResults: Among 94 patients with a median follow-up of 14.0 months, the rate of intracranial clinical benefit was 57% (95% confidence interval [CI], 47 to 68); the rate of complete response was 26%, the rate of partial response was 30%, and the rate of stable disease for at least 6 months was 2%. The rate of extracranial clinical benefit was 56% (95% CI, 46 to 67). Treatment-related grade 3 or 4 adverse events were reported in 55% of patients, including events involving the central nervous system in 7%. One patient died from immune-related myocarditis. The safety profile of the regimen was similar to that reported in patients with melanoma who do not have brain metastases.\n\nConclusions: Nivolumab combined with ipilimumab had clinically meaningful intracranial efficacy, concordant with extracranial activity, in patients with melanoma who had untreated brain metastases. (Funded by Bristol-Myers Squibb and the National Cancer Institute; CheckMate 204 ClinicalTrials.gov number, NCT02320058.).\n\nIndexed on Europe PMC as PubMed record 30134131 (DOI 10.1056/nejmoa1805453). Its abstract cites the registry id NCT02320058, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1805453", pmid: "30134131", authors: "Tawbi HA, Forsyth PA, Algazi A, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02320058 with the most citations, so it is the natural first reading for anyone following the CheckMate 204 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1805453"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30134131/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30134131"},{"label":"ClinicalTrials.gov NCT02320058","url":"https://clinicaltrials.gov/study/NCT02320058"}], tags: ["europepmc-ingest"], trials: ["checkmate-204"], journals: ["nejm"] }),
  p({ id: "paper-checkmate-204-lancet-oncol-2021-update", name: "Long-term outcomes of patients with active melanoma brain metastases treated with combination nivolumab plus ipilimumab (CheckMate 204): final results of an open-label, multicentre, phase 2 study", tldr: "Later report from the CheckMate 204 trial registered as NCT02320058, in The Lancet Oncology (2021); its title describes an updated or longer-term analysis.", summary: "Background: Combination nivolumab plus ipilimumab was efficacious in patients with asymptomatic melanoma brain metastases (MBM) in CheckMate 204, but showed low efficacy in patients with symptomatic MBM. Here, we provide final 3-year follow-up data from the trial.\n\nMethods: This open-label, multicentre, phase 2 study (CheckMate 204) included adults (aged ≥18 years) with measurable MBM (0·5-3·0 cm in diameter). Asymptomatic patients (cohort A) had an Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1 and no neurological symptoms or baseline corticosteroid use; symptomatic patients (cohort B) had an ECOG performance status of 0-2 with stable neurological symptoms and could be receiving low-dose dexamethasone. Nivolumab 1 mg/kg plus ipilimumab 3 mg/kg was given intravenously every 3 weeks for four doses, followed by nivolumab 3 mg/kg every 2 weeks for up to 2 years, until disease progression or unacceptable toxicity. The primary endpoint was intracranial clinical benefit rate (complete responses, partial responses, or stable disease lasting ≥6 months) assessed in all treated patients. Intracranial progression-free survival and overall survival were key secondary endpoints. This study is registered with ClinicalTrials.gov, NCT02320058.\n\nFindings: Between Feb 19, 2015, and Nov 1, 2017, 119 (72%) of 165 screened patients were enrolled and treated: 101 patients were asymptomatic (cohort A; median follow-up 34·3 months [IQR 14·7-36·4]) and 18 were symptomatic (cohort B; median follow-up 7·5 months [1·2-35·2]). Investigator-assessed intracranial clinical benefit was observed in 58 (57·4% [95% CI 47·2-67·2]) of 101 patients in cohort A and three (16·7% [3·6-41·4]) of 18 patients in cohort B; investigator-assessed objective response was observed in 54 (53·5% [43·3-63·5]) patients in cohort A and three (16·7% [3·6-41·4]) patients in cohort B. 33 (33%) patients in cohort A and three (17%) patients in cohort B had an investigator-assessed intracranial complete response. For patients in cohort A, 36-month intracranial progression-free survival was 54·1% (95% CI 42·7-64·1) and overall survival was 71·9% (61·8-79·8). For patients in cohort B, 36-month intracranial progression-free survival was 18·9% (95% CI 4·6-40·5) and overall survival was 36·6% (14·0-59·8). The most common grade 3-4 treatment-related adverse events (TRAEs) were increased alanine aminotransferase and aspartate aminotransferase (15 [15%] of 101 patients each) in cohort A; no grade 3 TRAEs occurred in more than one patient each in cohort B, and no grade 4 events occurred. The most common serious TRAEs were colitis, diarrhoea, hypophysitis, and increased alanine aminotransferase (five [5%] of each among the 101 patients in cohort A); no serious TRAE occurred in more than one patient each in cohort B. There was one treatment-related death (myocarditis in cohort A).\n\nInterpretation: The durable 3-year response, overall survival, and progression-free survival rates for asymptomatic patients support first-line use of nivolumab plus ipilimumab. Symptomatic disease in patients with MBM remains difficult to treat, but some patients achieve a long-term response with the combination.\n\nFunding: Bristol Myers Squibb.\n\nIndexed on Europe PMC as PubMed record 34774225 (DOI 10.1016/s1470-2045(21)00545-3). Its abstract cites the registry id NCT02320058, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2021, doi: "10.1016/s1470-2045(21)00545-3", pmid: "34774225", authors: "Tawbi HA, Forsyth PA, Hodi FS, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the CheckMate 204 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2021","url":"https://doi.org/10.1016/s1470-2045(21)00545-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34774225/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34774225"},{"label":"ClinicalTrials.gov NCT02320058","url":"https://clinicaltrials.gov/study/NCT02320058"}], tags: ["europepmc-ingest"], trials: ["checkmate-204"], journals: ["lancet-oncology"] }),
  p({ id: "paper-checkmate-238-lancet-oncol-2020-update", name: "Adjuvant nivolumab versus ipilimumab in resected stage IIIB-C and stage IV melanoma (CheckMate 238): 4-year results from a multicentre, double-blind, randomised, controlled, phase 3 trial", tldr: "Later report from the CheckMate 238 trial registered as NCT02388906, in The Lancet Oncology (2020); its title describes an updated or longer-term analysis.", summary: "Background: Previously, findings from CheckMate 238, a double-blind, phase 3 adjuvant trial in patients with resected stage IIIB-C or stage IV melanoma, showed significant improvements in recurrence-free survival and distant metastasis-free survival with nivolumab versus ipilimumab. This report provides updated 4-year efficacy, initial overall survival, and late-emergent safety results.\n\nMethods: This multicentre, double-blind, randomised, controlled, phase 3 trial was done in 130 academic centres, community hospitals, and cancer centres across 25 countries. Patients aged 15 years or older with resected stage IIIB-C or IV melanoma and an Eastern Cooperative Oncology Group performance status of 0 or 1 were randomly assigned (1:1) to receive nivolumab or ipilimumab via an interactive voice response system and stratified according to disease stage and baseline PD-L1 status of tumour cells. Patients received intravenous nivolumab 3 mg/kg every 2 weeks or intravenous ipilimumab 10 mg/kg every 3 weeks for four doses, and then every 12 weeks until 1 year of treatment, disease recurrence, unacceptable toxicity, or withdrawal of consent. The primary endpoint was recurrence-free survival by investigator assessment, and overall survival was a key secondary endpoint. Efficacy analyses were done in the intention-to-treat population (all randomly assigned patients). All patients who received at least one dose of study treatment were included in the safety analysis. The results presented in this report reflect the 4-year update of the ongoing study with a database lock date of Jan 30, 2020. This study is registered with ClinicalTrials.gov, NCT02388906.\n\nFindings: Between March 30 and Nov 30, 2015, 906 patients were assigned to nivolumab (n=453) or ipilimumab (n=453). Median follow-up was 51·1 months (IQR 41·6-52·7) with nivolumab and 50·9 months (36·2-52·3) with ipilimumab; 4-year recurrence-free survival was 51·7% (95% CI 46·8-56·3) in the nivolumab group and 41·2% (36·4-45·9) in the ipilimumab group (hazard ratio [HR] 0·71 [95% CI 0·60-0·86]; p=0·0003). With 211 (100 [22%] of 453 patients in the nivolumab group and 111 [25%] of 453 patients in the ipilimumab group) of 302 anticipated deaths observed (about 73% of the originally planned 88% power needed for significance), 4-year overall survival was 77·9% (95% CI 73·7-81·5) with nivolumab and 76·6% (72·2-80·3) with ipilimumab (HR 0·87 [95% CI 0·66-1·14]; p=0·31). Late-emergent grade 3-4 treatment-related adverse events were reported in three (1%) of 452 and seven (2%) of 453 patients. The most common late-emergent treatment-related grade 3 or 4 adverse events reported were diarrhoea, diabetic ketoacidosis, and pneumonitis (one patient each) in the nivolumab group, and colitis (two patients) in the ipilimumab group. Two previously reported treatment-related deaths in the ipilimumab group were attributed to study drug toxicity (marrow aplasia in one patient and colitis in one patient); no further treatment-related deaths were reported.\n\nInterpretation: At a minimum of 4 years' follow-up, nivolumab demonstrated sustained recurrence-free survival benefit versus ipilimumab in resected stage IIIB-C or IV melanoma indicating a long-term treatment benefit with nivolumab. With fewer deaths than anticipated, overall survival was similar in both groups. Nivolumab remains an efficacious adjuvant treatment for patients with resected high-risk melanoma, with a safety profile that is more tolerable than that of ipilimumab.\n\nFunding: Bristol Myers Squibb and Ono Pharmaceutical.\n\nIndexed on Europe PMC as PubMed record 32961119 (DOI 10.1016/s1470-2045(20)30494-0). Its abstract cites the registry id NCT02388906, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2020, doi: "10.1016/s1470-2045(20)30494-0", pmid: "32961119", authors: "Ascierto PA, Del Vecchio M, Mandalá M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CheckMate 238 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2020","url":"https://doi.org/10.1016/s1470-2045(20)30494-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32961119/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32961119"},{"label":"ClinicalTrials.gov NCT02388906","url":"https://clinicaltrials.gov/study/NCT02388906"}], tags: ["europepmc-ingest"], trials: ["checkmate-238"], journals: ["lancet-oncology"] }),
  p({ id: "paper-checkmate-915-j-immunother-cancer-2025", name: "Pretreatment and on-treatment ctDNA and tissue biomarkers predict recurrence in patients with stage IIIB-D/IV melanoma treated with adjuvant immunotherapy: CheckMate 915", tldr: "Published report from the CheckMate 915 trial registered as NCT03068455, in Journal for ImmunoTherapy of Cancer (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: CheckMate 915 (NCT03068455) compared adjuvant nivolumab monotherapy versus combination nivolumab+ipilimumab in patients with resected stage III/IV melanoma. This exploratory analysis was performed to identify biomarkers that correlate with benefit from adjuvant immunotherapy.\n\nPatients and methods: 1,844 patients received nivolumab 480 mg every 4 weeks or nivolumab 240 mg every 2 weeks with ipilimumab 1 mg/kg every 6 weeks. Tumor and peripheral biomarkers were evaluated, including tumor-informed circulating tumor DNA (ctDNA) at postresection baseline and on-treatment, for their association with recurrence-free survival and distant metastases-free survival.\n\nResults: Biomarker analyses were conducted in 60-96% of the intention-to-treat population. ctDNA positivity at baseline (seen in 16.2% of patients) and on-treatment was associated with higher risk of recurrence than ctDNA negativity (HR, 1.97; 95% CI, 1.57 to 2.46), with a high specificity (87%) and modest sensitivity (39%). ctDNA status, tumor mutational burden (TMB) status (TMB < or ≥350 mutations/tumor) and interferon gamma-RNA signature score (< or ≥median) evaluated together, as well as ctDNA status with tumor CD8 or cell programmed death ligand 1 expression, were more predictive of survival than ctDNA alone. Tumor bulk RNA-seq expression patterns identified gene expression at baseline associated with recurrence.\n\nConclusions: This study represents the largest assessment of ctDNA and other baseline tumor and peripheral biomarkers for predicting recurrence-free survival in patients with resected melanoma receiving adjuvant immunotherapy. ctDNA alone and in combination with more established biomarkers predicted recurrence-free and distant metastasis-free survival and has potential utility for assessing and monitoring the risk of recurrence in patients with resected melanoma treated with immunotherapy in the adjuvant setting.\n\nTrial registration number: NCT03068455.\n\nIndexed on Europe PMC as PubMed record 40645660 (DOI 10.1136/jitc-2025-012034). Its abstract cites the registry id NCT03068455, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal for ImmunoTherapy of Cancer", year: 2025, doi: "10.1136/jitc-2025-012034", pmid: "40645660", authors: "Long GV, Tang H, Desai K, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03068455 with the most citations, so it is the natural first reading for anyone following the CheckMate 915 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Immunother Cancer 2025","url":"https://doi.org/10.1136/jitc-2025-012034"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40645660/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40645660"},{"label":"ClinicalTrials.gov NCT03068455","url":"https://clinicaltrials.gov/study/NCT03068455"}], tags: ["europepmc-ingest"], trials: ["checkmate-915"], journals: ["jitc"] }),
  p({ id: "paper-cobrim-n-engl-j-med-2014", name: "Combined vemurafenib and cobimetinib in BRAF-mutated melanoma", tldr: "Published report from the coBRIM trial registered as NCT01689519, in New England Journal of Medicine (2014), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The combined inhibition of BRAF and MEK is hypothesized to improve clinical outcomes in patients with melanoma by preventing or delaying the onset of resistance observed with BRAF inhibitors alone. This randomized phase 3 study evaluated the combination of the BRAF inhibitor vemurafenib and the MEK inhibitor cobimetinib.\n\nMethods: We randomly assigned 495 patients with previously untreated unresectable locally advanced or metastatic BRAF V600 mutation-positive melanoma to receive vemurafenib and cobimetinib (combination group) or vemurafenib and placebo (control group). The primary end point was investigator-assessed progression-free survival.\n\nResults: The median progression-free survival was 9.9 months in the combination group and 6.2 months in the control group (hazard ratio for death or disease progression, 0.51; 95% confidence interval [CI], 0.39 to 0.68; P<0.001). The rate of complete or partial response in the combination group was 68%, as compared with 45% in the control group (P<0.001), including rates of complete response of 10% in the combination group and 4% in the control group. Progression-free survival as assessed by independent review was similar to investigator-assessed progression-free survival. Interim analyses of overall survival showed 9-month survival rates of 81% (95% CI, 75 to 87) in the combination group and 73% (95% CI, 65 to 80) in the control group. Vemurafenib and cobimetinib was associated with a nonsignificantly higher incidence of adverse events of grade 3 or higher, as compared with vemurafenib and placebo (65% vs. 59%), and there was no significant difference in the rate of study-drug discontinuation. The number of secondary cutaneous cancers decreased with the combination therapy.\n\nConclusions: The addition of cobimetinib to vemurafenib was associated with a significant improvement in progression-free survival among patients with BRAF V600-mutated metastatic melanoma, at the cost of some increase in toxicity. (Funded by F. Hoffmann-La Roche/Genentech; coBRIM ClinicalTrials.gov number, NCT01689519.).\n\nIndexed on Europe PMC as PubMed record 25265494 (DOI 10.1056/nejmoa1408868). Its abstract cites the registry id NCT01689519, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2014, doi: "10.1056/nejmoa1408868", pmid: "25265494", authors: "Larkin J, Ascierto PA, Dréno B, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01689519 with the most citations, so it is the natural first reading for anyone following the coBRIM trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2014","url":"https://doi.org/10.1056/nejmoa1408868"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/25265494/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/25265494"},{"label":"ClinicalTrials.gov NCT01689519","url":"https://clinicaltrials.gov/study/NCT01689519"}], tags: ["europepmc-ingest"], trials: ["cobrim"], journals: ["nejm"] }),
  p({ id: "paper-cobrim-lancet-oncol-2016-update", name: "Cobimetinib combined with vemurafenib in advanced BRAF(V600)-mutant melanoma (coBRIM): updated efficacy results from a randomised, double-blind, phase 3 trial", tldr: "Later report from the coBRIM trial registered as NCT01689519, in The Lancet Oncology (2016); its title describes an updated or longer-term analysis.", summary: "Background: The combination of cobimetinib with vemurafenib improves progression-free survival compared with placebo and vemurafenib in previously untreated patients with BRAF(V600)-mutant advanced melanoma, as previously reported in the coBRIM study. In this Article, we report updated efficacy results, including overall survival and safety after longer follow-up, and selected biomarker correlative studies.\n\nMethods: In this double-blind, randomised, placebo-controlled, multicentre study, adult patients (aged ≥18 years) with histologically confirmed BRAF(V600) mutation-positive unresectable stage IIIC or stage IV melanoma were randomly assigned (1:1) using an interactive response system to receive cobimetinib (60 mg once daily for 21 days followed by a 7-day rest period in each 28-day cycle) or placebo, in combination with oral vemurafenib (960 mg twice daily). Progression-free and overall survival were primary and secondary endpoints, respectively; all analyses were done on the intention-to-treat population. This study is registered with ClinicalTrials.gov, number NCT01689519, and is ongoing but no longer recruiting participants.\n\nFindings: Between Jan 8, 2013, and Jan 31, 2014, 495 eligible adult patients were enrolled and randomly assigned to the cobimetinib plus vemurafenib group (n=247) or placebo plus vemurafenib group (n=248). At a median follow-up of 14·2 months (IQR 8·5-17·3), the updated investigator-assessed median progression-free survival was 12·3 months (95% CI 9·5-13·4) for cobimetinib and vemurafenib versus 7·2 months (5·6-7·5) for placebo and vemurafenib (HR 0·58 [95% CI 0·46-0·72], p<0·0001). The final analysis for overall survival occurred when 255 (52%) patients had died (Aug 28, 2015). Median overall survival was 22·3 months (95% CI 20·3-not estimable) for cobimetinib and vemurafenib versus 17·4 months (95% CI 15·0-19·8) for placebo and vemurafenib (HR 0·70, 95% CI 0·55-0·90; p=0·005). The safety profile for cobimetinib and vemurafenib was tolerable and manageable, and no new safety signals were observed with longer follow-up. The most common grade 3-4 adverse events occurring at a higher frequency in patients in the cobimetinib and vemurafenib group compared with the vemurafenib group were γ-glutamyl transferase increase (36 [15%] in the cobimetinib and vemurafenib group vs 25 [10%] in the placebo and vemurafenib group), blood creatine phosphokinase increase (30 [12%] vs one [<1%]), and alanine transaminase increase (28 [11%] vs 15 [6%]). Serious adverse events occurred in 92 patients (37%) in the cobimetinib and vemurafenib group and 69 patients (28%) in the vemurafenib group. Pyrexia (six patients [2%]) and dehydration (five patients [2%]) were the most common serious adverse events reported in the cobimetinib and vemurafenib group. A total of 259 patients have died: 117 (47%) in the cobimetinib and vemurafenib group and 142 (58%) in the vemurafenib group. The primary cause of death was disease progression in most patients: 109 (93%) of 117 in the cobimetinib and vemurafenib group and 133 (94%) of 142 in the vemurafenib group.\n\nInterpretation: These data confirm the clinical benefit of cobimetinib combined with vemurafenib and support the use of the combination as a standard first-line approach to improve survival in patients with advanced BRAF(V600)-mutant melanoma.\n\nFunding: F Hoffmann-La Roche-Genentech.\n\nIndexed on Europe PMC as PubMed record 27480103 (DOI 10.1016/s1470-2045(16)30122-x). Its abstract cites the registry id NCT01689519, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2016, doi: "10.1016/s1470-2045(16)30122-x", pmid: "27480103", authors: "Ascierto PA, McArthur GA, Dréno B, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the coBRIM trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2016","url":"https://doi.org/10.1016/s1470-2045(16)30122-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/27480103/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/27480103"},{"label":"ClinicalTrials.gov NCT01689519","url":"https://clinicaltrials.gov/study/NCT01689519"}], tags: ["europepmc-ingest"], trials: ["cobrim"], journals: ["lancet-oncology"] }),
  p({ id: "paper-columbus-lancet-oncol-2018-update", name: "Overall survival in patients with BRAF-mutant melanoma receiving encorafenib plus binimetinib versus vemurafenib or encorafenib (COLUMBUS): a multicentre, open-label, randomised, phase 3 trial", tldr: "Later report from the COLUMBUS trial registered as NCT01909453, in The Lancet Oncology (2018); its title describes an updated or longer-term analysis.", summary: "Background: Encorafenib plus binimetinib and encorafenib alone improved progression-free survival compared with vemurafenib in patients with BRAF V600 -mutant melanoma in the COLUMBUS trial. Here, we report the results of the secondary endpoint of overall survival.\n\nMethods: COLUMBUS was a two-part, randomised, open-label, phase 3 study done at 162 hospitals in 28 countries. Eligible patients were aged at least 18 years with histologically confirmed, locally advanced, unresectable, or metastatic cutaneous melanoma, or unknown primary melanoma, BRAF V600E or BRAF V600K mutation, an Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1, and were treatment naive or had progressed on or after first-line immunotherapy. In part 1 of the study, patients were randomly assigned (1:1:1) by use of interactive response technology to receive oral encorafenib 450 mg once daily plus oral binimetinib 45 mg twice daily (encorafenib plus binimetinib group), oral encorafenib 300 mg once daily (encorafenib group), or oral vemurafenib 960 mg twice daily (vemurafenib group). Randomisation was stratified by the American Joint Committee on Cancer stage, ECOG performance status, and BRAF mutation status. The primary outcome of the trial, progression-free survival with encorafenib plus binimetinib versus vemurafenib, was reported previously. Here we present the prespecified interim overall survival analysis. Efficacy analyses were by intent to treat. Safety was analysed in patients who received at least one dose of study drug. Part 2 of the study was initiated at the request of the US Food and Drug Administration to better understand the contribution of binimetinib to the combination therapy by comparing encorafenib 300 mg once daily plus binimetinib 45 mg twice daily with encorafenib 300 mg once daily alone. Results of part 2 will be published separately. This trial is ongoing and is registered with ClinicalTrials.gov, number NCT01909453, and EudraCT, number 2013-001176-38.\n\nFindings: Between Dec 30, 2013, and April 10, 2015, 577 of 1345 screened patients were randomly assigned to receive encorafenib plus binimetinib (n=192), encorafenib (n=194), or vemurafenib (n=191). Median follow-up for overall survival was 36·8 months (95% CI 35·9-37·5). Median overall survival was 33·6 months (95% CI 24·4-39·2) with encorafenib plus binimetinib and 16·9 months (14·0-24·5) with vemurafenib (hazard ratio 0·61 [95% CI 0·47-0·79]; two-sided p<0·0001). The most common grade 3 or 4 adverse events did not change substantially from the first report; those seen in more than 5% of patients treated with encorafenib plus binimetinib were increased γ-glutamyltransferase (18 [9%] of 192 patients), increased blood creatine phosphokinase (14 [7%]), and hypertension (12 [6%]); those seen with encorafenib alone were palmar-plantar erythrodysaesthesia syndrome (26 [14%] of 192 patients), myalgia (19 [10%]), and arthralgia (18 [9%]); and with vemurafenib the most common grade 3 or 4 adverse event was arthralgia (11 [6%] of 186 patients). One death in the combination treatment group was considered by the investigator to be possibly related to treatment.\n\nInterpretation: The combination of encorafenib plus binimetinib provided clinically meaningful efficacy with good tolerability as shown by improvements in both progression-free survival and overall survival compared with vemurafenib. These data suggest that the combination of encorafenib plus binimetinib is likely to become an important therapeutic option in patients with BRAF V600 -mutant melanoma.\n\nFunding: Array BioPharma, Novartis.\n\nIndexed on Europe PMC as PubMed record 30219628 (DOI 10.1016/s1470-2045(18)30497-2). Its abstract cites the registry id NCT01909453, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2018, doi: "10.1016/s1470-2045(18)30497-2", pmid: "30219628", authors: "Dummer R, Ascierto PA, Gogas HJ, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the COLUMBUS trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2018","url":"https://doi.org/10.1016/s1470-2045(18)30497-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30219628/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30219628"},{"label":"ClinicalTrials.gov NCT01909453","url":"https://clinicaltrials.gov/study/NCT01909453"}], tags: ["europepmc-ingest"], trials: ["columbus"], journals: ["lancet-oncology"] }),
  p({ id: "paper-combi-ad-n-engl-j-med-2020-update", name: "Five-Year Analysis of Adjuvant Dabrafenib plus Trametinib in Stage III Melanoma", tldr: "Later report from the COMBI-AD trial registered as NCT01682083, in New England Journal of Medicine (2020); its title describes an updated or longer-term analysis.", summary: "Background: In the previously reported primary analysis of this phase 3 trial, 12 months of adjuvant dabrafenib plus trametinib resulted in significantly longer relapse-free survival than placebo in patients with resected stage III melanoma with BRAF V600E or V600K mutations. To confirm the stability of the relapse-free survival benefit, longer-term data were needed.\n\nMethods: We randomly assigned 870 patients who had resected stage III melanoma with BRAF V600E or V600K mutations to receive 12 months of oral dabrafenib (at a dose of 150 mg twice daily) plus trametinib (2 mg once daily) or two matched placebos. The primary end point was relapse-free survival. Here, we report 5-year results for relapse-free survival and survival without distant metastasis as the site of the first relapse. Overall survival was not analyzed, since the required number of events to trigger the final overall survival analysis had not been reached.\n\nResults: The minimum duration of follow-up was 59 months (median patient follow-up, 60 months for dabrafenib plus trametinib and 58 months for placebo). At 5 years, the percentage of patients who were alive without relapse was 52% (95% confidence interval [CI], 48 to 58) with dabrafenib plus trametinib and 36% (95% CI, 32 to 41) with placebo (hazard ratio for relapse or death, 0.51; 95% CI, 0.42 to 0.61). The percentage of patients who were alive without distant metastasis was 65% (95% CI, 61 to 71) with dabrafenib plus trametinib and 54% (95% CI, 49 to 60) with placebo (hazard ratio for distant metastasis or death, 0.55; 95% CI, 0.44 to 0.70). No clinically meaningful between-group difference in the incidence or severity of serious adverse events was reported during the follow-up period.\n\nConclusions: In the 5-year follow-up of a phase 3 trial involving patients who had resected stage III melanoma with BRAF V600E or V600K mutations, 12 months of adjuvant therapy with dabrafenib plus trametinib resulted in a longer duration of survival without relapse or distant metastasis than placebo with no apparent long-term toxic effects. (Funded by GlaxoSmithKline and Novartis; COMBI-AD ClinicalTrials.gov number, NCT01682083; EudraCT number, 2012-001266-15.).\n\nIndexed on Europe PMC as PubMed record 32877599 (DOI 10.1056/nejmoa2005493). Its abstract cites the registry id NCT01682083, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2020, doi: "10.1056/nejmoa2005493", pmid: "32877599", authors: "Dummer R, Hauschild A, Santinami M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the COMBI-AD trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"N Engl J Med 2020","url":"https://doi.org/10.1056/nejmoa2005493"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32877599/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32877599"},{"label":"ClinicalTrials.gov NCT01682083","url":"https://clinicaltrials.gov/study/NCT01682083"}], tags: ["europepmc-ingest"], trials: ["combi-ad"], journals: ["nejm"] }),
  p({ id: "paper-combi-d-n-engl-j-med-2014", name: "Combined BRAF and MEK inhibition versus BRAF inhibition alone in melanoma", tldr: "Published report from the COMBI-d trial registered as NCT01584648, in New England Journal of Medicine (2014), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Combined BRAF and MEK inhibition, as compared with BRAF inhibition alone, delays the emergence of resistance and reduces toxic effects in patients who have melanoma with BRAF V600E or V600K mutations.\n\nMethods: In this phase 3 trial, we randomly assigned 423 previously untreated patients who had unresectable stage IIIC or stage IV melanoma with a BRAF V600E or V600K mutation to receive a combination of dabrafenib (150 mg orally twice daily) and trametinib (2 mg orally once daily) or dabrafenib and placebo. The primary end point was progression-free survival. Secondary end points included overall survival, response rate, response duration, and safety. A preplanned interim overall survival analysis was conducted.\n\nResults: The median progression-free survival was 9.3 months in the dabrafenib-trametinib group and 8.8 months in the dabrafenib-only group (hazard ratio for progression or death in the dabrafenib-trametinib group, 0.75; 95% confidence interval [CI], 0.57 to 0.99; P=0.03). The overall response rate was 67% in the dabrafenib-trametinib group and 51% in the dabrafenib-only group (P=0.002). At 6 months, the interim overall survival rate was 93% with dabrafenib-trametinib and 85% with dabrafenib alone (hazard ratio for death, 0.63; 95% CI, 0.42 to 0.94; P=0.02). However, a specified efficacy-stopping boundary (two-sided P=0.00028) was not crossed. Rates of adverse events were similar in the two groups, although more dose modifications occurred in the dabrafenib-trametinib group. The rate of cutaneous squamous-cell carcinoma was lower in the dabrafenib-trametinib group than in the dabrafenib-only group (2% vs. 9%), whereas pyrexia occurred in more patients (51% vs. 28%) and was more often severe (grade 3, 6% vs. 2%) in the dabrafenib-trametinib group.\n\nConclusions: A combination of dabrafenib and trametinib, as compared with dabrafenib alone, improved the rate of progression-free survival in previously untreated patients who had metastatic melanoma with BRAF V600E or V600K mutations. (Funded by GlaxoSmithKline; Clinical Trials.gov number, NCT01584648.).\n\nIndexed on Europe PMC as PubMed record 25265492 (DOI 10.1056/nejmoa1406037). Its abstract cites the registry id NCT01584648, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2014, doi: "10.1056/nejmoa1406037", pmid: "25265492", authors: "Long GV, Stroyakovskiy D, Gogas H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01584648 with the most citations, so it is the natural first reading for anyone following the COMBI-d trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2014","url":"https://doi.org/10.1056/nejmoa1406037"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/25265492/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/25265492"},{"label":"ClinicalTrials.gov NCT01584648","url":"https://clinicaltrials.gov/study/NCT01584648"}], tags: ["europepmc-ingest"], trials: ["combi-d"], journals: ["nejm"] }),
  p({ id: "paper-empower-cscc-1-lancet-oncol-2020", name: "Cemiplimab in locally advanced cutaneous squamous cell carcinoma: results from an open-label, phase 2, single-arm trial", tldr: "Published report from the EMPOWER-CSCC-1 trial registered as NCT02760498, in The Lancet Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Cemiplimab has shown substantial antitumour activity in patients with metastatic cutaneous squamous cell carcinoma. Patients with locally advanced cutaneous squamous cell carcinoma have poor prognosis with conventional systemic therapy. We present a primary analysis of the safety and antitumour activity of cemiplimab in patients with locally advanced cutaneous squamous cell carcinoma.\n\nMethods: This pivotal open-label, phase 2, single-arm trial was done across 25 outpatient clinics, primarily at academic medical centres, in Australia, Germany, and the USA. Eligible patients (aged ≥18 years with histologically confirmed locally advanced cutaneous squamous cell carcinoma and an Eastern Cooperative Oncology Group performance status of 0-1) received cemiplimab 3 mg/kg intravenously over 30 min every 2 weeks for up to 96 weeks. Tumour measurements were done every 8 weeks. The primary endpoint was objective response, defined as the proportion of patients with complete or partial response, according to independent central review as per Response Evaluation Criteria in Solid Tumors version 1.1 for radiological scans and WHO criteria for medical photography. Data cutoff was Oct 10, 2018, when the fully enrolled cohort reached the prespecified timepoint for the primary analysis. Analyses were done as per the intention-to-treat principle. The safety analysis comprised all patients who received at least one dose of cemiplimab. This study is registered with ClinicalTrials.gov, number NCT02760498.\n\nFindings: Between June 14, 2016, and April 25, 2018, 78 patients were enrolled and treated with cemiplimab. The median duration of study follow-up was 9·3 months (IQR 5·1-15·7) at the time of data cutoff. An objective response was observed in 34 (44%; 95% CI 32-55) of 78 patients. The best overall response was ten (13%) patients with a complete response and 24 (31%) with a partial response. Grade 3-4 treatment-emergent adverse events occurred in 34 (44%) of 78 patients; the most common were hypertension in six (8%) patients and pneumonia in four (5%). Serious treatment-emergent adverse events occurred in 23 (29%) of 78 patients. One treatment-related death was reported that occurred after onset of aspiration pneumonia.\n\nInterpretation: Cemiplimab showed antitumour activity and an acceptable safety profile in patients with locally advanced cutaneous squamous cell carcinoma for whom there was no widely accepted standard of care.\n\nFunding: Regeneron Pharmaceuticals and Sanofi.\n\nIndexed on Europe PMC as PubMed record 31952975 (DOI 10.1016/s1470-2045(19)30728-4). Its abstract cites the registry id NCT02760498, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2020, doi: "10.1016/s1470-2045(19)30728-4", pmid: "31952975", authors: "Migden MR, Khushalani NI, Chang ALS, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02760498 with the most citations, so it is the natural first reading for anyone following the EMPOWER-CSCC-1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2020","url":"https://doi.org/10.1016/s1470-2045(19)30728-4"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31952975/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31952975"},{"label":"ClinicalTrials.gov NCT02760498","url":"https://clinicaltrials.gov/study/NCT02760498"}], tags: ["europepmc-ingest"], trials: ["empower-cscc-1"], journals: ["lancet-oncology"] }),
  p({ id: "paper-empower-cscc-1-j-am-acad-dermatol-2025-update", name: "A phase 2 open-label study of cemiplimab in patients with advanced cutaneous squamous cell carcinoma (EMPOWER-CSCC-1): Final long-term analysis of groups 1, 2, and 3, and primary analysis of fixed-dose treatment group 6", tldr: "Later report from the EMPOWER-CSCC-1 trial registered as NCT02760498, in Journal of the American Academy of Dermatology (2025); its title describes an updated or longer-term analysis.", summary: "Background: In the phase 2 EMPOWER-CSCC-1 study (NCT02760498), cemiplimab demonstrated antitumor activity against metastatic cutaneous squamous cell carcinoma (mCSCC) and locally advanced cutaneous squamous cell carcinoma (laCSCC).\n\nObjectives: To report final analysis of weight-based cemiplimab in mCSCC and laCSCC (groups 1 and 2), fixed-dose cemiplimab in mCSCC (group 3), and primary analysis of fixed-dose cemiplimab in mCSCC/laCSCC (group 6).\n\nMethods: Patients received cemiplimab (3 mg/kg intravenously every 2 weeks [groups 1 and 2]) or cemiplimab (350 mg intravenously [groups 3 and 6]) every 3 weeks. The primary end point was objective response rate (ORR). Duration of response (DOR) and progression-free survival (PFS) are presented per protocol, according to post-hoc sensitivity analyses that only include the period of protocol-mandated imaging assessments.\n\nResults: At 42.5 months, ORR for groups 1-3 (n = 193) was 47.2%, estimated 12-month DOR was 88.3%, and median PFS was 26.0 months. At 8.7 months, ORR for group 6 (n = 165 patients) was 44.8%; median DOR and median PFS were not reached. Serious treatment-emergent adverse event rates (grade ≥3) were groups 1-3: 31.1% and group 6: 34.5%.\n\nLimitations: Nonrandomized study, nonsurvival primary end point.\n\nConclusion: EMPOWER-CSCC-1 provides the largest prospective data on long-term efficacy and safety for anti-programmed cell death-1 therapy in advanced CSCC.\n\nIndexed on Europe PMC as PubMed record 39245360 (DOI 10.1016/j.jaad.2024.06.108). Its abstract cites the registry id NCT02760498, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of the American Academy of Dermatology", year: 2025, doi: "10.1016/j.jaad.2024.06.108", pmid: "39245360", authors: "Hughes BGM, Guminski A, Bowyer S, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the EMPOWER-CSCC-1 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Am Acad Dermatol 2025","url":"https://doi.org/10.1016/j.jaad.2024.06.108"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39245360/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39245360"},{"label":"ClinicalTrials.gov NCT02760498","url":"https://clinicaltrials.gov/study/NCT02760498"}], tags: ["europepmc-ingest"], trials: ["empower-cscc-1"] }),
  p({ id: "paper-erivance-bmc-cancer-2017-update", name: "Long-term safety and efficacy of vismodegib in patients with advanced basal cell carcinoma: final update of the pivotal ERIVANCE BCC study", tldr: "Later report from the ERIVANCE BCC trial registered as NCT00833417, in BMC cancer (2017); its title describes an updated or longer-term analysis.", summary: "Background: In the primary analysis of the ERIVANCE BCC trial, vismodegib, the first US Food and Drug Administration-approved Hedgehog pathway inhibitor, showed objective response rates (ORRs) by independent review facility (IRF) of 30% and 43% in metastatic basal cell carcinoma (mBCC) and locally advanced BCC (laBCC), respectively. ORRs by investigator review were 45% (mBCC) and 60% (laBCC). Herein, we present long-term safety and final investigator-assessed efficacy results in patients with mBCC or laBCC.\n\nMethods: One hundred four patients with measurable advanced BCC received oral vismodegib 150 mg once daily until disease progression or intolerable toxicity. The primary end point was IRF-assessed ORR. Secondary end points included ORR, duration of response (DOR), progression-free survival, overall survival (OS), and safety.\n\nResults: At data cutoff (39 months after completion of accrual), 8 patients were receiving the study drug (69 patients in survival follow-up). Investigator-assessed ORR was 48.5% in the mBCC group (all partial responses) and 60.3% in the laBCC group (20 patients had complete response and 18 patients had partial response). ORRs were comparable across patient subgroups, including aggressive histologic subtypes (eg, infiltrative BCC). Median DOR was 14.8 months (mBCC) and 26.2 months (laBCC). Median OS was 33.4 months in the mBCC cohort and not estimable in the laBCC cohort. Adverse events remained consistent with clinical experience. Thirty-three deaths (31.7%) were reported; none were related to vismodegib.\n\nConclusions: This long-term update of the ERIVANCE BCC trial demonstrated durability of response, efficacy across patient subgroups, and manageable long-term safety of vismodegib in patients with advanced BCC.\n\nTrial registration: This study was registered prospectively with Clinicaltrials.gov, number NCT00833417 on January 30, 2009.\n\nIndexed on Europe PMC as PubMed record 28511673 (DOI 10.1186/s12885-017-3286-5). Its abstract cites the registry id NCT00833417, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "BMC cancer", year: 2017, doi: "10.1186/s12885-017-3286-5", pmid: "28511673", authors: "Sekulic A, Migden MR, Basset-Seguin N, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the ERIVANCE BCC trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"BMC Cancer 2017","url":"https://doi.org/10.1186/s12885-017-3286-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28511673/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28511673"},{"label":"ClinicalTrials.gov NCT00833417","url":"https://clinicaltrials.gov/study/NCT00833417"}], tags: ["europepmc-ingest"], trials: ["erivance"], journals: ["bmc-cancer"] }),
  p({ id: "paper-imcgp100-202-n-engl-j-med-2021", name: "Overall Survival Benefit with Tebentafusp in Metastatic Uveal Melanoma", tldr: "Published report from the IMCgp100-202 trial registered as NCT03070392, in New England Journal of Medicine (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Uveal melanoma is a disease that is distinct from cutaneous melanoma, with a low tumor mutational burden and a 1-year overall survival of approximately 50% in patients with metastatic uveal melanoma. Data showing a proven overall survival benefit with a systemic treatment are lacking. Tebentafusp is a bispecific protein consisting of an affinity-enhanced T-cell receptor fused to an anti-CD3 effector that can redirect T cells to target glycoprotein 100-positive cells.\n\nMethods: In this open-label, phase 3 trial, we randomly assigned previously untreated HLA-A*02:01-positive patients with metastatic uveal melanoma in a 2:1 ratio to receive tebentafusp (tebentafusp group) or the investigator's choice of therapy with single-agent pembrolizumab, ipilimumab, or dacarbazine (control group), stratified according to the lactate dehydrogenase level. The primary end point was overall survival.\n\nResults: A total of 378 patients were randomly assigned to either the tebentafusp group (252 patients) or the control group (126 patients). Overall survival at 1 year was 73% in the tebentafusp group and 59% in the control group (hazard ratio for death, 0.51; 95% confidence interval [CI], 0.37 to 0.71; P<0.001) in the intention-to-treat population. Progression-free survival was also significantly higher in the tebentafusp group than in the control group (31% vs. 19% at 6 months; hazard ratio for disease progression or death, 0.73; 95% CI, 0.58 to 0.94; P = 0.01). The most common treatment-related adverse events in the tebentafusp group were cytokine-mediated events (due to T-cell activation) and skin-related events (due to glycoprotein 100-positive melanocytes), including rash (83%), pyrexia (76%), and pruritus (69%). These adverse events decreased in incidence and severity after the first three or four doses and infrequently led to discontinuation of the trial treatment (2%). No treatment-related deaths were reported.\n\nConclusions: Treatment with tebentafusp resulted in longer overall survival than the control therapy among previously untreated patients with metastatic uveal melanoma. (Funded by Immunocore; ClinicalTrials.gov number, NCT03070392; EudraCT number, 2015-003153-18.).\n\nIndexed on Europe PMC as PubMed record 34551229 (DOI 10.1056/nejmoa2103485). Its abstract cites the registry id NCT03070392, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2021, doi: "10.1056/nejmoa2103485", pmid: "34551229", authors: "Nathan P, Hassel JC, Rutkowski P, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03070392 with the most citations, so it is the natural first reading for anyone following the IMCgp100-202 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2021","url":"https://doi.org/10.1056/nejmoa2103485"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34551229/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34551229"},{"label":"ClinicalTrials.gov NCT03070392","url":"https://clinicaltrials.gov/study/NCT03070392"}], tags: ["europepmc-ingest"], trials: ["imcgp100-202"], journals: ["nejm"] }),
  p({ id: "paper-imcgp100-202-n-engl-j-med-2023-update", name: "Three-Year Overall Survival with Tebentafusp in Metastatic Uveal Melanoma", tldr: "Later report from the IMCgp100-202 trial registered as NCT03070392, in New England Journal of Medicine (2023); its title describes an updated or longer-term analysis.", summary: "Background: Tebentafusp, a T-cell receptor-bispecific molecule that targets glycoprotein 100 and CD3, is approved for adult patients who are positive for HLA-A*02:01 and have unresectable or metastatic uveal melanoma. The primary analysis in the present phase 3 trial supported a long-term survival benefit associated with the drug.\n\nMethods: We report the 3-year efficacy and safety results from our open-label, phase 3 trial in which HLA-A*02:01-positive patients with previously untreated metastatic uveal melanoma were randomly assigned in a 2:1 ratio to receive tebentafusp (tebentafusp group) or the investigator's choice of therapy with pembrolizumab, ipilimumab, or dacarbazine (control group), with randomization stratified according to the lactate dehydrogenase level. The primary end point was overall survival.\n\nResults: At a minimum follow-up of 36 months, median overall survival was 21.6 months in the tebentafusp group and 16.9 months in the control group (hazard ratio for death, 0.68; 95% confidence interval, 0.54 to 0.87). The estimated percentage of patients surviving at 3 years was 27% in the tebentafusp group and 18% in the control group. The most common treatment-related adverse events of any grade in the tebentafusp group were rash (83%), pyrexia (76%), pruritus (70%), and hypotension (38%). Most tebentafusp-related adverse events occurred early during treatment, and no new adverse events were observed with long-term administration. The percentage of patients who discontinued treatment because of adverse events continued to be low in both treatment groups (2% in the tebentafusp group and 5% in the control group). No treatment-related deaths occurred.\n\nConclusions: This 3-year analysis supported a continued long-term benefit of tebentafusp for overall survival among adult HLA-A*02:01-positive patients with previously untreated metastatic uveal melanoma. (Funded by Immunocore; IMCgp100-202 ClinicalTrials.gov number, NCT03070392; EudraCT number, 2015-003153-18.).\n\nIndexed on Europe PMC as PubMed record 37870955 (DOI 10.1056/nejmoa2304753). Its abstract cites the registry id NCT03070392, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2304753", pmid: "37870955", authors: "Hassel JC, Piperno-Neumann S, Rutkowski P, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the IMCgp100-202 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2304753"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37870955/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37870955"},{"label":"ClinicalTrials.gov NCT03070392","url":"https://clinicaltrials.gov/study/NCT03070392"}], tags: ["europepmc-ingest"], trials: ["imcgp100-202"], journals: ["nejm"] }),
  p({ id: "paper-imspire150-lancet-2020", name: "Atezolizumab, vemurafenib, and cobimetinib as first-line treatment for unresectable advanced BRAF V600 mutation-positive melanoma (IMspire150): primary analysis of the randomised, double-blind, placebo-controlled, phase 3 trial", tldr: "Published report from the IMspire150 trial registered as NCT02908672, in The Lancet (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: IMspire150 aimed to evaluate first-line combination treatment with BRAF plus MEK inhibitors and immune checkpoint therapy in BRAF V600 mutation-positive advanced or metastatic melanoma.\n\nMethods: IMspire150 was a randomised, double-blind, placebo-controlled phase 3 study done at 112 institutes in 20 countries. Patients with unresectable stage IIIc-IV, BRAF V600 mutation-positive melanoma were randomly assigned 1:1 to 28-day cycles of atezolizumab, vemurafenib, and cobimetinib (atezolizumab group) or atezolizumab placebo, vemurafenib, and cobimetinib (control group). In cycle 1, all patients received vemurafenib and cobimetinib only; atezolizumab placebo was added from cycle 2 onward. Randomisation was stratified by lactate dehydrogenase concentration and geographical region. Blinding for atezolizumab was achieved by means of an identical intravenous placebo, and blinding for vemurafenib was achieved by means of a placebo tablet. The primary outcome was investigator-assessed progression-free survival. This trial (ClinicalTrials.gov, NCT02908672) is ongoing but no longer recruiting patients.\n\nFindings: Between Jan 13, 2017, and April 26, 2018, 777 patients were screened and 514 were enrolled and randomly assigned to the atezolizumab group (n=256) or control group (n=258). At a median follow-up of 18·9 months (IQR 10·4-23·8), progression-free survival as assessed by the study investigator was significantly prolonged with atezolizumab versus control (15·1 vs 10·6 months; hazard ratio [HR] 0·78; 95% CI 0·63-0·97; p=0·025). Common treatment-related adverse events (>30%) in the atezolizumab and control groups were blood creatinine phosphokinase increased (51·3% vs 44·8%), diarrhoea (42·2% vs 46·6%), rash (40·9%, both groups), arthralgia (39·1% vs 28·1%), pyrexia (38·7% vs 26·0%), alanine aminotransferase increased (33·9% vs 22·8%), and lipase increased (32·2% vs 27·4%); 13% of patients in the atezolizumab group and 16% in the control group stopped all treatment because of adverse events.\n\nInterpretation: The addition of atezolizumab to targeted therapy with vemurafenib and cobimetinib was safe and tolerable and significantly increased progression-free survival in patients with BRAF V600 mutation-positive advanced melanoma.\n\nFunding: F Hoffmann-La Roche and Genentech.\n\nIndexed on Europe PMC as PubMed record 32534646 (DOI 10.1016/s0140-6736(20)30934-x). Its abstract cites the registry id NCT02908672, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2020, doi: "10.1016/s0140-6736(20)30934-x", pmid: "32534646", authors: "Gutzmer R, Stroyakovskiy D, Gogas H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02908672 with the most citations, so it is the natural first reading for anyone following the IMspire150 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2020","url":"https://doi.org/10.1016/s0140-6736(20)30934-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32534646/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32534646"},{"label":"ClinicalTrials.gov NCT02908672","url":"https://clinicaltrials.gov/study/NCT02908672"}], tags: ["europepmc-ingest"], trials: ["imspire150"], journals: ["lancet"] }),
  p({ id: "paper-imspire150-lancet-oncol-2023-update", name: "Overall survival with first-line atezolizumab in combination with vemurafenib and cobimetinib in BRAF V600 mutation-positive advanced melanoma (IMspire150): second interim analysis of a multicentre, randomised, phase 3 study", tldr: "Later report from the IMspire150 trial registered as NCT02908672, in The Lancet Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Background: Primary analysis of the phase 3 IMspire150 study showed improved investigator-assessed progression-free survival with first-line atezolizumab, vemurafenib, and cobimetinib (atezolizumab group) versus placebo, vemurafenib, and cobimetinib (control group) in patients with BRAF V600 mutation-positive melanoma. With a median follow-up of 18·9 months (IQR 10·4-23·8) at the primary analysis, overall survival data were immature. Here, we report the results from the second, prespecified, interim overall survival analysis.\n\nMethods: The multicentre, double-blind, placebo-controlled, randomised, phase 3 IMspire150 study was done at 108 academic and community hospitals in 20 countries. Patients aged 18 years or older with previously untreated unresectable stage IIIc or stage IV melanoma and an Eastern Cooperative Oncology Group performance status of 0 or 1 were eligible for inclusion. Patients were randomly assigned (1:1) to receive either atezolizumab (840 mg intravenously on day 1 and 15) or placebo plus vemurafenib (960 mg or 720 mg twice daily orally) and cobimetinib (60 mg once daily orally; 21 days on and 7 days off) in 28-day cycles. Atezolizumab and placebo were added to treatment regimens from cycle two onwards. Randomisation was done centrally (Durham, NC, USA) based on a permuted block randomisation scheme (block size of 4) using an interactive web-based response system and was stratified by geographical region and baseline lactate dehydrogenase concentration. Overall survival was analysed in the intention-to-treat population and safety was analysed in all patients who received at least one dose of study drug according to actual treatment received. The primary endpoint was investigator-assessed progression-free survival, which was previously reported. Here, we report the second, prespecified, interim overall survival analysis, which was planned after about 270 overall survival events had occurred. The trial is ongoing, but is no longer enrolling patients, and it is registered with ClinicalTrials.gov, NCT02908672.\n\nFindings: Between Jan 13, 2017, and April 26, 2018, 514 patients (median age 54 years [IQR 43-63]; 299 [58%] men and 215 [42%] women) were enrolled in the trial and randomly assigned to the atezolizumab group (256 [50%] patients) or the control group (258 [50%] patients). At the data cutoff (Sept 8, 2021), 273 patients had died (126 in the atezolizumab group and 147 in the control group). Median follow-up was 29·1 months (IQR 10·1-45·4) for the atezolizumab group versus 22·8 months (10·6-44·1) for the control group. Median overall survival was 39·0 months (95% CI 29·9-not estimable) in the atezolizumab group versus 25·8 months (22·0-34·6) in the control group (HR 0·84 [95% CI 0·66-1·06]; p=0·14). The most common adverse events of any grade in the atezolizumab group were blood creatine phosphokinase increased (123 [53%] of 231 patients), diarrhoea (116 [50%]), and pyrexia (115 [50%]). The most common adverse events of any grade in the control group were diarrhoea (157 [56%] of 280 patients), blood creatine phosphokinase increased (135 [48%]), and rash (119 [43%]). The most common grade 3-4 adverse events were increased lipase (54 [23%] of 231 patients in the atezolizumab group vs 62 [22%] of 280 patients in the control group), increased blood creatine phosphokinase (51 [22%] vs 50 [18%]), and increased alanine aminotransferase (32 [14%] vs 26 [9%]). Serious adverse events were reported in 112 (48%) patients in the atezolizumab group and 117 (42%) patients in the control group. Grade 5 adverse events were reported in eight (3%) patients in the atezolizumab group versus six (2%) patients in the control group. Two grade 5 adverse events (hepatitis fulminant and hepatic failure) in the atezolizumab group were considered to be associated with the triplet combination, and one event in the control group (pulmonary haemorrhage) was considered to be associated with cobimetinib.\n\nInterpretation: Additional follow-up of the IMspire150 trial showed that overall survival was not significantly improved with atezolizumab, vemurafenib, and cobimetinib compared with placebo, vemurafenib, and cobimetinib in patients with BRAF V600 mutation-positive advanced melanoma. Results of the final analysis are awaited to establish whether a significant improvement in overall survival can be achieved with long-term treatment with this triplet combination versus vemurafenib plus cobimetinib.\n\nFunding: F Hoffmann-La Roche.\n\nIndexed on Europe PMC as PubMed record 36460017 (DOI 10.1016/s1470-2045(22)00687-8). Its abstract cites the registry id NCT02908672, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2023, doi: "10.1016/s1470-2045(22)00687-8", pmid: "36460017", authors: "Ascierto PA, Stroyakovskiy D, Gogas H, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the IMspire150 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2023","url":"https://doi.org/10.1016/s1470-2045(22)00687-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36460017/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36460017"},{"label":"ClinicalTrials.gov NCT02908672","url":"https://clinicaltrials.gov/study/NCT02908672"}], tags: ["europepmc-ingest"], trials: ["imspire150"], journals: ["lancet-oncology"] }),
  p({ id: "paper-javelin-merkel-200-lancet-oncol-2016", name: "Avelumab in patients with chemotherapy-refractory metastatic Merkel cell carcinoma: a multicentre, single-group, open-label, phase 2 trial", tldr: "Published report from the JAVELIN Merkel 200 trial registered as NCT02155647, in The Lancet Oncology (2016), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Merkel cell carcinoma is a rare, aggressive skin cancer with poor prognosis in patients with advanced disease. Current standard care uses various cytotoxic chemotherapy regimens, but responses are seldom durable. Tumour oncogenesis is linked to Merkel cell polyomavirus integration and ultraviolet-radiation-induced mutations, providing rationale for treatment with immunotherapy antibodies that target the PD-L1/PD-1 pathway. We assessed treatment with avelumab, an anti-PD-L1 monoclonal antibody, in patients with stage IV Merkel cell carcinoma that had progressed after cytotoxic chemotherapy.\n\nMethods: In this multicentre, international, prospective, single-group, open-label, phase 2 trial, patients with stage IV chemotherapy-refractory, histologically confirmed Merkel cell carcinoma (aged ≥18 years) were enrolled from 35 cancer treatment centres and academic hospitals in North America, Europe, Australia, and Asia. Key eligibility criteria were an ECOG performance status of 0 or 1, measurable disease by Response Evaluation Criteria in Solid Tumors (RECIST) version 1.1, adequate haematological, hepatic, and renal function, and immune-competent status (patients with HIV, immunosuppression, haematological malignancies, and previous organ transplantation were excluded). Patient selection was not based on PD-L1 expression or Merkel cell polyomavirus status. Collection of biopsy material or use of archival tissue for these assessments was mandatory. Avelumab was given intravenously at a dose of 10 mg/kg every 2 weeks. The primary endpoint was confirmed objective response (complete response or partial response) assessed according to RECIST version 1.1 by an independent review committee. Safety and clinical activity were assessed in all patients who received at least one dose of study drug (the modified intention-to-treat population). This trial is registered with ClinicalTrials.gov as NCT02155647.\n\nFindings: Between July 25, 2014, and Sept 3, 2015, 88 patients were enrolled and received at least one dose of avelumab. Patients were followed up for a median of 10·4 months (IQR 8·6-13·1). The proportion of patients who achieved an objective response was 28 (31·8% [95·9% CI 21·9-43·1]) of 88 patients, including eight complete responses and 20 partial responses. Responses were ongoing in 23 (82%) of 28 patients at the time of analysis. Five grade 3 treatment-related adverse events occurred in four (5%) patients: lymphopenia in two patients, blood creatine phosphokinase increase in one patient, aminotransferase increase in one patient, and blood cholesterol increase in one patient; there were no treatment-related grade 4 adverse events or treatment-related deaths. Serious treatment-related adverse events were reported in five patients (6%): enterocolitis, infusion-related reaction, aminotransferases increased, chondrocalcinosis, synovitis, and interstitial nephritis (n=1 each).\n\nInterpretation: Avelumab was associated with durable responses, most of which are still ongoing, and was well tolerated; hence, avelumab represents a new therapeutic option for advanced Merkel cell carcinoma.\n\nFunding: Merck KGaA, Darmstadt, Germany.\n\nIndexed on Europe PMC as PubMed record 27592805 (DOI 10.1016/s1470-2045(16)30364-3). Its abstract cites the registry id NCT02155647, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2016, doi: "10.1016/s1470-2045(16)30364-3", pmid: "27592805", authors: "Kaufman HL, Russell J, Hamid O, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02155647 with the most citations, so it is the natural first reading for anyone following the JAVELIN Merkel 200 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2016","url":"https://doi.org/10.1016/s1470-2045(16)30364-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/27592805/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/27592805"},{"label":"ClinicalTrials.gov NCT02155647","url":"https://clinicaltrials.gov/study/NCT02155647"}], tags: ["europepmc-ingest"], trials: ["javelin-merkel-200"], journals: ["lancet-oncology"] }),
  p({ id: "paper-javelin-merkel-200-j-immunother-cancer-2018-update", name: "Updated efficacy of avelumab in patients with previously treated metastatic Merkel cell carcinoma after ≥1 year of follow-up: JAVELIN Merkel 200, a phase 2 clinical trial", tldr: "Later report from the JAVELIN Merkel 200 trial registered as NCT02155647, in Journal for ImmunoTherapy of Cancer (2018); its title describes an updated or longer-term analysis.", summary: "Background: Merkel cell carcinoma (MCC) is a rare, aggressive skin cancer associated with poor survival outcomes in patients with distant metastatic disease (mMCC). In an initial analysis from JAVELIN Merkel 200, a phase 2, prospective, open-label, single-arm trial in mMCC, avelumab-a human anti-programmed death-ligand 1 (PD-L1) monoclonal antibody-showed promising efficacy and a safety profile that was generally manageable and tolerable. Here, we report the efficacy of avelumab after ≥1 year of follow-up in patients with distant mMCC that had progressed following prior chemotherapy for metastatic disease.\n\nPatients and methods: Patients received avelumab 10 mg/kg by 1-h intravenous infusion every 2 weeks until confirmed disease progression, unacceptable toxicity, or withdrawal. The primary endpoint was best overall response. Secondary endpoints included duration of response (DOR), progression-free survival (PFS), and overall survival (OS).\n\nResults: Patients (N = 88) were followed for a minimum of 12 months. The confirmed objective response rate was 33.0% (95% CI, 23.3%-43.8%; complete response: 11.4%). An estimated 74% of responses lasted ≥1 year, and 72.4% of responses were ongoing at data cutoff. Responses were durable, with the median DOR not yet reached (95% CI, 18.0 months-not estimable), and PFS was prolonged; 1-year PFS and OS rates were 30% (95% CI, 21%-41%) and 52% (95% CI, 41%-62%), respectively. Median OS was 12.9 months (95% CI, 7.5-not estimable). Subgroup analyses suggested a higher probability of response in patients receiving fewer prior lines of systemic therapy, with a lower baseline disease burden, and with PD-L1-positive tumors; however, durable responses occurred irrespective of baseline factors, including tumor Merkel cell polyomavirus status.\n\nConclusions: With longer follow-up, avelumab continues to show durable responses and promising survival outcomes in patients with distant mMCC whose disease had progressed after chemotherapy.\n\nTrial registration: Clinicaltrials.gov identifier: NCT02155647.\n\nIndexed on Europe PMC as PubMed record 29347993 (DOI 10.1186/s40425-017-0310-x). Its abstract cites the registry id NCT02155647, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal for ImmunoTherapy of Cancer", year: 2018, doi: "10.1186/s40425-017-0310-x", pmid: "29347993", authors: "Kaufman HL, Russell JS, Hamid O, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the JAVELIN Merkel 200 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Immunother Cancer 2018","url":"https://doi.org/10.1186/s40425-017-0310-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/29347993/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/29347993"},{"label":"ClinicalTrials.gov NCT02155647","url":"https://clinicaltrials.gov/study/NCT02155647"}], tags: ["europepmc-ingest"], trials: ["javelin-merkel-200"], journals: ["jitc"] }),
  p({ id: "paper-keynote-017-n-engl-j-med-2016", name: "PD-1 Blockade with Pembrolizumab in Advanced Merkel-Cell Carcinoma", tldr: "Published report from the KEYNOTE-017 trial registered as NCT02267603, in New England Journal of Medicine (2016), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Merkel-cell carcinoma is an aggressive skin cancer that is linked to exposure to ultraviolet light and the Merkel-cell polyomavirus (MCPyV). Advanced Merkel-cell carcinoma often responds to chemotherapy, but responses are transient. Blocking the programmed death 1 (PD-1) immune inhibitory pathway is of interest, because these tumors often express PD-L1, and MCPyV-specific T cells express PD-1.\n\nMethods: In this multicenter, phase 2, noncontrolled study, we assigned adults with advanced Merkel-cell carcinoma who had received no previous systemic therapy to receive pembrolizumab (anti-PD-1) at a dose of 2 mg per kilogram of body weight every 3 weeks. The primary end point was the objective response rate according to Response Evaluation Criteria in Solid Tumors, version 1.1. Efficacy was correlated with tumor viral status, as assessed by serologic and immunohistochemical testing.\n\nResults: A total of 26 patients received at least one dose of pembrolizumab. The objective response rate among the 25 patients with at least one evaluation during treatment was 56% (95% confidence interval [CI], 35 to 76); 4 patients had a complete response, and 10 had a partial response. With a median follow-up of 33 weeks (range, 7 to 53), relapses occurred in 2 of the 14 patients who had had a response (14%). The response duration ranged from at least 2.2 months to at least 9.7 months. The rate of progression-free survival at 6 months was 67% (95% CI, 49 to 86). A total of 17 of the 26 patients (65%) had virus-positive tumors. The response rate was 62% among patients with MCPyV-positive tumors (10 of 16 patients) and 44% among those with virus-negative tumors (4 of 9 patients). Drug-related grade 3 or 4 adverse events occurred in 15% of the patients.\n\nConclusions: In this study, first-line therapy with pembrolizumab in patients with advanced Merkel-cell carcinoma was associated with an objective response rate of 56%. Responses were observed in patients with virus-positive tumors and those with virus-negative tumors. (Funded by the National Cancer Institute and Merck; ClinicalTrials.gov number, NCT02267603.).\n\nIndexed on Europe PMC as PubMed record 27093365 (DOI 10.1056/nejmoa1603702). Its abstract cites the registry id NCT02267603, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2016, doi: "10.1056/nejmoa1603702", pmid: "27093365", authors: "Nghiem PT, Bhatia S, Lipson EJ, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02267603 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-017 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2016","url":"https://doi.org/10.1056/nejmoa1603702"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/27093365/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/27093365"},{"label":"ClinicalTrials.gov NCT02267603","url":"https://clinicaltrials.gov/study/NCT02267603"}], tags: ["europepmc-ingest"], trials: ["keynote-017"], journals: ["nejm"] }),
  p({ id: "paper-keynote-017-j-immunother-cancer-2021-update", name: "Three-year survival, correlates and salvage therapies in patients receiving first-line pembrolizumab for advanced Merkel cell carcinoma", tldr: "Later report from the KEYNOTE-017 trial registered as NCT02267603, in Journal for ImmunoTherapy of Cancer (2021); its title describes an updated or longer-term analysis.", summary: "Background: Merkel cell carcinoma (MCC) is an aggressive skin cancer associated with poor survival. Programmed cell death-1 (PD-1) pathway inhibitors have shown high rates of durable tumor regression compared with chemotherapy for MCC. The current study was undertaken to assess baseline and on-treatment factors associated with MCC regression and 3-year survival, and to explore the effects of salvage therapies in patients experiencing initial non-response or tumor progression after response or stable disease following first-line pembrolizumab therapy on Cancer Immunotherapy Trials Network-09/KEYNOTE-017.\n\nMethods: In this multicenter phase II trial, 50 patients with advanced unresectable MCC received pembrolizumab 2 mg/kg every 3 weeks for ≤2 years. Patients were followed for a median of 31.8 months.\n\nResults: Overall response rate to pembrolizumab was 58% (complete response 30%+partial response 28%; 95% CI 43.2 to 71.8). Among 29 responders, the median response duration was not reached (NR) at 3 years (range 1.0+ to 51.8+ months). Median progression-free survival (PFS) was 16.8 months (95% CI 4.6 to 43.4) and the 3-year PFS was 39.1%. Median OS was NR; the 3-year OS was 59.4% for all patients and 89.5% for responders. Baseline Eastern Cooperative Oncology Group performance status of 0, greater per cent tumor reduction, completion of 2 years of treatment and low neutrophil-to-lymphocyte ratio were associated with response and longer survival. Among patients with initial disease progression or those who developed progression after response or stable disease, some had extended survival with subsequent treatments including chemotherapies and immunotherapies.\n\nConclusions: This study represents the longest available follow-up from any first-line anti-programmed death-(ligand) 1 (anti-PD-(L)1) therapy in MCC, confirming durable PFS and OS in a proportion of patients. After initial tumor progression or relapse following response, some patients receiving salvage therapies survived. Improving the management of anti-PD-(L)1-refractory MCC remains a challenge and a high priority.\n\nTrial registration number: NCT02267603.\n\nIndexed on Europe PMC as PubMed record 33879601 (DOI 10.1136/jitc-2021-002478). Its abstract cites the registry id NCT02267603, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal for ImmunoTherapy of Cancer", year: 2021, doi: "10.1136/jitc-2021-002478", pmid: "33879601", authors: "Nghiem P, Bhatia S, Lipson EJ, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the KEYNOTE-017 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Immunother Cancer 2021","url":"https://doi.org/10.1136/jitc-2021-002478"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33879601/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33879601"},{"label":"ClinicalTrials.gov NCT02267603","url":"https://clinicaltrials.gov/study/NCT02267603"}], tags: ["europepmc-ingest"], trials: ["keynote-017"], journals: ["jitc"] }),
  p({ id: "paper-keynote-716-lancet-oncol-2022-update", name: "Pembrolizumab versus placebo as adjuvant therapy in resected stage IIB or IIC melanoma (KEYNOTE-716): distant metastasis-free survival results of a multicentre, double-blind, randomised, phase 3 trial", tldr: "Later report from the KEYNOTE-716 trial registered as NCT03553836, in The Lancet Oncology (2022); its title describes an updated or longer-term analysis.", summary: "Background: Patients with stage IIB or IIC melanoma who undergo surgery alone are at a substantial risk for disease recurrence. Adjuvant pembrolizumab significantly improved recurrence-free survival versus placebo in stage IIB or IIC melanoma in the first interim analysis of the KEYNOTE-716 trial. Here, we report results from the secondary endpoint of distant metastasis-free survival (prespecified third interim analysis), and recurrence-free survival with longer follow-up.\n\nMethods: KEYNOTE-716 is a multicentre, double-blind, placebo-controlled, crossover or rechallenge, randomised, phase 3 trial done at 160 academic medical centres and hospitals across 16 countries. Eligible patients were aged 12 years and older with newly-diagnosed, completely resected, and histologically confirmed stage IIB (T3b or T4a) or IIC (T4b) cutaneous melanoma; negative sentinel lymph node biopsy; and an Eastern Cooperative Oncology Group performance status of 0-1. Patients were randomly assigned (1:1) to receive either 200 mg of pembrolizumab (2 mg/kg up to a maximum of 200 mg in paediatric patients) or placebo, both intravenously, every 3 weeks for 17 cycles (part 1) or until disease recurrence or unacceptable toxicity. Eligible patients with disease recurrence could receive further treatment with pembrolizumab in the part 2 crossover or rechallenge phase. Randomisation was done using an interactive response technology system and stratified by T category and paediatric status. The primary endpoint was investigator-assessed recurrence-free survival (assessed here with longer follow-up), and we report the prespecified third interim analysis of distant metastasis-free survival (secondary endpoint). Efficacy analyses were done in the intention-to-treat population (all patients who were randomly assigned, according to assigned group) and safety was assessed in all patients who were randomly assigned and received at least one dose of trial treatment, according to the treatment received. KEYNOTE-716 is registered at ClinicalTrials.gov, NCT03553836, and has completed recruitment.\n\nFindings: Between Sept 23, 2018, and Nov 4, 2020, 976 patients were randomly assigned to receive pembrolizumab (n=487) or placebo (n=489). At a median follow-up of 27·4 months (IQR 23·1-31·7), median distant metastasis-free survival was not reached (95% CI not reached [NR]-NR) in either group. Pembrolizumab significantly improved distant metastasis-free survival (hazard ratio [HR] 0·64, 95% CI 0·47-0·88, p=0·0029) versus placebo. Median recurrence-free survival was 37·2 months (95% CI NR-NR) in the pembrolizumab group and not reached in the placebo group (95% CI NR-NR). The risk of recurrence remained lower with pembrolizumab versus placebo (HR 0·64, 95% CI 0·50-0·84). The most common grade 3 or worse adverse events were hypertension (16 [3%] of 483 patients in the pembrolizumab group vs 17 [4%] of 486 patients in the placebo group), diarrhoea (eight [2%] vs one [<1%]), rash (seven [1%] vs two [<1%]), autoimmune hepatitis (seven [1%] vs two [<1%]), and increased lipase (six [1%] vs eight [2%]). Treatment-related serious adverse events occurred in 49 (10%) patients in the pembrolizumab group and 11 (2%) patients in the placebo group. No treatment-related deaths were reported.\n\nInterpretation: Adjuvant pembrolizumab is an efficacious treatment option for resected stage IIB and IIC melanoma, with significant improvement in distant-metastasis free survival versus placebo and continued reduction in the risk of recurrence with an adverse event profile consistent with previous studies of pembrolizumab. The overall benefit-risk of pembrolizumab continues to be positive in the adjuvant setting.\n\nFunding: Merck Sharp & Dohme, a subsidiary of Merck & Co.\n\nIndexed on Europe PMC as PubMed record 36265502 (DOI 10.1016/s1470-2045(22)00559-9). Its abstract cites the registry id NCT03553836, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2022, doi: "10.1016/s1470-2045(22)00559-9", pmid: "36265502", authors: "Long GV, Luke JJ, Khattak MA, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-716 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2022","url":"https://doi.org/10.1016/s1470-2045(22)00559-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36265502/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36265502"},{"label":"ClinicalTrials.gov NCT03553836","url":"https://clinicaltrials.gov/study/NCT03553836"}], tags: ["europepmc-ingest"], trials: ["keynote-716"], journals: ["lancet-oncology"] }),
  p({ id: "paper-relativity-047-nejm-evid-2023-update", name: "Overall Survival and Response with Nivolumab and Relatlimab in Advanced Melanoma", tldr: "Later report from the RELATIVITY-047 trial registered as NCT03470922, in NEJM Evidence (2023); its title describes an updated or longer-term analysis.", summary: "BACKGROUND: A phase 2/3 trial, A Study of Relatlimab Plus Nivolumab Versus Nivolumab Alone in Participants With Advanced Melanoma (RELATIVITY-047), evaluated nivolumab + relatlimab as a fixed-dose combination and found a significant progression-free survival (PFS) benefit over nivolumab monotherapy in previously untreated unresectable or metastatic melanoma. We now report updated PFS and safety data and the first results for overall survival (OS) and objective response rate (ORR). METHODS: Patients were randomly assigned 1:1 to receive nivolumab 480 mg and relatlimab 160 mg fixed-dose combination or nivolumab 480 mg alone, given intravenously every 4 weeks. PFS (primary end point) according to the Response Evaluation Criteria in Solid Tumors, version 1.1, was assessed by blinded independent central review (BICR). Secondary end points, tested hierarchically, were OS and then ORR per Response Evaluation Criteria in Solid Tumors, version 1.1, per BICR. RESULTS: At a median follow-up of 19.3 months, median PFS according to BICR was 10.2 months (95% confidence interval [CI], 6.5 to 14.8) with nivolumab + relatlimab versus 4.6 months (95% CI, 3.5 to 6.4) with nivolumab (hazard ratio, 0.78; 95% CI, 0.64 to 0.94). Median OS was not reached (NR) (95% CI, 34.2 to NR) with nivolumab + relatlimab versus 34.1 months (95% CI, 25.2 to NR) with nivolumab (hazard ratio, 0.80; 95% CI, 0.64 to 1.01; P=0.059) (prespecified value for statistical significance, P≤0.043). ORRs per BICR were 43.1% (95% CI, 37.9 to 48.4) versus 32.6% (95% CI, 27.8 to 37.7), respectively. Grade 3/4 treatment-related adverse events were observed in 21.1% of patients treated with nivolumab + relatlimab versus 11.1% treated with nivolumab. CONCLUSIONS: The fixed-dose combination of nivolumab + relatlimab showed consistent PFS benefit versus nivolumab with approximately 6 months of additional median follow-up. The combination treatment did not reach the preplanned statistical threshold for OS, with a 10.3 percentage-point difference in ORR. Grade 3/4 treatment-related adverse events were more frequent with nivolumab + relatlimab versus nivolumab. (Funded by Bristol Myers Squibb; ClinicalTrials.gov number, NCT03470922.)\n\nIndexed on Europe PMC as PubMed record 38320023 (DOI 10.1056/evidoa2200239). Its abstract cites the registry id NCT03470922, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "NEJM Evidence", year: 2023, doi: "10.1056/evidoa2200239", pmid: "38320023", authors: "Long GV, Stephen Hodi F, Lipson EJ, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the RELATIVITY-047 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"NEJM Evid 2023","url":"https://doi.org/10.1056/evidoa2200239"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38320023/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38320023"},{"label":"ClinicalTrials.gov NCT03470922","url":"https://clinicaltrials.gov/study/NCT03470922"}], tags: ["europepmc-ingest"], trials: ["relativity-047"], journals: ["nejm-evidence"] }),
  p({ id: "paper-relativity-098-nat-med-2025", name: "Adjuvant nivolumab and relatlimab in stage III/IV melanoma: the randomized phase 3 RELATIVITY-098 trial", tldr: "Published report from the RELATIVITY-098 trial registered as NCT05002569, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Based on RELATIVITY-047, nivolumab plus relatlimab is approved for advanced melanoma. Here, to address a current unmet need for more efficacious adjuvant regimens for completely resected melanoma, the phase 3, double-blind RELATIVITY-098 trial compared adjuvant nivolumab plus relatlimab to nivolumab after complete resection of stage III/IV melanoma. Patients were randomized 1:1 to receive nivolumab 480 mg plus relatlimab 160 mg (n = 547) or nivolumab 480 mg (n = 546) intravenously every 4 weeks for ≤1 year; safety populations totaled 543 and 545 patients, respectively. The primary endpoint was recurrence-free survival (RFS), and the key secondary was overall survival; translational endpoints were exploratory. There was no difference in RFS for nivolumab plus relatlimab versus nivolumab (hazard ratio = 1.01; 95% confidence interval: 0.83-1.22; P = 0.928); therefore, overall survival was not tested. Translational data across trials showed lower circulating LAG-3 + T cells in the adjuvant setting (RELATIVITY-098) versus advanced melanoma (RELATIVITY-047), where LAG-3 + T cells were enriched in tumor versus blood. The absence of macroscopic tumor and reduced peripheral LAG-3 + T cells may explain the lack of added benefit of nivolumab plus relatlimab over nivolumab in resected versus metastatic melanoma. ClinicalTrials.gov identifier: NCT05002569.\n\nIndexed on Europe PMC as PubMed record 41109920 (DOI 10.1038/s41591-025-04032-8). Its abstract cites the registry id NCT05002569, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-04032-8", pmid: "41109920", authors: "Long GV, Garnett-Benson C, Dolfi S, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05002569 with the most citations, so it is the natural first reading for anyone following the RELATIVITY-098 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-04032-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41109920/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41109920"},{"label":"ClinicalTrials.gov NCT05002569","url":"https://clinicaltrials.gov/study/NCT05002569"}], tags: ["europepmc-ingest"], trials: ["relativity-098"], journals: ["nature-medicine"] }),
  p({ id: "paper-swog-s1801-n-engl-j-med-2023", name: "Neoadjuvant-Adjuvant or Adjuvant-Only Pembrolizumab in Advanced Melanoma", tldr: "Published report from the SWOG S1801 trial registered as NCT03698019, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Whether pembrolizumab given both before surgery (neoadjuvant therapy) and after surgery (adjuvant therapy), as compared with pembrolizumab given as adjuvant therapy alone, would increase event-free survival among patients with resectable stage III or IV melanoma is unknown.\n\nMethods: In a phase 2 trial, we randomly assigned patients with clinically detectable, measurable stage IIIB to IVC melanoma that was amenable to surgical resection to three doses of neoadjuvant pembrolizumab, surgery, and 15 doses of adjuvant pembrolizumab (neoadjuvant-adjuvant group) or to surgery followed by pembrolizumab (200 mg intravenously every 3 weeks for a total of 18 doses) for approximately 1 year or until disease recurred or unacceptable toxic effects developed (adjuvant-only group). The primary end point was event-free survival in the intention-to-treat population. Events were defined as disease progression or toxic effects that precluded surgery; the inability to resect all gross disease; disease progression, surgical complications, or toxic effects of treatment that precluded the initiation of adjuvant therapy within 84 days after surgery; recurrence of melanoma after surgery; or death from any cause. Safety was also evaluated.\n\nResults: At a median follow-up of 14.7 months, the neoadjuvant-adjuvant group (154 patients) had significantly longer event-free survival than the adjuvant-only group (159 patients) (P = 0.004 by the log-rank test). In a landmark analysis, event-free survival at 2 years was 72% (95% confidence interval [CI], 64 to 80) in the neoadjuvant-adjuvant group and 49% (95% CI, 41 to 59) in the adjuvant-only group. The percentage of patients with treatment-related adverse events of grades 3 or higher during therapy was 12% in the neoadjuvant-adjuvant group and 14% in the adjuvant-only group.\n\nConclusions: Among patients with resectable stage III or IV melanoma, event-free survival was significantly longer among those who received pembrolizumab both before and after surgery than among those who received adjuvant pembrolizumab alone. No new toxic effects were identified. (Funded by the National Cancer Institute and Merck Sharp and Dohme; S1801 ClinicalTrials.gov number, NCT03698019.).\n\nIndexed on Europe PMC as PubMed record 36856617 (DOI 10.1056/nejmoa2211437). Its abstract cites the registry id NCT03698019, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2211437", pmid: "36856617", authors: "Patel SP, Othus M, Chen Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03698019 with the most citations, so it is the natural first reading for anyone following the SWOG S1801 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2211437"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36856617/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36856617"},{"label":"ClinicalTrials.gov NCT03698019","url":"https://clinicaltrials.gov/study/NCT03698019"}], tags: ["europepmc-ingest"], trials: ["swog-s1801"], journals: ["nejm"] }),
  p({ id: "paper-checkmate-358-j-clin-oncol-2019", name: "Safety and Efficacy of Nivolumab Monotherapy in Recurrent or Metastatic Cervical, Vaginal, or Vulvar Carcinoma: Results From the Phase I/II CheckMate 358 Trial", tldr: "Published report from the CheckMate 358 trial registered as NCT02488759, in Journal of Clinical Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Nivolumab was assessed in patients with virus-associated tumors in the phase I/II CheckMate 358 trial (ClinicalTrials.gov identifier: NCT02488759). We report on patients with recurrent/metastatic cervical, vaginal, or vulvar cancers.\n\nPatients and methods: Patients received nivolumab 240 mg every 2 weeks. Although patients with unknown human papillomavirus status were enrolled, patients known to have human papillomavirus-negative tumors were ineligible. The primary end point was objective response rate. Duration of response (DOR), progression-free survival, and overall survival were secondary end points. Safety and patient-reported outcomes were exploratory end points.\n\nResults: Twenty-four patients (cervical, n = 19; vaginal/vulvar, n = 5) were enrolled. Most patients had received prior systemic therapy for metastatic disease (cervical, 78.9%; vaginal/vulvar, 80.0%). Objective response rates were 26.3% (95% CI, 9.1 to 51.2) for cervical cancer and 20.0% (95% CI, 0.5 to 71.6) for vaginal/vulvar cancers. At a median follow-up of 19.2 months, median DOR was not reached (range, 23.3 to 29.5+ months; + indicates a censored observation) in the five responding patients in the cervical cohort; the DOR was 5.0 months in the single responding patient in the vaginal/vulvar cohort. Median overall survival was 21.9 months (95% CI, 15.1 months to not reached) among patients with cervical cancer. Any-grade treatment-related adverse events were reported in 12 of 19 patients (63.2%) in the cervical cohort and all five patients in the vaginal/vulvar cohort; there were no treatment-related deaths. In the cervical cohort, nivolumab treatment generally resulted in stabilization of patient-reported outcomes associated with health status and health-related quality of life.\n\nConclusion: The efficacy of nivolumab in patients with recurrent/metastatic cervical and vaginal or vulvar cancers is promising and warrants additional investigation. No new safety signals were identified with nivolumab treatment in this population.\n\nIndexed on Europe PMC as PubMed record 31487218 (DOI 10.1200/jco.19.00739). Its abstract cites the registry id NCT02488759, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2019, doi: "10.1200/jco.19.00739", pmid: "31487218", authors: "Naumann RW, Hollebecque A, Meyer T, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02488759 with the most citations, so it is the natural first reading for anyone following the CheckMate 358 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2019","url":"https://doi.org/10.1200/jco.19.00739"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31487218/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31487218"},{"label":"ClinicalTrials.gov NCT02488759","url":"https://clinicaltrials.gov/study/NCT02488759"}], tags: ["europepmc-ingest"], trials: ["checkmate-358"], journals: ["jco"] }),
  p({ id: "paper-mimic-01-nat-med-2023", name: "Fecal microbiota transplantation plus anti-PD-1 immunotherapy in advanced melanoma: a phase I trial", tldr: "Published report from the trial registered as NCT03772899, in Nature Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Fecal microbiota transplantation (FMT) represents a potential strategy to overcome resistance to immune checkpoint inhibitors in patients with refractory melanoma; however, the role of FMT in first-line treatment settings has not been evaluated. We conducted a multicenter phase I trial combining healthy donor FMT with the PD-1 inhibitors nivolumab or pembrolizumab in 20 previously untreated patients with advanced melanoma. The primary end point was safety. No grade 3 adverse events were reported from FMT alone. Five patients (25%) experienced grade 3 immune-related adverse events from combination therapy. Key secondary end points were objective response rate, changes in gut microbiome composition and systemic immune and metabolomics analyses. The objective response rate was 65% (13 of 20), including four (20%) complete responses. Longitudinal microbiome profiling revealed that all patients engrafted strains from their respective donors; however, the acquired similarity between donor and patient microbiomes only increased over time in responders. Responders experienced an enrichment of immunogenic and a loss of deleterious bacteria following FMT. Avatar mouse models confirmed the role of healthy donor feces in increasing anti-PD-1 efficacy. Our results show that FMT from healthy donors is safe in the first-line setting and warrants further investigation in combination with immune checkpoint inhibitors. ClinicalTrials.gov identifier NCT03772899.\n\nIndexed on Europe PMC as PubMed record 37414899 (DOI 10.1038/s41591-023-02453-x). Its abstract cites the registry id NCT03772899, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2023, doi: "10.1038/s41591-023-02453-x", pmid: "37414899", authors: "Routy B, Lenehan JG, Miller WH, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03772899 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2023","url":"https://doi.org/10.1038/s41591-023-02453-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37414899/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37414899"},{"label":"ClinicalTrials.gov NCT03772899","url":"https://clinicaltrials.gov/study/NCT03772899"}], tags: ["europepmc-ingest"], trials: ["mimic-01"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct02362594-lancet-oncol-2021-update", name: "Adjuvant pembrolizumab versus placebo in resected stage III melanoma (EORTC 1325-MG/KEYNOTE-054): distant metastasis-free survival results from a double-blind, randomised, controlled, phase 3 trial", tldr: "Later report from the KEYNOTE-054 trial registered as NCT02362594, in The Lancet Oncology (2021); its title describes an updated or longer-term analysis.", summary: "Background: The European Organisation for Research and Treatment of Cancer (EORTC) 1325/KEYNOTE-054 trial assessed pembrolizumab versus placebo in patients with resected high-risk stage III melanoma. At 15-month median follow-up, pembrolizumab improved recurrence-free survival (hazard ratio [HR] 0·57 [98·4% CI 0·43-0·74], p<0·0001) compared with placebo, leading to its approval in the USA and Europe. This report provides the final results for the secondary efficacy endpoint, distant metastasis-free survival and an update of the recurrence-free survival results.\n\nMethods: This double-blind, randomised, controlled, phase 3 trial was done at 123 academic centres and community hospitals across 23 countries. Patients aged 18 years or older with complete resection of cutaneous melanoma metastatic to lymph node, classified as American Joint Committee on Cancer staging system, seventh edition (AJCC-7) stage IIIA (at least one lymph node metastasis >1 mm), IIIB, or IIIC (without in-transit metastasis), and with an Eastern Cooperative Oncology Group performance status of 0 or 1 were eligible. Patients were randomly assigned (1:1) via a central interactive voice response system to receive intravenous pembrolizumab 200 mg or placebo every 3 weeks for up to 18 doses or until disease recurrence or unacceptable toxicity. Randomisation was stratified according to disease stage and region, using a minimisation technique, and clinical investigators, patients, and those collecting or analysing the data were masked to treatment assignment. The two coprimary endpoints were recurrence-free survival in the intention-to-treat (ITT) population and in patients with PD-L1-positive tumours. The secondary endpoint reported here was distant metastasis-free survival in the ITT and PD-L1-positive populations. This study is registered with ClinicalTrials.gov, NCT02362594, and EudraCT, 2014-004944-37.\n\nFindings: Between Aug 26, 2015, and Nov 14, 2016, 1019 patients were assigned to receive either pembrolizumab (n=514) or placebo (n=505). At an overall median follow-up of 42·3 months (IQR 40·5-45·9), 3·5-year distant metastasis-free survival was higher in the pembrolizumab group than in the placebo group in the ITT population (65·3% [95% CI 60·9-69·5] in the pembrolizumab group vs 49·4% [44·8-53·8] in the placebo group; HR 0·60 [95% CI 0·49-0·73]; p<0·0001). In the 853 patients with PD-L1-positive tumours, 3·5-year distant metastasis-free survival was 66·7% (95% CI 61·8-71·2) in the pembrolizumab group and 51·6% (46·6-56·4) in the placebo group (HR 0·61 [95% CI 0·49-0·76]; p<0·0001). Recurrence-free survival remained longer in the pembrolizumab group 59·8% (95% CI 55·3-64·1) than the placebo group 41·4% (37·0-45·8) at this 3·5-year follow-up in the ITT population (HR 0·59 [95% CI 0·49-0·70]) and in those with PD-L1-positive tumours 61·4% (56·3-66·1) in the pembrolizumab group and 44·1% (39·2-48·8) in the placebo group (HR 0·59 [95% CI 0·49-0·73]).\n\nInterpretation: Pembrolizumab adjuvant therapy provided a significant and clinically meaningful improvement in distant metastasis-free survival at a 3·5-year median follow-up, which was consistent with the improvement in recurrence-free survival. Therefore, the results of this trial support the indication to use adjuvant pembrolizumab therapy in patients with resected high risk stage III cutaneous melanoma.\n\nFunding: Merck Sharp & Dohme.\n\nIndexed on Europe PMC as PubMed record 33857412 (DOI 10.1016/s1470-2045(21)00065-6). Its abstract cites the registry id NCT02362594, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2021, doi: "10.1016/s1470-2045(21)00065-6", pmid: "33857412", authors: "Eggermont AMM, Blank CU, Mandalà M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-054 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2021","url":"https://doi.org/10.1016/s1470-2045(21)00065-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33857412/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33857412"},{"label":"ClinicalTrials.gov NCT02362594","url":"https://clinicaltrials.gov/study/NCT02362594"}], tags: ["europepmc-ingest"], trials: ["nct02362594"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct02938299-ann-oncol-2025", name: "Neoadjuvant intralesional targeted immunocytokines (daromun) in stage III melanoma", tldr: "Published report from the Neoadjuvant L19IL2 trial registered as NCT02938299, in Annals of Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: This phase III trial assessed daromun, a combination of two fibronectin-targeting immunocytokines (L19IL2 and L19TNF), as a neoadjuvant treatment for patients with clinically detectable stage IIIB/C melanoma [American Joint Committee on Cancer (AJCC) version 7].\n\nPatients and methods: Patients were randomized to weekly intralesional daromun administrations (13 million IU of L19IL2 and 400 μg of L19TNF) for 4 weeks followed by surgery, or upfront surgery. Pretreatment with approved adjuvant agents was allowed. The primary endpoint was recurrence-free survival (RFS): events were disease recurrence or death from any cause after complete surgical tumor resection (ClinicalTrials.gov NCT02938299).\n\nResults: A total of 246 patients were randomized and included in the intention-to-treat analysis: 74% had undergone two or more prior surgical resections and 35% had received prior systemic therapy. At a median follow-up of 21 months, the neoadjuvant group (n = 122) had a significantly longer RFS than the upfront surgery group (n = 124), with a median RFS of 16.7 months and 6.8 months, respectively [hazard ratio (HR) 0.59, 95% confidence interval (CI 0.41-0.86), P = 0.005, log-rank test]. The risk of distant recurrence was reduced by 40% in the neoadjuvant arm (HR 0.60, 95% CI 0.37-0.95, P = 0.029). Grade ≥3 treatment-related adverse events (TRAEs) were 6.7% in the surgery-alone arm and 27.1% in the daromun arm, mostly injection site reactions.\n\nConclusions: Neoadjuvant daromun resulted in a significantly longer RFS than upfront surgery in patients with locally advanced melanoma. TRAEs were transient and manageable. Neoadjuvant daromun is a new therapeutic option for patients with stage III melanoma, including those with locoregional recurrence after surgery and previous adjuvant therapy.\n\nIndexed on Europe PMC as PubMed record 40633690 (DOI 10.1016/j.annonc.2025.06.014). Its abstract cites the registry id NCT02938299, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2025, doi: "10.1016/j.annonc.2025.06.014", pmid: "40633690", authors: "Kähler KC, Hassel JC, Ziemer M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02938299 with the most citations, so it is the natural first reading for anyone following the Neoadjuvant L19IL2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2025","url":"https://doi.org/10.1016/j.annonc.2025.06.014"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40633690/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40633690"},{"label":"ClinicalTrials.gov NCT02938299","url":"https://clinicaltrials.gov/study/NCT02938299"}], tags: ["europepmc-ingest"], trials: ["nct02938299"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct02938299-j-clin-oncol-2026-update", name: "Neoadjuvant Intralesional Daromun (L19IL2/L19TNF) in Resectable Locally Advanced Melanoma: An Update on the Efficacy and Safety Results of the PIVOTAL Phase III Trial", tldr: "Later report from the Neoadjuvant L19IL2 trial registered as NCT02938299, in Journal of Clinical Oncology (2026); its title describes an updated or longer-term analysis.", summary: "Daromun (L19IL2/L19TNF) was investigated as a neoadjuvant, intralesional therapy for patients with fully resectable stage III melanoma in the phase III PIVOTAL trial (ClinicalTrials.gov identifier: NCT02938299). The trial enrolled 256 patients in the European Union and met its primary end point, demonstrating a statistically significant improvement in recurrence-free survival (RFS; hazard ratio, 0.59; P =.005) for daromun followed by surgery versus up-front surgery, at a median follow-up (FU) of 21 months from random assignment. PIVOTAL included two clinically distinct subgroups, namely, patients with de novo diagnosed metastatic disease (n = 34; 13%) and patients with recurrence(s) after surgery with or without radiotherapy and/or adjuvant systemic therapies (n = 222; 87%). Here, we present an updated analysis of the primary and secondary end points, including safety data, at a median FU of 36.8 months from random assignment (database cutoff: November 28, 2025), alongside new sensitivity analyses of event-free survival (EFS). The updated analysis confirms the clinically and statistically meaningful improvements in RFS and distant metastasis-free survival recorded in the neoadjuvant daromun versus control arm. The EFS post hoc analysis, conducted in both the overall population and the recurrent patient subgroups (with or without prior systemic therapies), provides consistency and robustness to the benefit of neoadjuvant daromun observed for the primary efficacy end point. No new safety signals of concern were recorded.\n\nIndexed on Europe PMC as PubMed record 42579833 (DOI 10.1200/jco-26-00852). Its abstract cites the registry id NCT02938299, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2026, doi: "10.1200/jco-26-00852", pmid: "42579833", authors: "Hauschild A, Hassel JC, Ziemer M, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the Neoadjuvant L19IL2 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2026","url":"https://doi.org/10.1200/jco-26-00852"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42579833/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42579833"},{"label":"ClinicalTrials.gov NCT02938299","url":"https://clinicaltrials.gov/study/NCT02938299"}], tags: ["europepmc-ingest"], trials: ["nct02938299"], journals: ["jco"] }),
  p({ id: "paper-nct03897881-j-clin-oncol-2026-update", name: "Intismeran Autogene Plus Pembrolizumab Versus Pembrolizumab Alone in High-Risk Resected Melanoma: 5-Year Update of the Randomized Phase IIb KEYNOTE-942 Study", tldr: "Later report from the trial registered as NCT03897881, in Journal of Clinical Oncology (2026); its title describes an updated or longer-term analysis.", summary: "Intismeran autogene (intismeran; formerly V940 or mRNA-4157) is an mRNA-based individualized neoantigen therapy. We report 5-year outcomes of intismeran plus pembrolizumab from the phase IIb KEYNOTE-942 study (ClinicalTrials.gov identifier: NCT03897881). Eligible patients with resected stage IIIB to IV cutaneous melanoma were randomly assigned 2:1 to receive nine doses of intramuscular intismeran 1 mg once every 3 weeks plus 18 doses of intravenous pembrolizumab 200 mg once every 3 weeks or 18 doses of intravenous pembrolizumab 200 mg once every 3 weeks. The primary end point was recurrence-free survival (RFS); secondary end points included distant metastasis-free survival (DMFS) and safety. Five-year analyses were descriptive. Among 157 randomly assigned patients (intismeran plus pembrolizumab, n = 107; pembrolizumab, n = 50), the median planned follow-up at data cutoff (December 15, 2025) was 60.3 (range, 50.5-76.4) months. Intismeran plus pembrolizumab continued to prolong RFS (hazard ratio [HR], 0.510 [95% CI, 0.294 to 0.887) and DMFS (HR, 0.411 [95% CI, 0.200 to 0.843]), with a favorable trend in overall survival (HR, 0.471 [95% CI, 0.165 to 1.345]) versus pembrolizumab. Safety profile continued to be manageable, with no new safety signals. Intismeran plus pembrolizumab was associated with increased T-cell receptor clonality and novel clonotypes versus pembrolizumab; greater novel clone expansion was observed in patients without versus with recurrence in the combination arm. After a 5-year follow-up, intismeran plus pembrolizumab demonstrated sustained, durable treatment benefits versus pembrolizumab alone in resected high-risk melanoma.\n\nIndexed on Europe PMC as PubMed record 42223134 (DOI 10.1200/jco-26-00835). Its abstract cites the registry id NCT03897881, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2026, doi: "10.1200/jco-26-00835", pmid: "42223134", authors: "Khattak A, Carlino MS, Meniawy T, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2026","url":"https://doi.org/10.1200/jco-26-00835"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42223134/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42223134"},{"label":"ClinicalTrials.gov NCT03897881","url":"https://clinicaltrials.gov/study/NCT03897881"}], tags: ["europepmc-ingest"], trials: ["nct03897881"], journals: ["jco"] }),
  p({ id: "paper-nct04639219-lancet-oncol-2024", name: "Trastuzumab deruxtecan in patients with solid tumours harbouring specific activating HER2 mutations (DESTINY-PanTumor01): an international, phase 2 study", tldr: "Published report from the trial registered as NCT04639219, in The Lancet Oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Trastuzumab deruxtecan is a HER2-directed antibody-drug conjugate approved by the US Food and Drug Administration and the European Medicines Agency for HER2-mutant non-small-cell lung cancer. Few treatment options exist for patients with HER2-mutant solid tumours beyond lung cancers. We investigated trastuzumab deruxtecan in metastatic solid tumours with specific activating HER2 mutations.\n\nMethods: In this open-label, phase 2, basket study done in 29 centres in Asia, Europe, and North America, we investigated trastuzumab deruxtecan (5·4 mg/kg every 3 weeks by intravenous infusion) in patients aged 18 years or older with unresectable or metastatic solid tumours with specific activating HER2 mutations, an Eastern Cooperative Oncology Group performance status of 0 or 1, and disease progression following previous treatment (previous HER2-targeted therapy was permitted) or with no satisfactory alternative treatment options. The primary endpoint was confirmed objective response rate by independent central review. Anti-tumour activity and safety were analysed in all patients who received at least one dose of trastuzumab deruxtecan. This trial is registered with ClinicalTrials.gov, NCT04639219, and is active but no longer recruiting.\n\nFindings: Between Dec 30, 2020, and Jan 25, 2023, 102 patients (62 [61%] female and 40 [39%] male; median age 66·5 years [IQR 58-72]; 51 [50%] White, two [2%] Black or African American, 38 [37%] Asian, and 11 [11%] did not have race information reported) with solid tumours with activating HER2 mutations received trastuzumab deruxtecan and were included in the anti-tumour activity and safety analyses sets. Patients had a median of three (IQR 2-4) previous treatment regimens. The median duration of follow-up was 8·61 months (IQR 3·71-12·68). The objective response rate by independent central review was 29·4% (95% CI 20·8-39·3; 30 of 102 patients). 52 (51%) patients had a treatment-emergent adverse event of grade 3 or worse; the most common events (in ≥5% of patients) were anaemia (16 [16%]) and neutrophil count decreased (eight [8%]). Drug-related treatment-emergent serious adverse events occurred in ten (10%) patients. Adjudicated drug-related interstitial lung disease or pneumonitis of any grade occurred in 11 patients (11%; three grade 1, five grade 2, one grade 3, and two grade 5); there were two (2%) cases of fatal adjudicated drug-related interstitial lung disease or pneumonitis.\n\nInterpretation: Trastuzumab deruxtecan showed anti-tumour activity and durable responses in heavily pretreated patients across multiple tumour types with activating HER2 mutations, with no new safety signals. Prespecified HER2 mutations might be targeted by HER2-directed antibody-drug conjugates and our findings support further investigation of trastuzumab deruxtecan in the pan-tumour setting.\n\nFunding: AstraZeneca and Daiichi Sankyo.\n\nIndexed on Europe PMC as PubMed record 38710187 (DOI 10.1016/s1470-2045(24)00140-2). Its abstract cites the registry id NCT04639219, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2024, doi: "10.1016/s1470-2045(24)00140-2", pmid: "38710187", authors: "Li BT, Meric-Bernstam F, Bardia A, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04639219 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2024","url":"https://doi.org/10.1016/s1470-2045(24)00140-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38710187/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38710187"},{"label":"ClinicalTrials.gov NCT04639219","url":"https://clinicaltrials.gov/study/NCT04639219"}], tags: ["europepmc-ingest"], trials: ["nct04639219"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct04657991-eur-j-cancer-2024", name: "First-line encorafenib plus binimetinib and pembrolizumab for advanced BRAF V600-mutant melanoma: Safety lead-in results from the randomized phase III STARBOARD study", tldr: "Published report from the trial registered as NCT04657991, in European Journal of Cancer (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: BRAF inhibitors plus MEK inhibitors (BRAFi/MEKi) and immune checkpoint inhibitors (CPIs) are approved for BRAF V600-mutant advanced melanoma. Combinations of BRAFi/MEKi with CPIs may further improve outcomes and could offer additional treatment strategies.\n\nMethods: STARBOARD (NCT04657991) is a phase III study with an initial safety lead-in (SLI) phase conducted to determine the recommended phase III dose (RP3D) for encorafenib in combination with binimetinib and pembrolizumab. Patients with untreated, unresectable locally advanced or metastatic BRAF V600E/K-mutant cutaneous melanoma received binimetinib 45 mg twice daily and pembrolizumab 200 mg every 3 weeks plus encorafenib 450 mg once daily (COMBO450 plus pembrolizumab) or 300 mg once daily (COMBO300 plus pembrolizumab). The primary endpoint was the incidence of dose-limiting toxicities (DLTs). Secondary endpoints included safety, objective response, time to response, and duration of response. Progression-free survival was assessed post hoc.\n\nResults: In the SLI, the median follow-up duration was 19.4 months. Twenty patients received COMBO450 plus pembrolizumab and 17 received COMBO300 plus pembrolizumab. DLTs occurred in 1 of 17 DLT-evaluable patients in the COMBO450 plus pembrolizumab arm and in 2 of 17 DLT-evaluable patients in the COMBO300 plus pembrolizumab arm. No treatment-related deaths occurred in either treatment arm. The overall response rate was 65.0 % in the COMBO450 plus pembrolizumab arm and 47.1 % in the COMBO300 plus pembrolizumab arm.\n\nConclusion: The STARBOARD SLI showed that safety across the cohorts was generally comparable to the known safety profile of each agent. The standard dose regimen of COMBO450 plus pembrolizumab was chosen as the RP3D.\n\nIndexed on Europe PMC as PubMed record 39427441 (DOI 10.1016/j.ejca.2024.115070). Its abstract cites the registry id NCT04657991, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "European Journal of Cancer", year: 2024, doi: "10.1016/j.ejca.2024.115070", pmid: "39427441", authors: "Dudnichenko O, Penkov K, McKean M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04657991 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Eur J Cancer 2024","url":"https://doi.org/10.1016/j.ejca.2024.115070"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39427441/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39427441"},{"label":"ClinicalTrials.gov NCT04657991","url":"https://clinicaltrials.gov/study/NCT04657991"}], tags: ["europepmc-ingest"], trials: ["nct04657991"], journals: ["european-journal-of-cancer"] }),
  p({ id: "paper-nct05415072-nat-med-2026", name: "An anti-PMEL antibody-drug conjugate with a G q/1 1 inhibitor payload in GNAQ/GNA11-mutant melanomas: a phase 1 trial", tldr: "Published report from the trial registered as NCT05415072, in Nature Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Metastatic uveal melanoma (mUM) is an aggressive cancer with limited treatment options; 85-90% of tumors harbor activating GNAQ and GNA11 mutations. Uveal melanoma cells also express PMEL (also known as PMEL17 or gp100), a melanocyte lineage antigen. DYP688, a novel biology-matched antibody-drug conjugate, binds surface PMEL and delivers the potent Gα q /Gα 11 (G q/11) inhibitor SDZ475 as payload by internalization. This dose-escalating first-in-human phase 1 study of DYP688 in patients with metastatic uveal melanoma and other GNAQ/GNA11-mutant melanomas assessed safety as the primary endpoint and pharmacokinetics and preliminary antitumor activity as secondary endpoints. Sixty-six patients received varying DYP688 doses and schedules. Grade 3 treatment-related adverse events occurred in five patients (7.6%), including one dose-limiting toxicity of grade 3 hypotension. Objective responses were seen in 13 out of 66 patients (19.7%) and tumor reduction in 47 out of 66 patients (71.2%). Median progression-free survival was 7.2 (95% CI: 5.3-7.8) months. In summary, DYP688 was well tolerated and showed preliminary efficacy, supporting this novel therapeutic approach. ClinicalTrials.gov identifier: NCT05415072.\n\nIndexed on Europe PMC as PubMed record 42443515 (DOI 10.1038/s41591-026-04518-z). Its abstract cites the registry id NCT05415072, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2026, doi: "10.1038/s41591-026-04518-z", pmid: "42443515", authors: "Carlino MS, Kapiteijn E, Piperno-Neumann S, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05415072 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2026","url":"https://doi.org/10.1038/s41591-026-04518-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42443515/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42443515"},{"label":"ClinicalTrials.gov NCT05415072","url":"https://clinicaltrials.gov/study/NCT05415072"}], tags: ["europepmc-ingest"], trials: ["nct05415072"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05732805-eur-j-cancer-2025", name: "Improved clinical outcomes with low-dose anti-CTLA-4 (Nurulimab) plus anti-PD-1 (Prolgolimab) vs. anti-PD-1 monotherapy in advanced cutaneous melanoma: Results from the phase III OCTAVA trial", tldr: "Published report from the OCTAVA trial registered as NCT05732805, in European Journal of Cancer (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: OCTAVA (NCT05732805) was an international, multi-center, randomized, double-blind, phase III study evaluating the fixed-dose combination of nurulimab (anti-CTLA-4) and prolgolimab (anti-PD-1) (BCD-217, Nuru+Prolgo) followed by prolgolimab maintenance versus prolgolimab monotherapy as first-line treatment for unresectable or metastatic melanoma (un/mM). We present the primary analysis results.\n\nMethods: Treatment-naïve patients with un/mM were randomized 1:1 to Nuru+Prolgo (n = 135) or prolgolimab (n = 136) for 4 cycles, followed by prolgolimab maintenance for up to two years. The primary endpoint was progression-free survival (PFS) by iRECIST.\n\nResults: With a median follow-up of 15.8 months, median PFS was significantly longer with nurulimab+prolgolimab [15.4 months (95 % CI, 10.3-ND)] compared to prolgolimab monotherapy [10.8 months (4.7-ND)] (HR 0.68; 95 % CI, 0.482-0.957; iRECIST). RECIST 1.1 analysis confirmed this benefit (mPFS 9.9 vs 2.8 months). ORR and DCR were also higher in the combination arm. Grade 3-4 treatment-related AE: 16.3 % (combination) vs 14.0 % (monotherapy). Immune-related AEs (irAE): 52.6 % vs 32.4 % (p = 0.0007); Gr. ≥ 3 irAE: 13.3 % vs 5.9 % (p = 0.04). Discontinuations due to AE: 9.6 % vs 4.4 %.\n\nConclusions: The Nuru+Prolgo fixed-dose combination demonstrated significantly superior efficacy versus aPD-1 monotherapy in first-line un/mM, with a manageable safety profile.\n\nIndexed on Europe PMC as PubMed record 40795521 (DOI 10.1016/j.ejca.2025.115674). Its abstract cites the registry id NCT05732805, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "European Journal of Cancer", year: 2025, doi: "10.1016/j.ejca.2025.115674", pmid: "40795521", authors: "Demidov L, Samoylenko I, Kharkevich G, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05732805 with the most citations, so it is the natural first reading for anyone following the OCTAVA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Eur J Cancer 2025","url":"https://doi.org/10.1016/j.ejca.2025.115674"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40795521/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40795521"},{"label":"ClinicalTrials.gov NCT05732805","url":"https://clinicaltrials.gov/study/NCT05732805"}], tags: ["europepmc-ingest"], trials: ["nct05732805"], journals: ["european-journal-of-cancer"] }),
  p({ id: "paper-nct02332668-lancet-oncol-2020", name: "Pembrolizumab in paediatric patients with advanced melanoma or a PD-L1-positive, advanced, relapsed, or refractory solid tumour or lymphoma (KEYNOTE-051): interim analysis of an open-label, single-arm, phase 1-2 trial", tldr: "Published report from the KEYNOTE-051 trial registered as NCT02332668, in The Lancet Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Pembrolizumab is approved for the treatment of advanced cancer in adults; however, no information is available on safety and efficacy in paediatric patients. We aimed to establish the recommended phase 2 dose of pembrolizumab and its safety and antitumour activity in advanced paediatric cancer.\n\nMethods: KEYNOTE-051 is an ongoing phase 1-2 open-label trial. In this interim analysis, children aged 6 months to 17 years were recruited at 30 hospitals located in Australia, Brazil, Canada, France, Germany, Israel, Italy, South Korea, Sweden, the UK, and the USA. Patients with melanoma or a centrally confirmed, PD-L1-positive, relapsed or refractory solid tumour or lymphoma, and a Lansky Play/Karnofsky Performance status score of 50 or higher, received intravenous pembrolizumab at an initial dose of 2 mg/kg every 3 weeks. Pharmacokinetics and dose-limiting toxicities were used to establish the recommended phase 2 dose, and the safety and antitumour activity of this dose were assessed. Primary endpoints were determination of dose-limiting toxicities at the maximum administered dose, safety and tolerability, and the proportion of patients with objective response to pembrolizumab for each tumour type according to the Response Evaluation Criteria in Solid Tumours version 1.1 or the International Neuroblastoma Response Criteria. Safety and efficacy were assessed in all treated patients who received at least one dose of pembrolizumab. Separate reporting of the cohort of patients with relapsed or refractory classical Hodgkin lymphoma was a post-hoc decision. The data cutoff for this interim analysis was Sept 3, 2018. This trial is still enrolling patients and is registered with ClinicalTrials.gov, number NCT02332668.\n\nFindings: Of 863 patients screened between March 23, 2015, and Sept 3, 2018, 796 had tumours that were evaluable for PD-L1 expression (278 [35%] were PD-L1-positive); 155 eligible patients were enrolled and 154 had at least one dose of pembrolizumab. The median age of the enrolled patients was 13 years (IQR 8-15). Median follow-up was 8·6 months (IQR 2·5-16·4). No dose-limiting toxicities were reported in phase 1, and pembrolizumab plasma concentrations were consistent with those previously reported in adults; the recommended phase 2 dose was therefore established as 2 mg/kg every 3 weeks. Of the 154 patients treated, 69 (45%) experienced grade 3-5 adverse events, most commonly anaemia in 14 (9%) patients and decreased lymphocyte count in nine (6%) patients. 13 (8%) of the 154 patients had grade 3-5 treatment-related adverse events, most commonly decreased lymphocyte count in three (2%) patients and anaemia in two (1%) patients. 14 (9%) patients had serious treatment-related adverse events, most commonly pyrexia (four [3%]), and hypertension and pleural effusion (two [1%] each). Four patients (3%) discontinued treatment because of treatment-related adverse events, and two (1%) died (one due to pulmonary oedema and one due to pleural effusion and pneumonitis). Of 15 patients with relapsed or refractory Hodgkin lymphoma, two had complete and seven had partial responses; thus, nine patients achieved an objective response (60·0%; 95% CI 32·3-83·7). Of 136 patients with solid tumours and other lymphomas, eight had partial responses (two patients each with adrenocortical carcinoma and mesothelioma, and one patient each with malignant ganglioglioma, epithelioid sarcoma, lymphoepithelial carcinoma, and malignant rhabdoid tumour); the proportion of patients with an objective response was 5·9% (95% CI 2·6-11·3).\n\nInterpretation: Pembrolizumab was well tolerated and showed encouraging antitumour activity in paediatric patients with relapsed or refractory Hodgkin lymphoma, consistent with experience in adult patients. Pembrolizumab had low antitumour activity in the majority of paediatric tumour types, and responses were observed in only a few rare PD-L1-positive tumour types, suggesting that PD-L1 expression alone is not sufficient as a biomarker for the selection of paediatric patients who are likely to respond to PD-1 checkpoint inhibitors. Final results of KEYNOTE-051, expected by September, 2022, with the possibility for extension, will report further on the activity of pembrolizumab in Hodgkin lymphoma, microsatellite instability-high tumours, and melanoma.\n\nFunding: Merck Sharp & Dohme, a subsidiary of Merck & Co.\n\nIndexed on Europe PMC as PubMed record 31812554 (DOI 10.1016/s1470-2045(19)30671-0). Its abstract cites the registry id NCT02332668, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2020, doi: "10.1016/s1470-2045(19)30671-0", pmid: "31812554", authors: "Geoerger B, Kang HJ, Yalon-Oren M, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02332668 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-051 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2020","url":"https://doi.org/10.1016/s1470-2045(19)30671-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31812554/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31812554"},{"label":"ClinicalTrials.gov NCT02332668","url":"https://clinicaltrials.gov/study/NCT02332668"}], tags: ["europepmc-ingest"], trials: ["nct02332668"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct05877430-j-immunother-cancer-2026", name: "Phase I trial of CJRB-101 plus pembrolizumab in patients with metastatic non-small cell lung cancer, head and neck squamous cell carcinoma and melanoma", tldr: "Published report from the trial registered as NCT05877430, in Journal for ImmunoTherapy of Cancer (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Dysbiosis of gut microbiome leads to resistance to immunotherapy in various advanced solid tumors. CJRB-101 is a live biotherapeutic product consisting of a novel strain belonging to the species Leuconostoc mesenteroides. To modulate the tumor microenvironment, CJRB-101 was combined with pembrolizumab.\n\nMethods: Preclinical efficacy and mechanistic studies were performed using humanized non-small cell lung cancer (NSCLC) patient-derived xenograft (PDX) models. This is a multicenter, first-in-human, two-part, phase I, open-label study of CJRB-101 (1×10 11 or 4×10 11 colony forming unit (CFU)/day) plus pembrolizumab (200 mg every three weeks (Q3W)) in advanced NSCLC, melanoma, and head and neck squamous cell carcinoma in both immune checkpoint inhibitor (ICI)-naive and ICI-refractory settings. The primary endpoint was to assess the dose-limiting toxicities (DLTs), adverse events, and preliminary activity of the combination treatment. Exploratory endpoints included stool metagenomics analysis and pharmacodynamics parameters.\n\nResults: In four PDX models, CJRB-101 with pembrolizumab demonstrated enhanced antitumor efficacy, showing a tumor growth inhibition (TGI) of 77.3% in the CJRB-101 monotherapy group and 61.9% in the combination group, which was significantly improved compared with pembrolizumab alone. A distinct M2-to-M1 repolarization was observed and validated in vitro. Notably, increased activation of cytotoxic T cells was observed, suggesting an immune-mediated antitumor mechanism of CJRB-101. A total of 42 patients were enrolled in the low-dose cohort (one capsule once a day; n=6) and high-dose cohort (two capsules two times a day, n=36). Metastatic NSCLC accounted for 86% (n=36) and 67% (n=28) of the patients were refractory to ICIs. None of the patients experienced DLT. In ICI-naïve NSCLC (n=12) with programmed death-ligand 1 (PD-L1) >50%, the overall response rate (ORR) and disease control rate (DCR) were 58% and 75%, respectively. The ORR was 5% and DCR was 41% in the ICI-refractory NSCLC (n=22) with an ORR of 5% and DCR of 41%. After a median follow-up of 15.6 months and 8.9 months for ICI-naïve and ICI-refractory NSCLC, the median progression-free survival was 9 months (95% CI 5.6 to not reached) and 1.8 months (95% CI 1.6 to 4.3), respectively. CJRB-101 plus pembrolizumab was well-tolerated, and none of the patients experienced grade > 3 treatment-related adverse events.\n\nConclusions: Early clinical data show encouraging antitumor response of CJRB-101 plus pembrolizumab in ICI-naïve metastatic NSCLC with PD-L1 > 50%.\n\nTrial registration number: NCT05877430.\n\nIndexed on Europe PMC as PubMed record 42140743 (DOI 10.1136/jitc-2025-014702). Its abstract cites the registry id NCT05877430, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal for ImmunoTherapy of Cancer", year: 2026, doi: "10.1136/jitc-2025-014702", pmid: "42140743", authors: "Lee JB, Baek S, Kim DK, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05877430 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Immunother Cancer 2026","url":"https://doi.org/10.1136/jitc-2025-014702"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42140743/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42140743"},{"label":"ClinicalTrials.gov NCT05877430","url":"https://clinicaltrials.gov/study/NCT05877430"}], tags: ["europepmc-ingest"], trials: ["nct05877430"], journals: ["jitc"] }),
  p({ id: "paper-aranote-eur-urol-2026", name: "Darolutamide Plus Androgen-deprivation Therapy in Metastatic Hormone-sensitive Prostate Cancer by Disease Volume and Risk Subgroups in the Phase 3 ARANOTE Trial", tldr: "Published report from the ARANOTE trial registered as NCT04736199, in European Urology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "In ARANOTE (NCT04736199), darolutamide plus androgen-deprivation therapy (ADT) significantly reduced the risk of radiologic progression or death versus placebo plus ADT in patients with metastatic hormone-sensitive prostate cancer, with favorable safety. Here, we report on post hoc outcomes by disease volume/risk. Randomized patients received darolutamide plus ADT or placebo plus ADT (2:1). High-volume (HV) and high-risk (HR) disease were defined by the CHAARTED and LATITUDE criteria, respectively. End points included radiologic progression-free survival (primary; rPFS), time to initiation of subsequent systemic anticancer therapy, time to metastatic castration-resistant prostate cancer, time to prostate-specific antigen (PSA) progression, time to pain progression, PSA <0.2 ng/ml rates, overall survival, and safety. Of 669 patients, 472 had HV disease, 197 had low-volume (LV) disease, 400 had HR disease, and 269 had low-risk (LR) disease; baseline characteristics were generally balanced. Darolutamide consistently reduced the rPFS (HV: 40% [hazard ratio, 0.60; 95% confidence interval, 0.44 to 0.80]; LV: 70% [0.30; 0.15 to 0.60]; HR: 39% [0.61; 0.44 to 0.86]; LR: 60% [0.40; 0.25 to 0.62]), with similar trends for all secondary end points versus placebo. Treatment-emergent adverse events were similar between treatment arms across all subgroups. Darolutamide was well tolerated, and outcomes were improved versus placebo, regardless of disease volume/risk. Prior presentation: Presented at the American Society of Clinical Oncology Genitourinary (ASCO GU) Cancers Symposium, San Francisco, CA, February 13-15, 2025. Clinical trial registration: NCT04736199 (EudraCT 2020-003093-48).\n\nIndexed on Europe PMC as PubMed record 42586872 (DOI 10.1016/j.eururo.2026.07.026). Its abstract cites the registry id NCT04736199, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "European Urology", year: 2026, doi: "10.1016/j.eururo.2026.07.026", pmid: "42586872", authors: "Saad F, Shore N, Vjaters E, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04736199 with the most citations, so it is the natural first reading for anyone following the ARANOTE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Eur Urol 2026","url":"https://doi.org/10.1016/j.eururo.2026.07.026"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42586872/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42586872"},{"label":"ClinicalTrials.gov NCT04736199","url":"https://clinicaltrials.gov/study/NCT04736199"}], tags: ["europepmc-ingest"], trials: ["aranote"], journals: ["european-urology"] }),
  p({ id: "paper-arches-j-clin-oncol-2019", name: "ARCHES: A Randomized, Phase III Study of Androgen Deprivation Therapy With Enzalutamide or Placebo in Men With Metastatic Hormone-Sensitive Prostate Cancer", tldr: "Published report from the ARCHES trial registered as NCT02677896, in Journal of Clinical Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Enzalutamide, a potent androgen-receptor inhibitor, has demonstrated significant benefits in metastatic and nonmetastatic castration-resistant prostate cancer. We evaluated the efficacy and safety of enzalutamide in metastatic hormone-sensitive prostate cancer (mHSPC).\n\nMethods: ARCHES (ClinicalTrials.gov identifier: NCT02677896) is a multinational, double-blind, phase III trial, wherein 1,150 men with mHSPC were randomly assigned 1:1 to enzalutamide (160 mg/day) or placebo, plus androgen deprivation therapy (ADT), stratified by disease volume and prior docetaxel chemotherapy. The primary end point was radiographic progression-free survival.\n\nResults: at October 14, 2018, the risk of radiographic progression or death was significantly reduced with enzalutamide plus ADT versus placebo plus ADT (hazard ratio, 0.39; 95% CI, 0.30 to 0.50; P <.001; median not reached v 19.0 months). Similar significant improvements in radiographic progression-free survival were reported in prespecified subgroups on the basis of disease volume and prior docetaxel therapy. Enzalutamide plus ADT significantly reduced the risk of prostate-specific antigen progression, initiation of new antineoplastic therapy, first symptomatic skeletal event, castration resistance, and reduced risk of pain progression. More men achieved an undetectable prostate-specific antigen level and/or an objective response with enzalutamide plus ADT ( P <.001). Patients in both treatment groups reported a high baseline level of quality of life, which was maintained over time. Grade 3 or greater adverse events were reported in 24.3% of patients who received enzalutamide plus ADT versus 25.6% of patients who received placebo plus ADT, with no unexpected adverse events.\n\nConclusion: Enzalutamide with ADT significantly reduced the risk of metastatic progression or death over time versus placebo plus ADT in men with mHSPC, including those with low-volume disease and/or prior docetaxel, with a safety analysis that seems consistent with the safety profile of enzalutamide in previous clinical trials in castration-resistant prostate cancer.\n\nIndexed on Europe PMC as PubMed record 31329516 (DOI 10.1200/jco.19.00799). Its abstract cites the registry id NCT02677896, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2019, doi: "10.1200/jco.19.00799", pmid: "31329516", authors: "Armstrong AJ, Szmulewitz RZ, Petrylak DP, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02677896 with the most citations, so it is the natural first reading for anyone following the ARCHES trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2019","url":"https://doi.org/10.1200/jco.19.00799"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31329516/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31329516"},{"label":"ClinicalTrials.gov NCT02677896","url":"https://clinicaltrials.gov/study/NCT02677896"}], tags: ["europepmc-ingest"], trials: ["arches"], journals: ["jco"] }),
  p({ id: "paper-arches-eur-urol-2026-update", name: "ARCHES 5-year Survival with Enzalutamide Plus Androgen-deprivation Therapy in Metastatic Hormone-sensitive Prostate Cancer Patients", tldr: "Later report from the ARCHES trial registered as NCT02677896, in European Urology (2026); its title describes an updated or longer-term analysis.", summary: "The ARCHES trial (NCT02677896) showed improved radiographic progression-free survival (primary analysis; 2018) and overall survival (prespecified analysis; 2021) with enzalutamide versus placebo, with concomitant androgen-deprivation therapy, in metastatic hormone-sensitive prostate cancer (mHSPC) patients. This post hoc analysis describes 5-yr efficacy and safety for all 1150 randomized patients (data cutoff: July 31, 2024). Patients were randomized 1:1 to receive enzalutamide or placebo (first patient randomized: March 21, 2016). After the primary analysis, ARCHES was unblinded (December 10, 2018); 65% and 32% of patients in the enzalutamide and placebo groups, respectively, enrolled in the open-label extension. After the 61.4-mo median follow-up, 5-yr survival probability was 66% with enzalutamide and 53% with placebo (median months not reached in either group; hazard ratio [HR]: 0.70; 95% confidence interval [CI]: 0.58, 0.85; p < 0.001; adjusted HR: 0.64; 95% CI: 0.51, 0.75). Patients with high-volume disease who received enzalutamide lived 36 mo longer than those who received placebo (HR: 0.70; 95% CI: 0.56, 0.88). No new safety signals emerged. As this was a post hoc, non-alpha protected analysis, the overall survival p value is nominal and should be interpreted cautiously. Overall, this study provides compelling long-term data demonstrating survival benefits with enzalutamide across diverse patient subgroups to guide clinical decision-making and establish prognostic expectations in the mHSPC setting.\n\nIndexed on Europe PMC as PubMed record 41633900 (DOI 10.1016/j.eururo.2025.12.021). Its abstract cites the registry id NCT02677896, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "European Urology", year: 2026, doi: "10.1016/j.eururo.2025.12.021", pmid: "41633900", authors: "Armstrong AJ, Petrylak DP, Shore ND, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the ARCHES trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Eur Urol 2026","url":"https://doi.org/10.1016/j.eururo.2025.12.021"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41633900/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41633900"},{"label":"ClinicalTrials.gov NCT02677896","url":"https://clinicaltrials.gov/study/NCT02677896"}], tags: ["europepmc-ingest"], trials: ["arches"], journals: ["european-urology"] }),
  p({ id: "paper-capitello-281-ann-oncol-2026", name: "Capivasertib plus abiraterone in PTEN-deficient metastatic hormone-sensitive prostate cancer: CAPItello-281 phase III study", tldr: "Published report from the CAPItello-281 trial registered as NCT04493853, in Annals of Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: In metastatic hormone-sensitive prostate cancer (mHSPC), phosphatase and tensin homolog (PTEN) deficiency results in phosphoinositide 3-kinase (PI3K)/protein kinase B (AKT) pathway activation, providing an independent proliferative drive, which cannot be suppressed by androgen receptor pathway inhibitors (ARPIs), resulting in worse outcomes. Dual inhibition of PI3K/AKT and AR pathways with capivasertib and abiraterone may delay progression and improve disease outcomes.\n\nPatients and methods: In CAPItello-281 (NCT04493853), patients with PTEN-deficient mHSPC (diagnostic cut-off: ≥90% viable malignant cells with no specific cytoplasmic PTEN immunohistochemistry staining) received capivasertib or placebo (1: 1) plus abiraterone, prednisone/prednisolone, and androgen deprivation therapy (ADT). The primary endpoint was investigator-assessed radiographic progression-free survival (rPFS); overall survival (OS) was a key secondary endpoint. Post hoc exploratory subgroups at increasing PTEN cut-off thresholds were also assessed.\n\nResults: 25.3% (1519/6003) of patients with valid tumor test results had PTEN-deficient tumors. In the randomized PTEN-deficient population, a statistically significant improvement in rPFS was observed with capivasertib plus abiraterone (n = 507, median 33.2 months) versus placebo plus abiraterone [n = 505, 25.7 months; hazard ratio (HR) 0.81, 95% confidence interval (CI) 0.66-0.98, P = 0.034]. Post hoc rPFS analyses for loss of PTEN cut-offs of ≥95%, ≥99%, and 100% showed that the capivasertib plus abiraterone arm performed consistently across cut-offs, but the placebo plus abiraterone arm performed progressively worse as the cut-off for the degree of PTEN loss was increased, resulting in a numerically improved treatment effect. In the overall population studied, the HR for OS (26.4% maturity) was 0.90, 95% CI 0.71-1.15, P = 0.401. The most common adverse events (AEs) for capivasertib plus abiraterone were diarrhea (51.9%; 8.0% placebo plus abiraterone), hyperglycemia (38.0%; 12.9%), and rash (35.4%; 7.0%). Deaths associated with an AE were reported in 36 (7.2%) and 26 (5.2%) patients in the capivasertib plus abiraterone and placebo plus abiraterone arms, respectively.\n\nConclusions: Capivasertib plus abiraterone improves rPFS versus placebo plus abiraterone in PTEN-deficient mHSPC, on a background of ADT, with a 7.5-month improvement in median rPFS. AE profile was consistent with that of the individual agents. Patients with PTEN-deficient mHSPC benefit from dual blockade of the PI3K/AKT and AR pathways with capivasertib plus abiraterone.\n\nIndexed on Europe PMC as PubMed record 41120017 (DOI 10.1016/j.annonc.2025.10.004). Its abstract cites the registry id NCT04493853, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2026, doi: "10.1016/j.annonc.2025.10.004", pmid: "41120017", authors: "Fizazi K, Clarke NW, De Santis M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04493853 with the most citations, so it is the natural first reading for anyone following the CAPItello-281 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2026","url":"https://doi.org/10.1016/j.annonc.2025.10.004"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41120017/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41120017"},{"label":"ClinicalTrials.gov NCT04493853","url":"https://clinicaltrials.gov/study/NCT04493853"}], tags: ["europepmc-ingest"], trials: ["capitello-281"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-enzamet-n-engl-j-med-2019", name: "Enzalutamide with Standard First-Line Therapy in Metastatic Prostate Cancer", tldr: "Published report from the ENZAMET trial registered as NCT02446405, in New England Journal of Medicine (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Enzalutamide, an androgen-receptor inhibitor, has been associated with improved overall survival in men with castration-resistant prostate cancer. It is not known whether adding enzalutamide to testosterone suppression, with or without early docetaxel, will improve survival in men with metastatic, hormone-sensitive prostate cancer.\n\nMethods: In this open-label, randomized, phase 3 trial, we assigned patients to receive testosterone suppression plus either open-label enzalutamide or a standard nonsteroidal antiandrogen therapy (standard-care group). The primary end point was overall survival. Secondary end points included progression-free survival as determined by the prostate-specific antigen (PSA) level, clinical progression-free survival, and adverse events.\n\nResults: A total of 1125 men underwent randomization; the median follow-up was 34 months. There were 102 deaths in the enzalutamide group and 143 deaths in the standard-care group (hazard ratio, 0.67; 95% confidence interval [CI], 0.52 to 0.86; P = 0.002). Kaplan-Meier estimates of overall survival at 3 years were 80% (based on 94 events) in the enzalutamide group and 72% (based on 130 events) in the standard-care group. Better results with enzalutamide were also seen in PSA progression-free survival (174 and 333 events, respectively; hazard ratio, 0.39; P<0.001) and in clinical progression-free survival (167 and 320 events, respectively; hazard ratio, 0.40; P<0.001). Treatment discontinuation due to adverse events was more frequent in the enzalutamide group than in the standard-care group (33 events and 14 events, respectively). Fatigue was more common in the enzalutamide group; seizures occurred in 7 patients in the enzalutamide group (1%) and in no patients in the standard-care group.\n\nConclusions: Enzalutamide was associated with significantly longer progression-free and overall survival than standard care in men with metastatic, hormone-sensitive prostate cancer receiving testosterone suppression. The enzalutamide group had a higher incidence of seizures and other toxic effects, especially among those treated with early docetaxel. (Funded by Astellas Scientific and Medical Affairs and others; ENZAMET (ANZUP 1304) ANZCTR number, ACTRN12614000110684; ClinicalTrials.gov number, NCT02446405; and EU Clinical Trials Register number, 2014-003190-42.).\n\nIndexed on Europe PMC as PubMed record 31157964 (DOI 10.1056/nejmoa1903835). Its abstract cites the registry id NCT02446405, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2019, doi: "10.1056/nejmoa1903835", pmid: "31157964", authors: "Davis ID, Martin AJ, Stockler MR, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02446405 with the most citations, so it is the natural first reading for anyone following the ENZAMET trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2019","url":"https://doi.org/10.1056/nejmoa1903835"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31157964/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31157964"},{"label":"ClinicalTrials.gov NCT02446405","url":"https://clinicaltrials.gov/study/NCT02446405"}], tags: ["europepmc-ingest"], trials: ["enzamet"], journals: ["nejm"] }),
  p({ id: "paper-goteborg-2-n-engl-j-med-2022", name: "Prostate Cancer Screening with PSA and MRI Followed by Targeted Biopsy Only", tldr: "Published report from the trial registered as ISRCTN94604465, in New England Journal of Medicine (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Screening for prostate cancer is burdened by a high rate of overdiagnosis. The most appropriate algorithm for population-based screening is unknown.\n\nMethods: We invited 37,887 men who were 50 to 60 years of age to undergo regular prostate-specific antigen (PSA) screening. Participants with a PSA level of 3 ng per milliliter or higher underwent magnetic resonance imaging (MRI) of the prostate; one third of the participants were randomly assigned to a reference group that underwent systematic biopsy as well as targeted biopsy of suspicious lesions shown on MRI. The remaining participants were assigned to the experimental group and underwent MRI-targeted biopsy only. The primary outcome was clinically insignificant prostate cancer, defined as a Gleason score of 3+3. The secondary outcome was clinically significant prostate cancer, defined as a Gleason score of at least 3+4. Safety was also assessed.\n\nResults: Of the men who were invited to undergo screening, 17,980 (47%) participated in the trial. A total of 66 of the 11,986 participants in the experimental group (0.6%) received a diagnosis of clinically insignificant prostate cancer, as compared with 72 of 5994 participants (1.2%) in the reference group, a difference of -0.7 percentage points (95% confidence interval [CI], -1.0 to -0.4; relative risk, 0.46; 95% CI, 0.33 to 0.64; P<0.001). The relative risk of clinically significant prostate cancer in the experimental group as compared with the reference group was 0.81 (95% CI, 0.60 to 1.1). Clinically significant cancer that was detected only by systematic biopsy was diagnosed in 10 participants in the reference group; all cases were of intermediate risk and involved mainly low-volume disease that was managed with active surveillance. Serious adverse events were rare (<0.1%) in the two groups.\n\nConclusions: The avoidance of systematic biopsy in favor of MRI-directed targeted biopsy for screening and early detection in persons with elevated PSA levels reduced the risk of overdiagnosis by half at the cost of delaying detection of intermediate-risk tumors in a small proportion of patients. (Funded by Karin and Christer Johansson's Foundation and others; GÖTEBORG-2 ISRCTN Registry number, ISRCTN94604465.).\n\nIndexed on Europe PMC as PubMed record 36477032 (DOI 10.1056/nejmoa2209454). Its abstract cites the registry id ISRCTN94604465, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2022, doi: "10.1056/nejmoa2209454", pmid: "36477032", authors: "Hugosson J, Månsson M, Wallström J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id ISRCTN94604465 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2022","url":"https://doi.org/10.1056/nejmoa2209454"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36477032/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36477032"},{"label":"ClinicalTrials.gov ISRCTN94604465","url":"https://clinicaltrials.gov/study/ISRCTN94604465"}], tags: ["europepmc-ingest"], trials: ["goteborg-2"], journals: ["nejm"] }),
  p({ id: "paper-latitude-lancet-oncol-2019-update", name: "Abiraterone acetate plus prednisone in patients with newly diagnosed high-risk metastatic castration-sensitive prostate cancer (LATITUDE): final overall survival analysis of a randomised, double-blind, phase 3 trial", tldr: "Later report from the LATITUDE trial registered as NCT01715285, in The Lancet Oncology (2019); its title describes an updated or longer-term analysis.", summary: "Background: In the interim analyses of the LATITUDE study, the addition of abiraterone acetate plus prednisone to androgen deprivation therapy (ADT) led to a significant improvement in overall survival and radiographic progression-free survival compared with placebos plus ADT in men with newly diagnosed high-risk metastatic castration-sensitive prostate cancer (mCSPC). Here, we present long-term survival outcomes and safety of abiraterone acetate plus prednisone and ADT from the final analysis of the LATITUDE study.\n\nMethods: This is a multicentre, randomised, double-blind, phase 3 trial done at 235 sites in 34 countries. Eligible patients (men aged ≥18 years) had newly diagnosed, histologically or cytologically confirmed prostate cancer with metastases, Eastern Cooperative Oncology Group (ECOG) performance status of 0-2, and at least two of the three high-risk prognostic factors (Gleason score of ≥8, presence of three or more lesions on bone scan, or presence of measurable visceral metastasis except lymph node metastasis). Patients were randomly assigned (1:1) to receive abiraterone acetate (1000 mg) once daily orally plus prednisone (5 mg) once daily orally and ADT (abiraterone acetate plus prednisone group) or matching placebos plus ADT (placebo group); each treatment cycle was 28 days. Randomisation was done by a centralised interactive web response system in a country-by-country scheme using permuted block randomisation, stratified by presence of visceral disease and ECOG performance status. The coprimary endpoint of overall survival was assessed in the intention-to-treat population. This study is registered at ClinicalTrials.gov, number NCT01715285 and is complete.\n\nFindings: Between Feb 12, 2013, and Dec 11, 2014, 1209 patients were screened, of whom ten were ineligible because of study site violations. 1199 patients were randomly assigned to either the abiraterone acetate plus prednisone group (n=597) or placebo group (n=602). After the results of the first interim analysis (cutoff date Oct 31, 2016), the study was unmasked to patients and investigators, and patients in the placebo group were allowed to cross over to receive abiraterone acetate and prednisone plus ADT treatment as per a protocol amendment (Feb 15, 2017) in an open-label extension phase of the study (up to 18 months from the protocol amendment). This final analysis (data cutoff Aug 15, 2018) was done after a median follow-up of 51·8 months (IQR 47·2-57·0) and 618 deaths (275 [46%] of 597 in the abiraterone acetate plus prednisone group and 343 [57%] of 602 in the placebo group). Overall survival was significantly longer in the abiraterone acetate plus prednisone group (median 53·3 months [95% CI 48·2-not reached]) than in the placebo group (36·5 months [33·5-40·0]), with a hazard ratio of 0·66 (95% CI 0·56-0·78; p<0·0001). The most common grade 3-4 adverse events were hypertension (125 [21%] in the abiraterone acetate plus prednisone group vs 60 [10%] in the placebo group vs three [4%] in the 72 patients who crossed over from placebo to abiraterone acetate plus prednisone) and hypokalaemia (70 [12%] vs ten [2%] vs two [3%]). Serious adverse events of any grade occurred in 192 (32%) of 597 patients in the abiraterone acetate plus prednisone group, 151 (25%) of 602 in the placebo group, and four (6%) of 72 in the crossover group. The most common treatment-related serious adverse event was hypokalaemia (four [1%] patients in the abiraterone acetate plus prednisone group and none in the other groups). Treatment-related deaths occurred in three (<1%) patients each in the abiraterone acetate plus prednisone group (gastric ulcer perforation, sudden death, and cerebrovascular accident) and the placebo group (sudden death, cerebrovascular accident, and pneumonia), with none in the crossover group.\n\nInterpretation: The combination of abiraterone acetate plus prednisone with ADT was associated with significantly longer overall survival than placebos plus ADT in men with newly diagnosed high-risk mCSPC and had a manageable safety profile. These findings support the use of abiraterone acetate plus prednisone as a standard of care in patients with high-risk mCSPC.\n\nFunding: Janssen Research & Development.\n\nIndexed on Europe PMC as PubMed record 30987939 (DOI 10.1016/s1470-2045(19)30082-8). Its abstract cites the registry id NCT01715285, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2019, doi: "10.1016/s1470-2045(19)30082-8", pmid: "30987939", authors: "Fizazi K, Tran N, Fein L, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the LATITUDE trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2019","url":"https://doi.org/10.1016/s1470-2045(19)30082-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30987939/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30987939"},{"label":"ClinicalTrials.gov NCT01715285","url":"https://clinicaltrials.gov/study/NCT01715285"}], tags: ["europepmc-ingest"], trials: ["latitude"], journals: ["lancet-oncology"] }),
  p({ id: "paper-magnitude-j-clin-oncol-2023", name: "Niraparib and Abiraterone Acetate for Metastatic Castration-Resistant Prostate Cancer", tldr: "Published report from the MAGNITUDE trial registered as NCT03748641, in Journal of Clinical Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Metastatic castration-resistant prostate cancer (mCRPC) remains a lethal disease with current standard-of-care therapies. Homologous recombination repair (HRR) gene alterations, including BRCA1/2 alterations, can sensitize cancer cells to poly (ADP-ribose) polymerase inhibition, which may improve outcomes in treatment-naïve mCRPC when combined with androgen receptor signaling inhibition.\n\nMethods: MAGNITUDE (ClinicalTrials.gov identifier: NCT03748641) is a phase III, randomized, double-blinded study that evaluates niraparib and abiraterone acetate plus prednisone (niraparib + AAP) in patients with (HRR+, n = 423) or without (HRR-, n = 247) HRR-associated gene alterations, as prospectively determined by tissue/plasma-based assays. Patients were assigned 1:1 to receive niraparib + AAP or placebo + AAP. The primary end point, radiographic progression-free survival (rPFS) assessed by central review, was evaluated first in the BRCA1/2 subgroup and then in the full HRR+ cohort, with secondary end points analyzed for the full HRR+ cohort if rPFS was statistically significant. A futility analysis was preplanned in the HRR- cohort.\n\nResults: Median rPFS in the BRCA1/2 subgroup was significantly longer in the niraparib + AAP group compared with the placebo + AAP group (16.6 v 10.9 months; hazard ratio [HR], 0.53; 95% CI, 0.36 to 0.79; P =.001). In the overall HRR+ cohort, rPFS was significantly longer in the niraparib + AAP group compared with the placebo + AAP group (16.5 v 13.7 months; HR, 0.73; 95% CI, 0.56 to 0.96; P =.022). These findings were supported by improvement in the secondary end points of time to symptomatic progression and time to initiation of cytotoxic chemotherapy. In the HRR- cohort, futility was declared per the prespecified criteria. Treatment with niraparib + AAP was tolerable, with anemia and hypertension as the most reported grade ≥ 3 adverse events.\n\nConclusion: Combination treatment with niraparib + AAP significantly lengthened rPFS in patients with HRR+ mCRPC compared with standard-of-care AAP.[Media: see text].\n\nIndexed on Europe PMC as PubMed record 36952634 (DOI 10.1200/jco.22.01649). Its abstract cites the registry id NCT03748641, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.22.01649", pmid: "36952634", authors: "Chi KN, Rathkopf D, Smith MR, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03748641 with the most citations, so it is the natural first reading for anyone following the MAGNITUDE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.22.01649"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36952634/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36952634"},{"label":"ClinicalTrials.gov NCT03748641","url":"https://clinicaltrials.gov/study/NCT03748641"}], tags: ["europepmc-ingest"], trials: ["magnitude"], journals: ["jco"] }),
  p({ id: "paper-pace-b-lancet-oncol-2019", name: "Intensity-modulated fractionated radiotherapy versus stereotactic body radiotherapy for prostate cancer (PACE-B): acute toxicity findings from an international, randomised, open-label, phase 3, non-inferiority trial", tldr: "Published report from the PACE-B trial registered as NCT01584258, in The Lancet Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Localised prostate cancer is commonly treated with external-beam radiotherapy. Moderate hypofractionation has been shown to be non-inferior to conventional fractionation. Ultra-hypofractionated stereotactic body radiotherapy would allow shorter treatment courses but could increase acute toxicity compared with conventionally fractionated or moderately hypofractionated radiotherapy. We report the acute toxicity findings from a randomised trial of standard-of-care conventionally fractionated or moderately hypofractionated radiotherapy versus five-fraction stereotactic body radiotherapy for low-risk to intermediate-risk localised prostate cancer.\n\nMethods: PACE is an international, phase 3, open-label, randomised, non-inferiority trial. In PACE-B, eligible men aged 18 years and older, with WHO performance status 0-2, low-risk or intermediate-risk prostate adenocarcinoma (Gleason 4 + 3 excluded), and scheduled to receive radiotherapy were recruited from 37 centres in three countries (UK, Ireland, and Canada). Participants were randomly allocated (1:1) by computerised central randomisation with permuted blocks (size four and six), stratified by centre and risk group, to conventionally fractionated or moderately hypofractionated radiotherapy (78 Gy in 39 fractions over 7·8 weeks or 62 Gy in 20 fractions over 4 weeks, respectively) or stereotactic body radiotherapy (36·25 Gy in five fractions over 1-2 weeks). Neither participants nor investigators were masked to allocation. Androgen deprivation was not permitted. The primary endpoint of PACE-B is freedom from biochemical or clinical failure. The coprimary outcomes for this acute toxicity substudy were worst grade 2 or more severe Radiation Therapy Oncology Group (RTOG) gastrointestinal or genitourinary toxic effects score up to 12 weeks after radiotherapy. Analysis was per protocol. This study is registered with ClinicalTrials.gov, NCT01584258. PACE-B recruitment is complete and follow-up is ongoing.\n\nFindings: Between Aug 7, 2012, and Jan 4, 2018, we randomly assigned 874 men to conventionally fractionated or moderately hypofractionated radiotherapy (n=441) or stereotactic body radiotherapy (n=433). 432 (98%) of 441 patients allocated to conventionally fractionated or moderately hypofractionated radiotherapy and 415 (96%) of 433 patients allocated to stereotactic body radiotherapy received at least one fraction of allocated treatment. Worst acute RTOG gastrointestinal toxic effect proportions were as follows: grade 2 or more severe toxic events in 53 (12%) of 432 patients in the conventionally fractionated or moderately hypofractionated radiotherapy group versus 43 (10%) of 415 patients in the stereotactic body radiotherapy group (difference -1·9 percentage points, 95% CI -6·2 to 2·4; p=0·38). Worst acute RTOG genitourinary toxicity proportions were as follows: grade 2 or worse toxicity in 118 (27%) of 432 patients in the conventionally fractionated or moderately hypofractionated radiotherapy group versus 96 (23%) of 415 patients in the stereotactic body radiotherapy group (difference -4·2 percentage points, 95% CI -10·0 to 1·7; p=0·16). No treatment-related deaths occurred.\n\nInterpretation: Previous evidence (from the HYPO-RT-PC trial) suggested higher patient-reported toxicity with ultrahypofractionation. By contrast, our results suggest that substantially shortening treatment courses with stereotactic body radiotherapy does not increase either gastrointestinal or genitourinary acute toxicity.\n\nFunding: Accuray and National Institute of Health Research.\n\nIndexed on Europe PMC as PubMed record 31540791 (DOI 10.1016/s1470-2045(19)30569-8). Its abstract cites the registry id NCT01584258, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2019, doi: "10.1016/s1470-2045(19)30569-8", pmid: "31540791", authors: "Brand DH, Tree AC, Ostler P, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01584258 with the most citations, so it is the natural first reading for anyone following the PACE-B trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2019","url":"https://doi.org/10.1016/s1470-2045(19)30569-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31540791/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31540791"},{"label":"ClinicalTrials.gov NCT01584258","url":"https://clinicaltrials.gov/study/NCT01584258"}], tags: ["europepmc-ingest"], trials: ["pace-b"], journals: ["lancet-oncology"] }),
  p({ id: "paper-pace-b-lancet-oncol-2022-update", name: "Intensity-modulated radiotherapy versus stereotactic body radiotherapy for prostate cancer (PACE-B): 2-year toxicity results from an open-label, randomised, phase 3, non-inferiority trial", tldr: "Later report from the PACE-B trial registered as NCT01584258, in The Lancet Oncology (2022); its title describes an updated or longer-term analysis.", summary: "Background: Localised prostate cancer is commonly treated with external beam radiotherapy and moderate hypofractionation is non-inferior to longer schedules. Stereotactic body radiotherapy (SBRT) allows shorter treatment courses without impacting acute toxicity. We report 2-year toxicity findings from PACE-B, a randomised trial of conventionally fractionated or moderately hypofractionated radiotherapy versus SBRT.\n\nMethods: PACE is an open-label, multicohort, randomised, controlled, phase 3 trial conducted at 35 hospitals in the UK, Ireland, and Canada. In PACE-B, men aged 18 years and older with a WHO performance status 0-2 and low-risk or intermediate-risk histologically-confirmed prostate adenocarcinoma (Gleason 4 + 3 excluded) were randomly allocated (1:1) by computerised central randomisation with permuted blocks (size four and six), stratified by centre and risk group to control radiotherapy (CRT; 78 Gy in 39 fractions over 7·8 weeks or, following protocol amendment on March 24, 2016, 62 Gy in 20 fractions over 4 weeks) or SBRT (36·25 Gy in five fractions over 1-2 weeks). Androgen deprivation was not permitted. Co-primary outcomes for this toxicity analysis were Radiation Therapy Oncology Group (RTOG) grade 2 or worse gastrointestinal and genitourinary toxicity at 24 months after radiotherapy. Analysis was by treatment received and included all patients with at least one fraction of study treatment assessed for late toxicity. Recruitment is complete. Follow-up for oncological outcomes continues. The trial is registered with ClinicalTrials.gov, NCT01584258.\n\nFindings: We enrolled and randomly assigned 874 men between Aug 7, 2012, and Jan 4, 2018 (441 to CRT and 433 to SBRT). In this analysis, 430 patients were analysed in the CRT group and 414 in the SBRT group; a total of 844 (97%) of 874 randomly assigned patients. At 24 months, RTOG grade 2 or worse genitourinary toxicity was seen in eight (2%) of 381 participants assigned to CRT and 13 (3%) of 384 participants assigned to SBRT (absolute difference 1·3% [95% CI -1·3 to 4·0]; p=0·39); RTOG grade 2 or worse gastrointestinal toxicity was seen in 11 (3%) of 382 participants in the CRT group versus six (2%) of 384 participants in the SBRT group (absolute difference -1·3% [95% CI -3·9 to 1·1]; p=0·32). No serious adverse events (defined as RTOG grade 4 or worse) or treatment-related deaths were reported within the analysis timeframe.\n\nInterpretation: In the PACE-B trial, 2-year RTOG toxicity rates were similar for five fraction SBRT and conventional schedules of radiotherapy. Prostate SBRT was found to be safe and associated with low rates of side-effects. Biochemical outcomes are awaited.\n\nFunding: Accuray.\n\nIndexed on Europe PMC as PubMed record 36113498 (DOI 10.1016/s1470-2045(22)00517-4). Its abstract cites the registry id NCT01584258, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2022, doi: "10.1016/s1470-2045(22)00517-4", pmid: "36113498", authors: "Tree AC, Ostler P, van der Voet H, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the PACE-B trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2022","url":"https://doi.org/10.1016/s1470-2045(22)00517-4"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36113498/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36113498"},{"label":"ClinicalTrials.gov NCT01584258","url":"https://clinicaltrials.gov/study/NCT01584258"}], tags: ["europepmc-ingest"], trials: ["pace-b"], journals: ["lancet-oncology"] }),
  p({ id: "paper-peace-1-lancet-2022", name: "Abiraterone plus prednisone added to androgen deprivation therapy and docetaxel in de novo metastatic castration-sensitive prostate cancer (PEACE-1): a multicentre, open-label, randomised, phase 3 study with a 2 × 2 factorial design", tldr: "Published report from the PEACE-1 trial registered as NCT01957436, in The Lancet (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Current standard of care for metastatic castration-sensitive prostate cancer supplements androgen deprivation therapy with either docetaxel, second-generation hormonal therapy, or radiotherapy. We aimed to evaluate the efficacy and safety of abiraterone plus prednisone, with or without radiotherapy, in addition to standard of care.\n\nMethods: We conducted an open-label, randomised, phase 3 study with a 2 × 2 factorial design (PEACE-1) at 77 hospitals across Belgium, France, Ireland, Italy, Romania, Spain, and Switzerland. Eligible patients were male, aged 18 years or older, with histologically confirmed or cytologically confirmed de novo metastatic prostate adenocarcinoma, and an Eastern Cooperative Oncology Group performance status of 0-1 (or 2 due to bone pain). Participants were randomly assigned (1:1:1:1) to standard of care (androgen deprivation therapy alone or with intravenous docetaxel 75 mg/m 2 once every 3 weeks), standard of care plus radiotherapy, standard of care plus abiraterone (oral 1000 mg abiraterone once daily plus oral 5 mg prednisone twice daily), or standard of care plus radiotherapy plus abiraterone. Neither the investigators nor the patients were masked to treatment allocation. The coprimary endpoints were radiographic progression-free survival and overall survival. Abiraterone efficacy was first assessed in the overall population and then in the population who received androgen deprivation therapy with docetaxel as standard of care (population of interest). This study is ongoing and is registered with ClinicalTrials.gov, NCT01957436.\n\nFindings: Between Nov 27, 2013, and Dec 20, 2018, 1173 patients were enrolled (one patient subsequently withdrew consent for analysis of his data) and assigned to receive standard of care (n=296), standard of care plus radiotherapy (n=293), standard of care plus abiraterone (n=292), or standard of care plus radiotherapy plus abiraterone (n=291). Median follow-up was 3·5 years (IQR 2·8-4·6) for radiographic progression-free survival and 4·4 years (3·5-5·4) for overall survival. Adjusted Cox regression modelling revealed no interaction between abiraterone and radiotherapy, enabling the pooled analysis of abiraterone efficacy. In the overall population, patients assigned to receive abiraterone (n=583) had longer radiographic progression-free survival (hazard ratio [HR] 0·54, 99·9% CI 0·41-0·71; p<0·0001) and overall survival (0·82, 95·1% CI 0·69-0·98; p=0·030) than patients who did not receive abiraterone (n=589). In the androgen deprivation therapy with docetaxel population (n=355 in both with abiraterone and without abiraterone groups), the HRs were consistent (radiographic progression-free survival 0·50, 99·9% CI 0·34-0·71; p<0·0001; overall survival 0·75, 95·1% CI 0·59-0·95; p=0·017). In the androgen deprivation therapy with docetaxel population, grade 3 or worse adverse events occurred in 217 (63%) of 347 patients who received abiraterone and 181 (52%) of 350 who did not; hypertension had the largest difference in occurrence (76 [22%] patients and 45 [13%], respectively). Addition of abiraterone to androgen deprivation therapy plus docetaxel did not increase the rates of neutropenia, febrile neutropenia, fatigue, or neuropathy compared with androgen deprivation therapy plus docetaxel alone.\n\nInterpretation: Combining androgen deprivation therapy, docetaxel, and abiraterone in de novo metastatic castration-sensitive prostate cancer improved overall survival and radiographic progression-free survival with a modest increase in toxicity, mostly hypertension. This triplet therapy could become a standard of care for these patients.\n\nFunding: Janssen-Cilag, Ipsen, Sanofi, and the French Government.\n\nIndexed on Europe PMC as PubMed record 35405085 (DOI 10.1016/s0140-6736(22)00367-1). Its abstract cites the registry id NCT01957436, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2022, doi: "10.1016/s0140-6736(22)00367-1", pmid: "35405085", authors: "Fizazi K, Foulon S, Carles J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01957436 with the most citations, so it is the natural first reading for anyone following the PEACE-1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2022","url":"https://doi.org/10.1016/s0140-6736(22)00367-1"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35405085/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35405085"},{"label":"ClinicalTrials.gov NCT01957436","url":"https://clinicaltrials.gov/study/NCT01957436"}], tags: ["europepmc-ingest"], trials: ["peace-1"], journals: ["lancet"] }),
  p({ id: "paper-propel-lancet-oncol-2023", name: "Olaparib plus abiraterone versus placebo plus abiraterone in metastatic castration-resistant prostate cancer (PROpel): final prespecified overall survival results of a randomised, double-blind, phase 3 trial", tldr: "Published report from the PROpel trial registered as NCT03732820, in The Lancet Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: PROpel met its primary endpoint showing statistically significant improvement in radiographic progression-free survival with olaparib plus abiraterone versus placebo plus abiraterone in patients with first-line metastatic castration-resistant prostate cancer (mCRPC) unselected by homologous recombination repair mutation (HRRm) status, with benefit observed in all prespecified subgroups. Here we report the final prespecified overall survival analysis.\n\nMethods: This was a randomised, double-blind, phase 3 trial done at 126 centres in 17 countries worldwide. Patients with mCRPC aged at least 18 years, Eastern Cooperative Oncology Group performance status 0-1, a life expectancy of at least 6 months, with no previous systemic treatment for mCRPC and unselected by HRRm status were randomly assigned (1:1) centrally by means of an interactive voice response system-interactive web response system to abiraterone acetate (orally, 1000 mg once daily) plus prednisone or prednisolone with either olaparib (orally, 300 mg twice daily) or placebo. The patients, the investigator, and study centre staff were masked to drug allocation. Stratification factors were site of metastases and previous docetaxel at metastatic hormone-sensitive cancer stage. Radiographic progression-free survival was the primary endpoint and overall survival was a key secondary endpoint with alpha-control (alpha-threshold at prespecified final analysis: 0·0377 [two-sided]), evaluated in the intention-to-treat population. Safety was evaluated in all patients who received at least one dose of a study drug. This study is registered with ClinicalTrials.gov, NCT03732820, and is completed and no longer recruiting.\n\nFindings: Between Oct 31, 2018 and March 11, 2020, 1103 patients were screened, of whom 399 were randomly assigned to olaparib plus abiraterone and 397 to placebo plus abiraterone. Median follow-up for overall survival in patients with censored data was 36·6 months (IQR 34·1-40·3) for olaparib plus abiraterone and 36·5 months (33·8-40·3) for placebo plus abiraterone. Median overall survival was 42·1 months (95% CI 38·4-not reached) with olaparib plus abiraterone and 34·7 months (31·0-39·3) with placebo plus abiraterone (hazard ratio 0·81, 95% CI 0·67-1·00; p=0·054). The most common grade 3-4 adverse event was anaemia reported in 64 (16%) of 398 patients in the olaparib plus abiraterone and 13 (3%) of 396 patients in the placebo plus abiraterone group. Serious adverse events were reported in 161 (40%) in the olaparib plus abiraterone group and 126 (32%) in the placebo plus abiraterone group. One death in the placebo plus abiraterone group, from interstitial lung disease, was considered treatment related.\n\nInterpretation: Overall survival was not significantly different between treatment groups at this final prespecified analysis.\n\nFunding: Supported by AstraZeneca and Merck Sharp & Dohme.\n\nIndexed on Europe PMC as PubMed record 37714168 (DOI 10.1016/s1470-2045(23)00382-0). Its abstract cites the registry id NCT03732820, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2023, doi: "10.1016/s1470-2045(23)00382-0", pmid: "37714168", authors: "Saad F, Clarke NW, Oya M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03732820 with the most citations, so it is the natural first reading for anyone following the PROpel trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2023","url":"https://doi.org/10.1016/s1470-2045(23)00382-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37714168/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37714168"},{"label":"ClinicalTrials.gov NCT03732820","url":"https://clinicaltrials.gov/study/NCT03732820"}], tags: ["europepmc-ingest"], trials: ["propel"], journals: ["lancet-oncology"] }),
  p({ id: "paper-psmaddition-lancet-2026", name: "[ 177 Lu]Lu-PSMA-617 in patients with PSMA-positive metastatic androgen pathway modulator-naive/sensitive prostate cancer (PSMAddition): a phase 3 randomised, controlled trial", tldr: "Published report from the PSMAddition trial registered as NCT04720157, in The Lancet (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: A contemporary standard of care for patients with metastatic androgen pathway modulator-naive/sensitive (APMN/S) prostate cancer (also known as metastatic hormone-sensitive prostate cancer) is androgen deprivation therapy (ADT) plus an androgen receptor pathway inhibitor (ARPI) until progression. PSMAddition aimed to evaluate the efficacy and safety of [ 177 Lu]Lu-PSMA-617 ( 177 Lu-PSMA-617) combined with ADT plus ARPI in prostate-specific membrane antigen (PSMA)-positive metastatic APMN/S prostate cancer.\n\nMethods: PSMAddition is an ongoing, randomised, controlled, phase 3 superiority trial conducted at 169 sites across 20 countries, including hospitals, medical centres, and specialist cancer centres. Eligible male patients had treatment-naive or minimally treated metastatic APMN/S prostate cancer diagnosed by CT, MRI, or bone scan and one or more PSMA-positive metastatic lesion on centrally read baseline [ 68 Ga]Ga-PSMA-11 PET. Patients were randomly assigned 1:1 to open-label, intravenous 177 Lu-PSMA-617 (7·4 GBq [200 mCi] ±10% every 6 weeks for up to six cycles) with ADT plus ARPI ( 177 Lu-PSMA-617 arm) or ADT plus ARPI (control arm). ADT and ARPI were investigator-chosen according to local authorisation and administered per local product labelling. Control arm patients with centrally confirmed radiographic progression could cross over to 177 Lu-PSMA-617. The primary endpoint was radiographic progression-free survival (centrally assessed per Prostate Cancer Clinical Trials Working Group 3-modified RECIST 1.1 or death); secondary endpoints included safety and tolerability. We report the second interim analysis of radiographic progression-free survival in the intention-to-treat population (all randomly assigned participants; data cutoff Jan 13, 2025). Safety was assessed in all patients who received at least one dose of study treatment. This study is registered with ClinicalTrials.gov, NCT04720157, and is ongoing.\n\nFindings: From June 15, 2021, to July 25, 2023, 1529 patients were screened and 1144 were randomly assigned (n=572 per arm; 1144 [100%] male, 572 [50%] with de novo metastatic APMN/S prostate cancer, 779 [68%] with high-volume disease; median age 68·0 years [IQR 62·0-73·0]). Baseline characteristics were balanced between arms. At second interim analysis for radiographic progression-free survival (median time from randomisation to data cutoff 23·6 months [IQR 20·3-29·2]; median radiographic progression-free survival follow-up time 19·6 months [IQR 14·0-24·1]), 139 (24%) of 572 participants in the 177 Lu-PSMA-617 arm and 172 (30%) of 572 participants in the control arm had radiographic disease progression or death. Radiographic progression-free survival was significantly improved in the 177 Lu-PSMA-617 arm versus the control arm, with a 28% reduction in the relative risk of radiographic progression or death (HR 0·72 [95% CI 0·58-0·90]; p=0·0021; median radiographic progression-free survival not reached in either arm). The primary endpoint was thus met. Grade 3 or worse adverse events occurred in 286 (51%) of 564 patients in the 177 Lu-PSMA-617 arm and 243 (43%) of 565 patients in the control arm. Serious adverse events occurred in 180 (32%) of 564 patients in the 177 Lu-PSMA-617 arm and 162 (29%) of 565 in the control arm; of which 17 (3%) in the 177 Lu-PSMA-617 arm were 177 Lu-PSMA-617-related. The most common adverse event was dry mouth, in 258 (46%) patients in the 177 Lu-PSMA-617 arm and 21 (4%) patients in the control arm; all were grade 1 or 2 and none were serious. Other common adverse events with higher incidence in the 177 Lu-PSMA-617 arm included cytopenias and gastrointestinal disturbances.\n\nInterpretation: Combining 177 Lu-PSMA-617 with ADT plus ARPI prolonged radiographic progression-free survival in patients with PSMA-positive metastatic APMN/S prostate cancer. Although adverse events were more frequent, there were no unexpected safety findings associated with the drug combination. Therefore, combining 177 Lu-PSMA-617 with ADT plus ARPI might be a new treatment option in metastatic APMN/S prostate cancer.\n\nFunding: Novartis.\n\nIndexed on Europe PMC as PubMed record 42561994 (DOI 10.1016/s0140-6736(26)01092-5). Its abstract cites the registry id NCT04720157, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2026, doi: "10.1016/s0140-6736(26)01092-5", pmid: "42561994", authors: "Tagawa ST, Sartor O, Piulats JM, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04720157 with the most citations, so it is the natural first reading for anyone following the PSMAddition trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2026","url":"https://doi.org/10.1016/s0140-6736(26)01092-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42561994/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42561994"},{"label":"ClinicalTrials.gov NCT04720157","url":"https://clinicaltrials.gov/study/NCT04720157"}], tags: ["europepmc-ingest"], trials: ["psmaddition"], journals: ["lancet"] }),
  p({ id: "paper-psmafore-lancet-2024", name: "177 Lu-PSMA-617 versus a change of androgen receptor pathway inhibitor therapy for taxane-naive patients with progressive metastatic castration-resistant prostate cancer (PSMAfore): a phase 3, randomised, controlled trial", tldr: "Published report from the PSMAfore trial registered as NCT04689828, in The Lancet (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: [ 177 Lu]Lu-PSMA-617 ( 177 Lu-PSMA-617) prolongs radiographic progression-free survival and overall survival in patients with metastatic castration-resistant prostate cancer previously treated with androgen receptor pathway inhibitor (ARPI) and taxane therapy. We aimed to investigate the efficacy of 177 Lu-PSMA-617 in patients with taxane-naive metastatic castration-resistant prostate cancer.\n\nMethods: In this phase 3, randomised, controlled trial conducted at 74 sites across Europe and North America, taxane-naive patients with prostate-specific membrane antigen (PSMA)-positive metastatic castration-resistant prostate cancer who had progressed once on a previous ARPI were randomly allocated (1:1) to open-label, intravenous 177 Lu-PSMA-617 at a dosage of 7·4 GBq (200 mCi) ± 10% once every 6 weeks for six cycles, or a change of ARPI (to abiraterone or enzalutamide, administered orally on a continuous basis per product labelling). Crossover from ARPI change to 177 Lu-PSMA-617 was allowed after centrally confirmed radiographic progression. The primary endpoint was radiographic progression-free survival, defined as the time from randomisation until radiographic progression or death, assessed in the intention-to-treat population. Safety was a secondary endpoint. This study is registered with ClinicalTrials.gov (NCT04689828) and is ongoing. In this primary report of the study, we present primary (first data cutoff) and updated (third data cutoff) analyses of radiographic progression-free survival; all other data are based on the third data cutoff.\n\nFindings: Overall, of the 585 patients screened, 468 met all eligibility criteria and were randomly allocated between June 15, 2021 and Oct 7, 2022 to receive 177 Lu-PSMA-617 (234 [50%] patients) or ARPI change (234 [50%]). Baseline characteristics were mostly similar between groups; median number of 177 Lu-PSMA-617 cycles was 6·0 (IQR 4·0-6·0). Of patients assigned to ARPI change, 134 (57%) crossed over to receive 177 Lu-PSMA-617. In the primary analysis (median time from randomisation to first data cutoff 7·26 months [IQR 3·38-10·55]), the median radiographic progression-free survival was 9·30 months (95% CI 6·77-not estimable) in the 177 Lu-PSMA-617 group versus 5·55 months (4·04-5·95) in the ARPI change group (hazard ratio [HR] 0·41 [95% CI 0·29-0·56]; p<0·0001). In the updated analysis at time of the third data cutoff (median time from randomisation to third data cutoff 24·11 months [IQR 20·24-27·40]), median radiographic progression-free survival was 11·60 months (95% CI 9·30-14·19) in the 177 Lu-PSMA-617 group versus 5·59 months (4·21-5·95) in the ARPI change group (HR 0·49 [95% CI 0·39-0·61]). The incidence of grade 3-5 adverse events was lower in the 177 Lu-PSMA-617 group (at least one event in 81 [36%] of 227 patients; four [2%] grade 5 [none treatment related]) than the ARPI change group (112 [48%] of 232; five [2%] grade 5 [one treatment related]).\n\nInterpretation: 177 Lu-PSMA-617 prolonged radiographic progression-free survival relative to ARPI change, with a favourable safety profile. For patients with PSMA-positive metastatic castration-resistant prostate cancer who are being considered for a change of ARPI after progression on a previous ARPI, 177 Lu-PSMA-617 may be an effective treatment alternative.\n\nFunding: Novartis.\n\nIndexed on Europe PMC as PubMed record 39293462 (DOI 10.1016/s0140-6736(24)01653-2). Its abstract cites the registry id NCT04689828, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2024, doi: "10.1016/s0140-6736(24)01653-2", pmid: "39293462", authors: "Morris MJ, Castellano D, Herrmann K, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04689828 with the most citations, so it is the natural first reading for anyone following the PSMAfore trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2024","url":"https://doi.org/10.1016/s0140-6736(24)01653-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39293462/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39293462"},{"label":"ClinicalTrials.gov NCT04689828","url":"https://clinicaltrials.gov/study/NCT04689828"}], tags: ["europepmc-ingest"], trials: ["psmafore"], journals: ["lancet"] }),
  p({ id: "paper-rtog-9601-n-engl-j-med-2017", name: "Radiation with or without Antiandrogen Therapy in Recurrent Prostate Cancer", tldr: "Published report from the RTOG 9601 trial registered as NCT00002874, in New England Journal of Medicine (2017), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Salvage radiation therapy is often necessary in men who have undergone radical prostatectomy and have evidence of prostate-cancer recurrence signaled by a persistently or recurrently elevated prostate-specific antigen (PSA) level. Whether antiandrogen therapy with radiation therapy will further improve cancer control and prolong overall survival is unknown.\n\nMethods: In a double-blind, placebo-controlled trial conducted from 1998 through 2003, we assigned 760 eligible patients who had undergone prostatectomy with a lymphadenectomy and had disease, as assessed on pathological testing, with a tumor stage of T2 (confined to the prostate but with a positive surgical margin) or T3 (with histologic extension beyond the prostatic capsule), no nodal involvement, and a detectable PSA level of 0.2 to 4.0 ng per milliliter to undergo radiation therapy and receive either antiandrogen therapy (24 months of bicalutamide at a dose of 150 mg daily) or daily placebo tablets during and after radiation therapy. The primary end point was the rate of overall survival.\n\nResults: The median follow-up among the surviving patients was 13 years. The actuarial rate of overall survival at 12 years was 76.3% in the bicalutamide group, as compared with 71.3% in the placebo group (hazard ratio for death, 0.77; 95% confidence interval, 0.59 to 0.99; P=0.04). The 12-year incidence of death from prostate cancer, as assessed by means of central review, was 5.8% in the bicalutamide group, as compared with 13.4% in the placebo group (P<0.001). The cumulative incidence of metastatic prostate cancer at 12 years was 14.5% in the bicalutamide group, as compared with 23.0% in the placebo group (P=0.005). The incidence of late adverse events associated with radiation therapy was similar in the two groups. Gynecomastia was recorded in 69.7% of the patients in the bicalutamide group, as compared with 10.9% of those in the placebo group (P<0.001).\n\nConclusions: The addition of 24 months of antiandrogen therapy with daily bicalutamide to salvage radiation therapy resulted in significantly higher rates of long-term overall survival and lower incidences of metastatic prostate cancer and death from prostate cancer than radiation therapy plus placebo. (Funded by the National Cancer Institute and AstraZeneca; RTOG 9601 ClinicalTrials.gov number, NCT00002874.).\n\nIndexed on Europe PMC as PubMed record 28146658 (DOI 10.1056/nejmoa1607529). Its abstract cites the registry id NCT00002874, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2017, doi: "10.1056/nejmoa1607529", pmid: "28146658", authors: "Shipley WU, Seiferheld W, Lukka HR, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00002874 with the most citations, so it is the natural first reading for anyone following the RTOG 9601 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2017","url":"https://doi.org/10.1056/nejmoa1607529"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28146658/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28146658"},{"label":"ClinicalTrials.gov NCT00002874","url":"https://clinicaltrials.gov/study/NCT00002874"}], tags: ["europepmc-ingest"], trials: ["rtog-9601"], journals: ["nejm"] }),
  p({ id: "paper-splash-front-oncol-2024", name: "Initial clinical experience with [ 177 Lu]Lu-PNT2002 radioligand therapy in metastatic castration-resistant prostate cancer: dosimetry, safety, and efficacy from the lead-in cohort of the SPLASH trial", tldr: "Published report from the SPLASH trial registered as NCT04647526, in Frontiers in oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: SPLASH (NCT04647526) is a multicenter phase III trial evaluating the efficacy and safety of [ 177 Lu]Lu-PNT2002 radioligand therapy in metastatic castration-resistant prostate cancer (mCRPC). This study leveraged a lead-in phase to assess tissue dosimetry and evaluate preliminary safety and efficacy, prior to expansion into a randomized phase. Here we report those results.\n\nMethods: Enrolled participants had mCRPC that progressed on one prior androgen receptor pathway inhibitor (ARPI), were prostate-specific membrane antigen (PSMA) PET-positive as determined by a central reader, were chemotherapy-naïve for mCRPC, and had adequate bone marrow and end-organ reserve. Participants received up to 4 cycles of [ 177 Lu]Lu-PNT2002 at 6.8 GBq (± 10%) intravenously per cycle every 8 weeks. Dosimetry (planar + SPECT/CT [n=7]; planar only [n=20]), safety, prostate-specific antigen (PSA) response, objective response rate (ORR), and radiographic progression-free survival (rPFS) per blinded independent central review were assessed.\n\nResults: Of 34 individuals screened, 32 underwent PSMA-PET/CT; 27 met all eligibility criteria. Median (range) age was 72 (57-86) years; all participants were enrolled in North America; 40.7% initiated prior ARPI treatment without distant metastases (M0) and 25.9% while hormone sensitive. Nineteen of 27 (70.4%) participants completed all 4 planned cycles. Organs receiving the largest mean (median, range) specific absorbed doses were lacrimal glands at 1.2 (0.9, 0.4-6.7) Gy/GBq (planar only [n=27]), followed by kidneys at 0.73 (0.63, 0.22-1.8) Gy/GBq (planar + SPECT/CT [n=7]; planar only [n=20]). Mean (median, range) tumor specific absorbed dose was 4.3 (2.1, 0.3-33.4) Gy/GBq (approximately 29 Gy/cycle) based on planar + SPECT/CT of 21 lesions in seven participants. [ 177 Lu]Lu-PNT2002 was associated with no treatment-related deaths, few treatment-related grade ≥3 treatment-emergent adverse events (TEAEs), and no discontinuations for unacceptable toxicity. Treatment-related TEAEs occurring in ≥10% of participants included dry mouth (22.2%; all grade 1), fatigue (18.5%; grades 1-2), nausea (18.5%; grades 1-2), and anemia (14.8%; grades 1-3). Median (95% CI) rPFS was 11.5 (9.2-19.1) months, a PSA decline of ≥50% occurred in 42.3% (11/26) of participants, and confirmed ORR for evaluable disease was 50% (5/10).\n\nConclusion: [ 177 Lu]Lu-PNT2002, administered at 6.8 GBq/cycle for 4 cycles, demonstrated a favorable dosimetry and safety profile, as well as promising preliminary efficacy.\n\nClinical trial registration: https://clinicaltrials.gov/, identifier NCT04647526.\n\nIndexed on Europe PMC as PubMed record 39839782 (DOI 10.3389/fonc.2024.1483953). Its abstract cites the registry id NCT04647526, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Frontiers in oncology", year: 2024, doi: "10.3389/fonc.2024.1483953", pmid: "39839782", authors: "Hansen AR, Probst S, Beauregard JM, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04647526 with the most citations, so it is the natural first reading for anyone following the SPLASH trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Front Oncol 2024","url":"https://doi.org/10.3389/fonc.2024.1483953"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39839782/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39839782"},{"label":"ClinicalTrials.gov NCT04647526","url":"https://clinicaltrials.gov/study/NCT04647526"}], tags: ["europepmc-ingest"], trials: ["splash"] }),
  p({ id: "paper-stampede-lancet-2016", name: "Addition of docetaxel, zoledronic acid, or both to first-line long-term hormone therapy in prostate cancer (STAMPEDE): survival results from an adaptive, multiarm, multistage, platform randomised controlled trial", tldr: "Published report from the STAMPEDE trial registered as NCT00268476, in The Lancet (2016), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Long-term hormone therapy has been the standard of care for advanced prostate cancer since the 1940s. STAMPEDE is a randomised controlled trial using a multiarm, multistage platform design. It recruits men with high-risk, locally advanced, metastatic or recurrent prostate cancer who are starting first-line long-term hormone therapy. We report primary survival results for three research comparisons testing the addition of zoledronic acid, docetaxel, or their combination to standard of care versus standard of care alone.\n\nMethods: Standard of care was hormone therapy for at least 2 years; radiotherapy was encouraged for men with N0M0 disease to November, 2011, then mandated; radiotherapy was optional for men with node-positive non-metastatic (N+M0) disease. Stratified randomisation (via minimisation) allocated men 2:1:1:1 to standard of care only (SOC-only; control), standard of care plus zoledronic acid (SOC + ZA), standard of care plus docetaxel (SOC + Doc), or standard of care with both zoledronic acid and docetaxel (SOC + ZA + Doc). Zoledronic acid (4 mg) was given for six 3-weekly cycles, then 4-weekly until 2 years, and docetaxel (75 mg/m(2)) for six 3-weekly cycles with prednisolone 10 mg daily. There was no blinding to treatment allocation. The primary outcome measure was overall survival. Pairwise comparisons of research versus control had 90% power at 2·5% one-sided α for hazard ratio (HR) 0·75, requiring roughly 400 control arm deaths. Statistical analyses were undertaken with standard log-rank-type methods for time-to-event data, with hazard ratios (HRs) and 95% CIs derived from adjusted Cox models. This trial is registered at ClinicalTrials.gov (NCT00268476) and ControlledTrials.com (ISRCTN78818544).\n\nFindings: 2962 men were randomly assigned to four groups between Oct 5, 2005, and March 31, 2013. Median age was 65 years (IQR 60-71). 1817 (61%) men had M+ disease, 448 (15%) had N+/X M0, and 697 (24%) had N0M0. 165 (6%) men were previously treated with local therapy, and median prostate-specific antigen was 65 ng/mL (IQR 23-184). Median follow-up was 43 months (IQR 30-60). There were 415 deaths in the control group (347 [84%] prostate cancer). Median overall survival was 71 months (IQR 32 to not reached) for SOC-only, not reached (32 to not reached) for SOC + ZA (HR 0·94, 95% CI 0·79-1·11; p=0·450), 81 months (41 to not reached) for SOC + Doc (0·78, 0·66-0·93; p=0·006), and 76 months (39 to not reached) for SOC + ZA + Doc (0·82, 0·69-0·97; p=0·022). There was no evidence of heterogeneity in treatment effect (for any of the treatments) across prespecified subsets. Grade 3-5 adverse events were reported for 399 (32%) patients receiving SOC, 197 (32%) receiving SOC + ZA, 288 (52%) receiving SOC + Doc, and 269 (52%) receiving SOC + ZA + Doc.\n\nInterpretation: Zoledronic acid showed no evidence of survival improvement and should not be part of standard of care for this population. Docetaxel chemotherapy, given at the time of long-term hormone therapy initiation, showed evidence of improved survival accompanied by an increase in adverse events. Docetaxel treatment should become part of standard of care for adequately fit men commencing long-term hormone therapy.\n\nFunding: Cancer Research UK, Medical Research Council, Novartis, Sanofi-Aventis, Pfizer, Janssen, Astellas, NIHR Clinical Research Network, Swiss Group for Clinical Cancer Research.\n\nIndexed on Europe PMC as PubMed record 26719232 (DOI 10.1016/s0140-6736(15)01037-5). Its abstract cites the registry id NCT00268476, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2016, doi: "10.1016/s0140-6736(15)01037-5", pmid: "26719232", authors: "James ND, Sydes MR, Clarke NW, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00268476 with the most citations, so it is the natural first reading for anyone following the STAMPEDE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2016","url":"https://doi.org/10.1016/s0140-6736(15)01037-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/26719232/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/26719232"},{"label":"ClinicalTrials.gov NCT00268476","url":"https://clinicaltrials.gov/study/NCT00268476"}], tags: ["europepmc-ingest"], trials: ["stampede"], journals: ["lancet"] }),
  p({ id: "paper-stampede-plos-med-2022-update", name: "Radiotherapy to the prostate for men with metastatic prostate cancer in the UK and Switzerland: Long-term results from the STAMPEDE randomised controlled trial", tldr: "Later report from the STAMPEDE trial registered as NCT00268476, in PLOS Medicine (2022); its title describes an updated or longer-term analysis.", summary: "Background: STAMPEDE has previously reported that radiotherapy (RT) to the prostate improved overall survival (OS) for patients with newly diagnosed prostate cancer with low metastatic burden, but not those with high-burden disease. In this final analysis, we report long-term findings on the primary outcome measure of OS and on the secondary outcome measures of symptomatic local events, RT toxicity events, and quality of life (QoL).\n\nMethods and findings: Patients were randomised at secondary care sites in the United Kingdom and Switzerland between January 2013 and September 2016, with 1:1 stratified allocation: 1,029 to standard of care (SOC) and 1,032 to SOC+RT. No masking of the treatment allocation was employed. A total of 1,939 had metastatic burden classifiable, with 42% low burden and 58% high burden, balanced by treatment allocation. Intention-to-treat (ITT) analyses used Cox regression and flexible parametric models (FPMs), adjusted for stratification factors age, nodal involvement, the World Health Organization (WHO) performance status, regular aspirin or nonsteroidal anti-inflammatory drug (NSAID) use, and planned docetaxel use. QoL in the first 2 years on trial was assessed using prospectively collected patient responses to QLQ-30 questionnaire. Patients were followed for a median of 61.3 months. Prostate RT improved OS in patients with low, but not high, metastatic burden (respectively: 202 deaths in SOC versus 156 in SOC+RT, hazard ratio (HR) = 0·64, 95% CI 0.52, 0.79, p < 0.001; 375 SOC versus 386 SOC+RT, HR = 1.11, 95% CI 0.96, 1.28, p = 0·164; interaction p < 0.001). No evidence of difference in time to symptomatic local events was found. There was no evidence of difference in Global QoL or QLQ-30 Summary Score. Long-term urinary toxicity of grade 3 or worse was reported for 10 SOC and 10 SOC+RT; long-term bowel toxicity of grade 3 or worse was reported for 15 and 11, respectively.\n\nConclusions: Prostate RT improves OS, without detriment in QoL, in men with low-burden, newly diagnosed, metastatic prostate cancer, indicating that it should be recommended as a SOC.\n\nTrial registration: ClinicalTrials.gov NCT00268476, ISRCTN.com ISRCTN78818544.\n\nIndexed on Europe PMC as PubMed record 35671327 (DOI 10.1371/journal.pmed.1003998). Its abstract cites the registry id NCT00268476, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "PLOS Medicine", year: 2022, doi: "10.1371/journal.pmed.1003998", pmid: "35671327", authors: "Parker CC, James ND, Brawley CD, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the STAMPEDE trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"PLoS Med 2022","url":"https://doi.org/10.1371/journal.pmed.1003998"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35671327/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35671327"},{"label":"ClinicalTrials.gov NCT00268476","url":"https://clinicaltrials.gov/study/NCT00268476"}], tags: ["europepmc-ingest"], trials: ["stampede"], journals: ["plos-medicine"] }),
  p({ id: "paper-talapro-2-lancet-2023", name: "Talazoparib plus enzalutamide in men with first-line metastatic castration-resistant prostate cancer (TALAPRO-2): a randomised, placebo-controlled, phase 3 trial", tldr: "Published report from the TALAPRO-2 trial registered as NCT03395197, in The Lancet (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Co-inhibition of poly(ADP-ribose) polymerase (PARP) and androgen receptor activity might result in antitumour efficacy irrespective of alterations in DNA damage repair genes involved in homologous recombination repair (HRR). We aimed to compare the efficacy and safety of talazoparib (a PARP inhibitor) plus enzalutamide (an androgen receptor blocker) versus enzalutamide alone in patients with metastatic castration-resistant prostate cancer (mCRPC).\n\nMethods: TALAPRO-2 is a randomised, double-blind, phase 3 trial of talazoparib plus enzalutamide versus placebo plus enzalutamide as first-line therapy in men (age ≥18 years [≥20 years in Japan]) with asymptomatic or mildly symptomatic mCRPC receiving ongoing androgen deprivation therapy. Patients were enrolled from 223 hospitals, cancer centres, and medical centres in 26 countries in North America, Europe, Israel, South America, South Africa, and the Asia-Pacific region. Patients were prospectively assessed for HRR gene alterations in tumour tissue and randomly assigned (1:1) to talazoparib 0·5 mg or placebo, plus enzalutamide 160 mg, administered orally once daily. Randomisation was stratified by HRR gene alteration status (deficient vs non-deficient or unknown) and previous treatment with life-prolonging therapy (docetaxel or abiraterone, or both: yes vs no) in the castration-sensitive setting. The sponsor, patients, and investigators were masked to talazoparib or placebo, while enzalutamide was open-label. The primary endpoint was radiographic progression-free survival (rPFS) by blinded independent central review, evaluated in the intention-to-treat population. Safety was evaluated in all patients who received at least one dose of study drug. This study is registered with ClinicalTrials.gov (NCT03395197) and is ongoing.\n\nFindings: Between Jan 7, 2019, and Sept 17, 2020, 805 patients were enrolled and randomly assigned (402 to the talazoparib group and 403 to the placebo group). Median follow-up for rPFS was 24·9 months (IQR 21·9-30·2) for the talazoparib group and 24·6 months (14·4-30·2) for the placebo group. At the planned primary analysis, median rPFS was not reached (95% CI 27·5 months-not reached) for talazoparib plus enzalutamide and 21·9 months (16·6-25·1) for placebo plus enzalutamide (hazard ratio 0·63; 95% CI 0·51-0·78; p<0·0001). In the talazoparib group, the most common treatment-emergent adverse events were anaemia, neutropenia, and fatigue; the most common grade 3-4 event was anaemia (185 [46%] of 398 patients), which improved after dose reduction, and only 33 (8%) of 398 patients discontinued talazoparib due to anaemia. Treatment-related deaths occurred in no patients in the talazoparib group and two patients (<1%) in the placebo group.\n\nInterpretation: Talazoparib plus enzalutamide resulted in clinically meaningful and statistically significant improvement in rPFS versus standard of care enzalutamide as first-line treatment for patients with mCRPC. Final overall survival data and additional long-term safety follow-up will further clarify the clinical benefit of the treatment combination in patients with and without tumour HRR gene alterations.\n\nFunding: Pfizer.\n\nIndexed on Europe PMC as PubMed record 37285865 (DOI 10.1016/s0140-6736(23)01055-3). Its abstract cites the registry id NCT03395197, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2023, doi: "10.1016/s0140-6736(23)01055-3", pmid: "37285865", authors: "Agarwal N, Azad AA, Carles J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03395197 with the most citations, so it is the natural first reading for anyone following the TALAPRO-2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2023","url":"https://doi.org/10.1016/s0140-6736(23)01055-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37285865/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37285865"},{"label":"ClinicalTrials.gov NCT03395197","url":"https://clinicaltrials.gov/study/NCT03395197"}], tags: ["europepmc-ingest"], trials: ["talapro-2"], journals: ["lancet"] }),
  p({ id: "paper-talapro-2-lancet-2025-update", name: "Talazoparib plus enzalutamide in men with metastatic castration-resistant prostate cancer: final overall survival results from the randomised, placebo-controlled, phase 3 TALAPRO-2 trial", tldr: "Later report from the TALAPRO-2 trial registered as NCT03395197, in The Lancet (2025); its title describes an updated or longer-term analysis.", summary: "Background: The primary analysis of this phase 3 trial combining talazoparib with enzalutamide demonstrated significantly improved radiographic progression-free survival (rPFS) versus enzalutamide plus placebo in patients with metastatic castration-resistant prostate cancer unselected for homologous recombination repair (HRR) gene alterations. Overall survival data were immature at that time. Here we report the final prespecified overall survival analysis, an updated descriptive analysis of rPFS, and safety in the cohort unselected for HRR gene alterations.\n\nMethods: TALAPRO-2 was a randomised, double-blind, placebo-controlled, phase 3 trial. In the genetically unselected cohort, patients were randomly assigned from 200 centres, including hospitals, cancer centres, and medical centres, in 26 countries in North America, Europe, Israel, South America, South Africa, and the Asia-Pacific region. Adult men (aged ≥18 years [≥20 years in Japan]) with asymptomatic or mildly symptomatic metastatic castration-resistant prostate cancer receiving ongoing androgen deprivation therapy, and with no previous life-prolonging systemic therapy for castration-resistant prostate cancer, were randomly assigned (1:1) to talazoparib 0·5 mg plus enzalutamide 160 mg or enzalutamide plus placebo, administered orally once daily as initial treatment for metastatic castration-resistant prostate cancer, stratified by HRR gene alteration status (HRR-deficient vs HRR-non-deficient or unknown) and previous treatment for castration-sensitive disease (yes vs no). The sponsor, patients, and investigators were masked to talazoparib or placebo, and enzalutamide was open label. The primary endpoint was rPFS by blinded independent central review, and overall survival (time from randomisation to death due to any cause) was an event-based α-protected key secondary endpoint (α-threshold at final overall survival analysis was 0·022 [two-sided])-both assessed in the intention-to-treat population. Follow-up for overall survival was intended to continue until the planned final analysis. Safety was assessed in patients who received at least one dose of a study drug. This study is registered with ClinicalTrials.gov, NCT03395197, and is ongoing.\n\nFindings: Between Jan 7, 2019, and Sept 17, 2020, 993 patients were assessed for eligibility, of whom 188 (19%) patients were excluded and 805 (81%) patients were enrolled and randomly assigned (402 [50%] to talazoparib plus enzalutamide, 403 [50%] to enzalutamide plus placebo). At a median follow-up of 52·5 months (IQR 48·6-56·0), overall survival was significantly improved with talazoparib plus enzalutamide compared with enzalutamide plus placebo (hazard ratio [HR] 0·80 [95% CI 0·66-0·96]; p=0·016); median overall survival was 45·8 months (95% CI 39·4-50·8) in the talazoparib group compared with 37·0 months (34·1-40·4) in the control group. Overall survival favoured talazoparib plus enzalutamide over enzalutamide plus placebo in HRR-deficient patients (n=169; HR 0·55 [0·36-0·83]; p=0·0035) and to a lesser extent in HRR-non-deficient or unknown patients (n=636; HR 0·88 [0·71-1·08]; p=0·22). Updated rPFS also favoured talazoparib plus enzalutamide (HR 0·67 [0·55-0·81]; p<0·0001); median rPFS was 33·1 months for talazoparib plus enzalutamide versus 19·5 months for enzalutamide plus placebo. Safety was consistent with the known profile of talazoparib; common grade 3 or higher adverse events with talazoparib plus enzalutamide were anaemia (195 [49%] vs 18 [4%] patients with enzalutamide plus placebo) and neutropenia (77 [19%] vs six [1%] patients with enzalutamide plus placebo).\n\nInterpretation: Combining talazoparib with enzalutamide significantly improved overall survival in patients with metastatic castration-resistant prostate cancer, supporting this combination as a standard-of-care initial treatment option for these patients.\n\nFunding: Pfizer.\n\nIndexed on Europe PMC as PubMed record 40683290 (DOI 10.1016/s0140-6736(25)00684-1). Its abstract cites the registry id NCT03395197, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2025, doi: "10.1016/s0140-6736(25)00684-1", pmid: "40683290", authors: "Agarwal N, Azad AA, Carles J, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the TALAPRO-2 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet 2025","url":"https://doi.org/10.1016/s0140-6736(25)00684-1"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40683290/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40683290"},{"label":"ClinicalTrials.gov NCT03395197","url":"https://clinicaltrials.gov/study/NCT03395197"}], tags: ["europepmc-ingest"], trials: ["talapro-2"], journals: ["lancet"] }),
  p({ id: "paper-therap-lancet-2021", name: "[ 177 Lu]Lu-PSMA-617 versus cabazitaxel in patients with metastatic castration-resistant prostate cancer (TheraP): a randomised, open-label, phase 2 trial", tldr: "Published report from the TheraP trial registered as NCT03392428, in The Lancet (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Lutetium-177 [ 177 Lu]Lu-PSMA-617 is a radiolabelled small molecule that delivers β radiation to cells expressing prostate-specific membrane antigen (PSMA), with activity and safety in patients with metastatic castration-resistant prostate cancer. We aimed to compare [ 177 Lu]Lu-PSMA-617 with cabazitaxel in patients with metastatic castration-resistant prostate cancer.\n\nMethods: We did this multicentre, unblinded, randomised phase 2 trial at 11 centres in Australia. We recruited men with metastatic castration-resistant prostate cancer for whom cabazitaxel was considered the next appropriate standard treatment. Participants were required to have adequate renal, haematological, and liver function, and an Eastern Cooperative Oncology Group performance status of 0-2. Previous treatment with androgen receptor-directed therapy was allowed. Men underwent gallium-68 [ 68 Ga]Ga-PSMA-11 and 2-flourine-18[ 18 F]fluoro-2-deoxy-D-glucose (FDG) PET-CT scans. PET eligibility criteria for the trial were PSMA-positive disease, and no sites of metastatic disease with discordant FDG-positive and PSMA-negative findings. Men were randomly assigned (1:1) to [ 177 Lu]Lu-PSMA-617 (6·0-8·5 GBq intravenously every 6 weeks for up to six cycles) or cabazitaxel (20 mg/m 2 intravenously every 3 weeks for up to ten cycles). The primary endpoint was prostate-specific antigen (PSA) response defined by a reduction of at least 50% from baseline. This trial is registered with ClinicalTrials.gov, NCT03392428.\n\nFindings: Between Feb 6, 2018, and Sept 3, 2019, we screened 291 men, of whom 200 were eligible on PET imaging. Study treatment was received by 98 (99%) of 99 men randomly assigned to [ 177 Lu]Lu-PSMA-617 versus 85 (84%) of 101 randomly assigned to cabazitaxel. PSA responses were more frequent among men in the [ 177 Lu]Lu-PSMA-617 group than in the cabazitaxel group (65 vs 37 PSA responses; 66% vs 37% by intention to treat; difference 29% (95% CI 16-42; p<0·0001; and 66% vs 44% by treatment received; difference 23% [9-37]; p=0·0016). Grade 3-4 adverse events occurred in 32 (33%) of 98 men in the [ 177 Lu]Lu-PSMA-617 group versus 45 (53%) of 85 men in the cabazitaxel group. No deaths were attributed to [ 177 Lu]Lu-PSMA-617.\n\nInterpretation: [ 177 Lu]Lu-PSMA-617 compared with cabazitaxel in men with metastatic castration-resistant prostate cancer led to a higher PSA response and fewer grade 3 or 4 adverse events. [ 177 Lu]Lu-PSMA-617 is a new effective class of therapy and a potential alternative to cabazitaxel.\n\nFunding: Prostate Cancer Foundation of Australia, Endocyte (a Novartis company), Australian Nuclear Science and Technology Organization, Movember, The Distinguished Gentleman's Ride, It's a Bloke Thing, and CAN4CANCER.\n\nIndexed on Europe PMC as PubMed record 33581798 (DOI 10.1016/s0140-6736(21)00237-3). Its abstract cites the registry id NCT03392428, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2021, doi: "10.1016/s0140-6736(21)00237-3", pmid: "33581798", authors: "Hofman MS, Emmett L, Sandhu S, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03392428 with the most citations, so it is the natural first reading for anyone following the TheraP trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2021","url":"https://doi.org/10.1016/s0140-6736(21)00237-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33581798/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33581798"},{"label":"ClinicalTrials.gov NCT03392428","url":"https://clinicaltrials.gov/study/NCT03392428"}], tags: ["europepmc-ingest"], trials: ["therap"], journals: ["lancet"] }),
  p({ id: "paper-therap-lancet-oncol-2024-update", name: "Overall survival with [ 177 Lu]Lu-PSMA-617 versus cabazitaxel in metastatic castration-resistant prostate cancer (TheraP): secondary outcomes of a randomised, open-label, phase 2 trial", tldr: "Later report from the TheraP trial registered as NCT03392428, in The Lancet Oncology (2024); its title describes an updated or longer-term analysis.", summary: "Background: The TheraP study reported improved prostate-specific antigen responses with lutetium-177 [ 177 Lu]Lu-PSMA-617 versus cabazitaxel in men with metastatic castration-resistant prostate cancer progressing after docetaxel. In this Article, we report the secondary outcome of overall survival with mature follow-up, and an updated imaging biomarker analysis. We also report the outcomes of participants excluded due to ineligibility on gallium-68 [ 68 Ga]Ga-PSMA-11 and 2-[ 18 F]fluoro-2-deoxy-D-glucose (2-[ 18 F]FDG) PET-CT.\n\nMethods: TheraP was an open-label, randomised phase 2 trial at 11 centres in Australia. Eligible participants had metastatic castration-resistant prostate cancer progressing after docetaxel, and PET imaging with [ 68 Ga]Ga-PSMA-11 and 2-[ 18 F]FDG that showed prostate-specific membrane antigen (PSMA)-positive disease and no sites of metastatic disease with discordant 2-[ 18 F]FDG-positive and PSMA-negative findings. Participants were randomly assigned (1:1) to treatment with [ 177 Lu]Lu-PSMA-617 (every 6 weeks for a maximum of six cycles; starting at 8·5 GBq, decreasing by 0.5 GBq to 6·0 GBq for the sixth cycle) versus cabazitaxel (20 mg/m 2 every 3 weeks, maximum of ten cycles). Overall survival was analysed by intention-to-treat and summarised as restricted mean survival time (RMST) to account for non-proportional hazards, with a 36-month restriction time corresponding to median follow-up. This trial is registered with ClinicalTrials.gov, NCT03392428, and is complete.\n\nFindings: 291 men were registered from Feb 6, 2018, to Sept 3, 2019; after study imaging, 200 were eligible and randomly assigned to treatment with [ 177 Lu]Lu-PSMA-617 (n=99) or cabazitaxel (n=101). After completing study treatment, 20 (20%) participants assigned to cabazitaxel and 32 (32%) assigned to [ 177 Lu]Lu-PSMA-617 were subsequently treated with the alternative regimen. After a median follow-up of 35·7 months (IQR 31·1 to 39·2), 77 (78%) participants had died in the [ 177 Lu]Lu-PSMA-617 group and 70 (69%) participants had died in the cabazitaxel group. Overall survival was similar among those assigned to [ 177 Lu]Lu-PSMA-617 versus those assigned to cabazitaxel (RMST 19·1 months [95% CI 16·9 to 21·4] vs 19·6 months [17·4 to 21·8]; difference -0·5 months [95% CI -3·7 to 2·7]; p=0·77). No additional safety signals were identified with the longer follow-up in this analysis. 80 (27%) of 291 men who were registered after initial eligibility screening were excluded after [ 68 Ga]Ga-PSMA-11 and 2-[ 18 F]FDG PET. In the 61 of these men with follow-up available, RMST was 11·0 months (95% CI 9·0 to 13·1).\n\nInterpretation: These results support the use of [ 177 Lu]Lu-PSMA-617 as an alternative to cabazitaxel for PSMA-positive metastatic castration-resistant prostate cancer progressing after docetaxel. We did not find evidence that overall survival differed between the randomised groups. Median overall survival was shorter for men who were excluded because of low PSMA expression or 2-[ 18 F]FDG-discordant disease.\n\nFunding: Australian and New Zealand Urogenital and Prostate Cancer Trials Group, Prostate Cancer Foundation of Australia, Endocyte (a Novartis company), Australian Nuclear Science and Technology Organization, Movember, It's a Bloke Thing, CAN4CANCER, and The Distinguished Gentleman's Ride.\n\nIndexed on Europe PMC as PubMed record 38043558 (DOI 10.1016/s1470-2045(23)00529-6). Its abstract cites the registry id NCT03392428, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2024, doi: "10.1016/s1470-2045(23)00529-6", pmid: "38043558", authors: "Hofman MS, Emmett L, Sandhu S, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the TheraP trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2024","url":"https://doi.org/10.1016/s1470-2045(23)00529-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38043558/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38043558"},{"label":"ClinicalTrials.gov NCT03392428","url":"https://clinicaltrials.gov/study/NCT03392428"}], tags: ["europepmc-ingest"], trials: ["therap"], journals: ["lancet-oncology"] }),
  p({ id: "paper-protect-bju-int-2026-update", name: "Long-term outcomes of cribriform-positive and cribriform-negative prostate cancer treated with radical prostatectomy in the ProtecT trial", tldr: "Later report from the ProtecT trial registered as NCT02044172, in BJU international (2026); its title describes an updated or longer-term analysis.", summary: "Objectives: To retrospectively analyse the results of the Prostate Testing for Cancer and Treatment (ProtecT; ClinicalTrials.gov identifier: NCT02044172) trial to establish the association between cribriform-positive and -negative prostate cancer (PCa) and the 15-year risk of metastasis or death from PCa in patients who underwent radical prostatectomy (RP).\n\nPatients and methods: Between 1999 and 2009, the ProtecT phase 3 clinical trial enrolled 1643 men with clinically localised PCa who were randomised to receive active monitoring, RP, or radiotherapy. In this secondary analysis of the trial, a centralised histopathological review was conducted on available RP pathology slides to classify patients as cribriform-positive if they had invasive cribriform carcinoma and/or intraductal carcinoma. The primary outcome was a composite of progression to metastatic disease or death from PCa. Exposures included age, prostate-specific antigen density, RP Grade Group (GG), pathological T stage (pT), and cribriform status. Multivariable Cox proportional hazards regression models assessed 15-year risk. Cumulative incidence curves were compared using the Gray test.\n\nResults: Of 480 men with RP specimens reviewed, 143 (30%) had cribriform-positive disease and 337 (70%) had cribriform-negative disease. All 21 metastatic or lethal events occurred exclusively in the cribriform-positive group (15-year cumulative incidence 14%). Within the cribriform-positive cohort, risk was concentrated in patients with pT3b stage and/or GG ≥3 (15-year cumulative incidence 27%). In multivariable analysis of cribriform-positive patients, pT3b stage (hazard ratio [HR] 8.19, 95% confidence interval [CI] 2.39-28.10; P < 0.001) and GG 3 disease (HR 5.12, 95% CI 1.59-16.40; P = 0.006) were independent predictors of adverse outcomes. Conversely, cribriform-positive patients with GG 2 and ≤pT3a had a 15-year event rate of only 3%.\n\nConclusion: In the ProtecT trial, the 15-year risk of metastasis or death after RP was a binary outcome defined by cribriform status. The concentration of risk in men with cribriform-positive, high-grade and/or pT3b tumours identifies a target population for adjuvant therapy trials, while supporting management de-escalation for most RP patients.\n\nIndexed on Europe PMC as PubMed record 41896701 (DOI 10.1111/bju.70261). Its abstract cites the registry id NCT02044172, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "BJU international", year: 2026, doi: "10.1111/bju.70261", pmid: "41896701", authors: "Sushentsev N, Warren AY, Colling R, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the ProtecT trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"BJU Int 2026","url":"https://doi.org/10.1111/bju.70261"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41896701/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41896701"},{"label":"ClinicalTrials.gov NCT02044172","url":"https://clinicaltrials.gov/study/NCT02044172"}], tags: ["europepmc-ingest"], trials: ["protect"] }),
  p({ id: "paper-nct01436968-lancet-oncol-2026", name: "Aglatimagene besadenovec (CAN-2409) with radiotherapy for patients with localised prostate cancer: a phase 3, multicentre, randomised, double-blind, placebo-controlled trial", tldr: "Published report from the trial registered as NCT01436968, in The Lancet Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: About 30% of men with localised prostate cancer undergoing radiotherapy with curative intent have disease recurrence associated with progression-related symptoms and substantial toxicity of salvage therapies. Previous studies with aglatimagene besadenovec (CAN-2409, hereafter referred to as aglatimagene) showed synergy with radiation and immune-mediated cytotoxicity in patients with prostate cancer. We aimed to assess whether addition of aglatimagene plus prodrug (valacyclovir) to standard-of-care external beam radiation therapy (EBRT) could improve disease-free survival in this population.\n\nMethods: We conducted a phase 3, randomised, double-blind, placebo-controlled trial at 51 medical centres (26 community and 25 institutional or military) across the USA and Puerto Rico in patients with intermediate or high-risk prostate cancer. Patients aged at least 18 years who were planning to undergo EBRT and with an Eastern Cooperative Oncology Group score of 0-2 were eligible. Patients were randomly assigned (2:1) via central block-randomisation to receive either three courses of intraprostatic aglatimagene (5 × 10 11 viral particles) plus valacyclovir or placebo plus valacyclovir, with randomisation stratified by risk category and androgen deprivation therapy (ADT) use. Patients received standard-of-care EBRT (78 Gy in 2 Gy fractions) or hypofractionated EBRT (60 Gy in 3 Gy fractions or 70 Gy in 2·5 Gy fractions) with optional ADT. The primary endpoint was disease-free survival, defined as time-from-randomisation to prostate cancer recurrence or death in the intent-to-treat population (all randomly assigned patients). Safety was assessed in all individuals who received at least one injection. The trial is registered at ClinicalTrials.gov, NCT01436968, and long-term follow-up is ongoing.\n\nFindings: Between Feb 21, 2012, and Sept 9, 2021, 745 men (591 [79%] White, 121 [16%] Black) were randomly assigned to receive aglatimagene plus valacyclovir (n=496) or placebo plus valacyclovir (n=249). After a median follow-up of 50·3 months (IQR 35·2-63·3), median disease-free survival was not reached (95% CI 121·78 to not reached) in the aglatimagene plus valacyclovir group versus 86·1 (IQR 29·7-143·0) months in the placebo plus valacyclovir group (hazard ratio 0·70, 95% CI 0·52-0·94; p=0·016). Treatment-emergent adverse events (TEAEs) of grade 3 or worse occurred in 40 (8%) of 479 patients in the aglatimagene group and 17 (7%)of 232 patients in the placebo group. The most common TEAE of grade 3 or worse was acute kidney injury in both the aglatimagene group (nine [2%] of 479 patients) and the placebo group (four [2%] of 232 patients). Serious adverse events occurred in 28 (6%) of 479 patients in the aglatimagene group and 17 (7%) of 232 in the placebo group. Treatment-related serious adverse events occurred in eight (2%) patients in the aglatimagene group (four acute kidney injury, two pyrexia, and one each influenza-like symptoms and urinary retention) and five (2%) in the placebo group (four acute kidney injury, and one each increased creatinine levels and skin rash; one patient reported two serious adverse events). No treatment-related deaths were reported.\n\nInterpretation: Aglatimagene plus valacyclovir was associated with longer disease-free survival than placebo plus valacyclovir when added to standard of radiotherapy for the treatment of localised prostate cancer, offering a meaningful benefit without increasing clinically significant toxicity.\n\nFunding: Candel Therapeutics and US National Institutes of Health.\n\nIndexed on Europe PMC as PubMed record 42225101 (DOI 10.1016/s1470-2045(26)00071-9). Its abstract cites the registry id NCT01436968, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2026, doi: "10.1016/s1470-2045(26)00071-9", pmid: "42225101", authors: "DeWeese TL, Manzanera A, Sylvester J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01436968 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2026","url":"https://doi.org/10.1016/s1470-2045(26)00071-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42225101/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42225101"},{"label":"ClinicalTrials.gov NCT01436968","url":"https://clinicaltrials.gov/study/NCT01436968"}], tags: ["europepmc-ingest"], trials: ["nct01436968"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct02257736-lancet-oncol-2021", name: "Apalutamide plus abiraterone acetate and prednisone versus placebo plus abiraterone and prednisone in metastatic, castration-resistant prostate cancer (ACIS): a randomised, placebo-controlled, double-blind, multinational, phase 3 study", tldr: "Published report from the trial registered as NCT02257736, in The Lancet Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The majority of patients with metastatic castration-resistant prostate cancer (mCRPC) will have disease progression of a uniformly fatal disease. mCRPC is driven by both activated androgen receptors and elevated intratumoural androgens; however, the current standard of care is therapy that targets a single androgen signalling mechanism. We aimed to investigate the combination treatment using apalutamide plus abiraterone acetate, each of which suppresses the androgen signalling axis in a different way, versus standard care in mCRPC.\n\nMethods: ACIS was a randomised, placebo-controlled, double-blind, phase 3 study done at 167 hospitals in 17 countries in the USA, Canada, Mexico, Europe, the Asia-Pacific region, Africa, and South America. We included chemotherapy-naive men (aged ≥18 years) with mCRPC who had not been previously treated with androgen biosynthesis signalling inhibitors and were receiving ongoing androgen deprivation therapy, with an Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1, and a Brief Pain Inventory-Short Form question 3 (ie, worst pain in the past 24 h) score of 3 or lower. Patients were randomly assigned (1:1) via a centralised interactive web response system with a permuted block randomisation scheme (block size 4) to oral apalutamide 240 mg once daily plus oral abiraterone acetate 1000 mg once daily and oral prednisone 5 mg twice daily (apalutamide plus abiraterone-prednisone group) or placebo plus abiraterone acetate and prednisone (abiraterone-prednisone group), in 28-day treatment cycles. Randomisation was stratified by presence or absence of visceral metastases, ECOG performance status, and geographical region. Patients, the investigators, study team, and the sponsor were masked to group assignments. An independent data-monitoring committee continually monitored data to ensure ongoing patient safety, and reviewed efficacy data. The primary endpoint was radiographic progression-free survival assessed in the intention-to-treat population. Safety was reported for all patients who received at least one dose of study drug. This study is completed and no longer recruiting and is registered with ClinicalTrials.gov, number NCT02257736.\n\nFindings: 982 men were enrolled and randomly assigned from Dec 10, 2014 to Aug 30, 2016 (492 to apalutamide plus abiraterone-prednisone; 490 to abiraterone-prednisone). At the primary analysis (median follow-up 25·7 months [IQR 23·0-28·9]), median radiographic progression-free survival was 22·6 months (95% CI 19·4-27·4) in the apalutamide plus abiraterone-prednisone group versus 16·6 months (13·9-19·3) in the abiraterone-prednisone group (hazard ratio [HR] 0·69, 95% CI 0·58-0·83; p<0·0001). At the updated analysis (final analysis for overall survival; median follow-up 54·8 months [IQR 51·5-58·4]), median radiographic progression-free survival was 24·0 months (95% CI 19·7-27·5) versus 16·6 months (13·9-19·3; HR 0·70, 95% CI 0·60-0·83; p<0·0001). The most common grade 3-4 treatment-emergent adverse event was hypertension (82 [17%] of 490 patients receiving apalutamide plus abiraterone-prednisone and 49 [10%] of 489 receiving abiraterone-prednisone). Serious treatment-emergent adverse events occurred in 195 (40%) patients receiving apalutamide plus abiraterone-prednisone and 181 (37%) patients receiving abiraterone-prednisone. Drug-related treatment-emergent adverse events with fatal outcomes occurred in three (1%) patients in the apalutamide plus abiraterone-prednisone group (2 pulmonary embolism, 1 cardiac failure) and five (1%) patients in the abiraterone-prednisone group (1 cardiac failure and 1 cardiac arrest, 1 mesenteric arterial occlusion, 1 seizure, and 1 sudden death).\n\nInterpretation: Despite the use of an active and established therapy as the comparator, apalutamide plus abiraterone-prednisone improved radiographic progression-free survival. Additional studies to identify subgroups of patients who might benefit the most from combination therapy are needed to further refine the treatment of mCRPC.\n\nFunding: Janssen Research & Development.\n\nIndexed on Europe PMC as PubMed record 34600602 (DOI 10.1016/s1470-2045(21)00402-2). Its abstract cites the registry id NCT02257736, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2021, doi: "10.1016/s1470-2045(21)00402-2", pmid: "34600602", authors: "Saad F, Efstathiou E, Attard G, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02257736 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2021","url":"https://doi.org/10.1016/s1470-2045(21)00402-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34600602/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34600602"},{"label":"ClinicalTrials.gov NCT02257736","url":"https://clinicaltrials.gov/study/NCT02257736"}], tags: ["europepmc-ingest"], trials: ["nct02257736"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct02489318-n-engl-j-med-2019", name: "Apalutamide for Metastatic, Castration-Sensitive Prostate Cancer", tldr: "Published report from the TITAN trial registered as NCT02489318, in New England Journal of Medicine (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Apalutamide is an inhibitor of the ligand-binding domain of the androgen receptor. Whether the addition of apalutamide to androgen-deprivation therapy (ADT) would prolong radiographic progression-free survival and overall survival as compared with placebo plus ADT among patients with metastatic, castration-sensitive prostate cancer has not been determined.\n\nMethods: In this double-blind, phase 3 trial, we randomly assigned patients with metastatic, castration-sensitive prostate cancer to receive apalutamide (240 mg per day) or placebo, added to ADT. Previous treatment for localized disease and previous docetaxel therapy were allowed. The primary end points were radiographic progression-free survival and overall survival.\n\nResults: A total of 525 patients were assigned to receive apalutamide plus ADT and 527 to receive placebo plus ADT. The median age was 68 years. A total of 16.4% of the patients had undergone prostatectomy or received radiotherapy for localized disease, and 10.7% had received previous docetaxel therapy; 62.7% had high-volume disease, and 37.3% had low-volume disease. At the first interim analysis, with a median of 22.7 months of follow-up, the percentage of patients with radiographic progression-free survival at 24 months was 68.2% in the apalutamide group and 47.5% in the placebo group (hazard ratio for radiographic progression or death, 0.48; 95% confidence interval [CI], 0.39 to 0.60; P<0.001). Overall survival at 24 months was also greater with apalutamide than with placebo (82.4% in the apalutamide group vs. 73.5% in the placebo group; hazard ratio for death, 0.67; 95% CI, 0.51 to 0.89; P = 0.005). The frequency of grade 3 or 4 adverse events was 42.2% in the apalutamide group and 40.8% in the placebo group; rash was more common in the apalutamide group.\n\nConclusions: In this trial involving patients with metastatic, castration-sensitive prostate cancer, overall survival and radiographic progression-free survival were significantly longer with the addition of apalutamide to ADT than with placebo plus ADT, and the side-effect profile did not differ substantially between the two groups. (Funded by Janssen Research and Development; TITAN ClinicalTrials.gov number, NCT02489318.).\n\nIndexed on Europe PMC as PubMed record 31150574 (DOI 10.1056/nejmoa1903307). Its abstract cites the registry id NCT02489318, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2019, doi: "10.1056/nejmoa1903307", pmid: "31150574", authors: "Chi KN, Agarwal N, Bjartell A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02489318 with the most citations, so it is the natural first reading for anyone following the TITAN trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2019","url":"https://doi.org/10.1056/nejmoa1903307"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31150574/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31150574"},{"label":"ClinicalTrials.gov NCT02489318","url":"https://clinicaltrials.gov/study/NCT02489318"}], tags: ["europepmc-ingest"], trials: ["nct02489318"], journals: ["nejm"] }),
  p({ id: "paper-nct02861573-eur-urol-2022", name: "Pembrolizumab Plus Docetaxel and Prednisone in Patients with Metastatic Castration-resistant Prostate Cancer: Long-term Results from the Phase 1b/2 KEYNOTE-365 Cohort B Study", tldr: "Published report from the KEYNOTE-365 trial registered as NCT02861573, in European Urology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Patients with metastatic castration-resistant prostate cancer (mCRPC) frequently receive docetaxel after they develop resistance to abiraterone or enzalutamide and need more efficacious treatments.\n\nObjective: To evaluate the efficacy and safety of pembrolizumab plus docetaxel and prednisone in patients with mCRPC.\n\nDesign, setting, and participants: The trial included patients with mCRPC in the phase 1b/2 KEYNOTE-365 cohort B study who were chemotherapy naïve and who experienced failure of or were intolerant to ≥4 wk of abiraterone or enzalutamide for mCRPC with progressive disease within 6 mo of screening.\n\nIntervention: Pembrolizumab 200 mg intravenously (IV) every 3 wk (Q3W), docetaxel 75 mg/m 2 IV Q3W, and prednisone 5 mg orally twice daily.\n\nOutcome measurements and statistical analysis: The primary endpoints were safety, the prostate-specific antigen (PSA) response rate, and the objective response rate (ORR) according to Response Evaluation Criteria in Solid Tumors version 1.1 (RECIST v1.1) by blinded independent central review (BICR). Secondary endpoints included time to PSA progression; the disease control rate (DCR) and duration of response (DOR) according to RECIST v1.1 by BICR; ORR, DCR, DOR, and radiographic progression-free survival (rPFS) according to Prostate Cancer Working Group 3-modified RECIST v1.1 by BICR; and overall survival (OS).\n\nResults and limitations: Among 104 treated patients, 52 had measurable disease. The median time from allocation to data cutoff (July 9, 2020) was 32.4 mo, during which 101 patients discontinued treatment, 81 (78%) for disease progression. The confirmed PSA response rate was 34% and the confirmed ORR (RECIST v1.1) was 23%. Median rPFS and OS were 8.5 mo and 20.2 mo, respectively. Treatment-related adverse events (TRAEs) occurred in 100 patients (96%). Grade 3-5 TRAEs occurred in 46 patients (44%). Seven AE-related deaths (6.7%) occurred (2 due to treatment-related pneumonitis). Limitations of the study include the single-arm design and small sample size.\n\nConclusions: Pembrolizumab plus docetaxel and prednisone demonstrated antitumor activity in chemotherapy-naïve patients with mCRPC treated with abiraterone or enzalutamide for mCRPC. Safety was consistent with profiles for the individual agents. Further investigation is warranted.\n\nPatient summary: We evaluated the efficacy and safety of the anti-PD-1 antibody pembrolizumab combined with the chemotherapy drug docetaxel and the steroid prednisone for patients with metastatic prostate cancer resistant to androgen deprivation therapy, and who never received chemotherapy. The combination showed antitumor activity and manageable safety in this patient population. This trial is registered on ClinicalTrials.gov as NCT02861573.\n\nIndexed on Europe PMC as PubMed record 35397952 (DOI 10.1016/j.eururo.2022.02.023). Its abstract cites the registry id NCT02861573, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "European Urology", year: 2022, doi: "10.1016/j.eururo.2022.02.023", pmid: "35397952", authors: "Yu EY, Kolinsky MP, Berry WR, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02861573 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-365 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Eur Urol 2022","url":"https://doi.org/10.1016/j.eururo.2022.02.023"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35397952/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35397952"},{"label":"ClinicalTrials.gov NCT02861573","url":"https://clinicaltrials.gov/study/NCT02861573"}], tags: ["europepmc-ingest"], trials: ["nct02861573"], journals: ["european-urology"] }),
  p({ id: "paper-nct03436485-nejm-evid-2024", name: "Targeted Inhibition of CYP11A1 in Castration-Resistant Prostate Cancer", tldr: "Published report from the CYPIDES trial registered as NCT03436485, in NEJM Evidence (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "BACKGROUND: Prostate cancer is regulated by steroid hormones, even in castration-resistant disease. ODM-208, a novel inhibitor of cytochrome P450 11A1 (which catalyzes the first step of steroid-hormone biosynthesis), was investigated in patients with heavily pretreated metastatic castration-resistant prostate cancer (mCRPC). METHODS: CYPIDES is a first-in-human phase 1 (3 + 3 design) and phase 2 study. We administered ODM-208 twice daily with glucocorticoid/mineralocorticoid replacement and ongoing androgen deprivation therapy to adults with previously treated mCRPC, regardless of androgen receptor gene (AR) ligand-binding domain mutations (phase 1) and with activating AR ligand-binding domain mutations (ARmut; phase 2). Safety, pharmacokinetics, steroid-hormone pharmacodynamics, and preliminary efficacy were the key outcomes. RESULTS: Ninety-two patients received one or more doses of ODM-208: 47 in phase 1 (20 [42.6%] with ARmut) and 45 in phase 2 (all ARmut). A dose of ODM-208 of 5 mg twice a day with dexamethasone 1 mg/fludrocortisone 0.1 mg provided a balance between decreased steroidogenesis and toxicity. Treatment-related adrenal insufficiency was the most common toxicity in phase 1 (n=17, 36.2%; necessitating ODM-208 discontinuation in one patient); this toxicity occurred in six patients (13.3%) at 5 mg twice a day in phase 2. Median circulating testosterone levels declined from 3.0 ng/dl (interquartile range, 1.3 to 6.2 ng/dl) at baseline to undetectable levels within the first week of ODM-208 5 mg twice a day treatment in 46 of 53 (87%) patients. A decrease in prostate-specific antigen levels of 50% or more occurred in 14 of 19 (73.7%) patients with ARmut and 2 of 23 (8.7%) patients with AR wild type in phase 1 and in 24 of 45 (53.3%) patients with ARmut in phase 2. CONCLUSIONS: ODM-208 potently inhibited steroid-hormone biosynthesis with the expected toxicity of adrenal insufficiency. Evidence of antitumor activity was observed in this heavily pretreated mCRPC population, especially in those with ARmut. (Funded by Orion Pharma; ClinicalTrials.gov number, NCT03436485.)\n\nIndexed on Europe PMC as PubMed record 38320513 (DOI 10.1056/evidoa2300171). Its abstract cites the registry id NCT03436485, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "NEJM Evidence", year: 2024, doi: "10.1056/evidoa2300171", pmid: "38320513", authors: "Fizazi K, Bernard-Tessier A, Roubaud G, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03436485 with the most citations, so it is the natural first reading for anyone following the CYPIDES trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"NEJM Evid 2024","url":"https://doi.org/10.1056/evidoa2300171"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38320513/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38320513"},{"label":"ClinicalTrials.gov NCT03436485","url":"https://clinicaltrials.gov/study/NCT03436485"}], tags: ["europepmc-ingest"], trials: ["nct03436485"], journals: ["nejm-evidence"] }),
  p({ id: "paper-nct03706365-lancet-oncol-2025", name: "Abemaciclib plus abiraterone in patients with metastatic castration-resistant prostate cancer (CYCLONE 2): a randomised, double-blind, placebo-controlled, phase 3 trial", tldr: "Published report from the CYCLONE 2 trial registered as NCT03706365, in The Lancet Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Abemaciclib, a potent CDK4 and CDK6 inhibitor, has shown antitumour activity in prostate cancer models and in patients with metastatic castration-resistant prostate cancer (mCRPC) who have been heavily treated. We aimed to evaluate the safety and efficacy of abemaciclib in combination with abiraterone in patients with mCRPC.\n\nMethods: CYCLONE 2 was a randomised, double-blind, placebo-controlled, phase 3 study done in 89 hospitals and academic and private research centres in 12 countries. All study parts had identical eligibility criteria, and used block randomisation with the same stratification factors (previous docetaxel treatment, presence of measurable disease, and type of progression). Participants were adults aged 18 years and older with histologically confirmed adenocarcinoma of the prostate and metastatic disease as documented by bone scans, CT scans, or MRI scans, and radiographic or PSA progression during continuous androgen deprivation therapy. Previous docetaxel for metastatic castration-sensitive prostate cancer was permitted; previous abiraterone, apalutamide, enzalutamide, darolutamide, or CDK4 and CDK6 inhibitors were exclusionary. The trial was conducted in three parts. Part 1 was a four-arm, placebo-controlled safety and dose-finding lead-in to determine the recommended phase 2 dose of abemaciclib with abiraterone. Participants were randomly assigned (2:2:1:1) to receive abiraterone (1000 mg orally once daily) and prednisone or prednisolone (5 mg orally twice daily) with either abemaciclib at 150 mg or 200 mg orally twice daily or with matching placebo (150 mg or 200 mg twice daily). In part 2 and part 3, patients were randomly assigned (1:1) to standard abiraterone and prednisone or prednisolone plus either abemaciclib at the recommended phase 2 dose or matching placebo. Patients, investigators, and sponsor were masked to treatment assignment. The primary outcome, investigator-assessed radiographic progression-free survival, was analysed in the intention-to-treat (participants from all study parts) population. Patients who received at least one dose of abiraterone, abemaciclib, or placebo were included in the safety population. This trial is registered at ClinicalTrials.gov, NCT03706365, and is completed.\n\nFindings: Between Nov 26, 2018, and July 20, 2022, 515 patients were screened for eligibility, 393 of whom were randomly assigned, 206 patients to abemaciclib plus abiraterone and 187 to placebo plus abiraterone. The median age was 70·0 years (IQR 63·0-76·0). 289 (74%) of 393 patients identified as White, 80 (20%) as Asian, 17 (4%) as Black or African American, and seven (2%) as multiple race or not reported. The highest tested dose of 200 mg abemaciclib administered twice daily was chosen as the recommended phase 2 dose. The median follow-up time was 26·3 months (IQR 22·1-48·2) for the abemaciclib plus abiraterone group and 25·6 months (22·1-40·8) for the placebo plus abiraterone group. The primary endpoint of radiographic progression-free survival was not met: radiographic progression-free survival events were reported in 92 (45%) of 206 patients in the abemaciclib plus abiraterone group and 95 (51%) of 187 patients in the placebo plus abiraterone group (HR 0·83 [95% CI 0·62-1·11]; p=0·21). Median radiographic progression-free survival was 22·0 months (95% CI 19·3-27·5) for abemaciclib plus abiraterone and 20·3 months (16·5-24·4) for placebo plus abiraterone. The most common grade 3 or higher adverse events reported in the abemaciclib plus abiraterone group were anaemia (28 [14%] of 206 vs eight [4%] of 185 in the placebo plus abiraterone group), neutropenia (26 [13%] vs one [1%]), and alanine aminotransferase increase (18 [9%] vs 12 [6%]). Serious adverse events occurred in 91 (44%) of 206 patients in the abemaciclib plus abiraterone group and in 68 (37%) of 185 patients in the placebo plus abiraterone group. There were three treatment-related deaths due to interstitial lung disease in the abemaciclib plus abiraterone group.\n\nInterpretation: Dual inhibition of CDK4 and CDK6 and the androgen receptor pathway with abemaciclib plus abiraterone did not improve radiographic progression-free survival compared with abiraterone alone in the CYCLONE 2 study population with mCRPC. Safety of the combination was consistent with the previously reported safety of the individual drugs. Additional research is required to identify effective combination therapies for patients with mCRPC, especially in those presenting with adverse prognostic characteristics.\n\nFunding: Eli Lilly.\n\nIndexed on Europe PMC as PubMed record 41167216 (DOI 10.1016/s1470-2045(25)00475-9). Its abstract cites the registry id NCT03706365, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2025, doi: "10.1016/s1470-2045(25)00475-9", pmid: "41167216", authors: "Smith M, Piulats J, Todenhöfer T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03706365 with the most citations, so it is the natural first reading for anyone following the CYCLONE 2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2025","url":"https://doi.org/10.1016/s1470-2045(25)00475-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41167216/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41167216"},{"label":"ClinicalTrials.gov NCT03706365","url":"https://clinicaltrials.gov/study/NCT03706365"}], tags: ["europepmc-ingest"], trials: ["nct03706365"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct03767244-n-engl-j-med-2026", name: "Perioperative Apalutamide in High-Risk Localized Prostate Cancer", tldr: "Published report from the PROTEUS trial registered as NCT03767244, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Radical prostatectomy is potentially curative in patients with high-risk localized or locally advanced prostate cancer; however, relapse occurs within 5 years in up to 50% of patients.\n\nMethods: We conducted a phase 3, double-blind, placebo-controlled trial in which patients with newly diagnosed high-risk localized or locally advanced prostate cancer were randomly assigned in a 1:1 ratio to receive androgen-deprivation therapy (ADT) plus apalutamide (240 mg per day) or ADT plus placebo for 6 cycles (28 days each) before and after radical prostatectomy with pelvic lymph-node dissection. The dual primary end points were a composite of pathological complete response or minimal residual disease (defined as a pathological stage of ypT2 or lower, with a tumor size of ≤5 mm in the greatest dimension) and metastasis-free survival, as assessed with conventional imaging or prostate-specific membrane antigen positron-emission tomography. Secondary end points included event-free survival, first subsequent treatment, and distant metastasis (assessed in time-to-event analyses), as well as safety.\n\nResults: A total of 2109 patients underwent randomization: 1057 were assigned to receive ADT plus apalutamide, and 1052 to receive ADT plus placebo. The median follow-up was 61.7 months. The percentage of patients with a pathological complete response or minimal residual disease was significantly higher in the apalutamide group than in the placebo group (8.9% vs. 1.0%; odds ratio, 10.17; 95% confidence interval [CI], 5.27 to 19.64; P<0.001), as was the percentage of patients with metastasis-free survival (probability of metastasis-free survival at 5 years, 78.2% vs. 73.5%; hazard ratio for distant metastasis or death, 0.80; 95% CI, 0.67 to 0.96; P = 0.02). Event-free survival, time to the first subsequent treatment, and time to distant metastasis significantly favored ADT plus apalutamide over ADT plus placebo (P<0.001 for all between-group comparisons). Grade 3 or 4 adverse events occurred in 39.6% of the patients in the apalutamide group and in 31.0% of those in the placebo group, with the difference between the groups driven primarily by a higher incidence of rash in the apalutamide group.\n\nConclusions: Perioperative treatment with ADT plus apalutamide was associated with better oncologic outcomes of radical prostatectomy in patients with high-risk localized or locally advanced prostate cancer than treatment with ADT plus placebo. Adverse events were more common in the apalutamide group than in the placebo group. (Funded by Johnson & Johnson; PROTEUS ClinicalTrials.gov number, NCT03767244.).\n\nIndexed on Europe PMC as PubMed record 42223077 (DOI 10.1056/nejmoa2603878). Its abstract cites the registry id NCT03767244, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2603878", pmid: "42223077", authors: "Taplin ME, Gleave M, Shore ND, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03767244 with the most citations, so it is the natural first reading for anyone following the PROTEUS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2603878"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42223077/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42223077"},{"label":"ClinicalTrials.gov NCT03767244","url":"https://clinicaltrials.gov/study/NCT03767244"}], tags: ["europepmc-ingest"], trials: ["nct03767244"], journals: ["nejm"] }),
  p({ id: "paper-nct04446117-lancet-oncol-2025", name: "Cabozantinib plus atezolizumab in metastatic prostate cancer (CONTACT-02): final analyses from a phase 3, open-label, randomised trial", tldr: "Published report from the CONTACT-02 trial registered as NCT04446117, in The Lancet Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Patients with metastatic castration-resistant prostate cancer (mCRPC) with extrapelvic soft-tissue metastases that has progressed on an androgen receptor pathway inhibitor (ARPI) have a poor prognosis with few treatment options. We aimed to assess efficacy and safety of cabozantinib, a tyrosine kinase inhibitor with immunomodulatory properties, plus the PD-L1 inhibitor atezolizumab in these patients.\n\nMethods: CONTACT-02 is an open-label, randomised, phase 3 study that enrolled patients at 184 sites across 24 countries (in Europe, North America, Asia-Pacific, and Latin America). Men aged 18 years and older, with an Eastern Cooperative Oncology Group performance status score of 0 or 1, and who had mCRPC and measurable extrapelvic soft-tissue metastases (lymph node or visceral) that had progressed on one previous ARPI were eligible. Patients were randomly assigned 1:1 to cabozantinib (40 mg orally once daily) plus atezolizumab (1200 mg intravenously once every 3 weeks) or ARPI switch (abiraterone 1000 mg orally once-daily plus prednisone 5 mg orally twice-daily, or enzalutamide 160 mg orally once-daily) using a web-based interactive response technology system and stratified by the presence of liver metastasis, previous docetaxel therapy, and disease status at first ARPI initiation. Dual primary endpoints were progression-free survival in the first 400 randomly assigned patients (progression-free survival intention-to treat [ITT] population) and overall survival in all randomly assigned patients (ITT population). Safety was assessed in all patients who received at least one dose of study treatment. Although the study is ongoing, with some patients remaining in follow-up, this analysis represents the protocol-specified final analysis. This trial is registered with ClinicalTrials.gov, NCT04446117.\n\nFindings: Between Aug 20, 2020 and June 7, 2023, 575 patients were randomly assigned to cabozantinib plus atezolizumab (n=289) or ARPI switch (n=286). Most patients were White (440 [77%]) or Asian (78 [14%]). After a median follow-up of 11·8 months (IQR 9·9-19·3), cabozantinib plus atezolizumab significantly improved progression-free survival versus ARPI switch (median 6·3 months [95% CI 6·2-8·8] vs 4·2 months [3·7-5·7]; hazard ratio [HR] 0·65 [95% CI 0·50-0·84], p=0·0007). After a median follow-up of 23·1 months (IQR 17·4-30·5), overall survival was not significantly different between the cabozantinib plus atezolizumab and ARPI switch groups (median 14·8 months [95% CI 13·4-16·7] vs 15·0 months [13·0-18·5]; HR 0·89 [95% CI 0·72-1·10], p=0·30). Any-cause grade 3-4 adverse events occurred in 158 (56%) of 284 patients given cabozantinib plus atezolizumab and 74 (26%) of 284 patients given ARPI switch; the most common in the cabozantinib plus atezolizumab group were hypertension (24 [8%] of 284 patients) and anaemia (23 [8%]) and the most common in the ARPI switch group was anaemia (18 [6%] of 284 patients). Serious adverse events deemed related to treatment occurred in 45 (16%) of 284 patients in the cabozantinib plus atezolizumab group and in 11 (4%) of 284 patients in the ARPI switch group; the most common with cabozantinib plus atezolizumab was diarrhoea (five [2%] of 284 patients) and the most common with ARPI switch was increase in alanine aminotransferase (two [1%] of 284 patients). Adverse events of any cause led to discontinuation of all components of study treatment in 49 (17%) of 284 patients in the cabozantinib plus atezolizumab group and in 42 (15%) of 284 patients in the ARPI switch group. No treatment-related deaths occurred.\n\nInterpretation: Cabozantinib plus atezolizumab, a novel drug combination that does not directly target androgen receptor signalling, could be a useful treatment option for patients with mCRPC and soft-tissue metastases who have progressed on an ARPI.\n\nFunding: Exelixis in partnership with Ipsen, Takeda, and Roche.\n\nIndexed on Europe PMC as PubMed record 40523369 (DOI 10.1016/s1470-2045(25)00209-8). Its abstract cites the registry id NCT04446117, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2025, doi: "10.1016/s1470-2045(25)00209-8", pmid: "40523369", authors: "Agarwal N, Azad AA, Carles J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04446117 with the most citations, so it is the natural first reading for anyone following the CONTACT-02 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2025","url":"https://doi.org/10.1016/s1470-2045(25)00209-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40523369/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40523369"},{"label":"ClinicalTrials.gov NCT04446117","url":"https://clinicaltrials.gov/study/NCT04446117"}], tags: ["europepmc-ingest"], trials: ["nct04446117"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct04497844-nat-med-2025", name: "Niraparib and abiraterone acetate plus prednisone for HRR-deficient metastatic castration-sensitive prostate cancer: a randomized phase 3 trial", tldr: "Published report from the AMPLITUDE trial registered as NCT04497844, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Inhibition of poly(ADP-ribose) polymerase (PARP) after relapse on hormone therapy is well established for patients with prostate cancer with homologous recombination repair (HRR) gene alterations, but resistance often develops. We hypothesized that PARP inhibition within 6 months of starting androgen deprivation therapy for metastatic castration-sensitive prostate cancer (mCSPC) could be effective and improve radiographic progression-free survival when added to standard-of-care treatments. The double-blind AMPLITUDE trial evaluated combining niraparib, a potent and specific PARP inhibitor, with abiraterone acetate and prednisone (AAP) versus placebo and AAP in mCSPC with HRR gene alterations. Patients (n = 696) were randomized in a 1:1 ratio (348 per group). Median age was 68 years; 56% had BRCA1 or BRCA2 alterations; 78% had high-volume metastases; and 16% had received docetaxel. The primary endpoint was met, with a significant improvement in radiographic progression-free survival observed first in the BRCA subgroup (median not reached at the time of analysis for the niraparib and AAP group versus 26 months for the AAP group; hazard ratio = 0.52; 95% confidence interval: 0.37-0.72; P < 0.0001) and then in the intention-to-treat population (hazard ratio = 0.63; 95% confidence interval: 0.49-0.80; P = 0.0001). The data for overall survival, a key secondary endpoint, are immature (193/389 events) but favor niraparib (hazard ratio = 0.79 (95% confidence interval: 0.59-1.04); BRCA subgroup: hazard ratio = 0.75 (95% confidence interval: 0.51-1.11)). Incidence of grade 3 or 4 adverse events was 75% in the niraparib and AAP group and 59% in the AAP group; most frequent in the niraparib and AAP group were anemia (29%), with 25% of patients requiring a blood transfusion, and hypertension (27%). There were 14 treatment-emergent adverse events leading to deaths in the niraparib group and seven in the placebo group. Combining niraparib with AAP significantly improved radiographic progression-free survival in patients with mCSPC harboring BRCA1/BRCA2 or other HRR gene alterations, suggesting clinical benefit with this combination for these patients. ClinicalTrials.gov identifier: NCT04497844.\n\nIndexed on Europe PMC as PubMed record 41057655 (DOI 10.1038/s41591-025-03961-8). Its abstract cites the registry id NCT04497844, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-03961-8", pmid: "41057655", authors: "Attard G, Agarwal N, Graff JN, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04497844 with the most citations, so it is the natural first reading for anyone following the AMPLITUDE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-03961-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41057655/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41057655"},{"label":"ClinicalTrials.gov NCT04497844","url":"https://clinicaltrials.gov/study/NCT04497844"}], tags: ["europepmc-ingest"], trials: ["nct04497844"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct04821622-n-engl-j-med-2026", name: "PARP and Androgen-Signaling Inhibition plus ADT in Metastatic Prostate Cancer", tldr: "Published report from the TALAPRO-3 trial registered as NCT04821622, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: A previous trial involving patients with metastatic prostate cancer that was resistant to androgen pathway modulation (formerly referred to as castration-resistant) showed that adding talazoparib to enzalutamide significantly improved imaging-based progression-free survival and overall survival, with the greatest benefit observed in the cohort with alterations in homologous recombination repair genes.\n\nMethods: In this ongoing, phase 3, double-blind trial assessing talazoparib in patients with metastatic androgen pathway modulation-sensitive [APMS] prostate cancer harboring alterations in homologous recombination repair genes, we randomly assigned patients in a 1:1 ratio to receive talazoparib at a dose of 0.5 mg plus enzalutamide at a dose of 160 mg once daily (talazoparib group) or placebo plus enzalutamide at a dose of 160 mg once daily (control group). Randomization was stratified according to disease status (new or relapsed), disease volume (high or low), and BRCA (vs. non- BRCA) mutation status. The primary end point was investigator-assessed imaging-based progression-free survival. The key secondary end point was overall survival.\n\nResults: A total of 300 patients were assigned to the talazoparib group and 299 to the control group. At 3 years, progression-free survival was 77% in the talazoparib group and 56% in the control group (hazard ratio for disease progression or death, 0.48; 95% confidence interval [CI], 0.36 to 0.65; P<0.001). In this interim analysis, overall survival at 3 years was 78% in the talazoparib group and 72% in the control group (hazard ratio for death, 0.77; 95% CI, 0.56 to 1.04). Serious adverse events were reported in 42% and 32% of the patients in the talazoparib group and the control group, respectively. In the talazoparib group, the most common adverse events were anemia, fatigue, and decreased neutrophil count, and the most common event of grade 3 or higher was anemia, reported in 51% of the patients; two treatment-related deaths occurred.\n\nConclusions: Talazoparib added to enzalutamide led to significantly better imaging-based progression-free survival than placebo plus enzalutamide among patients with metastatic APMS prostate cancer harboring alterations in homologous recombination repair genes. Serious adverse events were more common with talazoparib plus enzalutamide than with placebo plus enzalutamide. (Funded by Pfizer; TALAPRO-3 ClinicalTrials.gov number, NCT04821622.).\n\nIndexed on Europe PMC as PubMed record 42223064 (DOI 10.1056/nejmoa2604126). Its abstract cites the registry id NCT04821622, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2604126", pmid: "42223064", authors: "Agarwal N, Matsubara N, Azad AA, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04821622 with the most citations, so it is the natural first reading for anyone following the TALAPRO-3 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2604126"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42223064/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42223064"},{"label":"ClinicalTrials.gov NCT04821622","url":"https://clinicaltrials.gov/study/NCT04821622"}], tags: ["europepmc-ingest"], trials: ["nct04821622"], journals: ["nejm"] }),
  p({ id: "paper-nct03851640-signal-transduct-target-ther-2026", name: "Deutenzalutamide, a novel androgen receptor inhibitor, after progression on docetaxel and abiraterone in metastatic castration-resistant prostate cancer: results from the randomized phase III HC-1119-04 trial", tldr: "Published report from the trial registered as NCT03851640, in Signal transduction and targeted therapy (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Metastatic castration-resistant prostate cancer (mCRPC) after treatment with docetaxel and androgen receptor signaling inhibitors (ARSIs) has limited treatment options. Although enzalutamide has shown activity after abiraterone and docetaxel, robust evidence from randomized phase III trials is lacking. Deutenzalutamide, a novel derivative with slower metabolism and improved pharmacokinetics, may offer enhanced safety and efficacy. This phase III, double-blind trial conducted at 36 centers in China enrolled patients whose disease progressed on or who were intolerant to abiraterone and docetaxel, or who were ineligible for docetaxel. Patients were randomized (2:1) to receive deutenzalutamide 80 mg once daily or placebo until progression or unacceptable toxicity; the primary endpoint was radiographic progression-free survival (rPFS). Of 417 patients (276 deutenzalutamide; 141 placebo), all had previously received abiraterone, and 68% had also received docetaxel. Deutenzalutamide significantly improved rPFS (HR, 0.58; P = 0.0001), reducing the risk of progression by 42%. Although the initial OS analysis was not significant (HR, 0.95), sensitivity analyses adjusting for subsequent therapies showed significant OS benefits (HR, 0.65-0.73). Treatment-related grade 3 or higher adverse events occurred in 22.3% of patients treated with deutenzalutamide, compared with 15.0% with placebo. The most common treatment-related adverse event was anemia, reported at any grade in 21.2% versus 17.9%, with grade 3/4 anemia in 6.6% versus 2.9%, respectively. Notably, no seizures or falls were reported. In summary, deutenzalutamide significantly prolonged rPFS and, after adjustment, showed a potential OS benefit with a favorable safety profile, supporting its promise as a new treatment option for mCRPC. Clinical trial registration: NCT03851640.\n\nIndexed on Europe PMC as PubMed record 41968137 (DOI 10.1038/s41392-026-02618-3). Its abstract cites the registry id NCT03851640, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Signal transduction and targeted therapy", year: 2026, doi: "10.1038/s41392-026-02618-3", pmid: "41968137", authors: "Wu J, Li X, Gu C, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03851640 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Signal Transduct Target Ther 2026","url":"https://doi.org/10.1038/s41392-026-02618-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41968137/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41968137"},{"label":"ClinicalTrials.gov NCT03851640","url":"https://clinicaltrials.gov/study/NCT03851640"}], tags: ["europepmc-ingest"], trials: ["nct03851640"] }),
  p({ id: "paper-nct05413850-j-nucl-med-2024", name: "First Safety and Efficacy Data with the Radiohybrid 177 Lu-rhPSMA-10.1 for the Treatment of Metastatic Prostate Cancer", tldr: "Published report from the trial registered as NCT05413850, in Journal of Nuclear Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "We recently published the first dosimetry data, to our knowledge, for the radioligand therapy agent 177 Lu-rhPSMA-10.1, providing an intrapatient comparison with 177 Lu-PSMA-I&T in patients with metastatic prostate cancer. Here, we report efficacy and safety findings from these patients. Methods: Four consecutive patients with prostate-specific membrane antigen (PSMA)-positive metastatic prostate cancer received up to 6 cycles of 177 Lu-rhPSMA-10.1 (7.4-7.7 GBq per cycle). Efficacy (prostate-specific antigen response according to Prostate Cancer Working Group 3 criteria and the Response Evaluation Criteria in PSMA PET/CT), progression-free survival, and overall survival were evaluated. Adverse events were recorded from the first dose until 16-24 mo after treatment. Results: The patients received a total activity of 29.6-59.4 GBq (4-6 cycles). Prostate-specific antigen was reduced by 100%, 99%, 88%, and 35%. Progression-free survival was not reached for 2 patients at 24 and 18 mo of follow-up and was 15 and 12 mo for the other 2 patients. One patient had a sustained complete response with 2 y of follow up. All patients were alive at the last time point of data collection. No serious adverse events were reported. Conclusion: 177 Lu-rhPSMA-10.1 demonstrated encouraging preliminary efficacy and was well tolerated. Formal clinical trials are now under way to evaluate its potential prospectively (NCT05413850).\n\nIndexed on Europe PMC as PubMed record 38164586 (DOI 10.2967/jnumed.123.266741). Its abstract cites the registry id NCT05413850, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Nuclear Medicine", year: 2024, doi: "10.2967/jnumed.123.266741", pmid: "38164586", authors: "Dierks A, Gäble A, Rinscheid A, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05413850 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Nucl Med 2024","url":"https://doi.org/10.2967/jnumed.123.266741"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38164586/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38164586"},{"label":"ClinicalTrials.gov NCT05413850","url":"https://clinicaltrials.gov/study/NCT05413850"}], tags: ["europepmc-ingest"], trials: ["nct05413850"], journals: ["journal-of-nuclear-medicine"] }),
  p({ id: "paper-naliricc-lancet-gastroenterol-hepatol-2024", name: "Nanoliposomal irinotecan and fluorouracil plus leucovorin versus fluorouracil plus leucovorin in patients with cholangiocarcinoma and gallbladder carcinoma previously treated with gemcitabine-based therapies (AIO NALIRICC): a multicentre, open-label, randomised, phase 2 trial", tldr: "Published report from the NALIRICC trial registered as NCT03043547, in The lancet. Gastroenterology & hepatology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: There is an unmet need for effective therapies in pretreated advanced biliary tract cancer. We aimed to evaluate the efficacy of nanoliposomal irinotecan and fluorouracil plus leucovorin compared with fluorouracil plus leucovorin as second-line treatment for biliary tract cancer.\n\nMethods: NALIRICC was a multicentre, open-label, randomised, phase 2 trial done in 17 German centres for patients aged 18 years or older, with an Eastern Cooperative Oncology Group performance status of 0-1, metastatic biliary tract cancer, and progression on gemcitabine-based therapy. Patients were randomly assigned (1:1) to receive intravenous infusions of nanoliposomal irinotecan (70 mg/m 2), fluorouracil (2400 mg/m 2), and leucovorin (400 mg/m 2) every 2 weeks (nanoliposomal irinotecan group) or fluorouracil (2400 mg/m 2) plus leucovorin (400 mg/m 2) every 2 weeks (control group). Randomisation was by permutated block randomisation in block sizes of four, stratified by primary tumour site. Investigator-assessed progression-free survival was the primary endpoint, which was evaluated in all randomly assigned patients. Secondary efficacy outcomes were overall survival, objective response rate, and quality of life. Safety was assessed in all randomly assigned patients who received at least one dose of the study treatment. Enrolment for this trial has been completed, and it is registered with ClinicalTrials.gov, NCT03043547.\n\nFinding: Between Dec 4, 2017, and Aug 2, 2021, 49 patients were randomly assigned to the nanoliposomal irinotecan group and 51 patients to the control group. Median age was 65 years (IQR 59-71); 45 (45%) of 100 patients were female. Median progression-free survival was 2·6 months (95% CI 1·7-3·6) in the nanoliposomal irinotecan group and 2·3 months (1·6-3·4) in the control group (hazard ratio [HR] 0·87 [0·56-1·35]). Median overall survival was 6·9 months (95% CI 5·3-10·6) in the nanoliposomal irinotecan group and 8·2 months (5·4-11·9) in the control group (HR 1·08 [0·68-1·72]). The objective response rate was 14% (95% CI 6-27; seven patients) in the nanoliposomal irinotecan group and 4% (1-14; two patients) in the control group. The most common grade 3 or worse adverse events in the nanoliposomal irinotecan group were neutropenia (eight [17%] of 48 vs none in the control group), diarrhoea (seven [15%] vs one [2%]), and nausea (four [8%] vs none). In the control group, the most common grade 3 or worse adverse events were cholangitis (four [8%] patients vs none in the nanoliposomal irinotecan group) and bile duct stenosis (four [8%] vs three [6%]). Treatment-related serious adverse events occurred in 16 (33%) patients in the nanoliposomal irinotecan group (grade 2-3 diarrhoea in five patients; one case each of abdominal infection, acute kidney injury, pancytopenia, increased blood bilirubin, colitis, dehydration, dyspnoea, infectious enterocolitis, ileus, oral mucositis, and nausea). One (2%) treatment-related serious adverse event occurred in the control group (worsening of general condition). Median duration until deterioration of global health status, characterised by the time from randomisation to the initial observation of a score decline exceeding 10 points, was 4·0 months (95% CI 2·2-not reached) in the nanoliposomal irinotecan group and 3·7 months (2·7-not reached) in the control group.\n\nInterpretation: The addition of nanoliposomal irinotecan to fluorouracil plus leucovorin did not improve progression-free survival or overall survival and was associated with higher toxicity compared with fluorouracil plus leucovorin. Further research is necessary to define the role of irinotecan-based combinations in second-line treatment of biliary tract cancer.\n\nFunding: Servier and AIO-Studien.\n\nIndexed on Europe PMC as PubMed record 38870977 (DOI 10.1016/s2468-1253(24)00119-5). Its abstract cites the registry id NCT03043547, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The lancet. Gastroenterology & hepatology", year: 2024, doi: "10.1016/s2468-1253(24)00119-5", pmid: "38870977", authors: "Vogel A, Saborowski A, Wenzel P, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03043547 with the most citations, so it is the natural first reading for anyone following the NALIRICC trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Gastroenterol Hepatol 2024","url":"https://doi.org/10.1016/s2468-1253(24)00119-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38870977/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38870977"},{"label":"ClinicalTrials.gov NCT03043547","url":"https://clinicaltrials.gov/study/NCT03043547"}], tags: ["europepmc-ingest"], trials: ["naliricc"] }),
  p({ id: "paper-roar-lancet-oncol-2020", name: "Dabrafenib plus trametinib in patients with BRAF V600E -mutated biliary tract cancer (ROAR): a phase 2, open-label, single-arm, multicentre basket trial", tldr: "Published report from the ROAR trial registered as NCT02034110, in The Lancet Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Effective treatments for patients with cholangiocarcinoma after progression on gemcitabine-based chemotherapy are urgently needed. Mutations in the BRAF gene have been found in 5% of biliary tract tumours. The combination of dabrafenib and trametinib has shown activity in several BRAF V600E -mutated cancers. We aimed to assess the activity and safety of dabrafenib and trametinib combination therapy in patients with BRAF V600E -mutated biliary tract cancer.\n\nMethods: This study is part of an ongoing, phase 2, open-label, single-arm, multicentre, Rare Oncology Agnostic Research (ROAR) basket trial in patients with BRAF V600E -mutated rare cancers. Patients were eligible for the biliary tract cancer cohort if they were aged 18 years or older, had BRAF V600E -mutated, unresectable, metastatic, locally advanced, or recurrent biliary tract cancer, an Eastern Cooperative Oncology Group performance status of 0-2, and had received previous systemic treatment. All patients were treated with oral dabrafenib 150 mg twice daily and oral trametinib 2 mg once daily until disease progression or intolerance of treatment. The primary endpoint was the overall response rate, which was determined by Response Evaluation Criteria in Solid Tumors version 1.1 in the intention-to-treat evaluable population, which comprised all enrolled patients regardless of receiving treatment who were evaluable (ie, had progression, began a new anticancer treatment, withdrew consent, died, had stable disease for 6 weeks or longer, or had two or more post-baseline assessments). The ROAR trial is registered with ClinicalTrials.gov, NCT02034110. These results are based on an interim analysis; the study is active but not recruiting.\n\nFindings: Between March 12, 2014, and July 18, 2018, 43 patients with BRAF V600E -mutated biliary tract cancer were enrolled to the study and were evaluable. Median follow-up was 10 months (IQR 6-15). An investigator-assessed overall response was achieved by 22 (51%, 95% CI 36-67) of 43 patients. An independent reviewer-assessed overall response was achieved by 20 (47%, 95% CI 31-62) of 43 patients. The most common grade 3 or worse adverse event was increased γ-glutamyltransferase in five (12%) patients. 17 (40%) patients had serious adverse events and nine (21%) had treatment-related serious adverse events, the most frequent of which was pyrexia (eight [19%]). No treatment-related deaths were reported.\n\nInterpretation: Dabrafenib plus trametinib combination treatment showed promising activity in patients with BRAF V600E -mutated biliary tract cancer, with a manageable safety profile. Routine testing for BRAF V600E mutations should be considered in patients with biliary tract cancer.\n\nFunding: GlaxoSmithKline and Novartis.\n\nIndexed on Europe PMC as PubMed record 32818466 (DOI 10.1016/s1470-2045(20)30321-1). Its abstract cites the registry id NCT02034110, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2020, doi: "10.1016/s1470-2045(20)30321-1", pmid: "32818466", authors: "Subbiah V, Lassen U, Élez E, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02034110 with the most citations, so it is the natural first reading for anyone following the ROAR trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2020","url":"https://doi.org/10.1016/s1470-2045(20)30321-1"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32818466/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32818466"},{"label":"ClinicalTrials.gov NCT02034110","url":"https://clinicaltrials.gov/study/NCT02034110"}], tags: ["europepmc-ingest"], trials: ["roar"], journals: ["lancet-oncology"] }),
  p({ id: "paper-roar-ann-oncol-2022-update", name: "Dabrafenib plus trametinib in patients with BRAF V600E-mutant anaplastic thyroid cancer: updated analysis from the phase II ROAR basket study", tldr: "Later report from the ROAR trial registered as NCT02034110, in Annals of Oncology (2022); its title describes an updated or longer-term analysis.", summary: "Background: Combined therapy with dabrafenib plus trametinib was approved in several countries for treatment of BRAF V600E-mutant anaplastic thyroid cancer (ATC) based on an earlier interim analysis of 23 response-assessable patients in the ATC cohort of the phase II Rare Oncology Agnostic Research (ROAR) basket study. We report an updated analysis describing the efficacy and safety of dabrafenib plus trametinib in the full ROAR ATC cohort of 36 patients with ∼4 years of additional study follow-up.\n\nPatients and methods: ROAR (NCT02034110) is an open-label, nonrandomized, phase II basket study evaluating dabrafenib plus trametinib in BRAF V600E-mutant rare cancers. The ATC cohort comprised 36 patients with unresectable or metastatic ATC who received dabrafenib 150 mg twice daily plus trametinib 2 mg once daily orally until disease progression, unacceptable toxicity, or death. The primary endpoint was investigator-assessed overall response rate (ORR) per Response Evaluation Criteria in Solid Tumors version 1.1. Secondary endpoints were duration of response (DOR), progression-free survival (PFS), overall survival (OS), and safety.\n\nResults: At data cutoff (14 September 2020), median follow-up was 11.1 months (range, 0.9-76.6 months). The investigator-assessed ORR was 56% (95% confidence interval, 38.1% to 72.1%), including three complete responses; the 12-month DOR rate was 50%. Median PFS and OS were 6.7 and 14.5 months, respectively. The respective 12-month PFS and OS rates were 43.2% and 51.7%, and the 24-month OS rate was 31.5%. No new safety signals were identified with additional follow-up, and adverse events were consistent with the established tolerability of dabrafenib plus trametinib.\n\nConclusions: These updated results confirm the substantial clinical benefit and manageable toxicity of dabrafenib plus trametinib in BRAF V600E-mutant ATC. Dabrafenib plus trametinib notably improved long-term survival and represents a meaningful treatment option for this rare, aggressive cancer.\n\nIndexed on Europe PMC as PubMed record 35026411 (DOI 10.1016/j.annonc.2021.12.014). Its abstract cites the registry id NCT02034110, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2022, doi: "10.1016/j.annonc.2021.12.014", pmid: "35026411", authors: "Subbiah V, Kreitman RJ, Wainberg ZA, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the ROAR trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2022","url":"https://doi.org/10.1016/j.annonc.2021.12.014"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35026411/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35026411"},{"label":"ClinicalTrials.gov NCT02034110","url":"https://clinicaltrials.gov/study/NCT02034110"}], tags: ["europepmc-ingest"], trials: ["roar"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-topaz-1-lancet-gastroenterol-hepatol-2024-update", name: "Durvalumab or placebo plus gemcitabine and cisplatin in participants with advanced biliary tract cancer (TOPAZ-1): updated overall survival from a randomised phase 3 study", tldr: "Later report from the TOPAZ-1 trial registered as NCT03875235, in The lancet. Gastroenterology & hepatology (2024); its title describes an updated or longer-term analysis.", summary: "Background: In the preplanned interim analysis of the TOPAZ-1 study, durvalumab plus gemcitabine-cisplatin significantly improved overall survival versus placebo plus gemcitabine-cisplatin in participants with advanced biliary tract cancer. We aimed to report updated overall survival and safety data from TOPAZ-1 with additional follow-up and data maturity beyond the interim analysis.\n\nMethods: TOPAZ-1 was a phase 3, randomised, double-masked, placebo-controlled, global study done at 105 sites in 17 countries. Participants aged 18 years or older with unresectable, locally advanced, or metastatic biliary tract cancer were randomly assigned (1:1) to durvalumab plus gemcitabine-cisplatin or placebo plus gemcitabine-cisplatin using a computer-generated randomisation scheme, stratified by disease status and primary tumour location. Participants received durvalumab (1500 mg) or placebo on day 1 of each cycle every 3 weeks for up to eight cycles, plus gemcitabine (1000 mg/m 2) and cisplatin (25 mg/m 2) intravenously on days 1 and 8 of each cycle every 3 weeks for up to eight cycles, followed by durvalumab (1500 mg) or placebo monotherapy every 4 weeks until disease progression or other discontinuation criteria were met. Investigators and participants were masked to study treatment. The primary endpoint was overall survival. TOPAZ-1 met its primary endpoint at the preplanned interim analysis, and the study is active but no longer recruiting participants. Updated overall survival and safety data from TOPAZ-1, with additional follow-up (data cutoff Feb 25, 2022) and data maturity beyond the interim analysis, are reported here. Efficacy was assessed in the full analysis set (all randomly assigned participants). Safety was assessed in the safety analysis set (all participants who received at least one dose of study treatment). The TOPAZ-1 study is registered with ClinicalTrials.gov, NCT03875235.\n\nFindings: From April 16, 2019, to Dec 11, 2020, 914 participants were enrolled, 685 of whom were randomly assigned (341 to the durvalumab plus gemcitabine-cisplatin group and 344 to the placebo plus gemcitabine-cisplatin group). 345 (50%) participants were male and 340 (50%) were female. Median follow-up at the updated data cutoff was 23·4 months (95% CI 20·6-25·2) in the durvalumab plus gemcitabine-cisplatin group and 22·4 months (21·4-23·8) in the placebo plus gemcitabine-cisplatin group. At the updated data cutoff, 248 (73%) participants in the durvalumab plus gemcitabine-cisplatin group and 279 (81%) participants in the placebo plus gemcitabine-cisplatin group had died (median overall survival 12·9 months [95% CI 11·6-14·1] vs 11·3 months [10·1-12·5]; hazard ratio 0·76 [95% CI 0·64-0·91]). Kaplan-Meier-estimated 24-month overall survival rates were 23·6% (95% CI 18·7-28·9) in the durvalumab plus gemcitabine-cisplatin group and 11·5% (7·6-16·2) in the placebo plus gemcitabine-cisplatin group. Maximum grade 3 or 4 adverse events occurred in 250 (74%) of 338 participants in the durvalumab plus gemcitabine-cisplatin group and 257 (75%) of 342 in the placebo plus gemcitabine-cisplatin group. The most common maximum grade 3 or 4 treatment-related adverse events were decreased neutrophil count (70 [21%] vs 86 [25%]), anaemia (64 [19%] vs 64 [19%]), and neutropenia (63 [19%] vs 68 [20%]).\n\nInterpretation: Durvalumab plus gemcitabine-cisplatin showed robust and sustained overall survival benefit with no new safety signals. Findings continue to support the regimen as a standard of care for people with untreated, advanced biliary tract cancer.\n\nFunding: AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 38823398 (DOI 10.1016/s2468-1253(24)00095-5). Its abstract cites the registry id NCT03875235, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The lancet. Gastroenterology & hepatology", year: 2024, doi: "10.1016/s2468-1253(24)00095-5", pmid: "38823398", authors: "Oh DY, He AR, Bouattour M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the TOPAZ-1 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Gastroenterol Hepatol 2024","url":"https://doi.org/10.1016/s2468-1253(24)00095-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38823398/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38823398"},{"label":"ClinicalTrials.gov NCT03875235","url":"https://clinicaltrials.gov/study/NCT03875235"}], tags: ["europepmc-ingest"], trials: ["topaz-1"] }),
  p({ id: "paper-gap-phase2-mdacc-jama-oncol-2019", name: "Gemcitabine, Cisplatin, and nab-Paclitaxel for the Treatment of Advanced Biliary Tract Cancers: A Phase 2 Clinical Trial", tldr: "Published report from the cisplatin and nab-paclitaxel phase 2 trial registered as NCT02392637, in JAMA Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Administration of gemcitabine-cisplatin, the current standard therapy for advanced biliary tract cancers, results in median progression-free survival and overall survival of 8.0 and 11.7 months, respectively. New treatments offering improved survival outcomes are therefore needed.\n\nObjective: To evaluate the association between progression-free survival and the addition of nanoparticle albumin-bound (nab)-paclitaxel to gemcitabine-cisplatin for the treatment of patients with advanced biliary tract cancer.\n\nDesign, setting, and participants: This open-label, single-arm, phase 2 clinical trial conducted at the University of Texas MD Anderson Cancer Center and the Mayo Clinic in Phoenix, Arizona, enrolled 62 patients with advanced biliary tract cancers between April 14, 2015, and April 24, 2017.\n\nInterventions: Patients initially received gemcitabine, 1000 mg/m2, cisplatin, 25 mg/m2, and nab-paclitaxel, 125 mg/m2, on days 1 and 8 of 21-day cycles. Owing to hematologic adverse events among the first 32 patients enrolled, these starting doses were reduced to 800, 25, and 100 mg/m2, respectively, for the remaining 28 patients.\n\nMain outcomes and measures: The primary trial end point was investigator-assessed progression-free survival in the intention-to-treat population.\n\nResults: Of 60 patients who started treatment, the mean (SD) age was 58.4 (11.0) years, 38 (63%) had intrahepatic cholangiocarcinoma, 9 (15%) had extrahepatic cholangiocarcinoma, 13 (22%) had gallbladder cancer, 47 (78%) had metastatic disease, and 13 (22%) had locally advanced disease. Median follow-up was 12.2 (95% CI, 9.4-19.4) months, and median progression-free survival was 11.8 (95% CI, 6.0 to 15.6) months. The partial response rate was 45%, and the disease control rate was 84%. Median overall survival was 19.2 months (95% CI, 13.2 months to not estimable). Patients in the safety population (n = 57) received a median of 6 (interquartile range, 3-11) cycles of treatment; 26 patients (46%) remained on their starting dose throughout the trial. Grade 3 or higher adverse events occurred in 58% of patients, and 9 patients (16%) withdrew owing to adverse events. Neutropenia was the most common grade 3 or higher adverse event, occurring in 19 patients (33%) overall. Post hoc analyses showed that treatment efficacy was not significantly associated with starting dose, tumor type, or disease status and that tolerability was improved with reduced- vs high-dose treatment.\n\nConclusions and relevance: Treatment with nab-paclitaxel plus gemcitabine-cisplatin prolonged median progression-free survival and overall survival vs those reported for historical controls treated with gemcitabine-cisplatin alone. These findings will be tested in a phase 3 randomized clinical trial.\n\nTrial registration: ClinicalTrials.gov identifier: NCT02392637.\n\nIndexed on Europe PMC as PubMed record 30998813 (DOI 10.1001/jamaoncol.2019.0270). Its abstract cites the registry id NCT02392637, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2019, doi: "10.1001/jamaoncol.2019.0270", pmid: "30998813", authors: "Shroff RT, Javle MM, Xiao L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02392637 with the most citations, so it is the natural first reading for anyone following the cisplatin and nab-paclitaxel phase 2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2019","url":"https://doi.org/10.1001/jamaoncol.2019.0270"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30998813/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30998813"},{"label":"ClinicalTrials.gov NCT02392637","url":"https://clinicaltrials.gov/study/NCT02392637"}], tags: ["europepmc-ingest"], trials: ["gap-phase2-mdacc"], journals: ["jama-oncology"] }),
  p({ id: "paper-keynote-158-j-clin-oncol-2019", name: "Efficacy and Safety of Pembrolizumab in Previously Treated Advanced Cervical Cancer: Results From the Phase II KEYNOTE-158 Study", tldr: "Published report from the KEYNOTE-158 trial registered as NCT02628067, in Journal of Clinical Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: KEYNOTE-158 ( ClinicalTrials.gov identifier: NCT02628067) is a phase II basket study investigating the antitumor activity and safety of pembrolizumab in multiple cancer types. We present interim results from patients with previously treated advanced cervical cancer.\n\nPatients and methods: Patients received pembrolizumab 200 mg every 3 weeks for 2 years or until progression, intolerable toxicity, or physician or patient decision. Tumor imaging was performed every 9 weeks for the first 12 months and every 12 weeks thereafter. The primary end point was objective response rate (ORR), assessed per Response Evaluation Criteria in Solid Tumors (version 1.1) by independent central radiologic review. Safety was a secondary end point.\n\nResults: Ninety-eight patients were treated. Median age was 46.0 years (range, 24 to 75 years), and 65.3% of patients had Eastern Cooperative Oncology Group performance status of 1. Eighty-two patients (83.7%) had programmed death-ligand 1 (PD-L1)-positive tumors (combined positive score ≥ 1), 77 having previously received one or more lines of chemotherapy for recurrent or metastatic disease. Median follow-up was 10.2 months (range, 0.6 to 22.7 months). ORR was 12.2% (95% CI, 6.5% to 20.4%), with three complete and nine partial responses. All 12 responses were in patients with PD-L1-positive tumors, for an ORR of 14.6% (95% CI, 7.8% to 24.2%); 14.3% (95% CI, 7.4% to 24.1%) of these responses were in those who had received one or more lines of chemotherapy for recurrent or metastatic disease. Median duration of response was not reached (range, ≥ 3.7 to ≥ 18.6 months). Treatment-related adverse events occurred in 65.3% of patients, and the most common were hypothyroidism (10.2%), decreased appetite (9.2%), and fatigue (9.2%). Treatment-related grade 3 to 4 adverse events occurred in 12.2% of patients.\n\nConclusion: Pembrolizumab monotherapy demonstrated durable antitumor activity and manageable safety in patients with advanced cervical cancer. On the basis of these results, the US Food and Drug Administration granted accelerated approval of pembrolizumab for patients with advanced PD-L1-positive cervical cancer who experienced progression during or after chemotherapy.\n\nIndexed on Europe PMC as PubMed record 30943124 (DOI 10.1200/jco.18.01265). Its abstract cites the registry id NCT02628067, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2019, doi: "10.1200/jco.18.01265", pmid: "30943124", authors: "Chung HC, Ros W, Delord JP, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02628067 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-158 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2019","url":"https://doi.org/10.1200/jco.18.01265"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30943124/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30943124"},{"label":"ClinicalTrials.gov NCT02628067","url":"https://clinicaltrials.gov/study/NCT02628067"}], tags: ["europepmc-ingest"], trials: ["keynote-158"], journals: ["jco"] }),
  p({ id: "paper-keynote-158-ann-oncol-2022-update", name: "Pembrolizumab in microsatellite instability high or mismatch repair deficient cancers: updated analysis from the phase II KEYNOTE-158 study", tldr: "Later report from the KEYNOTE-158 trial registered as NCT02628067, in Annals of Oncology (2022); its title describes an updated or longer-term analysis.", summary: "Background: Pembrolizumab demonstrated durable antitumor activity in 233 patients with previously treated advanced microsatellite instability high (MSI-H) or mismatch repair deficient (dMMR) advanced solid tumors in the phase II multicohort KEYNOTE-158 (NCT02628067) study. Herein, we report safety and efficacy outcomes with longer follow-up for more patients with previously treated advanced MSI-H/dMMR noncolorectal cancers who were included in cohort K of the KEYNOTE-158 (NCT02628067) study.\n\nPatients and methods: Eligible patients with previously treated advanced noncolorectal MSI-H/dMMR solid tumors, measurable disease as per RECIST v1.1, and Eastern Cooperative Oncology Group performance status of 0 or 1 received pembrolizumab 200 mg Q3W for 35 cycles or until disease progression or unacceptable toxicity. The primary endpoint was objective response rate (ORR) as per RECIST v1.1 by independent central radiologic review.\n\nResults: Three hundred and fifty-one patients with various tumor types were enrolled in KEYNOTE-158 cohort K. The most common tumor types were endometrial (22.5%), gastric (14.5%), and small intestine (7.4%). Median time from first dose to database cut-off (5 October 2020) was 37.5 months (range, 0.2-55.6 months). ORR among 321 patients in the efficacy population (patients who received ≥1 dose of pembrolizumab enrolled ≥6 months before the data cut-off date) was 30.8% [95% confidence interval (CI) 25.8% to 36.2%]. Median duration of response was 47.5 months (range, 2.1+ to 51.1+ months; '+' indicates no progressive disease by the time of last disease assessment). Median progression-free survival was 3.5 months (95% CI 2.3-4.2 months) and median overall survival was 20.1 months (95% CI 14.1-27.1 months). Treatment-related adverse events (AEs) occurred in 227 patients (64.7%). Grade 3-4 treatment-related AEs occurred in 39 patients (11.1%); 3 (0.9%) had grade 5 treatment-related AEs (myocarditis, pneumonia, and Guillain-Barre syndrome, n = 1 each).\n\nConclusions: Pembrolizumab demonstrated clinically meaningful and durable benefit, with a high ORR of 30.8%, long median duration of response of 47.5 months, and manageable safety across a range of heavily pretreated, advanced MSI-H/dMMR noncolorectal cancers, providing support for use of pembrolizumab in this setting.\n\nIndexed on Europe PMC as PubMed record 35680043 (DOI 10.1016/j.annonc.2022.05.519). Its abstract cites the registry id NCT02628067, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2022, doi: "10.1016/j.annonc.2022.05.519", pmid: "35680043", authors: "Maio M, Ascierto PA, Manzyuk L, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the KEYNOTE-158 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2022","url":"https://doi.org/10.1016/j.annonc.2022.05.519"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35680043/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35680043"},{"label":"ClinicalTrials.gov NCT02628067","url":"https://clinicaltrials.gov/study/NCT02628067"}], tags: ["europepmc-ingest"], trials: ["keynote-158"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct04969887-jama-oncol-2025", name: "Nivolumab and Ipilimumab Combination Treatment in Advanced Ovarian and Endometrial Clear Cell Cancers: A Nonrandomized Clinical Trial", tldr: "Published report from the MOST-CIRCUIT trial registered as NCT04969887, in JAMA Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Gynecological clear cell cancers (CCCs) are aggressive malignant neoplasms with low response rate to chemotherapy. The treatment of patients with metastatic disease remains an area of significant unmet need.\n\nObjective: To evaluate the efficacy of combined anti-programmed cell death 1 protein (PD-1)/cytotoxic T-lymphocyte-associated protein 4 (CTLA-4) blockade using nivolumab and ipilimumab in advanced gynecological CCCs.\n\nDesign, setting, and participants: The MoST-CIRCUIT prospective multicenter phase 2 nonrandomized clinical trial included patients with advanced selected rare cancers. Patients with advanced clear cell ovarian cancer (CCOC)/clear cell endometrial cancer (CCEC) with a maximum of 1 course of prior systemic therapy were enrolled from August 2021 to February 2024 across 17 Australian and New Zealand sites.\n\nInterventions: Patients received nivolumab, 3 mg/kg, and ipilimumab, 1 mg/kg, every 3 weeks for 4 doses followed by nivolumab, 480 mg, every 4 weeks for 96 weeks until disease progression or the development of unacceptable toxic effects.\n\nMain outcomes and measures: Coprimary end points were objective response rate (ORR) and 6-month progression-free survival (PFS) as assessed by RECIST version 1.1 criteria, with the secondary end points being median overall survival, PFS, and treatment-related toxic effects.\n\nResults: Of 28 included patients, the median (range) age was 55 (34-77) years. A total of 24 had CCOC and 4 had CCEC; 19 (68%) had a previous course of therapy. Overall ORR was 54% (95% CI, 35-71), with 3 (12%) with complete response and 12 (42%) with partial response; the ORR was 55% (95% CI, 35-73) in the CCOC group and 50% (95% CI, 9-91) in the CCEC group. The median duration of response has not been reached, with all responses ongoing. The 6-month PFS was 58% (95% CI, 39-74), and the median overall survival has not been reached. A total of 9 patients (35%) experienced a grade 3 or 4 immune-related adverse event, and a grade 5 myocarditis occurred in 1 patient.\n\nConclusions and relevance: In this nonrandomized clinical trial, immunotherapy using combined anti-PD-1/CTLA-4 blockade demonstrated encouraging activity with a high rate of durable responses in patients with advanced gynecological CCCs. This regimen should be further investigated in this patient population with unmet medical need.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT04969887.\n\nIndexed on Europe PMC as PubMed record 40608313 (DOI 10.1001/jamaoncol.2025.1916). Its abstract cites the registry id NCT04969887, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2025, doi: "10.1001/jamaoncol.2025.1916", pmid: "40608313", authors: "Gao B, Carlino MS, Michael M, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04969887 with the most citations, so it is the natural first reading for anyone following the MOST-CIRCUIT trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2025","url":"https://doi.org/10.1001/jamaoncol.2025.1916"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40608313/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40608313"},{"label":"ClinicalTrials.gov NCT04969887","url":"https://clinicaltrials.gov/study/NCT04969887"}], tags: ["europepmc-ingest"], trials: ["nct04969887"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct05724563-nat-commun-2025", name: "Dual TIGIT and PD-1 blockade with domvanalimab plus zimberelimab in hepatocellular carcinoma refractory to anti-PD-1 therapies: the phase 2 LIVERTI trial", tldr: "Published report from the trial registered as NCT05724563, in Nature Communications (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "T cell immunoglobulin and ITIM domain (TIGIT) is an inhibitory receptor expressed on lymphocytes and NK cells, and is a candidate compensatory immune checkpoint that may mediate anti-PD-1/L1 resistance in hepatocellular carcinoma (HCC). We conducted the phase 2 LIVERTI trial testing domvanalimab, a monoclonal Fc-silent anti-TIGIT antibody, plus zimberelimab, an anti-PD-1 antibody, in immunotherapy refractory HCC. Here, we report an analysis of the primary endpoint, the confirmed overall response rate (ORR). Secondary endpoints included rates of adverse events, progression-free survival (PFS), 6-month PFS survival, overall survival, and duration of response, of which the latter two endpoints were excluded from this analysis due to the immaturity of long-term survival data. Among the 29 patients enrolled, the confirmed ORR was 17.2% (95% CI 5.8%-35.8%) and the median PFS was 4.4 months (95% CI, 4.1-4.6 months). Treatment-related adverse events occurred in 16 patients (55.2%). Analysis of circulating tumor DNA (ctDNA) demonstrated that ctDNA dynamics may serve as pharmacodynamic markers of response to domvanalimab plus zimberelimab. Despite the primary endpoint failing to meet the protocol-specified threshold, these results indicate that targeting TIGIT in anti-PD-1/L1 therapy refractory HCC is well-tolerated, associated with anti-tumor effects, and may be guided by ctDNA assessment. ClinicalTrials.gov registration: NCT05724563.\n\nIndexed on Europe PMC as PubMed record 40592848 (DOI 10.1038/s41467-025-60757-7). Its abstract cites the registry id NCT05724563, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Communications", year: 2025, doi: "10.1038/s41467-025-60757-7", pmid: "40592848", authors: "Hsiehchen D, Kainthla R, Kline H, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05724563 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Commun 2025","url":"https://doi.org/10.1038/s41467-025-60757-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40592848/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40592848"},{"label":"ClinicalTrials.gov NCT05724563","url":"https://clinicaltrials.gov/study/NCT05724563"}], tags: ["europepmc-ingest"], trials: ["nct05724563"], journals: ["nature-communications"] }),
];
